let SHENSI_SESSION_TOKEN = document.querySelector('meta[name="shensi-session-token"]')?.content || "";
const nativeFetch = window.fetch.bind(window);
let sessionRefreshFlight = null;
const refreshShensiSessionToken = async () => {
  if (sessionRefreshFlight) return sessionRefreshFlight;
  sessionRefreshFlight = (async () => {
    const response = await nativeFetch(`/index.html?shensiSessionRefresh=${Date.now()}`, { cache: "no-store" });
    if (!response.ok) throw new Error("神思页面会话刷新失败");
    const html = await response.text();
    const next = html.match(/name=["']shensi-session-token["']\s+content=["']([^"']+)["']/u)?.[1] || "";
    if (!next) throw new Error("神思页面没有返回新的本地会话");
    SHENSI_SESSION_TOKEN = next;
    const meta = document.querySelector('meta[name="shensi-session-token"]');
    if (meta) meta.setAttribute("content", next);
    return next;
  })().finally(() => { sessionRefreshFlight = null; });
  return sessionRefreshFlight;
};
window.fetch = async (input, init = {}) => {
  const url = typeof input === "string" ? input : input?.url || "";
  const apiUrl = typeof url === "string" && (url.startsWith("/api/") || url.startsWith(`${window.location.origin}/api/`));
  if (!apiUrl) return nativeFetch(input, init);
  const headers = new Headers(init.headers || (typeof input === "object" ? input.headers : undefined));
  if (SHENSI_SESSION_TOKEN) headers.set("X-Shensi-Session", SHENSI_SESSION_TOKEN);
  const response = await nativeFetch(input, { ...init, headers });
  const localSessionExpired = shouldRefreshLocalSession({
    status: response.status,
    errorCode: response.headers.get("X-Shensi-Error-Code"),
    alreadyRetried: init.__shensiSessionRetry === true,
  });
  if (!localSessionExpired) return response;
  try {
    const refreshed = await refreshShensiSessionToken();
    const retryHeaders = new Headers(headers);
    retryHeaders.set("X-Shensi-Session", refreshed);
    return nativeFetch(input, { ...init, headers: retryHeaders, __shensiSessionRetry: true });
  } catch {
    return response;
  }
};
