const normalizeNoteColorValue = (command, value) => {
  const raw = String(value ?? "").trim().toLowerCase();
  if (command === "hiliteColor" && (!raw || raw === "none" || raw === "transparent")) return "";
  if (/^#[0-9a-f]{3,8}$/u.test(raw)) return raw;
  if (/^rgba?\(\s*[\d. %]+(?:\s*,\s*[\d. %]+){2,3}\s*\)$/u.test(raw)) return raw;
  return command === "foreColor" ? "#000000" : "";
};

