const applyTypographyPresentation = (preferences = globalUiPreferences) => {
  const normalized = normalizedUiPreferences(preferences);
  document.documentElement.style.setProperty("--document-max-width", `${normalized.editorMaxWidth}px`);
  document.documentElement.style.setProperty("--document-font-size", `${normalized.editorFontSize}px`);
  document.documentElement.style.setProperty("--document-line-height", normalized.editorLineHeight);
  document.documentElement.style.setProperty("--document-font-family", EDITOR_FONT_STACKS[normalized.editorFontFamily]);
};

