const beginSettingsUiLanguagePreview = () => {
  settingsUiLanguagePreviewBaseline = globalUiPreferences.uiLanguage;
};

const previewSettingsUiLanguage = (language) => {
  if (settingsUiLanguagePreviewBaseline === null) beginSettingsUiLanguagePreview();
  globalUiPreferences = normalizedUiPreferences({ ...globalUiPreferences, uiLanguage: language });
  refreshUiLanguagePresentation();
};

const restoreSettingsUiLanguagePreview = () => {
  if (settingsUiLanguagePreviewBaseline === null) return;
  if (globalUiPreferences.uiLanguage === settingsUiLanguagePreviewBaseline) {
    settingsUiLanguagePreviewBaseline = null;
    return;
  }
  globalUiPreferences = normalizedUiPreferences({
    ...globalUiPreferences,
    uiLanguage: settingsUiLanguagePreviewBaseline,
  });
  settingsUiLanguagePreviewBaseline = null;
  refreshUiLanguagePresentation();
};

const applyUiPreferences = ({ localize = true } = {}) => {
  globalUiPreferences = normalizedUiPreferences(globalUiPreferences);
  Object.assign(state.settings, globalUiPreferences);
  appTheme = globalUiPreferences.themePreference;
  state.theme = resolvedTheme(appTheme);
  applyThemePresentation(appTheme, globalUiPreferences.customTheme);
  applyTypographyPresentation(globalUiPreferences);
  if (localize) translateStaticUi();
};

const folderStateIdentity = (workspacePath = state.settings?.workspacePath, projectName = state.projectName) => String(workspacePath || projectName || "未命名").trim().toLowerCase();
const readFolderStateCache = () => {
  try {
    return JSON.parse(localStorage.getItem(FOLDER_STATE_KEY) || "{}");
  } catch {
    return {};
  }
};
const expandedFoldersForWorkspace = (workspacePath, fallback = [], projectName = "") => {
  const entry = readFolderStateCache()[folderStateIdentity(workspacePath, projectName)];
  return Array.isArray(entry) ? entry : Array.isArray(entry?.ids) ? entry.ids : fallback;
};
const persistExpandedFolderState = () => {
  try {
    const cache = readFolderStateCache();
    cache[folderStateIdentity()] = { ids: [...state.expandedFolders], updatedAt: Date.now() };
    const retained = Object.entries(cache)
      .sort(([, left], [, right]) => Number(right?.updatedAt ?? 0) - Number(left?.updatedAt ?? 0))
      .slice(0, 100);
    localStorage.setItem(FOLDER_STATE_KEY, JSON.stringify(Object.fromEntries(retained)));
  } catch {}
};

