// Renderer-side persistence, recovery and catalogue refreshes may need to
// stringify sizeable state. Never start that work in the short window between
// a real pointer/key interaction and the frame that acknowledges it. This does
// not debounce user content: editor and generation drafts still enter the
// local crash-recovery cache immediately; only background preparation/network
// work yields to the current input frame.
const UI_BACKGROUND_INTERACTION_GRACE_MS = 180;
let lastUiInteractionAt = 0;

const markUiInteraction = () => {
  lastUiInteractionAt = performance.now();
};

document.addEventListener("pointerdown", markUiInteraction, { capture: true, passive: true });
document.addEventListener("keydown", markUiInteraction, { capture: true });

const cancelUiBackgroundTask = (task) => {
  if (!task) return;
  task.cancelled = true;
  if (task.timer !== null) clearTimeout(task.timer);
  if (task.idle !== null) {
    if (typeof window.cancelIdleCallback === "function") window.cancelIdleCallback(task.idle);
    else clearTimeout(task.idle);
  }
};

const scheduleUiBackgroundTask = (callback, {
  delay = 0,
  timeout = 1_800,
  interactionGrace = UI_BACKGROUND_INTERACTION_GRACE_MS,
} = {}) => {
  const task = {
    cancelled: false,
    timer: null,
    idle: null,
    deadline: performance.now() + Math.max(0, delay) + Math.max(250, timeout),
  };
  const queue = () => {
    if (task.cancelled) return;
    task.timer = null;
    const now = performance.now();
    const interactionWait = Math.max(0, interactionGrace - (now - lastUiInteractionAt));
    if (interactionWait > 0 && now < task.deadline) {
      task.timer = setTimeout(queue, Math.min(interactionWait + 16, 250));
      return;
    }
    const run = () => {
      task.idle = null;
      if (task.cancelled) return;
      const runAt = performance.now();
      const recentInteractionWait = Math.max(0, interactionGrace - (runAt - lastUiInteractionAt));
      const inputPending = navigator.scheduling?.isInputPending?.({ includeContinuous: true }) === true;
      if ((recentInteractionWait > 0 || inputPending) && runAt < task.deadline) {
        task.timer = setTimeout(queue, Math.min(Math.max(recentInteractionWait, 24) + 16, 250));
        return;
      }
      task.cancelled = true;
      callback();
    };
    if (typeof window.requestIdleCallback === "function") {
      task.idle = window.requestIdleCallback(run, {
        timeout: Math.max(1, Math.min(1_000, task.deadline - now)),
      });
    } else {
      task.idle = setTimeout(run, 16);
    }
  };
  task.timer = setTimeout(queue, Math.max(0, delay));
  return task;
};

const escapeHtml = (value = "") => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;")
  .replaceAll("'", "&#039;");

const inlineStructuredMarkdownToHtml = (value) => escapeHtml(cleanObsidianInlineMarkdown(value))
  .replace(/\*\*\*([^*\n]+)\*\*\*/g, "<strong><em>$1</em></strong>")
  .replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>")
  .replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>");

const proseToHtml = (value) => String(value ?? "")
  .replace(/\r\n?/g, "\n")
  .split(/\n\s*\n/)
  .map((block) => block.trim())
  .filter(Boolean)
  .map((block) => {
    const heading = block.match(/^(#{1,6})\s+([^\n]+)$/u);
    if (heading) {
      const level = heading[1].length;
      return `<h${level}>${inlineStructuredMarkdownToHtml(heading[2])}</h${level}>`;
    }
    const cleanedBlock = cleanGeneratedPlainText(block);
    return markdownTableToHtml(cleanedBlock, { renderInline: inlineStructuredMarkdownToHtml })
      || proseParagraphs(cleanedBlock).map((paragraph) => `<p>${inlineStructuredMarkdownToHtml(paragraph)}</p>`).join("");
  })
  .join("");

const compactGeneratedLandingHtml = (html = "") => {
  const container = document.createElement("div");
  container.innerHTML = sanitizeDocumentHtml(html);
  for (const paragraph of [...container.querySelectorAll(":scope > p")]) {
    const hasMedia = Boolean(paragraph.querySelector("img, video, table"));
    const hasText = Boolean(String(paragraph.textContent || "").replace(/\u00a0/g, " ").trim());
    if (!hasMedia && !hasText) paragraph.remove();
  }
  return sanitizeDocumentHtml(container.innerHTML);
};

const importedDocumentTextToHtml = (value) => sanitizeDocumentHtml(String(value ?? "")
  .replace(/\r\n?/g, "\n")
  .split(/\n\s*\n/)
  .map((block) => block.trim())
  .filter(Boolean)
  .map((block) => {
    const table = markdownTableToHtml(block, { renderInline: inlineStructuredMarkdownToHtml });
    if (table) return table;
    if (/^(?:---+|___+|\*\*\*+)\s*$/.test(block)) return "";
    const heading = block.match(/^(#{1,6})\s+([\s\S]+)$/);
    if (heading) return `<h${heading[1].length}>${inlineStructuredMarkdownToHtml(heading[2])}</h${heading[1].length}>`;
    const lines = block.split("\n");
    const unordered = lines.map((line) => line.match(/^\s*(?:[-*+]|·)\s+(.+)$/));
    if (unordered.length && unordered.every(Boolean)) {
      return `<ul>${unordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ul>`;
    }
    const ordered = lines.map((line) => line.match(/^\s*\d+[.)、]\s+(.+)$/));
    if (ordered.length && ordered.every(Boolean)) {
      return `<ol>${ordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ol>`;
    }
    return `<p>${inlineStructuredMarkdownToHtml(block).replaceAll("\n", "<br>")}</p>`;
  })
  .join(""));

const INLINE_SOURCE_FOLDER_ID = "custom-folder:library-original-source";

const archiveInlineSourceMaterial = async ({ messageId = "", content = "" } = {}) => {
  if (state.workspaceKind !== "project" || workspaceHasNoActiveEntry()) return null;
  const candidate = inlineSourceArchiveCandidate({ value: content });
  if (!candidate) return null;
  const hash = await sha256Hex(candidate.exactText);
  const documentId = `library-source-${hash.slice(0, 24)}`;
  if (state.documents[documentId]) {
    return { documentId, hash, reason: candidate.reason, duplicate: true };
  }

  state.moduleItems.library ??= [];
  state.customFolders ??= [];
  const createdFolder = !state.customFolders.some((folder) => folder.id === INLINE_SOURCE_FOLDER_ID);
  if (createdFolder) {
    state.customFolders.push({
      id: INLINE_SOURCE_FOLDER_ID,
      label: "对话原始素材",
      moduleId: "library",
      viewId: "default",
      folderPath: "对话原始素材",
      parentLocationId: "library:default:root",
      parentOptions: {},
    });
  }
  const title = `原始素材 ${hash.slice(0, 8)}`;
  const options = {
    workspaceView: "novel",
    contextDomain: "reference",
    customFolderId: INLINE_SOURCE_FOLDER_ID,
    customFolderName: "对话原始素材",
    customFolderPath: "对话原始素材",
    placementOverride: true,
  };
  state.documents[documentId] = {
    title,
    html: importedDocumentTextToHtml(candidate.exactText),
    markdown: candidate.exactText,
    updatedAt: nowTime(),
    moduleId: "library",
    documentKind: "document",
    sourceAuthority: candidate.authority,
    sourceArchiveReason: candidate.reason,
    sourceArchiveHash: hash,
    sourceMessageId: String(messageId || ""),
    sourceArchivedAt: new Date().toISOString(),
    ...options,
  };
  state.moduleItems.library.push([documentId, title, options]);
  state.histories[documentId] ??= [];
  persist({ documentIds: [documentId] });
  try {
    await saveWorkspace({
      throwOnError: true,
      forceFullState: true,
      operationDocumentIds: [documentId],
    });
  } catch (error) {
    delete state.documents[documentId];
    delete state.histories[documentId];
    state.moduleItems.library = state.moduleItems.library.filter(([id]) => id !== documentId);
    if (createdFolder) state.customFolders = state.customFolders.filter((folder) => folder.id !== INLINE_SOURCE_FOLDER_ID);
    persist();
    throw error;
  }
  return { documentId, hash, reason: candidate.reason, duplicate: false };
};

const archiveInlineSourceMaterialInPinnedWorkspace = async ({ workspaceState, workspacePath = "", messageId = "", content = "" } = {}) => {
  const candidate = inlineSourceArchiveCandidate({ value: content });
  if (!candidate || !workspacePath || workspaceState?.workspaceKind !== "project") return null;
  const hash = await sha256Hex(candidate.exactText);
  const documentId = `library-source-${hash.slice(0, 24)}`;
  const workspaceKind = workspaceState?.workspaceKind === "notebook" ? "notebook" : "project";
  const result = await enqueueInactiveWorkspaceGenerationWrite({
    key: workspaceCacheKey(workspaceKind, workspacePath),
    loadLatest: () => fetchWorkspacePayload(workspacePath),
    merge: (loaded) => {
      const targetState = loaded?.state ? clone(loaded.state) : null;
      if (!targetState) throw new Error("原始素材所属工作区已经不存在");
      targetState.documents ??= {};
      if (targetState.documents?.[documentId]) return { workspaceState: targetState, result: { documentId, hash, reason: candidate.reason, duplicate: true } };
      withSynchronousWorkspaceState(targetState, () => {
        targetState.moduleItems.library ??= [];
        targetState.customFolders ??= [];
        if (!targetState.customFolders.some((folder) => folder.id === INLINE_SOURCE_FOLDER_ID)) {
          targetState.customFolders.push({
            id: INLINE_SOURCE_FOLDER_ID,
            label: "对话原始素材",
            moduleId: "library",
            viewId: "default",
            folderPath: "对话原始素材",
            parentLocationId: "library:default:root",
            parentOptions: {},
          });
        }
        const title = `原始素材 ${hash.slice(0, 8)}`;
        const options = {
          workspaceView: "novel",
          contextDomain: "reference",
          customFolderId: INLINE_SOURCE_FOLDER_ID,
          customFolderName: "对话原始素材",
          customFolderPath: "对话原始素材",
          placementOverride: true,
        };
        targetState.documents[documentId] = {
          title,
          html: importedDocumentTextToHtml(candidate.exactText),
          markdown: candidate.exactText,
          updatedAt: nowTime(),
          moduleId: "library",
          documentKind: "document",
          sourceAuthority: candidate.authority,
          sourceArchiveReason: candidate.reason,
          sourceArchiveHash: hash,
          sourceMessageId: String(messageId || ""),
          sourceArchivedAt: new Date().toISOString(),
          ...options,
        };
        targetState.moduleItems.library.push([documentId, title, options]);
        targetState.histories ??= {};
        targetState.histories[documentId] ??= [];
      });
      return { workspaceState: targetState, result: { documentId, hash, reason: candidate.reason, duplicate: false } };
    },
    save: async ({ workspaceState: targetState, result: archiveResult }, loaded) => {
      if (archiveResult.duplicate) return { workspaceState: targetState, result: archiveResult };
      const request = await workspaceSaveRequest({
        workspacePath,
        expectedStateStamp: loaded?.stateStamp || "",
        state: backgroundWorkspaceStateForSave(targetState),
        operationDocumentIds: [documentId],
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw workspaceSaveError(response, payload);
      if (payload.savedAt) targetState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind,
        workspacePath,
        workspaceState: targetState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        prepared: true,
      });
      return { workspaceState: targetState, result: archiveResult };
    },
  });
  return result.result;
};

const upgradeLegacyStructuredMarkdownInHtml = (html) => {
  const container = document.createElement("div");
  container.innerHTML = sanitizeDocumentHtml(html);
  let changed = false;
  for (const paragraph of Array.from(container.querySelectorAll("p"))) {
    const source = Array.from(paragraph.childNodes).map((node) => node.nodeName === "BR" ? "\n" : node.textContent ?? "").join("").trim();
    const legacyPlanningHeading = source.match(/^第(?:\d+|[零〇一二两三四五六七八九十百千]+)章(?:事件包|模拟事件包|章纲|剧情包)$/u);
    const tableHtml = markdownTableToHtml(source, { renderInline: inlineStructuredMarkdownToHtml });
    const lines = source.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
    const unordered = lines.map((line) => line.match(/^(?:[-*+]|·)\s+(.+)$/));
    const ordered = lines.map((line) => line.match(/^\d+[.)、]\s+(.+)$/));
    const listHtml = unordered.length && unordered.every(Boolean)
      ? `<ul>${unordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ul>`
      : ordered.length && ordered.every(Boolean)
        ? `<ol>${ordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ol>`
        : "";
    const containsLegacyInlineSyntax = /\[\[[^\]]+\]\]|`[^`\n]+`/.test(source);
    const replacementHtml = legacyPlanningHeading
      ? `<h2>${inlineStructuredMarkdownToHtml(source)}</h2>`
      : tableHtml || listHtml || (containsLegacyInlineSyntax
      ? `<p>${inlineStructuredMarkdownToHtml(source).replaceAll("\n", "<br>")}</p>`
      : "");
    if (!replacementHtml) continue;
    const replacement = document.createElement("div");
    replacement.innerHTML = replacementHtml;
    paragraph.replaceWith(...replacement.childNodes);
    changed = true;
  }
  for (const element of Array.from(container.querySelectorAll("li, h1, h2, h3, h4, h5, h6, td, th"))) {
    const source = element.textContent?.trim() ?? "";
    if (!/\[\[[^\]]+\]\]|`[^`\n]+`/.test(source)) continue;
    element.innerHTML = inlineStructuredMarkdownToHtml(source);
    changed = true;
  }
  return { html: changed ? sanitizeDocumentHtml(container.innerHTML) : sanitizeDocumentHtml(html), changed };
};

const stripHtml = (html = "") => {
  const element = document.createElement("div");
  element.innerHTML = sanitizeDocumentHtml(html);
  return element.textContent?.replace(/\s+/g, "").trim() ?? "";
};

const visibleCharacterCount = (text = "") => String(text || "").replace(/\s+/g, "").length;

const updateEditorWordCount = (selectedText = "") => {
  const documentState = state.documents?.[state.activeDocument];
  if (!documentState || documentState.documentKind === "whiteboard" || state.activeDocument === "library-trash") return;
  const total = stripHtml(documentState.html).length;
  const selected = visibleCharacterCount(selectedText);
  const suffix = documentState.externalMarkdown ? " · 外部文件 · 只读预览" : "";
  elements.wordCount.textContent = selected > 0
    ? `已选 ${selected.toLocaleString("zh-CN")} 字 / 全文 ${total.toLocaleString("zh-CN")} 字${suffix}`
    : `${total.toLocaleString("zh-CN")} 字${suffix}`;
};

const contextPlainTextFromHtml = (html = "") => {
  const element = document.createElement("div");
  element.innerHTML = sanitizeDocumentHtml(html);
  for (const lineBreak of element.querySelectorAll("br")) lineBreak.replaceWith("\n");
  for (const block of element.querySelectorAll("p, div, li, h1, h2, h3, h4, h5, h6, blockquote, tr")) block.append("\n");
  return String(element.textContent ?? "")
    .replace(/\u00a0/g, " ")
    .replace(/\r\n?/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
};

const replaceImportedHtmlBaseline = (documentState, nextHtml) => {
  const importedHtmlUnchanged = documentState.importedHtmlRevision
    && documentState.importedHtmlRevision === contentRevision(documentState.html);
  const sanitized = sanitizeDocumentHtml(nextHtml);
  documentState.html = sanitized;
  if (importedHtmlUnchanged) documentState.importedHtmlRevision = contentRevision(sanitized);
};

const pruneStateTrash = (now = Date.now()) => {
  const result = pruneTrashEntries(state.trash ?? [], now);
  if (result.expired.length) purgeTrashPayloadsFromState(state, result.expired);
  state.trash = result.active;
  return result.expired.length;
};

