const removeDirectoryOrderEntries = ({ documentIds = [], folderIds = [] } = {}) => {
  const removedTokens = new Set([
    ...documentIds.filter(Boolean).map((id) => `document:${id}`),
    ...folderIds.filter(Boolean).map((id) => `folder:${id}`),
  ]);
  const removedParentKeys = new Set(folderIds.filter(Boolean));
  if (!removedTokens.size && !removedParentKeys.size) return;
  for (const [parentKey, order] of Object.entries(state.directoryOrders ?? {})) {
    if (removedParentKeys.has(parentKey)) {
      delete state.directoryOrders[parentKey];
      continue;
    }
    const next = (order ?? []).filter((token) => !removedTokens.has(token));
    if (next.length) state.directoryOrders[parentKey] = next;
    else delete state.directoryOrders[parentKey];
  }
};
