let attachmentPreviewScale = 1;
let attachmentPreviewPan = { x: 0, y: 0, pointerId: null, startX: 0, startY: 0, originX: 0, originY: 0 };
let attachmentTextPreviewState = null;
let attachmentTextPreviewDraftTimer = 0;
const WHITEBOARD_TEXT_PREVIEW_DRAFT_KEY = "shensi:whiteboard-text-preview-draft:v1";

const attachmentTextPreviewDraftIdentity = (previewState = attachmentTextPreviewState) => previewState ? {
  workspaceId: String(previewState.workspaceId || ""),
  documentId: String(previewState.documentId || ""),
  nodeId: String(previewState.nodeId || ""),
} : null;

const readAttachmentTextPreviewDraft = (previewState = attachmentTextPreviewState) => {
  const identity = attachmentTextPreviewDraftIdentity(previewState);
  if (!identity?.workspaceId || !identity.documentId || !identity.nodeId) return null;
  try {
    const payload = JSON.parse(localStorage.getItem(WHITEBOARD_TEXT_PREVIEW_DRAFT_KEY) || "null");
    if (!payload || payload.schemaVersion !== 1) return null;
    if (payload.workspaceId !== identity.workspaceId || payload.documentId !== identity.documentId || payload.nodeId !== identity.nodeId) return null;
    if (String(payload.baseText ?? "") !== String(previewState.text ?? "")) return null;
    return String(payload.text ?? "");
  } catch {
    return null;
  }
};

const clearAttachmentTextPreviewDraft = () => {
  clearTimeout(attachmentTextPreviewDraftTimer);
  attachmentTextPreviewDraftTimer = 0;
  try { localStorage.removeItem(WHITEBOARD_TEXT_PREVIEW_DRAFT_KEY); } catch {}
};

const flushAttachmentTextPreviewDraft = () => {
  clearTimeout(attachmentTextPreviewDraftTimer);
  attachmentTextPreviewDraftTimer = 0;
  const previewState = attachmentTextPreviewState;
  if (!previewState?.editing) return false;
  const draftText = String(previewState.draftText ?? previewState.text ?? "");
  if (draftText === String(previewState.text ?? "")) {
    clearAttachmentTextPreviewDraft();
    return true;
  }
  const identity = attachmentTextPreviewDraftIdentity(previewState);
  if (!identity) return false;
  try {
    localStorage.setItem(WHITEBOARD_TEXT_PREVIEW_DRAFT_KEY, JSON.stringify({
      schemaVersion: 1,
      ...identity,
      baseText: String(previewState.text ?? ""),
      text: draftText,
      updatedAt: new Date().toISOString(),
    }));
    return true;
  } catch {
    return false;
  }
};

const scheduleAttachmentTextPreviewDraft = () => {
  clearTimeout(attachmentTextPreviewDraftTimer);
  attachmentTextPreviewDraftTimer = setTimeout(flushAttachmentTextPreviewDraft, 80);
};

const attachmentPreviewPanMetrics = () => {
  const stage = elements.attachmentPreviewMedia.closest(".attachment-preview-stage");
  const media = elements.attachmentPreviewMedia.querySelector("img");
  return {
    mediaWidth: media?.offsetWidth || Number.parseFloat(media?.style.width || "0") || 0,
    mediaHeight: media?.offsetHeight || Number.parseFloat(media?.style.height || "0") || 0,
    stageWidth: stage?.clientWidth || 0,
    stageHeight: stage?.clientHeight || 0,
  };
};

const syncAttachmentPreviewTransform = () => {
  const previewKind = elements.attachmentPreviewMedia.dataset.previewKind || "";
  const textPreview = previewKind === "text";
  const textElement = textPreview ? elements.attachmentPreviewMedia.querySelector(".attachment-preview-text") : null;
  if (textElement) textElement.style.fontSize = `${Math.round(16 * attachmentPreviewScale)}px`;
  const pannable = attachmentPreviewCanPan({ kind: previewKind, scale: attachmentPreviewScale });
  const clamped = pannable
    ? clampAttachmentPreviewPan({ ...attachmentPreviewPan, scale: attachmentPreviewScale, ...attachmentPreviewPanMetrics() })
    : { x: 0, y: 0 };
  attachmentPreviewPan.x = clamped.x;
  attachmentPreviewPan.y = clamped.y;
  elements.attachmentPreviewMedia.style.transform = textPreview ? "none" : attachmentPreviewTransform({
    scale: attachmentPreviewScale,
    x: attachmentPreviewPan.x,
    y: attachmentPreviewPan.y,
  });
  elements.attachmentPreviewMedia.dataset.scale = attachmentPreviewScale.toFixed(2);
  elements.attachmentPreviewMedia.dataset.panX = attachmentPreviewPan.x.toFixed(2);
  elements.attachmentPreviewMedia.dataset.panY = attachmentPreviewPan.y.toFixed(2);
  elements.attachmentPreviewMedia.dataset.pannable = String(pannable);
  const image = elements.attachmentPreviewMedia.querySelector("img");
  if (image) image.draggable = !pannable;
};

const resetAttachmentPreviewPan = () => {
  attachmentPreviewPan = { x: 0, y: 0, pointerId: null, startX: 0, startY: 0, originX: 0, originY: 0 };
  elements.attachmentPreviewMedia.classList.remove("is-panning");
};

const setAttachmentPreviewScale = (scale) => {
  attachmentPreviewScale = Math.min(20, Math.max(0.5, scale));
  if (attachmentPreviewScale <= 1) resetAttachmentPreviewPan();
  syncAttachmentPreviewTransform();
};

const fitAttachmentPreviewMedia = (media) => {
  const sourceWidth = Number(media.naturalWidth || media.videoWidth || 16);
  const sourceHeight = Number(media.naturalHeight || media.videoHeight || 9);
  const maxWidth = Math.max(120, window.innerWidth - 72);
  const maxHeight = Math.max(120, window.innerHeight - 96);
  const ratio = sourceWidth / Math.max(1, sourceHeight);
  let width = maxWidth;
  let height = width / ratio;
  if (height > maxHeight) {
    height = maxHeight;
    width = height * ratio;
  }
  media.style.width = `${Math.round(width)}px`;
  media.style.height = `${Math.round(height)}px`;
  syncAttachmentPreviewTransform();
};

const attachmentTextPreviewDraft = () => String(
  elements.attachmentPreviewMedia.querySelector("[data-attachment-text-editor]")?.value
  ?? attachmentTextPreviewState?.draftText
  ?? attachmentTextPreviewState?.text
  ?? "",
);

const attachmentTextPreviewHasUnsavedDraft = () => Boolean(
  attachmentTextPreviewState?.editing
  && attachmentTextPreviewDraft() !== String(attachmentTextPreviewState.text ?? ""),
);

const captureAttachmentTextPreviewViewport = () => {
  const previewText = elements.attachmentPreviewMedia.querySelector(".attachment-preview-text");
  const rect = previewText?.getBoundingClientRect?.();
  if (!rect || rect.width <= 0 || rect.height <= 0) return null;
  return {
    width: Math.round(rect.width),
    height: Math.round(rect.height),
  };
};

const renderAttachmentTextPreview = ({ focusEditor = false } = {}) => {
  const previewState = attachmentTextPreviewState;
  if (!previewState) return;
  const editing = previewState.editable && previewState.editing;
  const draftText = attachmentTextPreviewDraft();
  elements.attachmentPreviewContent.dataset.previewKind = "text";
  elements.closeAttachmentPreview.hidden = true;
  elements.attachmentPreviewTextActions.hidden = !previewState.editable;
  elements.cancelAttachmentTextEdit.hidden = !editing;
  elements.toggleAttachmentTextEdit.dataset.mode = editing ? "save" : "edit";
  elements.toggleAttachmentTextEdit.title = editing ? "保存并返回阅读" : "编辑文字";
  elements.toggleAttachmentTextEdit.setAttribute("aria-label", editing ? "保存并返回阅读" : "编辑文字");
  elements.toggleAttachmentTextEdit.setAttribute("aria-pressed", String(editing));
  elements.toggleAttachmentTextEdit.innerHTML = editing
    ? icon("\uE736", "保存并返回阅读")
    : icon("\uE70F", "编辑文字");
  elements.attachmentPreviewMedia.dataset.previewKind = "text";
  elements.attachmentPreviewMedia.innerHTML = editing
    ? `<textarea class="attachment-preview-text attachment-preview-text-editor" data-attachment-text-editor aria-label="${escapeHtml(previewState.name)}">${escapeHtml(draftText)}</textarea>`
    : `<pre class="attachment-preview-text" tabindex="0" aria-label="${escapeHtml(previewState.name)}">${escapeHtml(previewState.text || "空白文本")}</pre>`;
  if (editing && previewState.editorViewport) {
    const editor = elements.attachmentPreviewMedia.querySelector("[data-attachment-text-editor]");
    editor.style.width = `${previewState.editorViewport.width}px`;
    editor.style.height = `${previewState.editorViewport.height}px`;
    editor.style.minHeight = `${previewState.editorViewport.height}px`;
  }
  syncAttachmentPreviewTransform();
  if (ui.whiteboardFind.open) requestAnimationFrame(() => renderWhiteboardFindPanel());
  if (focusEditor) {
    requestAnimationFrame(() => {
      const editor = elements.attachmentPreviewMedia.querySelector("[data-attachment-text-editor]");
      if (!editor) return;
      editor.focus();
      editor.setSelectionRange(editor.value.length, editor.value.length);
    });
  }
};

const closeAttachmentPreview = () => {
  if (attachmentTextPreviewHasUnsavedDraft() && !window.confirm("当前预览中的编辑尚未保存，确定放弃修改并关闭吗？")) return false;
  if (attachmentTextPreviewState?.editing) clearAttachmentTextPreviewDraft();
  if (ui.whiteboardFind.open && elements.whiteboardFindPanel.closest("#attachmentPreviewDialog")) closeWhiteboardFindPanel();
  const fullscreenElement = document.fullscreenElement;
  if (fullscreenElement && elements.attachmentPreviewDialog.contains(fullscreenElement)) {
    void document.exitFullscreen?.().catch(() => {});
  }
  // Exit the modal interaction state before releasing a potentially large
  // decoded image/video.  This makes the workspace clickable in the first
  // available turn instead of waiting for media teardown and garbage collection.
  elements.attachmentPreviewDialog.classList.add("is-closing");
  if (elements.attachmentPreviewDialog.open) elements.attachmentPreviewDialog.close();
  for (const media of elements.attachmentPreviewMedia.querySelectorAll("video, audio")) {
    try { media.pause(); } catch {}
    media.removeAttribute("src");
    media.querySelectorAll("source").forEach((source) => source.removeAttribute("src"));
    try { media.load(); } catch {}
  }
  elements.attachmentPreviewMedia.querySelectorAll("img").forEach((image) => image.removeAttribute("src"));
  elements.attachmentPreviewMedia.replaceChildren();
  return true;
};

const startAttachmentTextEditing = async () => {
  if (!attachmentTextPreviewState?.editable || attachmentTextPreviewState.editing) return;
  const previewState = attachmentTextPreviewState;
  if (previewState.workspaceId !== workspaceIdentity()) {
    elements.toggleAttachmentTextEdit.disabled = true;
    try {
      const loaded = await fetchWorkspacePayload(previewState.workspacePath);
      if (attachmentTextPreviewState !== previewState || !elements.attachmentPreviewDialog.open) return;
      const sourceDocument = loaded?.state?.documents?.[previewState.documentId];
      const sourceNode = whiteboardNodeById(previewState.nodeId, sourceDocument);
      if (!sourceDocument || sourceDocument.documentKind !== "whiteboard" || !["text", "generated"].includes(sourceNode?.kind)) {
        throw new Error("来源文字卡片已不存在");
      }
      previewState.text = String(sourceNode.text ?? "");
      previewState.draftText = previewState.text;
    } catch (error) {
      showToast(`无法打开资产编辑：${error.message}`);
      return;
    } finally {
      elements.toggleAttachmentTextEdit.disabled = false;
    }
  }
  if (attachmentTextPreviewState !== previewState || !elements.attachmentPreviewDialog.open) return;
  previewState.editorViewport = captureAttachmentTextPreviewViewport();
  const recoveredDraft = readAttachmentTextPreviewDraft(previewState);
  previewState.draftText = recoveredDraft ?? previewState.text;
  previewState.editing = true;
  renderAttachmentTextPreview({ focusEditor: true });
  if (recoveredDraft !== null && recoveredDraft !== previewState.text) showToast("已恢复上次未提交的预览编辑草稿");
};

const cancelAttachmentTextEditing = () => {
  if (!attachmentTextPreviewState?.editing) return;
  clearAttachmentTextPreviewDraft();
  attachmentTextPreviewState.draftText = attachmentTextPreviewState.text;
  attachmentTextPreviewState.editing = false;
  renderAttachmentTextPreview();
  elements.toggleAttachmentTextEdit.focus();
};

const saveInactiveAttachmentTextEditing = async (previewState, nextText) => {
  const key = workspaceCacheKey(previewState.workspaceKind, previewState.workspacePath);
  return enqueueInactiveWorkspaceGenerationWrite({
    key,
    loadLatest: () => fetchWorkspacePayload(previewState.workspacePath),
    merge: (loaded) => {
      const workspaceState = clone(loaded?.state || {});
      const documentState = workspaceState.documents?.[previewState.documentId];
      const currentNode = whiteboardNodeById(previewState.nodeId, documentState);
      if (!documentState || documentState.documentKind !== "whiteboard" || !["text", "generated"].includes(currentNode?.kind)) {
        throw new Error("来源文字卡片已不存在，无法保存修改");
      }
      const currentText = String(currentNode.text ?? "");
      if (currentText !== previewState.text) return { workspaceState, currentText, conflict: true };
      documentState.canvas = snapshotCanvasNodeVersion(documentState.canvas, previewState.nodeId, {
        id: uid("canvas-version"),
        source: "asset-preview-edit",
      });
      documentState.canvas = updateCanvasTextNode(documentState.canvas, previewState.nodeId, { text: nextText });
      documentState.updatedAt = nowTime();
      return { workspaceState, currentText, conflict: false };
    },
    save: async (merged, loaded) => {
      if (merged.conflict) return merged;
      const request = await workspaceSaveRequest({
        workspacePath: previewState.workspacePath,
        expectedStateStamp: loaded?.stateStamp || "",
        state: backgroundWorkspaceStateForSave(merged.workspaceState),
        operationDocumentIds: [previewState.documentId],
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw workspaceSaveError(response, payload);
      cacheWorkspaceState({
        workspaceKind: previewState.workspaceKind,
        workspacePath: previewState.workspacePath,
        workspaceState: merged.workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        prepared: true,
      });
      return { ...merged, stateStamp: payload.stateStamp || "" };
    },
  });
};

const saveAttachmentTextEditing = async () => {
  const previewState = attachmentTextPreviewState;
  if (!previewState?.editable || !previewState.editing || previewState.saving) return;
  const activeSource = previewState.workspaceId === workspaceIdentity() && previewState.documentId === state.activeDocument;
  if (activeSource && (state.readOnly || whiteboardCandidateFor(previewState.nodeId))) {
    showToast("当前卡片状态已变化，请关闭预览后重新打开再编辑");
    return;
  }
  const nextText = attachmentTextPreviewDraft();
  if (!activeSource) {
    previewState.saving = true;
    elements.toggleAttachmentTextEdit.disabled = true;
    elements.cancelAttachmentTextEdit.disabled = true;
    try {
      const result = await saveInactiveAttachmentTextEditing(previewState, nextText);
      if (result.conflict) {
        previewState.text = result.currentText;
        previewState.draftText = nextText;
        flushAttachmentTextPreviewDraft();
        renderAttachmentTextPreview({ focusEditor: true });
        showToast("来源卡片已在其他操作中更新，当前预览草稿已保留；再次点击阅读可保存到最新卡片");
        return;
      }
      clearAttachmentTextPreviewDraft();
      previewState.text = nextText;
      previewState.draftText = nextText;
      previewState.editing = false;
      renderAttachmentTextPreview();
      void refreshGlobalHistoricalAssets();
      showToast("文字卡片已保存，修改前内容已加入历史版本");
    } catch (error) {
      showToast(`文字卡片保存失败：${error.message}`);
    } finally {
      previewState.saving = false;
      elements.toggleAttachmentTextEdit.disabled = false;
      elements.cancelAttachmentTextEdit.disabled = false;
    }
    return;
  }
  const documentState = state.documents[previewState.documentId];
  const currentNode = whiteboardNodeById(previewState.nodeId, documentState);
  if (!documentState || documentState.documentKind !== "whiteboard" || !["text", "generated"].includes(currentNode?.kind)) {
    showToast("当前文字卡片已不存在，无法保存修改");
    return;
  }
  const currentText = String(currentNode.text ?? "");
  if (currentText !== previewState.text) {
    const preservedDraft = attachmentTextPreviewDraft();
    previewState.text = currentText;
    previewState.draftText = preservedDraft;
    flushAttachmentTextPreviewDraft();
    renderAttachmentTextPreview({ focusEditor: true });
    showToast("卡片内容已在其他操作中更新，当前预览草稿已保留；再次点击阅读可保存到最新卡片");
    return;
  }
  if (nextText !== currentText) {
    const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
    documentState.canvas = snapshotCanvasNodeVersion(documentState.canvas, previewState.nodeId, {
      id: uid("canvas-version"),
      source: "preview-edit",
    });
    documentState.canvas = updateCanvasTextNode(documentState.canvas, previewState.nodeId, { text: nextText });
    documentState.updatedAt = nowTime();
    pushWhiteboardHistory(beforeCanvas, { documentId: previewState.documentId, label: "在预览中编辑卡片" });
    persist({ documentIds: [previewState.documentId] });
    renderWhiteboard(documentState);
    if (elements.whiteboardAssetDialog.open) renderWhiteboardAssets();
  }
  clearAttachmentTextPreviewDraft();
  previewState.text = nextText;
  previewState.draftText = nextText;
  previewState.editing = false;
  renderAttachmentTextPreview();
  elements.toggleAttachmentTextEdit.focus();
  if (nextText !== currentText) showToast("文字卡片已保存，修改前内容已加入历史版本");
};

const requestAttachmentFullscreen = async (media) => {
  const dialog = elements.attachmentPreviewDialog;
  dialog.dataset.fullscreenRequested = "true";
  try {
    if (typeof media?.requestFullscreen === "function") {
      await media.requestFullscreen({ navigationUI: "hide" });
      return true;
    }
    if (typeof media?.webkitEnterFullscreen === "function") {
      media.webkitEnterFullscreen();
      return true;
    }
    if (typeof dialog?.requestFullscreen === "function") {
      await dialog.requestFullscreen({ navigationUI: "hide" });
      return true;
    }
  } catch {
    // The full-viewport modal below remains a deterministic Electron fallback.
  }
  dialog.classList.add("fullscreen-fallback");
  return false;
};

const attachmentVideoIsFullscreen = (preview) => {
  const video = preview?.matches?.("video") ? preview : preview?.querySelector?.("video");
  if (!video) return false;
  const fullscreenElement = document.fullscreenElement;
  return Boolean(
    video.webkitDisplayingFullscreen === true
    || video.dataset.nativeFullscreen === "true"
    || video.matches?.(":fullscreen")
    || fullscreenElement === video
    || fullscreenElement?.contains?.(video)
    || video.contains?.(fullscreenElement),
  );
};

const openAttachmentPreview = (preview) => {
  elements.attachmentPreviewDialog.classList.remove("is-closing");
  const previewKind = preview?.dataset.attachmentPreview || "image";
  const relativePath = String(preview?.dataset?.attachmentPath || preview?.closest?.("[data-attachment-path]")?.dataset?.attachmentPath || "");
  const attachmentWorkspacePath = String(preview?.dataset?.attachmentWorkspacePath || state.settings.workspacePath);
  const attachmentWorkspaceKind = String(preview?.dataset?.attachmentWorkspaceKind || state.workspaceKind);
  const attachmentDocumentId = String(preview?.dataset?.attachmentDocumentId || state.activeDocument);
  const attachmentMediaBatchDirectory = String(preview?.dataset?.mediaBatchDirectory || preview?.closest?.("[data-media-batch-directory]")?.dataset?.mediaBatchDirectory || "");
  const attachmentMediaDirectoryKind = String(preview?.dataset?.mediaDirectoryKind || preview?.closest?.("[data-media-directory-kind]")?.dataset?.mediaDirectoryKind || "");
  const video = previewKind === "video";
  const sourceCard = preview?.closest?.("[data-canvas-node]");
  const frameDestination = sourceCard ? "whiteboard" : "conversation";
  const frameSourceNode = String(sourceCard?.dataset?.canvasNode || "");
  if (previewKind === "video" && attachmentVideoIsFullscreen(preview)) return;
  if (
    previewKind !== "text"
    &&
    elements.attachmentPreviewDialog.open
    && elements.attachmentPreviewDialog.dataset.attachmentPath === relativePath
    && elements.attachmentPreviewDialog.dataset.attachmentKind === previewKind
    && elements.attachmentPreviewDialog.dataset.attachmentWorkspacePath === attachmentWorkspacePath
    && elements.attachmentPreviewDialog.dataset.mediaBatchDirectory === attachmentMediaBatchDirectory
    && elements.attachmentPreviewDialog.dataset.frameDestination === frameDestination
    && elements.attachmentPreviewDialog.dataset.frameSourceNode === frameSourceNode
  ) return;
  elements.attachmentPreviewDialog.dataset.attachmentPath = relativePath;
  elements.attachmentPreviewDialog.dataset.attachmentKind = previewKind;
  elements.attachmentPreviewDialog.dataset.attachmentDownloadName = String(preview?.dataset?.attachmentDownloadName || "");
  elements.attachmentPreviewDialog.dataset.attachmentWorkspacePath = attachmentWorkspacePath;
  elements.attachmentPreviewDialog.dataset.attachmentWorkspaceKind = attachmentWorkspaceKind;
  elements.attachmentPreviewDialog.dataset.attachmentDocumentId = attachmentDocumentId;
  elements.attachmentPreviewDialog.dataset.mediaBatchDirectory = attachmentMediaBatchDirectory;
  elements.attachmentPreviewDialog.dataset.mediaDirectoryKind = attachmentMediaDirectoryKind;
  elements.attachmentPreviewDialog.dataset.frameDestination = frameDestination;
  elements.attachmentPreviewDialog.dataset.frameSourceNode = frameSourceNode;
  elements.extractAttachmentVideoFrame.hidden = !video || !relativePath;
  elements.extractAttachmentVideoFrame.dataset.frameDestination = frameDestination;
  elements.extractAttachmentVideoFrame.dataset.frameSourceNode = frameSourceNode;
  elements.extractAttachmentVideoFrame.dataset.attachmentPath = relativePath;
  elements.extractAttachmentVideoFrame.dataset.attachmentWorkspacePath = attachmentWorkspacePath;
  elements.extractAttachmentVideoFrame.dataset.attachmentDocumentId = attachmentDocumentId;
  if (previewKind === "text") {
    const previewNodeId = String(preview?.dataset?.whiteboardPreviewNodeId || "");
    const previewWorkspaceId = String(preview?.dataset?.whiteboardPreviewWorkspaceId || "");
    const previewSourceEditable = preview?.dataset?.whiteboardPreviewEditable === "true";
    const hasWhiteboardPreviewText = Object.prototype.hasOwnProperty.call(preview?.dataset || {}, "whiteboardPreviewText");
    const sourceText = hasWhiteboardPreviewText
      ? String(preview.dataset.whiteboardPreviewText || "")
      : String(preview.querySelector("pre")?.textContent || "空白文本");
    const name = preview.title || preview.getAttribute("aria-label") || "历史文本预览";
    const previewDocumentState = state.documents[attachmentDocumentId];
    const currentNode = previewNodeId ? whiteboardNodeById(previewNodeId, previewDocumentState) : null;
    const activeSourceEditable = Boolean(
      previewNodeId
      && previewWorkspaceId === workspaceIdentity()
      && attachmentDocumentId === state.activeDocument
      && previewDocumentState?.documentKind === "whiteboard"
      && ["text", "generated"].includes(currentNode?.kind)
      && !state.readOnly
      && !whiteboardCandidateFor(previewNodeId)
    );
    const inactiveSourceEditable = Boolean(
      previewSourceEditable
      && previewNodeId
      && previewWorkspaceId
      && previewWorkspaceId !== workspaceIdentity()
      && attachmentWorkspacePath
      && attachmentDocumentId
    );
    const editable = activeSourceEditable || inactiveSourceEditable;
    attachmentTextPreviewState = {
      workspaceId: previewWorkspaceId,
      workspacePath: attachmentWorkspacePath,
      workspaceKind: attachmentWorkspaceKind,
      documentId: attachmentDocumentId,
      nodeId: previewNodeId,
      name,
      text: activeSourceEditable ? String(currentNode.text ?? "") : sourceText,
      editable,
      editing: false,
      draftText: activeSourceEditable ? String(currentNode.text ?? "") : sourceText,
      editorViewport: null,
    };
    renderAttachmentTextPreview();
    setAttachmentPreviewScale(1);
    if (!elements.attachmentPreviewDialog.open) elements.attachmentPreviewDialog.showModal();
    (editable ? elements.toggleAttachmentTextEdit : elements.closeAttachmentPreview).focus();
    return;
  }
  attachmentTextPreviewState = null;
  elements.attachmentPreviewContent.dataset.previewKind = previewKind;
  elements.closeAttachmentPreview.hidden = false;
  elements.attachmentPreviewTextActions.hidden = true;
  const sourceMedia = preview?.matches?.("img, video")
    ? preview
    : preview?.querySelector("img, video");
  const source = preview?.dataset?.attachmentSrc || sourceMedia?.currentSrc || sourceMedia?.src || "";
  if (!source) return;
  const name = preview.title || sourceMedia?.alt || sourceMedia?.getAttribute("aria-label") || "附件预览";
  const fullscreen = video && preview?.dataset?.attachmentFullscreen === "true";
  elements.attachmentPreviewMedia.dataset.previewKind = previewKind;
  elements.attachmentPreviewMedia.innerHTML = video
    ? `<video src="${escapeHtml(source)}" aria-label="${escapeHtml(name)}" controls playsinline preload="metadata"></video>`
    : `<img src="${escapeHtml(source)}" alt="${escapeHtml(name)}" />`;
  setAttachmentPreviewScale(1);
  const media = elements.attachmentPreviewMedia.querySelector("img, video");
  const fit = () => fitAttachmentPreviewMedia(media);
  if (video) media.addEventListener("loadedmetadata", fit, { once: true });
  else media.addEventListener("load", fit, { once: true });
  if ((video && media.readyState >= 1) || (!video && media.complete)) fit();
  if (!elements.attachmentPreviewDialog.open) elements.attachmentPreviewDialog.showModal();
  elements.closeAttachmentPreview.focus();
  if (fullscreen) {
    void requestAttachmentFullscreen(media);
  }
};

const paneResizers = Array.from(document.querySelectorAll("[data-pane-resizer]"));
const workspaceWidth = () => elements.workspace.getBoundingClientRect().width || window.innerWidth;

const desktopWindowControl = () => window.shensiDesktop?.windowControl;

const NOTE_TOOLBAR_INLINE_WIDTH = 900;
const NOTE_TOOLBAR_CONTROL_SELECTOR = "[data-note-command], [data-note-action], [data-note-block]";

const syncNoteToolbarMoreItems = () => {
  const primary = elements.noteRichToolbar.querySelector(".note-toolbar-primary");
  if (!primary) return;
  const primaryControlList = Array.from(primary.querySelectorAll(NOTE_TOOLBAR_CONTROL_SELECTOR));
  const moreControlList = Array.from(elements.noteToolbarMore.querySelectorAll(NOTE_TOOLBAR_CONTROL_SELECTOR));
  [...primaryControlList, ...moreControlList].forEach((control) => {
    const key = noteToolbarControlKey(control);
    if (key) control.dataset.noteControlKey = key;
  });
  const moreKeys = new Set(moreControlList.map(noteToolbarControlKey).filter(Boolean));
  primaryControlList.forEach((control) => {
    if (moreKeys.has(noteToolbarControlKey(control))) control.hidden = false;
  });
  // Reveal duplicate primary controls for one layout pass so a wider toolbar can reclaim them.
  primary.getBoundingClientRect();
  const primaryControls = new Map(primaryControlList
    .map((control) => [noteToolbarControlKey(control), control])
    .filter(([key]) => key));
  const visibility = new Map([...primaryControls].map(([key, control]) => [
    key,
    noteToolbarControlFullyVisible(control, primary),
  ]));
  moreControlList.forEach((control) => {
    const matching = primaryControls.get(noteToolbarControlKey(control));
    if (!matching) {
      control.hidden = false;
      return;
    }
    const assignment = noteToolbarDuplicateAssignment({
      hasPrimary: true,
      primaryFullyVisible: visibility.get(noteToolbarControlKey(control)) === true,
    });
    matching.hidden = assignment.primaryHidden;
    control.hidden = assignment.moreHidden;
  });
};

const noteToolbarInlineActive = () => {
  if (elements.noteRichToolbar.hidden) return false;
  const pane = elements.editor.closest(".editor-pane");
  return document.fullscreenElement === pane
    || elements.noteRichToolbar.getBoundingClientRect().width >= NOTE_TOOLBAR_INLINE_WIDTH;
};

const syncNoteToolbarLayout = () => {
  const inline = noteToolbarInlineActive();
  elements.noteRichToolbar.classList.toggle("inline-tools-expanded", inline);
  elements.noteToolbarExpand.hidden = inline;
  elements.noteToolbarMore.hidden = elements.noteRichToolbar.hidden || (!inline && !ui.noteToolbarExpanded);
  if (elements.noteRichToolbar.hidden) closeNoteTableSizePicker();
  syncNoteToolbarMoreItems();
};

let noteToolbarLayoutFrame = 0;
const scheduleNoteToolbarLayout = () => {
  if (noteToolbarLayoutFrame) cancelAnimationFrame(noteToolbarLayoutFrame);
  noteToolbarLayoutFrame = requestAnimationFrame(() => {
    noteToolbarLayoutFrame = 0;
    syncNoteToolbarLayout();
  });
};

const minimizeAppWindow = async () => {
  const bridge = desktopWindowControl();
  if (typeof bridge?.minimize === "function") await bridge.minimize();
  else showToast("浏览器预览无法缩小应用窗口；桌面版中此按钮会缩小窗口");
};

const applyWindowControlState = (maximized) => {
  elements.windowMaximizeButton.title = maximized ? "还原窗口" : "放大窗口";
  elements.windowMaximizeButton.innerHTML = maximized ? icon("\uE923", "还原窗口") : icon("\uE922", "放大窗口");
};

const syncWindowControlState = async () => {
  const bridge = desktopWindowControl();
  if (typeof bridge?.isMaximized === "function") {
    const state = await bridge.isMaximized().catch(() => ({ maximized: false }));
    applyWindowControlState(state?.maximized === true || state?.fullscreen === true);
    return;
  }
  applyWindowControlState(document.fullscreenElement === document.documentElement);
};

const syncNoteFullscreenState = () => {
  const active = elements.workspace.classList.contains("editor-fullscreen-active");
  syncNoteToolbarLayout();
  if (elements.whiteboardFullscreenButton) {
    const label = active ? "退出全屏编辑（F11）" : "全屏编辑（F11）";
    elements.whiteboardFullscreenButton.title = label;
    elements.whiteboardFullscreenButton.setAttribute("aria-label", label);
    elements.whiteboardFullscreenButton.setAttribute("aria-pressed", String(active));
    elements.whiteboardFullscreenButton.innerHTML = icon(active ? "\uE73F" : "\uE740", label);
  }
};

const toggleMaximizeAppWindow = async () => {
  const bridge = desktopWindowControl();
  if (typeof bridge?.toggleMaximize === "function") {
    const state = await bridge.toggleMaximize();
    applyWindowControlState(state?.maximized === true);
    return;
  }
  if (document.fullscreenElement) await document.exitFullscreen();
  else await document.documentElement.requestFullscreen();
  syncWindowControlState();
};

const closeAppWindow = async () => {
  const bridge = desktopWindowControl();
  if (typeof bridge?.close === "function") {
    await bridge.close();
  }
  else showToast("浏览器预览不会关闭浏览器标签；桌面版中此按钮会关闭窗口");
};

const applyChatPanelState = () => {
  elements.workspace.classList.toggle("chat-panel-collapsed", chatPanelCollapsed);
  elements.chatPanel.setAttribute("aria-hidden", String(chatPanelCollapsed));
  elements.chatPanel.inert = chatPanelCollapsed;
  const label = chatPanelCollapsed ? "展开右侧对话栏" : "收起右侧对话栏";
  elements.chatPanelToggle.title = label;
  elements.chatPanelToggle.setAttribute("aria-label", label);
  elements.chatPanelToggle.setAttribute("aria-expanded", String(!chatPanelCollapsed));
  elements.chatPanelToggle.innerHTML = icon(chatPanelCollapsed ? "\uE76B" : "\uE76C", label);
};

const applyLeftSidebarState = () => {
  elements.workspace.classList.toggle("left-sidebar-collapsed", leftSidebarCollapsed);
  if (elements.leftSidebar) {
    elements.leftSidebar.setAttribute("aria-hidden", String(leftSidebarCollapsed));
    // 只对侧栏内容子元素设置 inert，保留收起/展开按钮可交互
    Array.from(elements.leftSidebar.children).forEach((child) => {
      child.inert = leftSidebarCollapsed;
    });
  }
  const label = leftSidebarCollapsed ? "展开左侧目录栏" : "收起左侧目录栏";
  if (elements.leftSidebarToggle) {
    elements.leftSidebarToggle.title = label;
    elements.leftSidebarToggle.setAttribute("aria-label", label);
    elements.leftSidebarToggle.setAttribute("aria-expanded", String(!leftSidebarCollapsed));
    elements.leftSidebarToggle.innerHTML = icon(leftSidebarCollapsed ? "\uE76C" : "\uE76B", label);
  }
};

const writingTimerContext = () => {
  const documentState = state.documents?.[state.activeDocument];
  const eligible = !workspaceHasNoActiveEntry()
    && Boolean(documentState)
    && state.activeDocument !== "library-trash";
  return { timerId: GLOBAL_WRITING_TIMER_ID, eligible };
};

const activeWritingTimerRecord = () => normalizeWritingTimerRecord(
  writingTimerStore.timers[GLOBAL_WRITING_TIMER_ID] ?? {},
  GLOBAL_WRITING_TIMER_ID,
);

const setActiveWritingTimerRecord = (record, metrics = writingTimerStore.metrics) => {
  writingTimerStore = normalizeWritingTimerStore({
    ...writingTimerStore,
    timers: {
      ...writingTimerStore.timers,
      [GLOBAL_WRITING_TIMER_ID]: normalizeWritingTimerRecord(record, GLOBAL_WRITING_TIMER_ID),
    },
    metrics,
  });
  clearTimeout(writingTimerPersistTimer);
  writingTimerPersistTimer = null;
  persistWritingTimerStore(writingTimerStore);
};

const recordActiveWritingMetrics = ({ documentId, deltaChars, insertedChars = null, now = Date.now() } = {}) => {
  const record = activeWritingTimerRecord();
  if (record.status !== WRITING_TIMER_STATUS.running) return;
  writingTimerStore = normalizeWritingTimerStore({
    ...writingTimerStore,
    metrics: recordWritingMetricsActivity(writingTimerStore.metrics, { documentId, deltaChars, insertedChars, now }),
  });
  scheduleWritingTimerStorePersist();
};

const writingTimerStatusLabel = (status) => ({
  [WRITING_TIMER_STATUS.running]: "正在计时",
  [WRITING_TIMER_STATUS.paused]: "已手动暂停",
  [WRITING_TIMER_STATUS.stopped]: "本次计时已停止",
  [WRITING_TIMER_STATUS.idle]: "尚未开始计时",
}[status] || "尚未开始计时");

const refreshWritingTimerDisplay = () => {
  if (elements.writingTimer.hidden) return;
  const record = activeWritingTimerRecord();
  const durationLabel = formatWritingTimerDuration(writingTimerElapsedMs(record));
  const statusLabel = writingTimerStatusLabel(record.status);
  elements.writingTimer.dataset.status = record.status;
  elements.writingTimerTime.textContent = durationLabel;
  elements.writingTimerTime.title = statusLabel;
  elements.writingTimerToggle.title = `${statusLabel}，已计 ${durationLabel}；点击展开`;
  elements.writingTimerToggle.setAttribute("aria-label", elements.writingTimerToggle.title);
  const metrics = writingMetricsSnapshot(writingTimerStore.metrics, Date.now(), {
    timerElapsedMs: writingTimerElapsedMs(record),
    timerRunning: record.status === WRITING_TIMER_STATUS.running,
  });
  elements.writingSessionCharacters.textContent = metrics.sessionAddedChars.toLocaleString("zh-CN");
  elements.writingInputSpeed.textContent = metrics.sessionAverageCharsPerMinute.toLocaleString("zh-CN");
  elements.writingActiveTime.textContent = formatWritingTimerDuration(metrics.writingMs);
  elements.writingIdleTime.textContent = formatWritingTimerDuration(metrics.idleMs);
};

const renderWritingTimer = () => {
  const { eligible } = writingTimerContext();
  elements.writingTimer.hidden = !eligible;
  if (!eligible) return;
  const record = activeWritingTimerRecord();
  elements.writingTimer.classList.toggle("expanded", record.expanded);
  elements.writingTimerToggle.hidden = record.expanded;
  elements.writingTimerToggle.setAttribute("aria-expanded", String(record.expanded));
  elements.writingTimerControls.hidden = !record.expanded;
  elements.writingTimerMetrics.hidden = !record.expanded;
  const startButton = elements.writingTimer.querySelector('[data-writing-timer-action="start"]');
  const pauseButton = elements.writingTimer.querySelector('[data-writing-timer-action="pause"]');
  const stopButton = elements.writingTimer.querySelector('[data-writing-timer-action="stop"]');
  startButton.disabled = record.status === WRITING_TIMER_STATUS.running;
  startButton.title = record.status === WRITING_TIMER_STATUS.stopped ? "开始新的计时" : record.status === WRITING_TIMER_STATUS.paused ? "继续计时" : "开始计时";
  startButton.setAttribute("aria-label", startButton.title);
  pauseButton.disabled = record.status !== WRITING_TIMER_STATUS.running;
  stopButton.disabled = [WRITING_TIMER_STATUS.idle, WRITING_TIMER_STATUS.stopped].includes(record.status);
  refreshWritingTimerDisplay();
};

const EDITOR_SEARCH_MIN_WIDTH = 240;
const EDITOR_SEARCH_MAX_WIDTH = 720;
const EDITOR_SEARCH_EDGE_GAP = 16;
let globalSearchLayoutFrame = 0;

const syncGlobalSearchAnchor = () => {
  globalSearchLayoutFrame = 0;
  const topbarRect = elements.topbar?.getBoundingClientRect();
  const editorRect = elements.editorPane?.getBoundingClientRect();
  const projectRect = elements.projectButton?.getBoundingClientRect();
  const topActionsRect = elements.topActions?.getBoundingClientRect();
  if (!topbarRect?.width || !editorRect?.width || !projectRect || !topActionsRect) return;

  const editorCenter = ((editorRect.left + editorRect.right) / 2) - topbarRect.left;
  const leftLimit = projectRect.right - topbarRect.left + EDITOR_SEARCH_EDGE_GAP;
  const rightLimit = topActionsRect.left - topbarRect.left - EDITOR_SEARCH_EDGE_GAP;
  const symmetricRoom = Math.floor(2 * Math.min(editorCenter - leftLimit, rightLimit - editorCenter));
  const searchWidth = Math.min(EDITOR_SEARCH_MAX_WIDTH, symmetricRoom);
  const anchored = searchWidth >= EDITOR_SEARCH_MIN_WIDTH;

  elements.topbar.classList.toggle("editor-search-anchored", anchored);
  if (!anchored) {
    elements.topbar.style.removeProperty("--editor-search-center-x");
    elements.topbar.style.removeProperty("--editor-search-width");
    return;
  }
  elements.topbar.style.setProperty("--editor-search-center-x", `${editorCenter}px`);
  elements.topbar.style.setProperty("--editor-search-width", `${searchWidth}px`);
};

const scheduleGlobalSearchAnchor = () => {
  if (globalSearchLayoutFrame) cancelAnimationFrame(globalSearchLayoutFrame);
  globalSearchLayoutFrame = requestAnimationFrame(syncGlobalSearchAnchor);
};

const availableChatPanelHeight = () => {
  const measured = Math.round(elements.chatPanel?.getBoundingClientRect?.().height || 0);
  if (measured > 0) return measured;
  return Math.max(0, Math.round(window.innerHeight - (elements.topbar?.getBoundingClientRect?.().height || 0)));
};

const chatComposerLayoutOptions = () => {
  const panelHeight = availableChatPanelHeight();
  return {
    panelHeight,
    limits: CHAT_COMPOSER_HEIGHT_LIMITS,
  };
};

const applyChatComposerHeight = () => {
  if (!elements.chatForm || !elements.chatComposerResizer) return CHAT_COMPOSER_HEIGHT_DEFAULT;
  const options = chatComposerLayoutOptions();
  const range = chatComposerHeightRange(options);
  const appliedHeight = clampChatComposerHeight(chatComposerHeight, options);
  elements.chatForm.style.setProperty("--chat-composer-height", `${appliedHeight}px`);
  elements.chatComposerResizer.setAttribute("aria-valuemin", String(range.min));
  elements.chatComposerResizer.setAttribute("aria-valuemax", String(range.max));
  elements.chatComposerResizer.setAttribute("aria-valuenow", String(appliedHeight));
  return appliedHeight;
};

const setChatComposerHeightFromDrag = ({ startHeight, startY }, currentY) => {
  chatComposerHeight = resizeChatComposerHeight({
    startHeight,
    startY,
    currentY,
    ...chatComposerLayoutOptions(),
  });
  applyChatComposerHeight();
};

const applyPaneLayout = () => {
  state.layout = constrainPaneWidths({ ...state.layout, workspaceWidth: workspaceWidth() });
  elements.workspace.style.setProperty("--left-pane-width", `${state.layout.leftPaneWidth}px`);
  elements.workspace.style.setProperty("--right-pane-width", `${state.layout.rightPaneWidth}px`);
  for (const resizer of paneResizers) {
    const side = resizer.dataset.paneResizer;
    resizer.setAttribute("aria-valuenow", String(side === "left" ? state.layout.leftPaneWidth : state.layout.rightPaneWidth));
  }
  applyChatPanelState();
  applyLeftSidebarState();
  applyChatComposerHeight();
  scheduleGlobalSearchAnchor();
};

const setPaneLayoutFromDrag = ({ side, startLeft, startRight, startX }, clientX) => {
  state.layout = resizePaneWidths({
    side,
    startLeft,
    startRight,
    deltaX: clientX - startX,
    workspaceWidth: workspaceWidth(),
  });
  applyPaneLayout();
};

for (const resizer of paneResizers) {
  resizer.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || event.target.closest("#chatPanelToggle") || event.target.closest("#leftSidebarToggle")) return;
    const side = resizer.dataset.paneResizer;
    ui.paneDrag = {
      side,
      pointerId: event.pointerId,
      startX: event.clientX,
      startLeft: state.layout.leftPaneWidth,
      startRight: state.layout.rightPaneWidth,
    };
    resizer.setPointerCapture(event.pointerId);
    resizer.focus({ preventScroll: true });
    resizer.classList.add("active");
    document.body.classList.add("resizing-panes");
    event.preventDefault();
  });
  resizer.addEventListener("pointermove", (event) => {
    if (!ui.paneDrag || ui.paneDrag.pointerId !== event.pointerId) return;
    setPaneLayoutFromDrag(ui.paneDrag, event.clientX);
  });
  const finishPaneResize = (event) => {
    if (!ui.paneDrag || ui.paneDrag.pointerId !== event.pointerId) return;
    setPaneLayoutFromDrag(ui.paneDrag, event.clientX);
    ui.paneDrag = null;
    resizer.classList.remove("active");
    document.body.classList.remove("resizing-panes");
    persistPaneLayout();
    persist();
  };
  resizer.addEventListener("pointerup", finishPaneResize);
  resizer.addEventListener("pointercancel", finishPaneResize);
  resizer.addEventListener("dblclick", (event) => {
    if (event.target.closest("#chatPanelToggle") || event.target.closest("#leftSidebarToggle")) return;
    state.layout = clone(PANE_LAYOUT_DEFAULTS);
    applyPaneLayout();
    persistPaneLayout();
    persist();
    showToast("已恢复默认栏宽");
  });
  resizer.addEventListener("keydown", (event) => {
    if (event.target.closest("#chatPanelToggle")) return;
    if (!["ArrowLeft", "ArrowRight", "Home"].includes(event.key)) return;
    event.preventDefault();
    if (event.key === "Home") {
      state.layout = clone(PANE_LAYOUT_DEFAULTS);
    } else {
      state.layout = resizePaneWidths({
        side: resizer.dataset.paneResizer,
        startLeft: state.layout.leftPaneWidth,
        startRight: state.layout.rightPaneWidth,
        deltaX: event.key === "ArrowRight" ? 12 : -12,
        workspaceWidth: workspaceWidth(),
      });
    }
    applyPaneLayout();
    persistPaneLayout();
    persist();
  });
}

elements.chatComposerResizer.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) return;
  ui.chatComposerDrag = {
    pointerId: event.pointerId,
    startY: event.clientY,
    startHeight: applyChatComposerHeight(),
  };
  elements.chatComposerResizer.setPointerCapture(event.pointerId);
  elements.chatComposerResizer.focus({ preventScroll: true });
  elements.chatComposerResizer.classList.add("active");
  document.body.classList.add("resizing-chat-composer");
  event.preventDefault();
});

elements.chatComposerResizer.addEventListener("pointermove", (event) => {
  if (!ui.chatComposerDrag || ui.chatComposerDrag.pointerId !== event.pointerId) return;
  setChatComposerHeightFromDrag(ui.chatComposerDrag, event.clientY);
});

const finishChatComposerResize = (event) => {
  if (!ui.chatComposerDrag || ui.chatComposerDrag.pointerId !== event.pointerId) return;
  if (event.type === "pointerup") setChatComposerHeightFromDrag(ui.chatComposerDrag, event.clientY);
  ui.chatComposerDrag = null;
  elements.chatComposerResizer.classList.remove("active");
  document.body.classList.remove("resizing-chat-composer");
  persistChatComposerHeight(chatComposerHeight);
};

elements.chatComposerResizer.addEventListener("pointerup", finishChatComposerResize);
elements.chatComposerResizer.addEventListener("pointercancel", finishChatComposerResize);
elements.chatComposerResizer.addEventListener("lostpointercapture", finishChatComposerResize);
elements.chatComposerResizer.addEventListener("dblclick", (event) => {
  event.preventDefault();
  chatComposerHeight = CHAT_COMPOSER_HEIGHT_DEFAULT;
  applyChatComposerHeight();
  persistChatComposerHeight(chatComposerHeight);
  showToast("已恢复默认输入框高度");
});
elements.chatComposerResizer.addEventListener("keydown", (event) => {
  if (!["ArrowUp", "ArrowDown", "Home"].includes(event.key)) return;
  event.preventDefault();
  if (event.key === "Home") {
    chatComposerHeight = CHAT_COMPOSER_HEIGHT_DEFAULT;
  } else {
    const step = event.shiftKey ? 32 : 12;
    const currentHeight = applyChatComposerHeight();
    chatComposerHeight = clampChatComposerHeight(
      currentHeight + (event.key === "ArrowUp" ? step : -step),
      chatComposerLayoutOptions(),
    );
  }
  applyChatComposerHeight();
  persistChatComposerHeight(chatComposerHeight);
});

elements.chatPanelToggle.addEventListener("click", (event) => {
  event.stopPropagation();
  chatPanelCollapsed = !chatPanelCollapsed;
  persistChatPanelCollapsed(chatPanelCollapsed);
  applyChatPanelState();
  applyChatComposerHeight();
  scheduleGlobalSearchAnchor();
  requestAnimationFrame(syncNoteToolbarLayout);
});

elements.leftSidebarToggle?.addEventListener("click", (event) => {
  event.stopPropagation();
  leftSidebarCollapsed = !leftSidebarCollapsed;
  persistLeftSidebarCollapsed(leftSidebarCollapsed);
  applyLeftSidebarState();
  scheduleGlobalSearchAnchor();
  requestAnimationFrame(syncNoteToolbarLayout);
});

window.addEventListener("resize", applyPaneLayout);
const globalSearchResizeObserver = new ResizeObserver(scheduleGlobalSearchAnchor);
[elements.editorPane, elements.topActions, elements.projectButton]
  .filter(Boolean)
  .forEach((element) => globalSearchResizeObserver.observe(element));
const chatComposerLayoutObserver = new ResizeObserver(() => {
  if (!ui.chatComposerDrag) applyChatComposerHeight();
});
[
  elements.chatPanel,
  elements.codexAgentBar,
  elements.referencePanel,
  elements.chatComposerContext,
  document.querySelector("#quickModelPanel"),
]
  .filter(Boolean)
  .forEach((element) => chatComposerLayoutObserver.observe(element));
setInterval(refreshWritingTimerDisplay, 500);

const showToast = (message) => {
  let text = uiText(message);
  // The provider sometimes emits a bare identity-field read gap. It is not
  // actionable for users and is commonly transient; keep the real error in
  // the task record, but present a stable, non-alarming explanation here.
  if (/即梦没有返回\s*user[_ -]?id/iu.test(text)) {
    text = text.replace(/即梦没有返回\s*user[_ -]?id/giu, "即梦账号身份暂时无法读取");
  }
  // Background probes can report the same transient provider message on
  // every poll. Do not reset the dismissal timer for an already visible,
  // identical toast, otherwise it appears to flash forever.
  if (showToast.lastText === text
    && elements.toast.classList.contains("visible")
    && Date.now() - Number(showToast.lastAt || 0) < 3_000) return;
  showToast.lastText = text;
  showToast.lastAt = Date.now();
  elements.toast.textContent = text;
  elements.toast.classList.add("visible");
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => elements.toast.classList.remove("visible"), 2600);
};

const visibleWorkspaceKind = () => ui.workspaceMenuKind;

const renderModules = () => {
  const chromeKind = visibleWorkspaceKind();
  const notebookMode = chromeKind === "notebook";
  const emptyMode = workspaceHasNoActiveEntry();
  const selectingAnotherKind = chromeKind !== state.workspaceKind || emptyMode;
  elements.moduleSwitcher.hidden = notebookMode || emptyMode;
  elements.sidebarDivider.hidden = notebookMode || emptyMode;
  if (notebookMode || emptyMode) {
    if (elements.moduleSwitcher.childElementCount) elements.moduleSwitcher.innerHTML = "";
    ui.moduleSwitcherRenderKey = `${chromeKind}:${emptyMode}:empty`;
    return;
  }
  const activePresentationId = presentationModuleId(state.activeModule);
  const structureKey = `${chromeKind}:${selectingAnotherKind}:${globalUiPreferences.uiLanguage}:${VISIBLE_MODULES.map((module) => `${module.id}:${module.label}:${module.icon}`).join("|")}`;
  if (ui.moduleSwitcherRenderKey === structureKey && elements.moduleSwitcher.childElementCount) {
    elements.moduleSwitcher.querySelectorAll("[data-module]").forEach((button) => {
      button.classList.toggle("active", !selectingAnotherKind && button.dataset.module === activePresentationId);
      button.disabled = selectingAnotherKind;
    });
    return;
  }
  elements.moduleSwitcher.innerHTML = VISIBLE_MODULES.map((module) => `
    <button class="module-button ${!selectingAnotherKind && activePresentationId === module.id ? "active" : ""}" type="button" data-module="${module.id}" title="右键查看${module.label}历史或打开所在文件夹" ${selectingAnotherKind ? "disabled" : ""}>
      ${icon(module.icon)}<span>${module.label}</span>
    </button>
  `).join("");
  ui.moduleSwitcherRenderKey = structureKey;
};

const renderAuthorCockpitDocumentList = () => {
  elements.addDocument.disabled = state.temporaryNotebook === true || state.readOnly === true;
  elements.addDocument.title = elements.addDocument.disabled ? "当前工作区只读" : "正式新建文档、白板或文件夹";
  elements.listTitle.dataset.dropRoot = `${state.activeModule}:default`;
  elements.listTitle.textContent = "索引";
  ensureDirectorySelectionScope(state.activeModule, "default");
  const { sections, directories } = authorCockpitDirectoryContent(state);
  elements.documentList.innerHTML = sections.map((section) => `<section class="author-cockpit-directory-section" data-cockpit-section="${escapeHtml(section.id)}">
    <header><span>${escapeHtml(section.label)}</span><small>${section.items.length}</small></header>
    ${section.items.map((item) => `<button class="document-row ${state.activeDocument === item.id ? "active" : ""}" type="button" data-document="${escapeHtml(item.id)}" data-source-module="${escapeHtml(item.sourceModuleId)}" ${section.id === "compile-reports" ? `draggable="true" data-cockpit-report="${escapeHtml(item.id)}" title="拖动调整编译报告顺序"` : ""}>
      <span class="selection-dot"></span>
      <span class="document-label">${escapeHtml(item.label)}</span>
      <span class="more-button" data-more="${escapeHtml(item.id)}" role="button" tabindex="0" title="更多">•••</span>
    </button>`).join("") || `<p class="empty-folder">暂无内容</p>`}
  </section>`).join("") + directories.map(({ moduleId, viewId, label, tree }) => `<section class="author-cockpit-directory-section" data-directory-module="${escapeHtml(moduleId)}" data-directory-view="${escapeHtml(viewId)}">
    <header><span>${escapeHtml(label)}</span></header>
    ${renderDirectoryTree(orderedDirectoryTree(tree, directoryRootOrderKey(moduleId, viewId)), { moduleId, viewId })}
  </section>`).join("");
  syncDirectorySelectionClasses();
};

const directoryRootOrderKey = (moduleId, viewId) => `${moduleId}:${viewId}:root`;
const directoryNodeToken = (node) => `${node.type}:${node.id}`;

const directoryModuleForTarget = (target) => {
  const moduleId = target?.closest?.("[data-directory-module]")?.dataset.directoryModule;
  return state.workspaceKind === "project" && isAuthorCockpitModule(state.activeModule) && isAuthorCockpitModule(moduleId)
    ? moduleId
    : state.activeModule;
};

const directoryNodeSequence = (node) => {
  if (node?.type !== "document") return null;
  const kind = sequencedDocumentKind(node.id);
  if (!kind) return null;
  return {
    kind,
    number: effectiveSequencedDocumentNumber({ documentId: node.id, documentState: state.documents[node.id], title: node.label }),
  };
};

const defaultOrderedDirectoryNodes = (nodes) => nodes.map((node, index) => ({ node, index })).sort((left, right) => {
  const leftSequence = directoryNodeSequence(left.node);
  const rightSequence = directoryNodeSequence(right.node);
  if (leftSequence?.kind && rightSequence?.kind && leftSequence.kind === rightSequence.kind) {
    return leftSequence.number - rightSequence.number || left.index - right.index;
  }
  if (leftSequence && !rightSequence && left.node.type === right.node.type) return -1;
  if (!leftSequence && rightSequence && left.node.type === right.node.type) return 1;
  return left.index - right.index;
}).map(({ node }) => node);

const mergeExplicitDirectoryOrder = (nodes, order = []) => {
  const defaults = defaultOrderedDirectoryNodes(nodes);
  if (!order.length) return defaults;
  const byToken = new Map(defaults.map((node) => [directoryNodeToken(node), node]));
  const explicit = order.map((token) => byToken.get(token)).filter(Boolean);
  const explicitTokens = new Set(explicit.map(directoryNodeToken));
  const defaultRank = new Map(defaults.map((node, index) => [directoryNodeToken(node), index]));
  const merged = [...explicit];
  for (const node of defaults) {
    const token = directoryNodeToken(node);
    if (explicitTokens.has(token)) continue;
    const rank = defaultRank.get(token);
    const insertAt = merged.findIndex((candidate) => (defaultRank.get(directoryNodeToken(candidate)) ?? Number.MAX_SAFE_INTEGER) > rank);
    if (insertAt < 0) merged.push(node);
    else merged.splice(insertAt, 0, node);
  }
  return merged;
};

const orderedDirectoryTree = (nodes, parentKey) => {
  const order = state.directoryOrders?.[parentKey] ?? [];
  const normalized = nodes.map((node) => (
    node.type === "folder" ? { ...node, children: orderedDirectoryTree(node.children ?? [], node.id) } : node
  ));
  return mergeExplicitDirectoryOrder(normalized, order);
};

const directorySelectionScopeKey = (moduleId = state.activeModule, viewId = activeViewForModule(moduleId)) => [
  state.workspaceKind,
  state.settings.workspacePath || state.projectName || "workspace",
  moduleId,
  viewId,
].join("::");

const documentCutInClipboard = (documentId) => ui.documentClipboard?.mode === "cut"
  && workspaceCacheKey(ui.documentClipboard.sourceWorkspaceKind, ui.documentClipboard.sourceWorkspacePath) === workspaceIdentity()
  && ui.documentClipboard.documentIds.includes(documentId);

const resetDirectorySelection = ({ keepScope = false } = {}) => {
  ui.directorySelectedTokens = new Set();
  ui.directorySelectionAnchorToken = "";
  ui.directoryBatchContext = null;
  if (!keepScope) ui.directorySelectionScope = "";
};

const ensureDirectorySelectionScope = (moduleId = state.activeModule, viewId = activeViewForModule(moduleId)) => {
  const scope = directorySelectionScopeKey(moduleId, viewId);
  if (ui.directorySelectionScope !== scope) {
    resetDirectorySelection({ keepScope: true });
    ui.directorySelectionScope = scope;
  }
  return scope;
};

const visibleDirectoryEntries = () => [...elements.documentList.querySelectorAll("[data-directory-token]")]
  .filter((entry) => !entry.closest("[hidden]"));

const syncDirectorySelectionClasses = () => {
  const available = new Set();
  for (const entry of visibleDirectoryEntries()) {
    const token = entry.dataset.directoryToken;
    available.add(token);
    const selected = ui.directorySelectedTokens.has(token);
    entry.classList.toggle("directory-selected", selected);
    entry.classList.toggle("directory-cut", token.startsWith("document:") && documentCutInClipboard(token.slice("document:".length)));
    entry.setAttribute("aria-selected", selected ? "true" : "false");
  }
  ui.directorySelectedTokens = new Set([...ui.directorySelectedTokens].filter((token) => available.has(token)));
  if (ui.directorySelectionAnchorToken && !available.has(ui.directorySelectionAnchorToken)) ui.directorySelectionAnchorToken = "";
};

const selectDirectoryToken = (token, { range = false, toggle = false, additive = false } = {}) => {
  ensureDirectorySelectionScope();
  const entries = visibleDirectoryEntries();
  const tokens = entries.map((entry) => entry.dataset.directoryToken);
  const targetIndex = tokens.indexOf(token);
  if (targetIndex < 0) return false;
  if (range && ui.directorySelectionAnchorToken && tokens.includes(ui.directorySelectionAnchorToken)) {
    const anchorIndex = tokens.indexOf(ui.directorySelectionAnchorToken);
    const start = Math.min(anchorIndex, targetIndex);
    const end = Math.max(anchorIndex, targetIndex);
    ui.directorySelectedTokens = additive
      ? new Set([...ui.directorySelectedTokens, ...tokens.slice(start, end + 1)])
      : new Set(tokens.slice(start, end + 1));
  } else if (toggle) {
    const next = new Set(ui.directorySelectedTokens);
    if (next.has(token)) next.delete(token);
    else next.add(token);
    ui.directorySelectedTokens = next;
    ui.directorySelectionAnchorToken = token;
  } else {
    ui.directorySelectedTokens = new Set([token]);
    ui.directorySelectionAnchorToken = token;
  }
  syncDirectorySelectionClasses();
  return true;
};

const syncDocumentListActiveState = () => {
  elements.documentList.querySelectorAll("[data-document]").forEach((entry) => {
    entry.classList.toggle("active", entry.dataset.document === state.activeDocument);
  });
};

const documentListStructureKey = ({ moduleId, viewId, items }) => JSON.stringify({
  workspace: workspaceIdentity(),
  moduleId,
  viewId,
  structureLanguage: state.structureLanguage,
  uiLanguage: globalUiPreferences.uiLanguage,
  expandedFolders: state.expandedFolders,
  items: items.map((entry) => {
    const id = Array.isArray(entry) ? entry[0] : "";
    const documentState = state.documents[id];
    return [entry, documentState?.title, documentState?.titleLanguage, documentState?.documentKind, documentState?.systemGeneratedTitle, documentState?.virtual];
  }),
  folders: state.customFolders,
  orders: state.directoryOrders,
});

const renderDirectoryTree = (tree, { moduleId, viewId }) => {
  const module = { id: moduleId };
  const rootOrderKey = directoryRootOrderKey(moduleId, viewId);
  const renderDocumentNode = ({ id, label, options = {} }, depth = 0, parentKey = rootOrderKey) => {
    const displayLabel = localizeSystemDocumentTitle({
      title: label,
      language: state.documents[id]?.titleLanguage ?? state.structureLanguage,
      moduleId: module.id,
      viewId,
      documentId: id,
      documentKind: state.documents[id]?.documentKind,
      systemGenerated: state.documents[id]?.systemGeneratedTitle,
    });
    return `
    <button class="document-row ${depth ? "nested" : ""} ${state.activeDocument === id ? "active" : ""} ${ui.directorySelectedTokens.has(`document:${id}`) ? "directory-selected" : ""} ${documentCutInClipboard(id) ? "directory-cut" : ""}" style="--tree-depth:${depth}" type="button" data-document="${escapeHtml(id)}" data-document-kind="${escapeHtml(state.documents[id]?.documentKind ?? "document")}" data-directory-token="document:${escapeHtml(id)}" data-directory-parent="${escapeHtml(parentKey)}" aria-selected="${ui.directorySelectedTokens.has(`document:${id}`) ? "true" : "false"}" ${options.alias || state.documents[id]?.virtual ? "" : 'draggable="true"'}>
      ${state.documents[id]?.documentKind === "whiteboard" ? icon("\uE7C3", "白板") : '<span class="selection-dot"></span>'}
      <span class="document-label">${escapeHtml(displayLabel)}</span>
      ${options.alias ? `<span class="alias-icon" title="同源引用">${icon("\uE71B")}</span>` : ""}
      <span class="more-button" data-more="${escapeHtml(id)}" role="button" tabindex="0" title="更多">•••</span>
    </button>`;
  };
  const renderTreeNode = (node, depth = 0, parentKey = rootOrderKey) => {
    if (node.type === "document") return renderDocumentNode(node, depth, parentKey);
    const expanded = state.expandedFolders.includes(node.id);
    const isPersistedContentFolder = node.custom === true
      || module.id === "manuscript" && viewId === "novel" && String(node.id).startsWith("manuscript-volume:");
    const displayLabel = localizeDirectoryLabel({
      label: node.label,
      language: isPersistedContentFolder
        ? node.folder?.labelLanguage ?? state.structureLanguage
        : globalUiPreferences.uiLanguage,
      moduleId: module.id,
      viewId,
      folderId: node.id,
      custom: node.custom === true,
      systemGenerated: node.folder?.systemGeneratedLabel,
    });
    const children = expanded
      ? node.children.map((child) => renderTreeNode(child, depth + 1, node.id)).join("") || `<p class="empty-folder" style="--tree-depth:${depth + 1}">文件夹为空</p>`
      : "";
    return `<section class="document-folder" data-folder-container="${escapeHtml(node.id)}">
      <button class="folder-row ${ui.directorySelectedTokens.has(`folder:${node.id}`) ? "directory-selected" : ""}" style="--tree-depth:${depth}" type="button" draggable="true" data-folder-toggle="${escapeHtml(node.id)}" data-drop-folder="${escapeHtml(node.id)}" data-directory-token="folder:${escapeHtml(node.id)}" data-directory-parent="${escapeHtml(parentKey)}" aria-expanded="${expanded}" aria-selected="${ui.directorySelectedTokens.has(`folder:${node.id}`) ? "true" : "false"}" title="拖动调整与文档的上下位置">
        ${icon(expanded ? "\uE70D" : "\uE76C")}
        ${icon(expanded ? "\uE8D5" : "\uE8B7")}
        <span>${escapeHtml(displayLabel)}</span>
        <small>${node.children.length}</small>
      </button>
      <div class="folder-children" ${expanded ? "" : "hidden"}>${children}</div>
    </section>`;
  };
  return tree.map((node) => renderTreeNode(node)).join("");
};

const renderDocumentList = () => {
  const chromeKind = visibleWorkspaceKind();
  if (workspaceHasNoActiveEntry() || chromeKind !== state.workspaceKind) {
    const copy = emptyWorkspaceCopy(chromeKind);
    ui.documentListRenderKey = "";
    elements.listTitle.dataset.dropRoot = "";
    elements.listTitle.innerHTML = `<span class="${chromeKind === "notebook" ? "notebook-directory-title" : ""}">${escapeHtml(copy.directory)}</span>`;
    elements.documentList.innerHTML = `<div class="empty-list workspace-empty-list"><p>${escapeHtml(copy.prompt)}</p><button class="secondary-button" type="button" data-create-empty-workspace>${escapeHtml(copy.action)}</button></div>`;
    elements.addDocument.disabled = true;
    return;
  }
  elements.addDocument.disabled = state.temporaryNotebook === true || state.readOnly === true;
  elements.addDocument.title = elements.addDocument.disabled ? "临时笔记本只用于预览外部 Markdown" : "正式新建文档或文件夹";
  const module = activeModule();
  if (state.workspaceKind === "project" && isAuthorCockpitModule(module.id)) {
    ui.documentListRenderKey = "";
    renderAuthorCockpitDocumentList();
    return;
  }
  const views = MODULE_VIEWS[module.id] ?? [];
  const viewId = activeViewForModule(module.id);
  ensureDirectorySelectionScope(module.id, viewId);
  const currentView = views.find((view) => view.id === viewId) ?? views[0];
  elements.listTitle.dataset.dropRoot = `${module.id}:${viewId}`;
  if (state.workspaceKind === "notebook") {
    elements.listTitle.innerHTML = `<span class="notebook-directory-title">笔记目录</span>`;
  } else if (currentView) {
    elements.listTitle.innerHTML = `<button class="list-view-button" type="button" data-toggle-module-view="${module.id}" aria-expanded="${ui.moduleViewMenu === module.id}" title="右键查看${escapeHtml(currentView.label)}历史或打开所在文件夹"><span>${escapeHtml(currentView.label)}</span>${icon("\uE70D")}</button>
      <div class="list-view-menu" role="menu" ${ui.moduleViewMenu === module.id ? "" : "hidden"}>${views.map((view) => `<button class="${view.id === viewId ? "active" : ""}" type="button" role="menuitem" data-module-view="${escapeHtml(view.id)}">${icon(view.id === viewId ? "\uE73E" : "")}<span>${escapeHtml(view.label)}</span></button>`).join("")}</div>`;
  } else {
    elements.listTitle.textContent = module.listTitle;
  }
  const items = itemsForModuleView(module.id, viewId);
  const structureKey = documentListStructureKey({ moduleId: module.id, viewId, items });
  if (ui.documentListRenderKey === structureKey && elements.documentList.childElementCount) {
    syncDocumentListActiveState();
    syncDirectorySelectionClasses();
    return;
  }
  const rootOrderKey = directoryRootOrderKey(module.id, viewId);
  const tree = orderedDirectoryTree(buildDocumentTree({ moduleId: module.id, viewId, items, documents: state.documents, folders: state.customFolders, workspaceKind: state.workspaceKind }), rootOrderKey);
  elements.documentList.innerHTML = renderDirectoryTree(tree, { moduleId: module.id, viewId }) || `<p class="empty-list">没有匹配的文档</p>`;
  ui.documentListRenderKey = structureKey;
  syncDirectorySelectionClasses();
};

const renderSearchHighlight = () => {
  if (typeof CSS !== "undefined" && CSS.highlights) CSS.highlights.delete("shensi-search");
  delete elements.editor.dataset.searchHighlight;
  const highlight = ui.searchHighlight;
  if (!highlight || highlight.documentId !== state.activeDocument || !highlight.query) return;
  const query = highlight.query.toLowerCase();
  const walker = document.createTreeWalker(elements.editor, NodeFilter.SHOW_TEXT);
  const ranges = [];
  let node;
  while ((node = walker.nextNode()) && ranges.length < 100) {
    const text = node.textContent ?? "";
    const lower = text.toLowerCase();
    let start = lower.indexOf(query);
    while (start >= 0 && ranges.length < 100) {
      const range = new Range();
      range.setStart(node, start);
      range.setEnd(node, start + query.length);
      ranges.push(range);
      start = lower.indexOf(query, start + query.length);
    }
  }
  if (!ranges.length) return;
  if (typeof CSS !== "undefined" && CSS.highlights && typeof Highlight !== "undefined") {
    CSS.highlights.set("shensi-search", new Highlight(...ranges));
    elements.editor.dataset.searchHighlight = "css";
  } else {
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(ranges[0]);
    ui.searchSelection = { documentId: state.activeDocument, query: highlight.query };
    elements.editor.dataset.searchHighlight = "selection";
    elements.selectionToolbar.hidden = true;
  }
  ranges[0].startContainer.parentElement?.scrollIntoView({ block: "center", behavior: "smooth" });
};

const DOCUMENT_FIND_BLOCK_SELECTOR = "p,h1,h2,h3,h4,h5,h6,li,blockquote,pre,td,th,figcaption";
const DOCUMENT_FIND_SKIP_SELECTOR = ".inline-edit-suggestion,[data-note-table-editor-control],[data-document-artifact-controls],script,style,[hidden]";

const activeDocumentFindSurface = () => {
  const documentState = state.documents[state.activeDocument];
  if (!documentState || documentState.documentKind === "whiteboard" || state.activeDocument === "library-trash" || elements.editor.hidden) return null;
  return elements.editor;
};

const documentFindTextGroups = () => {
  const rootElement = activeDocumentFindSurface();
  if (!rootElement) return [];
  const groups = new Map();
  const walker = document.createTreeWalker(rootElement, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue?.length) return NodeFilter.FILTER_REJECT;
      const parent = node.parentElement;
      if (!parent || parent.closest(DOCUMENT_FIND_SKIP_SELECTOR)) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  while (walker.nextNode()) {
    const node = walker.currentNode;
    const block = node.parentElement?.closest(DOCUMENT_FIND_BLOCK_SELECTOR) ?? rootElement;
    const group = groups.get(block) ?? { text: "", segments: [] };
    const start = group.text.length;
    group.text += node.nodeValue ?? "";
    group.segments.push({ node, start, end: group.text.length });
    groups.set(block, group);
  }
  return [...groups.values()];
};

const rangeForDocumentFindMatch = (group, match) => {
  const startSegment = group.segments.find((segment) => match.start >= segment.start && match.start < segment.end);
  const lastCharacterOffset = Math.max(match.start, match.end - 1);
  const endSegment = group.segments.find((segment) => lastCharacterOffset >= segment.start && lastCharacterOffset < segment.end);
  if (!startSegment || !endSegment) return null;
  const range = document.createRange();
  range.setStart(startSegment.node, match.start - startSegment.start);
  range.setEnd(endSegment.node, match.end - endSegment.start);
  return range;
};

const currentDocumentFindMatches = () => {
  const query = ui.documentFind.query;
  if (!query || ui.documentFind.documentId !== state.activeDocument) return [];
  return documentFindTextGroups().flatMap((group) => findTextMatches(group.text, query)
    .map((match) => rangeForDocumentFindMatch(group, match))
    .filter(Boolean));
};

const clearDocumentFindHighlights = () => {
  if (typeof CSS !== "undefined" && CSS.highlights) {
    CSS.highlights.delete("shensi-document-find");
    CSS.highlights.delete("shensi-document-find-active");
  }
  delete elements.editor.dataset.documentFindHighlight;
};

const renderDocumentFindHighlights = (matches, { scroll = false } = {}) => {
  clearDocumentFindHighlights();
  if (!matches.length || ui.documentFind.currentIndex < 0) return;
  const activeRange = matches[ui.documentFind.currentIndex];
  if (typeof CSS !== "undefined" && CSS.highlights && typeof Highlight !== "undefined") {
    const passiveRanges = matches.filter((_, index) => index !== ui.documentFind.currentIndex);
    if (passiveRanges.length) CSS.highlights.set("shensi-document-find", new Highlight(...passiveRanges));
    CSS.highlights.set("shensi-document-find-active", new Highlight(activeRange));
    elements.editor.dataset.documentFindHighlight = "css";
  } else {
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(activeRange.cloneRange());
    ui.searchSelection = { documentId: state.activeDocument, query: activeRange.toString() };
    elements.editor.dataset.documentFindHighlight = "selection";
    elements.selectionToolbar.hidden = true;
  }
  if (scroll) activeRange.startContainer.parentElement?.scrollIntoView({ block: "center", behavior: "smooth" });
};

const renderDocumentFindPanel = ({ scroll = false } = {}) => {
  const available = Boolean(activeDocumentFindSurface());
  const active = ui.documentFind.open && ui.documentFind.documentId === state.activeDocument && available;
  elements.documentFindPanel.hidden = !active;
  if (!active) {
    clearDocumentFindHighlights();
    return [];
  }
  if (elements.documentFindQuery.value !== ui.documentFind.query) elements.documentFindQuery.value = ui.documentFind.query;
  if (elements.documentFindReplacement.value !== ui.documentFind.replacement) elements.documentFindReplacement.value = ui.documentFind.replacement;
  elements.documentFindReplaceRow.hidden = !ui.documentFind.replaceExpanded;
  elements.documentFindReplaceToggle.setAttribute("aria-expanded", String(ui.documentFind.replaceExpanded));
  const matches = currentDocumentFindMatches();
  if (!matches.length) ui.documentFind.currentIndex = -1;
  else if (ui.documentFind.currentIndex < 0 || ui.documentFind.currentIndex >= matches.length) ui.documentFind.currentIndex = 0;
  const currentLabel = ui.documentFind.currentIndex >= 0 ? ui.documentFind.currentIndex + 1 : 0;
  elements.documentFindCount.textContent = `${currentLabel}/${matches.length}`;
  const editable = Boolean(activeEditableDocument());
  elements.documentFindPanel.classList.toggle("is-readonly", !editable);
  elements.documentFindPrevious.disabled = !matches.length;
  elements.documentFindNext.disabled = !matches.length;
  elements.documentFindReplacement.disabled = !editable;
  elements.documentFindReplaceCurrent.disabled = !editable || !matches.length;
  elements.documentFindReplaceAll.disabled = !editable || !matches.length;
  renderDocumentFindHighlights(matches, { scroll });
  return matches;
};

const closeDocumentFindPanel = ({ restoreFocus = false } = {}) => {
  ui.documentFind.open = false;
  ui.documentFind.mutating = false;
  elements.documentFindPanel.hidden = true;
  clearDocumentFindHighlights();
  if (restoreFocus && activeDocumentFindSurface()) elements.editor.focus({ preventScroll: true });
};

const openDocumentFindPanel = ({ replaceExpanded = ui.documentFind.replaceExpanded } = {}) => {
  const surface = activeDocumentFindSurface();
  if (!surface) {
    showToast("当前页面没有可查找的文档正文");
    return false;
  }
  const selection = window.getSelection();
  const selectedText = selection?.rangeCount && surface.contains(selection.anchorNode) ? selection.toString().trim() : "";
  if (ui.documentFind.documentId !== state.activeDocument) {
    ui.documentFind.query = "";
    ui.documentFind.replacement = "";
  }
  ui.documentFind.open = true;
  ui.documentFind.replaceExpanded = Boolean(replaceExpanded);
  ui.documentFind.documentId = state.activeDocument;
  ui.documentFind.currentIndex = 0;
  if (selectedText && selectedText.length <= 200 && !selectedText.includes("\n")) ui.documentFind.query = selectedText;
  renderDocumentFindPanel({ scroll: Boolean(ui.documentFind.query) });
  requestAnimationFrame(() => {
    elements.documentFindQuery.focus();
    elements.documentFindQuery.select();
  });
  return true;
};

const moveCurrentDocumentFindMatch = (direction) => {
  const matches = currentDocumentFindMatches();
  ui.documentFind.currentIndex = nextTextMatchIndex({ currentIndex: ui.documentFind.currentIndex, matchCount: matches.length, direction });
  renderDocumentFindPanel({ scroll: true });
};

const applyDocumentFindReplacement = (range, replacement) => {
  if (!range || !activeEditableDocument()) return false;
  elements.editor.focus({ preventScroll: true });
  const selection = window.getSelection();
  selection?.removeAllRanges();
  selection?.addRange(range);
  const before = serializableEditorHtml();
  let executed = false;
  try {
    executed = Boolean(document.execCommand?.("insertText", false, replacement));
  } catch {
    executed = false;
  }
  if (!executed) {
    range.deleteContents();
    const inserted = document.createTextNode(replacement);
    range.insertNode(inserted);
    inserted.parentNode?.normalize();
  }
  const after = serializableEditorHtml();
  if (after === before) return false;
  if (state.documents[state.activeDocument]?.html !== after) {
    elements.editor.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement || null }));
  }
  return true;
};

const replaceCurrentDocumentFindMatch = () => {
  const matches = currentDocumentFindMatches();
  const range = matches[ui.documentFind.currentIndex];
  if (!range || !activeEditableDocument()) return false;
  ui.documentFind.mutating = true;
  const replaced = applyDocumentFindReplacement(range.cloneRange(), ui.documentFind.replacement);
  ui.documentFind.mutating = false;
  renderDocumentFindPanel({ scroll: true });
  return replaced;
};

const replaceAllCurrentDocumentFindMatches = () => {
  const matches = currentDocumentFindMatches();
  if (!matches.length || !activeEditableDocument()) return false;
  ui.documentFind.mutating = true;
  let replaced = 0;
  for (const range of [...matches].reverse()) {
    if (applyDocumentFindReplacement(range.cloneRange(), ui.documentFind.replacement)) replaced += 1;
  }
  ui.documentFind.mutating = false;
  ui.documentFind.currentIndex = 0;
  renderDocumentFindPanel({ scroll: true });
  showToast(`当前文档已替换 ${replaced} 处`);
  return replaced > 0;
};

const trashEntryTitle = (entry) => entry.title ?? entry.document?.title ?? entry.id;
const displayTrashDocumentTitle = ({ title, documentId = "", documentState = {} }) => localizeSystemDocumentTitle({
  title,
  language: documentState.titleLanguage ?? state.structureLanguage,
  moduleId: documentState.moduleId ?? "",
  viewId: documentState.workspaceView ?? "novel",
  documentId,
  documentKind: documentState.documentKind ?? "",
  systemGenerated: documentState.systemGeneratedTitle,
});
const displayTrashEntryTitle = (entry) => displayTrashDocumentTitle({
  title: trashEntryTitle(entry),
  documentId: entry.id ?? entry.document?.id ?? "",
  documentState: entry.document ?? entry.documents?.[entry.id] ?? {},
});
const trashDate = (entry) => new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(entry.deletedAtIso));
const trashMeta = (entry) => `${trashDate(entry)}删除 · ${daysUntilTrashExpiry(entry)}天后永久删除`;
const allTrashEntries = () => [...(state.trash ?? []), ...(ui.workspaceTrash ?? []), ...(ui.skillTrash ?? []), ...(globalUiPreferences.customThemeTrash ?? [])]
  .sort((left, right) => Date.parse(right.deletedAtIso || "") - Date.parse(left.deletedAtIso || ""));
const trashEntryById = (trashId) => allTrashEntries().find((item) => item.trashId === trashId || item.id === trashId);

const refreshSkillTrash = async () => {
  try {
    const response = await fetch("/api/skills/trash", { cache: "no-store" });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 回收站读取失败");
    ui.skillTrash = payload.items ?? [];
  } catch {
    ui.skillTrash ??= [];
  }
  renderTrashButton();
  return ui.skillTrash;
};

const refreshWorkspaceTrash = async () => {
  try {
    const response = await fetch("/api/workspaces/trash", { cache: "no-store" });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "作品与笔记本回收站读取失败");
    ui.workspaceTrash = Array.isArray(payload.items) ? payload.items : [];
  } catch (error) {
    ui.workspaceTrash ??= [];
    if (elements.trashDialog.open) showToast(error.message || "作品与笔记本回收站读取失败");
  }
  renderTrashButton();
  return ui.workspaceTrash;
};

const trashTreeNodes = (entry) => {
  if (Array.isArray(entry.structure) && entry.structure.length) {
    const [rootNode] = entry.structure;
    if (entry.structure.length === 1 && rootNode.type === "folder" && rootNode.title === trashEntryTitle(entry)) return rootNode.children ?? [];
    return entry.structure;
  }
  const documents = entry.documents ?? {};
  const used = new Set();
  const nodes = Object.entries(entry.moduleItems ?? {}).map(([moduleId, items]) => {
    const module = MODULES.find((item) => item.id === moduleId);
    const children = (items ?? []).filter(([id]) => documents[id]).map(([id, label]) => {
      used.add(id);
      return { id, type: "file", title: documents[id]?.title ?? label };
    });
    return { id: `module-${moduleId}`, type: "folder", title: module?.label ?? moduleId, children };
  }).filter((node) => node.children.length);
  const ungrouped = Object.entries(documents).filter(([id]) => !used.has(id)).map(([id, documentState]) => ({ id, type: "file", title: documentState.title ?? id }));
  if (ungrouped.length) nodes.push({ id: "ungrouped", type: "folder", title: "其他文档", children: ungrouped });
  return nodes;
};

const renderTrashTreeNode = (node, entry, path = "root", depth = 0) => {
  const children = Array.isArray(node.children) ? node.children : [];
  const folder = node.type === "folder" || children.length > 0;
  const key = `${entry.trashId}:${path}/${node.id ?? node.title}`;
  const expanded = ui.trashExpanded.has(key);
  if (!folder) {
    const documentState = entry.documents?.[node.id] ?? (entry.id === node.id ? entry.document : {}) ?? {};
    const title = displayTrashDocumentTitle({ title: node.title ?? node.label ?? "未命名文件", documentId: node.id ?? "", documentState });
    return `<button class="trash-tree-node file" style="--trash-depth:${depth}" type="button" data-trash-preview="${escapeHtml(entry.trashId)}" data-trash-document="${escapeHtml(node.id ?? "")}">${icon("\uE8A5")}<span>${escapeHtml(title)}</span></button>`;
  }
  return `<div class="trash-tree-branch">
    <button class="trash-tree-node folder" style="--trash-depth:${depth}" type="button" data-trash-toggle="${escapeHtml(key)}" aria-expanded="${expanded}">${icon(expanded ? "\uE70D" : "\uE76C")} ${icon("\uE8B7")}<span>${escapeHtml(node.title ?? node.label ?? "未命名文件夹")}</span></button>
    <div class="trash-tree-children" ${expanded ? "" : "hidden"}>${children.map((child, index) => renderTrashTreeNode(child, entry, `${path}/${node.id ?? index}`, depth + 1)).join("")}</div>
  </div>`;
};

const trashActions = (entry) => `<span class="trash-entry-actions">
  <button class="icon-button bare small" type="button" data-trash-restore="${escapeHtml(entry.trashId)}" title="恢复">${icon("\uE777", "恢复")}</button>
  <button class="icon-button bare small" type="button" data-trash-permanent="${escapeHtml(entry.trashId)}" title="永久删除">${icon("\uE74D", "永久删除")}</button>
</span>`;

const renderTrashEntry = (entry) => {
  if (["workspace-project", "workspace-notebook"].includes(entry.kind)) {
    const notebook = entry.kind === "workspace-notebook";
    return `<article class="trash-entry workspace ${notebook ? "notebook" : "project"}">
      <div class="trash-entry-row"><span class="trash-entry-main">${icon(notebook ? "\uE8A5" : "\uE8B7")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>${notebook ? "整个笔记本" : "整个作品"} · ${escapeHtml(trashMeta(entry))}</small><small>恢复时不会覆盖已有同名内容</small></span></span>${trashActions(entry)}</div>
    </article>`;
  }
  if (entry.kind === "conversation") return `<article class="trash-entry conversation">
    <div class="trash-entry-row"><span class="trash-entry-main">${icon("\uE8F2")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>对话 · ${escapeHtml(trashMeta(entry))}</small></span></span>${trashActions(entry)}</div>
  </article>`;
  if (entry.kind === "skill") return `<article class="trash-entry skill">
    <div class="trash-entry-row"><span class="trash-entry-main">${icon("\uE943")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>Skill · v${escapeHtml(entry.activeVersion || "-")} · ${escapeHtml(trashMeta(entry))}</small><small>${escapeHtml(entry.recoveryHint || "永久清理后无法恢复")}</small></span></span>${trashActions(entry)}</div>
  </article>`;
  if (entry.kind === "custom-theme") return `<article class="trash-entry custom-theme">
    <div class="trash-entry-row"><span class="trash-entry-main">${icon("\uE790")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>自定义主题 · v${escapeHtml(entry.theme?.version || "1")} · ${escapeHtml(trashMeta(entry))}</small><small>包含 ${Number(entry.history?.length) || 1} 个历史版本</small></span></span>${trashActions(entry)}</div>
  </article>`;
  if (entry.kind === "file") return `<article class="trash-entry file">
    <div class="trash-entry-row"><button class="trash-entry-main" type="button" data-trash-preview="${escapeHtml(entry.trashId)}" data-trash-document="${escapeHtml(entry.id)}">${icon("\uE8A5")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>${escapeHtml(trashMeta(entry))}</small></span></button>${trashActions(entry)}</div>
  </article>`;
  if (entry.kind === "history-version") return `<article class="trash-entry file history-version">
    <div class="trash-entry-row"><span class="trash-entry-main">${icon("\uE81C")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>历史版本 · ${escapeHtml(trashMeta(entry))}</small></span></span>${trashActions(entry)}</div>
  </article>`;
  const rootKey = `${entry.trashId}:root`;
  const expanded = ui.trashExpanded.has(rootKey);
  const nodes = trashTreeNodes(entry);
  return `<article class="trash-entry tree">
    <div class="trash-entry-row"><button class="trash-entry-main" type="button" data-trash-toggle="${escapeHtml(rootKey)}" aria-expanded="${expanded}">${icon(expanded ? "\uE70D" : "\uE76C")} ${icon("\uE8B7")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>${escapeHtml(trashMeta(entry))}</small></span></button>${trashActions(entry)}</div>
    <div class="trash-entry-tree" ${expanded ? "" : "hidden"}>${nodes.map((node, index) => renderTrashTreeNode(node, entry, `root-${index}`, 0)).join("")}</div>
  </article>`;
};

const renderTrashButton = () => {
  const count = (workspaceHasNoActiveEntry() ? 0 : state.trash?.length ?? 0) + (ui.workspaceTrash?.length ?? 0) + (ui.skillTrash?.length ?? 0) + (globalUiPreferences.customThemeTrash?.length ?? 0);
  const badge = document.querySelector("#trashCount");
  badge.hidden = count === 0;
  badge.textContent = count > 99 ? "99+" : String(count);
  document.querySelector("#trashButton").title = count ? `回收站，${count}项` : "回收站";
};

const renderTrashDialog = () => {
  const trash = allTrashEntries();
  elements.trashDialogList.innerHTML = trash.map(renderTrashEntry).join("") || `<div class="trash-dialog-empty">${icon("\uE74D")}<strong>回收站为空</strong></div>`;
  document.querySelector("#trashDialogSummary").textContent = `${trash.length} 项`;
  const clearButton = document.querySelector("#clearTrashButton");
  const clearLabel = clearButton.querySelector("span:last-child");
  clearButton.disabled = !trash.length || ui.trashClearing;
  clearButton.title = uiText(trash.length ? "永久清空回收站" : "回收站为空");
  clearLabel.textContent = uiText(ui.trashClearing ? "正在清空…" : "清空回收站");
  renderTrashButton();
};

const openTrashDialog = async () => {
  const expiredCount = pruneStateTrash();
  const themeRetention = pruneCustomThemeTrashEntries(globalUiPreferences.customThemeTrash);
  globalUiPreferences.customThemeTrash = themeRetention.active;
  if (expiredCount) {
    updateTrashIndexDocument();
    persist();
  }
  if (themeRetention.expired.length) {
    state.settings.customThemeTrash = themeRetention.active;
    persistUiPreferences();
    persist();
  }
  await Promise.all([refreshSkillTrash(), refreshWorkspaceTrash()]);
  if (!elements.trashDialog.open) ui.trashExpanded = new Set();
  renderTrashDialog();
  if (!elements.trashDialog.open) elements.trashDialog.showModal();
};

const closeTrashDialog = () => {
  if (elements.trashDialog.open) elements.trashDialog.close();
};

const renderTrashPreview = () => {
  const preview = ui.trashPreview;
  const entry = preview ? state.trash.find((item) => item.trashId === preview.trashId) : null;
  const payload = entry ? trashPreviewDocument(entry, preview.documentId) : null;
  if (!entry || !payload) return false;
  const documentState = payload.document ?? {};
  const content = documentState.html ?? documentState.markdown ?? "";
  document.querySelector("#trashPreviewTitle").textContent = displayTrashDocumentTitle({ title: documentState.title ?? trashEntryTitle(entry), documentId: preview.documentId ?? entry.id ?? "", documentState });
  document.querySelector("#trashPreviewMeta").textContent = trashMeta(entry);
  document.querySelector("#trashPreviewSummary").textContent = `${stripHtml(content).length.toLocaleString("zh-CN")} 字 · 只读预览`;
  elements.trashPreviewBody.innerHTML = previewDocumentHtml(documentState);
  return true;
};

const openTrashPreview = (trashId, documentId) => {
  ui.trashPreview = { trashId, documentId };
  if (!renderTrashPreview()) {
    ui.trashPreview = null;
    showToast("这个回收项没有可预览的文档内容");
    return;
  }
  if (!elements.trashPreviewDialog.open) elements.trashPreviewDialog.showModal();
};

const closeTrashPreview = () => {
  if (elements.trashPreviewDialog.open) elements.trashPreviewDialog.close();
  ui.trashPreview = null;
};

const updateTrashIndexDocument = () => {
  state.moduleItems.library = (state.moduleItems.library ?? []).filter(([documentId]) => documentId !== "library-trash");
  delete state.documents["library-trash"];
};

const selectionToolbarLeft = (selectionRect, canvasRect) => {
  const toolbarWidth = Math.min(elements.selectionToolbar.offsetWidth || 390, Math.max(260, canvasRect.width - 32));
  const maximumLeft = Math.max(16, canvasRect.width - toolbarWidth - 16);
  const minimumLeft = ui.historyScope ? Math.min(315, maximumLeft) : 16;
  return Math.max(minimumLeft, Math.min(selectionRect.left - canvasRect.left, maximumLeft));
};

const selectionToolbarAnchorRect = (range) => {
  const canvasRect = elements.editorCanvas.getBoundingClientRect();
  const visibleRects = Array.from(range?.getClientRects?.() ?? [])
    .filter((rect) => rect.width || rect.height)
    .filter((rect) => rect.bottom >= canvasRect.top && rect.top <= canvasRect.bottom);
  return visibleRects.at(-1) ?? range?.getBoundingClientRect?.() ?? canvasRect;
};

const positionSelectionToolbar = (rect) => {
  const canvasRect = elements.editorCanvas.getBoundingClientRect();
  elements.selectionToolbar.hidden = false;
  const toolbarHeight = Math.max(42, elements.selectionToolbar.offsetHeight || 42);
  const visibleBottom = Math.max(canvasRect.top + 16, Math.min(rect.bottom, canvasRect.bottom - toolbarHeight - 16));
  elements.selectionToolbar.style.left = `${selectionToolbarLeft(rect, canvasRect)}px`;
  elements.selectionToolbar.style.top = `${visibleBottom - canvasRect.top + elements.editorCanvas.scrollTop + 10}px`;
};

const clearSelectionHighlight = () => {
  if (typeof CSS !== "undefined" && CSS.highlights) CSS.highlights.delete("shensi-selection");
};

const rememberSelectionRange = (range, { highlight = true } = {}) => {
  ui.selectionRange = range.cloneRange();
  if (highlight && typeof CSS !== "undefined" && CSS.highlights && typeof Highlight !== "undefined") {
    CSS.highlights.set("shensi-selection", new Highlight(ui.selectionRange));
  } else {
    clearSelectionHighlight();
  }
};

const restoreSelectionRange = () => {
  if (!ui.selectionRange || !elements.editor.contains(ui.selectionRange.commonAncestorContainer)) return false;
  const selection = window.getSelection();
  selection.removeAllRanges();
  selection.addRange(ui.selectionRange);
  return true;
};

const setSelectionStyleMenu = (open) => {
  ui.selectionStyleMenuOpen = open;
  elements.selectionStyleMenu.hidden = !open;
  elements.selectionStyleButton.setAttribute("aria-expanded", String(open));
};

const setSelectionEditMode = (active, { focus = false } = {}) => {
  ui.selectionEditMode = active;
  setSelectionStyleMenu(false);
  elements.selectionCommandRow.hidden = active;
  elements.selectionEditForm.hidden = !active;
  if (active && focus) requestAnimationFrame(() => elements.selectionEditInput.focus());
};

const hideSelectionToolbar = () => {
  elements.selectionToolbar.hidden = true;
  setSelectionEditMode(false);
  ui.selectionMutationMode = "";
  elements.selectionEditInput.placeholder = "描述更改";
  elements.selectionEditInput.setAttribute("aria-label", "描述更改");
  ui.selectionRange = null;
  clearSelectionHighlight();
};

const renderTrashManager = () => {
  const trash = state.trash ?? [];
  elements.editor.innerHTML = `<div class="trash-manager">${trash.map((entry) => `
    <div class="trash-row">
      <span>${icon(entry.kind === "tree" ? "\uE8B7" : entry.kind === "conversation" ? "\uE8F2" : entry.kind === "history-version" ? "\uE81C" : "\uE8A5")}<span><strong>${escapeHtml(displayTrashEntryTitle(entry))}</strong><small>${entry.kind === "conversation" ? "对话 · " : entry.kind === "history-version" ? "历史版本 · " : ""}${escapeHtml(trashMeta(entry))}</small></span></span>
      <button type="button" data-restore-trash="${escapeHtml(entry.trashId)}">恢复</button>
    </div>`).join("") || `<p class="trash-empty">当前没有已删除内容</p>`}</div>`;
  elements.editor.dataset.document = "library-trash";
  elements.editor.contentEditable = "false";
  elements.wordCount.textContent = `${trash.length} 项`;
};

const whiteboardNodeSidePoint = (node, side = "right") => {
  if (side === "left") return { x: node.x, y: node.y + node.height / 2 };
  if (side === "top") return { x: node.x + node.width / 2, y: node.y };
  if (side === "bottom") return { x: node.x + node.width / 2, y: node.y + node.height };
  return { x: node.x + node.width, y: node.y + node.height / 2 };
};

const whiteboardEdgePath = (from, to) => {
  const distance = Math.max(70, Math.abs(to.x - from.x) * 0.45);
  return `M ${from.x} ${from.y} C ${from.x + distance} ${from.y}, ${to.x - distance} ${to.y}, ${to.x} ${to.y}`;
};

const whiteboardNodeKindLabel = (node) => ({
  reference: "引用文档",
  skill: "Skill",
  image: "图片",
  video: "视频",
  audio: "音频",
  web: "网页",
  group: "组",
}[node.kind] ?? "");

const generatedWhiteboardNodeBaseName = (kind = "text") => ({
  image: "图片节点",
  video: "视频节点",
  audio: "音频节点",
}[kind] || "文本节点");

const generatedWhiteboardNodeNames = (canvas, kind, count = 1, existingName = "") => {
  const base = generatedWhiteboardNodeBaseName(kind);
  const pattern = new RegExp(`^${base}\\s*(\\d+)(?:-副本\\s*(\\d+))?$`, "u");
  const existingMatch = String(existingName || "").trim().match(pattern);
  let sequence = normalizeCanvas(canvas).nodes.reduce((maximum, node) => {
    const match = String(node.name || "").trim().match(pattern);
    return Math.max(maximum, Number(match?.[1]) || 0);
  }, 0);
  const names = [];
  if (existingMatch) names.push(`${base} ${Number(existingMatch[1])}${existingMatch[2] ? `-副本${Number(existingMatch[2])}` : ""}`);
  while (names.length < Math.max(1, Number(count) || 1)) names.push(`${base} ${++sequence}`);
  return names;
};

const normalizeWhiteboardUrl = (value = "") => {
  const source = String(value).trim();
  if (!source) return "";
  try {
    const parsed = new URL(/^[a-z][a-z\d+.-]*:\/\//i.test(source) ? source : `https://${source}`);
    return ["http:", "https:"].includes(parsed.protocol) ? parsed.href : "";
  } catch {
    return "";
  }
};

const whiteboardWebTitle = (node) => {
  const captured = String(node?.webSnapshot?.title ?? "").trim();
  if (captured) return captured;
  const custom = String(node?.text ?? "").trim().split(/\r?\n/)[0];
  if (custom) return custom;
  try {
    return new URL(node?.url || "").hostname || "网页";
  } catch {
    return "网页";
  }
};

const whiteboardWebSourceText = (node) => {
  const snapshot = node?.webSnapshot;
  const text = String(snapshot?.text || "").trim();
  if (!text) return `[网页：${whiteboardWebTitle(node)}]\n来源：${node?.url || ""}\n（尚未读取网页正文）`;
  return `[网页：${whiteboardWebTitle(node)}]\n来源：${snapshot.sourceUrl || node?.url || ""}\n\n${text}`;
};

const readWhiteboardWebSnapshot = async (url) => {
  const response = await fetch("/api/whiteboard/web-content", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ url }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload.ok || !payload.snapshot?.text) throw new Error(payload.message || "网页正文读取失败");
  return payload.snapshot;
};

const workspaceAttachmentUrl = (relativePath, documentId = state.activeDocument, { downloadName = "", workspacePath = state.settings.workspacePath } = {}) => {
  const query = new URLSearchParams({
    workspacePath,
    relativePath: String(relativePath || ""),
    documentId: String(documentId || ""),
    shensiSession: SHENSI_SESSION_TOKEN,
  });
  if (downloadName) query.set("downloadName", downloadName);
  return `/api/workspace/attachment-content?${query}`;
};

const hydrateWorkspaceAttachmentMedia = (root = elements.editor) => {
  root?.querySelectorAll?.("img[data-attachment-path], video[data-attachment-path], audio[data-attachment-path]").forEach((media) => {
    const relativePath = String(media.dataset.attachmentPath || "").trim();
    if (!relativePath) return;
    const source = workspaceAttachmentUrl(relativePath);
    if (media.getAttribute("src") !== source) media.setAttribute("src", source);
  });
};

const attachmentPreviewMarkup = (attachment, className) => {
  if (!attachment?.relativePath) return "";
  const source = escapeHtml(workspaceAttachmentUrl(attachment.relativePath));
  const name = escapeHtml(attachment.name || "附件");
  const relativePath = escapeHtml(attachment.relativePath);
  if (attachment.mimeType?.startsWith("image/")) {
    return `<span class="${className}" data-attachment-preview="image" data-attachment-path="${relativePath}" title="${name}"><img src="${source}" alt="${name}" loading="lazy" /></span>`;
  }
  if (attachment.mimeType?.startsWith("video/")) {
    const frameButton = className === "message-attachment-preview"
      ? `<button class="video-frame-trigger message-video-frame-trigger" type="button" data-video-frame-trigger data-frame-destination="conversation" data-attachment-path="${relativePath}" title="提取关键帧" aria-label="提取关键帧">${icon("\uE722", "提取关键帧")}</button>`
      : "";
    return `<span class="${className}" data-attachment-preview="video" data-attachment-path="${relativePath}" title="${name}"><video src="${source}" aria-label="${name}" muted playsinline preload="metadata"></video><span class="attachment-video-play" aria-hidden="true">${icon("\uE768")}</span>${frameButton}</span>`;
  }
  return "";
};

const attachmentIcon = (attachment) => icon(attachment.mimeType?.startsWith("video/")
  ? "\uE714"
  : attachment.mimeType?.startsWith("audio/") ? "\uE8D6"
  : attachment.mimeType?.startsWith("image/") ? "\uEB9F" : attachment.referenceType === "book" ? "\uE82D" : "\uE723");

const messageAttachmentMarkup = (attachment, { sent = false } = {}) => {
  const preview = attachmentPreviewMarkup(attachment, "message-attachment-preview");
  const title = sent ? ' title="已随本条消息发送"' : "";
  if (!preview) {
    const label = attachment.referenceType === "book" ? `@${attachment.bookTitle || attachment.name}` : attachment.name;
    return `<span class="message-resource attachment${attachment.referenceType === "book" ? " book-reference" : ""}"${title}>${attachmentIcon(attachment)}<span>${escapeHtml(label)}</span></span>`;
  }
  return `<span class="message-resource attachment visual-attachment"${title}>${preview}</span>`;
};

const composerAttachmentMarkup = (attachment) => {
  const preview = attachmentPreviewMarkup(attachment, "context-attachment-preview");
  if (preview) {
    return `<span class="context-chip attachment-chip visual-attachment-chip">${preview}<button type="button" data-remove-attachment="${escapeHtml(attachment.id)}" title="移除附件" aria-label="移除附件">${icon("\uE711", "移除附件")}</button></span>`;
  }
  const label = attachment.referenceType === "book" ? `@${attachment.bookTitle || attachment.name}` : attachment.name;
  const detail = attachment.referenceType === "book"
    ? `${attachment.sourceName || "全本小说网"} · 已读取 ${Number(attachment.coverage?.successfulChapterCount) || 0} / ${Number(attachment.coverage?.requestedChapterCount) || 0} 章`
    : attachment.name;
  return `<span class="context-chip attachment-chip${attachment.referenceType === "book" ? " book-reference-chip" : ""}">${attachmentIcon(attachment)}<span title="${escapeHtml(detail)}">${escapeHtml(label)}</span><button type="button" data-remove-attachment="${escapeHtml(attachment.id)}" title="移除附件">${icon("\uE711", "移除附件")}</button></span>`;
};

const whiteboardAttachmentUrl = (node) => workspaceAttachmentUrl(node.file, state.activeDocument, {
  downloadName: mediaDownloadFileName({
    kind: node.kind,
    nodeName: node.generation ? node.name : "",
    prompt: node.generation?.prompt,
    name: node.name,
    relativePath: node.file,
    mimeType: node.mimeType,
  }),
});

const cleanDownloadFileName = (value, fallback = "白板卡片") => String(value || fallback)
  .replace(/[<>:"/\\|?*\u0000-\u001f]/g, " ")
  .replace(/\s+/g, " ")
  .replace(/[. ]+$/g, "")
  .trim()
  .slice(0, 100) || fallback;

const responseDownloadFileName = (response, fallback) => {
  const disposition = response.headers.get("Content-Disposition") || "";
  const encoded = disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];
  if (!encoded) return fallback;
  try {
    return decodeURIComponent(encoded);
  } catch {
    return fallback;
  }
};

const saveBlobLocally = async ({ blob, fileName, mimeType, extension, types = [], prepareBlob = null }) => {
  const nativeBinarySaver = window.shensiDesktop?.file?.saveBinary;
  if (typeof nativeBinarySaver === "function" && typeof prepareBlob !== "function") {
    const saved = await nativeBinarySaver({
      bytes: new Uint8Array(await blob.arrayBuffer()),
      suggestedName: fileName,
      mimeType: mimeType || blob.type || "application/octet-stream",
    });
    if (saved?.canceled) throw new DOMException("用户取消保存", "AbortError");
    if (!saved?.ok) throw new Error(saved?.message || "导出失败");
    return saved.fileName || fileName;
  }
  if (typeof window.showSaveFilePicker === "function") {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: fileName,
        types: types.length ? types : [{ description: extension === ".docx" ? "WPS/Word 文档" : extension === ".md" ? "Markdown 文档" : extension === ".zip" ? "导出文档包" : extension === ".skill" ? "完整 Skill 包" : extension === ".html" ? "白板分享网页" : "图片", accept: { [mimeType || blob.type || "application/octet-stream"]: [extension] } }],
        ...(types.length ? { excludeAcceptAllOption: true } : {}),
      });
      const outputBlob = typeof prepareBlob === "function" ? await prepareBlob({ blob, fileName: handle.name || fileName }) : blob;
      const writable = await handle.createWritable();
      await writable.write(outputBlob);
      await writable.close();
      return handle.name || fileName;
    } catch (error) {
      if (error?.name === "AbortError") throw error;
      console.warn("File System Access 保存失败，已回退为浏览器下载", error);
    }
  }
  const anchor = document.createElement("a");
  const url = URL.createObjectURL(blob);
  anchor.href = url;
  anchor.download = fileName;
  anchor.hidden = true;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return fileName;
};

const imageMimeForExtension = (extension = "") => ({
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
}[String(extension).toLowerCase()] || "");

const imageExtensionForMime = (mimeType = "") => ({
  "image/png": ".png",
  "image/jpeg": ".jpg",
  "image/webp": ".webp",
  "image/gif": ".gif",
  "image/avif": ".avif",
  "image/bmp": ".bmp",
}[String(mimeType).toLowerCase().split(";", 1)[0]] || ".png");

const fileNameExtension = (value = "") => String(value).match(/\.[a-z0-9]+$/i)?.[0]?.toLowerCase() || "";

const imageExportPickerTypes = ({ sourceMimeType = "image/png", sourceExtension = ".png" } = {}) => {
  const normalizedMimeType = String(sourceMimeType || "image/png").toLowerCase().split(";", 1)[0];
  const candidates = [
    { description: "原始图片格式", mimeType: normalizedMimeType, extension: sourceExtension || imageExtensionForMime(normalizedMimeType) },
    { description: "PNG 图片", mimeType: "image/png", extension: ".png" },
    { description: "JPG 图片", mimeType: "image/jpeg", extension: ".jpg" },
    { description: "WebP 图片", mimeType: "image/webp", extension: ".webp" },
  ];
  const seen = new Set();
  return candidates.filter((candidate) => {
    const extension = String(candidate.extension || "").toLowerCase();
    if (!extension || seen.has(extension)) return false;
    seen.add(extension);
    return true;
  }).map((candidate) => ({ description: candidate.description, accept: { [candidate.mimeType]: [candidate.extension] } }));
};

const transcodeImageBlob = async (blob, targetMimeType) => {
  const normalizedTarget = String(targetMimeType || "").toLowerCase();
  const sourceMimeType = String(blob.type || "").toLowerCase().split(";", 1)[0];
  if (!normalizedTarget || normalizedTarget === sourceMimeType) return blob;
  if (!["image/png", "image/jpeg", "image/webp"].includes(normalizedTarget)) throw new Error("所选图片格式暂不支持转码");
  let bitmap;
  let imageElement;
  try {
    try {
      bitmap = await createImageBitmap(blob);
    } catch {
      const dataUrl = await new Promise((resolveDataUrl, rejectDataUrl) => {
        const reader = new FileReader();
        reader.addEventListener("load", () => resolveDataUrl(String(reader.result || "")), { once: true });
        reader.addEventListener("error", () => rejectDataUrl(reader.error || new Error("原图片读取失败")), { once: true });
        reader.readAsDataURL(blob);
      });
      imageElement = new Image();
      imageElement.decoding = "async";
      await new Promise((resolveImage, rejectImage) => {
        imageElement.addEventListener("load", resolveImage, { once: true });
        imageElement.addEventListener("error", () => rejectImage(new Error("原图片无法解码")), { once: true });
        imageElement.src = dataUrl;
      });
    }
    const source = bitmap || imageElement;
    const width = Number(bitmap?.width || imageElement?.naturalWidth || 0);
    const height = Number(bitmap?.height || imageElement?.naturalHeight || 0);
    if (!width || !height) throw new Error("图片尺寸无效");
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d", { alpha: normalizedTarget !== "image/jpeg" });
    if (!context) throw new Error("浏览器无法建立图片转码画布");
    if (normalizedTarget === "image/jpeg") {
      context.fillStyle = "#ffffff";
      context.fillRect(0, 0, canvas.width, canvas.height);
    }
    context.drawImage(source, 0, 0);
    const converted = await new Promise((resolve) => canvas.toBlob(resolve, normalizedTarget, normalizedTarget === "image/png" ? undefined : 0.92));
    if (!converted) throw new Error("图片转码失败");
    return converted;
  } finally {
    bitmap?.close?.();
  }
};

const exportDocumentMarkdown = (documentState = {}) => preferredDocumentExportMarkdown({
  title: documentState.title,
  markdown: documentState.markdown,
  htmlMarkdown: htmlToMarkdown(documentState.html ?? ""),
});

const exportDocumentText = (documentState = {}) => {
  const editorText = documentTextFromHtml(documentState.html ?? "").trim();
  if (editorText) return editorText;
  return exportDocumentMarkdown(documentState)
    .replace(/!\[([^\]]*)\]\([^)]+\)/gu, "$1")
    .replace(/\[([^\]]+)\]\([^)]+\)/gu, "$1")
    .replace(/^\s{0,3}#{1,6}\s+/gmu, "")
    .replace(/^\s*[-+*>]\s+/gmu, "")
    .replace(/[`*_~|]/gu, "")
    .trim();
};

const directoryDocumentIdsForTokens = (tokens, { moduleId = state.activeModule, viewId = activeViewForModule(moduleId) } = {}) => {
  const tree = buildDocumentTree({
    moduleId,
    viewId,
    items: itemsForModuleView(moduleId, viewId),
    documents: state.documents,
    folders: state.customFolders,
    workspaceKind: state.workspaceKind,
  });
  return directoryDeletionDocumentIds({
    tokens,
    documents: state.documents,
    directoryItemIds: Object.values(state.moduleItems).flat().map(([id]) => id),
    tree,
  });
};

const documentsForScope = (scope) => {
  if (!scope) return {};
  if (scope.type === "document") return state.documents[scope.id] ? { [scope.id]: clone(state.documents[scope.id]) } : {};
  if (scope.type === "selection") return Object.fromEntries((scope.documentIds ?? []).filter((id) => state.documents[id]).map((id) => [id, clone(state.documents[id])]));
  if (scope.type === "volume") return volumeDocuments(scope);
  if (scope.type === "view") {
    const { moduleId, viewId } = viewScopeDetails(scope);
    return viewDocuments(moduleId, viewId);
  }
  if (scope.type === "module") return moduleDocuments(scope.id);
  return Object.fromEntries(Object.entries(state.documents).filter(([id, documentState]) => id !== "library-trash" && !documentState?.virtual).map(([id, documentState]) => [id, clone(documentState)]));
};

const exportScopeLabel = (scope) => {
  if (!scope || scope.type === "project") return state.projectName || "未命名作品";
  if (scope.type === "document") return state.documents[scope.id]?.title || "未命名文档";
  if (scope.type === "selection") return `已选 ${scope.itemCount ?? scope.documentIds?.length ?? 0} 项`;
  if (scope.type === "volume") return volumeLabel(scope);
  if (scope.type === "view") {
    const { moduleId, viewId } = viewScopeDetails(scope);
    return moduleView(moduleId, viewId)?.label || "分类";
  }
  return MODULES.find((item) => item.id === scope.id)?.label || "板块";
};

const exportDocumentPath = (documentId, scope) => {
  const documentState = state.documents[documentId] ?? {};
  const located = documentItem(documentId);
  const moduleId = located?.moduleId ?? documentState.moduleId ?? "library";
  const options = located?.item?.[2] ?? {};
  const viewId = itemWorkspaceView(moduleId, located?.item);
  const moduleLabel = MODULES.find((item) => item.id === moduleId)?.label ?? moduleId;
  const viewLabel = moduleView(moduleId, viewId)?.label;
  const folderPath = documentState.customFolderPath || options.customFolderPath || options.customFolderLabel || options.folderLabel || "";
  const parts = scope?.type === "document" ? [] : [moduleLabel, viewLabel && viewLabel !== moduleLabel ? viewLabel : "", ...String(folderPath).split(/[\\/]+/)];
  return [...parts.filter(Boolean), documentState.title || documentId].join("/");
};

const exportScopeModuleView = (scope) => {
  if (scope?.type === "document") {
    const located = documentItem(scope.id);
    return located ? { moduleId: located.moduleId, viewId: itemWorkspaceView(located.moduleId, located.item) } : { moduleId: "workspace", viewId: "all" };
  }
  if (scope?.type === "volume") return volumeScopeDetails(scope);
  if (scope?.type === "view") return viewScopeDetails(scope);
  if (scope?.moduleId || scope?.viewId) return { moduleId: scope.moduleId || state.activeModule, viewId: scope.viewId || activeViewForModule(scope.moduleId || state.activeModule) };
  if (scope?.type === "module") return { moduleId: scope.id, viewId: activeViewForModule(scope.id) };
  return { moduleId: "workspace", viewId: "all" };
};

const orderedExportDocumentIds = (scope) => {
  const allowed = new Set(Object.keys(documentsForScope(scope)));
  if (scope?.type === "document") return allowed.has(scope.id) ? [scope.id] : [];
  const ordered = [];
  const append = (documentId) => {
    if (allowed.has(documentId) && !ordered.includes(documentId)) ordered.push(documentId);
  };
  if (scope?.type === "volume") volumeTreeNodes(scope).filter((node) => node.type === "document").forEach((node) => append(node.id));
  else {
    const { moduleId, viewId } = exportScopeModuleView(scope);
    if (moduleId !== "workspace") {
      const tree = buildDocumentTree({
        moduleId,
        viewId,
        items: itemsForModuleView(moduleId, viewId),
        documents: state.documents,
        folders: state.customFolders,
        workspaceKind: state.workspaceKind,
      });
      const visit = (nodes) => nodes.forEach((node) => {
        if (node.type === "document") append(node.id);
        else visit(node.children ?? []);
      });
      visit(tree);
    }
  }
  allowed.forEach(append);
  return ordered;
};

const exportScopeManifest = (scope) => {
  const { moduleId, viewId } = exportScopeModuleView(scope);
  return buildDocumentExportManifest({
    state,
    moduleId,
    viewId,
    documentIds: orderedExportDocumentIds(scope),
    scopeLabel: exportScopeLabel(scope),
    textForDocument: exportDocumentText,
    markdownForDocument: exportDocumentMarkdown,
    pathForDocument: (documentId) => exportDocumentPath(documentId, scope),
  });
};

const manuscriptDirectoryExportScope = (scope) => {
  if (!scope || scope.type === "document") return false;
  const { moduleId, viewId } = exportScopeModuleView(scope);
  return moduleId === "manuscript" && ["novel", "script"].includes(viewId);
};

const EXPORT_FORMAT_LABELS = Object.freeze({
  docx: "WPS / Word",
  pdf: "PDF",
  markdown: "Markdown",
  text: "纯文本",
  screenplay: "剧本格式",
  epub: "电子书",
});

const EXPORT_FORMAT_EXTENSIONS = Object.freeze({
  docx: ".docx",
  pdf: ".pdf",
  markdown: ".md",
  text: ".txt",
  screenplay: ".docx",
  epub: ".epub",
});

const exportScope = async (scope, format = "docx", requestedMode = "") => {
  const manifest = exportScopeManifest(scope);
  if (!manifest.documentCount) throw new Error("这个层级没有可导出的文档");
  const mode = requestedMode || (scope?.type === "document" ? "complete" : "separate");
  const response = await fetch("/api/export/documents", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title: exportScopeLabel(scope),
      mode,
      format,
      documents: manifest.documents,
      documentCount: manifest.documentCount,
      manifestHash: manifest.manifestHash,
    }),
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(payload.message || "导出失败");
  }
  const actualMode = response.headers.get("x-shensi-export-mode");
  const actualFormat = response.headers.get("x-shensi-export-format");
  const actualFileCount = Number(response.headers.get("x-shensi-export-file-count"));
  const actualDocumentCount = Number(response.headers.get("x-shensi-export-document-count"));
  const expectedFileCount = mode === "complete" ? 1 : manifest.documentCount;
  if (actualMode !== mode || actualFormat !== format || actualFileCount !== expectedFileCount || actualDocumentCount !== manifest.documentCount) {
    throw new Error("服务端导出结果与当前清单不一致，已停止保存文件");
  }
  const responseName = responseDownloadFileName(response, "");
  const extension = responseName.match(/\.[a-z\d]{1,8}$/iu)?.[0]?.toLocaleLowerCase()
    || (mode === "separate" && manifest.documentCount > 1 ? ".zip" : EXPORT_FORMAT_EXTENSIONS[format]);
  const mimeType = response.headers.get("content-type") || "application/octet-stream";
  const fallback = `${cleanDownloadFileName(exportScopeLabel(scope), "神思导出")}${extension}`;
  await saveBlobLocally({ blob: await response.blob(), fileName: responseDownloadFileName(response, fallback), mimeType, extension });
  const formatLabel = EXPORT_FORMAT_LABELS[format] || format;
  showToast(mode === "complete"
    ? `${manifest.documentCount} 篇文档已合并导出为 1 个${formatLabel}文件`
    : `已分别导出 ${manifest.documentCount} 篇${formatLabel}文档`);
};

const openExportDialog = (scope) => {
  if (scope?.type === "document" && state.documents[scope.id]?.documentKind === "whiteboard") {
    showToast("白板不导出为 WPS/Word 或 Markdown；请使用“分享”生成可预览白板文件");
    return;
  }
  ui.exportScope = scope;
  const manifest = exportScopeManifest(scope);
  const count = manifest.documentCount;
  if (!count) {
    ui.exportScope = null;
    showToast("这个层级没有可导出的正文文档");
    return;
  }
  const manuscriptDirectory = manuscriptDirectoryExportScope(scope);
  document.querySelector("#exportDialogTitle").textContent = `导出“${exportScopeLabel(scope)}”`;
  document.querySelector("#exportDialogSummary").textContent = manuscriptDirectory
    ? "选择分别导出或全本导出；两个板块支持相同格式。"
    : scope?.type === "document" ? "请选择 WPS / Word 或 Markdown 格式。" : `将导出 ${count} 篇文档；白板会自动跳过并使用独立分享格式。`;
  document.querySelector("#singleExportOptions").hidden = manuscriptDirectory;
  document.querySelector("#manuscriptExportOptions").hidden = !manuscriptDirectory;
  document.querySelector("#separateExportSummary").textContent = `目录共包含 ${count} 个可导出文档，本次将导出 ${count} 个独立文档。`;
  document.querySelector("#completeExportSummary").textContent = `目录共包含 ${count} 个可导出文档，本次将按目录顺序合并为 1 个全本文档。`;
  elements.exportDialog.showModal();
};

const blobDataUrl = (blob) => new Promise((resolveDataUrl, rejectDataUrl) => {
  const reader = new FileReader();
  reader.addEventListener("load", () => resolveDataUrl(String(reader.result || "")), { once: true });
  reader.addEventListener("error", () => rejectDataUrl(reader.error || new Error("媒体读取失败")), { once: true });
  reader.readAsDataURL(blob);
});

const whiteboardShareHtml = async (documentState = {}) => {
  const canvas = normalizeCanvas(documentState.canvas);
  const mediaSources = new Map();
  let embeddedBytes = 0;
  for (const node of canvas.nodes.filter((item) => ["image", "video", "audio"].includes(item.kind) && item.file)) {
    if (mediaSources.has(node.file)) continue;
    try {
      const response = await fetch(workspaceAttachmentUrl(node.file, state.activeDocument), { cache: "no-store" });
      if (!response.ok) continue;
      const blob = await response.blob();
      if (blob.size > 96 * 1024 * 1024 || embeddedBytes + blob.size > 256 * 1024 * 1024) continue;
      embeddedBytes += blob.size;
      mediaSources.set(node.file, await blobDataUrl(blob));
    } catch {
      // A missing media file must not prevent text, layout and the remaining
      // assets from being shared and previewed.
    }
  }
  const padding = 48;
  const minX = Math.min(0, ...canvas.nodes.map((node) => node.x));
  const minY = Math.min(0, ...canvas.nodes.map((node) => node.y));
  const maxX = Math.max(900, ...canvas.nodes.map((node) => node.x + node.width));
  const maxY = Math.max(600, ...canvas.nodes.map((node) => node.y + node.height));
  const offsetX = padding - minX;
  const offsetY = padding - minY;
  const width = Math.ceil(maxX - minX + padding * 2);
  const height = Math.ceil(maxY - minY + padding * 2);
  const nodeById = new Map(canvas.nodes.map((node) => [node.id, node]));
  const edges = canvas.edges.map((edge) => {
    const from = nodeById.get(edge.fromNode);
    const to = nodeById.get(edge.toNode);
    if (!from || !to) return "";
    return `<line x1="${from.x + from.width / 2 + offsetX}" y1="${from.y + from.height / 2 + offsetY}" x2="${to.x + to.width / 2 + offsetX}" y2="${to.y + to.height / 2 + offsetY}" />`;
  }).join("");
  const cards = canvas.nodes.map((node) => {
    const source = mediaSources.get(node.file) || "";
    const media = node.kind === "image"
      ? source ? `<img src="${source}" alt="${escapeHtml(node.name || "图片")}" />` : `<div class="missing-media">图片文件未嵌入：${escapeHtml(node.name || "")}</div>`
      : node.kind === "video"
        ? source ? `<video src="${source}" controls preload="metadata"></video>` : `<div class="missing-media">视频文件未嵌入：${escapeHtml(node.name || "")}</div>`
        : node.kind === "audio"
          ? source ? `<audio src="${source}" controls preload="metadata"></audio>` : `<div class="missing-media">音频文件未嵌入：${escapeHtml(node.name || "")}</div>`
          : `<div class="card-text">${escapeHtml(node.text || "").replaceAll("\n", "<br />")}</div>`;
    return `<article class="card" style="left:${node.x + offsetX}px;top:${node.y + offsetY}px;width:${node.width}px;height:${node.height}px">${media}</article>`;
  }).join("");
  const serializedCanvas = JSON.stringify({ schemaVersion: 1, title: documentState.title || "未命名白板", canvas })
    .replaceAll("<", "\\u003c");
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(documentState.title || "神思白板")}</title><style>html,body{margin:0;background:#f5f7f8;color:#172026;font:14px/1.6 "Microsoft YaHei",sans-serif}header{position:sticky;top:0;z-index:2;padding:14px 20px;background:#fff;border-bottom:1px solid #d8dde1}header h1{margin:0;font-size:18px}.board{position:relative;width:${width}px;height:${height}px;min-width:100%;background-color:#fff;background-image:radial-gradient(#cfd6da 1px,transparent 1px);background-size:20px 20px;overflow:hidden}.edges{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.edges line{stroke:#7f8c94;stroke-width:1.5}.card{position:absolute;box-sizing:border-box;overflow:hidden;border:1px solid #8d989e;border-radius:10px;background:#fff;box-shadow:0 2px 8px #18202620}.card img,.card video{display:block;width:100%;height:100%;object-fit:contain;background:#111}.card audio{width:calc(100% - 20px);margin:20px 10px}.card-text{box-sizing:border-box;width:100%;height:100%;padding:14px;overflow:auto;white-space:normal}.missing-media{display:grid;place-items:center;height:100%;padding:12px;color:#68747b;text-align:center}</style></head><body><header><h1>${escapeHtml(documentState.title || "未命名白板")}</h1><small>神思可预览白板分享文件 · ${canvas.nodes.length} 张卡片</small></header><main class="board"><svg class="edges" viewBox="0 0 ${width} ${height}" aria-hidden="true">${edges}</svg>${cards}</main><script id="shensi-whiteboard-data" type="application/json">${serializedCanvas}</script></body></html>`;
};

const shareWhiteboardDocument = async (documentState = {}) => {
  const html = await whiteboardShareHtml(documentState);
  const fileName = `${cleanDownloadFileName(documentState.title || "神思白板", "神思白板")}.shensi-whiteboard.html`;
  await saveBlobLocally({
    blob: new Blob([html], { type: "text/html;charset=utf-8" }),
    fileName,
    mimeType: "text/html",
    extension: ".html",
  });
  showToast("可存储并预览布局的白板分享文件已导出");
};

const openShareDialog = (scope) => {
  ui.shareScope = scope;
  const count = Object.keys(documentsForScope(scope)).filter((id) => id !== "library-trash").length;
  document.querySelector("#shareDialogTitle").textContent = `分享“${exportScopeLabel(scope)}”`;
  document.querySelector("#shareDialogSummary").textContent = scope?.type === "document" ? "单篇文档" : `包含 ${count} 篇文档`;
  const whiteboard = scope?.type === "document" && state.documents[scope.id]?.documentKind === "whiteboard";
  document.querySelector("#shareFileDescription").textContent = whiteboard
    ? "生成可保存布局、文字和可用媒体预览的神思白板文件"
    : scope?.type === "document" ? "默认生成一个 WPS/Word 文档" : "默认生成保留目录结构的 WPS 文档包";
  const linkButton = elements.shareDialog.querySelector('[data-share-action="link"]');
  linkButton.disabled = true;
  linkButton.title = "当前坚果云客户端目录同步不能直接创建分享链接";
  elements.shareDialog.showModal();
};

const saveWhiteboardMedia = async ({ relativePath, name, nodeName = "", mimeType, kind, prompt = "", downloadName = "", workspacePath = state.settings.workspacePath, documentId = state.activeDocument }) => {
    const suggestedName = downloadName || mediaDownloadFileName({ kind, nodeName, prompt, name, relativePath, mimeType });
    const nativeMediaSaver = window.shensiDesktop?.file?.saveWorkspaceMedia;
    if (["image", "video", "audio"].includes(kind) && typeof nativeMediaSaver === "function") {
      const saved = await nativeMediaSaver({
        workspacePath,
        relativePath,
        suggestedName,
        kind,
        mimeType,
      });
      if (!saved?.canceled && saved?.ok) showToast(`已完整另存为 ${saved.fileName || suggestedName}`);
      return;
    }
    const response = await fetch(workspaceAttachmentUrl(relativePath, documentId, { workspacePath }), { cache: "no-store" });
    const kindLabel = kind === "audio" ? "音频" : kind === "video" ? "视频" : "图片";
    if (!response.ok) throw new Error(`${kindLabel}读取失败，无法另存为`);
    const blob = await response.blob();
    const resolvedMimeType = mimeType || blob.type || (kind === "audio" ? "audio/mpeg" : kind === "video" ? "video/mp4" : "image/png");
    const extension = String(suggestedName || name || "").match(/\.[a-z0-9]+$/i)?.[0]
      || ({ "image/jpeg": ".jpg", "image/webp": ".webp", "image/gif": ".gif", "image/avif": ".avif", "image/bmp": ".bmp", "video/webm": ".webm", "audio/wav": ".wav", "audio/mp4": ".m4a", "audio/aac": ".aac", "audio/flac": ".flac", "audio/ogg": ".ogg" }[resolvedMimeType] ?? (kind === "audio" ? ".mp3" : kind === "video" ? ".mp4" : ".png"));
    const fileName = cleanDownloadFileName(/\.[a-z0-9]+$/i.test(suggestedName) ? suggestedName : `${suggestedName}${extension}`);
    const savedFileName = await saveBlobLocally({
      blob,
      fileName,
      mimeType: resolvedMimeType,
      extension,
      ...(kind === "image" ? {
        types: imageExportPickerTypes({ sourceMimeType: resolvedMimeType, sourceExtension: extension }),
        prepareBlob: ({ fileName: selectedFileName }) => {
          const targetMimeType = imageMimeForExtension(fileNameExtension(selectedFileName)) || String(resolvedMimeType).toLowerCase().split(";", 1)[0];
          return transcodeImageBlob(blob, targetMimeType);
        },
      } : {}),
    });
    showToast(`已另存为 ${savedFileName}`);
};

const exportWhiteboardCard = async (nodeId) => {
  const documentState = activeWhiteboardDocument();
  const node = whiteboardNodeById(nodeId, documentState);
  if (!node) throw new Error("卡片不存在或已被删除");
  if (["image", "video", "audio"].includes(node.kind)) {
    await saveWhiteboardMedia({ relativePath: node.file, name: node.name, nodeName: node.generation ? node.name : "", mimeType: node.mimeType, kind: node.kind, prompt: node.generation?.prompt });
    return;
  }
  const text = String(node.text ?? "");
  const firstLine = text.split(/\r?\n/).map((line) => line.trim()).find(Boolean) || "白板卡片";
  const response = await fetch("/api/export/whiteboard-card", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text, title: firstLine }),
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(payload.message || "卡片导出失败");
  }
  const blob = await response.blob();
  const fallback = `${cleanDownloadFileName(firstLine)}.docx`;
  const fileName = responseDownloadFileName(response, fallback);
  await saveBlobLocally({ blob, fileName, mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", extension: ".docx" });
  showToast(`已另存为 ${fileName}`);
};

const copyTextToClipboard = async (text) => {
  try {
    const nativeClipboard = window.shensiDesktop?.clipboard?.writeText;
    if (typeof nativeClipboard === "function") {
      const result = await nativeClipboard(String(text ?? ""));
      if (result?.ok === false) throw new Error("系统剪贴板写入失败");
      return true;
    }
    await navigator.clipboard.writeText(String(text ?? ""));
    return true;
  } catch {
    const textarea = document.createElement("textarea");
    textarea.value = String(text ?? "");
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.append(textarea);
    textarea.select();
    document.execCommand("copy");
    textarea.remove();
    return true;
  }
};

const readTextFromClipboard = async () => {
  const nativeClipboard = window.shensiDesktop?.clipboard?.readText;
  if (typeof nativeClipboard === "function") {
    const result = await nativeClipboard();
    if (result?.ok === false) throw new Error("系统剪贴板读取失败");
    return String(result?.text ?? "");
  }
  if (!navigator.clipboard?.readText) throw new Error("当前环境不支持读取剪贴板文字");
  return String(await navigator.clipboard.readText());
};

const readFormattedClipboard = async () => {
  if (navigator.clipboard?.read) {
    const items = await navigator.clipboard.read();
    for (const item of items) {
      if (!item.types.includes("text/html")) continue;
      const blob = await item.getType("text/html");
      return { html: sanitizeDocumentHtml(await blob.text()), text: await readTextFromClipboard() };
    }
  }
  return { html: "", text: await readTextFromClipboard() };
};

const pngClipboardBlob = async (blob) => {
  if (blob.type === "image/png") return blob;
  const bitmap = await createImageBitmap(blob);
  const canvas = document.createElement("canvas");
  canvas.width = bitmap.width;
  canvas.height = bitmap.height;
  canvas.getContext("2d").drawImage(bitmap, 0, 0);
  bitmap.close();
  return new Promise((resolve, reject) => canvas.toBlob((result) => result ? resolve(result) : reject(new Error("图片转换失败")), "image/png"));
};

const copyWhiteboardImageAttachment = async ({ relativePath, workspacePath = state.settings.workspacePath, documentId = state.activeDocument }) => {
  if (!relativePath) return false;
  try {
    const nativeClipboard = window.shensiDesktop?.clipboard?.writeWorkspaceImage;
    if (typeof nativeClipboard === "function") {
      const result = await nativeClipboard({
        workspacePath,
        relativePath,
      });
      if (!result?.ok) throw new Error("Windows 剪贴板没有确认图片写入");
      showToast("图片已复制，可粘贴到神思或其他软件");
      return true;
    }
    const response = await fetch(workspaceAttachmentUrl(relativePath, documentId, { workspacePath }), { cache: "no-store" });
    if (!response.ok) throw new Error("图片读取失败");
    const blob = await pngClipboardBlob(await response.blob());
    if (!navigator.clipboard?.write || typeof ClipboardItem === "undefined") throw new Error("当前环境不支持复制图片");
    await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
    showToast("图片已复制，可粘贴到神思或其他软件");
    return true;
  } catch (error) {
    showToast(error.message || "图片复制失败");
    return false;
  }
};

const globalCatalogAsset = (asset) => asset?.catalogLinked === true && asset?.readOnlySource === true;

const historicalAssetWorkspaceContext = (asset = {}) => {
  const sourceCatalog = globalCatalogAsset(asset);
  return {
    workspacePath: sourceCatalog && asset.sourceWorkspacePath ? asset.sourceWorkspacePath : state.settings.workspacePath,
    workspaceKind: sourceCatalog && asset.sourceWorkspaceKind ? asset.sourceWorkspaceKind : state.workspaceKind,
    documentId: sourceCatalog && asset.sourceDocumentId ? asset.sourceDocumentId : state.activeDocument,
  };
};

const allHistoricalAssets = ({ includeHidden = false } = {}) => {
  const workspaceAssets = Array.isArray(state.workspaceAssets) ? state.workspaceAssets : [];
  const canvasAssets = normalizeCanvas(activeWhiteboardDocument()?.canvas).assets;
  const assets = normalizeGenerationAssets(workspaceAssets);
  const positions = new Map(assets.map((asset, index) => [asset.id, index]));
  for (const asset of canvasAssets) {
    const index = positions.get(asset.id);
    if (index === undefined) {
      positions.set(asset.id, assets.length);
      assets.push(asset);
    } else assets[index] = asset;
  }
  const merged = mergeGlobalHistoricalAssets({
    localAssets: assets,
    catalogAssets: ui.globalHistoricalAssets,
    currentWorkspacePath: state.settings.workspacePath,
    hiddenCatalogIds: includeHidden ? new Set() : ui.globalAssetHiddenIds,
  });
  const annotated = merged.map((asset) => ({
    ...asset,
    historyHidden: globalCatalogAsset(asset)
      ? ui.globalAssetHiddenIds.has(String(asset.id))
      : assetHistoryEntryIsSuppressed(state, asset),
  }));
  return includeHidden ? annotated : annotated.filter((asset) => !asset.historyHidden);
};

const refreshGlobalHistoricalAssets = async () => {
  const token = ++ui.globalHistoricalAssetsToken;
  ui.globalHistoricalAssetsLoading = true;
  ui.globalHistoricalAssetsError = "";
  if (elements.whiteboardAssetDialog.open) renderWhiteboardAssets();
  try {
    const response = await fetch("/api/history-assets/global", { cache: "no-store" });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !payload.ok || !Array.isArray(payload.items)) throw new Error(payload.message || "全局资产目录读取失败");
    if (token !== ui.globalHistoricalAssetsToken) return false;
    ui.globalHistoricalAssets = payload.items;
    ui.globalHistoricalAssetDiagnostics = Array.isArray(payload.diagnostics) ? payload.diagnostics : [];
    ui.globalHistoricalAssetsScannedAt = String(payload.scannedAt || "");
    return true;
  } catch (error) {
    if (token !== ui.globalHistoricalAssetsToken) return false;
    ui.globalHistoricalAssetsError = String(error?.message || "全局资产目录读取失败");
    return false;
  } finally {
    if (token === ui.globalHistoricalAssetsToken) {
      ui.globalHistoricalAssetsLoading = false;
      if (elements.whiteboardAssetDialog.open) renderWhiteboardAssets();
    }
  }
};

const hideGlobalCatalogAssets = (assets = [], { announce = true } = {}) => {
  const selected = (Array.isArray(assets) ? assets : [assets]).filter(globalCatalogAsset);
  if (!selected.length) return 0;
  selected.forEach((asset) => ui.globalAssetHiddenIds.add(asset.id));
  persistGlobalAssetHiddenIds(ui.globalAssetHiddenIds);
  if (announce) showToast(selected.length > 1
    ? `已从资产库隐藏 ${selected.length} 项来源记录；原始资产和源文件保持不变`
    : "已从资产库隐藏该来源记录；原始资产和源文件保持不变");
  return selected.length;
};

const hideAssetsFromHistoryLibrary = (assets = []) => {
  const selected = (Array.isArray(assets) ? assets : [assets]).filter(Boolean);
  const localAssets = selected.filter((asset) => !globalCatalogAsset(asset));
  const selectedCatalogAssets = selected.filter(globalCatalogAsset);
  const beforeGlobalAssetHiddenIds = globalAssetHiddenIdsSnapshot();
  const localSourceIdentities = new Set(localAssets.map((asset) => historicalAssetSourceIdentity(asset, state.settings.workspacePath)));
  const mirroredCatalogAssets = ui.globalHistoricalAssets.filter((asset) => (
    globalCatalogAsset(asset)
    && localSourceIdentities.has(historicalAssetSourceIdentity(asset, state.settings.workspacePath))
  ));
  hideGlobalCatalogAssets([...selectedCatalogAssets, ...mirroredCatalogAssets], { announce: false });
  const result = hideHistoricalAssetRecords(localAssets, { beforeGlobalAssetHiddenIds, announce: false });
  const deletedCount = result.deletedAssets.length + selectedCatalogAssets.length;
  const protectedCount = result.protectedAssets.length;
  const english = globalUiPreferences.uiLanguage === "en-US";
  if (deletedCount && protectedCount) {
    showToast(english
      ? `Hidden ${deletedCount} asset(s); kept ${protectedCount} protected item(s).`
      : `已隐藏 ${deletedCount} 项资产；${protectedCount} 项受保护内容保持显示`);
  } else if (deletedCount) {
    const onlyCatalogRecords = selectedCatalogAssets.length === deletedCount && !localAssets.length;
    showToast(onlyCatalogRecords
      ? english
        ? `${deletedCount} source record(s) hidden; original assets and source files were kept.`
        : deletedCount > 1
          ? `已从资产库隐藏 ${deletedCount} 项来源记录；原始资产和源文件保持不变`
          : "已从资产库隐藏该来源记录；原始资产和源文件保持不变"
      : english
        ? `${deletedCount} asset(s) hidden; records and local media files were kept.`
        : deletedCount > 1
          ? `已隐藏 ${deletedCount} 项资产；记录与本地媒体文件保持不变`
          : "资产已隐藏；记录与本地媒体文件保持不变");
  } else if (protectedCount) {
    showToast(english
      ? "The selected asset is still used by a whiteboard or document. Remove that reference before deleting its history record."
      : "所选资产仍被白板或正文使用，已保留历史记录；移除引用后可再次删除");
  }
  return result;
};

const unhideAssetsFromHistoryLibrary = (assets = []) => {
  const selected = (Array.isArray(assets) ? assets : [assets]).filter(Boolean);
  if (!selected.length) return 0;
  const sourceIdentities = new Set(selected.map((asset) => historicalAssetSourceIdentity(asset, state.settings.workspacePath)));
  const matchingCatalogIds = ui.globalHistoricalAssets
    .filter((asset) => sourceIdentities.has(historicalAssetSourceIdentity(asset, state.settings.workspacePath)))
    .map((asset) => String(asset.id));
  selected.forEach((asset) => matchingCatalogIds.push(String(asset.id)));
  matchingCatalogIds.forEach((assetId) => ui.globalAssetHiddenIds.delete(assetId));
  persistGlobalAssetHiddenIds(ui.globalAssetHiddenIds);
  const currentWorkspaceAssets = selected.filter((asset) => !globalCatalogAsset(asset)
    || normalizedWorkspacePath(asset.sourceWorkspacePath) === normalizedWorkspacePath(state.settings.workspacePath));
  state.assetHistoryTombstones = unhideHistoricalAssets(state, currentWorkspaceAssets);
  persist();
  showToast(selected.length > 1 ? `已取消隐藏 ${selected.length} 项资产` : "已取消隐藏该资产");
  return selected.length;
};

const whiteboardAssetById = (assetId) => allHistoricalAssets({ includeHidden: true }).find((asset) => asset.id === assetId) ?? null;

const whiteboardNodeForHistoricalAsset = (asset, documentState = activeWhiteboardDocument()) => {
  if (!asset || !documentState) return null;
  if (globalCatalogAsset(asset)) return null;
  const nodes = normalizeCanvas(documentState.canvas).nodes;
  const relativePath = String(asset.attachment?.relativePath || "").replaceAll("\\", "/").toLowerCase();
  const matches = (node) => ["image", "video", "audio"].includes(asset.kind)
    ? relativePath && String(node.file || "").replaceAll("\\", "/").toLowerCase() === relativePath
    : String(node.text || "") === String(asset.text || "");
  const sourceNode = nodes.find((node) => node.id === String(asset.sourceNodeId || ""));
  if (sourceNode && matches(sourceNode)) return sourceNode;
  return nodes.find(matches) || null;
};

const hideHistoricalAssetRecords = (assets = [], { beforeGlobalAssetHiddenIds = null, announce = true } = {}) => {
  const selected = (Array.isArray(assets) ? assets : [assets]).filter(Boolean);
  if (!selected.length && !Array.isArray(beforeGlobalAssetHiddenIds)) return { deletedAssets: [], protectedAssets: [] };
  const activeDocument = activeWhiteboardDocument();
  const beforeCanvas = activeDocument ? whiteboardCanvasSnapshot(activeDocument.canvas) : null;
  const beforeWorkspaceAssets = workspaceAssetsSnapshot();
  const beforeAssetHistoryTombstones = assetHistoryTombstonesSnapshot();
  const result = hideHistoricalAssets(state, selected);
  state.workspaceAssets = result.workspace.workspaceAssets;
  state.assetHistoryTombstones = result.workspace.assetHistoryTombstones;
  state.documents = result.workspace.documents;
  const nextActiveDocument = activeWhiteboardDocument();
  const tracksGlobalHiddenAssets = Array.isArray(beforeGlobalAssetHiddenIds);
  const globalHiddenAssetsChanged = tracksGlobalHiddenAssets
    && JSON.stringify(beforeGlobalAssetHiddenIds) !== JSON.stringify(globalAssetHiddenIdsSnapshot());
  if (result.deletedAssets.length || globalHiddenAssetsChanged) {
    if (nextActiveDocument) nextActiveDocument.updatedAt = nowTime();
    if (beforeCanvas) {
      pushWhiteboardHistory(beforeCanvas, {
        label: result.deletedAssets.length > 1
        ? `批量隐藏资产（${result.deletedAssets.length} 项）`
          : "隐藏资产",
        beforeWorkspaceAssets,
        beforeAssetHistoryTombstones,
        beforeGlobalAssetHiddenIds,
      });
    }
    if (result.deletedAssets.length) persist();
  }
  if (!announce) return result;
  const english = globalUiPreferences.uiLanguage === "en-US";
  if (result.deletedAssets.length && result.protectedAssets.length) {
    showToast(english
      ? `Hidden ${result.deletedAssets.length} asset(s); kept ${result.protectedAssets.length} protected item(s).`
      : `已隐藏 ${result.deletedAssets.length} 项资产；${result.protectedAssets.length} 项受保护内容保持显示`);
  } else if (result.deletedAssets.length) {
    showToast(english
      ? `${result.deletedAssets.length} asset(s) hidden; records and local media files were kept.`
      : result.deletedAssets.length > 1
        ? `已隐藏 ${result.deletedAssets.length} 项资产；记录与本地媒体文件保持不变`
        : "资产已隐藏；记录与本地媒体文件保持不变");
  } else if (result.protectedAssets.length) {
    showToast(english
      ? "The selected asset is still used by a whiteboard or document. Remove that reference before deleting its history record."
      : "所选资产仍被白板或正文使用，已保留历史记录；移除引用后可再次删除");
  }
  return result;
};

const closeWhiteboardAssetTransformMenus = (exceptCard = null) => {
  elements.whiteboardAssetList?.querySelectorAll("[data-whiteboard-asset-transform-menu]").forEach((menu) => {
    const card = menu.closest("[data-whiteboard-asset]");
    if (card === exceptCard) return;
    menu.hidden = true;
    card?.querySelector('[data-whiteboard-asset-action="toggle-transform"]')?.setAttribute("aria-expanded", "false");
  });
};

const resetWhiteboardAssetDeleteMode = () => {
  ui.whiteboardAssetDeleteMode = false;
  ui.whiteboardAssetSelectedIds.clear();
};

const toggleWhiteboardAssetDeleteSelection = (assetId, { restoreFocus = false } = {}) => {
  if (!ui.whiteboardAssetDeleteMode || !whiteboardAssetById(assetId)) return;
  if (ui.whiteboardAssetSelectedIds.has(assetId)) ui.whiteboardAssetSelectedIds.delete(assetId);
  else ui.whiteboardAssetSelectedIds.add(assetId);
  renderWhiteboardAssets();
  if (restoreFocus) requestAnimationFrame(() => elements.whiteboardAssetList.querySelector(`[data-whiteboard-asset="${CSS.escape(assetId)}"]`)?.focus());
};

const renderWhiteboardAssets = () => {
  const referenceTargetNodeId = String(ui.whiteboardAssetReferenceTargetNodeId || "");
  const referenceTarget = referenceTargetNodeId ? whiteboardNodeById(referenceTargetNodeId) : null;
  const referenceSlot = String(ui.whiteboardAssetReferenceSlot || "");
  const conversationReferenceMode = ui.whiteboardAssetConversationReferenceMode === true;
  const referenceMode = conversationReferenceMode || Boolean(referenceTarget);
  const showHidden = !referenceMode && ui.whiteboardAssetShowHidden === true;
  if (referenceTargetNodeId && !referenceTarget) ui.whiteboardAssetReferenceTargetNodeId = "";
  const sortDirection = ui.whiteboardAssetSortDirection === "asc" ? "asc" : "desc";
  const allAssets = [...(showHidden
    ? allHistoricalAssets({ includeHidden: true }).filter((asset) => asset.historyHidden)
    : allHistoricalAssets())].sort((left, right) => {
    const leftTime = assetEventTimestamp(left);
    const rightTime = assetEventTimestamp(right);
    const difference = leftTime - rightTime;
    return sortDirection === "asc" ? difference : -difference;
  });
  const allAssetIds = new Set(allAssets.map((asset) => asset.id));
  ui.whiteboardAssetSelectedIds = new Set([...ui.whiteboardAssetSelectedIds].filter((assetId) => allAssetIds.has(assetId)));
  const { origin: originFilter, kind: kindFilter } = normalizeHistoricalAssetFilters({ origin: ui.whiteboardAssetOriginFilter, kind: ui.whiteboardAssetKindFilter });
  const filteredAssets = filterHistoricalAssets(allAssets, { origin: originFilter, kind: kindFilter });
  const assets = !referenceTarget || !referenceSlot
    ? filteredAssets
    : referenceSlot === "primary"
      ? filteredAssets.filter((asset) => asset.kind === "video")
      : filteredAssets.filter((asset) => ["image", "video", "audio"].includes(asset.kind));
  const visibleLimit = Math.max(48, Number(ui.whiteboardAssetVisibleLimit) || 48);
  const visibleAssets = assets.slice(0, visibleLimit);
  const deleteMode = referenceMode ? false : ui.whiteboardAssetDeleteMode;
  const selectedCount = ui.whiteboardAssetSelectedIds.size;
  const { ids: filteredAssetIds, allSelected: allFilteredSelected } = historicalAssetSelection({ assets, selectedIds: ui.whiteboardAssetSelectedIds });
  elements.whiteboardAssetOriginFilter.value = originFilter;
  elements.whiteboardAssetKindFilter.value = kindFilter;
  elements.whiteboardAssetSort.setAttribute("aria-pressed", String(sortDirection === "asc"));
  elements.whiteboardAssetSort.setAttribute("aria-label", `全部资产排序：${sortDirection === "desc" ? "新的在上" : "旧的在上"}`);
  elements.whiteboardAssetSort.title = sortDirection === "desc" ? "资产排序：新的在上；点击改为旧的在上" : "资产排序：旧的在上；点击改为新的在上";
  elements.whiteboardAssetSort.innerHTML = icon("\uE8CB", sortDirection === "desc" ? "新的在上" : "旧的在上");
  elements.whiteboardAssetShowHidden.hidden = referenceMode;
  elements.whiteboardAssetShowHidden.setAttribute("aria-pressed", String(showHidden));
  elements.whiteboardAssetShowHidden.innerHTML = showHidden
    ? `${icon("\uE890", "返回全部资产")}<span>返回全部资产</span>`
    : `${icon("\uE890", "显示已隐藏")}<span>显示已隐藏</span>`;
  elements.whiteboardAssetBatchActions.hidden = referenceMode;
  elements.whiteboardAssetBatchActions.innerHTML = deleteMode
    ? `<button class="secondary-button compact" type="button" data-whiteboard-asset-batch-action="cancel">${icon("\uE711")}<span>取消</span></button><button class="secondary-button compact" type="button" data-whiteboard-asset-batch-action="select-all" aria-pressed="${allFilteredSelected}" ${filteredAssetIds.length ? "" : "disabled"}>${icon(allFilteredSelected ? "\uE711" : "\uE73E")}<span>${allFilteredSelected ? "取消全选" : `全选（${filteredAssetIds.length}）`}</span></button><button class="${showHidden ? "primary-button" : "danger-button"} whiteboard-asset-batch-confirm" type="button" data-whiteboard-asset-batch-action="confirm" title="${showHidden ? `确认取消隐藏 ${selectedCount} 项资产` : `确认隐藏 ${selectedCount} 项资产`}" aria-label="${showHidden ? `确认取消隐藏 ${selectedCount} 项资产` : `确认隐藏 ${selectedCount} 项资产`}" ${selectedCount ? "" : "disabled"}>${icon(showHidden ? "\uE777" : "\uE890")}<span>确认</span></button>`
    : `<button class="icon-button bare ${showHidden ? "" : "danger"}" type="button" data-whiteboard-asset-batch-action="begin" title="${showHidden ? "批量取消隐藏" : "批量隐藏"}" aria-label="${showHidden ? "批量取消隐藏" : "批量隐藏"}" ${allAssets.length ? "" : "disabled"}>${icon(showHidden ? "\uE777" : "\uE890", showHidden ? "批量取消隐藏" : "批量隐藏")}</button>`;
  elements.whiteboardAssetFilterCount.textContent = uiText(deleteMode ? `${selectedCount} 已选 · ${assets.length} / ${allAssets.length} 项` : `${assets.length} / ${allAssets.length} 项`);
  elements.whiteboardAssetList.innerHTML = assets.length ? `${visibleAssets.map((asset) => {
    const kindLabel = asset.kind === "image" ? "图片" : asset.kind === "video" ? "视频" : asset.kind === "audio" ? "音频" : "文本";
    const coverLabel = asset.novelCover?.assetType === "novel_cover" ? "小说封面" : "";
    const coverMeta = coverLabel
      ? [asset.novelCover.bookTitle, asset.novelCover.directionLabel].filter(Boolean).join(" · ")
      : "";
    const downloadName = ["image", "video", "audio"].includes(asset.kind) ? mediaDownloadFileName({
      kind: asset.kind,
      nodeName: asset.nodeName,
      prompt: asset.prompt,
      name: asset.attachment?.name,
      relativePath: asset.attachment?.relativePath,
      mimeType: asset.attachment?.mimeType,
    }) : "";
    const assetWorkspace = historicalAssetWorkspaceContext(asset);
    const whiteboardMediaDirectory = String(asset.whiteboardMediaDirectory || "");
    const managedMediaDirectory = whiteboardMediaDirectory || String(asset.mediaBatchDirectory || "");
    const revealLabel = whiteboardMediaDirectory ? uiText("打开白板媒体文件夹") : managedMediaDirectory ? uiText("打开本批次文件夹") : uiText("打开所在文件夹");
    const sourceAvailable = asset.sourceAvailable !== false;
    const url = asset.attachment?.relativePath ? workspaceAttachmentUrl(asset.attachment.relativePath, assetWorkspace.documentId, { downloadName, workspacePath: assetWorkspace.workspacePath }) : "";
    const videoUrl = url ? `${url}#t=0.001` : "";
    const posterUrl = asset.attachment?.thumbnailRelativePath
      ? workspaceAttachmentUrl(asset.attachment.thumbnailRelativePath, assetWorkspace.documentId, { workspacePath: assetWorkspace.workspacePath })
      : "";
    const attachmentSourceAttributes = ` data-attachment-workspace-path="${escapeHtml(assetWorkspace.workspacePath)}" data-attachment-workspace-kind="${escapeHtml(assetWorkspace.workspaceKind)}" data-attachment-document-id="${escapeHtml(assetWorkspace.documentId)}"${managedMediaDirectory ? ` data-media-batch-directory="${escapeHtml(managedMediaDirectory)}"` : ""}${whiteboardMediaDirectory ? ' data-media-directory-kind="whiteboard"' : ""}`;
    const assetSourceIsActive = normalizedWorkspacePath(assetWorkspace.workspacePath) === normalizedWorkspacePath(state.settings.workspacePath)
      && assetWorkspace.documentId === state.activeDocument;
    const assetSourceDocument = assetSourceIsActive ? activeWhiteboardDocument() : null;
    const assetSourceNode = asset.kind === "text" && assetSourceDocument
      ? whiteboardNodeById(String(asset.sourceNodeId || ""), assetSourceDocument) || whiteboardNodeForHistoricalAsset(asset, assetSourceDocument)
      : null;
    const editableAssetTextNode = ["text", "generated"].includes(assetSourceNode?.kind) ? assetSourceNode : null;
    const assetPreviewText = editableAssetTextNode ? String(editableAssetTextNode.text ?? "") : String(asset.text || "");
    const assetPreviewNodeId = String(editableAssetTextNode?.id || (sourceAvailable ? asset.sourceNodeId : "") || "");
    const assetTextPreviewAttributes = assetPreviewNodeId
      ? ` data-whiteboard-preview-editable="true" data-whiteboard-preview-workspace-id="${escapeHtml(workspaceCacheKey(assetWorkspace.workspaceKind, assetWorkspace.workspacePath))}" data-whiteboard-preview-node-id="${escapeHtml(assetPreviewNodeId)}" data-whiteboard-preview-text="${escapeHtml(assetPreviewText)}"`
      : "";
    const availablePreview = asset.kind === "image"
      ? deleteMode
        ? `<div class="whiteboard-asset-media-preview"><img src="${escapeHtml(url)}" alt="${escapeHtml(asset.attachment?.name || "历史图片")}" loading="lazy" decoding="async" /></div>`
        : `<button class="whiteboard-asset-media-preview" type="button" data-attachment-preview="image" data-attachment-path="${escapeHtml(asset.attachment?.relativePath || "")}" data-attachment-download-name="${escapeHtml(downloadName)}"${attachmentSourceAttributes} title="预览历史图片"><img src="${escapeHtml(url)}" alt="${escapeHtml(asset.attachment?.name || "历史图片")}" loading="lazy" decoding="async" /></button>`
      : asset.kind === "video"
        ? deleteMode
          ? `<div class="whiteboard-asset-media-preview whiteboard-static-video-preview">${posterUrl ? `<img src="${escapeHtml(posterUrl)}" alt="${escapeHtml(asset.attachment?.name || "历史视频")}" loading="lazy" decoding="async" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" aria-hidden="true">${icon("\uE768")}</span></div>`
          : `<button class="whiteboard-asset-media-preview whiteboard-static-video-preview" type="button" data-attachment-preview="video" data-attachment-src="${escapeHtml(videoUrl)}" data-attachment-path="${escapeHtml(asset.attachment?.relativePath || "")}" data-attachment-download-name="${escapeHtml(downloadName)}"${attachmentSourceAttributes} title="预览历史视频">${posterUrl ? `<img src="${escapeHtml(posterUrl)}" alt="${escapeHtml(asset.attachment?.name || "历史视频")}" loading="lazy" decoding="async" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" aria-hidden="true">${icon("\uE768")}</span></button>`
        : asset.kind === "audio"
          ? deleteMode
            ? `<div class="whiteboard-asset-media-preview"><audio src="${escapeHtml(url)}" controls preload="metadata"></audio></div>`
            : `<div class="whiteboard-asset-media-preview"><audio src="${escapeHtml(url)}" controls preload="metadata" aria-label="${escapeHtml(asset.attachment?.name || "历史音频")}"></audio></div>`
        : deleteMode
          ? `<div class="whiteboard-asset-text-preview"><pre>${escapeHtml(assetPreviewText || "空白文本")}</pre></div>`
          : `<button class="whiteboard-asset-text-preview" type="button" data-attachment-preview="text"${attachmentSourceAttributes}${assetTextPreviewAttributes} title="预览文字卡片" aria-label="预览文字卡片"><pre>${escapeHtml(assetPreviewText || "空白文本")}</pre></button>`;
    const preview = sourceAvailable
      ? availablePreview
      : `<div class="whiteboard-asset-source-unavailable">${icon("\uE783", "来源不可用")}<strong>来源不可用</strong><span>原笔记、原文档或附件当前无法读取</span></div>`;
    const createdAt = new Date(asset.createdAt);
    const elapsedLabel = Number(asset.elapsedMs) > 0 ? ` · ${uiText("总用时")} ${formatWhiteboardGenerationDuration(asset.elapsedMs)}` : "";
    const selected = ui.whiteboardAssetSelectedIds.has(asset.id);
    const referenceControl = referenceMode ? (() => {
      const conversation = conversationReferenceMode ? historicalAssetReferenceConversation() : null;
      const node = conversationReferenceMode ? null : whiteboardNodeForHistoricalAsset(asset);
      const connected = conversationReferenceMode
        ? conversationReferencesHistoricalAsset(conversation, asset, state.settings.workspacePath)
        : Boolean(node && normalizeCanvas(activeWhiteboardDocument()?.canvas).edges.some((edge) => edge.fromNode === node.id && edge.toNode === referenceTargetNodeId));
      const label = conversationReferenceMode
        ? connected ? "已加入对话引用" : "引用全部资产"
        : connected ? "已连接为参考" : "添加为参考";
      return `<button class="whiteboard-asset-reference-add" type="button" data-whiteboard-asset-action="reference" title="${label}" aria-label="${label}" ${connected || !sourceAvailable ? "disabled" : ""}><span aria-hidden="true">${connected ? "✓" : "+"}</span></button>`;
    })() : "";
    const sourceLabel = asset.source === "asset-library"
      ? "当前工作区 · 独立资产"
      : asset.sourceWorkspaceName
        ? [asset.sourceWorkspaceKind === "notebook" ? "笔记本" : "作品", asset.sourceWorkspaceName, asset.sourceTitle].filter(Boolean).join(" · ")
        : "";
    const typeSourceLabel = asset.source === "conversation" ? " · 对话" : asset.source === "asset-library" ? " · 独立资产" : "";
    const disabledSourceAction = sourceAvailable ? "" : "disabled";
    const originLabel = asset.origin === "generated" ? "生成" : asset.origin === "upload" ? "上传" : "来源待确认";
    return `<article class="whiteboard-asset-card ${referenceMode ? "is-reference-picker" : ""} ${deleteMode ? "is-batch-selecting" : ""} ${selected ? "is-selected" : ""} ${asset.historyHidden ? "is-history-hidden" : ""} ${globalCatalogAsset(asset) ? "is-global-source" : ""} ${sourceAvailable ? "" : "is-source-unavailable"}" data-whiteboard-asset="${escapeHtml(asset.id)}" data-whiteboard-asset-kind="${escapeHtml(asset.kind)}" data-whiteboard-asset-origin="${escapeHtml(asset.origin)}"${deleteMode ? ` data-whiteboard-asset-selectable role="checkbox" aria-checked="${selected}" tabindex="0"` : ""}>
      ${deleteMode ? `<span class="whiteboard-asset-selection-marker" aria-hidden="true"><span class="whiteboard-asset-selection-check">✓</span></span>` : ""}
      <header><strong>${coverLabel || kindLabel} · ${originLabel}${typeSourceLabel}</strong><time>${escapeHtml(`${Number.isNaN(createdAt.getTime()) ? "时间待确认" : createdAt.toLocaleString("zh-CN")}${elapsedLabel}`)}</time></header>
      <div class="whiteboard-asset-preview">${preview}${referenceControl}</div>
      ${sourceLabel ? `<p class="whiteboard-asset-source" title="${escapeHtml(sourceLabel)}">${icon(asset.sourceWorkspaceKind === "notebook" ? "\uE8A5" : "\uE8B7")}<span>${escapeHtml(sourceLabel)}</span>${sourceAvailable ? "" : "<b>来源不可用</b>"}</p>` : ""}
      ${coverMeta ? `<p class="whiteboard-asset-cover-meta" title="${escapeHtml(coverMeta)}"><strong>${escapeHtml(asset.novelCover.bookTitle || "未命名封面")}</strong><span>${escapeHtml(asset.novelCover.directionLabel || "封面方向")}</span></p>` : ""}
      ${asset.origin === "generated" && asset.prompt ? `<p class="whiteboard-asset-prompt" title="${escapeHtml(asset.prompt)}"><strong>生成提示词</strong><span>${escapeHtml(asset.prompt)}</span></p>` : ""}
      ${deleteMode || referenceMode ? "" : `<footer class="whiteboard-asset-actions">
        <button class="icon-button bare whiteboard-asset-reveal" type="button" data-whiteboard-asset-action="reveal" title="${revealLabel}" aria-label="${revealLabel}">${icon("\uE8B7", revealLabel)}</button>
        <span class="whiteboard-asset-transform">
          <button class="icon-button bare" type="button" data-whiteboard-asset-action="toggle-transform" title="转化" aria-label="转化全部资产" aria-haspopup="menu" aria-expanded="false" ${disabledSourceAction}>${icon("\uE895", "转化")}</button>
          <span class="whiteboard-asset-transform-menu" data-whiteboard-asset-transform-menu role="menu" hidden>
            <button type="button" role="menuitem" data-whiteboard-asset-action="transform-project" ${disabledSourceAction}>${icon("\uE895")}<span>转化为作品</span></button>
            <button type="button" role="menuitem" data-whiteboard-asset-action="transform-notebook" ${disabledSourceAction}>${icon("\uE8A5")}<span>转化为笔记</span></button>
          </span>
        </span>
        <button class="icon-button bare" type="button" data-whiteboard-asset-action="add" title="添加到白板" ${disabledSourceAction}>${icon("\uE710", "添加到白板")}</button>
        <button class="icon-button bare" type="button" data-whiteboard-asset-action="copy" title="复制" ${disabledSourceAction}>${icon("\uE8C8", "复制")}</button>
        <button class="icon-button bare" type="button" data-whiteboard-asset-action="save" title="另存为" ${disabledSourceAction}>${icon("\uE792", "另存为")}</button>
        <button class="icon-button bare ${asset.historyHidden ? "" : "danger"}" type="button" data-whiteboard-asset-action="${asset.historyHidden ? "unhide" : "delete"}" title="${asset.historyHidden ? "取消隐藏" : "从资产库隐藏（不删除文件或记录）"}">${icon(asset.historyHidden ? "\uE777" : "\uE890", asset.historyHidden ? "取消隐藏" : "隐藏")}</button>
      </footer>`}
    </article>`;
  }).join("")}${visibleAssets.length < assets.length ? `<button class="secondary-button whiteboard-assets-load-more" type="button" data-whiteboard-asset-load-more>继续显示（${visibleAssets.length} / ${assets.length}）</button>` : ""}` : `<p class="whiteboard-assets-empty">${ui.globalHistoricalAssetsLoading ? "正在读取笔记与作品资产…" : allAssets.length ? "没有符合当前筛选条件的资产。" : ui.globalHistoricalAssetsError ? `全局资产目录读取失败：${escapeHtml(ui.globalHistoricalAssetsError)}` : "还没有可用的资产。"}</p>`;
  const scopeLabel = elements.whiteboardAssetDialog.querySelector(".whiteboard-assets-shell > header small");
  if (scopeLabel) scopeLabel.textContent = referenceMode
    ? conversationReferenceMode
      ? "添加到当前对话引用"
      : `${referenceSlot === "primary" ? "选择编辑视频" : referenceSlot === "additional" ? "选择参考内容" : "连接到"}：${referenceTarget.name || whiteboardNodeKindLabel(referenceTarget) || "当前生成节点"}`
    : ui.globalHistoricalAssetsLoading ? "正在读取笔记与作品资产…" : "笔记与作品全部资产";
  const title = elements.whiteboardAssetDialog.querySelector("#whiteboardAssetTitle");
  if (title) title.textContent = conversationReferenceMode ? "引用全部资产" : referenceMode ? "选择全部资产作为参考" : showHidden ? "已隐藏资产" : "全部资产";
};

let whiteboardAssetRenderToken = 0;
const scheduleWhiteboardAssetRender = ({ settleNativeSelect = false } = {}) => {
  const token = ++whiteboardAssetRenderToken;
  const render = () => {
    if (token !== whiteboardAssetRenderToken || !elements.whiteboardAssetDialog.open) return;
    renderWhiteboardAssets();
  };
  requestAnimationFrame(() => {
    if (settleNativeSelect) requestAnimationFrame(render);
    else render();
  });
};

const openWhiteboardAssets = ({ referenceTargetNodeId = "", referenceSlot = "", conversationReference = false } = {}) => {
  if (!conversationReference && !activeWhiteboardDocument()) return;
  if (conversationReference && !activeConversation()) return;
  resetWhiteboardAssetDeleteMode();
  ui.whiteboardAssetConversationReferenceMode = conversationReference === true;
  ui.whiteboardAssetReferenceConversationId = conversationReference ? activeConversation()?.id || "" : "";
  ui.whiteboardAssetReferenceTargetNodeId = !conversationReference && whiteboardNodeById(referenceTargetNodeId) ? String(referenceTargetNodeId) : "";
  ui.whiteboardAssetReferenceSlot = ui.whiteboardAssetReferenceTargetNodeId && ["primary", "additional"].includes(referenceSlot) ? referenceSlot : "";
  ui.whiteboardAssetVisibleLimit = 48;
  elements.whiteboardAssetOriginFilter.value = ui.whiteboardAssetOriginFilter;
  elements.whiteboardAssetKindFilter.value = ui.whiteboardAssetKindFilter;
  elements.whiteboardAssetList.innerHTML = `<p class="whiteboard-assets-empty">正在读取全部资产…</p>`;
  elements.whiteboardAssetDialog.showModal();
  // Paint the dialog controls and native select labels first. Building media
  // previews is deferred until the following frame so the dropdown never
  // opens as a blank white panel on media-heavy whiteboards.
  scheduleWhiteboardAssetRender({ settleNativeSelect: true });
  void refreshGlobalHistoricalAssets();
};

const whiteboardCardHistoryEntries = (nodeId = ui.whiteboardCardHistoryNodeId) => canvasNodeGenerationHistory(
  activeWhiteboardDocument()?.canvas,
  nodeId,
);

const whiteboardCardCurrentHistoryAsset = (node, entries = whiteboardCardHistoryEntries(node?.id)) => {
  if (!node) return null;
  const generationJobId = String(node.generation?.jobId || "");
  const generationCreatedAt = String(node.generation?.createdAt || "");
  const generationMatch = entries.find((asset) => (
    (generationJobId && String(asset.generationJobId || "") === generationJobId)
    || (generationCreatedAt && String(asset.createdAt || "") === generationCreatedAt)
  ));
  if (generationMatch) return generationMatch;
  if (["image", "video", "audio"].includes(node.kind)) {
    return entries.find((asset) => asset.kind === node.kind && asset.attachment?.relativePath === node.file) ?? null;
  }
  const text = String(node.text || "");
  return entries.find((asset) => asset.kind === "text" && String(asset.text || "") === text) ?? null;
};

const whiteboardCardHistoryModel = (nodeId = ui.whiteboardCardHistoryNodeId) => {
  const node = whiteboardNodeById(nodeId);
  const versions = whiteboardCardHistoryEntries(nodeId);
  const current = whiteboardCardCurrentHistoryAsset(node, versions);
  return cardHistoryViewModel({ current, versions });
};

const renderWhiteboardCardHistory = () => {
  const node = whiteboardNodeById(ui.whiteboardCardHistoryNodeId);
  const entries = whiteboardCardHistoryModel();
  document.querySelector("#whiteboardCardHistoryTitle").textContent = `${node?.name || whiteboardNodeKindLabel(node) || "卡片"} · 历史版本`;
  elements.whiteboardCardHistoryList.innerHTML = entries.length ? entries.map((asset, index) => {
    const kindLabel = asset.kind === "image" ? "图片" : asset.kind === "video" ? "视频" : asset.kind === "audio" ? "音频" : "文本";
    const downloadName = ["image", "video", "audio"].includes(asset.kind) ? mediaDownloadFileName({
      kind: asset.kind,
      nodeName: asset.nodeName,
      prompt: asset.prompt,
      name: asset.attachment?.name,
      relativePath: asset.attachment?.relativePath,
      mimeType: asset.attachment?.mimeType,
    }) : "";
    const url = asset.attachment?.relativePath ? workspaceAttachmentUrl(asset.attachment.relativePath, state.activeDocument, { downloadName }) : "";
    const videoUrl = url ? `${url}#t=0.001` : "";
    const posterUrl = asset.attachment?.thumbnailRelativePath
      ? workspaceAttachmentUrl(asset.attachment.thumbnailRelativePath, state.activeDocument)
      : "";
    const whiteboardMediaDirectory = String(asset.whiteboardMediaDirectory || "");
    const managedMediaDirectory = whiteboardMediaDirectory || String(asset.mediaBatchDirectory || "");
    const mediaBatchAttribute = managedMediaDirectory ? ` data-media-batch-directory="${escapeHtml(managedMediaDirectory)}"${whiteboardMediaDirectory ? ' data-media-directory-kind="whiteboard"' : ""}` : "";
    const preview = asset.kind === "image"
      ? `<button class="whiteboard-asset-preview whiteboard-card-history-media" type="button" data-attachment-preview="image" data-attachment-path="${escapeHtml(asset.attachment?.relativePath || "")}" data-attachment-download-name="${escapeHtml(downloadName)}"${mediaBatchAttribute} title="预览历史图片"><img src="${escapeHtml(url)}" alt="${escapeHtml(asset.attachment?.name || "历史图片")}" loading="lazy" /></button>`
      : asset.kind === "video"
        ? `<button class="whiteboard-asset-preview whiteboard-card-history-media whiteboard-static-video-preview" type="button" data-attachment-preview="video" data-attachment-src="${escapeHtml(videoUrl)}" data-attachment-path="${escapeHtml(asset.attachment?.relativePath || "")}" data-attachment-download-name="${escapeHtml(downloadName)}"${mediaBatchAttribute} title="预览历史视频">${posterUrl ? `<img src="${escapeHtml(posterUrl)}" alt="${escapeHtml(asset.attachment?.name || "历史视频")}" loading="lazy" decoding="async" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" aria-hidden="true">${icon("\uE768")}</span></button>`
        : asset.kind === "audio"
          ? `<div class="whiteboard-asset-preview whiteboard-card-history-media"><audio src="${escapeHtml(url)}" controls preload="metadata" aria-label="${escapeHtml(asset.attachment?.name || "历史音频")}"></audio></div>`
        : `<pre>${escapeHtml(asset.text || "空白文本")}</pre>`;
    const createdAt = new Date(asset.createdAt);
    const current = asset.current === true;
    const elapsedLabel = Number(asset.elapsedMs) > 0 ? ` · ${uiText("总用时")} ${formatWhiteboardGenerationDuration(asset.elapsedMs)}` : "";
    const deleteAllowed = canDeleteCardHistoryVersion({ versionId: asset.id, currentVersionId: entries.find((entry) => entry.current)?.id, versionCount: entries.length });
    const currentAction = current
      ? `<button class="secondary-button compact whiteboard-card-history-state" type="button" disabled>当前版本</button>`
      : `<button class="primary-button compact whiteboard-card-history-state" type="button" data-whiteboard-card-history-restore="${escapeHtml(asset.id)}">设为当前</button>`;
    const deleteAction = deleteAllowed
      ? `<button class="icon-button bare small danger whiteboard-card-history-delete" type="button" data-whiteboard-card-history-delete="${escapeHtml(asset.id)}" title="删除历史版本" aria-label="删除历史版本">${icon("\uE74D", "删除历史版本")}</button>`
      : "";
    return `<article class="whiteboard-asset-card whiteboard-card-history-entry${current ? " current" : ""}" data-whiteboard-card-history-asset="${escapeHtml(asset.id)}" data-whiteboard-asset-kind="${escapeHtml(asset.kind)}" style="--whiteboard-card-history-order:${index}"><header><strong>v${asset.version} · ${kindLabel}</strong><time>${escapeHtml(`${Number.isNaN(createdAt.getTime()) ? "" : createdAt.toLocaleString("zh-CN")}${elapsedLabel}`)}</time></header><div class="whiteboard-asset-preview">${preview}</div>${asset.prompt ? `<p class="whiteboard-card-history-prompt"><strong>生成提示词</strong>${escapeHtml(asset.prompt)}</p>` : ""}<footer class="whiteboard-asset-actions">${currentAction}${deleteAction}</footer></article>`;
  }).join("") : `<p class="whiteboard-assets-empty">这张卡片还没有生成历史。</p>`;
};

const restoreWhiteboardCardHistoryVersion = ({ asset, documentState, nodeId } = {}) => {
  if (!asset || !documentState || !nodeId) return null;
  const node = normalizeCanvas(documentState.canvas).nodes.find((item) => item.id === String(nodeId));
  if (!node) return null;
  const entries = whiteboardCardHistoryEntries(nodeId);
  const currentAsset = whiteboardCardCurrentHistoryAsset(node, entries);
  if (currentAsset?.id === asset.id) return null;
  if (!canvasGenerationAssetContent(asset)) return null;

  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  let nextCanvas = documentState.canvas;
  // A legacy card may have no matching history asset. Capture that current
  // state once, then keep the selected historical asset in its original slot.
  if (!currentAsset) nextCanvas = snapshotCanvasNodeVersion(nextCanvas, nodeId, { id: uid("canvas-version") });
  nextCanvas = replaceCanvasNodeWithGenerationAsset(nextCanvas, nodeId, asset);
  documentState.canvas = nextCanvas;
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: `将卡片历史版本 v${asset.version} 设为当前` });
  return { beforeCanvas, optimisticCanvas: whiteboardCanvasSnapshot(nextCanvas) };
};

const persistRestoredWhiteboardCardHistoryVersion = async ({ documentState, beforeCanvas, optimisticCanvas, version } = {}) => {
  try {
    // Let the already-rendered swap reach the screen before cloning the full
    // workspace and scheduling its durable save.
    await new Promise((resolve) => setTimeout(resolve, 0));
    if (state.documents[state.activeDocument] === documentState) persist({ documentIds: [state.activeDocument] });
    await flushWorkspaceSave({ throwOnError: true, recoverConflict: true });
    showToast(`已将 v${version} 设为当前版本`);
  } catch (error) {
    const currentCanvas = whiteboardCanvasSnapshot(documentState?.canvas);
    const canRollback = documentState
      && JSON.stringify(currentCanvas) === JSON.stringify(optimisticCanvas);
    if (canRollback) {
      documentState.canvas = whiteboardCanvasSnapshot(beforeCanvas);
      documentState.updatedAt = nowTime();
      const stack = whiteboardUndoStack();
      if (stack.at(-1)?.label === `将卡片历史版本 v${version} 设为当前`) stack.pop();
      persist();
      renderWhiteboard(documentState);
      if (elements.whiteboardCardHistoryDialog.open) renderWhiteboardCardHistory();
    }
    showToast(canRollback ? `设置 v${version} 失败，已恢复原当前版本` : `设置 v${version} 保存失败，后续修改已保留`);
    console.warn("whiteboard card history restore failed", error);
  }
};

const deleteWhiteboardCardHistoryVersion = (assetId) => {
  const documentState = activeWhiteboardDocument();
  const entries = whiteboardCardHistoryModel();
  const currentVersionId = entries.find((entry) => entry.current)?.id || "";
  const asset = entries.find((entry) => entry.id === assetId);
  if (!documentState || !asset) return false;
  if (!canDeleteCardHistoryVersion({ versionId: assetId, currentVersionId, versionCount: entries.length })) {
    showToast(assetId === currentVersionId ? "当前版本不能删除，请先将其他版本设为当前" : "仅有一个版本时不能删除");
    return false;
  }
  if (!window.confirm(`删除卡片历史版本 v${asset.version}？此操作不会删除当前卡片。`)) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  documentState.canvas = removeCanvasAsset(documentState.canvas, assetId);
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: `删除卡片历史版本 v${asset.version}` });
  persist();
  renderWhiteboardCardHistory();
  return true;
};

const openWhiteboardCardHistory = (nodeId) => {
  ui.whiteboardCardHistoryNodeId = nodeId || "";
  renderWhiteboardCardHistory();
  elements.whiteboardCardHistoryDialog.showModal();
};

const exportWhiteboardAsset = async (asset) => {
  if (!asset) return;
  if (["image", "video", "audio"].includes(asset.kind)) {
    const assetWorkspace = historicalAssetWorkspaceContext(asset);
    await saveWhiteboardMedia({
      relativePath: asset.attachment?.relativePath,
      name: asset.attachment?.name,
      mimeType: asset.attachment?.mimeType,
      kind: asset.kind,
      nodeName: asset.nodeName,
      prompt: asset.prompt,
      workspacePath: assetWorkspace.workspacePath,
      documentId: assetWorkspace.documentId,
    });
    return;
  }
  const text = String(asset.text ?? "");
  const firstLine = text.split(/\r?\n/).map((line) => line.trim()).find(Boolean) || "历史文本";
  const response = await fetch("/api/export/whiteboard-card", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text, title: firstLine }),
  });
  if (!response.ok) throw new Error((await response.json().catch(() => ({}))).message || "文本导出失败");
  await saveBlobLocally({
    blob: await response.blob(),
    fileName: responseDownloadFileName(response, `${cleanDownloadFileName(firstLine)}.docx`),
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    extension: ".docx",
  });
};

const materializeHistoricalAssetForCurrentWorkspace = async (asset) => {
  if (!asset) return null;
  if (asset.sourceAvailable === false) throw new Error("来源当前不可用，无法添加该资产");
  const snapshot = clone(asset);
  if (!assetNeedsWorkspaceMaterialization(snapshot, state.settings.workspacePath)) return snapshot;
  const response = await fetch("/api/workspace/attachment/copy", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sourceWorkspacePath: snapshot.sourceWorkspacePath,
      targetWorkspacePath: state.settings.workspacePath,
      relativePath: snapshot.attachment.relativePath,
      name: snapshot.attachment.name,
      mimeType: snapshot.attachment.mimeType,
    }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload.ok || !payload.attachment?.relativePath) throw new Error(payload.message || "跨工作区附件复制失败");
  snapshot.attachment = {
    ...payload.attachment,
    ...(Number(snapshot.attachment?.durationMs) > 0 ? { durationMs: Number(snapshot.attachment.durationMs) } : {}),
  };
  return snapshot;
};

const historicalAssetReferenceConversation = () => state.conversations.find((conversation) => (
  conversation.id === ui.whiteboardAssetReferenceConversationId
)) ?? null;

const addHistoricalAssetToConversationReferences = async (asset) => {
  const conversation = historicalAssetReferenceConversation();
  if (!asset || !conversation) throw new Error("原对话已经关闭，无法加入全部资产引用");
  conversation.attachments ??= [];
  if (conversationReferencesHistoricalAsset(conversation, asset, state.settings.workspacePath)) {
    showToast("该资产已经在当前对话引用中");
    return false;
  }
  const dynamicModels = dynamicModelsForChannel(state.settings.provider, state.settings.adapter);
  const attachmentLimit = getDynamicAttachmentLimit(state.settings, dynamicModels);
  if (conversation.attachments.length >= attachmentLimit) {
    throw new Error(`对话输入区最多保留 ${attachmentLimit} 个附件，请先移除一个附件`);
  }
  const materializedAsset = await materializeHistoricalAssetForCurrentWorkspace(asset);
  let storedAttachment = materializedAsset.attachment ? clone(materializedAsset.attachment) : null;
  if (materializedAsset.kind === "text") {
    const text = String(materializedAsset.text || "");
    if (!text.trim()) throw new Error("空白历史文本不能加入引用");
    const baseName = cleanDownloadFileName(materializedAsset.nodeName || materializedAsset.sourceTitle || "历史文本");
    const file = new File([text], `${baseName}.txt`, { type: "text/plain" });
    storedAttachment = await uploadWorkspaceFile(file);
  }
  if (!storedAttachment?.relativePath) throw new Error("资产没有可读取的受管内容");
  const attachment = historicalAssetConversationAttachment({
    asset: materializedAsset,
    storedAttachment,
    id: uid("attachment"),
    currentWorkspacePath: state.settings.workspacePath,
  });
  if (!attachment) throw new Error("资产引用信息不完整");
  conversation.attachments.push(attachment);
  markConversationComposerReferencesPending(conversation);
  synchronizeConversationReferenceContext(conversation);
  persist();
  if (activeConversation()?.id === conversation.id) {
    renderContextChips();
    renderReferencePanel();
  }
  showToast("资产已加入当前对话引用");
  return true;
};

const addWhiteboardAssetToCanvas = async (asset) => {
  const documentState = activeWhiteboardDocument();
  if (!asset || !documentState) return false;
  const materializedAsset = await materializeHistoricalAssetForCurrentWorkspace(asset);
  const rect = elements.whiteboardEditor.getBoundingClientRect();
  const point = whiteboardWorldPoint(rect.left + rect.width / 2, rect.top + rect.height / 2, documentState);
  const generation = canvasGenerationMetadataForAsset(materializedAsset);
  if (["image", "video", "audio"].includes(materializedAsset.kind)) {
    return Boolean(addWhiteboardImageCard({
      attachment: materializedAsset.attachment,
      aspectRatio: materializedAsset.aspectRatio,
      generation,
      sourceAsset: materializedAsset,
      x: point.x - 160,
      y: point.y - 90,
    }));
  }
  return Boolean(addWhiteboardCard({ x: point.x - 130, y: point.y - 80, text: materializedAsset.text, kind: "generated", generation, sourceAsset: materializedAsset }));
};

const syncWhiteboardHistoryControls = () => {
  const isWhiteboard = Boolean(activeWhiteboardDocument());
  elements.whiteboardHistoryControls.hidden = !isWhiteboard;
  if (!isWhiteboard) return;
  const historyKey = `${workspaceIdentity()}::${state.activeDocument}`;
  elements.whiteboardUndo.disabled = !(ui.whiteboardUndoStacks.get(historyKey)?.length);
  elements.whiteboardRedo.disabled = !(ui.whiteboardRedoStacks.get(historyKey)?.length);
};

const whiteboardCandidateKey = (nodeId, {
  workspacePath = state.settings.workspacePath,
  documentId = state.activeDocument,
} = {}) => `${String(workspacePath || "").replaceAll("\\", "/").replace(/\/{2,}/gu, "/").replace(/\/$/u, "").toLocaleLowerCase()}::${String(documentId || "")}::${String(nodeId || "")}`;

const whiteboardCandidateFor = (nodeId, location = {}) => ui.whiteboardCandidates.get(whiteboardCandidateKey(nodeId, location)) ?? null;

const whiteboardCandidateBelongsToJob = (candidateKey, jobId) => {
  const candidate = ui.whiteboardCandidates.get(candidateKey);
  return Boolean(candidate && jobId && candidate.jobId === jobId);
};

const whiteboardGenerationProgressTimers = new Map();
const whiteboardProgressDisplayTimers = new Map();
const whiteboardTextRevealAnimations = new Map();
const WHITEBOARD_TEXT_REVEAL_FRAME_MS = 18;
const WHITEBOARD_PROGRESS_DISPLAY_FRAME_MS = 35;
let whiteboardGenerationProgressTicker = null;

const whiteboardProgressTarget = (candidate = {}) => whiteboardGenerationProgressTarget(candidate);

const whiteboardProgressDisplayField = (candidate = {}) => ["image", "video", "audio"].includes(candidate?.channel)
  ? "displayProviderProgressPercent"
  : "displayProgressPercent";

const whiteboardDisplayedProgress = (candidate = {}) => {
  const field = whiteboardProgressDisplayField(candidate);
  const value = Number(candidate[field]);
  return Math.round(Number.isFinite(value) ? value : 0);
};

const cancelWhiteboardProgressDisplay = (candidateKey) => {
  const timer = whiteboardProgressDisplayTimers.get(candidateKey);
  if (timer) clearTimeout(timer);
  whiteboardProgressDisplayTimers.delete(candidateKey);
};

const scheduleWhiteboardProgressDisplay = (candidateKey) => {
  if (whiteboardProgressDisplayTimers.has(candidateKey)) return;
  const advance = () => {
    whiteboardProgressDisplayTimers.delete(candidateKey);
    const candidate = ui.whiteboardCandidates.get(candidateKey);
    if (!candidate) return;
    if (!whiteboardGenerationMeasurementActive(candidate) && candidate.status !== "complete") return;
    const target = whiteboardProgressTarget(candidate);
    if (target === null) return;
    const field = whiteboardProgressDisplayField(candidate);
    const current = Number.isFinite(Number(candidate[field])) ? Number(candidate[field]) : 0;
    const nextValue = smoothProgressStep(current, target, {
      minimum: 0,
      maximum: ["image", "video", "audio"].includes(candidate.channel) ? 100 : 99,
      remainingFrames: 5,
    });
    const next = { ...candidate, [field]: nextValue };
    ui.whiteboardCandidates.set(candidateKey, next);
    patchWhiteboardCandidateProgress(next);
    if (nextValue < target) {
      whiteboardProgressDisplayTimers.set(candidateKey, setTimeout(advance, WHITEBOARD_PROGRESS_DISPLAY_FRAME_MS));
    }
  };
  whiteboardProgressDisplayTimers.set(candidateKey, setTimeout(advance, WHITEBOARD_PROGRESS_DISPLAY_FRAME_MS));
};

const stopWhiteboardGenerationProgressTickerWhenIdle = () => {
  if (whiteboardGenerationProgressTimers.size || !whiteboardGenerationProgressTicker) return;
  clearInterval(whiteboardGenerationProgressTicker);
  whiteboardGenerationProgressTicker = null;
};

const tickWhiteboardGenerationProgress = () => {
  for (const [candidateKey, startedAt] of whiteboardGenerationProgressTimers) {
    const current = ui.whiteboardCandidates.get(candidateKey);
    if (!current) {
      whiteboardGenerationProgressTimers.delete(candidateKey);
      continue;
    }
    const channel = current.channel || "text";
    if (!whiteboardGenerationMeasurementActive(current)) {
      whiteboardGenerationProgressTimers.delete(candidateKey);
      continue;
    }
    const elapsedMs = Math.max(0, Date.now() - Number(current.startedAt || startedAt || Date.now()));
    if (["image", "video", "audio"].includes(channel)) {
      const providerProgress = Number(current.providerProgressPercent);
      const hasProviderProgress = Number.isFinite(providerProgress) && providerProgress > 0;
      updateWhiteboardGenerationCandidate(candidateKey, {
        elapsedMs,
        ...(!whiteboardGenerationProgressActive(current) || hasProviderProgress ? {} : {
          progressPercent: Math.max(
            Number(current.progressPercent) || 0,
            syntheticMediaProgress({ elapsedMs, channel }),
          ),
        }),
      });
      continue;
    }
    if (whiteboardProviderQueueVisible(current)) {
      updateWhiteboardGenerationCandidate(candidateKey, { elapsedMs, progressPercent: 24 });
      continue;
    }
    const estimated = Math.round(8 + 80 * (1 - Math.exp(-elapsedMs / 30_000)));
    updateWhiteboardGenerationCandidate(candidateKey, {
      elapsedMs,
      progressPercent: Math.min(88, Math.max(Number(current.progressPercent) || 0, estimated)),
    });
  }
  stopWhiteboardGenerationProgressTickerWhenIdle();
};

const ensureWhiteboardGenerationProgressTicker = () => {
  if (whiteboardGenerationProgressTicker) return;
  whiteboardGenerationProgressTicker = setInterval(tickWhiteboardGenerationProgress, 1_000);
  whiteboardGenerationProgressTicker.unref?.();
};

const whiteboardCandidatePhaseKey = (candidate = {}) => JSON.stringify([
  candidate.channel || "",
  candidate.status || "",
  candidate.providerStatus || "",
  candidate.providerTaskId || "",
  candidate.submissionState || "",
  candidate.submittedAt || "",
  candidate.connectionInterrupted === true,
  candidate.providerQueuePosition ?? null,
  candidate.providerQueueLength ?? null,
  candidate.error || "",
  candidate.desiredAction || "",
  candidate.availableActions ?? [],
  candidate.cardApplyStage || "",
  candidate.cardApplyFailed === true,
]);

const patchWhiteboardCandidateProgress = (candidate) => {
  if (!candidate || !["text", "image", "video", "audio"].includes(candidate.channel)) return false;
  const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(candidate.nodeId)}"]`);
  if (!card || card.dataset.generationJobId !== String(candidate.jobId || "")) return false;
  if (card.dataset.generationPhaseKey !== whiteboardCandidatePhaseKey(candidate)) return false;
  const metrics = card.querySelector(".whiteboard-generation-metrics");
  if (!metrics) return false;
  const elapsed = metrics.querySelector("time");
  if (elapsed) elapsed.textContent = formatWhiteboardGenerationDuration(candidate.elapsedMs);
  const progress = metrics.querySelector("b");
  if (progress && whiteboardProgressTarget(candidate) !== null) {
    progress.textContent = `${whiteboardDisplayedProgress(candidate)}%`;
  }
  return true;
};

const renderWhiteboardCandidateLocation = (candidate) => {
  if (!candidate || state.activeDocument !== candidate.documentId) return;
  if (String(state.settings.workspacePath || "").toLowerCase() !== String(candidate.workspacePath || "").toLowerCase()) return;
  const activeDrag = ui.whiteboardDrag;
  if (activeDrag && activeDrag.documentId === candidate.documentId && ["card", "resize"].includes(activeDrag.mode)) {
    // Provider progress and elapsed-time updates can arrive several times per
    // second. Rebuilding the canvas while a card is under the pointer replaces
    // the accelerated drag layer and causes visible stalls. Keep the newest
    // candidate in memory and paint it once the pointer interaction commits.
    activeDrag.deferredRender = true;
    return;
  }
  if (patchWhiteboardCandidateProgress(candidate)) return;
  const documentState = activeWhiteboardDocument();
  if (documentState) renderWhiteboard(documentState);
};

const updateWhiteboardGenerationCandidate = (candidateKey, patch = {}, { render = true } = {}) => {
  const candidate = ui.whiteboardCandidates.get(candidateKey);
  if (!candidate) return null;
  const measurementWasActive = whiteboardGenerationMeasurementActive(candidate);
  const jobChanged = Object.prototype.hasOwnProperty.call(patch, "jobId")
    && candidate.jobId
    && patch.jobId
    && String(candidate.jobId) !== String(patch.jobId);
  const normalizedPatch = { ...patch };
  if (patch.status === "complete" && !Object.prototype.hasOwnProperty.call(patch, "cardApplyStage")) {
    normalizedPatch.cardApplyStage = candidate.cardApplyStage || "saving";
  }
  if (!jobChanged && Object.prototype.hasOwnProperty.call(patch, "startedAt") && Number(candidate.startedAt) > 0) {
    const incomingStartedAt = Number(patch.startedAt);
    normalizedPatch.startedAt = Number.isFinite(incomingStartedAt) && incomingStartedAt > 0
      ? Math.min(Number(candidate.startedAt), incomingStartedAt)
      : Number(candidate.startedAt);
  }
  if (!jobChanged && Object.prototype.hasOwnProperty.call(patch, "progressPercent")) {
    normalizedPatch.progressPercent = monotonicProgress(candidate.progressPercent, patch.progressPercent, { minimum: 1, maximum: 100 });
  }
  if (!jobChanged && Object.prototype.hasOwnProperty.call(patch, "providerProgressPercent")) {
    normalizedPatch.providerProgressPercent = monotonicProgress(candidate.providerProgressPercent, patch.providerProgressPercent, { minimum: 0, maximum: 100 });
  }
  const measurementWillBeActive = whiteboardGenerationMeasurementActive({ ...candidate, ...normalizedPatch });
  if (!measurementWasActive && measurementWillBeActive) {
    const startedAt = whiteboardGenerationStartedAt({ ...candidate, ...normalizedPatch });
    normalizedPatch.startedAt = startedAt;
    normalizedPatch.elapsedMs = Math.max(0, Date.now() - startedAt);
  } else if (!jobChanged && Object.prototype.hasOwnProperty.call(patch, "elapsedMs")) {
    normalizedPatch.elapsedMs = monotonicElapsedMs({
      previous: candidate.elapsedMs,
      incoming: patch.elapsedMs,
      startedAt: candidate.startedAt,
    });
  }
  const next = { ...candidate, ...normalizedPatch };
  ui.whiteboardCandidates.set(candidateKey, next);
  if (whiteboardGenerationMeasurementActive(next)) {
    whiteboardGenerationProgressTimers.set(candidateKey, next.startedAt);
    ensureWhiteboardGenerationProgressTicker();
  } else {
    whiteboardGenerationProgressTimers.delete(candidateKey);
    stopWhiteboardGenerationProgressTickerWhenIdle();
  }
  if (render) renderWhiteboardCandidateLocation(next);
  if ((whiteboardGenerationMeasurementActive(next) || next.status === "complete")
    && (Object.prototype.hasOwnProperty.call(patch, "progressPercent")
      || Object.prototype.hasOwnProperty.call(patch, "providerProgressPercent"))) {
    scheduleWhiteboardProgressDisplay(candidateKey);
  }
  return next;
};

const resolveWhiteboardTextRevealDrain = (reveal) => {
  reveal.finishBy = 0;
  const resolvers = reveal.drainResolvers.splice(0);
  resolvers.forEach((resolveDrain) => resolveDrain());
};

const cancelWhiteboardTextReveal = (candidateKey) => {
  const reveal = whiteboardTextRevealAnimations.get(candidateKey);
  if (!reveal) return;
  if (reveal.timer) clearTimeout(reveal.timer);
  reveal.timer = null;
  resolveWhiteboardTextRevealDrain(reveal);
  whiteboardTextRevealAnimations.delete(candidateKey);
};

const ensureWhiteboardTextReveal = (candidateKey) => {
  const current = whiteboardTextRevealAnimations.get(candidateKey);
  if (current) return current;
  const candidate = ui.whiteboardCandidates.get(candidateKey);
  const visibleText = String(candidate?.text ?? "");
  const reveal = {
    visibleText,
    targetText: visibleText,
    characters: [],
    characterIndex: 0,
    timer: null,
    finishBy: 0,
    drainResolvers: [],
  };
  whiteboardTextRevealAnimations.set(candidateKey, reveal);
  return reveal;
};

const updateWhiteboardTextRevealDom = (candidate, text) => {
  if (!candidate || state.activeDocument !== candidate.documentId) return;
  if (normalizedWorkspacePath(state.settings.workspacePath) !== normalizedWorkspacePath(candidate.workspacePath)) return;
  const activeDrag = ui.whiteboardDrag;
  if (activeDrag?.documentId === candidate.documentId && activeDrag?.nodeId === candidate.nodeId && ["card", "resize"].includes(activeDrag.mode)) {
    activeDrag.deferredRender = true;
    return;
  }
  const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(candidate.nodeId)}"]`);
  const field = card?.querySelector(`[data-canvas-text="${CSS.escape(candidate.nodeId)}"]`);
  if (field && field.value !== text) {
    const followsTail = !field.value || field.scrollHeight - field.scrollTop - field.clientHeight < 36;
    field.value = text;
    if (followsTail) field.scrollTop = field.scrollHeight;
  }
  const progress = card?.querySelector(".whiteboard-generation-metrics b");
  if (progress) progress.textContent = `${whiteboardDisplayedProgress(candidate)}%`;
};

const scheduleWhiteboardTextReveal = (candidateKey) => {
  const reveal = whiteboardTextRevealAnimations.get(candidateKey);
  if (!reveal || reveal.timer) return;
  reveal.timer = setTimeout(() => {
    reveal.timer = null;
    const candidate = ui.whiteboardCandidates.get(candidateKey);
    if (!candidate || candidate.channel !== "text" || ["retry_required", "failed"].includes(candidate.status)) {
      cancelWhiteboardTextReveal(candidateKey);
      return;
    }
    const remaining = reveal.characters.length - reveal.characterIndex;
    if (remaining <= 0) {
      reveal.characters = [];
      reveal.characterIndex = 0;
      resolveWhiteboardTextRevealDrain(reveal);
      return;
    }
    const remainingFrames = reveal.finishBy
      ? Math.max(1, Math.ceil((reveal.finishBy - Date.now()) / WHITEBOARD_TEXT_REVEAL_FRAME_MS))
      : remaining;
    const take = reveal.finishBy ? Math.max(1, Math.ceil(remaining / remainingFrames)) : 1;
    reveal.visibleText += reveal.characters.slice(reveal.characterIndex, reveal.characterIndex + take).join("");
    reveal.characterIndex += take;
    const currentProgress = Number(candidate.progressPercent) || 0;
    const textEstimate = 24 + Math.floor(reveal.visibleText.length / 180);
    const next = updateWhiteboardGenerationCandidate(candidateKey, {
      text: reveal.visibleText,
      // CLI stream chunks have very different sizes. Advance at most one
      // point per reveal frame so a large delta cannot make the percentage
      // jump by dozens of points in a single paint.
      progressPercent: Math.min(92, Math.max(currentProgress, Math.min(textEstimate, currentProgress + 1))),
    }, { render: false });
    updateWhiteboardTextRevealDom(next, reveal.visibleText);
    if (reveal.characterIndex < reveal.characters.length) scheduleWhiteboardTextReveal(candidateKey);
    else {
      reveal.characters = [];
      reveal.characterIndex = 0;
      resolveWhiteboardTextRevealDrain(reveal);
    }
  }, WHITEBOARD_TEXT_REVEAL_FRAME_MS);
};

const queueWhiteboardTextReveal = (candidateKey, delta) => {
  const value = String(delta ?? "");
  if (!value) return;
  const reveal = ensureWhiteboardTextReveal(candidateKey);
  reveal.targetText += value;
  for (const character of value) reveal.characters.push(character);
  scheduleWhiteboardTextReveal(candidateKey);
};

const finishWhiteboardTextReveal = async (candidateKey, finalText) => {
  const value = String(finalText ?? "");
  const currentCandidate = ui.whiteboardCandidates.get(candidateKey);
  const visibleTarget = currentCandidate
    && document.visibilityState !== "hidden"
    && state.activeDocument === currentCandidate.documentId
    && normalizedWorkspacePath(state.settings.workspacePath) === normalizedWorkspacePath(currentCandidate.workspacePath);
  if (!visibleTarget) {
    updateWhiteboardGenerationCandidate(candidateKey, { text: value }, { render: false });
    cancelWhiteboardTextReveal(candidateKey);
    return;
  }
  const reveal = ensureWhiteboardTextReveal(candidateKey);
  if (value !== reveal.targetText) {
    if (value.startsWith(reveal.visibleText)) {
      reveal.characters = [...value.slice(reveal.visibleText.length)];
    } else {
      reveal.visibleText = "";
      reveal.characters = [...value];
      const candidate = updateWhiteboardGenerationCandidate(candidateKey, { text: "" }, { render: false });
      updateWhiteboardTextRevealDom(candidate, "");
    }
    reveal.characterIndex = 0;
    reveal.targetText = value;
  }
  const remaining = reveal.characters.length - reveal.characterIndex;
  if (remaining <= 0) {
    const candidate = updateWhiteboardGenerationCandidate(candidateKey, { text: value }, { render: false });
    updateWhiteboardTextRevealDom(candidate, value);
    return;
  }
  reveal.finishBy = Date.now() + Math.min(1_800, Math.max(280, remaining * WHITEBOARD_TEXT_REVEAL_FRAME_MS));
  await new Promise((resolveDrain) => {
    reveal.drainResolvers.push(resolveDrain);
    scheduleWhiteboardTextReveal(candidateKey);
  });
};

const pruneWhiteboardRuntimeCandidates = () => {
  if (ui.whiteboardCandidates.size <= WHITEBOARD_RUNTIME_CANDIDATE_LIMIT) return;
  const currentWorkspace = normalizedWorkspacePath(state.settings.workspacePath);
  const activeStatuses = new Set(["connecting", "queued", "submitting", "running", "polling", "downloading", "cancel_requested", "streaming"]);
  for (const [candidateKey, candidate] of ui.whiteboardCandidates) {
    if (ui.whiteboardCandidates.size <= WHITEBOARD_RUNTIME_CANDIDATE_LIMIT) break;
    const belongsToVisibleBoard = normalizedWorkspacePath(candidate.workspacePath) === currentWorkspace
      && candidate.documentId === state.activeDocument;
    if (belongsToVisibleBoard || activeStatuses.has(candidate.status)) continue;
    cancelWhiteboardTextReveal(candidateKey);
    cancelWhiteboardProgressDisplay(candidateKey);
    whiteboardGenerationProgressTimers.delete(candidateKey);
    ui.whiteboardCandidates.delete(candidateKey);
  }
  stopWhiteboardGenerationProgressTickerWhenIdle();
};

const beginWhiteboardGenerationCandidate = ({ nodeId, workspacePath, documentId, channel, ...candidate }) => {
  const candidateKey = whiteboardCandidateKey(nodeId, { workspacePath, documentId });
  const existing = ui.whiteboardCandidates.get(candidateKey);
  cancelWhiteboardTextReveal(candidateKey);
  // The user-visible timer starts at the click that created this candidate.
  // Connection, queueing, provider generation, download, save, and readback
  // are one continuous lifecycle; only the percentage waits for acceptance.
  const defaultStatus = "connecting";
  const sameJob = Boolean(existing
    && candidate.jobId
    && existing.jobId
    && String(candidate.jobId) === String(existing.jobId));
  const createdAt = Number(existing?.createdAt) || Number(candidate.createdAt) || Date.now();
  const initialProgress = Number(candidate.progressPercent) || 0;
  const provisional = {
    ...candidate,
    nodeId,
    workspacePath,
    documentId,
    channel,
    status: candidate.status || defaultStatus,
  };
  if (provisional.status === "complete" && !provisional.cardApplyStage) provisional.cardApplyStage = "saving";
  const measurementActive = whiteboardGenerationMeasurementActive(provisional);
  const startedAt = measurementActive
    ? whiteboardGenerationStartedAt({ ...provisional, startedAt: sameJob ? existing?.startedAt : candidate.startedAt })
    : 0;
  const initial = {
    ...provisional,
    startedAt,
    createdAt,
    elapsedMs: measurementActive && sameJob
      ? monotonicElapsedMs({ previous: existing?.elapsedMs, incoming: candidate.elapsedMs, startedAt })
      : measurementActive ? Math.max(0, Number(candidate.elapsedMs) || 0) : 0,
    progressPercent: sameJob ? monotonicProgress(existing.progressPercent, initialProgress, { minimum: 1, maximum: 100 }) : initialProgress,
    displayProgressPercent: sameJob && Number.isFinite(Number(existing?.displayProgressPercent))
      ? Number(existing.displayProgressPercent)
      : 0,
    displayProviderProgressPercent: sameJob && Number.isFinite(Number(existing?.displayProviderProgressPercent))
      ? Number(existing.displayProviderProgressPercent)
      : 0,
    ...(sameJob && !Object.prototype.hasOwnProperty.call(candidate, "providerProgressPercent") && Number.isFinite(Number(existing.providerProgressPercent))
      ? { providerProgressPercent: existing.providerProgressPercent }
      : {}),
  };
  ui.whiteboardCandidates.set(candidateKey, initial);
  if (measurementActive) scheduleWhiteboardProgressDisplay(candidateKey);
  pruneWhiteboardRuntimeCandidates();
  if (!measurementActive) return { candidateKey, startedAt };
  whiteboardGenerationProgressTimers.set(candidateKey, startedAt);
  ensureWhiteboardGenerationProgressTicker();
  return { candidateKey, startedAt };
};

const beginWhiteboardSubmissionFeedback = ({ nodeId, workspacePath, documentId, channel, prompt = "" }) => {
  const startedAt = Date.now();
  const submissionAttemptId = uid("media-submission-attempt");
  const result = beginWhiteboardGenerationCandidate({
    nodeId,
    workspacePath,
    documentId,
    channel,
    kind: channel,
    text: "",
    prompt,
    status: "connecting",
    createdAt: startedAt,
    startedAt,
    submissionAttemptId,
  });
  const documentState = state.activeDocument === documentId ? activeWhiteboardDocument() : null;
  if (documentState) renderWhiteboard(documentState);
  return { ...result, submissionAttemptId };
};

const cancelWhiteboardSubmissionFeedback = (candidateKey, { workspacePath, documentId } = {}) => {
  stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
  renderWhiteboardCandidateLocation({ workspacePath, documentId });
};

const stopWhiteboardGenerationCandidate = (candidateKey, { remove = false, complete = false } = {}) => {
  cancelWhiteboardTextReveal(candidateKey);
  whiteboardGenerationProgressTimers.delete(candidateKey);
  stopWhiteboardGenerationProgressTickerWhenIdle();
  const candidate = ui.whiteboardCandidates.get(candidateKey);
  const elapsedMs = candidate?.startedAt
    ? Math.max(1, monotonicElapsedMs({ previous: candidate.elapsedMs, startedAt: candidate.startedAt }))
    : Math.max(0, Number(candidate?.elapsedMs) || 0);
  if (remove) ui.whiteboardCandidates.delete(candidateKey);
  else if (candidate) ui.whiteboardCandidates.set(candidateKey, {
    ...candidate,
    elapsedMs,
    ...(complete ? { progressPercent: 100, status: "complete" } : {}),
  });
  if (remove) cancelWhiteboardProgressDisplay(candidateKey);
  else if (candidate && complete) scheduleWhiteboardProgressDisplay(candidateKey);
  return elapsedMs;
};

const whiteboardGenerationJobTarget = ({ workspaceKind = state.workspaceKind, workspacePath = state.settings.workspacePath, documentId = state.activeDocument, nodeId } = {}) => ({
  workspaceKind,
  workspacePath,
  documentId,
  nodeId,
});

const postGenerationJobAction = async (path, body = {}, { transportRetries = 0 } = {}) => {
  let lastError = null;
  for (let attempt = 0; attempt <= Math.max(0, Number(transportRetries) || 0); attempt += 1) {
    try {
      const response = await fetch(path, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) {
        const error = new Error(payload.message || "生成任务状态写入失败");
        error.code = String(payload.code || "");
        error.details = payload.details || {};
        error.status = response.status;
        error.responseReceived = true;
        throw error;
      }
      const job = payload.job;
      if (!job || typeof job !== "object" || !String(job.id || "").trim() || !String(job.status || "").trim()) {
        const error = new Error("生成任务状态暂时未返回，正在重新连接任务");
        error.code = "GENERATION_JOB_RESPONSE_INVALID";
        error.status = response.status;
        error.responseReceived = true;
        throw error;
      }
      return job;
    } catch (error) {
      lastError = error;
      const transportFailure = error instanceof TypeError
        || error instanceof SyntaxError
        || /fetch|network|socket|connection/i.test(String(error?.message || ""));
      if (attempt >= transportRetries || !transportFailure) throw error;
    }
  }
  throw lastError ?? new Error("生成任务状态写入失败");
};

const whiteboardMediaSubmissionFlights = new Map();
const createWhiteboardMediaGenerationJob = ({ channel, target, request, forceNewGeneration = false, regenerationOfJobId = "" }) => {
  const submissionId = String(request?.submissionId || uid("media-submission"));
  const targetsWhiteboardNode = target?.targetType === "whiteboard-node"
    || (!target?.targetType && Boolean(target?.nodeId));
  const targetsSingleConversationImage = target?.targetType === "conversation-message"
    && !String(target?.mediaBatchId || "").trim();
  const normalizedTarget = channel === "image" && target?.targetType !== "capability-smoke" && !targetsWhiteboardNode && !targetsSingleConversationImage
    ? {
        ...target,
        mediaBatchId: String(target?.mediaBatchId || `image-batch-${submissionId}`),
        mediaBatchIndex: Math.max(1, Number(target?.mediaBatchIndex) || 1),
        mediaBatchTotal: Math.max(1, Number(target?.mediaBatchTotal) || 1),
        mediaBatchLabel: String(target?.mediaBatchLabel || "").trim(),
      }
    : target;
  const flightKey = JSON.stringify({
    submissionId,
    channel,
    target: normalizedTarget,
    prompt: request?.prompt || "",
    aspectRatio: request?.aspectRatio || "",
    quality: request?.quality || request?.resolution || "",
    duration: request?.duration || 0,
    audioType: request?.audioType || "",
    voiceId: request?.voiceId || "",
    language: request?.language || "",
    speed: request?.speed || 0,
    format: request?.format || "",
    sampleRate: request?.sampleRate || 0,
    imageCount: Math.max(1, Math.min(4, Number(request?.imageCount) || 1)),
    settings: {
      connectionId: request?.settings?.connectionId || request?.settings?.id || "",
      provider: request?.settings?.provider || "",
      adapter: request?.settings?.adapter || "",
      model: request?.settings?.model || "",
    },
    referenceMedia: (request?.referenceMedia || []).map((item) => item.relativePath || item.id || ""),
  });
  if (whiteboardMediaSubmissionFlights.has(flightKey)) return whiteboardMediaSubmissionFlights.get(flightKey);
  const submittedRequest = {
    ...request,
    submissionId,
    // Persist a credential-safe signature with every media job. Recovery can
    // therefore rebind capability evidence even when the active workspace
    // has not hydrated the full profile yet.
    capabilityProfileSignature: request?.capabilityProfileSignature
      || mediaCapabilityProfileSignature(channel, request?.settings || {}),
  };
  const submissionBody = {
    channel,
    target: normalizedTarget,
    submissionId,
    forceNewGeneration: forceNewGeneration === true,
    regenerationOfJobId: String(regenerationOfJobId || ""),
    request: submittedRequest,
  };
  const candidateKey = normalizedTarget?.nodeId
    ? whiteboardCandidateKey(normalizedTarget.nodeId, {
        workspacePath: normalizedTarget.workspacePath,
        documentId: normalizedTarget.documentId,
      })
    : "";
  const operation = recoverUnknownMediaSubmission(
    () => postGenerationJobAction("/api/generation/jobs/media", submissionBody),
    {
      onUncertain: ({ error }) => {
        if (!candidateKey || !ui.whiteboardCandidates.has(candidateKey)) return;
        updateWhiteboardGenerationCandidate(candidateKey, {
          status: "connecting",
          submissionOutcomeUnknown: true,
          connectionInterrupted: true,
          connectionError: error.message,
          error: "正在确认后台任务；不会重复提交或重复扣费",
        });
      },
      onRecovered: () => {
        if (!candidateKey || !ui.whiteboardCandidates.has(candidateKey)) return;
        updateWhiteboardGenerationCandidate(candidateKey, {
          submissionOutcomeUnknown: false,
          connectionInterrupted: false,
          connectionError: "",
          error: "",
        });
      },
    },
  ).finally(() => whiteboardMediaSubmissionFlights.delete(flightKey));
  whiteboardMediaSubmissionFlights.set(flightKey, operation);
  return operation;
};
const createWhiteboardClientGenerationJob = ({ channel = "text", target, request }) => postGenerationJobAction("/api/generation/jobs/client", { channel, target, request });
const heartbeatWhiteboardGenerationJob = (jobId, progressPercent) => postGenerationJobAction(`/api/generation/jobs/${encodeURIComponent(jobId)}/heartbeat`, { progressPercent });
const completeWhiteboardGenerationJob = (jobId, result) => postGenerationJobAction(`/api/generation/jobs/${encodeURIComponent(jobId)}/complete`, { result });
const failWhiteboardGenerationJob = (jobId, message, retryRequired = true) => postGenerationJobAction(`/api/generation/jobs/${encodeURIComponent(jobId)}/fail`, { message, retryRequired });
const markWhiteboardGenerationJobApplied = (jobId, resultAssetId = "", cardReadback = null) => postGenerationJobAction(`/api/generation/jobs/${encodeURIComponent(jobId)}/applied`, { resultAssetId, ...(cardReadback ? { cardReadback } : {}) });

const MEDIA_JOB_ACTIVE_STATUSES = new Set(["queued", "submitting", "running", "polling", "downloading", "cancel_requested"]);
const MEDIA_JOB_ATTENTION_STATUSES = new Set(["waiting_credentials", "waiting_storage", "retry_required", "failed", "reconciliation_required"]);
const MEDIA_JOB_POLL_STOP_STATUSES = new Set(["complete", "cancelled", ...MEDIA_JOB_ATTENTION_STATUSES]);
const mediaConversationProgressSaves = new Map();
const mediaDocumentArtifactProgressSaves = new Map();
const mediaRecoveryMessageSignatures = new Map();
const conversationMediaApplyQueues = new Map();
const mediaGenerationActionFlights = new Map();
const whiteboardMediaSubmissionLocks = new Map();

const whiteboardMediaSubmissionKey = ({ channel, nodeId, documentId = state.activeDocument, workspacePath = state.settings.workspacePath } = {}) => [
  String(workspacePath || "").replace(/\\/g, "/").toLowerCase(),
  String(documentId || ""),
  String(nodeId || ""),
  String(channel || ""),
].join("::");

const acquireWhiteboardMediaSubmissionLock = (key, channel = "") => {
  if (!key || whiteboardMediaSubmissionLocks.has(key)) return "";
  const token = uid("media-submit-lock");
  whiteboardMediaSubmissionLocks.set(key, {
    token,
    channel: String(channel || key.split("::").at(-1) || ""),
    acquiredAt: Date.now(),
  });
  return token;
};

const releaseWhiteboardMediaSubmissionLock = (key, token = "") => {
  if (!key) return false;
  const current = whiteboardMediaSubmissionLocks.get(key);
  if (!current || (token && current.token !== token)) return false;
  whiteboardMediaSubmissionLocks.delete(key);
  return true;
};

const whiteboardMediaSubmissionPendingForChannel = (channel) => [...whiteboardMediaSubmissionLocks.values()]
  .some((lock) => lock?.channel === channel);

const setWhiteboardGenerationSubmitBusy = (form, busy) => {
  if (!form) return;
  const button = form.querySelector('button[type="submit"]');
  if (button) {
    button.disabled = busy;
    button.setAttribute("aria-busy", String(busy));
  }
  form.setAttribute("aria-busy", String(busy));
  form.dataset.generationSubmitBusy = String(busy);
};

const finishWhiteboardMediaSubmissionAttempt = ({ key, token, channel, form }) => {
  const released = releaseWhiteboardMediaSubmissionLock(key, token);
  if (released && !whiteboardMediaSubmissionPendingForChannel(channel)) {
    setWhiteboardGenerationSubmitBusy(form, false);
  }
  return released;
};

const releaseWhiteboardMediaSubmissionLockForJob = (job) => {
  const channel = String(job?.channel || "");
  if (!['image', 'video', 'audio'].includes(channel)) return;
  const target = job?.target || {};
  const key = whiteboardMediaSubmissionKey({
    channel,
    nodeId: target.nodeId,
    documentId: target.documentId,
    workspacePath: target.workspacePath,
  });
  // Submission locks now protect only the click-to-durable-job handshake.
  // A late terminal update from an older job must never release a newer
  // submission's token or clear its busy state.
  if (whiteboardMediaSubmissionLocks.has(key)) return;
  const form = channel === "image"
    ? elements.whiteboardImageForm
    : channel === "video" ? elements.whiteboardVideoForm : elements.whiteboardAudioForm;
  if (form?.dataset.nodeId === String(target.nodeId || "")
    && !whiteboardMediaSubmissionPendingForChannel(channel)) {
    setWhiteboardGenerationSubmitBusy(form, false);
  }
};

const mediaGenerationProfileLabel = (job = {}) => {
  const current = job && typeof job === "object" ? job : {};
  const settings = current.request?.settings ?? {};
  const explicit = String(settings.remarkName || "").trim();
  if (explicit) return explicit;
  const connectionId = String(settings.connectionId || settings.id || "");
  const known = {
    "video-dreamina-cli": "柏物语",
    "video-dreamina-cli-chenan": "陈安",
    "video-dreamina-cli-guobazai": "锅巴仔",
    "video-dreamina-cli-xiaoyujie": "小鱼姐",
    "video-dreamina-cli-tashuo-juyougeng": "她说剧有梗",
  };
  return known[connectionId] || String(settings.name || settings.provider || "当前连接").trim();
};

const mediaGenerationErrorText = (job = {}) => {
  const current = job && typeof job === "object" ? job : {};
  const raw = String(current.error || "").trim();
  const code = String(current.providerErrorCode || current.errorCode || "").trim().toUpperCase();
  const settings = current.request?.settings ?? {};
  const dreamina = ["即梦", "dreamina"].includes(String(settings.provider || "").trim().toLowerCase())
    || code.startsWith("DREAMINA_") || /authsdk:\s*not logged in/i.test(raw);
  if (dreamina && (code || raw)) return `即梦配置“${mediaGenerationProfileLabel(current)}”：${dreaminaFailureDisplayText({
    code,
    message: raw,
    providerTaskId: current.providerTaskId,
    submissionState: current.submissionState,
  })}`;
  return raw;
};

const dreaminaFailureInput = ({ error = null, job = null } = {}) => ({
  code: job?.providerErrorCode || job?.errorCode || error?.code || error?.errorCode || "",
  message: job?.error || error?.message || "",
  providerTaskId: job?.providerTaskId || "",
  submissionState: job?.submissionState || "",
});

const dreaminaFailureNeedsVerification = ({ error = null, job = null } = {}) => (
  dreaminaFailureRequiresAccountVerification(dreaminaFailureInput({ error, job }))
);

const mediaGenerationPhaseText = (job = {}, { connectionInterrupted = false } = {}) => {
  const current = job && typeof job === "object" ? job : {};
  const status = String(current.status || "").trim();
  const localTaskId = String(current.id || current.jobId || "").trim();
  if (!status) return uiText("正在连接生成任务");
  if (current.submissionOutcomeUnknown === true) {
    return uiText("正在确认后台任务；不会重复提交或重复扣费");
  }
  const providerTaskId = String(current.providerTaskId || "").trim();
  const providerErrorCode = String(current.providerErrorCode || current.errorCode || "").trim().toUpperCase();
  if (providerErrorCode === "DREAMINA_PROVIDER_SESSION_RESTORE_PENDING") {
    return `${uiText("正在恢复查询会话；只续接原任务，不会重新提交")}${providerTaskId ? ` · ${uiText("厂商任务")} ${providerTaskId.slice(-8)}` : ""}`;
  }
  const providerAccepted = whiteboardMediaProviderAccepted({ ...current, channel: current.channel || "image" });
  const directGeneration = whiteboardProviderIsDirectGeneration(current);
  if (whiteboardGenerationConnectionPhase({ ...current, channel: current.channel || "image" })
    && ["connecting", "submitting", "running", "polling"].includes(status)) {
    return uiText("正在连接生成服务");
  }
  if (!localTaskId && ["submitting", "running", "polling"].includes(status)) return uiText("正在生成");
  const taskLabel = localTaskId
    ? ` · ${uiText("神思任务")} ${localTaskId.slice(-8)}${providerTaskId ? ` · ${uiText("厂商任务")} ${providerTaskId.slice(-8)}` : ""}`
    : "";
  const billingLabel = current.billingRisk
    ? uiText("费用状态待核验")
    : providerAccepted
      ? uiText("已提交厂商，可能已收费")
      : uiText("未收费");
  if (current.userStoppedAt || current.resultSuppressed || current.userStopped) {
    const cancelLabel = current.status === "cancelled" || current.providerStatus === "cancelled"
      ? uiText("用户已停止 · 厂商取消已确认")
      : current.status === "waiting_credentials"
        ? uiText("用户已停止 · 取消意图已保存，等待恢复原凭据")
        : current.status === "cancel_requested"
          ? uiText("用户已停止 · 正在后台核验厂商取消结果")
          : uiText("用户已停止 · 后台仍在跟踪任务结果");
    return `${cancelLabel} · ${billingLabel}${taskLabel}`;
  }
  if (connectionInterrupted) return `${uiText("本地连接暂断，后台任务仍在运行")} · ${billingLabel}${taskLabel}`;
  const lifecycleStage = mediaResultLifecycleStage(current);
  if (lifecycleStage === "provider_complete_retrieving") {
    const detail = mediaGenerationErrorText(current);
    return `${uiText("厂商已完成，正在取回结果")}${detail ? ` · ${detail}` : ""} · ${billingLabel}${taskLabel}`;
  }
  if (lifecycleStage === "asset_saved_card_pending") return `${uiText("结果已保存，正在回填卡片")} · ${billingLabel}${taskLabel}`;
  if (lifecycleStage === "card_complete") return `${uiText("卡片回读成功，任务完成")} · ${billingLabel}${taskLabel}`;
  const capacityLimited = String(current.providerErrorCode || "").toUpperCase() === "DREAMINA_CONCURRENCY_LIMIT"
    || /ExceedConcurrencyLimit/i.test(String(current.error || ""));
  if (current.status === "queued" && !providerTaskId && current.submissionState === "not_submitted") {
    const retryAt = Date.parse(current.nextPollAt || "");
    const retryIn = Number.isFinite(retryAt) ? Math.max(0, Math.ceil((retryAt - Date.now()) / 1000)) : 0;
    const prefix = capacityLimited ? uiText("即梦并发名额已满") : uiText("本地排队，尚未提交厂商");
    return `${prefix} · ${uiText("未收费")}${retryIn > 0 ? ` · ${retryIn}${uiText("秒后重试")}` : ""}${taskLabel}`;
  }
  if (current.status === "cancel_requested" && /不支持取消/i.test(String(current.error || ""))) return `${uiText("取消请求无法送达厂商，任务仍在跟踪")} · ${billingLabel}${taskLabel}`;
  const queuePosition = Number.isFinite(Number(current.providerQueuePosition)) && current.providerQueuePosition !== null
    ? ` ${Math.max(0, Number(current.providerQueuePosition)).toLocaleString()}${Number.isFinite(Number(current.providerQueueLength)) && current.providerQueueLength !== null ? `/${Math.max(0, Number(current.providerQueueLength)).toLocaleString()}` : ""}`
    : "";
  if (directGeneration && !whiteboardProviderQueueVisible(current)
    && ["queued", "polling", "running"].includes(current.status) && current.providerStatus === "queued") {
    return `${uiText("正在生成")} · ${billingLabel}${taskLabel}`;
  }
  if (["queued", "polling", "running"].includes(current.status) && whiteboardProviderQueueVisible(current)) {
    return queuePosition ? `${uiText("已提交厂商，正在排队")}${queuePosition} · ${billingLabel}${taskLabel}` : `${uiText("已提交厂商，正在排队")} · ${billingLabel}${taskLabel}`;
  }
  const labels = {
    connecting: "正在连接生成服务",
    queued: providerAccepted ? "已提交厂商，等待生成" : "本地排队，尚未提交厂商",
    submitting: providerAccepted ? "正在生成" : "正在连接生成服务",
    running: "正在生成",
    polling: "正在生成",
    downloading: "厂商已完成，正在下载结果",
    cancel_requested: "已停止，正在后台核验取消结果",
    waiting_credentials: current.desiredAction === "cancel" ? "取消请求已保存，请重新核验当前账号" : "任务已保留，请重新核验当前账号",
    waiting_storage: "生成结果已保留，正在等待可用存储空间",
    retry_required: current.providerStatus === "reconciling"
      ? "正在确认原任务是否已经生成；不会重复提交或重复扣费"
      : current.billingRisk ? "正在确认原任务结果，暂不重复提交" : "任务需要继续处理",
    reconciliation_required: "暂时无法确认原任务结果，请稍后重新检查",
    failed: "生成失败",
    cancelled: "媒体任务已取消",
    complete: "结果已保存，正在回填卡片",
  };
  const label = uiText(labels[current.status] || "生成任务进行中");
  return `${label} · ${billingLabel}${taskLabel}`;
};

const mediaGenerationSettingsForJob = (job) => {
  const requested = job?.request?.settings ?? {};
  const profileId = requested.connectionId || requested.id || "";
  if (profileId) {
    const keys = generationProfileKeys(job.channel);
    const exactProfile = (state.settings[keys?.list] ?? []).find((profile) => profile.id === profileId);
    if (!exactProfile) return null;
  }
  const settings = generationSettingsForChannel(state.settings, job.channel, profileId, requested.model ? { model: requested.model } : {});
  if (!settings
    || (requested.provider && settings.provider !== requested.provider)
    || (requested.adapter && settings.adapter !== requested.adapter)
    || (requested.protocol && settings.protocol !== requested.protocol)) return null;
  return { ...settings, [`${job.channel}Channel`]: true };
};

const capabilityEvidenceTimestamp = (job = {}) => {
  const candidates = [job.completedAt, job.failedAt, job.cancelledAt, job.updatedAt, job.createdAt]
    .map((value) => Date.parse(String(value || "")))
    .filter(Number.isFinite);
  return candidates.length ? Math.max(...candidates) : Date.now();
};

const capabilityEvidenceIsoTimestamp = (job = {}) => new Date(capabilityEvidenceTimestamp(job)).toISOString();

const capabilitySettingsForJob = (job = {}) => {
  const requested = job?.request?.settings ?? {};
  const id = String(requested.connectionId || requested.id || job.profileId || "").trim();
  if (!id) return null;
  const channel = String(job.channel || "");
  const current = mediaGenerationSettingsForJob(job);
  if (current) return current;
  return {
    ...requested,
    id,
    connectionId: id,
    provider: String(requested.provider || ""),
    adapter: String(requested.adapter || ""),
    protocol: String(requested.protocol || ""),
    model: String(requested.model || ""),
    [`${channel}Channel`]: true,
  };
};

const capabilitySignatureForJob = (job = {}, settings = null) => String(
  job?.request?.capabilityProfileSignature
  || job?.request?.settings?.capabilityProfileSignature
  || (settings ? mediaCapabilityProfileSignature(job.channel, settings) : ""),
);

const recordCustomTextGenerationCapability = (profile, error = null, { agent = false, checkedAt = "" } = {}) => {
  if (!profile?.id) return false;
  if (error) {
    if (publicTextModelProbeIsolated(profile) && publicTextFailureIsRequestSpecific(error)) return false;
    if (!publicTextModelProbeIsolated(profile) && !customCapabilityFailureIsProviderEvidence(error)) return false;
    storeCustomCapabilityFailure("text", profile, error, { generationResult: true, checkedAt });
    if (agent) {
      const failedProbe = textModelCapabilityProbe(profile);
      if (failedProbe) storeTextModelCapabilityProbe(profile, { ...failedProbe, agentVerified: false });
    }
  } else {
    const evidenceCheckedAt = checkedAt || new Date().toISOString();
    const previous = textModelCapabilityProbe(profile) ?? {};
    if (previous.generationCapabilityState === "available"
      && previous.generationCapabilityCheckedAt === evidenceCheckedAt
      && previous.profileSignature === textCapabilityProfileSignature(profile)) return false;
    storeTextModelCapabilityProbe(profile, {
      ...previous,
      connected: true,
      realInference: true,
      ...(agent ? { agentVerified: true, toolRoundTripVerified: true } : {}),
      modelCatalogChecked: true,
      models: [...new Set([...(previous.models ?? []), profile.model].filter(Boolean))],
      capabilityState: "available",
      generationCapabilityState: "available",
      generationCapabilityCheckedAt: evidenceCheckedAt,
      generationStatusDetail: "最近一次真实文字生成成功",
      verificationLevel: "generation_success",
      providerErrorCode: "",
      statusCode: 0,
      retryAfterMs: 0,
      checkedAt: evidenceCheckedAt,
    });
  }
  persistCapabilityProbes();
  renderCustomApiCapabilityStatus();
  renderQuickModelSelector();
  return true;
};

const recordCustomGenerationJobCapability = (job) => {
  if (!job?.channel || !CUSTOM_API_CAPABILITY_CHANNELS.includes(job.channel)) return false;
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped || job.status === "cancelled") return false;
  const profile = capabilitySettingsForJob(job);
  if (!profile || !customCapabilityProvider(profile, job.channel)) return false;
  const evidenceCheckedAt = capabilityEvidenceIsoTimestamp(job);
  const profileSignature = job.channel === "text" ? "" : capabilitySignatureForJob(job, profile);
  if (job.status === "complete") {
    if (job.channel === "text") {
      const previous = textModelCapabilityProbe(profile) ?? {};
      if (previous.generationCapabilityState === "available"
        && previous.generationCapabilityCheckedAt === evidenceCheckedAt
        && (!profileSignature || previous.profileSignature === profileSignature)) return false;
      storeTextModelCapabilityProbe(profile, {
        ...previous,
        connected: true,
        realInference: true,
        modelCatalogChecked: true,
        models: [...new Set([...(previous.models ?? []), profile.model].filter(Boolean))],
        capabilityState: "available",
        generationCapabilityState: "available",
        generationCapabilityCheckedAt: evidenceCheckedAt,
        generationStatusDetail: "最近一次真实文字生成成功",
        statusDetail: "当前配置已完成真实文字生成",
        verificationLevel: "generation_success",
        providerErrorCode: "",
        statusCode: 0,
        retryAfterMs: 0,
        checkedAt: evidenceCheckedAt,
      });
    } else {
      const previous = ui.mediaCapabilityProbes[mediaCapabilityProbeKey(job.channel, profile.id)] ?? {};
      if (previous.generationCapabilityState === "available"
        && previous.generationCapabilityCheckedAt === evidenceCheckedAt
        && (!profileSignature || previous.profileSignature === profileSignature)) return false;
      const probe = storeMediaCapabilityProbe(job.channel, profile, {
        ...previous,
        connected: true,
        available: true,
        capabilityState: "available",
        generationCapabilityState: "available",
        generationCapabilityCheckedAt: evidenceCheckedAt,
        generationStatusDetail: `最近一次真实${channelTitle(job.channel)}生成成功`,
        softwareIntegrated: true,
        generationPermissionChecked: true,
        statusDetail: `当前配置已完成真实${channelTitle(job.channel)}生成`,
        verificationLevel: "generation_success",
        checkedAt: evidenceCheckedAt,
      }, { profileSignatureOverride: profileSignature });
      probe.generationPermissionChecked = true;
    }
    persistCapabilityProbes();
    renderCustomApiCapabilityStatus();
    return true;
  }
  if (job.status === "waiting_credentials") {
    const error = new Error(String(job.error || "当前生成任务需要重新验证连接凭据"));
    error.code = String(job.providerErrorCode || job.code || job.errorCode || "MISSING_CREDENTIALS");
    error.statusCode = Number(job.statusCode) || 401;
    storeCustomCapabilityFailure(job.channel, profile, error, {
      generationResult: true,
      checkedAt: evidenceCheckedAt,
      profileSignatureOverride: profileSignature,
    });
    persistCapabilityProbes();
    renderCustomApiCapabilityStatus();
    return true;
  }
  if (MEDIA_JOB_ATTENTION_STATUSES.has(job.status) && String(job.error || "").trim()) {
    const error = new Error(String(job.error));
    error.code = String(job.providerErrorCode || job.code || job.errorCode || "");
    error.statusCode = Number(job.statusCode) || 0;
    error.availableModels = Array.isArray(job.capabilityProbe?.models) ? job.capabilityProbe.models : [];
    if (!customCapabilityFailureIsProviderEvidence(error)) return false;
    storeCustomCapabilityFailure(job.channel, profile, error, {
      generationResult: true,
      checkedAt: evidenceCheckedAt,
      profileSignatureOverride: profileSignature,
    });
    persistCapabilityProbes();
    renderCustomApiCapabilityStatus();
    return true;
  }
  return false;
};

const mediaGenerationActionMarkup = ({
  jobId = "",
  status = "",
  availableActions = {},
  desiredAction = "",
  providerErrorCode = "",
  errorCode = "",
  error = "",
  providerTaskId = "",
  submissionState = "",
} = {}, { compact = false } = {}) => {
  if (!jobId) return "";
  const buttons = [];
  const accountVerificationRequired = dreaminaFailureRequiresAccountVerification({
    code: providerErrorCode || errorCode,
    message: error,
    providerTaskId,
    submissionState,
  });
  if (String(status || "") === "waiting_credentials" && accountVerificationRequired) {
    buttons.push(`<button class="media-job-reverify" type="button" data-whiteboard-candidate-action data-media-job-action="reverify" data-media-job-id="${escapeHtml(jobId)}" title="${escapeHtml(uiText("重新核验当前生成配置"))}">${icon("\uE77B", uiText("核验账号"))}<span>${escapeHtml(uiText("核验账号"))}</span></button>`);
  }
  const primaryAction = mediaGenerationActionPresentation({ status, availableActions });
  if (primaryAction) {
    const label = uiText(primaryAction.label);
    const title = availableActions.autoReconcileProviderTask
      ? uiText("按原连接、幂等键、提示词、任务类型和创建时间自动查找结果，不会再次提交计费任务")
      : availableActions.resumeOriginal
        ? uiText("使用已保存的厂商任务 ID 找回并下载原结果，不会重新提交计费任务")
        : primaryAction.recovery
          ? uiText("原提交结果仍待核对；找回时沿用原幂等键，并在操作前提示核对厂商后台")
          : uiText("原任务已经明确失败；重新生成前会再次确认，并保留原提示词和引用范围");
    const className = primaryAction.action === "reconcile"
      ? "media-job-reconcile"
      : primaryAction.confirmNewSubmission ? "media-job-resubmit warning" : "media-job-resume";
    buttons.push(`<button class="${className}" type="button" data-whiteboard-candidate-action data-media-job-action="${escapeHtml(primaryAction.action)}" data-media-job-id="${escapeHtml(jobId)}"${primaryAction.confirmNewSubmission ? ' data-confirm-new-submission="true"' : ""} title="${escapeHtml(title)}">${icon(primaryAction.recovery ? "\uE8B7" : "\uE768", label)}<span>${escapeHtml(label)}</span></button>`);
  }
  if (availableActions.dismissCompleted || availableActions.dismissUncertain) {
    const completed = availableActions.dismissCompleted === true;
    const label = uiText(completed ? "放弃并隐藏" : "忽略旧任务");
    const title = uiText(completed
      ? "放弃将结果回填到原卡片并隐藏此任务；生成结果、任务记录和费用信息仍保留，不会重新生成或重复扣费"
      : "停止跟踪无法确认的旧提交并释放当前卡片；不会删除提示词、参考或任务记录");
    buttons.push(`<button class="media-job-dismiss warning" type="button" data-whiteboard-candidate-action data-media-job-action="dismiss" data-media-job-id="${escapeHtml(jobId)}" title="${escapeHtml(title)}">${icon("\uE711", label)}<span>${escapeHtml(label)}</span></button>`);
  }
  if (desiredAction === "cancel" && !["complete", "cancelled"].includes(status)) {
    buttons.push(`<span class="media-job-cancel-pending" role="status">${icon("\uE73E", uiText("已停止"))}<span>${escapeHtml(uiText("已停止"))}</span></span>`);
  } else if (!availableActions.dismissUncertain && !availableActions.dismissCompleted && (availableActions.stop || availableActions.cancel) && !["complete", "cancelled"].includes(status)) {
    buttons.push(`<button class="media-job-cancel" type="button" data-whiteboard-candidate-action data-media-job-action="cancel" data-media-job-id="${escapeHtml(jobId)}" title="${escapeHtml(uiText("停止当前媒体任务"))}">${icon("\uE71A", uiText("停止任务"))}<span>${escapeHtml(uiText("停止任务"))}</span></button>`);
  }
  return buttons.length ? `<div class="media-generation-actions ${compact ? "compact" : ""}">${buttons.join("")}</div>` : "";
};

const updateMediaJobTargetAfterAction = (job) => {
  if (!job?.id) return;
  const userStopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  if (job.target?.nodeId && (userStopped || !whiteboardMediaJobHoldsCard(job))) {
    releaseWhiteboardMediaSubmissionLockForJob(job);
  }
  if (job.target?.targetType === "conversation-message") {
    if (userStopped) {
      showInterruptedConversationMediaJob(job);
      return;
    }
    const target = conversationMessageTarget(job);
    if (target) {
      const message = target.messages[target.index];
      message.pending = MEDIA_JOB_ACTIVE_STATUSES.has(job.status);
      message.execution = {
        ...(message.execution ?? {}),
        status: message.pending ? "running" : job.status,
        mediaJobStatus: job.status,
        generationJobId: job.id,
        progressPercent: Number(job.progressPercent) || 1,
        mediaAvailableActions: job.availableActions ?? {},
        desiredAction: job.desiredAction || "run",
        result: job.status === "cancel_requested" ? "已取消" : "正在续接原媒体任务",
      };
      target.conversation.messages = clone(target.messages);
      if (target.conversation.id === state.activeConversationId) renderMessages();
      persist();
    }
    monitorConversationMediaJob(job);
    return;
  }
  if (job.target?.targetType === "document-artifact") {
    if (userStopped) {
      showInterruptedDocumentArtifactJob(job);
      return;
    }
    updateDocumentArtifactJobProgress(job, { persistNow: true });
    monitorDocumentArtifactJob(job);
    return;
  }
  if (job.target?.targetType === "capability-smoke") {
    updatePaidMediaSmokeJob(job);
    monitorPaidMediaSmokeJob(job);
    return;
  }
  if (userStopped) {
    showInterruptedWhiteboardGenerationJob(job);
    if (activeWhiteboardDocument()) renderWhiteboard(activeWhiteboardDocument());
    return;
  }
  monitorWhiteboardGenerationJob(job);
  if (activeWhiteboardDocument()) renderWhiteboard(activeWhiteboardDocument());
};

const controlMediaGenerationJob = async (jobId, action, { allowNewSubmission = false } = {}) => {
  const flightKey = `${jobId}:${action}`;
  if (mediaGenerationActionFlights.has(flightKey)) return mediaGenerationActionFlights.get(flightKey);
  const operation = (async () => {
  const current = await fetchWhiteboardGenerationJob(jobId);
  const actions = current.availableActions ?? {};
  if (action === "reconcile") {
    if (!actions.autoReconcileProviderTask) throw new Error(uiText("当前任务缺少可自动找回的原始记录"));
  }
  if (action === "dismiss") {
    const completed = actions.dismissCompleted === true;
    if (!actions.dismissUncertain && !completed) throw new Error(uiText("当前任务不属于可忽略的待核对提交"));
    const warning = completed
      ? uiText("确认放弃把已生成结果回填到原卡片并隐藏此任务？生成结果、任务记录和费用信息仍会保留，不会重新生成或重复扣费。")
      : uiText("确认忽略这个无法核对的旧任务并释放当前卡片？神思不会删除提示词、参考或任务记录，也不会再次提交；但如果厂商此前实际已经受理，仍可能产生远端结果或费用。忽略后可以切换配置并重新生成。");
    if (!window.confirm(warning)) return null;
  }
  if (action === "resume" && (actions.confirmedResubmit || actions.replaceLegacy || allowNewSubmission)) {
    const warning = uiText(actions.replaceLegacy
      ? "此旧任务没有可验证的厂商任务 ID和原始幂等键，不能续接。继续将创建一个全新任务，可能再次计费。请先在厂商后台确认没有仍在运行的旧任务。"
      : "当前记录没有厂商任务 ID，提交结果可能未知。继续会沿用原幂等键重新提交，但仍应先在厂商后台核查，避免重复计费。");
    if (!window.confirm(`${warning}\n\n${uiText("确认已经核查并继续？")}`)) return null;
    allowNewSubmission = true;
  }
  if (action === "cancel" && current.cancelPending) return current;
  if (action === "cancel") {
    const notSubmitted = !current.providerTaskId && current.submissionState === "not_submitted";
    const providerQueued = Boolean(current.providerTaskId) && current.providerStatus === "queued";
    const warning = notSubmitted
      ? "当前任务尚未提交给厂商，停止后不会消耗积分。确认停止？"
      : providerQueued
        ? "当前任务仍在厂商队列中。神思会立即请求取消；如果取消的同时任务刚好开始生成，厂商仍可能扣除积分。确认停止？"
        : "当前任务可能已经开始生成。停止后神思会立即通知厂商取消，但已经产生的费用可能无法退回。确认停止？";
    if (!window.confirm(uiText(warning))) return null;
    // The card lock represents the user's ability to submit from this card,
    // not the provider's eventual cancellation acknowledgement. Release it
    // immediately after the user confirms stop; the durable job continues to
    // track any late provider response without blocking this card's controls.
    releaseWhiteboardMediaSubmissionLockForJob(current);
  }
  const settings = mediaGenerationSettingsForJob(current);
  const response = await fetch(`/api/generation/jobs/${encodeURIComponent(jobId)}/${action}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...(settings ? { settings } : {}), allowNewSubmission }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || uiText(action === "cancel" ? "停止媒体任务失败" : action === "dismiss" ? "忽略旧任务失败" : action === "reconcile" ? "找回结果失败" : "续接媒体任务失败"));
  updateMediaJobTargetAfterAction(payload.job);
  if (payload.requiresCredentials) showToast(uiText("原任务操作意图已保存；请在模型设置中恢复同一连接后继续"));
  else if (action === "cancel" || action === "dismiss") showToast(action === "dismiss"
    ? uiText(current.availableActions?.dismissCompleted ? "已放弃回填并隐藏任务；结果和任务记录仍保留" : "旧任务已忽略，当前卡片和配置选择已恢复")
    : mediaGenerationPhaseText(payload.job));
  return payload.job;
  })().finally(() => mediaGenerationActionFlights.delete(flightKey));
  mediaGenerationActionFlights.set(flightKey, operation);
  return operation;
};

const handleMediaGenerationActionElement = async (element) => {
  const jobId = String(element?.dataset?.mediaJobId || "");
  const action = String(element?.dataset?.mediaJobAction || "");
  if (!jobId || !action) return null;
  if (action === "reapply") {
    const job = await fetchWhiteboardGenerationJob(jobId);
    if (job.status !== "complete" || job.appliedAt) throw new Error("该任务已经完成处理，无需重复回填");
    const applied = await retryCompletedWhiteboardGenerationApply(job);
    if (!applied) throw new Error("现有结果仍未能安全回填卡片，任务继续保留；不会重新生成");
    showToast("已使用现有结果回填卡片，不会重新生成或扣费");
    return job;
  }
  if (action === "reverify") {
    const job = await fetchWhiteboardGenerationJob(jobId);
    if (!dreaminaFailureNeedsVerification({ job })) {
      throw new Error(mediaGenerationErrorText(job) || "当前任务不是账号核验故障，请按任务提示处理后续操作");
    }
    const settings = mediaGenerationSettingsForJob(job);
    if (!settings) throw new Error("原任务绑定的模型配置已不存在，请先在模型设置中恢复同一连接");
    const provider = String(settings.provider || "").trim().toLowerCase();
    const adapter = String(settings.adapter || "").trim().toLowerCase();
    if (provider === "即梦" && adapter === "cli") {
      rememberDreaminaJobForReverification(job, settings);
      openDreaminaReverifyDialog({ settings, jobId: job.id, errorMessage: mediaGenerationErrorText(job) });
      return job;
    }
    throw new Error("当前任务的连接凭据已失效，请到模型设置中重新核验该连接");
  }
  return controlMediaGenerationJob(jobId, action, {
    allowNewSubmission: element.dataset.confirmNewSubmission === "true",
  });
};

const documentArtifactTask = (documentState, artifactId) => (documentState?.artifactTasks ?? []).find((item) => item.artifactId === artifactId);

const updateDocumentArtifactTask = (documentId, artifactId, patch = {}) => {
  const documentState = state.documents[documentId];
  if (!documentState || documentState.documentKind === "whiteboard") return null;
  documentState.artifactTasks ??= [];
  let task = documentArtifactTask(documentState, artifactId);
  if (!task) {
    task = { artifactId, status: "planned", createdAt: Date.now() };
    documentState.artifactTasks.push(task);
  }
  Object.assign(task, patch, { updatedAt: Date.now() });
  documentState.artifactTasks = documentState.artifactTasks.slice(-100);
  return task;
};

const submitAdoptedExperienceObservation = async ({ documentId, artifact, observation, documentRevision = "" } = {}) => {
  if (observation?.contract !== "experience_observation_request_v3" || !observation.collectionToken || !artifact) return { stored: false, skipped: true };
  const response = await fetch("/api/experience/adoptions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      accountId: "local",
      workspacePath: state.settings.workspacePath || "",
      artifact,
      documentId,
      documentRevision: String(documentRevision || observation.taskEnvelope?.documentRevision || ""),
      collectionToken: observation.collectionToken,
      observerProfile: observation.observerProfile ?? null,
      taskEnvelope: observation.taskEnvelope,
    }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "采用后经验采集排队失败");
  return payload;
};

const queueDocumentArtifactJobs = async ({ documentId, plan } = {}) => {
  const documentState = state.documents[documentId];
  if (!documentState || documentState.documentKind === "whiteboard" || plan?.contract !== "illustration_plan_v1") return { jobs: [], issues: [] };
  const imageSettings = currentImageGenerationSettings();
  if (!generationConnectionIsAvailable("image", imageSettings)) {
    for (const item of plan.items ?? []) {
      updateDocumentArtifactTask(documentId, item.id, {
        status: "retry_required",
        error: "尚未配置可用图片模型，正文已保留",
        artifact: clone(item),
      });
      upsertDocumentArtifactPlaceholder(documentId, item, { status: "retry_required", message: "尚未配置可用图片模型，点击此处可在配置后重试" });
    }
    persist();
    await saveWorkspace({ throwOnError: true });
    return { jobs: [], issues: ["尚未配置可用图片模型，配图计划已保存为可重试状态"] };
  }
  if (!(await ensureDreaminaGenerationAccountAvailable(imageSettings, { channel: "image" }))) {
    for (const item of plan.items ?? []) {
      updateDocumentArtifactTask(documentId, item.id, {
        status: "retry_required",
        error: "当前即梦配置需要核验，正文和配图计划均已保留",
        artifact: clone(item),
      });
      upsertDocumentArtifactPlaceholder(documentId, item, {
        status: "retry_required",
        message: "当前即梦配置需要核验；核验完成后可继续生成，不会在核验前提交收费任务",
      });
    }
    persist();
    await saveWorkspace({ throwOnError: true });
    return { jobs: [], issues: ["当前即梦配置需要核验，未提交配图生成任务"] };
  }
  const jobs = [];
  const issues = [];
  for (const item of plan.items ?? []) {
    const existing = documentArtifactTask(documentState, item.id);
    if (existing?.jobId && !["failed", "retry_required"].includes(existing.status)) continue;
    const target = {
      workspaceKind: state.workspaceKind,
      workspacePath: state.settings.workspacePath,
      documentId,
      targetType: "document-artifact",
      anchorId: item.id,
      artifactId: item.id,
    };
    try {
      upsertDocumentArtifactPlaceholder(documentId, item, { status: "queued", message: "配图生成中，正文已安全保存" });
      const job = await createWhiteboardMediaGenerationJob({
        channel: "image",
        target,
        request: {
          prompt: item.prompt,
          displayPrompt: item.prompt,
          settings: { ...imageSettings, workspacePath: state.settings.workspacePath },
          aspectRatio: item.aspectRatio || "16:9",
          quality: "high",
          artifact: item,
        },
      });
      updateDocumentArtifactTask(documentId, item.id, {
        status: job.status,
        jobId: job.id,
        artifact: clone(item),
        availableActions: clone(job.availableActions ?? {}),
        desiredAction: job.desiredAction || "run",
        error: "",
      });
      upsertDocumentArtifactPlaceholder(documentId, item, {
        status: job.status,
        message: mediaGenerationPhaseText(job),
        job,
      });
      jobs.push(job);
      monitorDocumentArtifactJob(job);
    } catch (error) {
      updateDocumentArtifactTask(documentId, item.id, { status: "retry_required", artifact: clone(item), error: error.message });
      upsertDocumentArtifactPlaceholder(documentId, item, { status: "retry_required", message: `配图生成失败，点击重试：${error.message}` });
      issues.push(`${item.purpose || item.id}：${error.message}`);
    }
  }
  persist();
  await saveWorkspace({ throwOnError: true });
  return { jobs, issues };
};

const executeAdoptedCandidateTrustedActions = async ({ documentId, artifact, target, sourceTaskId = "" } = {}) => {
  const results = { experienceStored: false, artifactJobs: 0, issues: [] };
  if (target?.experienceObservation) {
    try {
      const queued = await submitAdoptedExperienceObservation({
        documentId,
        artifact,
        observation: target.experienceObservation,
        documentRevision: target?.generationBasis?.targetRevisions?.[documentId]
          ?? target?.generationBasis?.relevantDocumentRevisions?.[documentId]
          ?? target.experienceObservation.taskEnvelope?.documentRevision,
      });
      results.experienceStored = queued.queued === true || queued.duplicate === true;
    } catch (error) {
      results.issues.push(`采用后经验采集：${error.message}`);
    }
  }
  if (target?.artifactPlan) {
    try {
      const queued = await queueDocumentArtifactJobs({ documentId, plan: target.artifactPlan });
      results.artifactJobs = queued.jobs.length;
      results.issues.push(...queued.issues.map((issue) => `自动配图：${issue}`));
    } catch (error) {
      results.issues.push(`自动配图：${error.message}`);
    }
  }
  return results;
};

const fetchWhiteboardGenerationJob = async (jobId) => {
  const response = await fetch(`/api/generation/jobs/${encodeURIComponent(jobId)}`);
  let payload;
  try {
    payload = await response.json();
  } catch {
    const error = new Error("生成任务状态响应无法解析");
    error.status = response.status;
    error.code = "INVALID_GENERATION_JOB_PAYLOAD";
    throw error;
  }
  if (!response.ok || !payload.ok) {
    const error = new Error(payload.message || "生成任务状态读取失败");
    error.status = response.status;
    error.code = String(payload.code || "");
    throw error;
  }
  if (!payload.job || typeof payload.job !== "object" || !payload.job.id || !payload.job.status) {
    const error = new Error("生成任务状态响应缺少任务数据");
    error.status = response.status;
    error.code = "INVALID_GENERATION_JOB_PAYLOAD";
    throw error;
  }
  if (String(payload.job.id) !== String(jobId)) {
    const error = new Error("生成任务状态响应与请求身份不一致");
    error.status = response.status;
    error.code = "GENERATION_JOB_ID_MISMATCH";
    throw error;
  }
  return payload.job;
};

const waitForGenerationJob = async (jobId, {
  onProgress = null,
  onConnectionError = null,
} = {}) => {
  let transientFailures = 0;
  let lastJob = null;
  while (true) {
    let job;
    try {
      job = await fetchWhiteboardGenerationJob(jobId);
    } catch (error) {
      transientFailures += 1;
      onConnectionError?.({ error, transientFailures, lastJob });
      if (mediaGenerationPollErrorIsTerminal(error, transientFailures)) throw error;
      const delayMs = mediaGenerationPollDelayMs({
        transientFailures,
        activePolls: ui.generationJobPolls.size + 1,
        pageHidden: document.visibilityState === "hidden",
      });
      await new Promise((resolveDelay) => setTimeout(resolveDelay, delayMs));
      continue;
    }

    lastJob = job;
    transientFailures = 0;
    onProgress?.(job);
    if (job.userStoppedAt || job.resultSuppressed || job.userStopped) return job;
    if (MEDIA_JOB_POLL_STOP_STATUSES.has(job.status) && job.automaticRecoveryInProgress !== true) return job;
    const delayMs = mediaGenerationPollDelayMs({
      activePolls: ui.generationJobPolls.size + 1,
      pageHidden: document.visibilityState === "hidden",
    });
    await new Promise((resolveDelay) => setTimeout(resolveDelay, delayMs));
  }
};

const waitForWhiteboardGenerationJob = (jobId, candidateKey) => waitForGenerationJob(jobId, {
  onProgress: (job) => {
    if (!whiteboardCandidateBelongsToJob(candidateKey, jobId)) return;
    updateWhiteboardGenerationCandidate(candidateKey, {
      jobId,
      status: job.status,
      desiredAction: job.desiredAction || "run",
      availableActions: job.availableActions ?? {},
      providerStatus: job.providerStatus,
      model: String(job.request?.settings?.model || job.settings?.model || ""),
      providerQueuePosition: job.providerQueuePosition,
      providerQueueLength: job.providerQueueLength,
      providerQueuePriority: job.providerQueuePriority,
      providerQueueStatus: job.providerQueueStatus,
      providerTaskId: job.providerTaskId,
      submissionState: job.submissionState,
      submittedAt: job.submittedAt,
      providerProgressPercent: job.providerProgressPercent,
      automaticRecoveryInProgress: job.automaticRecoveryInProgress === true,
      progressPercent: Number(job.progressPercent) || 1,
      connectionInterrupted: false,
      error: mediaGenerationErrorText(job),
      elapsedMs: Math.max(0, Date.now() - generationJobInteractionStartedAt(job)),
      cardApplyStage: job.status === "complete" ? "saving" : "",
    });
  },
  onConnectionError: ({ error }) => {
    if (!whiteboardCandidateBelongsToJob(candidateKey, jobId)) return;
    updateWhiteboardGenerationCandidate(candidateKey, {
      connectionInterrupted: true,
      connectionError: error.message,
    });
  },
});

const generationJobInteractionStartedAt = (job) => {
  const interactionStartedAt = Date.parse(String(job?.request?.interactionStartedAt || ""));
  if (Number.isFinite(interactionStartedAt) && interactionStartedAt > 0) return interactionStartedAt;
  const startedAt = Date.parse(String(job?.startedAt || job?.createdAt || ""));
  return Number.isFinite(startedAt) && startedAt > 0 ? startedAt : Date.now();
};

const generationJobElapsedMs = (job) => {
  const recorded = Number(job?.elapsedMs ?? job?.result?.elapsedMs);
  if (Number.isFinite(recorded) && recorded >= 0) return recorded;
  const endedAt = Date.parse(job?.userStoppedAt || job?.completedAt || job?.cancelledAt || job?.failedAt || job?.updatedAt || "");
  const startedAt = generationJobInteractionStartedAt(job);
  const elapsed = endedAt - startedAt;
  return Number.isFinite(elapsed) && elapsed > 0 ? elapsed : 1;
};

const normalizedMediaRelativePath = (value = "") => String(value || "")
  .replaceAll("\\", "/")
  .replace(/^\.\//, "")
  .toLocaleLowerCase();

const whiteboardGenerationContentFromJob = (job) => {
  const requestSettings = job.request?.settings ?? {};
  const requestGenerationProfile = job.request?.generationProfile && typeof job.request.generationProfile === "object"
    && Object.keys(job.request.generationProfile).length
    ? job.request.generationProfile
    : null;
  const resultGenerationProfile = job.result?.generationProfile && typeof job.result.generationProfile === "object"
    && Object.keys(job.result.generationProfile).length
    ? job.result.generationProfile
    : null;
  const explicitGenerationProfile = requestGenerationProfile || resultGenerationProfile;
  const common = {
    prompt: String(job.request?.prompt || ""),
    referenceOrder: Array.isArray(job.request?.referenceOrder) ? job.request.referenceOrder.map(String).filter(Boolean) : [],
    elapsedMs: generationJobElapsedMs(job),
    generationJobId: job.id,
    generationCreatedAt: job.completedAt || job.submittedAt || job.createdAt || job.startedAt || "",
    novelCover: job.request?.novelCover || null,
    mediaBatchId: String(job.target?.mediaBatchId || ""),
    mediaBatchIndex: Math.max(1, Number(job.target?.mediaBatchIndex) || 1),
    mediaBatchTotal: Math.max(1, Number(job.target?.mediaBatchTotal) || 1),
    mediaBatchLabel: String(job.target?.mediaBatchLabel || ""),
    mediaBatchDirectory: String(job.result?.mediaBatchDirectory || ""),
    mediaBatchIndexPath: String(job.result?.mediaBatchIndexPath || ""),
    whiteboardMediaDirectory: String(job.result?.whiteboardMediaDirectory || ""),
    whiteboardMediaIndexPath: String(job.result?.whiteboardMediaIndexPath || ""),
    // A completed, not-yet-applied media task has already incurred its provider
    // cost and has a verified local result. If its placeholder card disappeared
    // during an upgrade or reload, retaining the result is safer than silently
    // stranding it. Applied tasks are handled separately as history-only repairs
    // so a card the user intentionally deleted is not recreated.
    recoverMissingTarget: Boolean(job.reconciledProviderTaskAt)
      || (job.status === "complete" && !job.appliedAt && ["image", "video", "audio"].includes(job.channel)),
    generationProfile: explicitGenerationProfile ?? {
      connectionId: String(requestSettings.connectionId || requestSettings.id || ""),
      model: String(requestSettings.model || ""),
    },
  };
  if (job.channel === "image") {
    const [width, height] = String(job.request?.aspectRatio || "1:1").split(":").map(Number);
    return {
      ...common,
      kind: "image",
      attachment: job.result?.attachment,
      attachments: Array.isArray(job.result?.attachments) ? job.result.attachments : [job.result?.attachment].filter(Boolean),
      aspectRatio: width > 0 && height > 0 ? width / height : 1,
    };
  }
  if (job.channel === "video") {
    const [width, height] = String(job.request?.aspectRatio || "16:9").split(":").map(Number);
    return { ...common, kind: "video", attachment: job.result?.attachment, aspectRatio: width > 0 && height > 0 ? width / height : 16 / 9 };
  }
  if (job.channel === "audio") {
    return { ...common, kind: "audio", attachment: job.result?.attachment, aspectRatio: 16 / 5 };
  }
  return { ...common, kind: "generated", text: String(job.result?.text || "") };
};

const appliedWhiteboardJobCanSynchronizeCard = (job, node, content) => {
  if (!job?.id || !node || canvasNodeDisplaysGenerationContent(node, content)) return false;
  const currentJobId = String(node.generation?.jobId || "");
  // A manually placed media file has no durable generation owner. Do not
  // overwrite it while repairing an older applied task; only placeholders or
  // the exact task's partially written card are safe to synchronize.
  if (node.file && currentJobId !== job.id) return false;
  return shouldPromoteMediaGenerationResult({
    completedJobId: job.id,
    completedCreatedAt: content.generationCreatedAt,
    currentGenerationJobId: currentJobId,
    currentGenerationCreatedAt: node.generation?.createdAt,
  });
};

const ensureWhiteboardGenerationRecoveryTarget = ({ documentState, nodeId, job = null, text = "" } = {}) => {
  if (!documentState || documentState.documentKind !== "whiteboard" || !nodeId) return false;
  const normalizedBefore = normalizeCanvas(documentState.canvas);
  if (canvasGenerationRecoveryTargetDeleted(normalizedBefore, {
    nodeId,
    generationJobId: job?.id,
    generationCreatedAt: job?.createdAt,
  })) return false;
  if (normalizedBefore.nodes.some((node) => node.id === nodeId)) return false;
  const viewport = normalizedBefore.viewport;
  const width = 320;
  const height = 180;
  const baseX = Math.round((120 - viewport.x) / Math.max(0.1, viewport.zoom));
  const baseY = Math.round((120 - viewport.y) / Math.max(0.1, viewport.zoom));
  let x = baseX;
  let y = baseY;
  for (let index = 0; index < 24; index += 1) {
    const overlaps = normalizedBefore.nodes.some((node) => (
      x < node.x + node.width + 24
      && x + width + 24 > node.x
      && y < node.y + node.height + 24
      && y + height + 24 > node.y
    ));
    if (!overlaps) break;
    x = baseX + (index % 4) * 40;
    y = baseY + Math.floor(index / 4 + 1) * 220;
  }
  documentState.canvas = addCanvasTextNode(documentState.canvas, {
    id: nodeId,
    text,
    x,
    y,
    width,
    height,
    color: "yellow",
    ...(job ? {
      kind: "generated",
      generation: {
        channel: job.channel === "image" ? "image" : "video",
        prompt: String(job.request?.prompt || "媒体任务结果待找回"),
        jobId: job.id,
        createdAt: job.createdAt || new Date().toISOString(),
      },
    } : {}),
  });
  documentState.updatedAt = nowTime();
  return true;
};

const documentArtifactAnchorElement = (container, anchor = {}) => {
  const blocks = Array.from(container.querySelectorAll("h1,h2,h3,h4,h5,h6,p"));
  if (anchor.type === "after_heading") {
    const wanted = String(anchor.heading || "").replace(/^#{1,6}\s+/, "").trim();
    return blocks.find((element) => {
      const current = String(element.textContent || "").replace(/^#{1,6}\s+/, "").trim();
      return current === wanted || current.includes(wanted) || wanted.includes(current);
    }) ?? null;
  }
  if (anchor.type === "after_paragraph") {
    return container.querySelectorAll("p")[Number(anchor.paragraphIndex)] ?? null;
  }
  if (anchor.type === "after_excerpt") {
    const excerpt = String(anchor.excerpt || "").trim();
    return blocks.find((element) => excerpt && String(element.textContent || "").includes(excerpt)) ?? null;
  }
  return null;
};

const documentArtifactJobSnapshot = (task = {}) => ({
  id: task.jobId || "",
  status: task.status || "planned",
  desiredAction: task.desiredAction || "run",
  availableActions: task.availableActions ?? {},
  providerErrorCode: task.providerErrorCode || "",
  error: task.error || "",
  providerTaskId: task.providerTaskId || "",
  submissionState: task.submissionState || "",
});

const hydrateDocumentArtifactControls = (root = elements.editor, documentState = state.documents[state.activeDocument]) => {
  if (!root || !documentState || documentState.documentKind === "whiteboard") return;
  root.querySelectorAll("[data-document-artifact-controls]").forEach((controls) => controls.remove());
  root.querySelectorAll("figure[data-artifact-id][data-artifact-status]").forEach((figure) => {
    const task = documentArtifactTask(documentState, figure.dataset.artifactId);
    if (!task?.jobId || task.status === "complete") return;
    figure.dataset.generationJobId = task.jobId;
    const markup = mediaGenerationActionMarkup(documentArtifactJobSnapshot(task), { compact: true });
    if (!markup) return;
    const controls = document.createElement("div");
    controls.dataset.documentArtifactControls = "true";
    controls.innerHTML = markup;
    figure.append(controls);
  });
};

const syncActiveDocumentArtifactElement = (documentId, artifact = {}) => {
  if (state.activeDocument !== documentId || elements.editor.dataset.document !== documentId || !artifact.id) return;
  const documentState = state.documents[documentId];
  const persisted = document.createElement("div");
  persisted.innerHTML = sanitizeDocumentHtml(documentState?.html || "");
  const sourceFigure = persisted.querySelector(`[data-artifact-id="${CSS.escape(artifact.id)}"]`);
  if (!sourceFigure) return;
  const liveFigure = elements.editor.querySelector(`[data-artifact-id="${CSS.escape(artifact.id)}"]`);
  if (liveFigure) liveFigure.replaceWith(sourceFigure);
  else {
    const anchor = documentArtifactAnchorElement(elements.editor, artifact.anchor ?? {});
    if (!anchor) return;
    anchor.insertAdjacentElement("afterend", sourceFigure);
  }
  hydrateWorkspaceAttachmentMedia(elements.editor);
  hydrateDocumentArtifactControls(elements.editor, documentState);
};

const upsertDocumentArtifactPlaceholder = (documentId, artifact = {}, { status = "planned", message = "配图任务等待执行", job = null } = {}) => {
  const documentState = state.documents[documentId];
  if (!documentState || documentState.documentKind === "whiteboard" || !artifact.id) return false;
  const container = document.createElement("div");
  container.innerHTML = sanitizeDocumentHtml(documentState.html || "");
  let figure = container.querySelector(`[data-artifact-id="${CSS.escape(artifact.id)}"]`);
  if (!figure) {
    const anchor = documentArtifactAnchorElement(container, artifact.anchor ?? {});
    if (!anchor) return false;
    figure = document.createElement("figure");
    figure.className = "document-image";
    figure.contentEditable = "false";
    figure.dataset.artifactId = artifact.id;
    anchor.insertAdjacentElement("afterend", figure);
  }
  figure.dataset.artifactStatus = status;
  if (job?.id) figure.dataset.generationJobId = job.id;
  figure.innerHTML = `<figcaption>${escapeHtml(message)}</figcaption>`;
  documentState.html = sanitizeDocumentHtml(container.innerHTML);
  documentState.updatedAt = nowTime();
  syncActiveDocumentArtifactElement(documentId, artifact);
  return true;
};

const applyCompletedDocumentArtifactJob = async (job) => {
  if (!job?.id || job.status !== "complete" || job.appliedAt || job.target?.targetType !== "document-artifact") return false;
  recordCustomGenerationJobCapability(job);
  if (usesDreaminaAccountCredits(job.request?.settings)) {
    void refreshDreaminaCreditAfterSuccessfulGeneration(job);
  }
  const target = job.target ?? {};
  if (normalizedWorkspacePath(target.workspacePath) !== normalizedWorkspacePath(state.settings.workspacePath)) return false;
  const documentState = state.documents[target.documentId];
  if (!documentState || documentState.documentKind === "whiteboard") throw new Error("自动配图目标文档已经不存在");
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped) {
    updateDocumentArtifactTask(target.documentId, target.artifactId, {
      status: "cancelled",
      jobId: job.id,
      error: "用户已停止任务",
    });
    upsertDocumentArtifactPlaceholder(target.documentId, job.request?.artifact ?? { id: target.artifactId }, {
      status: "cancelled",
      message: "配图生成已停止",
      job,
    });
    persist();
    await markWhiteboardGenerationJobApplied(job.id);
    if (state.activeDocument === target.documentId) renderEditor();
    return true;
  }
  const attachment = job.result?.attachment;
  if (!attachment?.relativePath) throw new Error("自动配图任务缺少已落盘附件");
  const container = document.createElement("div");
  container.innerHTML = sanitizeDocumentHtml(documentState.html || "");
  const existing = container.querySelector(`[data-generation-job-id="${CSS.escape(job.id)}"]`);
  if (!existing) {
    const placeholder = container.querySelector(`[data-artifact-id="${CSS.escape(target.artifactId)}"]`);
    const anchor = placeholder || documentArtifactAnchorElement(container, job.request?.artifact?.anchor ?? {});
    if (!anchor) {
      updateDocumentArtifactTask(target.documentId, target.artifactId, {
        status: "retry_required",
        error: "正文锚点已变化，图片已保留但未自动插入",
        attachment: clone(attachment),
      });
      persist();
      return false;
    }
    const figure = createEditorMediaFigure(attachment);
    figure.dataset.generationJobId = job.id;
    figure.dataset.artifactId = target.artifactId;
    figure.dataset.artifactStatus = "complete";
    const altText = String(job.request?.artifact?.altText || job.request?.artifact?.purpose || "").trim();
    const image = figure.querySelector("img");
    if (image && altText) image.alt = altText;
    if (placeholder) placeholder.replaceWith(figure);
    else anchor.insertAdjacentElement("afterend", figure);
    documentState.html = sanitizeDocumentHtml(container.innerHTML);
    documentState.updatedAt = nowTime();
  }
  updateDocumentArtifactTask(target.documentId, target.artifactId, {
    status: "complete",
    jobId: job.id,
    attachment: clone(attachment),
    error: "",
  });
  syncActiveDocumentArtifactElement(target.documentId, job.request?.artifact ?? { id: target.artifactId });
  await saveWorkspace({ throwOnError: true });
  await markWhiteboardGenerationJobApplied(job.id, target.artifactId || attachment.relativePath || "");
  if (state.activeDocument === target.documentId) renderEditor();
  recordActivity({ type: "edit", label: `自动配图已插入${documentState.title || "当前文档"}`, documentId: target.documentId });
  return true;
};

const updateDocumentArtifactJobProgress = (job, { connectionInterrupted = false, persistNow = false } = {}) => {
  const target = job?.target ?? {};
  const documentState = state.documents[target.documentId];
  if (!job?.id || target.targetType !== "document-artifact" || !documentState || documentState.documentKind === "whiteboard") return false;
  const artifact = job.request?.artifact ?? documentArtifactTask(documentState, target.artifactId)?.artifact ?? { id: target.artifactId };
  const previous = documentArtifactTask(documentState, target.artifactId);
  const userStopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  const visibleStatus = userStopped ? "cancelled" : job.status;
  const phase = mediaGenerationPhaseText(job, { connectionInterrupted });
  const message = !connectionInterrupted && job.error && (MEDIA_JOB_ATTENTION_STATUSES.has(job.status) || job.status === "cancelled")
    ? `${phase}：${mediaGenerationErrorText(job)}`
    : phase;
  const statusChanged = previous?.status !== visibleStatus || previous?.statusMessage !== message;
  if (statusChanged && !userStopped && MEDIA_JOB_ATTENTION_STATUSES.has(job.status)) recordCustomGenerationJobCapability(job);
  updateDocumentArtifactTask(target.documentId, target.artifactId, {
    status: visibleStatus,
    statusMessage: message,
    jobId: job.id,
    desiredAction: job.desiredAction || "run",
    availableActions: clone(job.availableActions ?? {}),
    providerErrorCode: job.providerErrorCode || "",
    providerTaskId: job.providerTaskId || "",
    submissionState: job.submissionState || "",
    progressPercent: Math.min(100, Math.max(1, Number(job.progressPercent) || 1)),
    providerStatus: job.providerStatus || "",
    connectionInterrupted,
    error: connectionInterrupted ? previous?.error || "" : job.error || "",
    artifact: clone(artifact),
  });
  upsertDocumentArtifactPlaceholder(target.documentId, artifact, {
    status: visibleStatus,
    message,
    job,
  });
  const now = Date.now();
  const lastSave = mediaDocumentArtifactProgressSaves.get(job.id) || 0;
  if (persistNow || statusChanged || now - lastSave >= 8_000) {
    persist();
    mediaDocumentArtifactProgressSaves.set(job.id, now);
  }
  return true;
};

const showInterruptedDocumentArtifactJob = (job) => {
  const target = job.target ?? {};
  if (target.targetType !== "document-artifact" || !state.documents[target.documentId]) return;
  recordCustomGenerationJobCapability(job);
  promptDreaminaReverificationForJob(job);
  updateDocumentArtifactJobProgress(job, { persistNow: true });
  mediaDocumentArtifactProgressSaves.delete(job.id);
};

const waitForDocumentArtifactJob = (jobId, options = {}) => waitForGenerationJob(jobId, options);

const monitorDocumentArtifactJob = (job) => {
  if (!job?.id || ui.generationJobPolls.has(job.id)) return;
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped) {
    showInterruptedDocumentArtifactJob(job);
    return;
  }
  updateDocumentArtifactJobProgress(job, { persistNow: true });
  const operation = waitForDocumentArtifactJob(job.id, {
    onProgress: (current) => updateDocumentArtifactJobProgress(current),
    onConnectionError: ({ lastJob }) => updateDocumentArtifactJobProgress(lastJob || job, { connectionInterrupted: true }),
  })
    .then(async (completed) => {
      if (completed.status === "complete") await applyCompletedDocumentArtifactJob(completed);
      else showInterruptedDocumentArtifactJob(completed);
    })
    .catch((error) => showInterruptedDocumentArtifactJob({ ...job, status: "retry_required", error: error.message }))
    .finally(() => {
      ui.generationJobPolls.delete(job.id);
      mediaDocumentArtifactProgressSaves.delete(job.id);
    });
  ui.generationJobPolls.set(job.id, operation);
};

const conversationMessageTarget = (job) => {
  const conversation = state.conversations.find((item) => item.id === job.target?.conversationId);
  if (!conversation) return null;
  const messages = conversation.id === state.activeConversationId ? state.messages : conversation.messages ?? [];
  const index = messages.findIndex((message) => message.id === job.target?.messageId);
  return index >= 0 ? { conversation, messages, index } : null;
};

const updateConversationMediaProgressDom = (messageId, execution) => {
  const section = elements.chatFeed.querySelector(`[data-message="${CSS.escape(messageId)}"]`);
  if (!section) return false;
  const progress = Math.min(100, Math.max(1, Math.round(Number(execution.progressPercent) || 1)));
  const ring = section.querySelector(".execution-progress-ring");
  const sessionRecoveryPending = String(execution.mediaProviderErrorCode || "").toUpperCase()
    === "DREAMINA_PROVIDER_SESSION_RESTORE_PENDING";
  if (ring) {
    if (!sessionRecoveryPending) ring.style.setProperty("--execution-progress", `${progress * 3.6}deg`);
    if (sessionRecoveryPending) ring.removeAttribute("aria-valuenow");
    else ring.setAttribute("aria-valuenow", String(progress));
    ring.setAttribute("aria-label", sessionRecoveryPending ? "正在恢复查询会话" : "任务处理进度");
    const value = ring.querySelector("span");
    if (value) value.textContent = sessionRecoveryPending ? "恢复" : String(progress);
  }
  const result = section.querySelector(".execution-current-state dd span:last-child");
  if (result) result.textContent = execution.result || uiText("后台媒体任务进行中");
  const timer = section.querySelector(".execution-time");
  if (timer) {
    const startedAt = executionTimestampMilliseconds(execution.startedAt);
    const pending = execution.status === "running";
    const elapsedMs = pending && startedAt
      ? Math.max(0, Date.now() - startedAt)
      : Math.max(0, Number(execution.elapsedMs) || (startedAt && execution.endedAt ? executionTimestampMilliseconds(execution.endedAt) - startedAt : 0));
    if (pending && startedAt) timer.dataset.startedAt = String(startedAt);
    else delete timer.dataset.startedAt;
    timer.textContent = startedAt || elapsedMs > 0
      ? `${pending ? "已用" : "耗时"} ${formatExecutionDuration(elapsedMs)}`
      : uiText("耗时未记录");
  }
  return true;
};

const updateConversationMediaJobProgress = (job, { connectionInterrupted = false, persistNow = false, forceRender = false } = {}) => {
  if (!job?.id) return false;
  const target = conversationMessageTarget(job);
  if (!target) return false;
  const message = target.messages[target.index];
  const previousStatus = message.execution?.mediaJobStatus || "";
  const userStopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  const active = !userStopped && MEDIA_JOB_ACTIVE_STATUSES.has(job.status);
  const previousProgress = Number(message.execution?.progressPercent) || 0;
  const providerProgress = Number(job.providerProgressPercent);
  const hasProviderProgress = job.providerProgressPercent !== null
    && job.providerProgressPercent !== undefined
    && Number.isFinite(providerProgress)
    && providerProgress > 0;
  const startedAt = executionTimestampMilliseconds(message.execution?.startedAt || job.startedAt || job.createdAt) || Date.now();
  const syntheticProgress = syntheticMediaProgress({
    elapsedMs: Math.max(0, Date.now() - startedAt),
    channel: job.channel,
  });
  const maximumProgress = active ? 99 : 100;
  const sessionRecoveryPending = String(job.providerErrorCode || job.errorCode || "").toUpperCase()
    === "DREAMINA_PROVIDER_SESSION_RESTORE_PENDING";
  const nextProgress = sessionRecoveryPending
    ? Math.max(1, previousProgress)
    : connectionInterrupted
    ? monotonicProgress(previousProgress, hasProviderProgress ? providerProgress : syntheticProgress, { minimum: 1, maximum: maximumProgress })
    : hasProviderProgress
      ? monotonicProgress(previousProgress, providerProgress, { minimum: 1, maximum: maximumProgress })
      : active
        ? monotonicProgress(previousProgress, Math.max(Number(job.progressPercent) || 1, syntheticProgress), { minimum: 1, maximum: 99 })
        : job.status === "complete"
          ? 100
          : Math.max(previousProgress, Number(job.progressPercent) || 1);
  const endedAt = userStopped ? executionTimestampMilliseconds(job.userStoppedAt) || Date.now() : 0;
  const elapsedMs = userStopped
    ? Math.max(0, Number(job.elapsedMs) || endedAt - startedAt)
    : Math.max(0, Number(message.execution?.elapsedMs) || 0);
  message.pending = active;
  message.execution = {
    ...(message.execution ?? {}),
    status: active ? "running" : userStopped ? "cancelled" : job.status,
    mediaJobStatus: job.status,
    generationJobId: job.id,
    progressPercent: nextProgress,
    providerStatus: job.providerStatus || "",
    providerProgressPercent: job.providerProgressPercent,
    providerQueuePosition: job.providerQueuePosition ?? null,
    providerQueueLength: job.providerQueueLength ?? null,
    mediaAvailableActions: job.availableActions ?? {},
    mediaProviderErrorCode: job.providerErrorCode || "",
    mediaError: mediaGenerationErrorText(job),
    mediaProviderTaskId: job.providerTaskId || "",
    mediaSubmissionState: job.submissionState || "",
    desiredAction: job.desiredAction || "run",
    billingRisk: job.billingRisk || "",
    startedAt,
    ...(endedAt ? { endedAt, elapsedMs } : {}),
    providerStartedAt: Number(message.execution?.providerStartedAt) || Date.parse(job.startedAt || job.createdAt || "") || 0,
    result: mediaGenerationPhaseText(job, { connectionInterrupted }),
  };
  target.conversation.messages = clone(target.messages);
  const statusChanged = previousStatus !== job.status;
  if (statusChanged && !userStopped && MEDIA_JOB_ATTENTION_STATUSES.has(job.status)) recordCustomGenerationJobCapability(job);
  if (target.conversation.id === state.activeConversationId) {
    if (forceRender || statusChanged || !updateConversationMediaProgressDom(message.id, message.execution)) renderMessages();
  }
  const now = Date.now();
  const lastSave = mediaConversationProgressSaves.get(job.id) || 0;
  if (persistNow || statusChanged || now - lastSave >= 8_000) {
    persist();
    mediaConversationProgressSaves.set(job.id, now);
  }
  return true;
};

const applyCompletedConversationMediaJobNow = async (job, { repairApplied = false } = {}) => {
  if (!job?.id || job.status !== "complete" || (job.appliedAt && !repairApplied)) return false;
  recordCustomGenerationJobCapability(job);
  if (usesDreaminaAccountCredits(job.request?.settings)) {
    void refreshDreaminaCreditAfterSuccessfulGeneration(job);
  }
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped) {
    if (!job.appliedAt) await markWhiteboardGenerationJobApplied(job.id);
    mediaConversationProgressSaves.delete(job.id);
    scheduleConversationQueueDrain(job.target?.conversationId);
    return true;
  }
  if (!job.result?.attachment) return false;
  const mediaLabel = job.channel === "audio" ? "音频" : job.channel === "video" ? "视频" : "图片";
  const targetKind = job.target?.workspaceKind === "notebook" ? "notebook" : "project";
  const targetIsActive = workspaceTargetIsActive(targetKind, job.target?.workspacePath);
  if (!targetIsActive) {
    const receipt = await saveInactiveConversationMediaGeneration(job);
    await synchronizeBackgroundConversationIntoActiveWorkspace(job, receipt);
    if (!job.appliedAt) await markWhiteboardGenerationJobApplied(job.id, receipt?.landing?.assetId || job.result?.attachment?.relativePath || "");
    mediaConversationProgressSaves.delete(job.id);
    return true;
  }

  const landing = applyConversationMediaResultToWorkspace(state, job, { timeLabel: nowTime() });
  if (landing.suppressed) {
    if (!job.appliedAt) await markWhiteboardGenerationJobApplied(job.id);
    mediaConversationProgressSaves.delete(job.id);
    scheduleConversationQueueDrain(job.target?.conversationId);
    return true;
  }
  const target = conversationMessageTarget(job);
  if (!target) throw new Error("媒体结果消息回填失败");
  if (!landing.duplicate && job.target?.landAfterGeneration === true) {
    try {
      await landGeneratedMediaAttachment({
        attachment: job.result.attachment,
        channel: job.channel,
        documentId: job.target.documentId,
      });
      target.messages[target.index].content = `已生成${mediaLabel}，并插入当前绑定文档完成本地保存。`;
      target.messages[target.index].execution.result = `${mediaLabel}已生成、入库并写入文档`;
    } catch (error) {
      target.messages[target.index].content = `已生成${mediaLabel}并保存到本地资料库，但自动写入文档失败：${error.message}`;
      target.messages[target.index].execution.result = `${mediaLabel}已安全入库，文档写入待重试`;
    }
  }
  const successfulConnectionId = String(job.request?.connectionSelection?.connectionId || job.request?.settings?.id || "").trim();
  if (["image", "video"].includes(job.channel) && successfulConnectionId) {
    target.conversation.lastSuccessfulMediaConnectionIds = {
      ...(target.conversation.lastSuccessfulMediaConnectionIds ?? {}),
      [job.channel]: successfulConnectionId,
    };
    target.conversation.lastSuccessfulMediaSelections = {
      ...(target.conversation.lastSuccessfulMediaSelections ?? {}),
      [job.channel]: {
        profileId: successfulConnectionId,
        model: String(job.request?.settings?.model || "").trim(),
        ...(job.channel === "image" ? {
          aspectRatio: String(job.request?.aspectRatio || "").trim(),
          quality: String(job.request?.quality || "").trim(),
        } : {
          aspectRatio: String(job.request?.aspectRatio || "").trim(),
          resolution: String(job.request?.resolution || "").trim().toLowerCase(),
        }),
      },
    };
  }
  target.conversation.messages = clone(target.messages);
  if (target.conversation.id === state.activeConversationId) renderMessages();
  if (!landing.duplicate || landing.metadataRepaired) {
    persist();
    await ensureCurrentRecoveryCheckpoint();
    await flushWorkspaceSave({ throwOnError: true });
  }
  // The durable provider job is only closed after the message and history
  // asset have survived a real workspace save. This prevents a successful
  // video from disappearing behind a later save conflict or workspace switch.
  if (!job.appliedAt) await markWhiteboardGenerationJobApplied(job.id, landing.assetId || job.result?.attachment?.relativePath || "");
  if (!repairApplied) {
    recordActivity({
      type: "chat",
      label: `通过对话生成${mediaLabel}`,
      conversationId: job.target?.conversationId,
      messageId: job.target?.messageId,
    });
  }
  mediaConversationProgressSaves.delete(job.id);
  scheduleConversationQueueDrain(job.target?.conversationId);
  return true;
};

const applyCompletedConversationMediaJob = (job, options = {}) => {
  const queueKey = [
    String(job?.target?.workspaceKind || "project"),
    normalizedWorkspacePath(job?.target?.workspacePath || state.settings.workspacePath),
    String(job?.target?.conversationId || ""),
  ].join("::");
  const previous = conversationMediaApplyQueues.get(queueKey) ?? Promise.resolve();
  const operation = previous.catch(() => {}).then(() => applyCompletedConversationMediaJobNow(job, options));
  let tracked;
  tracked = operation.finally(() => {
    if (conversationMediaApplyQueues.get(queueKey) === tracked) conversationMediaApplyQueues.delete(queueKey);
  });
  conversationMediaApplyQueues.set(queueKey, tracked);
  return tracked;
};

const conversationImageQuotaFallbackPrompts = new Set();

const conversationImageQuotaFailure = (job = {}) => job.channel === "image"
  && job.request?.settings?.provider === "OpenAI"
  && /insufficient[_ -]?quota|billing[_ -]?hard[_ -]?limit|credit balance|quota exceeded|额度不足|余额不足|积分不足/i.test(String(job.error || job.providerErrorCode || ""));

const maybeOfferConversationImageQuotaFallback = async (job = {}) => {
  if (!conversationImageQuotaFailure(job)
    || job.request?.connectionSelection?.explicit === true
    || conversationImageQuotaFallbackPrompts.has(job.id)
    || job.target?.conversationId !== state.activeConversationId) return false;
  conversationImageQuotaFallbackPrompts.add(job.id);
  ui.gptImageQuotaUnavailable = true;
  const profiles = availableGenerationConnections("image").filter((profile) => profile.provider === "即梦");
  const selected = await requestConversationMediaConnection({
    channel: "image",
    profiles,
    reason: "GPT 生图已明确返回额度不足。请选择即梦配置继续本次生成；取消则保留当前失败记录，不会产生即梦费用。",
  });
  if (!selected) return false;
  const settings = currentImageGenerationSettings(selected.id);
  if (!settings || !generationConnectionIsAvailable("image", settings)) {
    showToast(`即梦配置“${conversationMediaConnectionLabel(selected)}”当前不可用，本次未提交`);
    return false;
  }
  if (!(await ensureDreaminaGenerationAccountAvailable(settings, { channel: "image" }))) return false;
  try {
    const replacement = await createWhiteboardMediaGenerationJob({
      channel: "image",
      target: clone(job.target ?? {}),
      request: {
        ...clone(job.request ?? {}),
        settings: { ...settings, workspacePath: job.target?.workspacePath || state.settings.workspacePath },
        connectionSelection: {
          source: "gpt_quota_fallback",
          explicit: true,
          connectionId: settings.id,
        },
        fallbackFromJobId: job.id,
      },
    });
    updateConversationMediaJobProgress(replacement, { forceRender: true, persistNow: true });
    monitorConversationMediaJob(replacement);
    showToast(`已改用“${conversationMediaConnectionLabel(selected)}”继续生成图片`);
    return true;
  } catch (error) {
    showToast(`切换即梦配置失败，本次未重新提交：${error.message}`);
    return false;
  }
};

const showInterruptedConversationMediaJob = (job) => {
  recordCustomGenerationJobCapability(job);
  const target = conversationMessageTarget(job);
  if (!target) return false;
  promptDreaminaReverificationForJob(job);
  const mediaLabel = job.channel === "audio" ? "音频" : job.channel === "video" ? "视频" : "图片";
  const batchTotal = Math.max(1, Number(job.target?.mediaBatchTotal) || 1);
  const batchIndex = Math.max(1, Number(job.target?.mediaBatchIndex) || 1);
  const batchItemLabel = String(job.target?.mediaBatchLabel || "").trim();
  const batchUnit = job.channel === "image" ? "张" : job.channel === "video" ? "个" : "项";
  const taskLabel = batchTotal > 1 ? `第 ${batchIndex}/${batchTotal} ${batchUnit}${batchItemLabel ? `「${batchItemLabel}」` : ""}` : mediaLabel;
  const message = target.messages[target.index];
  const userStopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  const nextStatus = userStopped ? "cancelled" : job.status;
  const nextContent = userStopped ? `${taskLabel}生成已停止。` : `${taskLabel}生成未完成：${mediaGenerationErrorText(job) || mediaGenerationPhaseText(job)}`;
  const recoverySignature = JSON.stringify({
    status: job.status,
    userStopped,
    content: nextContent,
    error: job.error || "",
    providerErrorCode: job.providerErrorCode || "",
    providerTaskId: job.providerTaskId || "",
    submissionState: job.submissionState || "",
    desiredAction: job.desiredAction || "run",
    availableActions: job.availableActions ?? {},
  });
  const previousExecution = message.execution ?? {};
  if (mediaRecoveryMessageSignatures.get(job.id) === recoverySignature
    && message.pending === false
    && message.content === nextContent
    && previousExecution.status === nextStatus
    && previousExecution.mediaJobStatus === job.status) return false;
  const endedAt = executionTimestampMilliseconds(job.userStoppedAt) || Date.now();
  const startedAt = executionTimestampMilliseconds(message.execution?.startedAt || job.startedAt || job.createdAt) || endedAt;
  Object.assign(message, {
    pending: false,
    content: nextContent,
    execution: {
      ...(message.execution ?? {}),
      status: nextStatus,
      mediaJobStatus: job.status,
      progressPercent: Number(job.progressPercent) || Number(message.execution?.progressPercent) || 1,
      generationJobId: job.id,
      mediaAvailableActions: job.availableActions ?? {},
      mediaProviderErrorCode: job.providerErrorCode || "",
      mediaError: mediaGenerationErrorText(job),
      mediaProviderTaskId: job.providerTaskId || "",
      mediaSubmissionState: job.submissionState || "",
      desiredAction: job.desiredAction || "run",
      billingRisk: job.billingRisk || "",
      startedAt,
      endedAt,
      elapsedMs: Math.max(0, Number(job.elapsedMs) || endedAt - startedAt),
      result: userStopped ? `${taskLabel}：已停止` : `${taskLabel}：${mediaGenerationPhaseText(job)}`,
    },
  });
  mediaRecoveryMessageSignatures.set(job.id, recoverySignature);
  target.conversation.messages = clone(target.messages);
  if (target.conversation.id === state.activeConversationId) renderMessages();
  persist();
  mediaConversationProgressSaves.delete(job.id);
  scheduleConversationQueueDrain(job.target?.conversationId);
  void maybeOfferConversationImageQuotaFallback(job);
  return true;
};

const monitorConversationMediaJob = (job) => {
  if (!job?.id || ui.generationJobPolls.has(job.id)) return;
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped) {
    showInterruptedConversationMediaJob(job);
    return;
  }
  updateConversationMediaJobProgress(job, { forceRender: true, persistNow: true });
  const operation = waitForDocumentArtifactJob(job.id, {
    onProgress: (current) => updateConversationMediaJobProgress(current),
    onConnectionError: ({ lastJob }) => updateConversationMediaJobProgress(lastJob || job, { connectionInterrupted: true }),
  })
    .then(async (completed) => {
      if (completed.status === "complete") await applyCompletedConversationMediaJob(completed);
      else showInterruptedConversationMediaJob(completed);
    })
    .catch((error) => showInterruptedConversationMediaJob({ ...job, status: "retry_required", error: error.message }))
    .finally(() => ui.generationJobPolls.delete(job.id));
  ui.generationJobPolls.set(job.id, operation);
};

const finalizeWhiteboardCompletedCandidate = (job) => {
  const target = job?.target ?? {};
  const candidateKey = whiteboardCandidateKey(target.nodeId, {
    workspacePath: target.workspacePath,
    documentId: target.documentId,
  });
  if (!whiteboardCandidateBelongsToJob(candidateKey, job?.id)) return false;
  const candidate = ui.whiteboardCandidates.get(candidateKey);
  const elapsedMs = Math.max(
    1,
    Number(candidate?.elapsedMs) || 0,
    Number(candidate?.startedAt) > 0 ? Date.now() - Number(candidate.startedAt) : 0,
    generationJobElapsedMs(job),
  );
  whiteboardGenerationCompletionTimes.delete(String(job.id));
  whiteboardGenerationCompletionTimes.set(String(job.id), elapsedMs);
  while (whiteboardGenerationCompletionTimes.size > WHITEBOARD_DISMISSED_METRIC_LIMIT) {
    whiteboardGenerationCompletionTimes.delete(whiteboardGenerationCompletionTimes.keys().next().value);
  }
  persistWhiteboardGenerationCompletionTimes();
  stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
  renderWhiteboardCandidateLocation({ workspacePath: target.workspacePath, documentId: target.documentId });
  return true;
};

const updateWhiteboardCompletedApplyStage = (job, cardApplyStage) => {
  const target = job?.target ?? {};
  const candidateKey = whiteboardCandidateKey(target.nodeId, {
    workspacePath: target.workspacePath,
    documentId: target.documentId,
  });
  if (!whiteboardCandidateBelongsToJob(candidateKey, job?.id)) return false;
  updateWhiteboardGenerationCandidate(candidateKey, {
    status: "complete",
    progressPercent: 100,
    providerProgressPercent: 100,
    cardApplyStage,
    cardApplyFailed: false,
  });
  return true;
};

const applyCompletedWhiteboardGenerationJob = async (job, { beforeCanvas = null } = {}) => {
  if (!job?.id || job.status !== "complete") return false;
  if (job.appliedAt) {
    finalizeWhiteboardCompletedCandidate(job);
    return false;
  }
  updateWhiteboardCompletedApplyStage(job, "saving");
  recordCustomGenerationJobCapability(job);
  if (usesDreaminaAccountCredits(job.request?.settings)) {
    void refreshDreaminaCreditAfterSuccessfulGeneration(job);
  }
  const target = job.target ?? {};
  const stopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  const candidateKey = whiteboardCandidateKey(target.nodeId, {
    workspacePath: target.workspacePath,
    documentId: target.documentId,
  });
  if (job.mode === "server" && !stopped) {
    const currentCandidate = ui.whiteboardCandidates.get(candidateKey);
    if (currentCandidate && !whiteboardCandidateBelongsToJob(candidateKey, job.id)) return false;
  }
  if (stopped) {
    const content = {
      ...whiteboardGenerationContentFromJob(job),
      recoverMissingTarget: false,
      preserveAssetOnly: true,
    };
    const landing = await writeWhiteboardGeneration({
      workspaceKind: target.workspaceKind,
      workspacePath: target.workspacePath,
      documentId: target.documentId,
      nodeId: target.nodeId,
      content,
      label: job.channel === "image" ? "保留已停止任务的图片资产" : "保留已停止任务的视频资产",
      retainCandidateUntilVerified: true,
    });
    const resultAsset = normalizeCanvas(landing?.documentState?.canvas).assets
      .find((asset) => asset.generationJobId === job.id);
    await markWhiteboardGenerationJobApplied(job.id, resultAsset?.id || "");
    releaseWhiteboardMediaSubmissionLockForJob(job);
    finalizeWhiteboardCompletedCandidate(job);
    return true;
  }
  const sameWorkspace = normalizedWorkspacePath(target.workspacePath) === normalizedWorkspacePath(state.settings.workspacePath);
  const currentDocument = sameWorkspace ? state.documents[target.documentId] : null;
  const historyCanvas = beforeCanvas ?? whiteboardCanvasSnapshot(currentDocument?.canvas);
  const content = { ...whiteboardGenerationContentFromJob(job), forceDurableCardWrite: true };
  if (["image", "video", "audio"].includes(content.kind) && !content.attachment?.relativePath) throw new Error("后台生成任务缺少已落盘附件");
  if (content.kind === "generated" && !content.text.trim()) throw new Error("后台生成任务缺少文本结果");
  if (content.kind === "generated" && sameWorkspace && state.activeDocument === target.documentId) {
    if (ui.whiteboardCandidates.has(candidateKey)) await finishWhiteboardTextReveal(candidateKey, content.text);
  }
  const landing = await writeWhiteboardGeneration({
    workspaceKind: target.workspaceKind,
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    nodeId: target.nodeId,
    beforeCanvas: historyCanvas,
    content,
    label: job.channel === "image" ? "恢复后台生成图片" : job.channel === "video" ? "恢复后台生成视频" : job.channel === "audio" ? "恢复后台生成音频" : "恢复后台生成文字",
    retainCandidateUntilVerified: true,
  });
  const landedDocument = landing?.documentState;
  const landedCanvas = normalizeCanvas(landedDocument?.canvas);
  const landedNode = landedCanvas.nodes.find((node) => node.id === target.nodeId);
  const landedAsset = landedCanvas.assets.find((asset) => asset.generationJobId === job.id);
  if (!landedAsset && landedNode?.generation?.jobId !== job.id) {
    throw new Error("生成文件已落盘，但目标卡片尚未确认写入；任务保持未完成并继续回写");
  }
  const resultAssetId = landedAsset?.id || landedNode?.id || "";
  updateWhiteboardCompletedApplyStage(job, "verifying");
  const cardReadback = await verifyWhiteboardGenerationCardReadback({ job, resultAssetId });
  await markWhiteboardGenerationJobApplied(job.id, resultAssetId, cardReadback);
  releaseWhiteboardMediaSubmissionLockForJob(job);
  finalizeWhiteboardCompletedCandidate(job);
  return true;
};

const completedWhiteboardApplyRetries = new Map();
const retryCompletedWhiteboardGenerationApply = (job, { beforeCanvas = null } = {}) => {
  if (!job?.id || job.status !== "complete") return Promise.resolve(false);
  if (completedWhiteboardApplyRetries.has(job.id)) return completedWhiteboardApplyRetries.get(job.id);
  const operation = (async () => {
    let lastError = null;
    for (const delayMs of [100, 350, 1_000, 2_500, 5_000, 10_000]) {
      await new Promise((resolveRetry) => setTimeout(resolveRetry, delayMs));
      try {
        const current = await fetchWhiteboardGenerationJob(job.id);
        if (current.appliedAt) {
          finalizeWhiteboardCompletedCandidate(current);
          return true;
        }
        if (current.status !== "complete") return false;
        if (await applyCompletedWhiteboardGenerationJob(current, { beforeCanvas })) {
          showToast(`${current.channel === "video" ? "视频" : current.channel === "image" ? "图片" : current.channel === "text" ? "文字" : "媒体"}已生成并写入卡片`);
          return true;
        }
      } catch (error) {
        lastError = error;
      }
    }
    if (lastError) {
      console.warn("completed whiteboard result awaiting local apply", job.id, lastError);
      const target = job.target ?? {};
      const candidateKey = whiteboardCandidateKey(target.nodeId, {
        workspacePath: target.workspacePath,
        documentId: target.documentId,
      });
      if (whiteboardCandidateBelongsToJob(candidateKey, job.id)) {
        updateWhiteboardGenerationCandidate(candidateKey, {
          status: "complete",
          cardApplyStage: "",
          cardApplyFailed: true,
          elapsedMs: Math.max(1, Date.now() - Number(ui.whiteboardCandidates.get(candidateKey)?.startedAt || Date.now())),
          error: `结果已经生成，但卡片回填失败：${lastError.message || lastError}`,
        });
      }
    }
    return false;
  })().finally(() => completedWhiteboardApplyRetries.delete(job.id));
  completedWhiteboardApplyRetries.set(job.id, operation);
  return operation;
};

const completedWhiteboardApplyPendingJob = (job, error) => ({
  ...job,
  status: "waiting_storage",
  providerStatus: "completed",
  error: `厂商生成已完成，结果已进入全部资产；正在自动同步到原卡片：${error?.message || error || "工作区暂不可写"}`,
});

const dreaminaReverifyPromptedJobs = new Set();
const dreaminaReverifyPendingJobs = new Map();
const dreaminaReverifyPromptQueue = new Map();
let dreaminaReverifyQueuePaused = false;

const rememberDreaminaJobForReverification = (job, settings) => {
  const profileId = String(settings?.dreaminaCliProfile || "").trim();
  if (!profileId) return false;
  const jobs = dreaminaReverifyPendingJobs.get(profileId) || new Set();
  if (job?.id) jobs.add(job.id);
  dreaminaReverifyPendingJobs.set(profileId, jobs);
  return true;
};

const resumeDreaminaJobsAfterVerification = async (profileId) => {
  const jobs = [...(dreaminaReverifyPendingJobs.get(profileId) || [])];
  if (!jobs.length) return;
  dreaminaReverifyPendingJobs.delete(profileId);
  dreaminaReverifyPromptQueue.delete(profileId);
  for (const jobId of jobs) {
    // A later credential expiry for the same durable task must be allowed to
    // surface again after this verification cycle has completed.
    dreaminaReverifyPromptedJobs.delete(jobId);
    try {
      const current = await fetchWhiteboardGenerationJob(jobId);
      // Automatic continuation is safe only when the provider already issued
      // a durable task ID. A credential check must never create a new paid job.
      if (!current.providerTaskId || !["waiting_credentials", "retry_required", "failed"].includes(current.status)) continue;
      const resumed = await controlMediaGenerationJob(jobId, "resume");
      if (resumed) {
        updateMediaJobTargetAfterAction(resumed);
        if (resumed.target?.targetType === "conversation-message") monitorConversationMediaJob(resumed);
        else if (resumed.target?.targetType === "document-artifact") monitorDocumentArtifactJob(resumed);
        else showInterruptedWhiteboardGenerationJob(resumed);
      }
    } catch (error) {
      showToast(`即梦账号已核验，但原任务 ${jobId.slice(-8)} 自动续接失败：${error.message}`);
    }
  }
};

const showNextQueuedDreaminaReverification = () => {
  if (elements.dreaminaReverifyDialog?.open) return false;
  const next = dreaminaReverifyPromptQueue.entries().next();
  if (next.done) return false;
  const [profileId, prompt] = next.value;
  dreaminaReverifyPromptQueue.delete(profileId);
  return openDreaminaReverifyDialog(prompt);
};

const queueDreaminaReverification = ({ settings, account = null, errorMessage = "", jobId = "" } = {}) => {
  const profileId = String(settings?.dreaminaCliProfile || account?.profileId || "").trim();
  if (!profileId) {
    showToast("当前连接未指定即梦账号，请重新选择配置");
    return false;
  }
  const visibleProfileId = elements.dreaminaReverifyDialog?.open
    ? String(elements.dreaminaReverifyDialog.dataset.profileId || "")
    : "";
  if (visibleProfileId !== profileId && !dreaminaReverifyPromptQueue.has(profileId)) {
    dreaminaReverifyPromptQueue.set(profileId, { settings, account, errorMessage, jobId });
  }
  showNextQueuedDreaminaReverification();
  return true;
};

const promptDreaminaReverificationForJob = (job) => {
  if (String(job?.status || "") !== "waiting_credentials" || !job?.id || dreaminaReverifyPromptedJobs.has(job.id)) return;
  if (!dreaminaFailureNeedsVerification({ job })) return;
  const settings = mediaGenerationSettingsForJob(job);
  const provider = String(settings?.provider || "").trim().toLowerCase();
  const adapter = String(settings?.adapter || "").trim().toLowerCase();
  if (provider !== "即梦" || adapter !== "cli") return;
  rememberDreaminaJobForReverification(job, settings);
  dreaminaReverifyPromptedJobs.add(job.id);
  queueDreaminaReverification({
    settings,
    account: dreaminaAccountForSettings(settings),
    errorMessage: mediaGenerationErrorText(job),
    jobId: job.id,
  });
};

const showInterruptedWhiteboardGenerationJob = (job) => {
  if (!job || typeof job !== "object" || !String(job.id || "").trim()) {
    console.warn("ignored invalid interrupted generation job", job);
    return;
  }
  recordCustomGenerationJobCapability(job);
  const target = job.target ?? {};
  const documentState = state.documents[target.documentId];
  if (!documentState || documentState.documentKind !== "whiteboard") return;
  const userStopped = Boolean(job.userStoppedAt || job.resultSuppressed || job.userStopped);
  const targetWasDeleted = canvasGenerationRecoveryTargetDeleted(documentState.canvas, {
    nodeId: target.nodeId,
    generationJobId: job.id,
    generationCreatedAt: job.createdAt,
  });
  if (userStopped || targetWasDeleted) {
    const candidateKey = whiteboardCandidateKey(target.nodeId, { workspacePath: target.workspacePath, documentId: target.documentId });
    releaseWhiteboardMediaSubmissionLockForJob(job);
    stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
    renderWhiteboardCandidateLocation({ workspacePath: target.workspacePath, documentId: target.documentId });
    return;
  }
  promptDreaminaReverificationForJob(job);
  const targetNode = normalizeCanvas(documentState.canvas).nodes.find((node) => node.id === target.nodeId);
  const candidateKey = whiteboardCandidateKey(target.nodeId, { workspacePath: target.workspacePath, documentId: target.documentId });
  if (targetNode && whiteboardMediaJobIsSupersededByNodeGeneration(job, targetNode)) {
    stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
    renderWhiteboardCandidateLocation({ workspacePath: target.workspacePath, documentId: target.documentId });
    return;
  }
  restoreInterruptedWhiteboardGenerationDraft(job);
  const targetMissing = !targetNode;
  if (targetMissing && job.availableActions?.autoReconcileProviderTask) {
    const prompt = String(job.request?.prompt || "").trim();
    const created = ensureWhiteboardGenerationRecoveryTarget({
      documentState,
      nodeId: target.nodeId,
      job,
      text: `${uiText("后台视频结果待找回")}\n\n${prompt}${prompt ? "\n\n" : ""}${uiText("请点击卡片中的“自动找回”，系统会按原任务记录查找，无需填写任务 ID。")}`,
    });
    if (created) persist();
  }
  const activeCandidate = ui.whiteboardCandidates.get(candidateKey);
  if (activeCandidate && activeCandidate.jobId !== job.id) return;
  if (!whiteboardMediaJobHoldsCard(job)) {
    stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
    renderWhiteboardCandidateLocation({
      workspacePath: target.workspacePath,
      documentId: target.documentId,
    });
    return;
  }
  beginWhiteboardGenerationCandidate({
    nodeId: target.nodeId,
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    channel: job.channel,
    kind: job.channel,
    status: job.status,
    progressPercent: Number(job.progressPercent) || 1,
    startedAt: generationJobInteractionStartedAt(job),
    elapsedMs: generationJobElapsedMs(job),
    text: job.channel === "text" ? String(job.error || "生成连接已中断，原提示词已保留，请重新生成。") : "",
    prompt: job.request?.prompt || "",
    jobId: job.id,
    providerTaskId: job.providerTaskId || "",
    submissionState: job.submissionState || "",
    submittedAt: job.submittedAt || "",
    billingRisk: job.billingRisk || "",
    resubmitConfirmationRequired: job.resubmitConfirmationRequired === true,
    desiredAction: job.desiredAction || "run",
    availableActions: job.availableActions ?? {},
    providerErrorCode: job.providerErrorCode || "",
    providerStatus: job.providerStatus || "",
    providerQueuePosition: job.providerQueuePosition ?? null,
    providerQueueLength: job.providerQueueLength ?? null,
    error: mediaGenerationErrorText(job),
  });
};

const monitorWhiteboardGenerationJob = (job) => {
  if (!job?.id || ui.generationJobPolls.has(job.id)) return;
  if (job.userStoppedAt || job.resultSuppressed || job.userStopped) {
    showInterruptedWhiteboardGenerationJob(job);
    return;
  }
  const target = job.target ?? {};
  const candidateKey = whiteboardCandidateKey(target.nodeId, { workspacePath: target.workspacePath, documentId: target.documentId });
  const activeCandidate = ui.whiteboardCandidates.get(candidateKey);
  if (!activeCandidate || activeCandidate.jobId === job.id) {
    beginWhiteboardGenerationCandidate({
      nodeId: target.nodeId,
      workspacePath: target.workspacePath,
      documentId: target.documentId,
      channel: job.channel,
      kind: job.channel,
      status: job.status,
      progressPercent: job.progressPercent,
      startedAt: generationJobInteractionStartedAt(job),
      prompt: job.request?.prompt || "",
      jobId: job.id,
      desiredAction: job.desiredAction || "run",
      availableActions: job.availableActions ?? {},
      providerErrorCode: job.providerErrorCode || "",
      providerStatus: job.providerStatus || "",
      providerTaskId: job.providerTaskId || "",
      submissionState: job.submissionState || "",
      submittedAt: job.submittedAt || "",
      providerProgressPercent: job.providerProgressPercent,
      automaticRecoveryInProgress: job.automaticRecoveryInProgress === true,
      providerQueuePosition: job.providerQueuePosition ?? null,
      providerQueueLength: job.providerQueueLength ?? null,
    });
  }
  const operation = waitForWhiteboardGenerationJob(job.id, candidateKey)
    .then(async (completed) => {
      if (completed.status === "complete") await applyCompletedWhiteboardGenerationJob(completed);
      else showInterruptedWhiteboardGenerationJob(completed);
    })
    .catch((error) => showInterruptedWhiteboardGenerationJob({ ...job, status: "retry_required", error: error.message }))
    .finally(() => ui.generationJobPolls.delete(job.id));
  ui.generationJobPolls.set(job.id, operation);
};

let dismissedMediaRecoveryMessage = "";

const showMediaRecoveryBanner = (message, { checking = false } = {}) => {
  if (!elements.mediaRecoveryBanner) return;
  const copy = String(message || "未能重新连接本机媒体任务，请重新检查。");
  if (!checking && dismissedMediaRecoveryMessage === copy) return;
  elements.mediaRecoveryBanner.hidden = false;
  elements.mediaRecoveryBanner.dataset.state = checking ? "checking" : "error";
  elements.mediaRecoveryBannerCopy.textContent = copy;
  elements.retryMediaRecovery.disabled = checking;
  elements.retryMediaRecovery.textContent = checking ? "正在检查…" : "重新检查";
};

const clearMediaRecoveryBanner = () => {
  if (!elements.mediaRecoveryBanner) return;
  elements.mediaRecoveryBanner.hidden = true;
  elements.mediaRecoveryBanner.dataset.state = "ready";
  elements.retryMediaRecovery.disabled = false;
  elements.retryMediaRecovery.textContent = "重新检查";
};

const mediaRecoveryAttentionStatuses = new Set([
  "queued",
  "submitting",
  "running",
  "polling",
  "downloading",
  "cancel_requested",
  "waiting_credentials",
  "waiting_storage",
  "retry_required",
  "reconciliation_required",
  "failed",
  "complete",
]);

const mediaRecoveryJobIsActionable = (job = {}) => {
  if (!mediaRecoveryJobBlocksOperation(job)) return false;
  const status = String(job.status || "");
  if (status === "complete") return true;
  const actions = job.availableActions && typeof job.availableActions === "object"
    ? job.availableActions
    : {};
  if (Object.values(actions).some(Boolean)) return true;
  // Keep an account-related failure visible only when the user can actually
  // resolve it through the verification dialog. Historical, non-actionable
  // jobs are intentionally omitted so the queue does not grow forever.
  return dreaminaFailureNeedsVerification({ job });
};

const mediaRecoveryJobNeedsAccountVerification = (job = {}) => (
  String(job.status || "") === "waiting_credentials"
  && dreaminaFailureNeedsVerification({ job })
);

const mediaRecoveryJobTargetLabel = (job) => {
  const target = job?.target ?? {};
  const documentTitle = state.documents?.[target.documentId]?.title;
  const documentLabel = documentTitle || target.documentId || "未命名文档";
  const nodeLabel = target.nodeId ? ` · 卡片 ${String(target.nodeId).slice(-8)}` : "";
  const workspaceLabel = normalizedWorkspacePath(target.workspacePath) === normalizedWorkspacePath(state.settings.workspacePath)
    ? "当前工作区"
    : target.workspacePath
      ? `其他工作区 · ${String(target.workspacePath).split(/[\\/]/).pop() || target.workspacePath}`
      : "未知工作区";
  return `${workspaceLabel} · ${documentLabel}${nodeLabel}`;
};

const renderMediaRecoveryJobs = (jobs = []) => {
  if (!elements.mediaRecoveryList) return;
  if (!jobs.length) {
    elements.mediaRecoveryList.innerHTML = '<p class="panel-empty">当前没有阻塞软件运行的媒体任务，软件可正常使用。</p>';
    return;
  }
  elements.mediaRecoveryList.innerHTML = jobs.map((job) => {
    const status = String(job.status || "");
    const actions = mediaGenerationActionMarkup({
      jobId: job.id,
      status,
      availableActions: job.availableActions ?? {},
      desiredAction: job.desiredAction || "run",
      providerErrorCode: job.providerErrorCode || "",
      error: job.error || "",
      providerTaskId: job.providerTaskId || "",
      submissionState: job.submissionState || "",
    });
    const reapply = status === "complete" && !job.appliedAt
      ? `<button class="media-job-resume" type="button" data-media-recovery-action="reapply" data-media-job-id="${escapeHtml(job.id)}" title="${escapeHtml(uiText("使用已生成结果重新回填卡片，不会重新生成"))}">${icon("\uE8B7", uiText("重新回填"))}<span>${escapeHtml(uiText("重新回填"))}</span></button>`
      : "";
    const verify = mediaRecoveryJobNeedsAccountVerification(job)
      ? `<button class="media-job-resume" type="button" data-media-recovery-action="verify" data-media-job-id="${escapeHtml(job.id)}" title="核验该任务原来使用的即梦配置">${icon("\uE77B", "核验账号")}<span>核验账号</span></button>`
      : "";
    const actionsMarkup = actions || reapply || verify
      ? `<div class="media-generation-actions recovery-dialog-actions">${actions}${reapply}${verify}</div>`
      : '<small class="media-recovery-no-action">请先重新读取任务状态。</small>';
    return `<article class="media-recovery-item" data-media-recovery-job="${escapeHtml(job.id)}"><header><strong>${escapeHtml(job.channel === "video" ? "视频任务" : job.channel === "image" ? "图片任务" : "媒体任务")}</strong><small>${escapeHtml(status || "未知状态")}</small></header><p>${escapeHtml(mediaRecoveryJobTargetLabel(job))}</p><p>${escapeHtml(mediaGenerationPhaseText(job))}</p>${actionsMarkup}</article>`;
  }).join("");
};

const readMediaRecoveryJobsForDialog = async () => {
  if (!elements.mediaRecoveryList) return [];
  const previousScrollTop = elements.mediaRecoveryList.scrollTop;
  const hasExistingItems = Boolean(elements.mediaRecoveryList.querySelector(".media-recovery-item"));
  if (!hasExistingItems) elements.mediaRecoveryList.innerHTML = '<p class="panel-empty">正在读取待处理任务…</p>';
  try {
    const { response, globalResponse, smokeResponse, payload, globalPayload, smokePayload } = await fetchMediaRecoveryJobs({
      fetchFn: fetch.bind(window),
      workspacePath: state.settings.workspacePath,
    });
    if (!response.ok || !payload.ok) throw new Error(payload.message || "生成任务恢复失败");
    if (!globalResponse.ok || !globalPayload.ok) throw new Error(globalPayload.message || "跨工作区生成任务恢复失败");
    const jobs = [...new Map([
      ...(payload.jobs ?? []),
      ...(globalPayload.jobs ?? []),
      ...(smokeResponse.ok && smokePayload.ok ? smokePayload.jobs ?? [] : []),
    ].map((job) => [job.id, job])).values()]
      .filter((job) => job.target?.targetType !== "capability-smoke")
      .filter((job) => mediaRecoveryAttentionStatuses.has(String(job.status || "")))
      .filter(mediaRecoveryJobBlocksOperation)
      .filter(mediaRecoveryJobIsActionable)
      .sort((left, right) => Date.parse(right.updatedAt || right.createdAt || "") - Date.parse(left.updatedAt || left.createdAt || ""));
    renderMediaRecoveryJobs(jobs);
    requestAnimationFrame(() => {
      if (elements.mediaRecoveryList) elements.mediaRecoveryList.scrollTop = Math.min(previousScrollTop, elements.mediaRecoveryList.scrollHeight);
    });
    return jobs;
  } catch (error) {
    elements.mediaRecoveryList.innerHTML = `<p class="panel-empty">待处理任务读取失败：${escapeHtml(error.message || "未知错误")}</p>`;
    return [];
  }
};

const openMediaRecoveryDialog = async () => {
  if (!elements.mediaRecoveryDialog) return;
  if (!elements.mediaRecoveryDialog.open) elements.mediaRecoveryDialog.showModal();
  await readMediaRecoveryJobsForDialog();
};

let mediaRecoveryFullScanKey = "";

const recoverWhiteboardGenerationJobsOnce = async ({ reportEmptyWorkspace = false, manual = false } = {}) => {
  if (manual) showMediaRecoveryBanner("正在重新读取本机媒体任务与厂商续接状态…", { checking: true });
  const recoveryScanKey = `${state.workspaceKind}:${normalizedWorkspacePath(state.settings.workspacePath)}`;
  const fullScan = manual || mediaRecoveryFullScanKey !== recoveryScanKey;
  try {
    // The first scan for a workspace (and every manual check) includes applied
    // jobs so a lost canvas asset ledger can be rebuilt from the durable job
    // receipt without resubmitting or charging the provider. Later visible
    // heartbeats only inspect unapplied jobs to keep the UI responsive.
    const { response, globalResponse, smokeResponse, payload, globalPayload, smokePayload } = await fetchMediaRecoveryJobs({
      fetchFn: fetch.bind(window),
      workspacePath: state.settings.workspacePath,
      includeApplied: fullScan,
      includeSmoke: fullScan,
    });
    if (!response.ok || !payload.ok) throw new Error(payload.message || "生成任务恢复失败");
    if (!globalResponse.ok || !globalPayload.ok) throw new Error(globalPayload.message || "跨工作区生成任务恢复失败");
    if (fullScan && smokeResponse.ok && smokePayload.ok) mediaRecoveryFullScanKey = recoveryScanKey;
    const jobs = [...new Map([
      ...(payload.jobs ?? []),
      ...(globalPayload.jobs ?? []),
      ...(smokeResponse.ok && smokePayload.ok ? smokePayload.jobs ?? [] : []),
    ].map((job) => [job.id, job])).values()];
    let recovered = 0;
    const recoveryIssues = [];
    for (const job of jobs) {
      try {
        // Capability evidence is independent from card readback. Rebind it
        // before any applied-job early return so restart/workspace recovery
        // cannot leave a stale failure beside a real successful generation.
        recordCustomGenerationJobCapability(job);
        if (job.target?.targetType === "composite-long-video-segment") {
          if (await recoverCompositeLongVideoChildJob(job)) recovered += 1;
          continue;
        }
        if (job.target?.targetType === "capability-smoke") {
          await recoverPaidMediaSmokeJob(job);
          recovered += 1;
          continue;
        }
        const targetWorkspaceIsActive = workspaceTargetIsActive(job.target?.workspaceKind, job.target?.workspacePath);
        if (job.appliedAt) {
          if (!targetWorkspaceIsActive) continue;
          if (job.target?.targetType === "conversation-message") {
            if (job.status === "complete" && job.result?.attachment && (
              !conversationMediaResultPresent(state, job)
              || conversationMediaTimingNeedsRepair(state, job)
            )) {
              await applyCompletedConversationMediaJob(job, { repairApplied: true });
              recovered += 1;
            }
            continue;
          }
          const targetDocument = state.documents[job.target?.documentId];
          const targetNode = normalizeCanvas(targetDocument?.canvas).nodes
            .find((node) => node.id === job.target?.nodeId);
          const recoveryContent = whiteboardGenerationContentFromJob(job);
          const landedRelativePath = String(job.result?.attachment?.relativePath || "").replace(/\\/g, "/").toLowerCase();
          const hasDurableAsset = normalizeCanvas(targetDocument?.canvas).assets
            .some((asset) => asset.generationJobId === job.id || (
              landedRelativePath
              && String(asset.attachment?.relativePath || "").replace(/\\/g, "/").toLowerCase() === landedRelativePath
            ));
          const canRepairAssetLedger = targetDocument?.documentKind === "whiteboard"
            && job.status === "complete"
            && ["image", "video", "audio"].includes(job.channel)
            && Boolean(job.result?.attachment?.relativePath);
          const recoveryAsset = {
            id: `recovered-${job.id}`,
            kind: job.channel,
            generationJobId: job.id,
            attachment: job.result?.attachment,
          };
          const assetSuppressed = assetHistoryEntryIsSuppressed(state, recoveryAsset);
          if (canRepairAssetLedger && !assetSuppressed && appliedWhiteboardJobCanSynchronizeCard(job, targetNode, recoveryContent)) {
            await repairAppliedWhiteboardCardDisplay(job, recoveryContent);
            recovered += 1;
          } else if (canRepairAssetLedger && !hasDurableAsset && !assetSuppressed) {
            const historyOnlyContent = {
              ...recoveryContent,
              recoverMissingTarget: false,
              preserveAssetOnly: true,
            };
            await repairAppliedWhiteboardAssetLedger(job, historyOnlyContent);
            recovered += 1;
          }
          continue;
        }
        if (job.target?.targetType === "conversation-message") {
          if (job.status === "complete") {
            if (!await applyCompletedConversationMediaJob(job)) throw new Error("目标对话或消息已经不存在");
            recovered += 1;
          } else if (MEDIA_JOB_ACTIVE_STATUSES.has(job.status)) {
            monitorConversationMediaJob(job);
            recovered += 1;
          } else if (MEDIA_JOB_ATTENTION_STATUSES.has(job.status) || job.status === "cancelled") {
            showInterruptedConversationMediaJob(job);
            recovered += 1;
          }
          continue;
        }
        if (job.target?.targetType === "document-artifact") {
          if (!targetWorkspaceIsActive || !state.documents[job.target?.documentId]) continue;
          if (job.status === "complete") {
            if (!await applyCompletedDocumentArtifactJob(job)) throw new Error("正文锚点已变化，附件已保留但尚未插入");
            recovered += 1;
          } else if (MEDIA_JOB_ACTIVE_STATUSES.has(job.status)) {
            monitorDocumentArtifactJob(job);
            recovered += 1;
          } else if (MEDIA_JOB_ATTENTION_STATUSES.has(job.status) || job.status === "cancelled") {
            showInterruptedDocumentArtifactJob(job);
            recovered += 1;
          }
          continue;
        }
        if (job.status === "complete") {
          if (!await applyCompletedWhiteboardGenerationJob(job)) throw new Error("媒体结果尚未应用到目标卡片");
          recovered += 1;
        } else if (MEDIA_JOB_ACTIVE_STATUSES.has(job.status)) {
          monitorWhiteboardGenerationJob(job);
          recovered += 1;
        } else if (MEDIA_JOB_ATTENTION_STATUSES.has(job.status) || job.status === "cancelled") {
          showInterruptedWhiteboardGenerationJob(job);
          recovered += 1;
        }
      } catch (error) {
        console.warn(`Generation job ${job.id} recovery skipped:`, error.message);
        if (mediaRecoveryJobBlocksOperation(job) && mediaRecoveryJobIsActionable(job)) {
          recoveryIssues.push(`${job.channel === "video" ? "视频" : job.channel === "image" ? "图片" : "媒体"}任务 ${job.id.slice(-8)}：${error.message}`);
        }
      }
    }
    if (recovered && activeWhiteboardDocument()) renderWhiteboard(activeWhiteboardDocument());
    if (recoveryIssues.length) {
      showMediaRecoveryBanner(`当前有 ${recoveryIssues.length} 项待处理问题：${recoveryIssues[0]}${recoveryIssues.length > 1 ? `；其余 ${recoveryIssues.length - 1} 项可在“查看待处理”中处理` : ""}`);
    } else if (!smokeResponse.ok || !smokePayload.ok) {
      showMediaRecoveryBanner(smokePayload.message || "常规媒体任务已恢复，但收费能力验证任务暂时无法读取；请重新检查。");
    } else {
      clearMediaRecoveryBanner();
      if (manual) showToast(recovered ? `媒体任务恢复检查完成，已处理 ${recovered} 项` : "媒体任务恢复检查完成，没有待处理任务");
    }
    return recovered;
  } catch (error) {
    console.warn("Generation job recovery failed:", error.message);
    if (isMediaRecoveryTransportError(error)) {
      if (manual) {
        showMediaRecoveryBanner("本机媒体服务正在恢复连接，任务记录与结果文件均已保留；神思会继续自动重试，无需重新提交任务。", { checking: true });
      } else {
        clearMediaRecoveryBanner();
      }
    } else {
      showMediaRecoveryBanner(`媒体任务恢复需要处理：${error.message || "任务状态暂不可读"}。任务记录仍保留，可重新检查，不会自动重复提交。`);
    }
    return 0;
  }
};

const mediaRecoveryReconciler = createMediaRecoveryReconciler({
  recover: recoverWhiteboardGenerationJobsOnce,
  // A hidden window cannot present recovery UI and the full applied-job scan
  // is expensive. Visibility/focus events still trigger an immediate pass
  // when the user returns.
  shouldRun: () => document.visibilityState !== "hidden",
});

const recoverWhiteboardGenerationJobs = (options = {}) => mediaRecoveryReconciler.run(options);

elements.retryMediaRecovery.addEventListener("click", () => {
  dismissedMediaRecoveryMessage = "";
  void recoverWhiteboardGenerationJobs({ reportEmptyWorkspace: true, manual: true });
});

elements.openMediaRecovery?.addEventListener("click", () => {
  void openMediaRecoveryDialog();
});

elements.refreshMediaRecoveryList?.addEventListener("click", () => {
  void readMediaRecoveryJobsForDialog();
});

elements.mediaRecoveryDialog?.addEventListener("click", async (event) => {
  const mediaAction = event.target.closest("[data-media-job-action][data-media-job-id]");
  if (mediaAction) {
    event.preventDefault();
    event.stopPropagation();
    mediaAction.disabled = true;
    try {
      await handleMediaGenerationActionElement(mediaAction);
      const remaining = await readMediaRecoveryJobsForDialog();
      if (!remaining.length) clearMediaRecoveryBanner();
    } catch (error) {
      showToast(error.message || "媒体任务操作失败");
      await readMediaRecoveryJobsForDialog();
    } finally {
      if (mediaAction.isConnected) mediaAction.disabled = false;
    }
    return;
  }
  const reapply = event.target.closest("[data-media-recovery-action='reapply'][data-media-job-id]");
  const verify = event.target.closest("[data-media-recovery-action='verify'][data-media-job-id]");
  if (verify) {
    event.preventDefault();
    verify.disabled = true;
    try {
      const job = await fetchWhiteboardGenerationJob(verify.dataset.mediaJobId);
      const settings = mediaGenerationSettingsForJob(job);
      if (!settings) throw new Error("该任务原配置已不存在，无法自动核验");
      openDreaminaReverifyDialog({ settings, account: dreaminaAccountForSettings(settings), jobId: job.id });
    } catch (error) {
      showToast(error.message || "账号核验未能开始");
    } finally {
      if (verify.isConnected) verify.disabled = false;
    }
    return;
  }
  if (!reapply) return;
  event.preventDefault();
  reapply.disabled = true;
  try {
    const job = await fetchWhiteboardGenerationJob(reapply.dataset.mediaJobId);
    if (job.status !== "complete" || job.appliedAt) throw new Error("该任务已经完成处理，无需重复回填");
    const applied = await retryCompletedWhiteboardGenerationApply(job);
    if (!applied) throw new Error("现有结果仍未能安全回填卡片，任务继续保留在待处理列表中");
    showToast("已使用现有结果回填卡片，不会重新生成或扣费");
    const remaining = await readMediaRecoveryJobsForDialog();
    if (!remaining.length) clearMediaRecoveryBanner();
  } catch (error) {
    showToast(error.message || "重新回填失败");
  } finally {
    if (reapply.isConnected) reapply.disabled = false;
  }
});

elements.dismissMediaRecovery.addEventListener("click", () => {
  dismissedMediaRecoveryMessage = String(elements.mediaRecoveryBannerCopy?.textContent || "");
  elements.mediaRecoveryBanner.hidden = true;
});

const formatWhiteboardGenerationDuration = (milliseconds = 0) => {
  const english = String(globalUiPreferences.uiLanguage || "").toLowerCase().startsWith("en");
  return formatGenerationDuration(milliseconds, { english });
};

const backgroundWorkspaceStateForSave = (workspaceState) => {
  const payload = { ...workspaceState, settings: { ...(workspaceState.settings ?? {}) } };
  delete payload.localCacheMode;
  delete payload.theme;
  delete payload.documentPatch;
  payload.settings = portableGenerationSettings(payload.settings);
  delete payload.settings.shensiRoot;
  delete payload.settings.workspacePath;
  payload.documents = Object.fromEntries(Object.entries(payload.documents ?? {})
    .filter(([, documentState]) => !documentState.virtual)
    .map(([id, documentState]) => documentState.documentKind === "whiteboard"
      ? [id, { ...documentState, html: "", markdown: "", canvas: normalizeCanvas(documentState.canvas) }]
      : [id, documentState]));
  return payload;
};

const applyWhiteboardGenerationToWorkspace = ({ workspaceState, documentId, nodeId, content, promoteCurrent = true }) => {
  const documentState = workspaceState.documents?.[documentId];
  if (!documentState || documentState.documentKind !== "whiteboard") throw new Error("目标白板已经不存在");
  const normalizedBefore = normalizeCanvas(documentState.canvas);
  const existingTarget = normalizedBefore.nodes.find((node) => node.id === nodeId);
  let recoveredTarget = false;
  if (!existingTarget) {
    if (content.recoverMissingTarget) recoveredTarget = ensureWhiteboardGenerationRecoveryTarget({
      documentState,
      nodeId,
      job: {
        id: content.generationJobId,
        createdAt: content.generationCreatedAt,
      },
    });
    else if (!content.preserveAssetOnly) throw new Error("目标卡片已经不存在");
  }
  const mediaKind = ["image", "video", "audio"].includes(content.kind);
  const attachments = mediaKind
    ? [...new Map([
      content.attachment,
      ...(Array.isArray(content.attachments) ? content.attachments : []),
    ].filter((item) => item?.relativePath).map((item) => [normalizedMediaRelativePath(item.relativePath), item])).values()]
    : [content.attachment];
  const namingTarget = normalizeCanvas(documentState.canvas).nodes.find((node) => node.id === nodeId);
  const nodeNames = generatedWhiteboardNodeNames(
    documentState.canvas,
    mediaKind ? content.kind : "text",
    mediaKind ? Math.max(1, attachments.length) : 1,
    namingTarget?.name,
  );
  let assetMetadataRepaired = false;
  if (mediaKind && content.generationJobId) {
    const expectedPaths = new Set(attachments.map((attachment) => normalizedMediaRelativePath(attachment.relativePath)).filter(Boolean));
    const currentCanvas = normalizeCanvas(documentState.canvas);
    const repairedAssets = currentCanvas.assets.map((asset) => {
      const pathMatches = expectedPaths.has(normalizedMediaRelativePath(asset.attachment?.relativePath));
      if (!pathMatches || (asset.generationJobId && asset.generationJobId !== content.generationJobId)) return asset;
      const repaired = {
        ...asset,
        generationJobId: content.generationJobId,
        sourceNodeId: asset.sourceNodeId || nodeId,
        prompt: asset.prompt || content.prompt || "",
      };
      if (JSON.stringify(repaired) === JSON.stringify(asset)) return asset;
      assetMetadataRepaired = true;
      return repaired;
    });
    if (assetMetadataRepaired) documentState.canvas = { ...currentCanvas, assets: repairedAssets };
  }
  const existingAssets = content.generationJobId
    ? normalizeCanvas(documentState.canvas).assets.filter((asset) => asset.generationJobId === content.generationJobId)
    : [];
  const existingPaths = new Set(existingAssets.map((asset) => normalizedMediaRelativePath(asset.attachment?.relativePath)).filter(Boolean));
  const duplicate = mediaKind
    ? attachments.length > 0 && attachments.every((attachment) => existingPaths.has(normalizedMediaRelativePath(attachment.relativePath)))
    : existingAssets.length > 0;
  const assets = [];
  for (let index = 0; index < attachments.length; index += 1) {
    const attachment = attachments[index];
    const attachmentPath = normalizedMediaRelativePath(attachment?.relativePath);
    if (mediaKind && existingPaths.has(attachmentPath)) {
      assets.push(existingAssets.find((asset) => normalizedMediaRelativePath(asset.attachment?.relativePath) === attachmentPath));
      continue;
    }
    if (!mediaKind && existingAssets.length) {
      assets.push(existingAssets[0]);
      continue;
    }
    const asset = {
      id: uid("canvas-asset"),
      kind: mediaKind ? content.kind : "text",
      origin: "generated",
      text: content.text,
      prompt: content.prompt,
      elapsedMs: Math.max(0, Number(content.elapsedMs) || 0),
      attachment,
      aspectRatio: content.aspectRatio,
      generationJobId: content.generationJobId || "",
      mediaBatchId: content.mediaBatchId || "",
      mediaBatchIndex: content.mediaBatchIndex || 1,
      mediaBatchTotal: content.mediaBatchTotal || 1,
      mediaBatchLabel: content.mediaBatchLabel || "",
      mediaBatchDirectory: content.mediaBatchDirectory || "",
      mediaBatchIndexPath: content.mediaBatchIndexPath || "",
      whiteboardMediaDirectory: content.whiteboardMediaDirectory || "",
      whiteboardMediaIndexPath: content.whiteboardMediaIndexPath || "",
      novelCover: content.novelCover || null,
      sourceNodeId: nodeId,
      nodeName: nodeNames[index] || nodeNames[0],
      createdAt: content.generationCreatedAt || new Date().toISOString(),
    };
    assets.push(asset);
    documentState.canvas = appendCanvasAsset(documentState.canvas, asset);
  }
  const asset = assets[0];
  let cardSynchronized = false;
  if (promoteCurrent && (existingTarget || recoveredTarget)) {
    const mainContent = { ...content, name: nodeNames[0], attachment: attachments[0] || content.attachment };
    const latestTarget = normalizeCanvas(documentState.canvas).nodes.find((node) => node.id === nodeId);
    if (!canvasNodeDisplaysGenerationContent(latestTarget, mainContent)) {
      documentState.canvas = snapshotCanvasNodeVersion(documentState.canvas, nodeId, { id: uid("canvas-version") });
      documentState.canvas = replaceCanvasNodeContent(documentState.canvas, nodeId, mainContent);
      cardSynchronized = true;
    }
    if (content.kind === "image" && attachments.length > 1) {
      const anchor = normalizeCanvas(documentState.canvas).nodes.find((node) => node.id === nodeId) || existingTarget;
      const inheritedIncomingEdges = normalizeCanvas(documentState.canvas).edges.filter((edge) => edge.toNode === nodeId);
      for (let index = 1; index < attachments.length; index += 1) {
        const attachment = attachments[index];
        const extraNodeId = `${nodeId}-result-${String(content.generationJobId || "media").slice(-8)}-${index + 1}`;
        if (normalizeCanvas(documentState.canvas).nodes.some((node) => node.id === extraNodeId)) continue;
        documentState.canvas = addCanvasImageNode(documentState.canvas, {
          id: extraNodeId,
          file: attachment.relativePath,
          name: nodeNames[index] || `${generatedWhiteboardNodeBaseName("image")} ${index + 1}`,
          mimeType: attachment.mimeType || "image/png",
          aspectRatio: content.aspectRatio || 1,
          x: Number(anchor?.x || 40) + (Number(anchor?.width || 320) + 28) * index,
          y: Number(anchor?.y || 40),
          width: Number(anchor?.width || 320),
          generation: {
            channel: "image",
            prompt: content.prompt,
            elapsedMs: content.elapsedMs,
            jobId: content.generationJobId,
            createdAt: content.generationCreatedAt,
            ...(Array.isArray(content.referenceOrder) ? { referenceOrder: content.referenceOrder } : {}),
          },
        });
        for (const edge of inheritedIncomingEdges) {
          documentState.canvas = addCanvasEdge(documentState.canvas, {
            fromNode: edge.fromNode,
            toNode: extraNodeId,
            order: edge.order,
            fromSide: edge.fromSide,
            toSide: edge.toSide,
            label: edge.label,
            color: edge.color,
          });
        }
        cardSynchronized = true;
      }
    }
  }
  if (!duplicate || cardSynchronized || recoveredTarget || assetMetadataRepaired) documentState.updatedAt = nowTime();
  return { documentState, asset, assets, duplicate, promoted: promoteCurrent, recoveredTarget, cardSynchronized, assetMetadataRepaired };
};

const enqueueInactiveWorkspaceGenerationWrite = createSerializedWorkspaceGenerationWriter();

const ensureDedicatedNotebookEntry = async (notebookName) => {
  await refreshNotebooks({ force: true, render: false });
  const normalizedName = String(notebookName || "").trim().toLocaleLowerCase();
  let entry = ui.notebooks.find((notebook) => !notebook.temporary && String(notebook.name || "").trim().toLocaleLowerCase() === normalizedName);
  if (entry) return entry;
  const response = await fetch("/api/notebooks/create", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: notebookName }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) {
    await refreshNotebooks({ force: true, render: false });
    entry = ui.notebooks.find((notebook) => !notebook.temporary && String(notebook.name || "").trim().toLocaleLowerCase() === normalizedName);
    if (entry) return entry;
    throw new Error(payload.message || `无法建立“${notebookName}”笔记本`);
  }
  ui.workspaceListCacheAt.notebook = 0;
  await refreshNotebooks({ force: true, render: false });
  return ui.notebooks.find((notebook) => notebook.workspacePath === payload.notebook.workspacePath)
    || payload.notebook;
};

const captureNotebookLandingDestination = (destination) => {
  if (!destination || destination.placement !== "active_notebook") return destination;
  const activeNotebook = state.workspaceKind === "notebook"
    && !workspaceHasNoActiveEntry()
    && !state.temporaryNotebook
    && !state.readOnly
    && state.settings.workspacePath
    ? { workspacePath: state.settings.workspacePath, notebookName: state.projectName }
    : null;
  const rememberedNotebook = storedWorkspaceKindHistory().notebook;
  const target = activeNotebook || (rememberedNotebook?.workspacePath ? {
    workspacePath: rememberedNotebook.workspacePath,
    notebookName: rememberedNotebook.projectName,
  } : null);
  return target ? { ...destination, ...target } : destination;
};

const notebookEntryForLandingDestination = async (destination = {}) => {
  if (destination.placement === "dedicated_notebook") {
    if (!destination.notebookName) throw new Error("专用笔记本名称缺失");
    return ensureDedicatedNotebookEntry(destination.notebookName);
  }
  if (destination.placement !== "active_notebook") throw new Error("单篇成品缺少明确的笔记落点");

  const capturedPath = String(destination.workspacePath || "").trim();
  if (capturedPath && workspaceTargetIsActive("notebook", capturedPath) && (state.temporaryNotebook || state.readOnly)) {
    throw new Error("生成时选择的笔记本当前为只读状态，请先选择可写笔记本后重新生成");
  }
  if (capturedPath && workspaceTargetIsActive("notebook", capturedPath)) {
    return { name: destination.notebookName || state.projectName, workspacePath: capturedPath };
  }
  await refreshNotebooks({ force: true, render: false });
  if (capturedPath) {
    const capturedEntry = ui.notebooks.find((notebook) => !notebook.temporary
      && normalizedWorkspacePath(notebook.workspacePath) === normalizedWorkspacePath(capturedPath));
    if (capturedEntry) return capturedEntry;
    throw new Error(`原先选择的笔记本“${destination.notebookName || capturedPath}”已不可用，请先选择新的笔记本后重新生成`);
  }

  if (state.workspaceKind === "notebook" && !workspaceHasNoActiveEntry() && !state.temporaryNotebook && !state.readOnly && state.settings.workspacePath) {
    return { name: state.projectName, workspacePath: state.settings.workspacePath };
  }
  const rememberedNotebook = storedWorkspaceKindHistory().notebook;
  const rememberedEntry = rememberedNotebook?.workspacePath
    ? ui.notebooks.find((notebook) => !notebook.temporary
      && normalizedWorkspacePath(notebook.workspacePath) === normalizedWorkspacePath(rememberedNotebook.workspacePath))
    : null;
  if (rememberedEntry) return rememberedEntry;
  throw new Error("请先打开或新建一个用于存放普通笔记成品的笔记本；系统不会自动建立“短视频脚本”“短篇小说”或“提示词”笔记本");
};

const standaloneNotebookLandingContent = ({ candidate = "", destination = null } = {}) => {
  const fallbackTitle = `未命名${destination?.label || "文档"}`;
  const parts = standaloneDocumentParts({ content: candidate, fallbackTitle });
  const html = compactGeneratedLandingHtml(stripMatchingLeadingHeadingHtml(proseToHtml(parts.body), [parts.title]));
  return { ...parts, html };
};

const saveStandaloneNotebookDeliverable = async ({ candidate = "", target = null } = {}) => {
  const destination = target?.notebookDestination;
  if (!destination?.deliverableType) throw new Error("单篇成品缺少确定的笔记归类目标");
  const entry = await notebookEntryForLandingDestination(destination);
  const resolvedNotebookName = entry?.name || destination.notebookName || "当前笔记本";
  if (!entry?.workspacePath) throw new Error(`“${resolvedNotebookName}”笔记本路径不可用`);
  const content = standaloneNotebookLandingContent({ candidate, destination });
  const sourceMessage = [...state.messages].reverse().find((message) => message.role === "user");
  const landingKey = String(target.generationAttemptRequestId || `${state.settings.workspacePath}:${activeConversation()?.id || "conversation"}:${sourceMessage?.id || content.title}`);
  const mutation = {
    notebookName: resolvedNotebookName,
    deliverableType: destination.deliverableType,
    title: content.title,
    html: content.html,
    landingKey,
    sourceWorkspaceName: state.projectName,
    sourceConversationId: activeConversation()?.id || "",
    updatedAt: nowTime(),
  };

  if (workspaceTargetIsActive("notebook", entry.workspacePath)) {
    const result = materializeNotebookDeliverable(state, mutation);
    const conversation = activeConversation();
    if (conversation) {
      conversation.boundDocumentId = result.documentId;
      conversation.intentTarget = { documentId: result.documentId, explicitArtifact: true };
    }
    elements.editor.dataset.document = "";
    await saveWorkspace({ throwOnError: true, operationDocumentIds: [result.documentId] });
    return {
      ...result,
      workspacePath: entry.workspacePath,
      notebookName: resolvedNotebookName,
      content,
      batchLandingReceipt: clone(ui.lastWorkspaceLandingReceipt),
    };
  }

  const key = workspaceCacheKey("notebook", entry.workspacePath);
  const receipt = await enqueueInactiveWorkspaceGenerationWrite({
    key,
    loadLatest: () => fetchWorkspacePayload(entry.workspacePath),
    merge: (loaded) => {
      const workspaceState = loaded?.state
        ? clone(loaded.state)
        : createBlankNotebookState({
          name: resolvedNotebookName,
          workspacePath: entry.workspacePath,
          settings: { uiLanguage: globalUiPreferences.uiLanguage },
        });
      const result = materializeNotebookDeliverable(workspaceState, mutation);
      return { workspaceState, result };
    },
    save: async ({ workspaceState, result }, loaded) => {
      const request = await workspaceSaveRequest({
        workspacePath: entry.workspacePath,
        expectedStateStamp: loaded?.stateStamp || "",
        state: backgroundWorkspaceStateForSave(workspaceState),
        operationDocumentIds: [result.documentId],
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw workspaceSaveError(response, payload);
      if (payload.savedAt) workspaceState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind: "notebook",
        workspacePath: entry.workspacePath,
        workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        prepared: true,
      });
      return {
        result,
        workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        batchLandingReceipt: payload.batchLandingReceipt ?? null,
      };
    },
  });
  return {
    ...receipt.result,
    workspacePath: entry.workspacePath,
    notebookName: resolvedNotebookName,
    content,
    batchLandingReceipt: clone(receipt.batchLandingReceipt),
  };
};

const workspaceTargetIsActive = (workspaceKind, workspacePath) => (
  state.workspaceKind === (workspaceKind === "notebook" ? "notebook" : "project")
  && normalizedWorkspacePath(state.settings.workspacePath) === normalizedWorkspacePath(workspacePath)
  && !workspaceHasNoActiveEntry()
);

const withActiveWorkspaceFormalLandingLock = async (task) => {
  if (ui.formalLandingPromise) await ui.formalLandingPromise.catch(() => {});
  let release;
  const lock = new Promise((resolve) => { release = resolve; });
  ui.formalLandingPromise = lock;
  try {
    return await task();
  } finally {
    release();
    if (ui.formalLandingPromise === lock) ui.formalLandingPromise = null;
  }
};

const backgroundFormalLandingOperation = ({
  documentId,
  source,
  target,
  instruction,
  authorization,
  workspaceState,
  operationId,
} = {}) => {
  const existing = workspaceState.documents?.[documentId] ?? null;
  const extracted = extractFormalArtifacts({ response: source, instruction, target, writeAuthorization: authorization });
  const artifact = extracted.artifacts?.find((item) => !item.targetDocumentId || item.targetDocumentId === documentId)
    || extracted.artifacts?.[0]
    || null;
  const requestedTitle = String(
    artifact?.title
    || leadingFormalDocumentTitle(source)
    || target?.chapterTitle
    || target?.episodeTitle
    || target?.title
    || "",
  ).trim();
  const currentTitle = String(existing?.title || "").trim();
  const title = authorization.allowTitleMutation === true && requestedTitle && requestedTitle !== "未命名"
    ? freeDocumentTitle({ documentId, title: requestedTitle, language: existing?.titleLanguage || "zh-CN" })
    : currentTitle;
  const rawBody = String(artifact?.content || source || "").trim();
  const body = stripCandidateChapterHeading(rawBody, title || currentTitle).trim();
  const action = String(authorization.action || "replace");
  const common = {
    operationId,
    targetDocumentId: documentId,
    targetDirectoryId: target?.directoryId || target?.moduleId || existing?.moduleId || "library",
    contentType: target?.contextDomain || target?.contentType || existing?.contextDomain || "document",
    ...(authorization.allowTitleMutation === true && title ? { requestedTitle: title } : {}),
  };
  if (action === "rename") return { ...common, type: "rename" };
  if (!body) throw Object.assign(new Error(`目标“${currentTitle || documentId}”没有可写入的正式正文`), { code: "DOCUMENT_TRANSACTION_EMPTY_CANDIDATE" });
  if (action === "create") return { ...common, type: "create", content: body };
  if (!existing) {
    throw Object.assign(new Error(`目标文档不存在：${documentId}；生成候选已保留，未改写其他文档`), {
      code: "DOCUMENT_TARGET_NOT_FOUND",
      documentId,
    });
  }
  if (action === "append") return { ...common, type: "append", content: body };
  if (action === "patch") {
    const previous = String(existing.markdown || documentTextFromHtml(existing.html || ""));
    const insertionPlan = inferContextualInsertionEditPlan({
      instruction,
      targetDocumentId: documentId,
      currentContent: previous,
      candidateContent: body,
      executionSurface: "agent",
      requestId: operationId,
      baselineRevision: contentRevision(previous),
    });
    const semanticPatch = insertionPlan ? null : semanticSectionPatch({ currentContent: previous, candidate: body, instruction });
    const exactPlan = insertionPlan || semanticPatch ? null : inferExactReplacementEditPlan({
      instruction,
      targetDocumentId: documentId,
      currentContent: previous,
      executionSurface: "chat",
      requestId: operationId,
      baselineRevision: contentRevision(previous),
    });
    const contextualReplacementPlan = insertionPlan || semanticPatch || exactPlan ? null : inferContextualReplacementEditPlan({
      instruction,
      targetDocumentId: documentId,
      currentContent: previous,
      candidateContent: body,
      executionSurface: "agent",
      requestId: operationId,
      baselineRevision: contentRevision(previous),
    });
    const patches = insertionPlan ? patchesFromDocumentEditPlan(insertionPlan) : semanticPatch ? [{
      type: "range",
      editId: `${operationId}-semantic`,
      start: semanticPatch.start,
      end: semanticPatch.end,
      expectedText: semanticPatch.previous,
      content: semanticPatch.replacement,
    }] : exactPlan ? patchesFromDocumentEditPlan(exactPlan) : contextualReplacementPlan ? patchesFromDocumentEditPlan(contextualReplacementPlan) : [];
    if (!patches.length) throw Object.assign(new Error("局部修改没有形成可在原工作区重放的唯一锚点，生成结果已保留但没有覆盖正文"), { code: "DOCUMENT_TRANSACTION_EMPTY_PATCH" });
    return { ...common, type: "patch", patches };
  }
  return { ...common, type: "replace", content: body };
};

const landFormalCandidateInPinnedWorkspace = async ({
  reply,
  target,
  creativeTask,
  instruction,
  workspaceScope,
  requestId,
} = {}) => {
  const workspacePath = String(workspaceScope?.workspacePath || creativeTask?.target?.workspacePath || "").trim();
  const workspaceKind = workspaceScope?.workspaceKind === "notebook" ? "notebook" : "project";
  const candidate = String(reply?.candidate || "").trim();
  const authorization = reply?.writeAuthorization || reply?.engineExecution?.writeAuthorization || creativeTask?.writeAuthorization;
  if (!workspacePath || !candidate || authorization?.state !== "commit") throw new Error("原工作区正式落盘参数不完整");
  const loaded = await fetchWorkspacePayload(workspacePath);
  const workspaceState = loaded?.state ? clone(loaded.state) : null;
  if (!workspaceState) throw new Error("发起任务的原工作区已经不存在");
  const targetIds = Array.isArray(authorization.targetDocumentIds) ? authorization.targetDocumentIds.map(String).filter(Boolean) : [];
  const currentRevisions = Object.fromEntries(targetIds.map((documentId) => [
    documentId,
    formalDocumentWriteRevisionFromState(workspaceState, documentId),
  ]));
  const targetDecision = liveWriteTargetDecision({
    action: authorization.action,
    expectedRevisions: authorization.expectedRevisions,
    currentRevisions,
    workspaceMatches: false,
  });
  if (targetDecision.action === "regenerate_from_latest") {
    throw Object.assign(new Error("原工作区正文在最终生成后再次变化，已暂停自动写入并保留旧候选；请选择按旧候选写入、重读最新版重新生成或其他目标"), { code: "DOCUMENT_REVISION_CONFLICT" });
  }
  const rebasedAuthorization = targetDecision.action === "rebase_title_only"
    ? rebaseFormalWriteAuthorization(authorization, { expectedRevisions: currentRevisions, reason: "title_only_rebased_in_pinned_workspace" })
    : authorization;
  const boundAuthorization = bindFormalWriteCandidate(rebasedAuthorization, {
    candidate,
    targetDocumentIds: targetIds,
    expectedRevisions: targetDecision.action === "rebase_title_only" ? currentRevisions : authorization.expectedRevisions,
  });
  const replyDocuments = Array.isArray(reply?.candidateDocuments) && reply.candidateDocuments.length
    ? reply.candidateDocuments
    : [{ content: candidate, target }];
  const operations = targetIds.map((documentId, index) => {
    const sourceDocument = replyDocuments.find((item) => item?.target?.documentId === documentId) || replyDocuments[index] || replyDocuments[0];
    return backgroundFormalLandingOperation({
      documentId,
      source: sourceDocument?.content || candidate,
      target: sourceDocument?.target || target,
      instruction,
      authorization: boundAuthorization,
      workspaceState,
      operationId: `${requestId || "background-write"}-${index + 1}`,
    });
  });
  const response = await fetch("/api/document-transactions/execute", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      workspacePath,
      task: {
        ...creativeTask,
        taskId: requestId || creativeTask?.taskId,
        executionSurface: creativeTask?.executionSurface === "agent" ? "agent" : "chat",
        instruction,
        authorizedCandidate: candidate,
        writeAuthorization: boundAuthorization,
      },
      operations,
      expectedRevisions: boundAuthorization.expectedRevisions,
      commitMode: "atomic",
      requestId,
      batchId: requestId ? `batch-${requestId}` : "",
    }),
  });
  const receipt = await response.json().catch(() => null);
  if (!response.ok || receipt?.verified !== true) throw new Error(receipt?.message || receipt?.failures?.[0]?.error || "原工作区磁盘复核失败");
  const latest = await fetchWorkspacePayload(workspacePath);
  cacheWorkspaceState({
    workspaceKind,
    workspacePath,
    workspaceState: latest.state,
    stateStamp: latest.stateStamp || "",
    prepared: false,
  });
  const landedDocuments = targetIds.map((documentId) => ({
    documentId,
    title: latest.state?.documents?.[documentId]?.title || documentId,
    content: String(latest.state?.documents?.[documentId]?.markdown || documentTextFromHtml(latest.state?.documents?.[documentId]?.html || "")),
  }));
  const landingManifest = buildLandingManifest({
    source: candidate,
    documents: landedDocuments.map((document) => ({ ...document, target: { documentId: document.documentId } })),
    workspaceKind,
    workspacePath,
    workspaceName: workspaceScope?.workspaceName || creativeTask?.target?.workspaceName || "",
    batchLandingReceipt: receipt,
  });
  const materialUpdatePrompt = materialUpdatePromptFor({
    documentIds: targetIds,
    executionSurface: creativeTask?.executionSurface === "agent" ? "agent" : "chat",
    workspaceState: latest.state,
  });
  return {
    landingManifest,
    landingReceipt: receipt,
    landedDocuments,
    materialUpdatePrompt: clone(materialUpdatePrompt),
    content: `正式内容已写入发起任务时的原工作区“${workspaceScope?.workspaceName || creativeTask?.target?.workspaceName || "目标工作区"}”，当前浏览位置未改变；历史版本与磁盘回读均已校验。`,
  };
};

const savePinnedConversationCompletion = async ({
  workspaceKind = "project",
  workspacePath = "",
  conversationId = "",
  messages = [],
  candidateState = null,
  conversationState = null,
  force = false,
} = {}) => {
  const targetPath = String(workspacePath || "").trim();
  if (!targetPath || !conversationId || (!force && workspaceTargetIsActive(workspaceKind, targetPath))) return false;
  return enqueueInactiveWorkspaceGenerationWrite({
    key: workspaceCacheKey(workspaceKind, targetPath),
    loadLatest: () => fetchWorkspacePayload(targetPath),
    merge: (loaded) => {
      const workspaceState = loaded?.state ? clone(loaded.state) : null;
      if (!workspaceState) throw new Error("发起任务的原工作区已经不存在");
      const conversation = (workspaceState.conversations ?? []).find((item) => item.id === conversationId);
      if (!conversation) throw new Error("发起任务的原对话已经不存在");
      const completionMessages = clone(messages);
      const storedMessages = conversation.messages ?? [];
      const storedById = new Map(storedMessages.map((message) => [message?.id, message]));
      const completionIds = new Set(completionMessages.map((message) => message?.id).filter(Boolean));
      conversation.messages = completionMessages.map((message) => ({
        ...(storedById.get(message?.id) ?? {}),
        ...message,
      }));
      conversation.messages.push(...storedMessages.filter((message) => !message?.id || !completionIds.has(message.id)));
      // A background completion may race with a later queued instruction. Keep
      // the live queue and snapshots, while retaining remote queue items that
      // were created after this task started. Explicit queue acknowledgements
      // remove only the matching item/lease pair instead of resurrecting it.
      if (conversationState && Object.hasOwn(conversationState, "queue")) {
        const liveQueue = Array.isArray(conversationState.queue) ? clone(conversationState.queue) : [];
        const liveIds = new Set(liveQueue.map((item) => String(item?.id || "")).filter(Boolean));
        const acknowledgements = new Set(Array.isArray(conversationState.queueAcknowledgements)
          ? conversationState.queueAcknowledgements.map(String)
          : []);
        const storedQueue = Array.isArray(conversation.queue) ? conversation.queue : [];
        const retainedRemoteQueue = storedQueue.filter((item) => {
          const itemId = String(item?.id || "");
          if (!itemId || liveIds.has(itemId)) return false;
          const receiptKey = `${itemId}::${String(item?.leaseId || "")}`;
          return !acknowledgements.has(receiptKey);
        });
        conversation.queue = [...liveQueue, ...clone(retainedRemoteQueue)];
      }
      if (conversationState && Object.hasOwn(conversationState, "queueAcknowledgements")) {
        const storedAcknowledgements = Array.isArray(conversation.queueAcknowledgements)
          ? conversation.queueAcknowledgements
          : [];
        const liveAcknowledgements = Array.isArray(conversationState.queueAcknowledgements)
          ? conversationState.queueAcknowledgements
          : [];
        conversation.queueAcknowledgements = [...new Set([
          ...storedAcknowledgements.map(String),
          ...liveAcknowledgements.map(String),
        ])].slice(-200);
      }
      if (conversationState && Object.hasOwn(conversationState, "snapshots")) {
        conversation.snapshots = {
          ...(conversation.snapshots ?? {}),
          ...(clone(conversationState.snapshots ?? {})),
        };
      }
      for (const key of ["nativeAgentRun", "agentQuestion", "candidateBranchGroups"]) {
        if (conversationState && Object.hasOwn(conversationState, key)) conversation[key] = clone(conversationState[key]);
      }
      if (candidateState) {
        conversation.currentCandidate = String(candidateState.currentCandidate || "");
        conversation.currentCandidateTarget = clone(candidateState.currentCandidateTarget ?? null);
        conversation.currentCandidateMemoryUpdate = clone(candidateState.currentCandidateMemoryUpdate ?? null);
        conversation.currentCandidateAuthorization = clone(candidateState.currentCandidateAuthorization ?? null);
      }
      const pendingMaterialDocumentIds = [...new Set(completionMessages.flatMap((message) => {
        const prompt = message?.materialUpdatePrompt;
        if (prompt?.kind !== "material_update_prompt" || prompt.status === "complete") return [];
        return prompt.sourceDocumentIds ?? prompt.documentIds ?? [];
      }).map(String).filter(Boolean))];
      const changedDocumentIds = new Set();
      if (pendingMaterialDocumentIds.length) {
        withSynchronousWorkspaceState(workspaceState, () => {
          markMaterialUpdatePending({
            documentIds: pendingMaterialDocumentIds,
            workspaceState,
          }).forEach((documentId) => changedDocumentIds.add(documentId));
        });
      }
      conversation.updatedAt = `今天 ${nowTime()}`;
      if (workspaceState.activeConversationId === conversationId) {
        workspaceState.messages = conversation.messages;
        workspaceState.snapshots = conversation.snapshots ?? workspaceState.snapshots ?? {};
        workspaceState.currentCandidate = conversation.currentCandidate ?? "";
        workspaceState.currentCandidateTarget = clone(conversation.currentCandidateTarget ?? null);
        workspaceState.currentCandidateMemoryUpdate = clone(conversation.currentCandidateMemoryUpdate ?? null);
        workspaceState.currentCandidateAuthorization = clone(conversation.currentCandidateAuthorization ?? null);
      }
      return { workspaceState, changedDocumentIds: [...changedDocumentIds] };
    },
    save: async ({ workspaceState, changedDocumentIds }, loaded) => {
      const request = await workspaceSaveRequest({
        workspacePath: targetPath,
        expectedStateStamp: loaded?.stateStamp || "",
        state: backgroundWorkspaceStateForSave(workspaceState),
        ...(changedDocumentIds?.length ? { operationDocumentIds: changedDocumentIds } : {}),
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw workspaceSaveError(response, payload);
      if (payload.savedAt) workspaceState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind,
        workspacePath: targetPath,
        workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        prepared: true,
      });
      return {
        workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
      };
    },
  });
};

const mergeAgentRuntimeConversationState = (workspaceState, runtime) => {
  if (!workspaceState || !runtime?.conversation?.id) return runtime ?? null;
  workspaceState.conversations ??= [];
  const conversationId = runtime.conversation.id;
  const index = workspaceState.conversations.findIndex((item) => item.id === conversationId);
  const storedConversation = index >= 0 ? workspaceState.conversations[index] : null;
  const liveConversation = runtime.conversation;
  const liveRecord = { ...liveConversation };
  const liveMessages = Array.isArray(runtime.messages)
    ? runtime.messages
    : Array.isArray(liveConversation.messages) ? liveConversation.messages : [];
  const storedMessages = storedConversation
    ? (workspaceState.activeConversationId === conversationId
        ? workspaceState.messages ?? storedConversation.messages ?? []
        : storedConversation.messages ?? [])
    : [];
  const liveMessageIds = new Set(liveMessages.map((message) => message?.id).filter(Boolean));
  const mergedMessages = [
    ...liveMessages,
    ...storedMessages.filter((message) => !message?.id || !liveMessageIds.has(message.id)),
  ];
  liveMessages.splice(0, liveMessages.length, ...mergedMessages);

  const liveQueue = Array.isArray(liveRecord.queue) ? liveRecord.queue : [];
  const liveQueueIds = new Set(liveQueue.map((item) => item?.id).filter(Boolean));
  liveQueue.push(...(storedConversation?.queue ?? []).filter((item) => !liveQueueIds.has(item?.id)));
  liveQueue.sort((left, right) => Number(left?.queuedAt || 0) - Number(right?.queuedAt || 0));
  const candidateSnapshot = {
    currentCandidate: String(runtime.candidateState?.currentCandidate ?? liveRecord.currentCandidate ?? ""),
    currentCandidateTarget: clone(runtime.candidateState?.currentCandidateTarget ?? liveRecord.currentCandidateTarget ?? null),
    currentCandidateMemoryUpdate: clone(runtime.candidateState?.currentCandidateMemoryUpdate ?? liveRecord.currentCandidateMemoryUpdate ?? null),
    currentCandidateAuthorization: clone(runtime.candidateState?.currentCandidateAuthorization ?? liveRecord.currentCandidateAuthorization ?? null),
  };
  Object.assign(liveConversation, storedConversation ?? {}, liveRecord, candidateSnapshot, {
    messages: liveMessages,
    queue: liveQueue,
    snapshots: {
      ...(storedConversation?.snapshots ?? {}),
      ...(liveRecord.snapshots ?? {}),
    },
  });
  if (index >= 0) workspaceState.conversations.splice(index, 1, liveConversation);
  else workspaceState.conversations.push(liveConversation);
  if (workspaceState.activeConversationId === conversationId) {
    workspaceState.messages = liveMessages;
    workspaceState.snapshots = liveConversation.snapshots;
    workspaceState.currentCandidate = liveConversation.currentCandidate;
    workspaceState.currentCandidateTarget = clone(liveConversation.currentCandidateTarget ?? null);
    workspaceState.currentCandidateMemoryUpdate = clone(liveConversation.currentCandidateMemoryUpdate ?? null);
    workspaceState.currentCandidateAuthorization = clone(liveConversation.currentCandidateAuthorization ?? null);
  }
  runtime.workspaceState = workspaceState;
  runtime.conversation = liveConversation;
  runtime.messages = liveMessages;
  runtime.candidateState = conversationCandidateState(liveConversation, workspaceState);
  return runtime;
};

const absorbAgentTaskWorkspaceState = (runtime, incomingState) => {
  if (!runtime || !incomingState) return runtime ?? null;
  const liveWorkspaceState = runtime.workspaceState || {};
  if (liveWorkspaceState !== incomingState) {
    const runtimeSettings = liveWorkspaceState.settings ?? {};
    const runtimeTheme = liveWorkspaceState.theme;
    Object.assign(liveWorkspaceState, incomingState, {
      settings: {
        ...(incomingState.settings ?? {}),
        ...runtimeSettings,
        workspacePath: runtime.workspaceScope?.workspacePath || runtimeSettings.workspacePath || "",
      },
      ...(runtimeTheme !== undefined ? { theme: runtimeTheme } : {}),
    });
  }
  return mergeAgentRuntimeConversationState(liveWorkspaceState, runtime);
};

const agentTaskRuntimeNeedsRetention = (runtime) => Boolean(
  runtime?.conversation?.agentOperationProposal
  || (runtime?.conversation?.queue ?? []).some((item) => ["queued", "dispatching", "editing"].includes(String(item?.state || "queued")))
  || (runtime?.messages ?? []).some((message) => message?.pending === true),
);

const persistAgentTaskRuntime = async (runtime, { finalize = false } = {}) => {
  if (!runtime?.conversation?.id || !runtime.workspaceScope?.workspacePath) return false;
  const active = workspaceTargetIsActive(runtime.workspaceScope.workspaceKind, runtime.workspaceScope.workspacePath);
  if (active) {
    mergeAgentRuntimeConversationState(state, runtime);
    persist();
  } else {
    const receipt = await savePinnedConversationCompletion({
      ...runtime.workspaceScope,
      conversationId: runtime.conversation.id,
      messages: runtime.messages,
      candidateState: runtime.candidateState,
      force: true,
    });
    if (receipt?.workspaceState) {
      absorbAgentTaskWorkspaceState(runtime, receipt.workspaceState);
      cacheWorkspaceState({
        ...runtime.workspaceScope,
        workspaceState: runtime.workspaceState,
        stateStamp: receipt.stateStamp || "",
        prepared: true,
      });
    }
  }
  if (finalize
    && ui.agentTaskRuntimes.get(runtime.conversation.id) === runtime
    && !agentTaskRuntimeNeedsRetention(runtime)) {
    ui.agentTaskRuntimes.delete(runtime.conversation.id);
  }
  return true;
};

const savePinnedAgentLandingMetadata = async ({ runtime, pending, conversation, landing } = {}) => {
  const scope = runtime?.workspaceScope;
  if (!scope?.workspacePath || !conversation?.id || !pending) return false;
  const landedDocumentIds = (landing?.landedDocuments ?? [])
    .map((item) => String(item?.documentId || ""))
    .filter(Boolean);
  const receipt = await enqueueInactiveWorkspaceGenerationWrite({
    key: workspaceCacheKey(scope.workspaceKind, scope.workspacePath),
    loadLatest: () => fetchWorkspacePayload(scope.workspacePath),
    merge: (loaded) => {
      const workspaceState = loaded?.state ? clone(loaded.state) : null;
      if (!workspaceState) throw new Error("Agent 原工作区已经不存在");
      const changedDocumentIds = new Set();
      withSynchronousWorkspaceState(workspaceState, () => {
        const materialDocumentIds = markMaterialUpdatePending({
          documentIds: landedDocumentIds,
          workspaceState,
        });
        materialDocumentIds.forEach((documentId) => changedDocumentIds.add(documentId));
        const materialUpdatePrompt = pending.materialUpdatePrompt
          || landing?.materialUpdatePrompt
          || materialUpdatePromptFor({
            documentIds: materialDocumentIds,
            executionSurface: "agent",
            workspaceState,
          });
        const storedConversation = (workspaceState.conversations ?? []).find((item) => item.id === conversation.id);
        const storedPending = storedConversation?.messages?.find((item) => item.id === pending.id);
        if (storedPending) {
          Object.assign(storedPending, clone(pending));
          storedPending.pending = false;
          if (materialUpdatePrompt) {
            storedPending.materialUpdatePrompt = {
              ...clone(materialUpdatePrompt),
              conversationId: conversation.id,
              messageId: storedPending.id,
              status: "pending",
            };
          }
        }
        if (storedConversation) {
          storedConversation.currentCandidate = "";
          storedConversation.currentCandidateTarget = null;
          storedConversation.currentCandidateMemoryUpdate = null;
          storedConversation.currentCandidateAuthorization = null;
          storedConversation.updatedAt = `今天 ${nowTime()}`;
        }
        if (workspaceState.activeConversationId === conversation.id && storedConversation) {
          workspaceState.messages = storedConversation.messages;
          workspaceState.currentCandidate = "";
          workspaceState.currentCandidateTarget = null;
          workspaceState.currentCandidateMemoryUpdate = null;
          workspaceState.currentCandidateAuthorization = null;
        }
      });
      return { workspaceState, changedDocumentIds: [...changedDocumentIds] };
    },
    save: async ({ workspaceState, changedDocumentIds }, loaded) => {
      const request = await workspaceSaveRequest({
        workspacePath: scope.workspacePath,
        expectedStateStamp: loaded?.stateStamp || "",
        state: backgroundWorkspaceStateForSave(workspaceState),
        operationDocumentIds: changedDocumentIds,
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw workspaceSaveError(response, payload);
      if (payload.savedAt) workspaceState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind: scope.workspaceKind,
        workspacePath: scope.workspacePath,
        workspaceState,
        stateStamp: payload.stateStamp || loaded?.stateStamp || "",
        prepared: true,
      });
      return { workspaceState };
    },
  });
  if (receipt?.workspaceState) {
    if (runtime?.candidateState) {
      runtime.candidateState.currentCandidate = "";
      runtime.candidateState.currentCandidateTarget = null;
      runtime.candidateState.currentCandidateMemoryUpdate = null;
      runtime.candidateState.currentCandidateAuthorization = null;
    }
    absorbAgentTaskWorkspaceState(runtime, receipt.workspaceState);
  }
  return receipt;
};

const synchronizeBackgroundGenerationIntoActiveWorkspace = async ({
  workspaceKind,
  workspacePath,
  documentId,
  nodeId,
  content,
  promotionContext,
  receipt,
  label,
}) => {
  if (!workspaceTargetIsActive(workspaceKind, workspacePath)) return false;
  if (ui.workspaceSavePromise) await ui.workspaceSavePromise.catch(() => false);
  if (!workspaceTargetIsActive(workspaceKind, workspacePath)) return false;
  const latest = await fetchWorkspacePayload(workspacePath);
  cacheWorkspaceState({
    workspaceKind,
    workspacePath,
    workspaceState: latest.state ?? receipt.workspaceState,
    stateStamp: latest.stateStamp || receipt.stateStamp || "",
    prepared: false,
  });
  if (!workspaceTargetIsActive(workspaceKind, workspacePath)) return false;
  const latestWorkspaceState = latest.state ?? receipt.workspaceState;
  const currentDocument = state.documents?.[documentId];
  const currentNode = normalizeCanvas(currentDocument?.canvas).nodes.find((node) => node.id === nodeId);
  const promoteCurrent = shouldPromoteMediaGenerationResult({
    ...promotionContext,
    completedJobId: content?.generationJobId,
    completedCreatedAt: content?.generationCreatedAt,
    currentGenerationJobId: currentNode?.generation?.jobId,
    currentGenerationCreatedAt: currentNode?.generation?.createdAt,
  });
  const canvasBeforeApply = whiteboardCanvasSnapshot(currentDocument?.canvas);
  const { documentState, asset, assets = [asset].filter(Boolean), duplicate, recoveredTarget, cardSynchronized, assetMetadataRepaired } = applyWhiteboardGenerationToWorkspace({
    workspaceState: state,
    documentId,
    nodeId,
    content,
    promoteCurrent: content?.preserveAssetOnly ? false : promoteCurrent,
  });
  // The background writer advanced the workspace's optimistic-concurrency
  // baseline while this project was inactive. Keep the active in-memory
  // documents (including edits made after switching back), but adopt the
  // latest savedAt token before persisting the merged generation result.
  if (latestWorkspaceState?.savedAt) state.savedAt = latestWorkspaceState.savedAt;
  ui.activeWorkspaceStamp = latest.stateStamp || receipt.stateStamp || ui.activeWorkspaceStamp;
  ui.workspaceDocumentHashes = documentSaveHashes(latestWorkspaceState?.documents ?? {});
  ui.workspaceBaselineStateHashes = workspaceStateHashes(latestWorkspaceState ?? {});
  ui.workspaceSaveError = null;
  if (!duplicate || recoveredTarget || cardSynchronized || assetMetadataRepaired) {
    pushWhiteboardHistory(assets.reduce((canvas, item) => appendCanvasAsset(canvas, item), canvasBeforeApply), { documentId, label });
    persist({ documentIds: [documentId] });
  }
  if (ui.workspaceDirty) {
    await ensureCurrentRecoveryCheckpoint();
    await flushWorkspaceSave({ throwOnError: true });
    cacheWorkspaceState({ workspaceKind, workspacePath, workspaceState: state, stateStamp: ui.activeWorkspaceStamp, prepared: true });
  } else {
    cacheWorkspaceState({ workspaceKind, workspacePath, workspaceState: state, stateStamp: ui.activeWorkspaceStamp, prepared: true });
    setAutoSaveState("saved");
  }
  if (state.activeDocument === documentId) renderWhiteboard(documentState);
  if (elements.whiteboardAssetDialog.open && state.activeDocument === documentId) renderWhiteboardAssets();
  if (elements.whiteboardCardHistoryDialog.open && state.activeDocument === documentId && ui.whiteboardCardHistoryNodeId === nodeId) renderWhiteboardCardHistory();
  if (recoveredTarget) showToast(uiText("原卡片已丢失，已在原白板建立找回结果卡片"));
  return true;
};

const saveInactiveWhiteboardGeneration = async ({ workspaceKind, workspacePath, documentId, nodeId, content, promotionContext = {} }) => {
  const targetKind = workspaceKind === "notebook" ? "notebook" : "project";
  const key = workspaceCacheKey(targetKind, workspacePath);
  return enqueueInactiveWorkspaceGenerationWrite({
    key,
    loadLatest: () => fetchWorkspacePayload(workspacePath),
    merge: (loaded) => {
      const workspaceState = loaded?.state ? clone(loaded.state) : null;
      if (!workspaceState) throw new Error("发起任务的工作区已经不存在");
      const latestDocument = workspaceState.documents?.[documentId];
      const latestNode = normalizeCanvas(latestDocument?.canvas).nodes.find((node) => node.id === nodeId);
      // The target workspace may have changed while this completion waited in
      // the serialized writer. Re-evaluate against the freshly loaded card so
      // an older task can be archived without rolling back a newer result.
      const promoteCurrent = shouldPromoteMediaGenerationResult({
        ...promotionContext,
        completedJobId: content?.generationJobId,
        completedCreatedAt: content?.generationCreatedAt,
        currentGenerationJobId: latestNode?.generation?.jobId,
        currentGenerationCreatedAt: latestNode?.generation?.createdAt,
      });
      const { documentState } = applyWhiteboardGenerationToWorkspace({ workspaceState, documentId, nodeId, content, promoteCurrent });
      return { workspaceState, documentState };
    },
    save: async ({ workspaceState, documentState }, loaded) => {
      const request = await workspaceSaveRequest({
        workspacePath,
        expectedStateStamp: loaded.stateStamp || "",
        state: backgroundWorkspaceStateForSave(workspaceState),
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) {
        const error = new Error(payload.message || "原白板后台保存失败");
        error.status = response.status;
        error.code = payload.code || "";
        throw error;
      }
      if (payload.savedAt) workspaceState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind: targetKind,
        workspacePath,
        workspaceState,
        stateStamp: payload.stateStamp || loaded.stateStamp || "",
        prepared: true,
      });
      return {
        documentState,
        workspaceState,
        stateStamp: payload.stateStamp || loaded.stateStamp || "",
      };
    },
  });
};

const saveInactiveConversationMediaGeneration = async (job) => {
  const workspaceKind = job.target?.workspaceKind === "notebook" ? "notebook" : "project";
  const workspacePath = String(job.target?.workspacePath || "");
  if (!workspacePath) throw new Error("对话媒体任务缺少原工作区路径");
  return enqueueInactiveWorkspaceGenerationWrite({
    key: workspaceCacheKey(workspaceKind, workspacePath),
    loadLatest: () => fetchWorkspacePayload(workspacePath),
    merge: (loaded) => {
      const workspaceState = loaded?.state ? clone(loaded.state) : null;
      if (!workspaceState) throw new Error("发起媒体任务的工作区已经不存在");
      const landing = applyConversationMediaResultToWorkspace(workspaceState, job, { timeLabel: nowTime() });
      return { workspaceState, landing };
    },
    save: async ({ workspaceState, landing }, loaded) => {
      if (landing.duplicate && !landing.metadataRepaired) {
        return { workspaceState, landing, stateStamp: loaded.stateStamp || "" };
      }
      const request = await workspaceSaveRequest({
        workspacePath,
        expectedStateStamp: loaded.stateStamp || "",
        state: backgroundWorkspaceStateForSave(workspaceState),
      });
      const response = await fetch("/api/workspace/save", {
        method: "POST",
        headers: request.headers,
        body: request.body,
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) {
        const error = new Error(payload.message || "原对话媒体结果后台保存失败");
        error.status = response.status;
        error.code = payload.code || "";
        throw error;
      }
      if (payload.savedAt) workspaceState.savedAt = payload.savedAt;
      cacheWorkspaceState({
        workspaceKind,
        workspacePath,
        workspaceState,
        stateStamp: payload.stateStamp || loaded.stateStamp || "",
        prepared: true,
      });
      return { workspaceState, landing, stateStamp: payload.stateStamp || loaded.stateStamp || "" };
    },
  });
};

const synchronizeBackgroundConversationIntoActiveWorkspace = async (job, receipt) => {
  const workspaceKind = job.target?.workspaceKind === "notebook" ? "notebook" : "project";
  const workspacePath = String(job.target?.workspacePath || "");
  if (!workspaceTargetIsActive(workspaceKind, workspacePath)) return false;
  if (ui.workspaceSavePromise) await ui.workspaceSavePromise.catch(() => false);
  if (!workspaceTargetIsActive(workspaceKind, workspacePath)) return false;
  const latest = await fetchWorkspacePayload(workspacePath);
  const latestWorkspaceState = latest.state ?? receipt.workspaceState;
  const landing = applyConversationMediaResultToWorkspace(state, job, { timeLabel: nowTime() });
  if (latestWorkspaceState?.savedAt) state.savedAt = latestWorkspaceState.savedAt;
  ui.activeWorkspaceStamp = latest.stateStamp || receipt.stateStamp || ui.activeWorkspaceStamp;
  ui.workspaceDocumentHashes = documentSaveHashes(latestWorkspaceState?.documents ?? {});
  ui.workspaceBaselineStateHashes = workspaceStateHashes(latestWorkspaceState ?? {});
  ui.workspaceSaveError = null;
  if (!landing.duplicate || landing.metadataRepaired) {
    persist();
    await ensureCurrentRecoveryCheckpoint();
    await flushWorkspaceSave({ throwOnError: true });
  } else {
    setAutoSaveState("saved");
  }
  cacheWorkspaceState({ workspaceKind, workspacePath, workspaceState: state, stateStamp: ui.activeWorkspaceStamp, prepared: true });
  if (landing.conversation.id === state.activeConversationId) renderMessages();
  return true;
};

const repairAppliedWhiteboardAssetLedger = async (job, content) => {
  const target = job?.target ?? {};
  const workspaceKind = target.workspaceKind === "notebook" ? "notebook" : "project";
  const label = job.channel === "image" ? "找回历史图片记录" : "找回历史视频记录";
  const receipt = await saveInactiveWhiteboardGeneration({
    workspaceKind,
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    nodeId: target.nodeId,
    content: { ...content, preserveAssetOnly: true },
    promotionContext: { completedJobId: content.generationJobId, completedCreatedAt: content.generationCreatedAt },
  });
  await synchronizeBackgroundGenerationIntoActiveWorkspace({
    workspaceKind,
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    nodeId: target.nodeId,
    content: { ...content, preserveAssetOnly: true },
    promotionContext: { completedJobId: content.generationJobId, completedCreatedAt: content.generationCreatedAt },
    receipt,
    label,
  });
  return true;
};

const repairAppliedWhiteboardCardDisplay = async (job, content) => {
  const target = job?.target ?? {};
  const landing = await writeWhiteboardGeneration({
    workspaceKind: target.workspaceKind === "notebook" ? "notebook" : "project",
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    nodeId: target.nodeId,
    content: {
      ...content,
      recoverMissingTarget: false,
      preserveAssetOnly: false,
      forceDurableCardWrite: true,
    },
    label: job.channel === "video" ? "同步生成视频到原卡片" : job.channel === "audio" ? "同步生成音频到原卡片" : "同步生成图片到原卡片",
  });
  const landedCanvas = normalizeCanvas(landing?.documentState?.canvas);
  const resultAsset = landedCanvas.assets.find((asset) => asset.generationJobId === job.id);
  await verifyWhiteboardGenerationCardReadback({ job, resultAssetId: resultAsset?.id || job.resultAssetId || "" });
  if (state.activeDocument === target.documentId) showToast("已将全部资产中的生成结果同步到原卡片");
  return true;
};

const writeWhiteboardGeneration = async ({ workspaceKind = state.workspaceKind, workspacePath, documentId, nodeId, beforeCanvas, content, label, retainCandidateUntilVerified = false }) => {
  const sameWorkspace = state.workspaceKind === (workspaceKind === "notebook" ? "notebook" : "project")
    && normalizedWorkspacePath(state.settings.workspacePath) === normalizedWorkspacePath(workspacePath);
  const candidateKey = whiteboardCandidateKey(nodeId, { workspacePath, documentId });
  const activeCandidate = ui.whiteboardCandidates.get(candidateKey);
  const completedJobId = String(content?.generationJobId || "");
  const activeJobId = String(activeCandidate?.jobId || "");
  // A previous task may finish while a new candidate is still compiling and has
  // not received its durable job id yet. Only the exact durable job may stop or
  // remove an existing candidate; otherwise the late result must stay isolated.
  const ownsCandidate = !activeCandidate || (Boolean(completedJobId) && activeJobId === completedJobId);
  const landedContent = ownsCandidate && Number(activeCandidate?.startedAt) > 0
    ? {
        ...content,
        elapsedMs: Math.max(
          Number(content?.elapsedMs) || 0,
          Date.now() - Number(activeCandidate.startedAt),
        ),
      }
    : content;
  const currentDocument = sameWorkspace ? state.documents[documentId] : null;
  const currentNode = normalizeCanvas(currentDocument?.canvas).nodes.find((node) => node.id === nodeId);
  const promotionContext = {
    activeCandidatePresent: Boolean(activeCandidate),
    activeCandidateJobId: activeJobId,
    completedJobId,
    completedCreatedAt: content?.generationCreatedAt,
  };
  const promoteCurrent = shouldPromoteMediaGenerationResult({
    ...promotionContext,
    currentGenerationJobId: currentNode?.generation?.jobId,
    currentGenerationCreatedAt: currentNode?.generation?.createdAt,
  });
  if (!sameWorkspace) {
    const receipt = await saveInactiveWhiteboardGeneration({ workspaceKind, workspacePath, documentId, nodeId, content: landedContent, promotionContext });
    const synchronized = await synchronizeBackgroundGenerationIntoActiveWorkspace({
      workspaceKind,
      workspacePath,
      documentId,
      nodeId,
      content: landedContent,
      promotionContext,
      receipt,
      label,
    });
    if (ownsCandidate && !retainCandidateUntilVerified) {
      stopWhiteboardGenerationCandidate(candidateKey);
      ui.whiteboardCandidates.delete(candidateKey);
      // The synchronization render happens before this background candidate is
      // released. Render once more so a completed card shows its durable total
      // time instead of retaining the final 99% candidate shell.
      if (synchronized && state.activeDocument === documentId) renderWhiteboard(state.documents[documentId]);
    }
    return { documentState: receipt.documentState, background: true };
  }
  const canvasBeforeApply = whiteboardCanvasSnapshot(currentDocument?.canvas ?? beforeCanvas);
  const { documentState, asset, assets = [asset].filter(Boolean), duplicate, recoveredTarget, cardSynchronized, assetMetadataRepaired } = applyWhiteboardGenerationToWorkspace({
    workspaceState: state,
    documentId,
    nodeId,
    content: landedContent,
    promoteCurrent: landedContent?.preserveAssetOnly ? false : promoteCurrent,
  });
  const landingChanged = !duplicate || recoveredTarget || cardSynchronized || assetMetadataRepaired;
  if (landingChanged) {
    const historyCanvas = assets.reduce((canvas, item) => appendCanvasAsset(canvas, item), canvasBeforeApply);
    pushWhiteboardHistory(historyCanvas, { documentId, label });
  }
  if (landingChanged || landedContent?.forceDurableCardWrite) {
    persist({ documentIds: [documentId] });
    await ensureCurrentRecoveryCheckpoint();
    await flushWorkspaceSave({ throwOnError: true });
  }
  if (ownsCandidate && !retainCandidateUntilVerified) {
    stopWhiteboardGenerationCandidate(candidateKey);
    ui.whiteboardCandidates.delete(candidateKey);
  }
  if (state.activeDocument === documentId) renderWhiteboard(documentState);
  if (elements.whiteboardAssetDialog.open && state.activeDocument === documentId) renderWhiteboardAssets();
  if (elements.whiteboardCardHistoryDialog.open && state.activeDocument === documentId && ui.whiteboardCardHistoryNodeId === nodeId) renderWhiteboardCardHistory();
  if (recoveredTarget) showToast(uiText("原卡片已丢失，已在原白板建立找回结果卡片"));
  return { documentState, background: false };
};

const verifyWhiteboardGenerationCardReadback = async ({ job, resultAssetId = "" } = {}) => {
  const target = job?.target ?? {};
  const loaded = await fetchWorkspacePayload(target.workspacePath);
  const persistedDocument = loaded?.state?.documents?.[target.documentId];
  if (!persistedDocument || persistedDocument.documentKind !== "whiteboard") {
    throw new Error("生成结果已保存，但回读时没有找到目标白板；任务保持在回填状态");
  }
  const persistedCanvas = normalizeCanvas(persistedDocument.canvas);
  const persistedAsset = persistedCanvas.assets.find((asset) => asset.generationJobId === job.id
    || (resultAssetId && asset.id === resultAssetId));
  const persistedNode = persistedCanvas.nodes.find((node) => node.id === target.nodeId);
  const persistedContent = whiteboardGenerationContentFromJob(job);
  if (!persistedAsset) throw new Error("生成结果文件已保存，但白板资产记录尚未落盘；正在自动同步");
  if (!canvasNodeDisplaysGenerationContent(persistedNode, persistedContent)) {
    throw new Error("生成结果已进入全部资产，但原生成卡片尚未显示该结果；正在自动同步到卡片");
  }
  const verifiedResultAssetId = String(persistedAsset.id || resultAssetId || "");
  if (resultAssetId && verifiedResultAssetId !== resultAssetId) {
    throw new Error("卡片回读结果与本次生成资产不一致；任务保持在回填状态");
  }
  return {
    verified: true,
    workspacePath: target.workspacePath,
    documentId: target.documentId,
    nodeId: persistedNode?.id || target.nodeId || "",
    generationJobId: job.id,
    resultAssetId: verifiedResultAssetId,
    stateStamp: String(loaded.stateStamp || ""),
    verifiedAt: new Date().toISOString(),
  };
};

const renderWhiteboardMultiSelection = (documentState) => {
  if (!documentState || documentState.documentKind !== "whiteboard" || ui.whiteboardSelectedDocumentId !== state.activeDocument) {
    elements.whiteboardMultiSelection.hidden = true;
    return;
  }
  const validIds = selectedWhiteboardNodeIds().filter((id) => whiteboardNodeById(id, documentState));
  if (validIds.length < 2) {
    elements.whiteboardMultiSelection.hidden = true;
    return;
  }
  const bounds = canvasSelectionBounds(documentState.canvas, validIds);
  if (!bounds) {
    elements.whiteboardMultiSelection.hidden = true;
    return;
  }
  const viewport = normalizeCanvas(documentState.canvas).viewport;
  elements.whiteboardMultiSelection.style.left = `${viewport.x + bounds.left * viewport.zoom}px`;
  elements.whiteboardMultiSelection.style.top = `${viewport.y + bounds.top * viewport.zoom}px`;
  elements.whiteboardMultiSelection.style.width = `${bounds.width * viewport.zoom}px`;
  elements.whiteboardMultiSelection.style.height = `${bounds.height * viewport.zoom}px`;
  elements.whiteboardMultiSelection.hidden = false;
};

const whiteboardCardRenderSignature = (value) => {
  const source = JSON.stringify(value);
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
};

const whiteboardStableNodeRenderSignatures = new WeakMap();

const whiteboardStableNodeRenderSignature = (node) => {
  if (!node || typeof node !== "object") return whiteboardCardRenderSignature(node);
  const cached = whiteboardStableNodeRenderSignatures.get(node);
  if (cached) return cached;
  const { x: _x, y: _y, width: _width, height: _height, ...renderNode } = node;
  const signature = whiteboardCardRenderSignature(renderNode);
  whiteboardStableNodeRenderSignatures.set(node, signature);
  return signature;
};

const syncWhiteboardMediaCardSection = (card, replacement, selector, beforeSelector) => {
  const current = card.querySelector(`:scope > ${selector}`);
  const next = replacement.querySelector(`:scope > ${selector}`);
  if (current && next) {
    current.replaceWith(next.cloneNode(true));
    return;
  }
  if (current) {
    current.remove();
    return;
  }
  if (!next) return;
  const anchor = beforeSelector ? card.querySelector(`:scope > ${beforeSelector}`) : null;
  card.insertBefore(next.cloneNode(true), anchor || null);
};

const patchStableWhiteboardMediaCard = (card, replacement, mediaIdentity) => {
  if (!card || !replacement || !mediaIdentity) return false;
  if (card.dataset.whiteboardMediaIdentity !== mediaIdentity
    || replacement.dataset.whiteboardMediaIdentity !== mediaIdentity
    || card.dataset.cardKind !== replacement.dataset.cardKind
    || !["image", "video"].includes(card.dataset.cardKind)) return false;

  const mediaSelector = card.dataset.cardKind === "video" ? "video.whiteboard-card-video" : "img.whiteboard-card-image";
  const currentMedia = card.querySelector(mediaSelector);
  const nextMedia = replacement.querySelector(mediaSelector);
  if (!currentMedia || !nextMedia || currentMedia.getAttribute("src") !== nextMedia.getAttribute("src")) return false;

  // Progress polling must never replace a live <video> or <img>. Replacing the
  // native element resets playback/decoding and visibly flashes the card. Keep
  // the media node itself and reconcile only the changing generation chrome.
  for (const attribute of ["alt", "aria-label", "title", "data-attachment-preview", "data-attachment-path", "data-attachment-download-name", "data-media-batch-directory"]) {
    if (nextMedia.hasAttribute(attribute)) currentMedia.setAttribute(attribute, nextMedia.getAttribute(attribute));
    else currentMedia.removeAttribute(attribute);
  }
  for (const className of ["low-detail", "editing", "candidate-pending", "focused", "selected", "generating"]) {
    card.classList.toggle(className, replacement.classList.contains(className));
  }
  for (const attribute of [
    "data-card-kind",
    "data-card-color",
    "data-card-origin",
    "data-card-has-content",
    "data-generated-content",
    "data-generation-job-id",
    "data-generation-status",
    "data-generation-channel",
    "data-generation-phase-key",
    "data-whiteboard-media-identity",
  ]) {
    if (replacement.hasAttribute(attribute)) card.setAttribute(attribute, replacement.getAttribute(attribute));
    else card.removeAttribute(attribute);
  }
  syncWhiteboardMediaCardSection(card, replacement, ".whiteboard-card-node-title", ".whiteboard-card-kind, .whiteboard-card-image, .whiteboard-card-media-shell");
  syncWhiteboardMediaCardSection(card, replacement, ".whiteboard-card-kind", ".whiteboard-card-image, .whiteboard-card-media-shell");
  syncWhiteboardMediaCardSection(card, replacement, ".media-generation-actions", ".whiteboard-node-handle");
  for (const selector of [".whiteboard-node-handle", ".whiteboard-resize-handle"]) {
    card.querySelectorAll(`:scope > ${selector}`).forEach((element) => element.remove());
    replacement.querySelectorAll(`:scope > ${selector}`).forEach((element) => card.append(element.cloneNode(true)));
  }
  return true;
};

const whiteboardGenerationElapsedDismissKey = (node, documentId = state.activeDocument) => {
  const generation = node?.generation;
  if (!documentId || !node?.id || !generation || Number(generation.elapsedMs) <= 0) return "";
  const generationIdentity = generation.jobId
    || generation.createdAt
    || `${generation.channel || ""}:${generation.elapsedMs}:${generation.prompt || ""}`;
  return `${workspaceIdentity()}::${documentId}:${node.id}:${generationIdentity}`;
};

const whiteboardGenerationCompletedElapsedMs = (node) => Math.max(
  Number(node?.generation?.elapsedMs) || 0,
  Number(whiteboardGenerationCompletionTimes.get(String(node?.generation?.jobId || ""))) || 0,
);

const dismissWhiteboardGenerationElapsed = (card) => {
  const metrics = card?.querySelector(".whiteboard-generation-metrics.complete");
  if (!metrics) return false;
  const node = whiteboardNodeById(card.dataset.canvasNode);
  const dismissKey = whiteboardGenerationElapsedDismissKey(node);
  if (dismissKey) {
    addToBoundedSet(ui.whiteboardDismissedGenerationElapsed, dismissKey, WHITEBOARD_DISMISSED_METRIC_LIMIT);
    persistWhiteboardDismissedGenerationElapsed(ui.whiteboardDismissedGenerationElapsed);
  }
  const status = metrics.closest(".whiteboard-card-kind");
  metrics.remove();
  if (status && !status.textContent.trim() && !status.querySelector(".whiteboard-generation-spinner")) status.remove();
  return true;
};

// Keep large boards responsive on integrated GPUs: DOM/media cards outside the
// visible area are not useful during an interaction and are materialized again
// as soon as the viewport approaches them.
const WHITEBOARD_VIRTUALIZATION_NODE_THRESHOLD = 80;
const WHITEBOARD_MEDIA_VIRTUALIZATION_THRESHOLD = 8;
const WHITEBOARD_VIRTUALIZATION_OVERSCAN_PX = 260;
const WHITEBOARD_PROGRESSIVE_RENDER_THRESHOLD = 48;
const WHITEBOARD_PROGRESSIVE_RENDER_BATCH = 10;
const WHITEBOARD_PROGRESSIVE_FRAME_BUDGET_MS = 7;
const WHITEBOARD_DEFERRED_IMAGE_BATCH = 2;

const cancelWhiteboardMediaHydration = () => {
  cancelUiBackgroundTask(ui.whiteboardMediaHydrationTask);
  ui.whiteboardMediaHydrationTask = null;
  ui.whiteboardMediaHydrationToken = (Number(ui.whiteboardMediaHydrationToken) || 0) + 1;
};

const scheduleWhiteboardMediaHydration = () => {
  cancelWhiteboardMediaHydration();
  const renderIdentity = elements.whiteboardSurface.dataset.renderIdentity || "";
  const queue = [...elements.whiteboardSurface.querySelectorAll("img[data-whiteboard-deferred-src]")];
  if (!queue.length) return;
  const token = ui.whiteboardMediaHydrationToken;
  const run = () => {
    ui.whiteboardMediaHydrationTask = null;
    if (token !== ui.whiteboardMediaHydrationToken
      || elements.whiteboardSurface.dataset.renderIdentity !== renderIdentity
      || !activeWhiteboardDocument()) return;
    let hydrated = 0;
    while (queue.length && hydrated < WHITEBOARD_DEFERRED_IMAGE_BATCH) {
      const image = queue.shift();
      const source = String(image?.dataset?.whiteboardDeferredSrc || "");
      if (!image?.isConnected || !source) continue;
      image.src = source;
      delete image.dataset.whiteboardDeferredSrc;
      hydrated += 1;
    }
    if (queue.length) {
      ui.whiteboardMediaHydrationTask = scheduleUiBackgroundTask(run, {
        delay: 48,
        timeout: 1_600,
        interactionGrace: 240,
      });
    }
  };
  ui.whiteboardMediaHydrationTask = scheduleUiBackgroundTask(run, {
    delay: 72,
    timeout: 1_600,
    interactionGrace: 240,
  });
};

const cancelWhiteboardProgressiveRender = ({ clearPresentation = false } = {}) => {
  if (ui.whiteboardProgressiveRenderFrame) cancelAnimationFrame(ui.whiteboardProgressiveRenderFrame);
  ui.whiteboardProgressiveRenderFrame = null;
  ui.whiteboardProgressiveRenderToken += 1;
  if (clearPresentation) {
    elements.whiteboardSurface.classList.remove("progressive-rendering");
    elements.whiteboardSurface.querySelectorAll(":scope > .whiteboard-card.progressive-ready")
      .forEach((card) => card.classList.remove("progressive-ready"));
  }
};

const whiteboardVirtualRenderWindow = (documentState) => {
  const nodes = documentState?.canvas?.nodes ?? [];
  const mediaNodeCount = nodes.reduce((count, node) => count + (["video", "audio"].includes(node?.kind) ? 1 : 0), 0);
  if (nodes.length <= WHITEBOARD_VIRTUALIZATION_NODE_THRESHOLD && mediaNodeCount < WHITEBOARD_MEDIA_VIRTUALIZATION_THRESHOLD) {
    return { enabled: false, nodes, nodeIds: new Set(nodes.map((node) => node.id)) };
  }
  elements.whiteboardEditor.hidden = false;
  const rect = elements.whiteboardEditor.getBoundingClientRect();
  const viewport = whiteboardViewport(documentState);
  if (rect.width < 1 || rect.height < 1) {
    const fallback = nodes.slice(0, WHITEBOARD_VIRTUALIZATION_NODE_THRESHOLD);
    return { enabled: true, nodes: fallback, nodeIds: new Set(fallback.map((node) => node.id)) };
  }
  const overscan = WHITEBOARD_VIRTUALIZATION_OVERSCAN_PX / viewport.zoom;
  const bounds = {
    left: -viewport.x / viewport.zoom - overscan,
    top: -viewport.y / viewport.zoom - overscan,
    right: (rect.width - viewport.x) / viewport.zoom + overscan,
    bottom: (rect.height - viewport.y) / viewport.zoom + overscan,
  };
  const preservedIds = new Set([
    ...selectedWhiteboardNodeIds(),
    ui.whiteboardEditingNodeId,
    ui.whiteboardFocusedNodeId,
    ui.whiteboardGeneratingNodeId,
    ui.whiteboardDrag?.nodeId,
    ...(ui.whiteboardDrag?.groupMembers ?? []).map((member) => member.id),
    ...whiteboardGenerationDialogs().map((dialog) => dialog.dataset.anchorNodeId),
  ].filter(Boolean));
  for (const card of elements.whiteboardSurface.querySelectorAll(":scope > [data-canvas-node]")) {
    const media = card.querySelector("video, audio");
    if (media && !media.paused && !media.ended) preservedIds.add(card.dataset.canvasNode);
  }
  const renderNodes = nodes.filter((node) => preservedIds.has(node.id) || !(
    node.x + node.width < bounds.left
    || node.x > bounds.right
    || node.y + node.height < bounds.top
    || node.y > bounds.bottom
  ));
  return { enabled: true, nodes: renderNodes, nodeIds: new Set(renderNodes.map((node) => node.id)), bounds };
};

const whiteboardActiveVideoKey = (nodeId, documentId = state.activeDocument) => `${workspaceIdentity()}::${documentId}::${nodeId}`;

const activateDormantWhiteboardVideo = (card) => {
  const shell = card?.querySelector?.(".whiteboard-card-video-poster[data-attachment-src]");
  const source = String(shell?.dataset?.attachmentSrc || "");
  if (!shell || !source) return null;
  const video = document.createElement("video");
  video.className = "whiteboard-card-video";
  video.src = source;
  video.controls = true;
  video.preload = "none";
  video.playsInline = true;
  video.setAttribute("aria-label", String(shell.dataset.attachmentDownloadName || "白板视频"));
  video.dataset.attachmentPreview = "video";
  for (const name of ["attachmentPath", "attachmentDownloadName", "mediaBatchDirectory", "mediaDirectoryKind"]) {
    if (shell.dataset[name]) video.dataset[name] = shell.dataset[name];
  }
  const poster = shell.querySelector("img")?.currentSrc
    || shell.querySelector("img")?.src
    || shell.querySelector("img")?.dataset?.whiteboardDeferredSrc
    || "";
  if (poster) video.poster = poster;
  video.title = "拖拽移动；双击预览视频";
  const dragSurface = document.createElement("span");
  dragSurface.className = "whiteboard-card-video-drag-surface";
  dragSurface.dataset.whiteboardVideoDragSurface = "";
  dragSurface.title = "拖拽移动；双击预览视频";
  dragSurface.setAttribute("aria-hidden", "true");
  const frameButton = shell.querySelector("[data-video-frame-trigger]");
  shell.classList.remove("dormant", "whiteboard-card-video-poster", "whiteboard-card-low-detail", "media", "video");
  shell.classList.add("whiteboard-card-media-shell");
  shell.removeAttribute("data-attachment-preview");
  shell.removeAttribute("data-attachment-src");
  shell.replaceChildren(video, dragSurface, ...(frameButton ? [frameButton] : []));
  card.classList.remove("low-detail");
  return video;
};

const releaseActiveWhiteboardVideo = (card) => {
  const shell = card?.querySelector?.(".whiteboard-card-media-shell");
  const video = shell?.querySelector?.(".whiteboard-card-video");
  if (!shell || !video) return false;
  const source = String(video.currentSrc || video.src || "");
  const poster = String(video.poster || "");
  const label = String(video.dataset.attachmentDownloadName || video.getAttribute("aria-label") || "白板视频");
  const frameButton = shell.querySelector("[data-video-frame-trigger]");
  clearWhiteboardVideoOverlayTimer(shell);
  if (!video.paused && !video.ended) video.pause();
  video.removeAttribute("src");
  video.load();
  shell.classList.remove("video-playing", "video-controls-visible");
  shell.classList.add("dormant", "whiteboard-card-video-poster");
  shell.dataset.attachmentPreview = "video";
  shell.dataset.attachmentSrc = source;
  shell.title = "点击播放；拖拽移动；双击预览视频";
  const preview = document.createElement(poster ? "img" : "span");
  if (poster) {
    preview.className = "whiteboard-card-overview-image";
    preview.src = poster;
    preview.alt = label;
    preview.decoding = "async";
    preview.draggable = false;
  } else {
    preview.className = "whiteboard-card-overview-placeholder";
    preview.innerHTML = icon("\uE714", "视频");
  }
  const play = document.createElement("span");
  play.className = "attachment-video-play";
  play.dataset.whiteboardVideoActivate = "";
  play.setAttribute("aria-hidden", "true");
  play.innerHTML = icon("\uE768", "播放视频");
  shell.replaceChildren(preview, play, ...(frameButton ? [frameButton] : []));
  return true;
};

const scheduleWhiteboardDormantVideoRefresh = () => {
  cancelUiBackgroundTask(ui.whiteboardDormantVideoTask);
  const identity = `${workspaceIdentity()}::${state.activeDocument}`;
  ui.whiteboardDormantVideoTask = scheduleUiBackgroundTask(() => {
    ui.whiteboardDormantVideoTask = null;
    if (`${workspaceIdentity()}::${state.activeDocument}` !== identity) return;
    const documentState = activeWhiteboardDocument();
    if (documentState) renderWhiteboard(documentState);
  }, { delay: 40, timeout: 800, interactionGrace: 120 });
};

const renderWhiteboard = (documentState) => {
  cancelWhiteboardMediaHydration();
  const arrangePreview = ui.whiteboardArrangePreview;
  const previewMatches = arrangePreview
    && arrangePreview.workspaceId === workspaceIdentity()
    && arrangePreview.documentId === state.activeDocument;
  if (arrangePreview && !previewMatches) {
    ui.whiteboardArrangePreview = null;
    elements.whiteboardArrangeDecision.hidden = true;
    elements.whiteboardEditor.classList.remove("is-arrange-preview");
  } else if (previewMatches) {
    documentState = {
      ...documentState,
      canvas: whiteboardCanvasWithPreviewLayout(documentState.canvas, arrangePreview.layoutCanvas),
    };
  }
  documentState.canvas = canonicalCanvas(documentState.canvas);
  const { x, y, zoom } = documentState.canvas.viewport;
  elements.whiteboardSurface.style.transform = `translate3d(${x}px, ${y}px, 0) scale(${zoom})`;
  elements.whiteboardZoomOut.disabled = zoom <= CANVAS_MIN_ZOOM;
  elements.whiteboardZoomIn.disabled = zoom >= CANVAS_MAX_ZOOM;
  elements.whiteboardZoomOut.title = `缩小白板（当前 ${Math.round(zoom * 100)}%）`;
  elements.whiteboardZoomIn.title = `放大白板（当前 ${Math.round(zoom * 100)}%）`;
  const nodeMap = new Map(documentState.canvas.nodes.map((node) => [node.id, node]));
  const virtualWindow = whiteboardVirtualRenderWindow(documentState);
  elements.whiteboardEditor.dataset.virtualized = String(virtualWindow.enabled);
  elements.whiteboardEditor.dataset.renderedNodeCount = String(virtualWindow.nodes.length);
  elements.whiteboardEditor.dataset.totalNodeCount = String(documentState.canvas.nodes.length);
  const uploadedMediaNodeIds = new Set(documentState.canvas.assets
    .filter((asset) => asset?.origin === "upload" && ["image", "video", "audio"].includes(asset?.kind) && asset?.sourceNodeId)
    .map((asset) => asset.sourceNodeId));
  const generationDraftCache = readWhiteboardGenerationDraftCache();
  const generationDraftByNode = new Map();
  for (const entry of Object.values(generationDraftCache.entries)) {
    if (entry.workspaceId !== workspaceIdentity() || entry.documentId !== state.activeDocument) continue;
    const current = generationDraftByNode.get(entry.nodeId);
    if (!current || entry.updatedAt > current.updatedAt) generationDraftByNode.set(entry.nodeId, entry);
  }
  const edgeMarkup = documentState.canvas.edges.map((edge, index) => {
    const fromNode = nodeMap.get(edge.fromNode);
    const toNode = nodeMap.get(edge.toNode);
    if (!fromNode || !toNode) return "";
    if (virtualWindow.enabled && !virtualWindow.nodeIds.has(edge.fromNode) && !virtualWindow.nodeIds.has(edge.toNode)) return "";
    const path = whiteboardEdgePath(whiteboardNodeSidePoint(fromNode, edge.fromSide), whiteboardNodeSidePoint(toNode, edge.toSide));
    const selected = ui.whiteboardSelectedEdgeDocumentId === state.activeDocument
      && (ui.whiteboardSelectedEdgeIds?.has(edge.id) || ui.whiteboardSelectedEdgeId === edge.id);
    return `<g class="whiteboard-edge-group ${selected ? "selected" : ""}" data-canvas-edge="${escapeHtml(edge.id)}"><path class="whiteboard-edge-hit" d="${path}"></path><path class="whiteboard-edge" d="${path}"></path><path class="whiteboard-edge-flow" d="${path}" pathLength="100" style="--whiteboard-flow-delay:-${(index % 8) * 0.17}s"></path></g>`;
  }).join("");
  const draftStart = ui.whiteboardEdgeDraft?.fromPoint
    ?? (ui.whiteboardEdgeDraft?.fromNode && nodeMap.has(ui.whiteboardEdgeDraft.fromNode) ? whiteboardNodeSidePoint(nodeMap.get(ui.whiteboardEdgeDraft.fromNode), "right") : null);
  const draftMarkup = draftStart
    ? `<path class="whiteboard-edge draft" d="${whiteboardEdgePath(draftStart, { x: ui.whiteboardEdgeDraft.x, y: ui.whiteboardEdgeDraft.y })}"></path>`
    : "";
  const renderIdentity = `${workspaceIdentity()}::${state.activeDocument}`;
  const previousRenderIdentity = elements.whiteboardSurface.dataset.renderIdentity || "";
  const renderIdentityChanged = previousRenderIdentity !== renderIdentity;
  if (renderIdentityChanged) ui.whiteboardActiveVideoKeys.clear();
  const progressiveAlreadyRunning = elements.whiteboardSurface.classList.contains("progressive-rendering");
  cancelWhiteboardProgressiveRender();
  const useProgressiveRender = virtualWindow.nodes.length > WHITEBOARD_PROGRESSIVE_RENDER_THRESHOLD
    && (renderIdentityChanged || progressiveAlreadyRunning);
  elements.whiteboardSurface.dataset.renderIdentity = renderIdentity;
  const buildWhiteboardCardRecord = (node) => {
    const cardOrigin = uploadedMediaNodeIds.has(node.id) ? "upload" : "";
    const editing = ui.whiteboardEditingNodeId === node.id;
    const candidate = whiteboardCandidateFor(node.id);
    const durableMediaCandidate = ["image", "video", "audio"].includes(candidate?.channel);
    const candidateAutomaticRecovery = candidate?.automaticRecoveryInProgress === true;
    const candidateConnecting = Boolean(candidate && whiteboardGenerationConnectionPhase(candidate));
    const candidateInterrupted = Boolean(candidate && (durableMediaCandidate
      ? !candidateConnecting && !MEDIA_JOB_ACTIVE_STATUSES.has(candidate.status) && candidate.status !== "complete" && !candidateAutomaticRecovery
        : ["retry_required", "failed"].includes(candidate.status)));
    const candidateApplyFailed = candidate?.cardApplyFailed === true;
    const candidateActive = Boolean(candidate && !candidateApplyFailed
      && (durableMediaCandidate ? candidateConnecting || MEDIA_JOB_ACTIVE_STATUSES.has(candidate.status) || candidateAutomaticRecovery : !candidateInterrupted));
    const candidateApplying = Boolean(candidate && ["saving", "verifying"].includes(candidate.cardApplyStage));
    const generating = Boolean(candidateActive || candidateApplying || ui.whiteboardGeneratingNodeId === node.id || ui.whiteboardSmartSplitNodeIds.has(node.id));
    const visibleNode = ["image", "video", "audio"].includes(candidate?.kind) && candidate.attachment?.relativePath
      ? {
          ...node,
          type: "file",
          kind: candidate.kind,
          file: candidate.attachment.relativePath,
          name: candidate.attachment.name,
          mimeType: candidate.attachment.mimeType,
          aspectRatio: candidate.aspectRatio,
          thumbnailRelativePath: candidate.attachment.thumbnailRelativePath || "",
          thumbnailMimeType: candidate.attachment.thumbnailMimeType || "",
        }
      : node;
    const activeVideoKey = visibleNode.kind === "video" ? whiteboardActiveVideoKey(node.id) : "";
    const activeVideo = Boolean(activeVideoKey && ui.whiteboardActiveVideoKeys.has(activeVideoKey));
    // At overview zoom, full textareas/web previews are unreadable but still
    // participate in every global style/layout pass. Use a lightweight card
    // body until the user zooms in or starts editing; data, generation routing
    // and hit targets continue to use the canonical node object.
    const lowDetail = zoom <= 0.36
      && ["text", "generated", "web", "skill", "reference", "image", "video", "audio"].includes(visibleNode.kind)
      && !editing
      && !candidate
      && !generating
      && !activeVideo;
    const candidateHasOutput = Boolean(String(candidate?.text ?? "").trim() || candidate?.attachment?.relativePath);
    const generatedDisplayName = candidateHasOutput
      ? generatedWhiteboardNodeNames(documentState.canvas, ["image", "video", "audio"].includes(candidate.kind) ? candidate.kind : "text", 1, node.name)[0]
      : node.generation ? node.name : "";
    const visibleMediaDownloadName = ["image", "video", "audio"].includes(visibleNode.kind) ? mediaDownloadFileName({
      kind: visibleNode.kind,
      nodeName: generatedDisplayName,
      prompt: candidate?.prompt || visibleNode.generation?.prompt,
      name: visibleNode.name,
      relativePath: visibleNode.file,
      mimeType: visibleNode.mimeType,
    }) : "";
    const visibleText = candidate && !["image", "video", "audio"].includes(candidate.kind) ? candidate.text : node.text;
    const hasVisibleTextContent = Boolean(String(visibleText ?? "").trim());
    const hasGeneratedContent = Boolean(
      (visibleNode.kind === "generated" && String(visibleText ?? "").trim())
      || (visibleNode.generation && (
        String(visibleText ?? "").trim()
        || (["image", "video", "audio"].includes(visibleNode.kind) && visibleNode.file)
      ))
      || (candidate?.status === "complete" && (
        String(candidate.text ?? "").trim()
        || candidate.attachment?.relativePath
      )),
    );
    const hasCardContent = Boolean(
      hasVisibleTextContent
      || hasGeneratedContent
      || visibleNode.file
      || (visibleNode.kind === "web" && (visibleNode.url || visibleNode.webSnapshot)),
    );
    const pendingGenerationType = !hasGeneratedContent && !hasVisibleTextContent && !candidate && !whiteboardAutoOpenIsDisabled(node.id)
      ? generationDraftByNode.get(node.id)?.channel || ""
      : "";
    const pendingGenerationTypeLabels = { text: "文字生成", image: "图片生成", video: "视频生成", audio: "音频生成" };
    const pendingGenerationTypeIcons = { text: "\uE8D2", image: "\uEB9F", video: "\uE714", audio: "\uE8D6" };
    const generationTypeIndicator = pendingGenerationType
      ? `<span class="whiteboard-card-generation-type" data-generation-card-type="${escapeHtml(pendingGenerationType)}" title="${escapeHtml(pendingGenerationTypeLabels[pendingGenerationType] || pendingGenerationType)}" aria-label="${escapeHtml(pendingGenerationTypeLabels[pendingGenerationType] || pendingGenerationType)}">${icon(pendingGenerationTypeIcons[pendingGenerationType] || "\uE8D2")}</span>`
      : "";
    const generatedNodeTitle = !lowDetail && hasGeneratedContent && generatedDisplayName
      ? `<div class="whiteboard-card-node-title" title="${escapeHtml(generatedDisplayName)}">${escapeHtml(uiText(generatedDisplayName))}</div>`
      : "";
    const visibleMediaUrl = ["image", "video"].includes(visibleNode.kind)
      ? whiteboardAttachmentUrl({ ...visibleNode, generation: { ...(visibleNode.generation || {}), prompt: candidate?.prompt || visibleNode.generation?.prompt } })
      : "";
    const visibleVideoUrl = visibleNode.kind === "video" && visibleMediaUrl ? `${visibleMediaUrl}#t=0.001` : visibleMediaUrl;
    const visiblePosterUrl = visibleNode.kind === "video" && visibleNode.thumbnailRelativePath
      ? workspaceAttachmentUrl(visibleNode.thumbnailRelativePath, state.activeDocument)
      : "";
    const visiblePosterAttribute = visiblePosterUrl ? ` poster="${escapeHtml(visiblePosterUrl)}"` : "";
    const visibleMediaIdentity = ["image", "video"].includes(visibleNode.kind) && visibleMediaUrl
      ? whiteboardCardRenderSignature({ kind: visibleNode.kind, source: visibleNode.kind === "video" ? visibleVideoUrl : visibleMediaUrl, poster: visiblePosterUrl })
      : "";
    const generationChannel = ["image", "video", "audio"].includes(candidate?.channel) ? candidate.channel : "text";
    const generationTaskLabel = generating
      ? uiText({ text: "文本", image: "图片", video: "视频", audio: "音频" }[generationChannel])
      : "";
    const queuePosition = Number.isFinite(Number(candidate?.providerQueuePosition)) && candidate?.providerQueuePosition !== null
      ? Math.max(0, Number(candidate.providerQueuePosition))
      : null;
    const queueLength = Number.isFinite(Number(candidate?.providerQueueLength)) && candidate?.providerQueueLength !== null
      ? Math.max(0, Number(candidate.providerQueueLength))
      : null;
    const providerQueueLabel = whiteboardProviderQueueVisible(candidate)
      ? `${uiText("厂商排队")}${queueLength !== null ? ` · ${uiText("共")} ${queueLength.toLocaleString()} ${uiText("人")}` : ""}${queuePosition !== null ? ` · ${uiText("当前第")} ${Math.max(1, queuePosition).toLocaleString()} ${uiText("位")}` : ""}`
      : "";
    const generationStatusLabel = candidateApplyFailed
      ? uiText("结果已生成，卡片回填失败")
      : candidate?.cardApplyStage === "saving"
      ? uiText("生成完成，正在保存")
      : candidate?.cardApplyStage === "verifying"
        ? uiText("结果已保存，正在回读卡片")
      : candidateConnecting
      ? durableMediaCandidate ? mediaGenerationPhaseText(candidate) : uiText("正在连接生成服务")
      : candidate?.connectionInterrupted
      ? uiText("本地连接暂断，后台任务仍在运行")
      : candidateInterrupted
        ? durableMediaCandidate
          ? `${mediaGenerationPhaseText(candidate)}${candidate.error ? `：${String(candidate.error).slice(0, 120)}` : ""}`
          : uiText("连接中断，需重新生成")
      : generating ? durableMediaCandidate ? providerQueueLabel || mediaGenerationPhaseText(candidate) : uiText("正在生成") : "";
    const generationMeasurementActive = Boolean(candidate && whiteboardGenerationMeasurementActive(candidate));
    const generationMeasurementStarted = Boolean(candidate && Number(candidate.startedAt) > 0);
    const visibleGenerationProgress = Boolean(candidate && whiteboardGenerationProgressActive(candidate) && whiteboardProgressTarget(candidate) !== null);
    const generationElapsedDismissed = ui.whiteboardDismissedGenerationElapsed.has(whiteboardGenerationElapsedDismissKey(node));
    const generationMetrics = candidate && (generationMeasurementActive || (candidateInterrupted && generationMeasurementStarted))
      ? candidateInterrupted
        ? `<span class="whiteboard-generation-metrics interrupted"><time>${escapeHtml(formatWhiteboardGenerationDuration(candidate.elapsedMs))}</time></span>`
        : `<span class="whiteboard-generation-metrics">${visibleGenerationProgress ? `<b>${whiteboardDisplayedProgress(candidate)}%</b>` : ""}<time>${escapeHtml(formatWhiteboardGenerationDuration(candidate.elapsedMs))}</time></span>`
      : !generating && !generationElapsedDismissed && whiteboardGenerationCompletedElapsedMs(node) > 0
        ? `<span class="whiteboard-generation-metrics complete"><span>${escapeHtml(uiText("已完成"))} · ${escapeHtml(uiText("总用时"))}</span><time>${escapeHtml(formatWhiteboardGenerationDuration(whiteboardGenerationCompletedElapsedMs(node)))}</time></span>`
        : "";
    const kindMarkup = generationTaskLabel || generationStatusLabel || generationMetrics
      ? `<span class="whiteboard-card-kind ${generating || candidateInterrupted ? "whiteboard-generation-status" : ""} ${candidateInterrupted ? "interrupted" : ""}"${candidate?.error ? ` title="${escapeHtml(candidate.error)}"` : ""}>${generationTaskLabel ? `<span class="whiteboard-generation-task-type" data-generation-task-type="${escapeHtml(generationChannel)}">${escapeHtml(generationTaskLabel)}</span>` : ""}${generationStatusLabel ? `<span class="whiteboard-generation-phase-label">${escapeHtml(generationStatusLabel)}</span>` : ""}${generationMetrics}${generating ? '<span class="whiteboard-generation-spinner" aria-hidden="true"></span>' : ""}</span>`
      : "";
    const textEditor = lowDetail
      ? ""
      : `<textarea data-canvas-text="${escapeHtml(node.id)}" aria-label="${escapeHtml(uiText("白板卡片内容"))}" ${editing && !candidate ? "" : 'readonly tabindex="-1"'}>${escapeHtml(visibleText)}</textarea>`;
    const whiteboardMediaDirectory = String(visibleNode.whiteboardMediaDirectory || "");
    const managedMediaDirectory = whiteboardMediaDirectory || String(visibleNode.mediaBatchDirectory || "");
    const mediaBatchAttribute = managedMediaDirectory ? ` data-media-batch-directory="${escapeHtml(managedMediaDirectory)}"${whiteboardMediaDirectory ? ' data-media-directory-kind="whiteboard"' : ""}` : "";
    const plainCardName = String(visibleNode.name || "").trim();
    const emptyPlainCard = visibleNode.kind === "text"
      && (!plainCardName || ["文字卡片", "普通卡片"].includes(plainCardName))
      && !String(visibleText || "").trim()
      && !visibleNode.generation;
    const overviewLabel = emptyPlainCard
      ? ""
      : generatedDisplayName || visibleNode.name || whiteboardNodeKindLabel(visibleNode) || "";
    const lowDetailContent = visibleNode.kind === "image"
      ? `<div class="whiteboard-card-low-detail media image"><img class="whiteboard-card-overview-image" data-whiteboard-deferred-src="${escapeHtml(visibleMediaUrl)}" alt="${escapeHtml(visibleNode.name || "白板图片")}" data-attachment-preview="image" data-attachment-src="${escapeHtml(visibleMediaUrl)}" data-attachment-path="${escapeHtml(visibleNode.file || "")}" data-attachment-download-name="${escapeHtml(visibleMediaDownloadName)}"${mediaBatchAttribute} title="${escapeHtml(`拖拽移动；双击预览 ${visibleNode.name || "白板图片"}`)}" decoding="async" fetchpriority="low" draggable="false" /></div>`
      : visibleNode.kind === "video"
        ? `<div class="whiteboard-card-low-detail media video whiteboard-card-video-poster" data-attachment-preview="video" data-attachment-src="${escapeHtml(visibleVideoUrl)}" data-attachment-path="${escapeHtml(visibleNode.file || "")}" data-attachment-download-name="${escapeHtml(visibleMediaDownloadName)}"${mediaBatchAttribute} title="点击播放；拖拽移动；双击预览视频">${visiblePosterUrl ? `<img class="whiteboard-card-overview-image" data-whiteboard-deferred-src="${escapeHtml(visiblePosterUrl)}" alt="${escapeHtml(visibleNode.name || "白板视频")}" decoding="async" fetchpriority="low" draggable="false" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" data-whiteboard-video-activate aria-hidden="true">${icon("\uE768", "播放视频")}</span></div>`
        : visibleNode.kind === "audio"
          ? `<div class="whiteboard-card-low-detail media audio"><span class="whiteboard-card-overview-placeholder">${icon("\uE8D6", "音频")}</span></div>`
          : `<div class="whiteboard-card-low-detail" aria-hidden="true">${overviewLabel ? `<strong>${escapeHtml(overviewLabel)}</strong>` : ""}</div>`;
    const content = lowDetail
      ? lowDetailContent
      : visibleNode.kind === "image"
      ? `<img class="whiteboard-card-image" src="${escapeHtml(visibleMediaUrl)}" alt="${escapeHtml(visibleNode.name || "白板图片")}" data-attachment-preview="image" data-attachment-path="${escapeHtml(visibleNode.file || "")}" data-attachment-download-name="${escapeHtml(visibleMediaDownloadName)}"${mediaBatchAttribute} title="${escapeHtml(`拖拽移动；双击预览 ${visibleNode.name || "白板图片"}`)}" loading="lazy" decoding="async" draggable="false" />`
      : visibleNode.kind === "video"
        ? activeVideo
          ? `<div class="whiteboard-card-media-shell"><video class="whiteboard-card-video" src="${escapeHtml(visibleVideoUrl)}"${visiblePosterAttribute} controls preload="none" aria-label="${escapeHtml(visibleMediaDownloadName || visibleNode.name || "白板视频")}" data-attachment-preview="video" data-attachment-path="${escapeHtml(visibleNode.file || "")}" data-attachment-download-name="${escapeHtml(visibleMediaDownloadName)}"${mediaBatchAttribute} title="拖拽移动；双击预览视频"></video><span class="whiteboard-card-video-drag-surface" data-whiteboard-video-drag-surface title="拖拽移动；双击预览视频" aria-hidden="true"></span><button class="video-frame-trigger whiteboard-video-frame-trigger" type="button" data-video-frame-trigger data-frame-destination="whiteboard" data-frame-source-node="${escapeHtml(node.id)}" data-attachment-path="${escapeHtml(visibleNode.file || "")}" title="提取关键帧" aria-label="提取关键帧">${icon("\uE722", "提取关键帧")}</button></div>`
          : `<div class="whiteboard-card-media-shell dormant whiteboard-card-video-poster" data-attachment-preview="video" data-attachment-src="${escapeHtml(visibleVideoUrl)}" data-attachment-path="${escapeHtml(visibleNode.file || "")}" data-attachment-download-name="${escapeHtml(visibleMediaDownloadName)}"${mediaBatchAttribute} title="点击播放；拖拽移动；双击预览视频">${visiblePosterUrl ? `<img class="whiteboard-card-overview-image" data-whiteboard-deferred-src="${escapeHtml(visiblePosterUrl)}" alt="${escapeHtml(visibleNode.name || "白板视频")}" decoding="async" fetchpriority="low" draggable="false" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" data-whiteboard-video-activate aria-hidden="true">${icon("\uE768", "播放视频")}</span><button class="video-frame-trigger whiteboard-video-frame-trigger" type="button" data-video-frame-trigger data-frame-destination="whiteboard" data-frame-source-node="${escapeHtml(node.id)}" data-attachment-path="${escapeHtml(visibleNode.file || "")}" title="提取首帧" aria-label="提取首帧">${icon("\uE722", "提取首帧")}</button></div>`
        : visibleNode.kind === "audio"
          ? `<div class="whiteboard-card-audio-shell"><strong title="${escapeHtml(visibleNode.name || "白板音频")}">${escapeHtml(visibleNode.name || "白板音频")}</strong><audio class="whiteboard-card-audio" src="${escapeHtml(whiteboardAttachmentUrl(visibleNode))}" controls preload="none" aria-label="${escapeHtml(visibleNode.name || "白板音频")}"></audio></div>`
      : visibleNode.kind === "web" && !editing
        ? `<div class="whiteboard-web-card" title="已读取网页正文；拖拽移动，双击或右键可修改链接"><span class="whiteboard-web-icon">${icon("\uE774")}</span><strong>${escapeHtml(whiteboardWebTitle(visibleNode))}</strong><small>${escapeHtml(visibleNode.webSnapshot ? `${visibleNode.webSnapshot.pages?.length || 1} 页 · ${visibleNode.webSnapshot.contentCharacters || visibleNode.webSnapshot.text?.length || 0} 字` : visibleNode.url)}</small><a class="whiteboard-web-open" href="${escapeHtml(visibleNode.url)}" target="_blank" rel="noopener noreferrer" title="打开网页" aria-label="打开 ${escapeHtml(whiteboardWebTitle(visibleNode))}">${icon("\uE8A7")}</a></div>`
        : textEditor;
    const selected = ui.whiteboardSelectedDocumentId === state.activeDocument && ui.whiteboardSelectedNodeIds.has(node.id);
    const usesFourCornerResize = ["image", "video", "audio"].includes(visibleNode.kind) || (visibleNode.type === "text" && visibleNode.kind !== "web");
    const resizeHandles = lowDetail
      ? ""
      : usesFourCornerResize
      ? ["nw", "ne", "sw", "se"].map((corner) => `<span class="whiteboard-resize-handle ${["image", "video", "audio"].includes(visibleNode.kind) ? "media-corner" : "text-corner"} ${corner}" data-canvas-resize="${corner}" title="拖拽调整卡片大小" aria-label="从${corner}角调整卡片大小"></span>`).join("")
      : '<span class="whiteboard-resize-handle se" data-canvas-resize="se" title="拖拽调整卡片大小" aria-label="拖拽调整卡片大小"></span>';
    const imageEditButton = !lowDetail && visibleNode.kind === "image" && visibleNode.file && !candidate && !state.readOnly
      ? `<button class="whiteboard-image-edit-button" type="button" data-edit-whiteboard-image="${escapeHtml(node.id)}" title="编辑图片" aria-label="编辑图片">${icon("\uE70F", "编辑图片")}</button>`
      : "";
    const compositeManifest = node.generation?.compositeLongVideo;
    const compositeProcessButton = !lowDetail && compositeManifest
      ? `<button class="whiteboard-long-video-process-trigger" type="button" data-composite-long-video-process="${escapeHtml(node.id)}" title="查看每个分段的提示词、参考、状态和积分"><span>${escapeHtml(compositeManifest.status === "complete" ? "生成过程" : `${Number(compositeManifest.completedSegments) || 0}/${compositeManifest.segments?.length || 0}`)}</span>${icon("\uE9D9", "生成过程")}</button>`
      : "";
    const markup = `<article class="whiteboard-card ${lowDetail ? "low-detail" : ""} ${editing ? "editing" : ""} ${candidate ? "candidate-pending" : ""} ${ui.whiteboardFocusedNodeId === node.id ? "focused" : ""} ${selected ? "selected" : ""} ${generating ? "generating" : ""}" data-canvas-node="${escapeHtml(node.id)}" data-card-kind="${escapeHtml(visibleNode.kind)}" data-card-color="${escapeHtml(node.color)}" data-card-origin="${escapeHtml(cardOrigin)}" data-card-has-text="${hasVisibleTextContent ? "true" : "false"}" data-card-has-content="${hasCardContent ? "true" : "false"}"${visibleMediaIdentity ? ` data-whiteboard-media-identity="${escapeHtml(visibleMediaIdentity)}"` : ""}${hasGeneratedContent ? ' data-generated-content="true"' : ""}${candidate ? ` data-generation-job-id="${escapeHtml(candidate.jobId || "")}" data-generation-status="${escapeHtml(candidate.status || "")}" data-generation-channel="${escapeHtml(candidate.channel || "")}" data-generation-phase-key="${escapeHtml(whiteboardCandidatePhaseKey(candidate))}"` : ""} style="left:${node.x}px;top:${node.y}px;width:${node.width}px;height:${node.height}px">
      ${generatedNodeTitle}
      ${kindMarkup}
      ${generationTypeIndicator}
      ${compositeProcessButton}
      ${content}
      ${imageEditButton}
      ${candidateApplyFailed ? `<div class="media-generation-actions compact"><button class="media-job-resume" type="button" data-whiteboard-candidate-action data-media-job-action="reapply" data-media-job-id="${escapeHtml(candidate.jobId || "")}" title="${escapeHtml(uiText("使用已生成结果重新回填卡片，不会重新生成"))}">${icon("\uE8B7", uiText("重新回填"))}<span>${escapeHtml(uiText("重新回填"))}</span></button></div>` : candidate ? mediaGenerationActionMarkup({ jobId: candidate.jobId, status: candidate.status, availableActions: candidate.availableActions, desiredAction: candidate.desiredAction, providerErrorCode: candidate.providerErrorCode, error: candidate.error, providerTaskId: candidate.providerTaskId, submissionState: candidate.submissionState }, { compact: true }) : ""}
      ${lowDetail ? "" : `<button class="whiteboard-node-handle input" type="button" data-canvas-handle="input" title="${escapeHtml(uiText("输入节点：接收直接上游信息"))}" aria-label="${escapeHtml(uiText("输入节点：接收直接上游信息"))}"></button>
      <button class="whiteboard-node-handle output" type="button" data-canvas-handle="output" title="${escapeHtml(uiText("输出节点：连接下游卡片"))}" aria-label="${escapeHtml(uiText("输出节点：连接下游卡片"))}"></button>`}
      ${resizeHandles}
    </article>`;
    return {
      id: node.id,
      node,
      selected,
      focused: ui.whiteboardFocusedNodeId === node.id,
      mediaIdentity: visibleMediaIdentity,
      signature: whiteboardCardRenderSignature({ stableNode: whiteboardStableNodeRenderSignature(node), candidate, editing, generating, lowDetail, activeVideo, generationElapsedDismissed, pendingGenerationType, visibleText: lowDetail ? "" : visibleText, visibleKind: visibleNode.kind, visibleFile: visibleNode.file || "", cardOrigin }),
      markup,
    };
  };
  const cardRecords = useProgressiveRender ? [] : virtualWindow.nodes.map(buildWhiteboardCardRecord);
  const edgeLayerMarkup = `<defs><marker id="whiteboardArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"></path></marker></defs>${edgeMarkup}${draftMarkup}`;
  const edgeLayerRenderKey = whiteboardCardRenderSignature({ documentId: state.activeDocument, edgeMarkup, draftMarkup });
  let edgeLayer = elements.whiteboardSurface.querySelector(":scope > .whiteboard-edge-layer");
  if (!edgeLayer) {
    elements.whiteboardSurface.insertAdjacentHTML("afterbegin", `<svg class="whiteboard-edge-layer" aria-hidden="true">${edgeLayerMarkup}</svg>`);
    edgeLayer = elements.whiteboardSurface.querySelector(":scope > .whiteboard-edge-layer");
    edgeLayer.dataset.whiteboardRenderKey = edgeLayerRenderKey;
  } else if (edgeLayer.dataset.whiteboardRenderKey !== edgeLayerRenderKey) {
    edgeLayer.innerHTML = edgeLayerMarkup;
    edgeLayer.dataset.whiteboardRenderKey = edgeLayerRenderKey;
  }
  const existingCards = new Map([...elements.whiteboardSurface.querySelectorAll(":scope > [data-canvas-node]")].map((card) => [card.dataset.canvasNode, card]));
  if (useProgressiveRender) {
    elements.whiteboardSurface.classList.add("progressive-rendering");
    existingCards.forEach((card) => card.classList.remove("progressive-ready"));
  } else {
    elements.whiteboardSurface.classList.remove("progressive-rendering");
    existingCards.forEach((card) => card.classList.remove("progressive-ready"));
  }
  const activeDrag = ui.whiteboardDrag?.documentId === state.activeDocument && ["card", "resize"].includes(ui.whiteboardDrag?.mode)
    ? ui.whiteboardDrag
    : null;
  // A background render can replace the SVG edge layer while a card is still
  // being dragged. Rebind and restore the current geometry in this same render
  // so the visible connector never falls back to the card's saved position.
  if (activeDrag) updateWhiteboardConnectedEdgePreview(activeDrag);
  const activelyPreviewedNodeIds = new Set(activeDrag ? [activeDrag.nodeId, ...(activeDrag.groupMembers ?? []).map((member) => member.id)] : []);
  let cursor = edgeLayer?.nextElementSibling || null;
  const applyCardRecord = (record) => {
    let card = existingCards.get(record.id);
    const preserveLivePreview = Boolean(card && activelyPreviewedNodeIds.has(record.id));
    const renderKeyChanged = Boolean(card && (renderIdentityChanged || card.dataset.whiteboardRenderKey !== record.signature));
    if (!card || (renderKeyChanged && !preserveLivePreview)) {
      const replacingCursor = card === cursor;
      const template = document.createElement("template");
      template.innerHTML = record.markup.trim();
      const replacement = template.content.firstElementChild;
      replacement.dataset.whiteboardRenderKey = record.signature;
      const patchedStableMedia = Boolean(!renderIdentityChanged && card && patchStableWhiteboardMediaCard(card, replacement, record.mediaIdentity));
      if (patchedStableMedia) {
        card.dataset.whiteboardRenderKey = record.signature;
      } else {
        if (card) card.replaceWith(replacement);
        else elements.whiteboardSurface.insertBefore(replacement, cursor);
        card = replacement;
        if (replacingCursor) cursor = replacement;
      }
    }
    if (renderKeyChanged && preserveLivePreview && activeDrag) activeDrag.deferredRender = true;
    if (!preserveLivePreview) {
      card.style.left = `${record.node.x}px`;
      card.style.top = `${record.node.y}px`;
      card.style.width = `${record.node.width}px`;
      card.style.height = `${record.node.height}px`;
    }
    card.classList.toggle("selected", record.selected);
    card.classList.toggle("focused", record.focused);
    if (useProgressiveRender) card.classList.add("progressive-ready");
    if (card !== cursor) elements.whiteboardSurface.insertBefore(card, cursor?.isConnected ? cursor : null);
    cursor = card.nextElementSibling;
    existingCards.delete(record.id);
  };
  if (useProgressiveRender) {
    const progressiveToken = ui.whiteboardProgressiveRenderToken;
    let recordIndex = 0;
    let staleCards = null;
    let staleIndex = 0;
    const renderProgressiveChunk = () => {
      ui.whiteboardProgressiveRenderFrame = null;
      if (progressiveToken !== ui.whiteboardProgressiveRenderToken
        || workspaceIdentity() + `::${state.activeDocument}` !== renderIdentity) return;
      const startedAt = performance.now();
      let processed = 0;
      while (recordIndex < virtualWindow.nodes.length
        && processed < WHITEBOARD_PROGRESSIVE_RENDER_BATCH
        && performance.now() - startedAt < WHITEBOARD_PROGRESSIVE_FRAME_BUDGET_MS) {
        applyCardRecord(buildWhiteboardCardRecord(virtualWindow.nodes[recordIndex++]));
        processed += 1;
      }
      if (recordIndex >= virtualWindow.nodes.length) {
        staleCards ??= [...existingCards.values()];
        while (staleIndex < staleCards.length
          && processed < WHITEBOARD_PROGRESSIVE_RENDER_BATCH
          && performance.now() - startedAt < WHITEBOARD_PROGRESSIVE_FRAME_BUDGET_MS) {
          staleCards[staleIndex++]?.remove();
          processed += 1;
        }
      }
      if (recordIndex < virtualWindow.nodes.length || staleIndex < (staleCards?.length ?? 0)) {
        ui.whiteboardProgressiveRenderFrame = requestAnimationFrame(renderProgressiveChunk);
        return;
      }
      elements.whiteboardSurface.classList.remove("progressive-rendering");
      elements.whiteboardSurface.querySelectorAll(":scope > .whiteboard-card.progressive-ready")
        .forEach((card) => card.classList.remove("progressive-ready"));
      scheduleWhiteboardMediaHydration();
    };
    renderProgressiveChunk();
  } else {
    cardRecords.forEach(applyCardRecord);
    existingCards.forEach((card) => card.remove());
  }
  renderWhiteboardMultiSelection(documentState);
  const snapEnabled = documentState.canvas.settings.snapToGrid;
  elements.whiteboardSnapToggle.setAttribute("aria-pressed", String(snapEnabled));
  elements.whiteboardSnapToggle.title = snapEnabled ? "关闭自动吸附" : "开启自动吸附";
  elements.whiteboardSnapToggle.setAttribute("aria-label", elements.whiteboardSnapToggle.title);
  elements.whiteboardEditor.hidden = false;
  elements.wordCount.textContent = `${documentState.canvas.nodes.length} 个节点`;
  syncWhiteboardHistoryControls();
  if (ui.panel === "references" && ui.referenceTarget === "whiteboard") {
    scheduleWhiteboardReferencePanelPosition();
  }
  if (elements.whiteboardGenerateDialog.open) {
    renderWhiteboardGenerationReferences(elements.whiteboardTextReferences, elements.whiteboardGenerateForm.dataset.nodeId);
  }
  if (elements.whiteboardImageDialog.open) {
    renderWhiteboardGenerationReferences(elements.whiteboardImageReferences, elements.whiteboardImageForm.dataset.nodeId);
  }
  if (elements.whiteboardVideoDialog.open) {
    renderWhiteboardGenerationReferences(elements.whiteboardVideoReferences, elements.whiteboardVideoForm.dataset.nodeId);
  }
  if (elements.whiteboardAudioDialog.open) {
    renderWhiteboardGenerationReferences(elements.whiteboardAudioReferences, elements.whiteboardAudioForm.dataset.nodeId);
  }
  renderWhiteboardGenerationCollapsedSessions();
  scheduleWhiteboardGenerationDialogPosition();
  if (!useProgressiveRender) scheduleWhiteboardMediaHydration();
};

const currentDocumentPreviewKey = () => `${state.settings?.workspacePath || state.projectName || "未命名"}::${state.activeDocument || ""}`;

const documentPreviewActive = () => ui.documentPreviewKey === currentDocumentPreviewKey();

const renderDocumentModeButton = ({ available, previewMode }) => {
  elements.documentModeButton.hidden = !available;
  if (!available) return;
  const label = previewMode ? "进入编辑模式" : "进入预览模式";
  elements.documentModeButton.innerHTML = icon(previewMode ? "\uE70F" : "\uE736", label);
  elements.documentModeButton.title = label;
  elements.documentModeButton.setAttribute("aria-label", label);
  elements.documentModeButton.setAttribute("aria-pressed", String(previewMode));
};

const AUTHOR_COCKPIT_READONLY_DOCUMENT_IDS = new Set([
  "report-compile",
  "report-novel",
  "report-script",
  "report-adaptation",
  "index-update-log",
]);

const belongsToAuthorCockpitReportCollection = ({ documentId = state.activeDocument, documentState = state.documents[state.activeDocument] } = {}) => documentState?.moduleId === "reports"
  || (state.moduleItems?.reports ?? []).some((entry) => Array.isArray(entry) && entry[0] === documentId);

const isAuthorCockpitContractDocument = ({ documentId = state.activeDocument } = {}) => state.workspaceKind === "project"
  && documentId === CREATIVE_CONTRACT_DOCUMENT_ID;

const isReadonlyAuthorCockpitDocument = ({ documentId = state.activeDocument, documentState = state.documents[state.activeDocument], moduleId = state.activeModule } = {}) => state.workspaceKind === "project"
  && isAuthorCockpitModule(moduleId)
  && (documentId === "index-pending" || documentState?.derived === true || AUTHOR_COCKPIT_READONLY_DOCUMENT_IDS.has(documentId)
    || (belongsToAuthorCockpitReportCollection({ documentId, documentState }) && documentState?.placementOverride !== true && documentState?.documentKind !== "whiteboard"))
  && documentId !== "index-language-blacklist"
  ;

const renderCompilationDecisionSummary = () => {
  const documentState = state.documents[state.activeDocument];
  const contractDocument = isAuthorCockpitContractDocument();
  const visible = contractDocument || isReadonlyAuthorCockpitDocument({ documentState });
  elements.compilationDecisionSummary.hidden = !visible;
  if (!visible) {
    elements.compilationDecisionSummary.innerHTML = "";
    return;
  }
  if (state.activeDocument === "report-compile") {
    if (!ui.automation.experienceActivation && !ui.automation.experienceLoading) queueMicrotask(() => void refreshExperienceManager());
    const decision = projectCompilationDecisionSummary({ moduleItems: state.moduleItems, documents: state.documents });
    const projectExperienceItems = (ui.automation.experienceItems ?? []).filter((item) => item.scope?.level === "project" && item.scope?.scopeId === ui.automation.experienceProjectId);
    elements.compilationDecisionSummary.dataset.state = decision.status;
    elements.compilationDecisionSummary.innerHTML = authorCockpitOverviewHtml({
      moduleItems: state.moduleItems,
      documents: state.documents,
      decision,
      reportOrder: state.authorCockpitReportOrder,
      translate: uiText,
      refreshing: ui.authorCockpitRefreshing,
      integrityScan: ui.authorCockpitIntegrityScan,
      experienceSummary: {
        loading: ui.automation.experienceLoading,
        total: projectExperienceItems.length,
        mature: projectExperienceItems.filter((item) => ["mature", "clustered"].includes(item.status) || item.promotion?.status === "skill_draft").length,
        suspended: projectExperienceItems.filter((item) => item.usage?.recallSuspended === true || item.status === "revoked").length,
      },
    });
    return;
  }
  elements.compilationDecisionSummary.dataset.state = "readonly";
  elements.compilationDecisionSummary.innerHTML = contractDocument
    ? authorCockpitContractDocumentHtml({ documentState, translate: uiText })
    : state.activeDocument === "index-pending"
      ? authorCockpitPendingDocumentHtml({ documentState, translate: uiText })
      : authorCockpitReadonlyDocumentHtml({ documentState, translate: uiText });
};

const updatePendingDecisionItem = (itemId, patch = {}) => {
  const pendingDocument = state.documents["index-pending"];
  if (!pendingDocument) return null;
  const items = pendingDecisionItems(pendingDocument);
  const index = items.findIndex((item) => item.id === itemId);
  if (index < 0) return null;
  items[index] = { ...items[index], ...patch };
  pendingDocument.cockpitDecisionItems = items;
  pendingDocument.updatedAt = nowTime();
  return items[index];
};

const pendingDecisionById = (itemId) => pendingDecisionItems(state.documents["index-pending"] ?? {})
  .find((item) => item.id === itemId && item.status !== "resolved");

const persistCockpitDecisionDraftSoon = () => {
  clearTimeout(ui.authorCockpitDecisionDraftTimer);
  ui.authorCockpitDecisionDraftTimer = setTimeout(() => {
    ui.authorCockpitDecisionDraftTimer = null;
    persist({ documentIds: ["index-pending"] });
  }, 180);
};

const persistCockpitDecisionNow = () => {
  clearTimeout(ui.authorCockpitDecisionDraftTimer);
  ui.authorCockpitDecisionDraftTimer = null;
  persist({ documentIds: ["index-pending"] });
  void saveWorkspace();
};

const renderAuthorCockpitDecisionDialog = (itemId = elements.authorCockpitDecisionDialog?.dataset?.itemId || "") => {
  const items = pendingDecisionItems(state.documents["index-pending"] ?? {}).filter((item) => item.status !== "resolved");
  const index = items.findIndex((item) => item.id === itemId);
  const item = items[index];
  if (!item) {
    if (elements.authorCockpitDecisionDialog?.open) elements.authorCockpitDecisionDialog.close();
    return false;
  }
  elements.authorCockpitDecisionDialog.dataset.itemId = item.id;
  elements.authorCockpitDecisionDialogTitle.textContent = item.status === "confirmed" ? "已确认事项" : item.status === "processing" || item.status === "queued" ? "处理中事项" : "待确认事项";
  elements.authorCockpitDecisionDialogBody.innerHTML = authorCockpitDecisionEditorHtml({ item, index, translate: uiText });
  return true;
};

const openAuthorCockpitDecisionDialog = (itemId) => {
  if (!renderAuthorCockpitDecisionDialog(itemId)) {
    showToast("该问题已经处理或内容已经变化，请刷新后重试");
    return;
  }
  if (!elements.authorCockpitDecisionDialog.open) elements.authorCockpitDecisionDialog.showModal();
  requestAnimationFrame(() => {
    const textarea = elements.authorCockpitDecisionDialogBody.querySelector("[data-cockpit-decision-opinion]");
    if (textarea && !textarea.readOnly) textarea.focus({ preventScroll: true });
  });
};

const closeAuthorCockpitDecisionDialog = () => {
  const itemId = elements.authorCockpitDecisionDialog?.dataset?.itemId || "";
  if (ui.authorCockpitDecisionDraftTimer || pendingDecisionById(itemId)) persistCockpitDecisionNow();
  if (elements.authorCockpitDecisionDialog.open) elements.authorCockpitDecisionDialog.close();
  elements.authorCockpitDecisionDialog.dataset.itemId = "";
};

const confirmCockpitDecision = (button) => {
  const itemId = button?.dataset?.confirmCockpitDecision;
  const item = pendingDecisionById(itemId);
  if (!item) {
    showToast("该问题已经处理或内容已经变化，请刷新后重试");
    return false;
  }
  const itemElement = button.closest("[data-cockpit-decision-item]");
  const opinion = String(itemElement?.querySelector("[data-cockpit-decision-opinion]")?.value || item.draftOpinion || "").trim();
  if (!opinion) {
    showToast("请先填写具体决策信息，再点击确认");
    return false;
  }
  updatePendingDecisionItem(itemId, {
    status: "confirmed",
    decisionType: "opinion",
    opinion,
    draftOpinion: opinion,
    confirmedDecision: opinion,
    reviewedAt: `今天 ${nowTime()}`,
    processingAt: "",
    lastError: "",
  });
  persistCockpitDecisionNow();
  renderCompilationDecisionSummary();
  if (elements.authorCockpitDecisionDialog.open) renderAuthorCockpitDecisionDialog(itemId);
  showToast("决策已确认并锁定；点击“执行已确认项目”后才会交给 Agent");
  return true;
};

const editCockpitDecision = (button) => {
  const itemId = button?.dataset?.editCockpitDecision;
  const item = pendingDecisionById(itemId);
  if (!item || item.status !== "confirmed") return false;
  updatePendingDecisionItem(itemId, {
    status: "pending",
    draftOpinion: item.draftOpinion || item.opinion,
    lastError: "",
  });
  persistCockpitDecisionNow();
  renderCompilationDecisionSummary();
  if (elements.authorCockpitDecisionDialog.open) {
    renderAuthorCockpitDecisionDialog(itemId);
    requestAnimationFrame(() => {
      const textarea = elements.authorCockpitDecisionDialogBody.querySelector("[data-cockpit-decision-opinion]");
      textarea?.focus({ preventScroll: true });
      textarea?.setSelectionRange?.(textarea.value.length, textarea.value.length);
    });
  }
  return true;
};

const updateCockpitDecisionDraftFromTextarea = (textarea) => {
  if (!textarea || textarea.readOnly) return;
  const itemElement = textarea.closest("[data-cockpit-decision-item]");
  const itemId = itemElement?.dataset?.cockpitDecisionItem;
  if (!itemId) return;
  const draftOpinion = textarea.value;
  updatePendingDecisionItem(itemId, { draftOpinion });
  persistCockpitDecisionDraftSoon();
  const confirmButton = itemElement.querySelector("[data-confirm-cockpit-decision]");
  if (confirmButton) confirmButton.disabled = !draftOpinion.trim();
};

const ensureCockpitDecisionReport = () => {
  const documentId = "report-decision-processing";
  if (!state.documents[documentId]) {
    state.documents[documentId] = {
      title: "批示处理记录",
      moduleId: "reports",
      derived: true,
      html: "<h1>批示处理记录</h1><p>记录作者逐条确认或批示后的实际处理结果、修改范围与失败原因。</p>",
      updatedAt: nowTime(),
    };
  }
  state.moduleItems.reports ??= [];
  if (!state.moduleItems.reports.some(([id]) => id === documentId)) state.moduleItems.reports.push([documentId, "批示处理记录", { workspaceView: "default" }]);
  return state.documents[documentId];
};

const appendCockpitDecisionReport = ({ item, decisionType, opinion, status, changedTitles = [], result = "" }) => {
  const report = ensureCockpitDecisionReport();
  const handledAt = `今天 ${nowTime()}`;
  const statusLabel = status === "resolved" ? "已完成" : "未完成";
  const changeCopy = changedTitles.length ? changedTitles.join("、") : "未检测到项目文档变更";
  report.html = sanitizeDocumentHtml(`${String(report.html || "")}<section><h2>${escapeHtml(handledAt)} · ${escapeHtml(statusLabel)}</h2><p><strong>待确认事项：</strong>${escapeHtml(item.text)}</p><p><strong>作者处理：</strong>${escapeHtml(decisionType === "confirmed" ? "确认按当前建议执行" : opinion)}</p><p><strong>实际修改：</strong>${escapeHtml(changeCopy)}</p>${result ? `<p><strong>处理结果：</strong>${escapeHtml(result)}</p>` : ""}</section>`);
  report.updatedAt = nowTime();
  return report;
};

const cockpitDecisionExecutionPrompt = ({ item, decisionType, opinion = "" }) => {
  const display = pendingDecisionDisplay(item);
  const authorInstruction = decisionType === "confirmed" ? "作者确认按当前问题所表达的方向处理。" : `作者确认意见：${String(opinion).trim()}`;
  const foreshadowingDecision = /伏笔|暗线|悬念|线索|埋设|回收/u.test([
    display.question,
    display.explanation,
    item?.context,
    item?.recommendation,
    opinion,
  ].filter(Boolean).join("\n"));
  const specialRouting = foreshadowingDecision
    ? [
      "本项属于伏笔信息确认：只把确认口径同步到当前文体对应的记忆板块信息台阶、伏笔管理和全文/全集大纲。",
      "小说优先更新 memory-release、memory-foreshadowing 与 outline-series；剧本优先更新 script-memory-release、script-memory-foreshadowing 与 script-outline-series。根据来源文体只选一组，不得同时污染小说与剧本。",
      "本轮严禁修改任何正文、章节或分集剧本文档；伏笔应在后续正式创作时依据记忆和大纲自然兑现。",
    ].join("\n")
    : "本项不是伏笔专用同步，按用户确认内容只修改实际受影响的正式文档。";
  return [
    "处理索引中已经由用户确认的一条具体问题。",
    `来源文档：${display.sourcePath}`,
    `具体问题：${display.question}`,
    authorInstruction,
    specialRouting,
    "这是用户已经确认的修改指令，不得再设置候选稿、自检满意度或二次审批门禁；只有发现会导致不可逆删除、目标含义互斥或缺少用户才能提供的事实时，才返回清晰的自然语言问题交由界面弹窗确认。",
    "读取当前作品全部必要资料并建立影响清单；从来源文档和正式设定开始，检查资料、设定、大纲、正文与记忆中的直接提及、别名、语义依赖和因果依赖。",
    "对每个受影响文档读取用户当前最新版，优先使用精确 Patch、范围 Patch、块级 Patch 或语义 Patch；不要整篇重写，不要改动无关内容。",
    "对任何已有文档执行覆盖、续写、追加或局部替换前，都必须保存一次完整历史版本；包括空白或只有标题的占位文档。",
    "将确认结论写入所有实际受影响的正式文档并回读验证；没有真实内容时不要创建文档，不得只写编译报告或只解释方案。",
    "完成后逐项列出实际修改的正式文档。不要修改任何 CLI、API、模型、凭证或生成连接配置。",
  ].join("\n");
};

const finalizeCockpitDecisionExecution = async ({ itemId, decisionType, opinion = "", completion, beforeHashes }) => {
  const pendingDocument = state.documents["index-pending"];
  const item = pendingDecisionItems(pendingDocument).find((entry) => entry.id === itemId && entry.status !== "resolved");
  if (!item) return false;
  let operationApplied = true;
  if (completion?.workspacePlan?.status === "waiting_confirm") {
    operationApplied = await applyWorkspaceOperationPlan(completion.id, { automatic: true, confirmed: true });
  }
  const effectiveMessage = completion?.id ? state.messages.find((message) => message.id === completion.id) ?? completion : completion;
  const afterHashes = documentSaveHashes(state.documents);
  const changedDocumentIds = [...afterHashes.entries()]
    .filter(([documentId, hash]) => !["index-pending", "report-decision-processing", "index-update-log"].includes(documentId) && beforeHashes.get(documentId) !== hash)
    .map(([documentId]) => documentId);
  const changedTitles = changedDocumentIds.map((documentId) => state.documents[documentId]?.title || documentId);
  const executed = effectiveMessage?.workspacePlan?.status === "applied"
    || effectiveMessage?.landingStatus === "complete"
    || changedTitles.length > 0;
  const failed = !effectiveMessage
    || ["failed", "cancelled", "blocked", "paused"].includes(effectiveMessage.execution?.status)
    || effectiveMessage.workspacePlan && effectiveMessage.workspacePlan.status !== "applied"
    || operationApplied === false
    || !executed;
  const result = String(effectiveMessage?.execution?.result || effectiveMessage?.content || "").replace(/\s+/g, " ").trim().slice(0, 500);
  const status = failed ? "confirmed" : "resolved";
  updatePendingDecisionItem(itemId, {
    status,
    decisionType,
    opinion: String(opinion).trim(),
    draftOpinion: String(opinion).trim(),
    reviewedAt: `今天 ${nowTime()}`,
    committedTargets: failed ? [] : changedDocumentIds,
    lastError: failed ? result || "AI 未能完成本次修改，事项仍保留待确认。" : "",
  });
  appendCockpitDecisionReport({ item, decisionType, opinion: String(opinion).trim(), status, changedTitles, result });
  rebuildProjectCompilationStatus();
  recordActivity({
    type: "edit",
    label: failed ? `索引事项处理未完成：${pendingDecisionDisplay(item).question.slice(0, 24)}` : `索引事项已处理：${pendingDecisionDisplay(item).question.slice(0, 24)}`,
    documentId: "report-decision-processing",
    scope: { type: "project", id: "project" },
  });
  persist({ documentIds: ["index-pending", "report-decision-processing"] });
  await saveWorkspace({ throwOnError: true });
  renderAll();
  showToast(failed ? "本次修改未完成，具体问题仍保留在待确认事项中" : "确认内容已写入受影响文档并完成验证");
  return !failed;
};

const failCockpitDecisionExecution = async ({ itemId, decisionType, opinion = "", error }) => {
  const pendingDocument = state.documents["index-pending"];
  const item = pendingDecisionItems(pendingDocument).find((entry) => entry.id === itemId && entry.status !== "resolved");
  if (!item) return false;
  const message = String(error?.message || error || "处理失败");
  updatePendingDecisionItem(itemId, { status: "confirmed", decisionType, opinion: String(opinion).trim(), draftOpinion: String(opinion).trim(), lastError: message });
  appendCockpitDecisionReport({ item, decisionType, opinion: String(opinion).trim(), status: "pending", result: message });
  persist({ documentIds: ["index-pending", "report-decision-processing"] });
  await saveWorkspace();
  renderAll();
  showToast(`事项处理失败：${message}`);
  return false;
};

const processCockpitDecisionItem = async ({ itemId, decisionType, opinion = "" }) => {
  const pendingDocument = state.documents["index-pending"];
  const item = pendingDecisionItems(pendingDocument).find((entry) => entry.id === itemId && entry.status !== "resolved");
  const normalizedOpinion = String(opinion).trim();
  if (!item) {
    showToast("该事项已处理或内容已经变化，请刷新后重试");
    return false;
  }
  if (decisionType === "opinion" && !normalizedOpinion) {
    showToast("请先填写具体决策指示");
    return false;
  }
  updatePendingDecisionItem(itemId, {
    status: "queued",
    decisionType,
    opinion: normalizedOpinion,
    processingAt: "",
    lastError: "",
  });
  persist({ documentIds: ["index-pending"] });
  renderCompilationDecisionSummary();
  const prompt = cockpitDecisionExecutionPrompt({ item, decisionType, opinion: normalizedOpinion });
  const completion = await sendMessage(prompt, {
    conversationId: state.activeConversationId,
    cockpitDecision: { itemId, decisionType, opinion: normalizedOpinion },
  });
  if (!completion) showToast("确认内容已进入当前任务队列，完成后会自动回写受影响文档");
  return true;
};

const processCockpitDecisionBatchWithAgent = async () => {
  const pendingDocument = state.documents["index-pending"];
  const selected = pendingDecisionItems(pendingDocument).filter((item) => (
    item.status === "confirmed"
    && String(item.opinion || "").trim()
  ));
  if (!selected.length) {
    showToast("没有可执行项目：请先填写决策并点击确认");
    return false;
  }
  if (elements.authorCockpitDecisionDialog.open) closeAuthorCockpitDecisionDialog();
  const batchAuditPrompt = [
    "使用工作区 Agent 批量处理索引中全部已确认的待裁定事项。",
    "",
    "待处理事项：",
    ...selected.map((item, index) => `${index + 1}. [${item.id}] ${item.text}`),
    "",
    "执行要求：",
    "1. 先读取当前项目资料，分析事项之间的依赖、冲突和共同影响范围，并在执行详情中给出统一计划。",
    "2. 每条事项必须独立处理、独立验证；不得把多条事项合并成一个模糊结论。",
    "3. 只修改当前作品内必要的设定、创作合同、大纲、状态或索引文档；不得修改 CLI、API、模型、凭证或连接配置。",
    "4. 修改前遵守工作区 Agent 的权限、历史快照和不可逆操作确认门。",
    "5. 只有已实际落盘并验证成功的事项，才从 09_索引/待确认事项.md 移除；失败项必须原样保留。",
    "6. 在批示处理记录或编译报告中逐项记录：原事项、实际修改文档、验证结果、失败原因。",
    "7. 完成后列出成功、失败和仍待作者补充的事项。",
  ].join("\n");
  renderCompilationDecisionSummary();
  recordActivity({
    type: "edit",
    label: `执行已确认项目：${selected.length} 项`,
    documentId: "index-pending",
    scope: { type: "project", id: "project" },
    detail: batchAuditPrompt.slice(0, 500),
  });
  for (const item of selected) {
    await processCockpitDecisionItem({
      itemId: item.id,
      decisionType: "opinion",
      opinion: item.opinion,
    });
  }
  return true;
};

const clearEditorNarrativePlaceholder = () => {
  elements.editor.removeAttribute("data-empty-placeholder");
  elements.editor.removeAttribute("aria-placeholder");
};

const syncEditorNarrativePlaceholder = ({
  documentId = state.activeDocument,
  html = state.documents[documentId]?.html ?? "",
} = {}) => {
  const placeholder = String(state.documents[documentId]?.emptyPlaceholder || "").trim() || narrativeEmptyPlaceholder({
    documentId,
    language: globalUiPreferences.uiLanguage,
  });
  if (!placeholder || stripHtml(html)) {
    clearEditorNarrativePlaceholder();
    return false;
  }
  elements.editor.dataset.emptyPlaceholder = placeholder;
  elements.editor.setAttribute("aria-placeholder", placeholder);
  return true;
};

const showWhiteboardSurface = () => {
  cancelUiBackgroundTask(ui.whiteboardSurfaceHideTask);
  ui.whiteboardSurfaceHideTask = null;
  elements.whiteboardEditor.hidden = false;
  elements.whiteboardEditor.classList.remove("surface-suspended");
};

const deferWhiteboardSurfaceHide = () => {
  // Hiding a large transformed canvas with `display:none` can synchronously
  // tear down hundreds of card layout objects. Make the document visible in
  // the current frame, then perform that housekeeping when input is idle.
  elements.whiteboardEditor.classList.add("surface-suspended");
  cancelWhiteboardProgressiveRender({ clearPresentation: true });
  cancelWhiteboardMediaHydration();
  cancelUiBackgroundTask(ui.whiteboardSurfaceHideTask);
  ui.whiteboardSurfaceHideTask = scheduleUiBackgroundTask(() => {
    ui.whiteboardSurfaceHideTask = null;
    if (activeWhiteboardDocument()) return;
    elements.whiteboardEditor.hidden = true;
    // The canonical canvas remains in state. Discard only the dormant DOM so
    // hidden image decoders and media elements cannot keep consuming memory or
    // compete with document editing; returning to the board rematerializes it.
    elements.whiteboardSurface.replaceChildren();
    delete elements.whiteboardSurface.dataset.renderIdentity;
  }, { delay: 80, timeout: 1_200 });
};

const renderEditor = () => {
  clearEditorNarrativePlaceholder();
  elements.whiteboardFullscreenButton.hidden = true;
  dismissWhiteboardGenerationDialogsOutsideActiveSurface();
  scheduleCodexAgentDocumentDirectorySync();
  if (ui.documentFind.open && ui.documentFind.documentId !== state.activeDocument) closeDocumentFindPanel();
  renderWritingTimer();
  renderMemoryReviewEntry();
  renderCompilationDecisionSummary();
  elements.editorCanvas.classList.remove("author-cockpit-readonly-mode");
  if (workspaceHasNoActiveEntry()) {
    const copy = emptyWorkspaceCopy();
    elements.workspace.classList.remove("whiteboard-mode");
    elements.editorCanvas.classList.remove("whiteboard-active", "note-document-active", "document-preview-mode");
    elements.whiteboardHistoryControls.hidden = true;
    elements.whiteboardEditor.hidden = true;
    elements.noteRichToolbar.hidden = true;
    elements.chapterTitlePanel.hidden = true;
    elements.documentModeButton.hidden = true;
    elements.selectionToolbar.hidden = true;
    elements.editor.hidden = false;
    elements.editor.contentEditable = "false";
    elements.editor.dataset.document = "";
    elements.editor.classList.add("workspace-empty");
    elements.editor.innerHTML = `<section class="workspace-empty-state" contenteditable="false"><strong>${escapeHtml(copy.prompt)}</strong><span>${escapeHtml(copy.chat)}</span><button class="primary-button" type="button" data-create-empty-workspace>${escapeHtml(copy.action)}</button></section>`;
    elements.breadcrumbs.innerHTML = `<span>${escapeHtml(copy.directory)}</span>`;
    elements.wordCount.textContent = "";
    const saveVersionButton = document.querySelector("#saveVersionButton");
    saveVersionButton.disabled = true;
    saveVersionButton.title = copy.prompt;
    saveVersionButton.setAttribute("aria-label", copy.prompt);
    renderWhiteboardGenerationCollapsedSessions();
    return;
  }
  elements.editor.classList.remove("workspace-empty");
  const documentState = state.documents[state.activeDocument];
  if (!documentState) {
    elements.workspace.classList.remove("whiteboard-mode");
    elements.editorCanvas.classList.remove("whiteboard-active", "note-document-active", "document-preview-mode");
    elements.whiteboardHistoryControls.hidden = true;
    elements.whiteboardEditor.hidden = true;
    elements.noteRichToolbar.hidden = true;
    elements.chapterTitlePanel.hidden = true;
    elements.documentModeButton.hidden = true;
    elements.selectionToolbar.hidden = true;
    elements.editor.hidden = false;
    elements.editor.contentEditable = "false";
    elements.editor.dataset.document = "";
    elements.editor.classList.toggle("workspace-empty", state.workspaceKind === "project");
    elements.editor.innerHTML = state.workspaceKind === "project"
      ? `<section class="workspace-empty-state" contenteditable="false"><strong>${escapeHtml(uiText("这里将呈现你的作品"))}</strong><span>${escapeHtml(uiText("可以先在右侧聊一个想法，或者带入已有稿件。"))}</span></section>`
      : "";
    elements.breadcrumbs.innerHTML = `<span>${state.workspaceKind === "notebook" ? "笔记目录" : "作品目录"}</span>`;
    elements.wordCount.textContent = "";
    const saveVersionButton = document.querySelector("#saveVersionButton");
    saveVersionButton.disabled = true;
    saveVersionButton.title = "当前没有可保存的文档";
    saveVersionButton.setAttribute("aria-label", saveVersionButton.title);
    renderWhiteboardGenerationCollapsedSessions();
    return;
  }
  const isWhiteboard = documentState.documentKind === "whiteboard";
  elements.whiteboardFullscreenButton.hidden = false;
  renderWhiteboardCreditBalance();
  if (isWhiteboard && !(ui.dreaminaAccountStatuses || []).length) {
    // Opening a whiteboard may read durable account metadata, but it must not
    // start a live CLI probe. Dreamina has one global Windows credential slot;
    // background probes for a stale profile used to block unrelated, verified
    // profiles before the user had asked to generate anything.
    void refreshDreaminaAccountStatus().catch(() => {});
  }
  if (!isWhiteboard) renderWhiteboardGenerationCollapsedSessions();
  elements.workspace.classList.toggle("whiteboard-mode", isWhiteboard);
  elements.whiteboardHistoryControls.hidden = !isWhiteboard;
  const isNoteDocument = state.workspaceKind === "notebook" && !isWhiteboard && state.activeDocument !== "library-trash";
  const module = activeModule();
  const cockpitContractDocument = isAuthorCockpitContractDocument();
  const forcedPreview = documentState.derived === true || documentState.externalMarkdown === true || cockpitContractDocument || isReadonlyAuthorCockpitDocument({ documentState, moduleId: module.id });
  const temporaryEditPromotionAvailable = state.temporaryNotebook === true && documentState.externalMarkdown === true;
  const previewAvailable = (!forcedPreview || temporaryEditPromotionAvailable) && !isWhiteboard && state.activeDocument !== "library-trash";
  const previewMode = forcedPreview || (previewAvailable && documentPreviewActive());
  elements.whiteboardFullscreenButton.hidden = previewMode && !isAuthorCockpitModule(module.id);
  renderDocumentModeButton({ available: previewAvailable, previewMode });
  // Notes and editable project documents share the same rich-text surface.
  // Keep the toolbar hidden only for whiteboards, previews, and non-document views.
  elements.noteRichToolbar.hidden = isWhiteboard || previewMode;
  elements.noteToolbarExpand.setAttribute("aria-expanded", String(!elements.noteRichToolbar.hidden && ui.noteToolbarExpanded));
  syncNoteToolbarLayout();
  elements.editorCanvas.classList.toggle("note-document-active", isNoteDocument);
  elements.editorCanvas.classList.toggle("document-preview-mode", previewMode);
  if (!isWhiteboard) {
    const markdownUpgrade = upgradeLegacyStructuredMarkdownInHtml(documentState.html);
    if (markdownUpgrade.changed) documentState.html = markdownUpgrade.html;
  }
  const presentationModule = activePresentationModule();
  const cockpitReadonlyDocument = isReadonlyAuthorCockpitDocument({ documentState, moduleId: module.id });
  const cockpitFixedDocument = cockpitReadonlyDocument || cockpitContractDocument;
  elements.editorCanvas.classList.toggle("author-cockpit-readonly-mode", cockpitFixedDocument);
  const displayDocumentTitle = localizeSystemDocumentTitle({ title: documentState.title, language: documentState.titleLanguage ?? state.structureLanguage, moduleId: module.id, viewId: activeViewForModule(module.id), documentId: state.activeDocument, documentKind: documentState.documentKind, systemGenerated: documentState.systemGeneratedTitle });
  const breadcrumbModuleId = state.workspaceKind === "notebook" ? "manuscript" : presentationModule.id;
  const breadcrumbModuleLabel = state.workspaceKind === "notebook" ? "笔记" : presentationModule.label;
  elements.breadcrumbs.innerHTML = `<button class="breadcrumb-link" type="button" data-breadcrumb-module="${escapeHtml(breadcrumbModuleId)}" title="${escapeHtml(uiText("返回上一级"))}" aria-label="${escapeHtml(uiText("返回上一级"))}">${escapeHtml(uiText(breadcrumbModuleLabel))}</button>${icon("\uE76C")}<span>${escapeHtml(displayDocumentTitle)}</span>`;
  const isNovelChapter = state.workspaceKind !== "notebook" && /^chapter-\d+$/.test(state.activeDocument);
  const isScriptEpisode = state.workspaceKind !== "notebook" && /^script-episode-\d+$/.test(state.activeDocument);
  const saveVersionButton = document.querySelector("#saveVersionButton");
  const canSaveCurrentDocument = Boolean(state.documents[state.activeDocument] && state.activeDocument !== "library-trash" && !documentState.derived && !documentState.externalMarkdown && !cockpitFixedDocument);
  saveVersionButton.disabled = !canSaveCurrentDocument;
  saveVersionButton.title = canSaveCurrentDocument ? "版本保存当前文档" : "当前内容不支持版本保存";
  saveVersionButton.setAttribute("aria-label", saveVersionButton.title);
  const hasDocumentTitle = !isWhiteboard && state.activeDocument !== "library-trash";
  const editableDocumentTitle = hasDocumentTitle && canSaveCurrentDocument && !previewMode;
  elements.chapterTitlePanel.hidden = !hasDocumentTitle;
  elements.chapterTitlePanel.classList.toggle("note-title-panel", isNoteDocument);
  elements.chapterTitle.classList.toggle("note-document-title", isNoteDocument);
  if (hasDocumentTitle) {
    const titleLabel = isNovelChapter ? "修改章节标题" : isScriptEpisode ? "修改剧本标题" : isNoteDocument ? "修改笔记标题" : "修改文档标题";
    const navigationTitle = documentItem(state.activeDocument)?.item?.[1] || "";
    const sequenceKind = sequencedDocumentKind(state.activeDocument, documentState);
    const sequenceNumber = sequenceKind
      ? effectiveSequencedDocumentNumber({ documentId: state.activeDocument, documentState, title: documentState.title })
      : 0;
    const englishSequence = documentState.titleLanguage === "en-US";
    const completeTitle = sequenceKind && sequenceNumber
      ? sequencedDocumentLabel({ documentId: state.activeDocument, title: documentState.title, language: englishSequence ? "en-US" : "zh-CN", documentState })
      : documentState.title;
    elements.chapterTitle.innerHTML = `<span class="chapter-title-text" contenteditable="${editableDocumentTitle}" role="textbox" aria-label="${titleLabel}" spellcheck="false" data-document-id="${escapeHtml(state.activeDocument)}" data-original-title="${escapeHtml(completeTitle)}" data-full-sequence-title="${sequenceKind ? "true" : "false"}"${editableDocumentTitle ? ' tabindex="0"' : ""}>${escapeHtml(completeTitle)}</span>`;
    documentState.html = stripMatchingLeadingHeadingHtml(documentState.html, [documentState.title, navigationTitle]);
  }
  if (state.activeDocument === "library-trash") {
    ui.whiteboardFind.open = false;
    elements.whiteboardFindPanel.hidden = true;
    elements.editorCanvas.classList.remove("whiteboard-active");
    elements.editorCanvas.classList.remove("note-document-active");
    elements.noteRichToolbar.hidden = true;
    elements.whiteboardEditor.hidden = true;
    elements.editor.hidden = false;
    elements.chapterTitlePanel.hidden = true;
    renderTrashManager();
    elements.selectionToolbar.hidden = true;
    return;
  }
  if (isWhiteboard) {
    elements.editorCanvas.classList.add("whiteboard-active");
    elements.editorCanvas.classList.remove("note-document-active");
    elements.noteRichToolbar.hidden = true;
    elements.chapterTitlePanel.hidden = true;
    elements.editor.hidden = true;
    showWhiteboardSurface();
    elements.selectionToolbar.hidden = true;
    renderWhiteboard(documentState);
    return;
  }
  elements.editorCanvas.classList.remove("whiteboard-active");
  ui.whiteboardEditingNodeId = null;
  ui.whiteboardSelectedNodeId = null;
  ui.whiteboardSelectedDocumentId = null;
  ui.whiteboardSelectedEdgeId = null;
  ui.whiteboardSelectedEdgeIds = new Set();
  ui.whiteboardSelectedEdgeDocumentId = null;
  deferWhiteboardSurfaceHide();
  ui.whiteboardFind.open = false;
  elements.whiteboardFindPanel.hidden = true;
  if (cockpitFixedDocument) {
    elements.editor.hidden = true;
    elements.editor.dataset.document = state.activeDocument;
    elements.selectionToolbar.hidden = true;
    if (cockpitContractDocument) {
      const contract = normalizeCreativeContract(documentState);
      const count = contract.bannedTerms.length + contract.specialNotes.length;
      elements.wordCount.textContent = `${count.toLocaleString("zh-CN")} 字 · 自动保存`;
    } else {
      elements.wordCount.textContent = "只读";
    }
    return;
  }
  elements.editor.hidden = false;
  elements.editor.contentEditable = String(!previewMode);
  elements.editor.setAttribute("aria-label", previewMode ? "正文预览" : "可编辑正文");
  if (elements.editor.dataset.document !== state.activeDocument) {
    ui.inlineEdits.clear();
    ui.documentEditPendingMutation = null;
    ui.documentEditorRange = null;
    ui.documentEditorRangeDocumentId = "";
    const sanitizeKey = `${workspaceIdentity()}::${state.activeDocument}`;
    const sourceRevision = contentRevision(documentState.html);
    const cachedSanitized = ui.sanitizedDocumentHtmlCache.get(sanitizeKey);
    if (cachedSanitized?.revision === sourceRevision) {
      documentState.html = cachedSanitized.html;
      touchBoundedMap(ui.sanitizedDocumentHtmlCache, sanitizeKey, cachedSanitized, SANITIZED_DOCUMENT_CACHE_LIMIT);
    } else {
      documentState.html = sanitizeDocumentHtml(documentState.html);
      touchBoundedMap(ui.sanitizedDocumentHtmlCache, sanitizeKey, {
        revision: contentRevision(documentState.html),
        html: documentState.html,
      }, SANITIZED_DOCUMENT_CACHE_LIMIT);
    }
    elements.editor.innerHTML = documentState.html;
    hydrateWorkspaceAttachmentMedia(elements.editor);
    elements.editor.dataset.document = state.activeDocument;
    restorePendingInlineEditsForDocument(state.activeDocument);
  }
  hydrateNoteTables(elements.editor, { editable: !elements.noteRichToolbar.hidden });
  hydrateDocumentArtifactControls(elements.editor, documentState);
  syncEditorNarrativePlaceholder({ documentId: state.activeDocument, html: documentState.html });
  if (!previewMode) activeDocumentEditHistory(state.activeDocument, documentState.html);
  syncDocumentEditorHistoryControls();
  updateEditorWordCount();
  if (!elements.noteRichToolbar.hidden) requestAnimationFrame(syncNoteToolbarState);
  if (previewMode) hideSelectionToolbar();
  renderDocumentFindPanel();
  requestAnimationFrame(() => {
    if (previewMode) {
      hideSelectionToolbar();
      return;
    }
    hideSelectionToolbar();
  });
  requestAnimationFrame(renderSearchHighlight);
};

const targetLabel = (target = null) => {
  if (!target?.documentId) return "当前绑定文档";
  return state.documents[target.documentId]?.title
    ?? target.title
    ?? (target.chapterNumber ? `第${target.chapterNumber}章（待建立文档）` : "当前绑定文档");
};

const explicitNamedDocumentLandingTarget = ({ intent = null, fallbackTarget = null, deliverableType = "" } = {}) => {
  if (!intent?.create) return null;
  const report = deliverableType === "review_report" || fallbackTarget?.moduleId === "reports";
  const moduleId = report ? "reports" : fallbackTarget?.moduleId || "manuscript";
  const viewId = report ? "default" : fallbackTarget?.viewId || (moduleId === "manuscript" ? "novel" : "default");
  const contextDomain = report
    ? fallbackTarget?.contextDomain || "novel"
    : fallbackTarget?.contextDomain || (viewId === "script" ? "script" : "novel");
  const resolved = {
    ...(fallbackTarget || {}),
    kind: "artifact",
    documentId: uid(`${moduleId}-generated-document`),
    moduleId,
    viewId,
    contextDomain,
    title: intent.title || fallbackTarget?.title || "未命名文档",
    explicitArtifact: true,
    explicitChapter: false,
    forceCreateNewDocument: true,
    requestedDocumentTitle: intent.title || "",
  };
  delete resolved.chapterNumber;
  delete resolved.episodeNumber;
  delete resolved.batchRequest;
  delete resolved.chapterDocuments;
  delete resolved.expectedChapterCount;
  delete resolved.incompleteBatch;
  return resolved;
};

const createMissingArtifactDocument = (artifactTarget) => {
  if (!artifactTarget?.explicitArtifact || !artifactTarget.documentId || state.documents[artifactTarget.documentId]) return false;
  const moduleId = artifactTarget.moduleId;
  if (!MODULES.some((module) => module.id === moduleId)) return false;
  const creationLanguage = normalizeStructureLanguage(globalUiPreferences.uiLanguage);
  const title = fixedStructureTitle({
    documentId: artifactTarget.documentId,
    title: artifactTarget.title || (creationLanguage === "en-US" ? "Untitled document" : "未命名文档"),
    language: creationLanguage,
  });
  const options = {
    workspaceView: artifactTarget.viewId ?? "novel",
    contextDomain: artifactTarget.contextDomain ?? "novel",
    ...(artifactTarget.sourceMode ? { sourceMode: artifactTarget.sourceMode } : {}),
    ...(artifactTarget.treeGroup ? { treeGroup: artifactTarget.treeGroup } : {}),
  };
  state.documents[artifactTarget.documentId] = {
    title,
    html: "",
    updatedAt: nowTime(),
    moduleId,
    titleLanguage: creationLanguage,
    systemGeneratedTitle: true,
    ...options,
  };
  state.moduleItems[moduleId] ??= [];
  state.moduleItems[moduleId].push([artifactTarget.documentId, title, options]);
  return true;
};

const executionProgressValue = (execution, pending = false) => {
  const fallback = pending ? 3 : execution?.status === "complete" ? 100 : 0;
  return Math.min(100, Math.max(0, Math.round(Number(execution?.progressPercent) || fallback)));
};

const formatExecutionDuration = (milliseconds = 0) => formatGenerationDuration(milliseconds);

const executionTimestampMilliseconds = (value) => {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const parsed = Date.parse(String(value || ""));
  return Number.isFinite(parsed) ? parsed : 0;
};

const executionTiming = (execution = {}, message = null, pending = false) => {
  const attempt = message?.generationAttempt ?? {};
  const startedAt = executionTimestampMilliseconds(execution.startedAt || attempt.startedAt || attempt.createdAt);
  const endedAt = executionTimestampMilliseconds(execution.endedAt || attempt.completedAt || attempt.updatedAt);
  const recordedElapsed = Math.max(0, Number(execution.elapsedMs) || Number(attempt.execution?.elapsedMs) || 0);
  const elapsedMs = pending && startedAt
    ? Math.max(0, Date.now() - startedAt)
    : recordedElapsed || (startedAt && endedAt ? Math.max(0, endedAt - startedAt) : 0);
  return { startedAt, endedAt, elapsedMs };
};

const refreshExecutionTimers = () => {
  document.querySelectorAll(".execution-time[data-started-at]").forEach((element) => {
    const startedAt = Number(element.dataset.startedAt);
    if (startedAt) element.textContent = `已用 ${formatExecutionDuration(Date.now() - startedAt)}`;
  });
  document.querySelectorAll(".execution-agent-elapsed[data-agent-started-at]").forEach((element) => {
    const startedAt = Number(element.dataset.agentStartedAt);
    if (startedAt) element.textContent = `已用 ${formatExecutionDuration(Date.now() - startedAt)}`;
  });
  document.querySelectorAll("[data-heartbeat-at]").forEach((element) => {
    const heartbeatAt = Date.parse(element.dataset.heartbeatAt || "");
    if (!Number.isFinite(heartbeatAt)) return;
    const seconds = Math.max(0, Math.round((Date.now() - heartbeatAt) / 1000));
    const stageStartedAt = Date.parse(element.dataset.stageStartedAt || "");
    const stageSeconds = Number.isFinite(stageStartedAt) ? Math.max(0, Math.round((Date.now() - stageStartedAt) / 1000)) : 0;
    const recent = seconds < 60 ? `${seconds}秒前` : `${Math.floor(seconds / 60)}分${seconds % 60}秒前`;
    element.textContent = seconds > 15
      ? `连接待核对 · 最近心跳：${recent}`
      : stageSeconds > 30
        ? `模型仍在响应 · 最近心跳：${recent}`
        : `最近响应：${recent}`;
    element.dataset.state = seconds > 15 ? "check_connection" : stageSeconds > 30 ? "responding" : "live";
    if (seconds > 20) {
      const messageId = element.closest("[data-message]")?.dataset.message || "";
      const message = state.messages.find((item) => item.id === messageId && item.pending && item.execution?.requestId);
      if (message && message.execution?.status !== "applying") scheduleStaleTextGenerationReconciliation(message);
    }
  });
};

const EXECUTION_TIMER_SELECTOR = [
  ".execution-time[data-started-at]",
  ".execution-agent-elapsed[data-agent-started-at]",
  "[data-heartbeat-at]",
].join(",");
let executionTimerRefreshHandle = null;
const scheduleExecutionTimerRefresh = () => {
  if (executionTimerRefreshHandle || !document.querySelector(EXECUTION_TIMER_SELECTOR)) return;
  const refresh = () => {
    executionTimerRefreshHandle = null;
    if (!document.querySelector(EXECUTION_TIMER_SELECTOR)) return;
    refreshExecutionTimers();
    executionTimerRefreshHandle = setTimeout(refresh, 250);
  };
  executionTimerRefreshHandle = setTimeout(refresh, 250);
};

const generationAttemptActionMarkup = (message) => {
  const attempt = message.generationAttempt;
  if (!attempt?.requestId) return "";
  const candidateAvailable = Boolean(attempt.candidate || message.candidate);
  const status = attempt.status || "";
  const validation = attempt.validationStatus || message.execution?.validationStatus || "pending";
  const landing = attempt.landingStatus || message.execution?.landingStatus || "not_requested";
  const memoryBlocked = attempt.resultData?.payload?.execution?.memoryGate?.status === "blocked";
  const isTerminal = !["running", "checking", "planning", "generating", "repairing", "finalizing"].includes(status) && !attempt.active;
  let action = "";
  let label = "";
  // A verified formal result lands automatically. Landing recovery and target
  // clarification live beside the composer, so authors never have to scroll
  // back to an old message to finish a write transaction.
  if (["interrupted", "failed"].includes(status) && candidateAvailable && landing !== "failed") [action, label] = ["continue_check", "继续检查，不重新生成"];
  else if (validation === "blocked" && candidateAvailable) [action, label] = [memoryBlocked ? "continue_check" : "recheck", "重新验收最终稿"];
  else if (validation === "pending" && candidateAvailable && !["running", "checking"].includes(status)) [action, label] = ["recheck", "重新验收最终稿"];
  else if (["running", "checking"].includes(status) && candidateAvailable) [action, label] = ["view_candidate", "查看已保存候选"];
  else if (status === "failed" && !candidateAvailable) [action, label] = ["regenerate", "重新生成"];
  if (!action) return "";
  const disabledAttr = ui.workspaceHydrating ? ' disabled title="工作区仍在安全加载，加载完成后即可操作"' : "";
  const primaryButton = `<button class="secondary-button compact" type="button" data-generation-attempt-action="${action}" data-generation-attempt-id="${escapeHtml(attempt.requestId)}"${disabledAttr}>${escapeHtml(label)}</button>`;
  const regenerateButton = (candidateAvailable && isTerminal && action !== "regenerate")
    ? `<button class="secondary-button compact" type="button" data-generation-attempt-action="regenerate" data-generation-attempt-id="${escapeHtml(attempt.requestId)}"${disabledAttr} title="重新生成，旧内容将存入历史版本">重新生成</button>`
    : "";
  return `<div class="generation-attempt-actions">${primaryButton}${regenerateButton}</div>`;
};

