  running_command: "正在运行命令",
  command_completed: "命令已完成",
  preparing_file_change: "正在准备文件修改",
  file_change_completed: "文件修改已完成",
  mutation_retrying: "文件未实际修改，正在自动纠正重试",
  mutation_verified: "文件修改已核验",
  mutation_not_applied: "文件未实际修改",
  mutation_retry_failed: "文件修改重试失败",
  evidence_retrying: "文件未实际读取，正在自动纠正重试",
  evidence_verified: "文件读取已核验",
  evidence_not_observed: "文件未实际读取",
  evidence_retry_failed: "文件读取重试失败",
