const confirmProjectDelete = (target) => {
  ui.deleteProjectTarget = target;
  ui.deleteDocumentId = null;
  ui.confirmAction = null;
  const notebook = target.workspaceKind === "notebook";
  document.querySelector("#confirmDialogTitle").textContent = notebook ? "删除笔记本" : "删除作品";
  document.querySelector("#confirmDialogCopy").textContent = notebook
    ? `“${target.name}”及其中全部笔记、白板和历史版本将作为整个笔记本移入统一回收站，保留30天。`
    : `“${target.name}”及其全部正文、设定、记忆和历史版本将作为整个作品移入统一回收站，保留30天。`;
  const submit = document.querySelector("#confirmDialogSubmit");
  submit.textContent = notebook ? "删除笔记本" : "删除作品";
  submit.classList.remove("primary-button");
  submit.classList.add("danger-button");
  elements.confirmDialog.showModal();
};

const confirmFolderDelete = (folderId) => {
  const record = customFolder(folderId);
  if (!record) return;
  const folderIds = customFolderSubtreeIds(folderId);
  const documentCount = itemsForModuleView(record.moduleId, record.viewId).filter(([, , options = {}]) => folderIds.has(options.customFolderId)).length;
  const childFolderCount = Math.max(0, folderIds.size - 1);
  ui.confirmAction = { type: "delete-folder", folderId };
  ui.deleteProjectTarget = null;
  ui.deleteDocumentId = null;
  document.querySelector("#confirmDialogTitle").textContent = "删除文件夹";
  document.querySelector("#confirmDialogCopy").textContent = `“${record.label}”${childFolderCount ? `、其中 ${childFolderCount} 个子文件夹` : ""}${documentCount ? `及 ${documentCount} 个文档` : ""}将连同文件夹历史版本移入回收站，保留30天。`;
  const submit = document.querySelector("#confirmDialogSubmit");
  submit.textContent = "移入回收站";
  submit.classList.remove("primary-button");
  submit.classList.add("danger-button");
  elements.confirmDialog.showModal();
};

const manuscriptVolumeSelection = (folderId) => manuscriptVolumeDeleteSelection({
  folderId,
  items: itemsForModuleView("manuscript", "novel"),
  folders: state.customFolders ?? [],
});

const confirmManuscriptVolumeDelete = (node) => {
  const selection = manuscriptVolumeSelection(node.id);
  // Count tree entries as well as hydrated documents. Older migration/copy
  // builds could leave a valid directory entry whose document payload was
  // already missing; users must still be able to remove that orphan safely.
  const documentCount = selection.documentIds.length;
  const childFolderCount = selection.customFolders.length;
  if (!documentCount && !childFolderCount) return;
  ui.confirmAction = { type: "delete-manuscript-volume", folderId: node.id, label: node.label };
  ui.deleteProjectTarget = null;
  ui.deleteDocumentId = null;
  document.querySelector("#confirmDialogTitle").textContent = "删除分卷";
  document.querySelector("#confirmDialogCopy").textContent = `“${node.label}”${childFolderCount ? `、其中 ${childFolderCount} 个子文件夹` : ""}${documentCount ? `及 ${documentCount} 个章节` : ""}将连同分卷历史版本移入回收站，保留30天。`;
  const submit = document.querySelector("#confirmDialogSubmit");
  submit.textContent = "移入回收站";
  submit.classList.remove("primary-button");
  submit.classList.add("danger-button");
  elements.confirmDialog.showModal();
};

const treeFolderDeleteSelection = (node) => {
  const documentIds = [];
  const customFolderIds = [];
  const visit = (entry) => {
    if (!entry) return;
    if (entry.type === "document" && entry.id) documentIds.push(entry.id);
    if (entry.type === "folder") {
      if (entry.custom && entry.id) customFolderIds.push(entry.id);
      (entry.children ?? []).forEach(visit);
    }
  };
  visit(node);
  return {
    documentIds: [...new Set(documentIds)],
    customFolderIds: [...new Set(customFolderIds)],
  };
};

const confirmTreeFolderDelete = ({ node, moduleId, viewId }) => {
  const selection = treeFolderDeleteSelection(node);
  ui.confirmAction = { type: "delete-tree-folder", node: clone(node), moduleId, viewId };
  ui.deleteProjectTarget = null;
  ui.deleteDocumentId = null;
  document.querySelector("#confirmDialogTitle").textContent = "删除文件夹";
  document.querySelector("#confirmDialogCopy").textContent = `“${node.label}”${selection.customFolderIds.length ? `及其中 ${selection.customFolderIds.length} 个子文件夹` : ""}${selection.documentIds.length ? `和 ${selection.documentIds.length} 个文档` : ""}将自动备份并移入回收站。`;
  const submit = document.querySelector("#confirmDialogSubmit");
  submit.textContent = "移入回收站";
  submit.classList.remove("primary-button");
  submit.classList.add("danger-button");
  elements.confirmDialog.showModal();
};

const projectCompilationInputSignature = () => {
  const documentParts = Object.entries(state.documents ?? {})
    .map(([id, documentState]) => [
      id,
      String(documentState?.updatedAt ?? ""),
      String(documentState?.contentRef?.hash ?? ""),
      String(documentState?.revision ?? documentState?.contentRevision ?? ""),
      String(documentState?.title ?? ""),
      String(documentState?.html?.length ?? documentState?.markdown?.length ?? 0),
      documentState?.derived === true ? "derived" : "",
    ])
    .sort(([left], [right]) => left.localeCompare(right, "en"));
  const moduleParts = Object.entries(state.moduleItems ?? {})
    .map(([moduleId, items]) => [moduleId, (items ?? []).map(([id, label, options = {}]) => [id, label, options.workspaceView ?? "", options.treeGroup ?? ""])])
    .sort(([left], [right]) => left.localeCompare(right, "en"));
  return JSON.stringify([documentParts, moduleParts]);
};

const rebuildProjectCompilationStatus = () => {
  if (state.workspaceKind !== "project") return false;
  const documentState = state.documents["report-compile"] || ensureLazyCockpitDocument("report-compile");
  if (!documentState) return false;
  const signature = projectCompilationInputSignature();
  const cached = ui.projectCompilationStatusCache;
  if (cached?.signature === signature && cached.document === documentState) return false;
  const nextHtml = projectCompilationStatusHtml({ moduleItems: state.moduleItems, documents: state.documents });
  const titleChanged = documentState.title !== "项目总览";
  const derivedChanged = documentState.derived !== true;
  if (!titleChanged && !derivedChanged && documentState.html === nextHtml) {
    ui.projectCompilationStatusCache = { signature, document: documentState };
    return false;
  }
  documentState.title = "项目总览";
  documentState.html = nextHtml;
  documentState.derived = true;
  documentState.updatedAt = nowTime();
  const item = state.moduleItems.reports?.find(([documentId]) => documentId === "report-compile");
  if (item) item[1] = "项目总览";
  ui.projectCompilationStatusCache = { signature: projectCompilationInputSignature(), document: documentState };
  return true;
};

const refreshImmediateCommitProjections = ({
  directDocumentIds = [],
  derivedDocumentIds = [],
  instruction = "",
  memoryPendingDocumentIds = [],
} = {}) => {
  if (state.workspaceKind !== "project") return { documentIds: [], plan: null };
  const directIds = [...new Set(directDocumentIds.filter((documentId) => state.documents[documentId]))];
  const plan = compilePostCommitProjection({
    documents: directIds.map((documentId) => ({
      documentId,
      moduleId: moduleForDocument(documentId),
      contextDomain: documentContextDomain(documentId),
    })),
  });
  const changedDocumentIds = new Set();
  const compileDocument = state.documents["report-compile"] || ensureLazyCockpitDocument("report-compile");
  if (compileDocument) snapshotDocument("report-compile", "本轮创作事务刷新项目总览前");
  if (rebuildProjectCompilationStatus()) changedDocumentIds.add("report-compile");

  const updateLog = state.documents["index-update-log"] || ensureLazyCockpitDocument("index-update-log");
  if (updateLog) {
    snapshotDocument("index-update-log", "追加本轮创作事务记录前");
    const committedTitles = directIds.map((documentId) => state.documents[documentId]?.title || documentId);
    const derivedIds = [...new Set([...derivedDocumentIds, ...changedDocumentIds])]
      .filter((documentId) => !directIds.includes(documentId) && documentId !== "index-update-log");
    const derivedTitles = derivedIds.map((documentId) => state.documents[documentId]?.title || documentId);
    const committedAt = new Date().toISOString();
    const pendingProjectionCount = new Set(memoryPendingDocumentIds).size;
    const statusText = pendingProjectionCount
      ? `正文已落盘；${pendingProjectionCount} 个正文单元仍有派生同步待重试`
      : "直接写入与即时派生更新均已进入同一保存事务";
    const entryHtml = [
      `<section data-shensi-commit="${escapeHtml(committedAt)}">`,
      `<h2>创作事务 · ${escapeHtml(`今天 ${nowTime()}`)}</h2>`,
      `<p><strong>状态：</strong>${escapeHtml(statusText)}</p>`,
      `<p><strong>直接写入：</strong>${escapeHtml(committedTitles.join("、") || "无")}</p>`,
      `<p><strong>派生更新：</strong>${escapeHtml(derivedTitles.join("、") || "无内容变化")}</p>`,
      memoryPendingDocumentIds.length ? `<p><strong>待同步：</strong>${escapeHtml(memoryPendingDocumentIds.map((documentId) => state.documents[documentId]?.title || documentId).join("、"))}</p>` : "",
      instruction ? `<p><strong>来源指令：</strong>${escapeHtml(String(instruction).replace(/\s+/gu, " ").slice(0, 300))}</p>` : "",
      "</section>",
    ].filter(Boolean).join("");
    updateLog.html = sanitizeDocumentHtml(`${String(updateLog.html || "")}${entryHtml}`);
    updateLog.structuredLogEntries ??= [];
    updateLog.structuredLogEntries.push({
      id: `commit-${contentRevision(`${committedAt}\u0000${directIds.join("\u0000")}\u0000${derivedIds.join("\u0000")}`)}`,
      kind: "creative_commit",
      sourceCommit: committedAt,
      changedDocuments: [...directIds, ...derivedIds],
      pendingDocuments: [...new Set(memoryPendingDocumentIds)],
      verifiedAt: committedAt,
    });
    updateLog.structuredLogEntries = updateLog.structuredLogEntries.slice(-500);
    updateLog.managedFormat = managedDocumentFormatMetadata({ documentId: "index-update-log", moduleId: "index", source: "trusted-index-projector" });
    updateLog.updatedAt = nowTime();
    updateLog.cockpitRecentSummary = statusText;
    changedDocumentIds.add("index-update-log");
  }
  return { documentIds: [...changedDocumentIds], plan };
};

const structuredMarkdownToHtml = (content = "") => String(content)
  .replace(/\r\n?/g, "\n")
  .split(/\n\s*\n/)
  .map((block) => block.trim())
  .filter(Boolean)
  .map((block) => {
    const table = markdownTableToHtml(block, { renderInline: inlineStructuredMarkdownToHtml });
    if (table) return table;
    if (/^(?:---+|___+|\*\*\*+)\s*$/.test(block)) return "";
    const heading = block.match(/^(#{1,3})\s+(.+)$/s);
    if (heading) {
      const level = heading[1].length;
      return `<h${level}>${inlineStructuredMarkdownToHtml(heading[2].trim())}</h${level}>`;
    }
    const lines = block.split(/\r?\n/);
    const unordered = lines.map((line) => line.match(/^\s*(?:[-*+]|·)\s+(.+)$/));
    if (unordered.length && unordered.every(Boolean)) return `<ul>${unordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ul>`;
    const ordered = lines.map((line) => line.match(/^\s*\d+[.)、]\s+(.+)$/));
    if (ordered.length && ordered.every(Boolean)) return `<ol>${ordered.map((item) => `<li>${inlineStructuredMarkdownToHtml(item[1])}</li>`).join("")}</ol>`;
    return `<p>${inlineStructuredMarkdownToHtml(block).replaceAll("\n", "<br>")}</p>`;
  })
  .join("");

const nextStructuredNumber = (pattern, fallback = 1) => Math.max(
  fallback - 1,
  ...Object.keys(state.documents).map((documentId) => Number(String(documentId).match(pattern)?.[1] ?? 0)),
) + 1;

const nextQuickCreateName = (kind, { moduleId = state.activeModule, viewId = activeViewForModule(moduleId) } = {}) => {
  const english = globalUiPreferences.uiLanguage === "en-US";
  const base = kind === "folder"
    ? english ? "New folder" : "新建文件夹"
    : kind === "whiteboard"
      ? english ? "Untitled whiteboard" : "未命名白板"
    : moduleId === "manuscript" && ["novel", "script"].includes(viewId)
      ? english ? "Untitled" : "未命名"
      : english ? "Untitled document" : "未命名文档";
  const labels = kind === "folder"
    ? state.customFolders.filter((folder) => folder.moduleId === moduleId && folder.viewId === viewId).map((folder) => folder.label)
    : itemsForModuleView(moduleId, viewId).map(([, label]) => label);
  if (!labels.includes(base)) return base;
  let index = 2;
  while (labels.includes(`${base} ${index}`)) index += 1;
  return `${base} ${index}`;
};

const createDocument = (name, placement = null, { kind = "document", systemGeneratedTitle = false } = {}) => {
  if (state.temporaryNotebook || state.readOnly) {
    showToast("临时笔记本只用于预览；请先将外部 Markdown 移动到正式笔记本");
    return null;
  }
  const moduleId = state.activeModule;
  const viewId = activeViewForModule(moduleId);
  const viewItems = itemsForModuleView(moduleId, viewId);
  const defaultTreeOptions = newDocumentTreeOptions({
    moduleId,
    viewId,
    items: viewItems,
    documents: state.documents,
    activeDocumentId: state.activeDocument,
  });
  const treeOptions = documentCreationOptions({ defaultOptions: defaultTreeOptions, placement });
  const creationLanguage = normalizeStructureLanguage(globalUiPreferences.uiLanguage);
  const english = creationLanguage === "en-US";
  const novelChapterSpec = kind !== "whiteboard" && state.workspaceKind !== "notebook" && moduleId === "manuscript" && viewId === "novel"
    ? novelChapterCreationSpec({
      name,
      existingIds: itemsForModule("manuscript").map(([itemId]) => itemId),
      existingNumbers: itemsForModule("manuscript")
        .filter(([itemId]) => sequencedDocumentKind(itemId) === "chapter")
        .map(([itemId]) => effectiveSequencedDocumentNumber({ documentId: itemId, documentState: state.documents[itemId] })),
      language: creationLanguage,
    })
    : null;
  if (novelChapterSpec?.collision) {
    showToast(`${english ? `Chapter ${novelChapterSpec.number}` : `第${novelChapterSpec.number}章`}已存在，请打开现有章节或改用其他章号`);
    return null;
  }
  const scopeLabel = moduleView(moduleId, viewId)?.label ?? activeModule().label;
  if (treeOptions.customFolderId) {
    snapshotVolume({ type: "volume", id: treeOptions.customFolderId, label: treeOptions.customFolderLabel, moduleId, viewId }, `${treeOptions.customFolderLabel}新增文档前的结构`);
  } else if (moduleId === "manuscript" && viewId === "novel" && treeOptions.folderId) {
    snapshotVolume({ type: "volume", id: treeOptions.folderId, label: treeOptions.folderLabel }, `${treeOptions.folderLabel}新增章节前的结构`);
  } else {
    snapshotStructure(moduleId, viewId, `${scopeLabel}新增文档前的结构`);
  }
  let id = state.workspaceKind === "notebook"
    ? `${kind === "whiteboard" ? "whiteboard" : "note"}-${Date.now()}`
    : kind === "whiteboard" ? uid(`${moduleId}-whiteboard`) : `${moduleId}-${Date.now()}`;
  let label = name;
  let documentTitle = name;
  if (kind !== "whiteboard" && state.workspaceKind !== "notebook" && moduleId === "manuscript" && viewId === "novel") {
    id = novelChapterSpec.documentId;
    label = novelChapterSpec.label;
    documentTitle = novelChapterSpec.title;
  } else if (kind !== "whiteboard" && moduleId === "manuscript" && viewId === "script") {
    const numbers = itemsForModule("manuscript").map(([itemId]) => Number(itemId.match(/^script-episode-(\d+)$/)?.[1] ?? 0));
    const number = Math.max(0, ...numbers) + 1;
    id = `script-episode-${number}`;
    documentTitle = freeDocumentTitle({ documentId: id, title: name, language: creationLanguage });
    label = sequencedDocumentLabel({ documentId: id, title: documentTitle, language: creationLanguage });
  } else if (kind !== "whiteboard" && moduleId === "manuscript" && viewId === "prompts") {
    id = `prompt-${treeOptions.treeGroup || "video"}-${Date.now()}`;
  } else if (kind !== "whiteboard" && moduleId === "outline" && viewId === "script") {
    id = treeOptions.treeGroup === "series"
      ? `script-outline-general-${Date.now()}`
      : `script-outline-episode-${nextStructuredNumber(/^script-outline-episode-(\d+)$/)}`;
  } else if (kind !== "whiteboard" && moduleId === "outline") {
    id = treeOptions.treeGroup === "series"
      ? `outline-general-${Date.now()}`
      : treeOptions.treeGroup === "volumes"
        ? `outline-volume-${nextStructuredNumber(/^outline-volume-(\d+)$/)}`
        : `outline-chapter-${nextStructuredNumber(/^outline-chapter-(\d+)$/)}`;
  }
  state.moduleItems[moduleId] ??= [];
  if (novelChapterSpec) {
    const insertionIndex = chapterInsertionIndex(state.moduleItems[moduleId], novelChapterSpec.number);
    state.moduleItems[moduleId].splice(insertionIndex, 0, [id, label, treeOptions]);
  } else state.moduleItems[moduleId].push([id, label, treeOptions]);
  state.documents[id] = {
    title: documentTitle,
    html: kind === "whiteboard" ? "" : moduleId === "manuscript" && ["novel", "script"].includes(viewId)
      ? ""
      : state.workspaceKind === "notebook" ? "" : `<p>${english ? "Define this document's purpose in the chat panel before filling it in." : "在右侧对话中确定这一文档的具体内容。"}</p>`,
    updatedAt: nowTime(),
    moduleId,
    workspaceView: treeOptions.workspaceView ?? viewId,
    contextDomain: state.workspaceKind === "notebook" ? "general" : treeOptions.contextDomain ?? "novel",
    documentKind: kind === "whiteboard" ? "whiteboard" : state.workspaceKind === "notebook" ? "note" : "document",
    systemGeneratedTitle: Boolean(systemGeneratedTitle),
    titleLanguage: creationLanguage,
    ...(kind === "whiteboard" ? { canvas: { nodes: [], edges: [], viewport: { x: 0, y: 0, zoom: 1 }, settings: { snapToGrid: true, gridSize: 20 } } } : {}),
    treeGroup: treeOptions.treeGroup,
    ...(treeOptions.rootPlacement === true ? { rootPlacement: true } : {}),
    ...(treeOptions.customFolderId ? {
      customFolderId: treeOptions.customFolderId,
      customFolderName: treeOptions.customFolderLabel,
      customFolderPath: treeOptions.customFolderPath ?? treeOptions.customFolderLabel,
    } : {}),
    placementOverride: true,
    ...(moduleId === "manuscript" && viewId === "novel" ? { volumeFolder: treeOptions.volumeFolder, volumeLabel: treeOptions.folderLabel } : {}),
  };
  state.histories[id] = [];
  if (state.workspaceKind === "notebook") state.moduleItems[moduleId] = sortNotebookChapterItems(state.moduleItems[moduleId], state.documents);
  state.activeDocument = id;
  state.moduleViews ??= {};
  if (typeof MODULE_VIEWS !== "undefined" && MODULE_VIEWS[moduleId]) state.moduleViews[moduleId] = treeOptions.workspaceView ?? viewId;
  const conversation = activeConversation();
  bindConversationToCreatedDocument({ conversation, documentId: id });
  synchronizeConversationReferenceContext(conversation);
  elements.editor.dataset.document = "";
  rebuildProjectCompilationStatus();
  recordActivity({ type: "edit", label: `新建${kind === "whiteboard" ? "白板" : state.workspaceKind === "notebook" ? "笔记" : `${activeModule().label}文档`}“${label}”`, documentId: id });
  persist();
  ui.documentListRenderKey = "";
  renderAll();
  return id;
};

const createFolder = async (name, placement = null, { systemGeneratedLabel = false } = {}) => {
  if (state.temporaryNotebook || state.readOnly) {
    showToast("临时笔记本只用于预览；请先移动到正式笔记本");
    return false;
  }
  const moduleId = state.activeModule;
  const viewId = activeViewForModule(moduleId);
  const label = String(name).trim();
  const duplicate = state.customFolders.some((folder) => (
    folder.moduleId === moduleId && folder.viewId === viewId && folder.label.toLowerCase() === label.toLowerCase()
  ));
  if (duplicate) {
    showToast("当前目录已经存在同名文件夹");
    return false;
  }
  const rollbackState = clone(state);
  const id = uid("custom-folder");
  const effectivePlacement = placement;
  const parentOptions = { ...(effectivePlacement?.options ?? effectivePlacement ?? {}) };
  delete parentOptions.customFolderId;
  delete parentOptions.customFolderLabel;
  if (moduleId === "manuscript" && viewId === "novel") Object.assign(parentOptions, {
    workspaceView: "novel",
    contextDomain: "novel",
    folderId: id,
    folderLabel: label,
    volumeFolder: label,
    treeGroup: "volume",
  });
  snapshotStructure(moduleId, viewId, `${moduleView(moduleId, viewId)?.label ?? activeModule().label}新建文件夹前的结构`);
  state.customFolders.push({
    id,
    label,
    systemGeneratedLabel,
    labelLanguage: normalizeStructureLanguage(globalUiPreferences.uiLanguage),
    moduleId,
    viewId,
    parentLocationId: effectivePlacement?.id ?? `${moduleId}:${viewId}:root`,
    parentLabel: effectivePlacement?.label ?? moduleView(moduleId, viewId)?.label ?? activeModule().label,
    parentOptions,
    folderPath: [parentOptions.customFolderPath, label].filter(Boolean).join("/"),
    createdAt: new Date().toISOString(),
  });
  state.expandedFolders.push(id);
  persistExpandedFolderState();
  recordActivity({ type: "edit", label: `新建文件夹“${label}”`, scope: { type: "volume", id, label, moduleId, viewId } });
  persist();
  renderAll();
  try {
    await saveWorkspace({ throwOnError: true });
    showToast(`已新建文件夹“${label}”`);
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    persist();
    renderAll();
    showToast(`新建文件夹失败：${error.message}`);
    return false;
  }
};

const renameFolder = async (folderId, nextName, context = {}) => {
  const record = customFolder(folderId);
  const label = String(nextName).trim();
  if (!record) {
    const moduleId = context.moduleId ?? state.activeModule;
    const viewId = context.viewId ?? activeViewForModule(moduleId);
    const tree = buildDocumentTree({
      moduleId,
      viewId,
      items: itemsForModuleView(moduleId, viewId),
      documents: state.documents,
      folders: state.customFolders,
      workspaceKind: state.workspaceKind,
    });
    const findFolder = (nodes) => {
      for (const node of nodes) {
        if (node.type !== "folder") continue;
        if (node.id === folderId) return node;
        const nested = findFolder(node.children ?? []);
        if (nested) return nested;
      }
      return null;
    };
    const node = findFolder(tree);
    if (!node || moduleId !== "manuscript" || viewId !== "novel" || !label || node.label === label) return false;
    if (tree.some((candidate) => candidate.type === "folder" && candidate.id !== folderId && candidate.label.toLowerCase() === label.toLowerCase())) {
      showToast("当前目录已经存在同名文件夹");
      return false;
    }
    const rollbackState = clone(state);
    const scope = { type: "volume", id: folderId, label: node.label, moduleId, viewId };
    snapshotVolume(scope, `文件夹“${node.label}”重命名为“${label}”`);
    for (const item of itemsForModuleView(moduleId, viewId)) {
      const options = item[2] ?? {};
      if (options.folderId !== folderId) continue;
      options.folderLabel = label;
      options.volumeFolder = label;
      const documentState = state.documents[item[0]];
      if (!documentState) continue;
      documentState.volumeLabel = label;
      documentState.volumeFolder = label;
      documentState.updatedAt = nowTime();
    }
    for (const folder of state.customFolders) {
      if (folder.parentLocationId !== folderId) continue;
      folder.parentLabel = label;
      if (folder.parentOptions) Object.assign(folder.parentOptions, { folderLabel: label, volumeFolder: label });
    }
    ui.historyScope = { ...scope, label };
    recordActivity({ type: "edit", label: `文件夹“${node.label}”重命名为“${label}”`, scope: ui.historyScope });
    persist();
    ui.documentListRenderKey = ""; // 清除缓存，确保文件夹列表立即显示最新命名
    renderAll();
    try {
      await saveWorkspace({ throwOnError: true });
      showToast("文件夹名称已更新");
      return true;
    } catch (error) {
      state = rollbackState;
      ensureStateSchema();
      persist();
      renderAll();
      showToast(`重命名失败：${error.message}`);
      return false;
    }
  }
  if (!label || record.label === label) return false;
  if (state.customFolders.some((folder) => folder.id !== folderId && folder.moduleId === record.moduleId && folder.viewId === record.viewId && folder.label.toLowerCase() === label.toLowerCase())) {
    showToast("当前目录已经存在同名文件夹");
    return false;
  }
  const rollbackState = clone(state);
  const scope = { type: "volume", id: folderId, label: record.label, moduleId: record.moduleId, viewId: record.viewId };
  snapshotVolume(scope, `文件夹“${record.label}”重命名为“${label}”`);
  const previousLabel = record.label;
  record.label = label;
  record.systemGeneratedLabel = false;
  if (record.moduleId === "manuscript" && record.viewId === "novel") {
    Object.assign(record.parentOptions, { folderLabel: label, volumeFolder: label });
  }
  const folderIds = customFolderSubtreeIds(folderId);
  for (const folder of state.customFolders) {
    if (folderIds.has(folder.id)) folder.folderPath = customFolderPathForRecord(folder.id);
  }
  for (const item of itemsForModuleView(record.moduleId, record.viewId)) {
    const options = item[2] ?? {};
    if (!folderIds.has(options.customFolderId)) continue;
    const owningFolder = customFolder(options.customFolderId);
    options.customFolderPath = customFolderPathForRecord(options.customFolderId);
    if (options.customFolderId === folderId) options.customFolderLabel = label;
    if (options.customFolderId === folderId && record.moduleId === "manuscript" && record.viewId === "novel") {
      options.folderLabel = label;
      options.volumeFolder = label;
    }
    const documentState = state.documents[item[0]];
    if (!documentState) continue;
    documentState.customFolderName = owningFolder?.label ?? documentState.customFolderName;
    documentState.customFolderPath = options.customFolderPath;
    if (options.customFolderId === folderId && record.moduleId === "manuscript" && record.viewId === "novel") {
      documentState.volumeLabel = label;
      documentState.volumeFolder = label;
    }
    documentState.updatedAt = nowTime();
  }
  ui.historyScope = { ...scope, label };
  recordActivity({ type: "edit", label: `文件夹“${previousLabel}”重命名为“${label}”`, scope: ui.historyScope });
  persist();
  ui.documentListRenderKey = ""; // 清除缓存，确保文件夹列表立即显示最新命名
  renderAll();
  try {
    await saveWorkspace({ throwOnError: true });
    showToast("文件夹名称已更新");
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    persist();
    renderAll();
    showToast(`重命名失败：${error.message}`);
    return false;
  }
};

const deleteCustomFolder = async (folderId) => {
  const record = customFolder(folderId);
  if (!record) return false;
  const rollbackState = clone(state);
  const scope = { type: "volume", id: folderId, label: record.label, moduleId: record.moduleId, viewId: record.viewId };
  snapshotVolume(scope, `文件夹“${record.label}”移入回收区之前的结构`);
  const folderIds = customFolderSubtreeIds(folderId);
  const folderRecords = clone(state.customFolders.filter((folder) => folderIds.has(folder.id)));
  const items = clone(itemsForModuleView(record.moduleId, record.viewId).filter(([, , options = {}]) => folderIds.has(options.customFolderId)));
  const treeDocumentIds = [...new Set(items.map(([id]) => id))];
  const hydratedDocumentIds = treeDocumentIds.filter((id) => state.documents[id]);
  const documents = Object.fromEntries(hydratedDocumentIds.map((id) => [id, clone(state.documents[id])]));
  const histories = Object.fromEntries(hydratedDocumentIds.map((id) => [id, clone(state.histories[id] ?? [])]));
  const conversationBindings = Object.fromEntries(hydratedDocumentIds.map((id) => [id, {
    boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === id).map((conversation) => conversation.id),
    referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(id)).map((conversation) => conversation.id),
  }]));
  state.trash.unshift(createTreeTrashEntry({
    id: uid("folder-trash"),
    title: record.label,
    documents,
    histories,
    moduleItems: { [record.moduleId]: items },
    customFolders: folderRecords,
    volumeHistories: Object.fromEntries([...folderIds].map((id) => [id, clone(state.volumeHistories[id] ?? [])])),
    structure: [{ type: "folder", title: record.label, children: items.map(([id, label]) => ({ type: "document", id, label })) }],
    conversationBindings,
  }));
  treeDocumentIds.forEach(removeDocumentFromWorkspaceState);
  removeDirectoryOrderEntries({ documentIds: treeDocumentIds, folderIds: [...folderIds] });
  state.customFolders = state.customFolders.filter((folder) => !folderIds.has(folder.id));
  state.expandedFolders = state.expandedFolders.filter((id) => !folderIds.has(id));
  for (const id of folderIds) {
    delete state.volumeHistories[id];
    clearCurrentVersionMetadata({ type: "volume", id });
  }
  if (!state.documents[state.activeDocument]) {
    state.activeDocument = Object.keys(state.documents).find((id) => id !== "library-trash") ?? "library-trash";
    state.activeModule = moduleForDocument(state.activeDocument);
  }
  elements.editor.dataset.document = "";
  rebuildProjectCompilationStatus();
  updateTrashIndexDocument();
  recordActivity({ type: "edit", label: `文件夹“${record.label}”已移入回收区`, destination: "trash" });
  persistExpandedFolderState();
  persist();
  renderAll();
  try {
    await saveWorkspace({ throwOnError: true });
    showToast(`文件夹“${record.label}”已移入回收站`);
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    persist();
    renderAll();
    showToast(`删除文件夹失败：${error.message}`);
    return false;
  }
};

const deleteTreeFolder = async ({ node, moduleId, viewId }) => {
  const rollbackState = clone(state);
  const selection = treeFolderDeleteSelection(node);
  const documentIds = selection.documentIds;
  const documentIdSet = new Set(documentIds);
  const items = clone((state.moduleItems[moduleId] ?? []).filter(([documentId]) => documentIdSet.has(documentId)));
  const hydratedDocumentIds = documentIds.filter((documentId) => state.documents[documentId]);
  const documents = Object.fromEntries(hydratedDocumentIds.map((documentId) => [documentId, clone(state.documents[documentId])]));
  const histories = Object.fromEntries(hydratedDocumentIds.map((documentId) => [documentId, clone(state.histories[documentId] ?? [])]));
  const customFolderIdSet = new Set(selection.customFolderIds);
  const customFolders = clone((state.customFolders ?? []).filter((folder) => customFolderIdSet.has(folder.id)));
  const conversationBindings = Object.fromEntries(hydratedDocumentIds.map((documentId) => [documentId, {
    boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === documentId).map((conversation) => conversation.id),
    referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(documentId)).map((conversation) => conversation.id),
  }]));
  snapshotVolume({ type: "volume", id: node.id, label: node.label, moduleId, viewId }, `文件夹“${node.label}”移入回收区之前的结构`);
  state.trash.unshift(createTreeTrashEntry({
    id: uid("folder-trash"),
    title: node.label,
    documents,
    histories,
    moduleItems: { [moduleId]: items },
    customFolders,
    volumeHistories: Object.fromEntries(selection.customFolderIds.map((folderId) => [folderId, clone(state.volumeHistories[folderId] ?? [])])),
    structure: [clone(node)],
    conversationBindings,
  }));
  documentIds.forEach(removeDocumentFromWorkspaceState);
  removeDirectoryOrderEntries({ documentIds, folderIds: [node.id, ...selection.customFolderIds] });
  state.customFolders = (state.customFolders ?? []).filter((folder) => !customFolderIdSet.has(folder.id));
  state.expandedFolders = (state.expandedFolders ?? []).filter((folderId) => folderId !== node.id && !customFolderIdSet.has(folderId));
  selection.customFolderIds.forEach((folderId) => {
    delete state.volumeHistories[folderId];
    clearCurrentVersionMetadata({ type: "volume", id: folderId });
  });
  if (!state.documents[state.activeDocument]) {
    state.activeDocument = Object.keys(state.documents).find((documentId) => documentId !== "library-trash") ?? "library-trash";
    state.activeModule = moduleForDocument(state.activeDocument);
  }
  elements.editor.dataset.document = "";
  rebuildProjectCompilationStatus();
  updateTrashIndexDocument();
  persistExpandedFolderState();
  persist();
  renderAll();
  try {
    await saveWorkspace({ throwOnError: true, forceFullState: true });
    showToast(`文件夹“${node.label}”已移入回收站`);
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    elements.editor.dataset.document = "";
    persist();
    renderAll();
    showToast(`删除文件夹失败：${error.message}`);
    return false;
  }
};

