const renameDocument = (documentId, nextName, { createHistory = true, sequenceNumber = 0 } = {}) => {
  const documentState = state.documents[documentId];
  if (!documentState) return;
  const moduleId = moduleForDocument(documentId);
  const viewId = itemWorkspaceView(moduleId, documentItem(documentId)?.item);
  const sequenceKind = sequencedDocumentKind(documentId, documentState);
  const currentSequenceNumber = sequenceKind
    ? effectiveSequencedDocumentNumber({ documentId, documentState, title: documentState.title })
    : 0;
  const renameSpec = sequenceKind
    ? sequencedDocumentRenameSpec({
      documentId,
      currentTitle: documentState.title,
      currentSequenceNumber,
      nextName,
      language: documentState.titleLanguage || state.structureLanguage || "zh-CN",
    })
    : null;
  const requestedSequenceNumber = sequenceKind
    ? Math.max(1, Number(sequenceNumber) || renameSpec?.sequenceNumber || currentSequenceNumber)
    : 0;
  const nextLabel = sequenceKind
    ? renameSpec.title
    : documentRenameTitle({ workspaceKind: state.workspaceKind, moduleId, viewId, documentId, currentTitle: documentState.title, nextName });
  if (!nextLabel) return false;
  if (sequenceKind && requestedSequenceNumber !== currentSequenceNumber) {
    const collision = itemsForModuleView(moduleId, viewId).some(([candidateId]) => (
      candidateId !== documentId
      && sequencedDocumentKind(candidateId, state.documents[candidateId]) === sequenceKind
      && effectiveSequencedDocumentNumber({ documentId: candidateId, documentState: state.documents[candidateId] }) === requestedSequenceNumber
    ));
    if (collision) {
      showToast(`第${requestedSequenceNumber}${sequenceKind === "chapter" ? "章" : "集"}已存在，请使用其他序号`);
      renderEditor();
      return false;
    }
  }
  if (nextLabel === documentState.title && (!sequenceKind || requestedSequenceNumber === currentSequenceNumber)) return false;
  if (createHistory) {
    snapshotDocument(documentId, `文档“${documentState.title}”重命名前的内容版本`);
    const volumeScope = volumeScopeForDocument(documentId);
    if (volumeScope) snapshotVolume(volumeScope, `${documentState.title}重命名前的分卷结构`);
    else snapshotStructure(moduleId, viewId, `${documentState.title}重命名前的分类结构`);
  }
  documentState.title = nextLabel;
  documentState.systemGeneratedTitle = false;
  if (sequenceKind) {
    delete documentState.customSequenceTitle;
    if (requestedSequenceNumber === sequencedDocumentNumber(documentId)) delete documentState.manualChapterNumber;
    else documentState.manualChapterNumber = requestedSequenceNumber;
  }
  documentState.updatedAt = nowTime();
  for (const items of Object.values(state.moduleItems)) {
    const item = items.find(([id]) => id === documentId);
    if (item) item[1] = sequenceKind
      ? sequencedDocumentLabel({ documentId, title: nextLabel, language: documentState.titleLanguage || state.structureLanguage || "zh-CN", documentState })
      : nextLabel;
  }
  if (state.workspaceKind === "notebook") state.moduleItems[moduleId] = sortNotebookChapterItems(state.moduleItems[moduleId], state.documents);
  rebuildProjectCompilationStatus();
  recordActivity({
    type: "edit",
    label: sequenceKind
      ? `${sequenceKind === "chapter" ? "章节" : "单集"}改为“${sequencedDocumentLabel({ documentId, title: nextLabel, language: documentState.titleLanguage || state.structureLanguage || "zh-CN", documentState })}”`
      : `文档重命名为“${nextLabel}”`,
    documentId,
  });
  persist();
  ui.documentListRenderKey = ""; // 清除缓存，确保文档列表立即显示最新命名
  renderAll();
  return true;
};

const deleteDocument = async (documentId) => {
  const documentState = state.documents[documentId];
  const locatedDocument = documentItem(documentId);
  if (!documentDeleteAllowed({
    documentId,
    moduleId: locatedDocument?.moduleId || documentState?.moduleId,
    workspaceKind: state.workspaceKind,
  })) return false;
  if (!documentState) {
    const orphan = orphanTreeReferenceTrashPayload({ documentId, located: locatedDocument, fallbackModuleId: state.activeModule });
    if (!orphan) return false;
    const rollbackState = clone(state);
    const viewId = itemWorkspaceView(orphan.moduleId, orphan.item);
    snapshotStructure(orphan.moduleId, viewId, `${orphan.title}移入回收区之前的目录结构`);
    state.trash.unshift(createTreeTrashEntry({
      id: uid("orphan-reference-trash"),
      title: orphan.title,
      documents: {},
      histories: {},
      moduleItems: orphan.moduleItems,
      structure: orphan.structure,
      missingContentReference: true,
    }));
    removeDocumentFromWorkspaceState(documentId);
    removeDirectoryOrderEntries({ documentIds: [documentId] });
    updateTrashIndexDocument();
    recordActivity({ type: "edit", label: `损坏目录引用“${orphan.title}”已移入回收区`, destination: "trash" });
    persist();
    renderAll();
    try {
      await saveWorkspace({ throwOnError: true, forceFullState: true });
      showToast(`“${orphan.title}”已移入回收站`);
      return true;
    } catch (error) {
      state = rollbackState;
      ensureStateSchema();
      persist();
      renderAll();
      showToast(`删除旧目录记录失败：${error.message}`);
      return false;
    }
  }
  const rollbackState = clone(state);
  const moduleId = moduleForDocument(documentId);
  const viewId = itemWorkspaceView(moduleId, documentItem(documentId)?.item);
  const volumeScope = volumeScopeForDocument(documentId);
  if (volumeScope) snapshotVolume(volumeScope, `${documentState.title}移入回收区之前的分卷结构`);
  else snapshotStructure(moduleId, viewId, `${documentState.title}移入回收区之前的分类结构`);
  state.trash.unshift(createFileTrashEntry({
    id: documentId,
    document: clone(documentState),
    history: clone(state.histories[documentId] ?? []),
    item: clone(itemsForModule(moduleId).find(([id]) => id === documentId) ?? [documentId, documentState.title]),
    moduleId,
    boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === documentId).map((conversation) => conversation.id),
    referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(documentId)).map((conversation) => conversation.id),
  }));
  delete state.documents[documentId];
  delete state.histories[documentId];
  if (state.documentConversationBindings) delete state.documentConversationBindings[documentId];
  for (const [id, items] of Object.entries(state.moduleItems)) state.moduleItems[id] = items.filter(([itemId]) => itemId !== documentId);
  removeDirectoryOrderEntries({ documentIds: [documentId] });
  for (const conversation of state.conversations) {
    if (conversation.boundDocumentId === documentId) conversation.boundDocumentId = null;
    conversation.references = (conversation.references ?? []).filter((id) => id !== documentId);
    synchronizeConversationReferenceContext(conversation, {
      cleared: !conversation.references?.length
        && !conversation.workspaceReferences?.length
        && !conversation.skillReferences?.length
        && !conversation.attachments?.length,
    });
  }
  const next = itemsForModule(moduleId)[0]?.[0] || Object.keys(state.documents)[0];
  state.activeDocument = next;
  state.activeModule = moduleForDocument(next);
  elements.editor.dataset.document = "";
  rebuildProjectCompilationStatus();
  updateTrashIndexDocument();
  recordActivity({ type: "edit", label: `“${documentState.title}”已移入回收区`, destination: "trash" });
  persist();
  renderAll();
  try {
    await saveWorkspace({ throwOnError: true, forceFullState: true });
    showToast(`“${documentState.title}”已移入回收站`);
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    elements.editor.dataset.document = "";
    persist();
    renderAll();
    showToast(`删除文档失败：${error.message}`);
    return false;
  }
};

const workspaceOperationContentHtml = (documentId, content) => {
  const moduleId = moduleForDocument(documentId);
  const viewId = itemWorkspaceView(moduleId, documentItem(documentId)?.item);
  const source = String(content ?? "").trim();
  if (!source) return "";
  return moduleId === "manuscript" && viewId === "novel"
    ? proseToHtml(source)
    : structuredMarkdownToHtml(source);
};

const replaceDocumentText = (documentId, find, replacement, replaceAll = false) => {
  const documentState = state.documents[documentId];
  if (!documentState) throw new Error("目标文档已不存在");
  const beforeContent = stripHtml(documentState.html ?? "");
  if (replaceAll && !/\r|\n/u.test(find)) {
    const expectedOccurrences = beforeContent.split(find).length - 1;
    const patchResult = applyDocumentPatchPlan(beforeContent, [{
      type: "replace_all_exact",
      editId: `workspace-replace-${documentId}`,
      original: find,
      content: replacement,
      expectedOccurrences,
    }]);
    documentState.html = applyExactTextEditsToDocumentHtml(documentState.html ?? "", {
      edits: [{ editId: `workspace-replace-${documentId}`, kind: "replace_all_exact", originalText: find, replacementText: replacement, expectedOccurrences }],
    });
    return { replaced: expectedOccurrences, ...patchResult };
  }
  const container = document.createElement("div");
  container.innerHTML = documentState.html ?? "";
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  let replaced = 0;
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (!node.nodeValue.includes(find)) continue;
    if (replaceAll) {
      const parts = node.nodeValue.split(find);
      replaced += parts.length - 1;
      node.nodeValue = parts.join(replacement);
    } else {
      node.nodeValue = node.nodeValue.replace(find, replacement);
      replaced = 1;
      break;
    }
  }
  if (!replaced && /\r|\n/.test(find)) {
    let searchFrom = 0;
    while (true) {
      const blocks = Array.from(container.children);
      const blockTexts = blocks.map((block) => Array.from(block.childNodes)
        .map((node) => node.nodeName === "BR" ? "\n" : node.textContent ?? "")
        .join(""));
      const range = findWorkspaceTextBlockRange({ blocks: blockTexts, find, startIndex: searchFrom });
      if (!range) break;
      const replacementContainer = document.createElement("div");
      replacementContainer.innerHTML = workspaceOperationContentHtml(documentId, replacement);
      const replacementNodes = Array.from(replacementContainer.childNodes);
      const anchor = blocks[range.start];
      if (replacementNodes.length) anchor.before(...replacementNodes);
      blocks.slice(range.start, range.end + 1).forEach((block) => block.remove());
      replaced += 1;
      if (!replaceAll) break;
      searchFrom = range.start + replacementNodes.length;
    }
  }
  if (!replaced) throw new Error(`“${documentState.title}”中没有找到需要替换的原文`);
  documentState.html = container.innerHTML;
  const afterContent = stripHtml(documentState.html ?? "");
  const start = beforeContent.indexOf(find);
  return {
    replaced,
    content: afterContent,
    beforeRevision: contentRevision(beforeContent),
    afterRevision: contentRevision(afterContent),
    changeSet: start >= 0 ? [{ editId: `workspace-replace-${documentId}`, start, end: start + find.length, before: find, after: replacement }] : [],
  };
};

const nextOperationDocumentId = ({ moduleId, viewId, title }) => {
  const number = Number(String(title).match(/第\s*(\d+)\s*[章集卷]/)?.[1] ?? 0);
  if (moduleId === "manuscript" && viewId === "novel") {
    const next = number || Math.max(0, ...itemsForModule("manuscript").map(([id]) => Number(id.match(/^chapter-(\d+)$/)?.[1] ?? 0))) + 1;
    return `chapter-${next}`;
  }
  if (moduleId === "manuscript" && viewId === "script") {
    const next = number || Math.max(0, ...itemsForModule("manuscript").map(([id]) => Number(id.match(/^script-episode-(\d+)$/)?.[1] ?? 0))) + 1;
    return `script-episode-${next}`;
  }
  if (moduleId === "manuscript" && viewId === "prompts") {
    if (/视觉资产|图片资产/.test(title)) return "prompt-visual-assets";
    const group = /全景调度|站位|空间调度/.test(title) ? "panorama" : "video";
    const pattern = new RegExp(`^prompt-${group}-(\\d+)$`);
    const next = number || Math.max(0, ...itemsForModule("manuscript").map(([id]) => Number(id.match(pattern)?.[1] ?? 0))) + 1;
    return `prompt-${group}-${next}`;
  }
  if (moduleId === "outline" && viewId === "novel" && /全集大纲/.test(title)) return "outline-series";
  if (moduleId === "outline" && viewId === "script" && /全集大纲/.test(title)) return "script-outline-series";
  if (moduleId === "outline" && viewId === "novel" && /章纲/.test(title)) {
    const next = number || Math.max(0, ...itemsForModule("outline").map(([id]) => Number(id.match(/^outline-chapter-(\d+)$/)?.[1] ?? 0))) + 1;
    return `outline-chapter-${next}`;
  }
  if (moduleId === "outline" && viewId === "novel" && /卷纲/.test(title)) {
    const next = number || Math.max(0, ...itemsForModule("outline").map(([id]) => Number(id.match(/^outline-volume-(\d+)$/)?.[1] ?? 0))) + 1;
    return `outline-volume-${next}`;
  }
  if (moduleId === "outline" && viewId === "script" && /集纲|剧集大纲/.test(title)) {
    const next = number || Math.max(0, ...itemsForModule("outline").map(([id]) => Number(id.match(/^script-outline-episode-(\d+)$/)?.[1] ?? 0))) + 1;
    return `script-outline-episode-${next}`;
  }
  return `${moduleId}-${viewId}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
};

const workspaceOperationFolderRecord = ({ moduleId, viewId, name, parentFolderId = "" }) => {
  const label = String(name || "").trim();
  if (!label) throw new Error("文件夹名称不能为空");
  const duplicate = (state.customFolders ?? []).find((folder) => (
    folder.moduleId === moduleId
    && folder.viewId === viewId
    && String(folder.label || "").toLocaleLowerCase() === label.toLocaleLowerCase()
  ));
  if (duplicate) return { record: duplicate, created: false };
  const virtualItem = itemsForModuleView(moduleId, viewId).find(([, , options = {}]) => (
    !options.customFolderId
    && options.folderId
    && String(options.folderLabel || options.volumeFolder || "").toLocaleLowerCase() === label.toLocaleLowerCase()
  ));
  if (virtualItem) {
    const options = virtualItem[2] ?? {};
    return {
      record: {
        id: options.folderId,
        label,
        moduleId,
        viewId,
        parentOptions: { ...options, folderId: options.folderId, folderLabel: label, volumeFolder: options.volumeFolder || label },
        folderPath: options.volumeFolder || label,
      },
      created: false,
    };
  }
  const parent = parentFolderId ? customFolder(parentFolderId) : null;
  if (parentFolderId && (!parent || parent.moduleId !== moduleId || parent.viewId !== viewId)) {
    throw new Error("目标父文件夹已经变化，请重新生成操作计划");
  }
  const id = uid("custom-folder");
  const parentOptions = parent ? { ...(parent.parentOptions ?? {}) } : {
    workspaceView: viewId,
    contextDomain: ["script", "prompts"].includes(viewId) ? "script" : "novel",
  };
  delete parentOptions.customFolderId;
  delete parentOptions.customFolderLabel;
  delete parentOptions.customFolderPath;
  if (moduleId === "manuscript" && viewId === "novel") Object.assign(parentOptions, {
    workspaceView: "novel",
    contextDomain: "novel",
    folderId: id,
    folderLabel: label,
    volumeFolder: label,
    treeGroup: "volume",
  });
  const record = {
    id,
    label,
    systemGeneratedLabel: false,
    labelLanguage: normalizeStructureLanguage(globalUiPreferences.uiLanguage),
    moduleId,
    viewId,
    parentLocationId: parent?.id ?? `${moduleId}:${viewId}:root`,
    parentLabel: parent?.label ?? moduleView(moduleId, viewId)?.label ?? MODULES.find((item) => item.id === moduleId)?.label ?? moduleId,
    parentOptions,
    folderPath: [parent?.folderPath, label].filter(Boolean).join("/"),
    createdAt: new Date().toISOString(),
  };
  state.customFolders ??= [];
  state.expandedFolders ??= [];
  state.customFolders.push(record);
  state.expandedFolders.push(id);
  return { record, created: true };
};

const workspaceOperationFolderOptions = (record) => ({
  ...(record.parentOptions ?? {}),
  workspaceView: record.viewId,
  contextDomain: ["script", "prompts"].includes(record.viewId) ? "script" : "novel",
  ...(customFolder(record.id) ? {
    customFolderId: record.id,
    customFolderLabel: record.label,
    customFolderPath: customFolderPathForRecord(record.id) || record.label,
  } : {}),
  placementOverride: true,
});

const prepareWorkspaceOperationFolders = (plan) => {
  for (const operation of plan.operations) {
    if (operation.type !== "folder.ensure") continue;
    const prepared = workspaceOperationFolderRecord(operation);
    operation.folderId = prepared.record.id;
    operation.folderLabel = prepared.record.label;
    operation.created = prepared.created;
  }
  for (const operation of plan.operations) {
    if (!["document.create", "document.move"].includes(operation.type) || !operation.folderLabel) continue;
    const prepared = workspaceOperationFolderRecord({
      moduleId: operation.moduleId,
      viewId: operation.viewId,
      name: operation.folderLabel,
    });
    Object.assign(operation, workspaceOperationFolderOptions(prepared.record), { folderLabel: prepared.record.label });
    if (operation.moduleId === "manuscript" && operation.viewId === "novel") {
      operation.folderId = prepared.record.id;
      operation.volumeFolder = operation.volumeFolder || prepared.record.label;
    } else {
      delete operation.folderId;
      delete operation.volumeFolder;
    }
  }
};

const workspaceOperationFolderExists = (folderId) => {
  if (customFolder(folderId)) return true;
  return Object.values(state.moduleItems ?? {}).some((items) => items.some(([, , options = {}]) => (
    options.folderId === folderId || options.customFolderId === folderId
  )));
};

const renameFolderFromWorkspaceOperation = (folderId, nextName) => {
  const label = String(nextName || "").trim();
  if (!label) throw new Error("文件夹名称不能为空");
  const record = customFolder(folderId);
  if (record) {
    const duplicate = state.customFolders.some((folder) => folder.id !== folderId
      && folder.moduleId === record.moduleId
      && folder.viewId === record.viewId
      && String(folder.label || "").toLocaleLowerCase() === label.toLocaleLowerCase());
    if (duplicate) throw new Error("当前目录已经存在同名文件夹");
    if (record.label === label) return 0;
    record.label = label;
    record.systemGeneratedLabel = false;
    if (record.moduleId === "manuscript" && record.viewId === "novel") {
      Object.assign(record.parentOptions ?? (record.parentOptions = {}), { folderLabel: label, volumeFolder: label });
    }
    const folderIds = customFolderSubtreeIds(folderId);
    for (const folder of state.customFolders) {
      if (folderIds.has(folder.id)) folder.folderPath = customFolderPathForRecord(folder.id);
      if (folder.parentLocationId === folderId) folder.parentLabel = label;
    }
    let changedDocuments = 0;
    for (const item of itemsForModuleView(record.moduleId, record.viewId)) {
      const options = item[2] ?? (item[2] = {});
      if (!folderIds.has(options.customFolderId)) continue;
      const owningFolder = customFolder(options.customFolderId);
      options.customFolderPath = customFolderPathForRecord(options.customFolderId);
      if (options.customFolderId === folderId) options.customFolderLabel = label;
      if (options.customFolderId === folderId && record.moduleId === "manuscript" && record.viewId === "novel") {
        options.folderLabel = label;
        options.volumeFolder = label;
      }
      const documentState = state.documents[item[0]];
      if (!documentState) continue;
      documentState.customFolderName = owningFolder?.label ?? documentState.customFolderName;
      documentState.customFolderPath = options.customFolderPath;
      if (options.customFolderId === folderId && record.moduleId === "manuscript" && record.viewId === "novel") {
        documentState.volumeLabel = label;
        documentState.volumeFolder = label;
      }
      documentState.updatedAt = nowTime();
      changedDocuments += 1;
    }
    return Math.max(1, changedDocuments);
  }

  const matching = [];
  for (const [moduleId, items] of Object.entries(state.moduleItems ?? {})) {
    for (const item of items ?? []) {
      const options = item?.[2] ?? {};
      if (options.folderId === folderId) matching.push({ moduleId, item, options });
    }
  }
  if (!matching.length) throw new Error("目标文件夹已经变化，请重新生成操作计划");
  for (const { item, options } of matching) {
    options.folderLabel = label;
    options.volumeFolder = label;
    const documentState = state.documents[item[0]];
    if (documentState) Object.assign(documentState, { volumeLabel: label, volumeFolder: label, updatedAt: nowTime() });
  }
  return matching.length;
};

const createDocumentFromOperation = (operation) => {
  const { moduleId, viewId, title } = operation;
  const items = itemsForModuleView(moduleId, viewId);
  const defaults = newDocumentTreeOptions({ moduleId, viewId, items, documents: state.documents, activeDocumentId: state.activeDocument });
  const options = {
    ...defaults,
    workspaceView: viewId,
    ...(operation.treeGroup ? { treeGroup: operation.treeGroup } : {}),
    ...(operation.folderId ? { folderId: operation.folderId } : {}),
    ...(operation.folderLabel ? { folderLabel: operation.folderLabel } : {}),
    ...(operation.volumeFolder ? { volumeFolder: operation.volumeFolder } : {}),
    ...(operation.customFolderId ? {
      customFolderId: operation.customFolderId,
      customFolderLabel: operation.customFolderLabel,
      customFolderPath: operation.customFolderPath,
      placementOverride: true,
    } : {}),
  };
  if (["script", "prompts"].includes(viewId)) options.contextDomain = "script";
  const id = nextOperationDocumentId(operation);
  if (state.documents[id]) throw new Error(`“${title}”的目标文档已经存在`);
  const documentTitle = sequencedDocumentKind(id)
    ? freeDocumentTitle({ documentId: id, title, language: state.structureLanguage || "zh-CN" })
    : title;
  const label = sequencedDocumentKind(id)
    ? sequencedDocumentLabel({ documentId: id, title: documentTitle, language: state.structureLanguage || "zh-CN" })
    : title;
  state.moduleItems[moduleId] ??= [];
  state.moduleItems[moduleId].push([id, label, options]);
  state.documents[id] = {
    title: documentTitle,
    html: stripMatchingLeadingHeadingHtml(workspaceOperationContentHtml(id, operation.content), [documentTitle, label]),
    updatedAt: nowTime(),
    moduleId,
    workspaceView: viewId,
    contextDomain: options.contextDomain ?? "novel",
    treeGroup: options.treeGroup,
    ...(options.volumeFolder ? { volumeFolder: options.volumeFolder, volumeLabel: options.folderLabel } : {}),
    ...(options.customFolderId ? {
      customFolderId: options.customFolderId,
      customFolderName: options.customFolderLabel,
      customFolderPath: options.customFolderPath,
      placementOverride: true,
    } : {}),
  };
  state.histories[id] = [];
  return id;
};

const removeDocumentFromWorkspaceState = (documentId) => {
  delete state.documents[documentId];
  delete state.histories[documentId];
  if (state.documentConversationBindings) delete state.documentConversationBindings[documentId];
  state.pendingInlineEdits = (state.pendingInlineEdits ?? []).filter((record) => record.documentId !== documentId);
  for (const [inlineEditId, record] of ui.inlineEdits) if (record.documentId === documentId) ui.inlineEdits.delete(inlineEditId);
  for (const [moduleId, items] of Object.entries(state.moduleItems)) state.moduleItems[moduleId] = items.filter(([id]) => id !== documentId);
  for (const conversation of state.conversations) {
    if (conversation.boundDocumentId === documentId) conversation.boundDocumentId = null;
    conversation.references = (conversation.references ?? []).filter((id) => id !== documentId);
    synchronizeConversationReferenceContext(conversation, {
      cleared: !conversation.references?.length
        && !conversation.workspaceReferences?.length
        && !conversation.skillReferences?.length
        && !conversation.attachments?.length,
    });
  }
};

const scopeOperationDocumentIds = (operation) => {
  const matches = [];
  const modules = operation.scopeType === "project" ? operation.modules : [operation.moduleId];
  for (const moduleId of modules.filter(Boolean)) {
    for (const [id, , options = {}] of state.moduleItems[moduleId] ?? []) {
      if (id === "library-trash" || options.alias || !state.documents[id]) continue;
      if (operation.scopeType === "view" && itemWorkspaceView(moduleId, [id, state.documents[id].title, options]) !== operation.viewId) continue;
      if (operation.scopeType === "volume" && options.folderId !== operation.volumeId) continue;
      matches.push(id);
    }
  }
  return [...new Set(matches)];
};

const moveDocumentsToTreeTrash = (documentIds, title) => {
  const ids = [...new Set(documentIds)].filter((id) => id !== "library-trash" && state.documents[id]);
  if (!ids.length) return 0;
  const idSet = new Set(ids);
  const documents = Object.fromEntries(ids.map((id) => [id, clone(state.documents[id])]));
  const histories = Object.fromEntries(ids.map((id) => [id, clone(state.histories[id] ?? [])]));
  const moduleItems = Object.fromEntries(Object.entries(state.moduleItems)
    .map(([moduleId, items]) => [moduleId, clone(items.filter(([id]) => idSet.has(id)))])
    .filter(([, items]) => items.length));
  const conversationBindings = Object.fromEntries(ids.map((id) => [id, {
    boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === id).map((conversation) => conversation.id),
    referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(id)).map((conversation) => conversation.id),
  }]));
  const structure = Object.entries(moduleItems).map(([moduleId, items]) => ({
    type: "folder",
    title: MODULES.find((module) => module.id === moduleId)?.label ?? moduleId,
    children: buildDocumentTree({ moduleId, viewId: state.moduleViews[moduleId] ?? "novel", items, documents, folders: state.customFolders, workspaceKind: state.workspaceKind }),
  }));
  state.trash.unshift(createTreeTrashEntry({ id: uid("tree-trash"), title, documents, histories, moduleItems, structure, conversationBindings }));
  ids.forEach(removeDocumentFromWorkspaceState);
  return ids.length;
};

const deleteDirectorySelection = async (context) => {
  if (!context?.tokens?.length) return false;
  const requestedDocumentIds = [...new Set(context.documentIds ?? directoryDocumentIdsForTokens(context.tokens, context))];
  const protectedDocumentIds = requestedDocumentIds.filter((id) => {
      const located = documentItem(id);
      return !documentDeleteAllowed({
        documentId: id,
        moduleId: located?.moduleId || state.documents[id]?.moduleId || context.moduleId,
        workspaceKind: state.workspaceKind,
      });
    });
  if (protectedDocumentIds.length) {
    showToast("所选目录包含不能删除的系统文档，已停止本次删除");
    return false;
  }
  const documentIds = requestedDocumentIds;
  const hydratedDocumentIds = documentIds.filter((id) => state.documents[id]);
  const orphanDocumentIds = documentIds.filter((id) => !state.documents[id]);
  const hasOrphanReferences = orphanDocumentIds.length > 0;
  const documentIdSet = new Set(documentIds);
  const customFolderIds = new Set();
  for (const token of context.tokens) {
    if (!token.startsWith("folder:")) continue;
    const folderId = token.slice("folder:".length);
    if (customFolder(folderId)) {
      for (const id of customFolderSubtreeIds(folderId)) customFolderIds.add(id);
      continue;
    }
    if (context.moduleId === "manuscript" && context.viewId === "novel") {
      const selection = manuscriptVolumeSelection(folderId);
      selection.customFolders.forEach((folder) => customFolderIds.add(folder.id));
    }
  }
  const folderRecords = clone(state.customFolders.filter((folder) => customFolderIds.has(folder.id)));
  if (!documentIds.length && !folderRecords.length) {
    showToast("所选系统目录没有可删除的内容");
    return false;
  }
  const rollbackState = clone(state);
  ui.operationApplying = true;
  try {
    const documents = Object.fromEntries(hydratedDocumentIds.map((id) => [id, clone(state.documents[id])]));
    const histories = Object.fromEntries(hydratedDocumentIds.map((id) => [id, clone(state.histories[id] ?? [])]));
    const moduleItems = Object.fromEntries(Object.entries(state.moduleItems)
      .map(([moduleId, items]) => [moduleId, clone(items.filter(([id]) => documentIdSet.has(id)))])
      .filter(([, items]) => items.length));
    const conversationBindings = Object.fromEntries(hydratedDocumentIds.map((id) => [id, {
      boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === id).map((conversation) => conversation.id),
      referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(id)).map((conversation) => conversation.id),
    }]));
    const structure = [{
      type: "folder",
      title: `批量删除的 ${context.itemCount ?? context.tokens.length} 个目录项`,
      children: buildDocumentTree({
        moduleId: context.moduleId,
        viewId: context.viewId,
        items: (moduleItems[context.moduleId] ?? []),
        documents,
        folders: folderRecords,
        workspaceKind: state.workspaceKind,
      }),
    }];
    state.trash.unshift(createTreeTrashEntry({
      id: uid("directory-batch-trash"),
      title: `批量删除 ${context.itemCount ?? context.tokens.length} 项`,
      documents,
      histories,
      moduleItems,
      customFolders: folderRecords,
      volumeHistories: Object.fromEntries([...customFolderIds].map((id) => [id, clone(state.volumeHistories[id] ?? [])])),
      structure,
      conversationBindings,
      missingContentReferenceIds: orphanDocumentIds,
    }));
    documentIds.forEach(removeDocumentFromWorkspaceState);
    state.customFolders = state.customFolders.filter((folder) => !customFolderIds.has(folder.id));
    state.expandedFolders = state.expandedFolders.filter((id) => !customFolderIds.has(id));
    for (const id of customFolderIds) {
      delete state.volumeHistories[id];
      clearCurrentVersionMetadata({ type: "volume", id });
    }
    removeDirectoryOrderEntries({ documentIds, folderIds: [...customFolderIds] });
    if (!state.documents[state.activeDocument]) {
      state.activeDocument = Object.keys(state.documents).find((id) => id !== "library-trash") ?? "library-trash";
      state.activeModule = moduleForDocument(state.activeDocument);
    }
    resetDirectorySelection();
    elements.editor.dataset.document = "";
    rebuildProjectCompilationStatus();
    updateTrashIndexDocument();
    recordActivity({ type: "edit", label: `批量删除 ${context.itemCount ?? context.tokens.length} 个目录项`, destination: "trash" });
    persistExpandedFolderState();
    persist();
    await saveWorkspace({ throwOnError: true, forceFullState: hasOrphanReferences });
    renderAll();
    showToast(`已将 ${documentIds.length} 个文档${folderRecords.length ? `和 ${folderRecords.length} 个文件夹` : ""}移入回收站`);
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    persist();
    renderAll();
    showToast(`批量删除失败：${error.message}`);
    return false;
  } finally {
    ui.operationApplying = false;
  }
};

const snapshotWorkspaceOperationPlan = (plan) => {
  const targets = [];
  const instructedTarget = historyTargetForBackupScope(plan.backupScope);
  if (instructedTarget) targets.push(instructedTarget);
  for (const operation of plan.operations) {
    if (operation.type === "folder.ensure") {
      targets.push(historyTargetForDocument(null, {
        moduleId: operation.moduleId,
        viewId: operation.viewId,
        structural: true,
      }));
      continue;
    }
    if (operation.type === "folder.rename") {
      const record = customFolder(operation.folderId);
      if (record) targets.push(historyTargetForDocument(null, {
        moduleId: record.moduleId,
        viewId: record.viewId,
        volumeId: record.id,
        structural: true,
      }));
      continue;
    }
    if (["document.replace_text", "document.replace_content", "document.append_content", "document.clear"].includes(operation.type)) {
      targets.push(historyTargetForDocument(operation.documentId));
      continue;
    }
    if (operation.type === "scope.clear") {
      if (operation.scopeType === "project") {
        targets.push({ scopeType: "project" });
      } else {
        targets.push({
          scopeType: operation.scopeType,
          moduleId: operation.moduleId,
          viewId: operation.viewId,
          volumeId: operation.volumeId,
          structural: true,
        });
      }
      continue;
    }
    if (!["document.create", "document.rename", "document.delete", "document.move", "document.reorder"].includes(operation.type)) continue;
    if (operation.documentId) targets.push(historyTargetForDocument(operation.documentId, { structural: true }));
    if (operation.type === "document.create" || operation.type === "document.move") {
      targets.push(historyTargetForDocument(null, {
        moduleId: operation.moduleId,
        viewId: operation.viewId,
        volumeId: operation.folderId,
        structural: true,
      }));
    }
  }
  snapshotAiWriteHistory(targets, plan.intent || plan.summary || "内容修改", {
    operations: plan.operations,
    documentReason: "神思生成或修改内容落盘前的完整文档",
  });
};

const currentDocumentRevision = (documentId) => {
  return formalDocumentWriteRevision({
    documentId,
    document: state.documents[documentId] ?? null,
    item: documentItem(documentId)?.item ?? null,
  });
};

const historyScopeFromOperation = (operation) => {
  if (operation.scopeType === "document") return { type: "document", id: operation.scopeId };
  if (operation.scopeType === "volume") return { type: "volume", id: operation.scopeId };
  if (operation.scopeType === "view") {
    const [moduleId, viewId] = operation.scopeId.split(":");
    return { type: "view", id: operation.scopeId, moduleId, viewId };
  }
  if (operation.scopeType === "module") return { type: "module", id: operation.scopeId };
  return { type: "project", id: "project" };
};

const validateWorkspaceOperationPlan = (plan) => {
  if (!plan?.operations?.length) throw new Error("操作计划为空");
  if (!workspaceOperationConfirmationIsCurrent(plan, { workspaceRevision: workspaceOperationStateRevision() })) {
    throw new Error("操作计划生成后，操作内容或工作区结构已经变化；旧确认已失效，请重新发送指令");
  }
  for (const operation of plan.operations) {
    if (operation.documentId && !state.documents[operation.documentId]) throw new Error("操作计划中的目标文档已经变化，请重新发送指令");
    if (operation.documentId === "library-trash") throw new Error("回收站索引不能由对话操作修改");
    if (operation.documentId && operation.expectedRevision && currentDocumentRevision(operation.documentId) !== operation.expectedRevision) {
      throw new Error(`“${state.documents[operation.documentId]?.title ?? operation.documentId}”在计划生成后已被修改，请重新生成操作计划`);
    }
    if (operation.type === "folder.rename" && !workspaceOperationFolderExists(operation.folderId)) {
      throw new Error("操作计划中的目标文件夹已经变化，请重新发送指令");
    }
    if (operation.type === "document.move") {
      const locations = Object.values(state.moduleItems).filter((items) => items.some(([id]) => id === operation.documentId));
      if (locations.length > 1) throw new Error("同源引用文档不能直接移动，请改为移动其正式来源");
    }
    for (const seedDocument of operation.initialDocuments ?? []) {
      if (!seedDocument.sourceDocumentId) continue;
      if (!state.documents[seedDocument.sourceDocumentId]) throw new Error("创建计划中的初始资料来源已经不存在，请重新发送指令");
      if (seedDocument.sourceExpectedRevision
        && currentDocumentRevision(seedDocument.sourceDocumentId) !== seedDocument.sourceExpectedRevision) {
        throw new Error(`初始资料“${state.documents[seedDocument.sourceDocumentId]?.title || seedDocument.sourceDocumentId}”在确认前已变化，请重新生成创建计划`);
      }
    }
  }
  const proseViolations = workspaceProseMutationViolations({
    plan,
    documentTexts: Object.fromEntries(Object.entries(state.documents)
      .map(([documentId, documentState]) => [documentId, stripHtml(documentState?.html ?? "")])),
    documentLocations: workspaceOperationInventory(),
    absoluteTerms: projectAbsoluteBannedTerms(),
  });
  // Deterministic prose findings are advisory diagnostics. They must never
  // turn Chat/Agent document permissions into a hidden write barrier.
  if (proseViolations.length) plan.advisoryProseFindings = proseViolations.slice(0, 20);
};

const applyWorkspaceOperationPlan = async (messageId, { automatic = false, confirmed = false } = {}) => {
  const message = state.messages.find((item) => item.id === messageId && item.role === "assistant");
  const plan = message?.workspacePlan;
  if (!message || !plan || plan.status !== "waiting_confirm") return false;
  const requiresConfirmation = workspacePlanRequiresConfirmation(plan);
  if (automatic && requiresConfirmation && !confirmed) return false;
  if ((!automatic && ui.generating) || ui.operationApplying) {
    showToast("当前有任务正在修改上下文，请等待完成后再执行操作计划");
    return false;
  }
  if (requiresConfirmation && (!automatic || confirmed)) {
    plan.confirmation.status = "confirmed";
    plan.confirmation.confirmedAt = new Date().toISOString();
  }
  ui.operationApplying = true;
  const rollbackState = clone(state);
  const sourceWorkspace = currentConversationWorkspace();
  const sourceConversation = activeConversation();
  const sourceConversationId = sourceConversation?.id || "";
  const sourceMessages = sourceConversation ? conversationMessagesForTaskState(sourceConversation) : state.messages;
  const sourceCandidateState = sourceConversation ? conversationCandidateState(sourceConversation) : state;
  let operationSubmissionStarted = false;
  let operationDiskCommitted = false;
  try {
    validateWorkspaceOperationPlan(plan);
    plan.status = "applying";
    renderMessages();
    const projectOperation = plan.operations.find((operation) => operation.type.startsWith("project.") || operation.type === "notebook.create");
    if (projectOperation) {
      await refreshProjects();
      const target = ui.projects.find((project) => project.name === projectOperation.projectName);
      let success = false;
      const initialDocuments = (projectOperation.initialDocuments ?? []).map((initialDocument) => ({
        ...clone(initialDocument),
        content: String(initialDocument.content || (initialDocument.sourceDocumentId
          ? htmlToMarkdown(state.documents[initialDocument.sourceDocumentId]?.html || "")
            || String(state.documents[initialDocument.sourceDocumentId]?.markdown || "")
          : "")).trim(),
      })).filter((initialDocument) => initialDocument.content);
      const creationOptions = {
        operationId: plan.id,
        creationRequirements: projectOperation.creationRequirements,
        initialDocuments,
      };
      if (projectOperation.type === "project.create") success = await createProject(projectOperation.name, creationOptions);
      else if (projectOperation.type === "notebook.create") success = await createNotebook(projectOperation.name, creationOptions);
      else if (!target) throw new Error("目标作品已不存在");
      else if (projectOperation.type === "project.rename") success = await renameProject(target, projectOperation.name);
      else if (projectOperation.type === "project.switch") success = await switchProject(target);
      else if (projectOperation.type === "project.delete") success = await deleteProject(target);
      if (!success) {
        const creationPending = ["project.create", "notebook.create"].includes(projectOperation.type);
        throw Object.assign(new Error(creationPending ? "新工作区尚未完成首次保存；可用同一计划安全重试" : "作品操作未完成"), {
          code: creationPending ? "WORKSPACE_CREATION_FINALIZATION_PENDING" : "WORKSPACE_OPERATION_FAILED",
        });
      }
      const creationOperation = ["project.create", "notebook.create"].includes(projectOperation.type);
      if (creationOperation) {
        plan.status = "applied";
        plan.appliedAt = nowTime();
        message.content = projectOperation.type === "notebook.create" ? "笔记本创建及明确初始资料写入已完成。" : "作品创建及明确初始资料写入已完成。";
        message.execution = { ...(message.execution ?? {}), status: "complete", strength: "operation", result: message.content };
        const sourceCompletionSaved = await savePinnedConversationCompletion({
          workspaceKind: sourceWorkspace.workspaceKind,
          workspacePath: sourceWorkspace.workspacePath,
          conversationId: sourceConversationId,
          messages: sourceMessages,
          candidateState: sourceCandidateState,
        });
        if (!sourceCompletionSaved) throw Object.assign(new Error("新工作区已创建，但源对话的完成回执尚未保存；重试将复用同一创建任务，不会重复新建"), {
          code: "WORKSPACE_CREATION_FINALIZATION_PENDING",
        });
      } else {
        const retainedMessage = state.messages.find((item) => item.id === messageId);
        if (retainedMessage?.workspacePlan) {
          retainedMessage.workspacePlan.status = "applied";
          retainedMessage.content = "作品操作已完成。";
          retainedMessage.execution = { ...(retainedMessage.execution ?? {}), status: "complete", strength: "operation", result: "作品操作已完成" };
          persist();
        }
      }
      renderAll();
      ui.operationApplying = false;
      return true;
    }
    snapshotWorkspaceOperationPlan(plan);
    prepareWorkspaceOperationFolders(plan);
    let changed = 0;
    let movedToTrash = false;
    const processedAtomicTextDocuments = new Set();
    for (const operation of plan.operations) {
      if (operation.type === "folder.ensure") {
        if (operation.created) changed += 1;
      } else if (operation.type === "folder.rename") {
        renameFolderFromWorkspaceOperation(operation.folderId, operation.name);
        changed += 1;
      } else if (operation.type === "document.create") {
        operation.documentId = createDocumentFromOperation(operation);
        changed += 1;
      } else if (operation.type === "document.rename") {
        const documentState = state.documents[operation.documentId];
        let label = operation.title;
        if (moduleForDocument(operation.documentId) === "manuscript") {
          const number = Number(operation.documentId.match(/\d+/)?.[0] ?? 1);
          const unit = operation.documentId.startsWith("script-episode-") ? "集" : "章";
          label = `第${number}${unit}　${operation.title.replace(/^第.+?[章集][　 ]*/, "")}`;
        }
        documentState.title = label;
        for (const items of Object.values(state.moduleItems)) {
          const item = items.find(([id]) => id === operation.documentId);
          if (item) item[1] = label;
        }
        changed += 1;
      } else if (operation.type === "document.replace_text") {
        if (processedAtomicTextDocuments.has(operation.documentId)) continue;
        const atomicOperations = plan.operations.filter((candidate) => candidate.type === "document.replace_text"
          && candidate.documentId === operation.documentId
          && candidate.replaceAll === true
          && !/\r|\n/u.test(candidate.find));
        let patchResult;
        if (atomicOperations.length > 1) {
          const beforeContent = stripHtml(state.documents[operation.documentId].html ?? "");
          const edits = atomicOperations.map((candidate, index) => ({
            editId: `workspace-replace-${operation.documentId}-${index + 1}`,
            kind: "replace_all_exact",
            originalText: candidate.find,
            replacementText: candidate.replace,
            expectedOccurrences: beforeContent.split(candidate.find).length - 1,
          }));
          patchResult = applyDocumentPatchPlan(beforeContent, edits.map((edit) => ({
            type: "replace_all_exact",
            editId: edit.editId,
            original: edit.originalText,
            content: edit.replacementText,
            expectedOccurrences: edit.expectedOccurrences,
          })));
          state.documents[operation.documentId].html = applyExactTextEditsToDocumentHtml(state.documents[operation.documentId].html ?? "", { edits });
          processedAtomicTextDocuments.add(operation.documentId);
          changed += atomicOperations.length;
        } else {
          patchResult = replaceDocumentText(operation.documentId, operation.find, operation.replace, operation.replaceAll);
          changed += 1;
        }
        annotateLatestDocumentHistory(operation.documentId, {
          changeSet: patchResult.changeSet,
          afterContent: patchResult.content,
        });
      } else if (operation.type === "document.replace_content") {
        state.documents[operation.documentId].html = preserveProtectedDocumentMedia({
          previousHtml: state.documents[operation.documentId].html,
          nextHtml: workspaceOperationContentHtml(operation.documentId, operation.content),
        });
        changed += 1;
      } else if (operation.type === "document.append_content") {
        const addition = workspaceOperationContentHtml(operation.documentId, operation.content);
        state.documents[operation.documentId].html = `${state.documents[operation.documentId].html ?? ""}${addition}`;
        changed += 1;
      } else if (operation.type === "document.clear") {
        state.documents[operation.documentId].html = "";
        changed += 1;
      } else if (operation.type === "document.delete") {
        const documentState = state.documents[operation.documentId];
        const moduleId = moduleForDocument(operation.documentId);
        state.trash.unshift(createFileTrashEntry({
          id: operation.documentId,
          document: clone(documentState),
          history: clone(state.histories[operation.documentId] ?? []),
          item: clone(itemsForModule(moduleId).find(([id]) => id === operation.documentId)),
          moduleId,
          boundConversationIds: state.conversations.filter((conversation) => conversation.boundDocumentId === operation.documentId).map((conversation) => conversation.id),
          referenceConversationIds: state.conversations.filter((conversation) => conversation.references?.includes(operation.documentId)).map((conversation) => conversation.id),
        }));
        removeDocumentFromWorkspaceState(operation.documentId);
        movedToTrash = true;
        changed += 1;
      } else if (operation.type === "document.move") {
        const sourceModule = moduleForDocument(operation.documentId);
        const sourceItem = clone(documentItem(operation.documentId)?.item ?? [operation.documentId, state.documents[operation.documentId].title, {}]);
        state.moduleItems[sourceModule] = state.moduleItems[sourceModule].filter(([id]) => id !== operation.documentId);
        const options = {
          ...(sourceItem[2] ?? {}),
          workspaceView: operation.viewId,
          ...(operation.treeGroup ? { treeGroup: operation.treeGroup } : {}),
          ...(operation.folderId ? { folderId: operation.folderId } : {}),
          ...(operation.folderLabel ? { folderLabel: operation.folderLabel } : {}),
          ...(operation.volumeFolder ? { volumeFolder: operation.volumeFolder } : {}),
          ...(operation.customFolderId ? {
            customFolderId: operation.customFolderId,
            customFolderLabel: operation.customFolderLabel,
            customFolderPath: operation.customFolderPath,
            placementOverride: true,
          } : {}),
        };
        state.moduleItems[operation.moduleId] ??= [];
        state.moduleItems[operation.moduleId].push([operation.documentId, sourceItem[1], options]);
        Object.assign(state.documents[operation.documentId], {
          moduleId: operation.moduleId,
          workspaceView: operation.viewId,
          contextDomain: ["script", "prompts"].includes(operation.viewId) ? "script" : "novel",
          treeGroup: options.treeGroup,
          volumeFolder: options.volumeFolder,
          volumeLabel: options.folderLabel,
          ...(options.customFolderId ? {
            customFolderId: options.customFolderId,
            customFolderName: options.customFolderLabel,
            customFolderPath: options.customFolderPath,
            placementOverride: true,
          } : {}),
        });
        changed += 1;
      } else if (operation.type === "document.reorder") {
        const moduleId = moduleForDocument(operation.documentId);
        const items = state.moduleItems[moduleId];
        const sourceIndex = items.findIndex(([id]) => id === operation.documentId);
        const targetId = operation.beforeDocumentId || operation.afterDocumentId;
        const originalTarget = items.find(([id]) => id === targetId);
        if (sourceIndex < 0 || !originalTarget || moduleForDocument(targetId) !== moduleId) throw new Error("排序目标必须位于同一板块");
        const [sourceItem] = items.splice(sourceIndex, 1);
        const targetIndex = items.findIndex(([id]) => id === targetId);
        items.splice(operation.beforeDocumentId ? targetIndex : targetIndex + 1, 0, sourceItem);
        changed += 1;
      } else if (operation.type === "scope.clear") {
        const ids = scopeOperationDocumentIds(operation);
        const removed = moveDocumentsToTreeTrash(ids, plan.summary || "对话批量清空的结构");
        changed += removed;
        movedToTrash ||= removed > 0;
      } else if (operation.type === "history.save_document") {
        if (operation.documentId === "library-trash") throw new Error("当前内容不支持版本保存");
        const beforeCount = state.histories[operation.documentId]?.length ?? 0;
        snapshotDocument(operation.documentId, "通过对话执行版本保存", { force: true });
        changed += (state.histories[operation.documentId]?.length ?? 0) > beforeCount ? 1 : 0;
      } else if (operation.type === "history.restore") {
        if (!await restoreVersion(operation.versionId, historyScopeFromOperation(operation))) throw new Error("历史版本未能完成本地交换");
        changed += 1;
      } else if (operation.type === "history.delete") {
        deleteVersion(operation.versionId, historyScopeFromOperation(operation));
        changed += 1;
      } else if (operation.type === "trash.restore") {
        restoreTrashDocument(operation.trashId);
        changed += 1;
      }
      if (operation.documentId && state.documents[operation.documentId]) state.documents[operation.documentId].updatedAt = nowTime();
    }
    const operationReason = plan.intent || plan.summary || "Agent 执行文档操作后的当前版本";
    const affectedDocumentIds = [...new Set(plan.operations
      .filter((operation) => operation.documentId && operation.type !== "document.delete" && !operation.type.startsWith("history."))
      .map((operation) => operation.documentId))];
    for (const documentId of affectedDocumentIds) {
      if (!state.documents[documentId]) continue;
      markCurrentDocumentVersion(documentId, operationReason, {
        operations: plan.operations.filter((operation) => operation.documentId === documentId),
      });
    }
    ensureDocumentTreeMetadata(state);
    rebuildProjectCompilationStatus();
    updateTrashIndexDocument();
    if (!state.documents[state.activeDocument]) {
      state.activeDocument = Object.keys(state.documents).find((id) => id !== "library-trash") ?? "library-trash";
      state.activeModule = moduleForDocument(state.activeDocument);
    }
    plan.status = "applied";
    plan.appliedAt = nowTime();
    message.content = `已执行 ${changed} 项文档与结构变更。修改前版本已自动保存${movedToTrash ? "，删除内容已进入回收站" : ""}。`;
    message.execution = { ...(message.execution ?? {}), status: "complete", strength: "operation", result: `已执行 ${changed} 项软件操作` };
    elements.editor.dataset.document = "";
    recordActivity({ type: "edit", label: `通过对话执行 ${changed} 项工作区操作`, documentId: state.activeDocument, scope: { type: "project", id: "project" } });
    saveActiveConversation();
    persist();
    operationSubmissionStarted = true;
    await saveWorkspace({ throwOnError: true, forceFullState: true, operationDocumentIds: affectedDocumentIds });
    operationDiskCommitted = true;
    const verifiedReceipt = clone(ui.lastWorkspaceLandingReceipt);
    if (affectedDocumentIds.length && verifiedReceipt?.verified === true && verifiedReceipt?.failed === 0) {
      const landedDocuments = affectedDocumentIds.filter((documentId) => state.documents[documentId]).map((documentId) => ({
        documentId,
        title: state.documents[documentId].title,
        content: stripHtml(state.documents[documentId].html ?? ""),
        target: { moduleId: moduleForDocument(documentId), viewId: itemWorkspaceView(moduleForDocument(documentId), documentItem(documentId)?.item), title: state.documents[documentId].title },
      }));
      const landedMessage = state.messages.find((item) => item.id === message.id) ?? message;
      landedMessage.landingManifest = buildLandingManifest({
        source: landedDocuments.map((item) => item.content).join("\n\n"),
        documents: landedDocuments,
        workspaceKind: state.workspaceKind,
        workspacePath: state.settings.workspacePath,
        workspaceName: state.projectName || state.settings.projectName || "",
        batchLandingReceipt: verifiedReceipt,
      });
      landedMessage.landingStatus = "complete";
      saveActiveConversation();
      persist();
    }
    renderAll();
    showToast("操作已执行，修改前版本已保存");
    ui.operationApplying = false;
    return true;
  } catch (error) {
    const outcome = classifyFormalWriteFailure({ submissionStarted: operationSubmissionStarted, diskCommitted: operationDiskCommitted, error });
    if (!outcome.rollbackAllowed) {
      const reply = holdFormalWriteForReadback({ outcome, error, documentIds: plan.operations.map((item) => item.documentId).filter(Boolean) });
      message.content = reply.content;
      message.execution = { ...(message.execution || {}), ...reply.engineExecution };
      message.workspacePlan.status = outcome.status;
      ui.operationApplying = false;
      renderAll();
      return false;
    }
    state = rollbackState;
    ensureStateSchema();
    const restoredMessage = state.messages.find((item) => item.id === messageId);
    if (restoredMessage?.workspacePlan) {
      restoredMessage.workspacePlan.status = error.code === "WORKSPACE_CREATION_FINALIZATION_PENDING" ? "waiting_confirm" : "failed";
      restoredMessage.workspacePlan.error = error.message;
      restoredMessage.content = error.code === "WORKSPACE_CREATION_FINALIZATION_PENDING"
        ? `创建任务尚待收尾：${error.message}`
        : `操作未执行：${error.message}`;
    }
    saveActiveConversation();
    persist();
    await saveWorkspace();
    renderAll();
    showToast(`操作未执行：${error.message}`);
    ui.operationApplying = false;
    return false;
  }
};

const cancelWorkspaceOperationPlan = (messageId) => {
  const message = state.messages.find((item) => item.id === messageId && item.role === "assistant");
  if (!message?.workspacePlan || message.workspacePlan.status !== "waiting_confirm") return;
  message.workspacePlan.status = "cancelled";
  message.content = "已取消本次软件操作，作品内容没有变化。";
  message.execution = { ...(message.execution ?? {}), status: "cancelled", strength: "operation", result: "操作已取消" };
  persist();
  renderMessages();
};

const restoreSkillTrashEntry = async (entry) => {
  try {
    const response = await fetch("/api/skills/trash/restore", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ trashId: entry.trashId }) });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 恢复失败");
    ui.skillTrash = ui.skillTrash.filter((item) => item.trashId !== entry.trashId);
    await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
    renderTrashDialog();
    showToast(`已恢复 Skill“${entry.title}”`);
  } catch (error) {
    showToast(error.message || "Skill 恢复失败");
  }
};

const persistGlobalCustomThemeCollections = () => {
  globalUiPreferences = normalizedUiPreferences(globalUiPreferences);
  state.settings.customThemes = normalizeCustomThemeRecords(globalUiPreferences.customThemes);
  state.settings.activeCustomThemeId = globalUiPreferences.activeCustomThemeId;
  state.settings.customTheme = normalizeCustomTheme(globalUiPreferences.customTheme);
  state.settings.customThemeHistories = normalizeCustomThemeHistories(globalUiPreferences.customThemeHistories, state.settings.customThemes);
  state.settings.customThemeTrash = pruneCustomThemeTrashEntries(globalUiPreferences.customThemeTrash).active;
  persistUiPreferences();
  persist();
};

const restoreCustomThemeTrashEntry = (entry) => {
  const currentThemes = normalizeCustomThemeRecords(globalUiPreferences.customThemes);
  let id = normalizeCustomThemeId(entry.theme?.id || entry.id, `custom-theme-restored-${Date.now().toString(36)}`);
  while (currentThemes.some((theme) => theme.id === id)) id = `${id}-restored`;
  const [restored] = normalizeCustomThemeRecords([{ ...entry.theme, id }]);
  globalUiPreferences.customThemes = [...currentThemes, restored];
  globalUiPreferences.customThemeHistories = {
    ...globalUiPreferences.customThemeHistories,
    [id]: normalizeCustomThemeVersionHistory(entry.history, restored),
  };
  globalUiPreferences.customThemeTrash = (globalUiPreferences.customThemeTrash ?? []).filter((item) => item.trashId !== entry.trashId);
  persistGlobalCustomThemeCollections();
  renderTrashDialog();
  showToast(`已恢复自定义主题“${restored.name || "自定义主题"}”`);
};

const restoreWorkspaceTrashEntry = async (entry) => {
  try {
    const response = await fetch("/api/workspaces/trash/restore", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ trashId: entry.trashId }),
    });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "工作区恢复失败");
    ui.workspaceTrash = (ui.workspaceTrash ?? []).filter((item) => item.trashId !== entry.trashId);
    await Promise.all([
      refreshProjects({ force: true, render: false }),
      refreshNotebooks({ force: true, render: false }),
    ]);
    renderProjectMenu();
    renderTrashDialog();
    showToast(`已恢复${entry.kind === "workspace-notebook" ? "笔记本" : "作品"}“${payload.restored?.name || entry.title}”`);
  } catch (error) {
    showToast(error.message || "工作区恢复失败");
  }
};

const restoreTrashDocument = (trashId) => {
  const themeEntry = (globalUiPreferences.customThemeTrash ?? []).find((item) => item.trashId === trashId || item.id === trashId);
  if (themeEntry) {
    restoreCustomThemeTrashEntry(themeEntry);
    return;
  }
  const skillEntry = (ui.skillTrash ?? []).find((item) => item.trashId === trashId || item.id === trashId);
  if (skillEntry) {
    void restoreSkillTrashEntry(skillEntry);
    return;
  }
  const workspaceEntry = (ui.workspaceTrash ?? []).find((item) => item.trashId === trashId);
  if (workspaceEntry) {
    void restoreWorkspaceTrashEntry(workspaceEntry);
    return;
  }
  const entry = state.trash.find((item) => item.trashId === trashId || item.id === trashId);
  if (!entry) return;
  if (entry.kind === "history-version") {
    const scope = clone(entry.scope);
    const versionEntry = clone(entry.versionEntry);
    if (!scope || !versionEntry) {
      showToast("这个历史版本的恢复信息不完整");
      return;
    }
    const versions = historyData(scope);
    if (!versions.some((version) => version.id === versionEntry.id)) {
      setHistoryData(scope, [versionEntry, ...versions]);
    }
    state.trash = state.trash.filter((item) => item.trashId !== entry.trashId);
    updateTrashIndexDocument();
    recordActivity({ type: "history", label: `从回收站恢复“${trashEntryTitle(entry)}”`, documentId: scope.type === "document" ? scope.id : null, scope });
    persist();
    renderAll();
    if (elements.trashDialog.open) renderTrashDialog();
    showToast("历史版本已恢复到原层级");
    return;
  }
  if (entry.kind === "conversation") {
    const restored = clone(entry.conversation ?? {});
    if (!restored.id) restored.id = uid("conversation");
    if (state.conversations.some((conversation) => conversation.id === restored.id)) {
      restored.id = uid("conversation");
      restored.title = `${restored.title || trashEntryTitle(entry)}（恢复）`;
    }
    restored.messages ??= [];
    restored.snapshots ??= {};
    restored.isolatedBranches ??= [];
    restored.currentCandidate ??= "";
    restored.currentCandidateTarget ??= null;
    restored.currentCandidateMemoryUpdate ??= null;
    restored.intentTarget ??= null;
    restored.queue ??= [];
    restored.references ??= [];
    restored.attachments ??= [];
    saveActiveConversation();
    state.conversations.unshift(restored);
    state.trash = state.trash.filter((item) => item.trashId !== entry.trashId);
    loadConversation(restored.id, { saveCurrent: false });
    updateTrashIndexDocument();
    recordActivity({ type: "chat", label: `从回收站恢复对话“${trashEntryTitle(entry)}”`, conversationId: restored.id });
    persist();
    renderAll();
    if (elements.trashDialog.open) renderTrashDialog();
    showToast(`已恢复对话“${trashEntryTitle(entry)}”`);
    return;
  }
  const documents = entry.kind === "tree" ? clone(entry.documents ?? {}) : { [entry.id]: clone(entry.document) };
  const documentIds = Object.keys(documents);
  const conflicts = documentIds.filter((id) => state.documents[id]);
  if (conflicts.length) {
    showToast("原位置已有同名文档，无法恢复");
    return;
  }
  const restoredFolders = clone(entry.customFolders ?? []);
  const restoredVolumeFolders = clone(entry.volumeFolders ?? []);
  const folderConflict = restoredFolders.some((folder) => state.customFolders.some((current) => (
    current.id === folder.id
    || current.moduleId === folder.moduleId && current.viewId === folder.viewId && current.label.toLowerCase() === folder.label.toLowerCase()
  )));
  const restoredVolumeFolderIds = new Set(restoredVolumeFolders.map((folder) => folder.id).filter(Boolean));
  const volumeFolderConflict = (state.moduleItems.manuscript ?? []).some(([, , options = {}]) => restoredVolumeFolderIds.has(options.folderId));
  if (folderConflict || volumeFolderConflict) {
    showToast("原位置已有同名文件夹，无法恢复");
    return;
  }
  const affectedModules = entry.kind === "tree"
    ? Object.keys(entry.moduleItems ?? {}).filter((moduleId) => (entry.moduleItems[moduleId] ?? []).length)
    : [entry.moduleId];
  if (affectedModules.length > 1) snapshotProject(`跨板块恢复“${trashEntryTitle(entry)}”之前的作品结构`);
  else if (affectedModules[0]) {
    const moduleId = affectedModules[0];
    const restoredItems = entry.kind === "tree" ? entry.moduleItems?.[moduleId] ?? [] : [entry.item].filter(Boolean);
    const affectedViews = new Set(restoredItems.map((item) => itemWorkspaceView(moduleId, item)));
    const restoredVolumeIds = new Set(restoredItems.map(([, , options = {}]) => options.folderId).filter(Boolean));
    const rootVolumeIds = restoredVolumeFolderIds.size ? restoredVolumeFolderIds : restoredVolumeIds;
    if (moduleId === "manuscript" && affectedViews.size === 1 && affectedViews.has("novel") && rootVolumeIds.size === 1) {
      const folderId = Array.from(rootVolumeIds)[0];
      const options = restoredItems.find(([, , itemOptions = {}]) => itemOptions.folderId === folderId)?.[2] ?? {};
      const restoredVolume = restoredVolumeFolders.find((folder) => folder.id === folderId);
      snapshotVolume({ type: "volume", id: folderId, label: restoredVolume?.label ?? options.folderLabel }, `恢复“${trashEntryTitle(entry)}”之前的分卷结构`);
    } else if (MODULE_VIEWS[moduleId] && affectedViews.size === 1) {
      snapshotView(moduleId, Array.from(affectedViews)[0], `恢复“${trashEntryTitle(entry)}”之前的分类结构`);
    } else {
      snapshotModule(moduleId, `恢复“${trashEntryTitle(entry)}”之前的板块整体结构`);
    }
  }
  Object.assign(state.documents, documents);
  for (const folder of restoredFolders) {
    state.customFolders.push(folder);
    if (!state.expandedFolders.includes(folder.id)) state.expandedFolders.push(folder.id);
  }
  for (const [folderId, versions] of Object.entries(entry.volumeHistories ?? {})) state.volumeHistories[folderId] = clone(versions);
  if (entry.kind === "tree") {
    for (const [id, history] of Object.entries(entry.histories ?? {})) state.histories[id] = clone(history);
    for (const [moduleId, items] of Object.entries(entry.moduleItems ?? {})) {
      state.moduleItems[moduleId] ??= [];
      for (const item of items) if (!state.moduleItems[moduleId].some(([id]) => id === item[0])) state.moduleItems[moduleId].push(clone(item));
    }
    for (const [documentId, bindings] of Object.entries(entry.conversationBindings ?? {})) {
      for (const conversation of state.conversations) {
        if (bindings.boundConversationIds?.includes(conversation.id)) conversation.boundDocumentId = documentId;
        if (bindings.referenceConversationIds?.includes(conversation.id) && !conversation.references.includes(documentId)) conversation.references.push(documentId);
        synchronizeConversationReferenceContext(conversation);
      }
    }
  } else {
    state.histories[entry.id] = clone(entry.history ?? []);
    state.moduleItems[entry.moduleId] ??= [];
    if (!state.moduleItems[entry.moduleId].some(([id]) => id === entry.id)) state.moduleItems[entry.moduleId].push(clone(entry.item ?? [entry.id, entry.document.title]));
    for (const conversation of state.conversations) {
      if (entry.boundConversationIds?.includes(conversation.id)) conversation.boundDocumentId = entry.id;
      if (entry.referenceConversationIds?.includes(conversation.id) && !conversation.references.includes(entry.id)) conversation.references.push(entry.id);
      synchronizeConversationReferenceContext(conversation);
    }
  }
  state.trash = state.trash.filter((item) => item.trashId !== entry.trashId);
  if (restoredFolders.length) persistExpandedFolderState();
  state.activeDocument = documentIds[0] ?? state.activeDocument;
  state.activeModule = moduleForDocument(state.activeDocument);
  elements.editor.dataset.document = "";
  rebuildProjectCompilationStatus();
  updateTrashIndexDocument();
  recordActivity({ type: "edit", label: `从回收站恢复“${trashEntryTitle(entry)}”`, documentId: state.activeDocument });
  persist();
  renderAll();
  if (elements.trashDialog.open) renderTrashDialog();
  showToast(`已恢复“${trashEntryTitle(entry)}”`);
};

const requestPermanentSkillTrashDelete = async (entry) => {
  const response = await fetch("/api/skills/trash/permanent", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ trashId: entry.trashId }) });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 永久删除失败");
  return payload;
};

const permanentlyDeleteSkillTrashEntry = async (entry) => {
  try {
    const payload = await requestPermanentSkillTrashDelete(entry);
    ui.skillTrash = ui.skillTrash.filter((item) => item.trashId !== entry.trashId);
    renderTrashDialog();
    showToast(payload.recoveryHint || "Skill 已永久删除，无法恢复");
  } catch (error) {
    showToast(error.message || "Skill 永久删除失败");
  }
};

const permanentlyDeleteCustomThemeTrashEntry = (entry) => {
  globalUiPreferences.customThemeTrash = (globalUiPreferences.customThemeTrash ?? []).filter((item) => item.trashId !== entry.trashId);
  persistGlobalCustomThemeCollections();
  renderTrashDialog();
  showToast("自定义主题已永久删除，无法恢复");
};

const requestPermanentWorkspaceTrashDelete = async (entry) => {
  const response = await fetch("/api/workspaces/trash/permanent", {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ trashId: entry.trashId }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "工作区永久删除失败");
  return payload;
};

const permanentlyDeleteWorkspaceTrashEntry = async (entry) => {
  try {
    await requestPermanentWorkspaceTrashDelete(entry);
    ui.workspaceTrash = (ui.workspaceTrash ?? []).filter((item) => item.trashId !== entry.trashId);
    renderTrashDialog();
    showToast(`${entry.kind === "workspace-notebook" ? "笔记本" : "作品"}已永久删除，无法恢复`);
  } catch (error) {
    showToast(error.message || "工作区永久删除失败");
  }
};

const permanentlyDeleteTrashEntry = async (trashId) => {
  const themeEntry = (globalUiPreferences.customThemeTrash ?? []).find((item) => item.trashId === trashId);
  if (themeEntry) {
    permanentlyDeleteCustomThemeTrashEntry(themeEntry);
    return true;
  }
  const skillEntry = (ui.skillTrash ?? []).find((item) => item.trashId === trashId);
  if (skillEntry) {
    await permanentlyDeleteSkillTrashEntry(skillEntry);
    return true;
  }
  const workspaceEntry = (ui.workspaceTrash ?? []).find((item) => item.trashId === trashId);
  if (workspaceEntry) {
    await permanentlyDeleteWorkspaceTrashEntry(workspaceEntry);
    return true;
  }
  const entry = state.trash.find((item) => item.trashId === trashId);
  if (!entry) return false;
  const rollbackState = clone(state);
  try {
    purgeTrashPayloadsFromState(state, [entry]);
    state.trash = state.trash.filter((item) => item.trashId !== trashId);
    updateTrashIndexDocument();
    recordActivity({ type: "edit", label: `永久删除回收项“${trashEntryTitle(entry)}”`, destination: "trash" });
    persist();
    await flushWorkspaceSave({ throwOnError: true });
    renderAll();
    if (elements.trashDialog.open) renderTrashDialog();
    showToast("已永久删除，无法恢复");
    return true;
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    persist();
    renderAll();
    if (elements.trashDialog.open) renderTrashDialog();
    showToast(`永久删除失败：${error.message || "保存失败"}`);
    return false;
  }
};

const permanentlyDeleteAllTrashEntries = async () => {
  if (ui.trashClearing) return;
  const documentEntries = [...(state.trash ?? [])];
  const workspaceEntries = [...(ui.workspaceTrash ?? [])];
  const skillEntries = [...(ui.skillTrash ?? [])];
  const themeEntries = [...(globalUiPreferences.customThemeTrash ?? [])];
  const requestedCount = documentEntries.length + workspaceEntries.length + skillEntries.length + themeEntries.length;
  if (!requestedCount) return;

  ui.trashClearing = true;
  renderTrashDialog();
  const failed = [];
  let failedCount = 0;
  const deletedSkillIds = new Set();
  for (const entry of skillEntries) {
    try {
      await requestPermanentSkillTrashDelete(entry);
      deletedSkillIds.add(entry.trashId);
    } catch (error) {
      failed.push({ entry, error });
      failedCount += 1;
    }
  }
  ui.skillTrash = (ui.skillTrash ?? []).filter((entry) => !deletedSkillIds.has(entry.trashId));

  let documentDeletedCount = 0;
  if (documentEntries.length) {
    const rollbackState = clone(state);
    const documentTrashIds = new Set(documentEntries.map((entry) => entry.trashId));
    try {
      purgeTrashPayloadsFromState(state, documentEntries);
      state.trash = (state.trash ?? []).filter((entry) => !documentTrashIds.has(entry.trashId));
      updateTrashIndexDocument();
      recordActivity({ type: "edit", label: `清空回收站，永久删除 ${documentEntries.length} 项`, destination: "trash" });
      persist();
      await flushWorkspaceSave({ throwOnError: true });
      documentDeletedCount = documentEntries.length;
    } catch (error) {
      state = rollbackState;
      ensureStateSchema();
      persist();
      failed.push({ entry: null, error });
      failedCount += documentEntries.length;
    }
  }

  let workspaceDeletedCount = 0;
  const deletedWorkspaceIds = new Set();
  for (const entry of workspaceEntries) {
    try {
      await requestPermanentWorkspaceTrashDelete(entry);
      deletedWorkspaceIds.add(entry.trashId);
      workspaceDeletedCount += 1;
    } catch (error) {
      failed.push({ entry, error });
      failedCount += 1;
    }
  }
  ui.workspaceTrash = (ui.workspaceTrash ?? []).filter((entry) => !deletedWorkspaceIds.has(entry.trashId));

  let themeDeletedCount = 0;
  if (themeEntries.length) {
    const rollbackThemeTrash = clone(globalUiPreferences.customThemeTrash ?? []);
    const themeTrashIds = new Set(themeEntries.map((entry) => entry.trashId));
    try {
      globalUiPreferences.customThemeTrash = (globalUiPreferences.customThemeTrash ?? []).filter((entry) => !themeTrashIds.has(entry.trashId));
      persistGlobalCustomThemeCollections();
      themeDeletedCount = themeEntries.length;
    } catch (error) {
      globalUiPreferences.customThemeTrash = rollbackThemeTrash;
      persistGlobalCustomThemeCollections();
      failed.push({ entry: null, error });
      failedCount += themeEntries.length;
    }
  }

  ui.trashClearing = false;
  renderAll();
  if (elements.trashDialog.open) renderTrashDialog();
  const deletedCount = documentDeletedCount + workspaceDeletedCount + themeDeletedCount + deletedSkillIds.size;
  if (failed.length) showToast(`已永久删除 ${deletedCount} 项，${failedCount} 项清理失败，请重试`);
  else showToast(`已清空回收站，共永久删除 ${deletedCount} 项`);
};

