  homeDocumentBoundAtEpoch: 0,
  documentAssociationHistory: {},
  associationRevision: 0,
  messages: [],
  snapshots: {},
  isolatedBranches: [],
  branchGroups: [],
  candidateBranchGroups: [],
  currentCandidate: "",
  currentCandidateTarget: null,
  currentCandidateMemoryUpdate: null,
  currentCandidateAuthorization: null,
  nativeAgentSession: null,
  agentContextEpoch: "",
  constraintIndex: [],
  contextCapsule: null,
  conversationContextCheckpoint: null,
  contextLedger: null,
  contextCompressionSignature: "",
  contextCompressionStatus: null,
  intentTarget: null,
  queue: [],
  references: [],
  workspaceReferences: [],
  skillReferences: [],
  attachments: [],
