  if (!option) return;
  const moduleId = state.activeModule;
  const previousViewId = activeViewForModule(moduleId);
  if (state.activeDocument && state.documents[state.activeDocument]) {
    rememberModuleDocument(state.activeDocument, { moduleId, viewId: previousViewId });
  }
  const viewId = option.dataset.moduleView;
  state.moduleViews[moduleId] = viewId;
  ui.moduleViewMenu = null;
