  state.activeDocument = rememberedModuleDocument({
    moduleId: presentationModuleId(moduleId),
    viewId,
    remembered: state.moduleLastDocuments,
    documentIds,
  }) || null;
  if (state.activeDocument) rememberModuleDocument(state.activeDocument, { moduleId, viewId });
  state.selectedText = "";
