elements.compilationDecisionSummary.addEventListener("change", async (event) => {
  const input = event.target.closest("[data-creative-contract-field]");
  if (!input || state.activeDocument !== CREATIVE_CONTRACT_DOCUMENT_ID) return;
  const field = input.dataset.creativeContractField;
  if (!Object.hasOwn({ bannedTerms: true, specialNotes: true }, field)) return;
  const documentState = state.documents[CREATIVE_CONTRACT_DOCUMENT_ID];
  if (!documentState) return;
  const current = normalizeCreativeContract(documentState);
  if (current[field] === input.value.trim()) return;
  const rollbackState = clone(state);
  snapshotDocument(CREATIVE_CONTRACT_DOCUMENT_ID, `手动修改创作合同 / ${field === "bannedTerms" ? "项目禁用词" : "特别注意事项"}`);
  state.documents[CREATIVE_CONTRACT_DOCUMENT_ID] = creativeContractDocumentPatch(documentState, { [field]: input.value });
  state.documents[CREATIVE_CONTRACT_DOCUMENT_ID].updatedAt = nowTime();
  markCurrentDocumentVersion(CREATIVE_CONTRACT_DOCUMENT_ID, "手动修改创作合同", {
    operations: [{ type: "creative-contract-field-update", documentId: CREATIVE_CONTRACT_DOCUMENT_ID, field }],
  });
  try {
    await saveWorkspace({ throwOnError: true, forceFullState: true });
    recordActivity({ type: "edit", label: `已更新创作合同 / ${field === "bannedTerms" ? "项目禁用词" : "特别注意事项"}`, documentId: CREATIVE_CONTRACT_DOCUMENT_ID });
    renderAll();
    showToast("创作合同已保存");
  } catch (error) {
    state = rollbackState;
    ensureStateSchema();
    renderAll();
    showToast(`创作合同保存失败：${error.message}`);
  }
});
elements.memoryReviewDialog.addEventListener("click", (event) => {
  const reviewAction = event.target.closest("[data-memory-review-action]");
  if (reviewAction) {
    const action = reviewAction.dataset.memoryReviewAction;
    const candidateId = reviewAction.dataset.memoryCandidateId || "";
    const candidate = candidateId ? memoryReviewCandidateById(candidateId) : null;
    const documentId = reviewAction.dataset.memoryDocumentId || candidate?.documentId || "";
    if (action === "defer" && candidateId) {
      ui.memoryReview.deferredIds.add(candidateId);
      ui.memoryReview.selectedIds.delete(candidateId);
      renderMemoryReviewDialog();
    } else if (action === "resume" && candidateId) {
      ui.memoryReview.deferredIds.delete(candidateId);
      renderMemoryReviewDialog();
    } else if (action === "repair" && documentId) {
      closeMemoryReview();
      selectDocument(documentId);
      requestAnimationFrame(() => elements.editor?.focus());
      showToast("已打开来源正文；完成后请重新扫描记忆");
    } else if (action === "ignore" && candidate) {
      void applyMemoryReviewDisposition({ decision: "ignore", candidate, documentId });
    } else if (action === "edit" && candidate) {
      void prepareEditedMemoryCandidate(candidate);
    } else if (["exclude", "include", "reconsider"].includes(action) && documentId) {
      void applyMemoryReviewDisposition({ decision: action, documentId });
    }
    return;
  }
  const recommendedButton = event.target.closest("[data-select-recommended-memory]");
  if (recommendedButton) {
    ui.memoryReview.selectedIds = toggleRecommendedMemorySelection(ui.memoryReview);
    for (const candidateId of ui.memoryReview.deferredIds) ui.memoryReview.selectedIds.delete(candidateId);
    renderMemoryReviewDialog();
    return;
  }
  if (event.target === elements.memoryReviewDialog || event.target.closest("#closeMemoryReview")) closeMemoryReview();
});
elements.memoryReviewDialog.addEventListener("change", (event) => {
  const checkbox = event.target.closest("[data-memory-candidate]");
  if (!checkbox) return;
  if (checkbox.checked) ui.memoryReview.selectedIds.add(checkbox.dataset.memoryCandidate);
  else ui.memoryReview.selectedIds.delete(checkbox.dataset.memoryCandidate);
  renderMemoryReviewDialog();
});
elements.reloadMemoryReview.addEventListener("click", () => void loadMemoryReviewPlan());
elements.selectAllMemoryReview.addEventListener("click", () => {
  const selectable = memoryReviewCandidates().filter((candidate) => candidate.status === "proposal" && !ui.memoryReview.deferredIds.has(candidate.candidateId));
  const allSelected = selectable.length && selectable.every((candidate) => ui.memoryReview.selectedIds.has(candidate.candidateId));
  ui.memoryReview.selectedIds = allSelected ? new Set() : new Set(selectable.map((candidate) => candidate.candidateId));
  renderMemoryReviewDialog();
});
