elements.selectionEditForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const instruction = elements.selectionEditInput.value.trim();
  if (!instruction) return;
  const requestedMode = ui.selectionMutationMode;
  const retargetedFrom = ui.inlineEditRetargetId;
  const inlineEdit = createInlineEditAnchor({ instruction, requestedMode });
  if (!inlineEdit) {
    showToast(requestedMode === "insert_at_caret" ? "无法锁定当前补写位置，请重新右键选择" : "无法锁定当前选区，请重新拖选后修改");
    return;
  }
  if (retargetedFrom) {
    inlineEdit.retargetedFrom = retargetedFrom;
    ui.inlineEditRetargetId = "";
  }
  const prompt = buildInlineSelectionPrompt({
    selectedText: inlineEdit.originalText,
    instruction,
    anchor: inlineEdit.anchor,
    documentTitle: state.documents[inlineEdit.documentId]?.title || "",
    mode: inlineEdit.mutationMode,
  });
  if (!prompt) {
    cancelInlineEdit(inlineEdit.id);
    return;
  }
  inlineEdit.displayContent = `${inlineEditModeLabel(inlineEdit.mutationMode)}：${instruction}`;
  elements.selectionEditInput.value = "";
  hideSelectionToolbar();
  window.getSelection()?.removeAllRanges();
  sendMessage(prompt, {
    inlineEdit,
    executionSurface: ui.codexAgent.status?.provider === "codex_agent" ? "agent" : "chat",
  });
});

elements.inlineEditConflictDialog?.addEventListener("click", (event) => {
  const action = event.target.closest("[data-inline-edit-conflict-action]")?.dataset.inlineEditConflictAction;
  if (!action) return;
  const dialog = elements.inlineEditConflictDialog;
  const inlineEditId = String(dialog.dataset.inlineEditId || "");
  if (action === "retry") {
    if (recheckInlineEditAnchor(inlineEditId)) dialog.close("retried");
    else {
      const record = inlineEditRecord(inlineEditId);
      if (record) {
        elements.inlineEditConflictMessage.textContent = record.conflictMessage || "当前正文中仍找不到唯一且稳定的原文位置。";
        elements.inlineEditConflictCandidate.textContent = record.candidate || "";
        showToast("当前正文仍无法唯一定位；候选已保留，原文未修改");
      }
    }
    return;
  }
  if (action === "retarget") {
    if (beginInlineEditRetarget(inlineEditId)) dialog.close("retarget");
    return;
  }
  dialog.close("kept");
});

elements.inlineEditConflictDialog?.addEventListener("close", () => {
  delete elements.inlineEditConflictDialog.dataset.inlineEditId;
});

const inlineDocumentTitlePart = (target) => target?.closest?.(".chapter-title-text");

elements.chapterTitle.addEventListener("keydown", (event) => {
  const part = inlineDocumentTitlePart(event.target);
  if (!part || part.contentEditable !== "true") return;
  if (event.key === "Enter") {
    event.preventDefault();
    part.blur();
    return;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    renderEditor();
  }
});

elements.chapterTitle.addEventListener("beforeinput", (event) => {
  const part = inlineDocumentTitlePart(event.target);
  if (!part || part.contentEditable !== "true") return;
  if (event.inputType === "insertParagraph" || event.inputType === "insertLineBreak") event.preventDefault();
});

elements.chapterTitle.addEventListener("paste", (event) => {
  const part = inlineDocumentTitlePart(event.target);
  if (!part || part.contentEditable !== "true") return;
  event.preventDefault();
  const title = normalizePastedDocumentTitle(event.clipboardData?.getData("text/plain") || "");
  if (!title) return;
  document.execCommand("insertText", false, title);
});

elements.chapterTitle.addEventListener("input", (event) => {
  const part = inlineDocumentTitlePart(event.target);
  if (!part || part.contentEditable !== "true") return;
  const normalized = normalizePastedDocumentTitle(part.textContent).slice(0, 180);
  if (part.textContent !== normalized) part.textContent = normalized;
  if (part.classList.contains("chapter-title-text")) {
    const breadcrumbTitle = elements.breadcrumbs.querySelector("span:last-child");
    if (breadcrumbTitle) breadcrumbTitle.textContent = normalized;
  }
});

elements.chapterTitle.addEventListener("focusout", (event) => {
  const part = inlineDocumentTitlePart(event.target);
  if (!part || part.contentEditable !== "true") return;
  if (inlineDocumentTitlePart(event.relatedTarget)) return;
  const documentId = String(part.dataset.documentId || state.activeDocument || "");
  if (!documentId || documentId !== state.activeDocument || !state.documents[documentId]) return;
  const titlePart = elements.chapterTitle.querySelector(".chapter-title-text");
  const nextName = String(titlePart?.textContent || "").replace(/[\r\n]+/g, " ").trim();
  if (!nextName) {
    showToast("文档标题不能为空");
    renderEditor();
    return;
  }
  renameDocument(documentId, nextName);
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && (ui.selectionEditMode || ui.selectionStyleMenuOpen)) {
    event.preventDefault();
    event.stopImmediatePropagation();
    setSelectionEditMode(false);
    restoreSelectionRange();
    return;
  }
  if (event.target?.matches?.("input, textarea, select")) return;
  const editorActive = elements.editor.contains(event.target)
    || (!elements.selectionToolbar.hidden && Boolean(ui.selectionRange));
  if (!editorActive) return;
  const shortcut = shortcutFromKeyboardEvent(event);
  if (!shortcut) return;
  const bindings = normalizedShortcutBindings(state.settings.shortcuts ?? globalUiPreferences.shortcuts);
  const actionId = SHORTCUT_DEFINITIONS.find(({ id, scope }) => scope === "editor"
    && bindings[id]
    && bindings[id].toLowerCase() === shortcut.toLowerCase())?.id;
  if (!actionId) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (actionId === "selectAllDocument") selectAllEditorContent();
  else if (actionId === "clearDocumentFormatting") clearEditorFormatting();
  else if (actionId === "selectionChange") openSelectionChangeEditor();
  else if (actionId === "selectionBold") applySelectionFormat("bold");
  else if (actionId === "selectionItalic") applySelectionFormat("italic");
  else {
    const styles = {
      selectionParagraph: "paragraph",
      selectionHeading1: "heading1",
      selectionHeading2: "heading2",
      selectionHeading3: "heading3",
      selectionOrderedList: "ordered",
      selectionBulletList: "bullet",
      selectionChecklist: "checklist",
    };
    if (styles[actionId]) applySelectionStyle(styles[actionId]);
  }
});

document.addEventListener("selectionchange", handleSelection);
document.addEventListener("selectionchange", () => {
  if (elements.editor.hidden || activeWhiteboardDocument() || state.activeDocument === "library-trash") return;
  rememberDocumentEditorRange();
  if (!activeNoteDocument()) return;
  rememberNoteEditorRange();
  syncNoteToolbarState();
});
elements.editor.addEventListener("mouseup", handleSelection);
elements.editor.addEventListener("mouseup", () => {
  rememberDocumentEditorRange();
  if (!activeNoteDocument()) return;
  rememberNoteEditorRange();
  if (ui.noteFormatPainter) setTimeout(applyCapturedNoteFormat, 0);
});
elements.editor.addEventListener("keyup", handleSelection);
elements.editor.addEventListener("keyup", () => {
  rememberDocumentEditorRange();
  if (activeNoteDocument()) rememberNoteEditorRange();
});
elements.editor.addEventListener("focus", () => {
  clearEditorNarrativePlaceholder();
  setEditorParagraphMode();
  rememberDocumentEditorRange();
});
elements.editor.addEventListener("beforeinput", (event) => {
  if (documentPreviewActive()) {
    event.preventDefault();
    return;
  }
  if (activeEditableDocument() && !ui.documentEditHistoryApplying) {
    ui.documentEditPendingMutation = {
      documentId: state.activeDocument,
      html: serializableEditorHtml(),
      selection: editorSelectionBookmark(),
      inputType: event.inputType || "",
      at: Date.now(),
    };
  }
  if (event.inputType === "insertParagraph") setEditorParagraphMode();
});
elements.editor.addEventListener("keydown", (event) => {
  if (documentPreviewActive()) return;
  const modifier = event.ctrlKey || event.metaKey;
  const key = event.key.toLowerCase();
  const shortcut = shortcutFromKeyboardEvent(event);
  const editorBindings = normalizedShortcutBindings(state.settings.shortcuts ?? globalUiPreferences.shortcuts);
  const editorAction = SHORTCUT_DEFINITIONS.find(({ id, scope }) => scope === "editor"
    && editorBindings[id]
    && editorBindings[id].toLowerCase() === shortcut.toLowerCase())?.id;
  if (["selectAllDocument", "clearDocumentFormatting"].includes(editorAction)) {
    event.preventDefault();
    event.stopPropagation();
    if (editorAction === "selectAllDocument") selectAllEditorContent();
    else clearEditorFormatting();
    return;
  }
  const historyCommand = modifier && !event.altKey
    ? key === "y" && !event.shiftKey ? "redo" : key === "z" ? event.shiftKey ? "redo" : "undo" : ""
    : "";
  if (historyCommand) {
    event.preventDefault();
    event.stopPropagation();
    runDocumentEditorHistoryCommand(historyCommand);
    return;
  }
  mergeEditorParagraphAtBoundary(event);
});

document.addEventListener("keydown", (event) => {
  const modifier = event.ctrlKey || event.metaKey;
  if (modifier && !event.altKey && event.key.toLowerCase() === "f") {
    event.preventDefault();
    event.stopImmediatePropagation();
    const textPreviewOpen = Boolean(
      elements.attachmentPreviewDialog.open
      && elements.attachmentPreviewMedia.dataset.previewKind === "text"
      && attachmentTextPreviewState,
    );
    const blockingDialog = [...document.querySelectorAll("dialog[open]")].some((dialog) => (
      !dialog.classList.contains("whiteboard-generation-popover")
      && !(textPreviewOpen && dialog === elements.attachmentPreviewDialog)
    ));
    if (blockingDialog) {
      showToast("请先关闭当前窗口，再查找当前文档");
      return;
    }
    if (textPreviewOpen || activeWhiteboardDocument()) {
      openWhiteboardFindPanel();
      return;
    }
    if (document.querySelector("dialog[open]")) {
      showToast("请先关闭当前窗口，再查找当前文档");
      return;
    }
    openDocumentFindPanel();
    return;
  }
  if (event.key === "Escape" && ui.whiteboardFind.open) {
    event.preventDefault();
    event.stopImmediatePropagation();
    closeWhiteboardFindPanel({ restoreFocus: true });
    return;
  }
  if (event.key === "Escape" && ui.documentFind.open) {
    event.preventDefault();
    event.stopImmediatePropagation();
    closeDocumentFindPanel({ restoreFocus: true });
  }
});

