elements.whiteboardEditor.addEventListener("click", async (event) => {
  // Generation popovers live inside the whiteboard DOM so they can stay
  // anchored to a card. Their controls must never fall through to the canvas
  // selection/click pipeline, which can clear focus from the rich prompt.
  if (event.target.closest(".whiteboard-generation-popover")) return;
  // View controls reframe the canvas but do not leave the card/composer task.
  // Let their dedicated handlers run without treating the toolbar click as a
  // blank-canvas click that dismisses the attached generation surface.
  if (event.target.closest(".whiteboard-tool-controls, .whiteboard-zoom-controls, .whiteboard-find-panel")) return;
  const imageEditButton = event.target.closest("[data-edit-whiteboard-image]");
  if (imageEditButton) {
    event.preventDefault();
    event.stopPropagation();
    await openWhiteboardImageEditor(imageEditButton.dataset.editWhiteboardImage);
    return;
  }
  if (ui.whiteboardIgnoreClick) {
    ui.whiteboardIgnoreClick = false;
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  const card = event.target.closest("[data-canvas-node]");
  const modifierSelection = Boolean(card && (event.ctrlKey || event.metaKey)
    && !event.target.closest("button, input, select, textarea, a, audio, video, [contenteditable='true'], [data-canvas-handle], [data-canvas-resize]"));
  if (modifierSelection) {
    event.preventDefault();
    event.stopPropagation();
    cancelWhiteboardCardOpen();
    toggleWhiteboardNodeSelection(card.dataset.canvasNode);
    finishWhiteboardEditing();
    ui.whiteboardModifierSelectionPointer = null;
    return;
  }
  if (event.detail === 3 && !event.target.closest("button, input, select, textarea, a, audio, video, [contenteditable='true'], [data-canvas-handle], [data-canvas-resize]")) {
    event.preventDefault();
    event.stopPropagation();
    cancelWhiteboardCardOpen();
    let nodeId = card?.dataset.canvasNode || "";
    if (!nodeId) {
      const documentState = activeWhiteboardDocument();
      const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState);
      const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
      nodeId = uid("canvas-node");
      documentState.canvas = addCanvasTextNode(documentState.canvas, {
        id: nodeId,
        text: "",
        kind: "text",
        x: snapCanvasValue(point.x - 130, documentState.canvas),
        y: snapCanvasValue(point.y - 80, documentState.canvas),
        width: 260,
        height: 160,
      });
      documentState.updatedAt = nowTime();
      pushWhiteboardHistory(beforeCanvas, { label: "三击白板创建 AI 生成目标" });
      persist({ documentIds: [state.activeDocument] });
      renderWhiteboard(documentState);
    }
    selectWhiteboardNode(nodeId);
    setWhiteboardAutoOpenDisabled(nodeId, false);
    if (!card || !openPreferredWhiteboardGenerationForNode(nodeId)) openWhiteboardGenerateDialog(nodeId, { centered: !card });
    return;
  }
  if (card) dismissWhiteboardGenerationElapsed(card);
  const dormantVideoTrigger = event.target.closest("[data-whiteboard-video-activate]");
  if (dormantVideoTrigger && card) {
    event.preventDefault();
    event.stopPropagation();
    cancelWhiteboardCardOpen();
    const nodeId = card.dataset.canvasNode;
    ui.whiteboardActiveVideoKeys.add(whiteboardActiveVideoKey(nodeId));
    const video = activateDormantWhiteboardVideo(card);
    if (!video) return;
    void video.play().catch(() => revealWhiteboardVideoOverlay(video, { autoHide: false }));
    scheduleWhiteboardCardOpen(nodeId);
    return;
  }
  const videoDragSurface = event.target.closest("[data-whiteboard-video-drag-surface]");
  if (videoDragSurface) {
    event.preventDefault();
    event.stopPropagation();
    const video = videoDragSurface.closest(".whiteboard-card-media-shell")?.querySelector("video");
    if (video?.paused) void video.play().catch(() => {});
    else video?.pause();
    // Playing an existing result must not consume the card click. The delayed
    // opener still respects the user's explicit Close preference and is
    // cancelled automatically if this click becomes a drag or a double click.
    if (card && event.detail === 1) scheduleWhiteboardCardOpen(card.dataset.canvasNode);
    return;
  }
  const mediaAction = event.target.closest("[data-media-job-action][data-media-job-id]");
  if (mediaAction) {
    event.preventDefault();
    event.stopPropagation();
    mediaAction.disabled = true;
    try {
      await handleMediaGenerationActionElement(mediaAction);
    } catch (error) {
      showToast(error.message || uiText("媒体任务操作失败"));
      const current = await fetchWhiteboardGenerationJob(mediaAction.dataset.mediaJobId).catch(() => null);
      if (current) updateMediaJobTargetAfterAction(current);
    } finally {
      if (mediaAction.isConnected) mediaAction.disabled = false;
    }
    return;
  }
  if (!card) {
    closeWhiteboardGenerationDialogsOutside(event.target);
  }
  const keepMultiSelection = card && selectedWhiteboardNodeIds().length > 1 && ui.whiteboardSelectedNodeIds.has(card.dataset.canvasNode);
  if (!keepMultiSelection) selectWhiteboardNode(card?.dataset.canvasNode ?? null);
  if (card && event.detail >= 2) {
    cancelWhiteboardCardOpen();
    event.preventDefault();
    return;
  }
  const editingCard = event.target.closest(`[data-canvas-node="${CSS.escape(ui.whiteboardEditingNodeId || "__none__")}"]`);
  if (!editingCard) finishWhiteboardEditing();
  elements.whiteboardMenu.hidden = true;
  if (card && event.detail === 1) scheduleWhiteboardCardOpen(card.dataset.canvasNode);
});

const applyWhiteboardDragPreview = (drag) => {
  if (!drag?.pending) return;
  const pending = drag.pending;
  if (["edge", "multi-edge"].includes(drag.mode)) {
    ui.whiteboardEdgeDraft = drag.mode === "multi-edge"
      ? { fromPoint: drag.sourcePoint, x: pending.x, y: pending.y }
      : { fromNode: drag.nodeId, x: pending.x, y: pending.y };
    const path = elements.whiteboardSurface.querySelector(".whiteboard-edge.draft");
    if (path && drag.sourcePoint) path.setAttribute("d", whiteboardEdgePath(drag.sourcePoint, pending));
  } else if (drag.mode === "pan") {
    elements.whiteboardSurface.style.transform = `translate3d(${pending.x}px, ${pending.y}px, 0) scale(${drag.zoom})`;
    if (!elements.whiteboardMultiSelection.hidden) {
      const deltaX = pending.x - drag.viewportX;
      const deltaY = pending.y - drag.viewportY;
      elements.whiteboardMultiSelection.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0)`;
    }
  } else if (drag.mode === "select") {
    const rect = drag.editorRect ?? elements.whiteboardEditor.getBoundingClientRect();
    const left = Math.min(drag.startX, pending.clientX) - rect.left;
    const top = Math.min(drag.startY, pending.clientY) - rect.top;
    elements.whiteboardMarquee.style.left = `${left}px`;
    elements.whiteboardMarquee.style.top = `${top}px`;
    elements.whiteboardMarquee.style.width = `${Math.abs(pending.clientX - drag.startX)}px`;
    elements.whiteboardMarquee.style.height = `${Math.abs(pending.clientY - drag.startY)}px`;
    elements.whiteboardMarquee.hidden = false;
  } else if (drag.mode === "resize") {
    drag.card.style.left = `${pending.x}px`;
    drag.card.style.top = `${pending.y}px`;
    drag.card.style.width = `${pending.width}px`;
    drag.card.style.height = `${pending.height}px`;
  } else if (drag.mode === "card") {
    const deltaX = pending.x - drag.nodeX;
    const deltaY = pending.y - drag.nodeY;
    drag.card.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0)`;
    for (const member of drag.groupMembers ?? []) member.card.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0)`;
  }
  updateWhiteboardConnectedEdgePreview(drag);
  if (["pan", "resize", "card"].includes(drag.mode)) scheduleWhiteboardGenerationDialogPosition();
};

const startWhiteboardPan = (event, documentState) => {
  event.preventDefault();
  event.stopPropagation();
  finishWhiteboardEditing();
  elements.whiteboardEditor.setPointerCapture?.(event.pointerId);
  const viewport = normalizeCanvas(documentState.canvas).viewport;
  ui.whiteboardDrag = {
    mode: "pan",
    documentId: state.activeDocument,
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    viewportX: viewport.x,
    viewportY: viewport.y,
    zoom: viewport.zoom,
    beforeCanvas: whiteboardCanvasSnapshot(documentState.canvas),
    pending: null,
    frame: 0,
  };
  elements.whiteboardEditor.classList.add("panning");
};

const whiteboardTextareaScrollbarHit = (event, field) => {
  if (!field || field.scrollHeight <= field.clientHeight) return false;
  const rect = field.getBoundingClientRect();
  const gutterWidth = Math.max(12, field.offsetWidth - field.clientWidth);
  return event.clientX >= rect.right - gutterWidth;
};

const whiteboardNativeMediaControlHit = (event) => {
  const media = event.target.closest?.("audio, video");
  if (!media) return false;
  if (media.matches("audio")) return true;
  const rect = media.getBoundingClientRect();
  const nativeControlBand = Math.min(48, Math.max(32, rect.height * 0.3));
  return event.clientY >= rect.bottom - nativeControlBand;
};

const createWhiteboardConnectedEdgePreview = (canvas, nodeIds = []) => {
  const normalized = normalizeCanvas(canvas);
  const movingIds = new Set(nodeIds.filter(Boolean));
  const nodesById = new Map(normalized.nodes.map((node) => [node.id, node]));
  return {
    nodesById,
    edges: normalized.edges
      .filter((edge) => movingIds.has(edge.fromNode) || movingIds.has(edge.toNode))
      .map((edge) => ({
        edge,
        group: elements.whiteboardSurface.querySelector(`[data-canvas-edge="${CSS.escape(edge.id)}"]`),
      }))
      .filter((record) => record.group),
  };
};

const updateWhiteboardConnectedEdgePreview = (drag) => {
  const preview = drag?.edgePreview;
  if (!preview || !drag.pending || !["card", "resize"].includes(drag.mode)) return;
  const overrides = new Map();
  if (drag.mode === "resize") {
    const node = preview.nodesById.get(drag.nodeId);
    if (node) overrides.set(drag.nodeId, { ...node, ...drag.pending });
  } else {
    const deltaX = drag.pending.x - drag.nodeX;
    const deltaY = drag.pending.y - drag.nodeY;
    const node = preview.nodesById.get(drag.nodeId);
    if (node) overrides.set(drag.nodeId, { ...node, x: drag.pending.x, y: drag.pending.y });
    for (const member of drag.groupMembers ?? []) {
      const memberNode = preview.nodesById.get(member.id);
      if (memberNode) overrides.set(member.id, { ...memberNode, x: member.x + deltaX, y: member.y + deltaY });
    }
  }
  for (const record of preview.edges) {
    const { edge } = record;
    let { group } = record;
    if (!group?.isConnected) {
      group = elements.whiteboardSurface.querySelector(`[data-canvas-edge="${CSS.escape(edge.id)}"]`);
      record.group = group;
    }
    if (!group) continue;
    const fromNode = overrides.get(edge.fromNode) ?? preview.nodesById.get(edge.fromNode);
    const toNode = overrides.get(edge.toNode) ?? preview.nodesById.get(edge.toNode);
    if (!fromNode || !toNode) continue;
    const path = whiteboardEdgePath(
      whiteboardNodeSidePoint(fromNode, edge.fromSide),
      whiteboardNodeSidePoint(toNode, edge.toSide),
    );
    for (const pathElement of group.querySelectorAll("path")) pathElement.setAttribute("d", path);
  }
};

const scheduleWhiteboardDragPreview = (drag) => {
  if (drag.frame) return;
  drag.frame = requestAnimationFrame(() => {
    drag.frame = 0;
    if (ui.whiteboardDrag === drag) applyWhiteboardDragPreview(drag);
  });
};

const flushWhiteboardDragPreview = (drag) => {
  if (!drag) return;
  if (drag.frame) cancelAnimationFrame(drag.frame);
  drag.frame = 0;
  applyWhiteboardDragPreview(drag);
};

let whiteboardNodeCreateIntent = null;

const setWhiteboardNodeCreateIntent = (intent) => {
  whiteboardNodeCreateIntent = {
    ...intent,
    workspaceId: workspaceIdentity(),
    documentId: state.activeDocument,
    sourceIds: [...new Set((intent.sourceIds ?? []).map(String).filter(Boolean))],
  };
  return whiteboardNodeCreateIntent;
};

const closeWhiteboardNodeCreateMenu = () => {
  const hadPendingIntent = Boolean(whiteboardNodeCreateIntent);
  whiteboardNodeCreateIntent = null;
  elements.whiteboardNodeCreateMenu.hidden = true;
  if (hadPendingIntent && ui.whiteboardEdgeDraft) {
    ui.whiteboardEdgeDraft = null;
    elements.whiteboardSurface.querySelector(".whiteboard-edge.draft")?.remove();
  }
};

const whiteboardNodeCreateChannelAvailable = (kind) => {
  if (kind === "plain") return true;
  if (kind === "text") return hasAvailableTextGenerationExecutor();
  if (kind === "image") return visibleGenerationPickerProfiles(state.settings, "image").length > 0;
  if (kind === "video") return visibleGenerationPickerProfiles(state.settings, "video").length > 0;
  if (kind === "audio") return availableGenerationConnections("audio").length > 0;
  return false;
};

const openWhiteboardNodeCreateMenu = (intent) => {
  setWhiteboardNodeCreateIntent(intent);
  const unavailableMessages = {
    text: "请先连接可用的 Chat 模型或 Agent 引擎",
    image: "请先配置可用的图片 API 或 CLI 连接",
    video: "请先配置可用的视频 API 或 CLI 连接",
    audio: "请先配置并核验可用的音频 API 或 CLI 连接",
  };
  elements.whiteboardNodeCreateMenu.querySelectorAll("[data-whiteboard-node-create]").forEach((button) => {
    const kind = button.dataset.whiteboardNodeCreate;
    const available = whiteboardNodeCreateChannelAvailable(kind);
    button.hidden = kind !== "plain" && !available;
    button.disabled = !available;
    if (available) button.removeAttribute("title");
    else button.title = unavailableMessages[kind] || "当前生成类型不可用";
  });
  positionContextMenu(elements.whiteboardNodeCreateMenu, { x: intent.clientX, y: intent.clientY });
  requestAnimationFrame(() => elements.whiteboardNodeCreateMenu.querySelector("button:not(:disabled)")?.focus());
};

const commitWhiteboardNodeCreateIntent = (kind) => {
  const intent = whiteboardNodeCreateIntent;
  if (!intent || !["plain", "text", "image", "video", "audio"].includes(kind)) return false;
  if (!whiteboardNodeCreateChannelAvailable(kind)) return false;
  const documentState = activeWhiteboardDocument();
  const sourceIds = intent.sourceIds.filter((nodeId) => whiteboardNodeById(nodeId, documentState));
  if (
    !documentState
    || intent.workspaceId !== workspaceIdentity()
    || intent.documentId !== state.activeDocument
    || sourceIds.length !== intent.sourceIds.length
  ) {
    closeWhiteboardNodeCreateMenu();
    showToast("白板或来源卡片已变化，请重新拖拽连接");
    return false;
  }
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const nodeId = uid("canvas-node");
  const width = 260;
  const height = 160;
  let nextCanvas = addCanvasTextNode(documentState.canvas, {
    id: nodeId,
    text: "",
    kind: "text",
    width,
    height,
    x: snapCanvasValue(intent.point.x - width / 2, documentState.canvas),
    y: snapCanvasValue(intent.point.y - height / 2, documentState.canvas),
  });
  const connections = sourceIds.map((sourceId) => intent.direction === "input"
    ? { fromNode: nodeId, toNode: sourceId }
    : { fromNode: sourceId, toNode: nodeId });
  nextCanvas = connections.reduce((canvas, connection) => addCanvasEdge(canvas, connection), nextCanvas);
  const channel = kind === "plain" ? "text" : kind;
  const capacity = checkWhiteboardReferenceCapacity(nextCanvas, connections.map((connection) => connection.toNode), {
    channel,
    operation: kind === "plain" ? "connect" : "generate",
    bulk: connections.length > 1,
  });
  if (!capacity.ok) {
    closeWhiteboardNodeCreateMenu();
    return false;
  }
  closeWhiteboardNodeCreateMenu();
  documentState.canvas = nextCanvas;
  documentState.updatedAt = nowTime();
  const sourceLabel = intent.origin === "canvas-context" ? "右键" : "拖拽";
  pushWhiteboardHistory(beforeCanvas, { label: kind === "plain" ? `${sourceLabel}新建普通卡片` : `${sourceLabel}新建${whiteboardGenerationSessionTitle(channel)}卡片` });
  persist({ documentIds: [state.activeDocument] });
  renderWhiteboard(documentState);
  selectWhiteboardNode(nodeId);
  if (kind === "text") openWhiteboardGenerateDialog(nodeId);
  else if (kind === "image") openWhiteboardImageDialog(nodeId);
  else if (kind === "video") openWhiteboardVideoDialog(nodeId);
  else if (kind === "audio") openWhiteboardAudioDialog(nodeId);
  return true;
};

const syncWhiteboardGenerationMenuCapabilities = (target) => {
  const imageAvailable = availableGenerationConnections("image").length > 0;
  const videoAvailable = availableGenerationConnections("video").length > 0;
  const capabilityCount = 1 + Number(imageAvailable) + Number(videoAvailable);
  const cardTarget = target === "card";
  const toggle = elements.whiteboardMenu.querySelector('[data-whiteboard-action="toggle-generate"]');
  const directText = elements.whiteboardMenu.querySelector("[data-whiteboard-direct-generation]");
  const submenu = elements.whiteboardMenu.querySelector("#whiteboardGenerateMenu");
  const imageGenerate = submenu?.querySelector('[data-whiteboard-action="generate-image"]');
  const videoGenerate = submenu?.querySelector('[data-whiteboard-action="generate-video"]');
  if (toggle) {
    toggle.hidden = !cardTarget || capabilityCount < 2;
    toggle.setAttribute("aria-expanded", "false");
  }
  if (directText) directText.hidden = !cardTarget || capabilityCount !== 1;
  if (submenu) submenu.hidden = true;
  if (imageGenerate) {
    imageGenerate.hidden = !imageAvailable;
    imageGenerate.disabled = false;
    imageGenerate.removeAttribute("title");
  }
  if (videoGenerate) {
    videoGenerate.hidden = !videoAvailable;
    videoGenerate.disabled = false;
    videoGenerate.classList.remove("needs-configuration");
    videoGenerate.removeAttribute("title");
  }
  elements.whiteboardMenu.querySelectorAll("[data-whiteboard-canvas-create]").forEach((button) => {
    const kind = button.dataset.whiteboardCanvasCreate;
    button.hidden = target !== "canvas" || !whiteboardNodeCreateChannelAvailable(kind);
  });
  elements.whiteboardMenu.dataset.generationCapabilities = [
    "text",
    ...(imageAvailable ? ["image"] : []),
    ...(videoAvailable ? ["video"] : []),
  ].join(" ");
};

const collapseWhiteboardContextMenu = ({ hide = true } = {}) => {
  closeWhiteboardNodeCreateMenu();
  elements.whiteboardMenu.querySelectorAll("[data-whiteboard-collapsible]").forEach((item) => {
    item.hidden = true;
  });
  elements.whiteboardMenu.querySelectorAll('[data-whiteboard-action^="toggle-"]').forEach((item) => {
    item.setAttribute("aria-expanded", "false");
  });
  if (hide) elements.whiteboardMenu.hidden = true;
};

const captureWhiteboardSpaceTextSnapshot = (target) => {
  const field = target?.closest?.(".whiteboard-generation-popover input, .whiteboard-generation-popover textarea, .whiteboard-generation-popover [contenteditable='true']");
  if (!field) return null;
  const source = field.closest(".whiteboard-generation-prompt-editor")?.querySelector(".whiteboard-generation-prompt-source") ?? null;
  return {
    field,
    kind: field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement ? "value" : "html",
    value: field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement ? field.value : field.innerHTML,
    source,
    sourceValue: source?.value ?? "",
  };
};

const restoreWhiteboardSpaceTextSnapshotForPan = () => {
  const snapshot = ui.whiteboardSpaceTextSnapshot;
  ui.whiteboardSpaceTextSnapshot = null;
  if (!snapshot?.field?.isConnected) return;
  if (snapshot.kind === "value") snapshot.field.value = snapshot.value;
  else snapshot.field.innerHTML = snapshot.value;
  if (snapshot.source?.isConnected) snapshot.source.value = snapshot.sourceValue;
  snapshot.field.dispatchEvent(new Event("input", { bubbles: true }));
  const dialog = snapshot.field.closest(".whiteboard-generation-popover");
  if (dialog?.open) saveWhiteboardGenerationDraft(dialog, { active: true, open: true });
};

elements.whiteboardEditor.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) return;
  if (event.target.closest(".whiteboard-find-panel")) {
    event.stopPropagation();
    return;
  }
  // Do not let the canvas drag/marquee handler consume pointerdown from an
  // anchored generation form. Leaving the native default intact is required
  // for contenteditable prompt fields to receive the caret and keyboard input.
  if (event.target.closest(".whiteboard-generation-popover")) {
    event.stopPropagation();
    return;
  }
  flushWhiteboardWheelZoom();
  commitWhiteboardViewportGesture();
  collapseWhiteboardContextMenu();
  if (ui.whiteboardSpacePressed) restoreWhiteboardSpaceTextSnapshotForPan();
  if (whiteboardGenerationDialogs().some((dialog) => dialog.open && dialog.contains(document.activeElement))) {
    document.activeElement.blur();
  }
  if (event.target.closest("[data-whiteboard-candidate-action], [data-media-job-action]")) {
    event.stopPropagation();
    return;
  }
  const documentState = activeWhiteboardDocument();
  if (!documentState) return;
  if (!ui.whiteboardSpacePressed) closeWhiteboardGenerationDialogsOutside(event.target);
  const activeEditingCard = ui.whiteboardEditingNodeId
    ? event.target.closest(`[data-canvas-node="${CSS.escape(ui.whiteboardEditingNodeId)}"]`)
    : null;
  if (ui.whiteboardEditingNodeId && !activeEditingCard) finishWhiteboardEditing();
  if (ui.whiteboardSpacePressed) {
    startWhiteboardPan(event, documentState);
    return;
  }
  const multiHandle = event.target.closest("[data-whiteboard-multi-handle]");
  if (multiHandle) {
    const nodeIds = selectedWhiteboardNodeIds();
    const bounds = canvasSelectionBounds(documentState.canvas, nodeIds);
    if (!bounds || nodeIds.length < 2) return;
    event.preventDefault();
    event.stopPropagation();
    elements.whiteboardEditor.setPointerCapture?.(event.pointerId);
    const direction = multiHandle.dataset.whiteboardMultiHandle;
    elements.whiteboardEditor.dataset.edgeTargetHandle = direction === "input" ? "output" : "input";
    const sourcePoint = {
      x: direction === "input" ? bounds.left : bounds.right,
      y: bounds.top + bounds.height / 2,
    };
    const editorRect = elements.whiteboardEditor.getBoundingClientRect();
    const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState, editorRect);
    ui.whiteboardEdgeDraft = { fromPoint: sourcePoint, x: point.x, y: point.y };
    ui.whiteboardDrag = {
      mode: "multi-edge",
      documentId: state.activeDocument,
      pointerId: event.pointerId,
      direction,
      nodeIds,
      sourcePoint,
      editorRect,
      beforeCanvas: whiteboardCanvasSnapshot(documentState.canvas),
      pending: point,
      frame: 0,
    };
    renderWhiteboard(documentState);
    return;
  }
  const edge = event.target.closest("[data-canvas-edge]");
  if (edge) {
    event.preventDefault();
    event.stopPropagation();
    finishWhiteboardEditing();
    selectWhiteboardEdge(edge.dataset.canvasEdge);
    return;
  }
  const card = event.target.closest("[data-canvas-node]");
  const cardTextarea = event.target.closest("textarea[data-canvas-text]");
  const modifierSelection = Boolean(card && (event.ctrlKey || event.metaKey)
    && !event.target.closest("button, input, select, textarea, a, audio, video, [contenteditable='true'], [data-canvas-handle], [data-canvas-resize]"));
  if (modifierSelection) {
    event.stopPropagation();
    ui.whiteboardModifierSelectionPointer = {
      pointerId: event.pointerId,
      documentId: state.activeDocument,
      nodeId: card.dataset.canvasNode,
    };
    return;
  }
  if (cardTextarea && ui.whiteboardEditingNodeId !== card?.dataset.canvasNode && whiteboardTextareaScrollbarHit(event, cardTextarea)) return;
  if (card && !selectedWhiteboardNodeIds().includes(card.dataset.canvasNode)) selectWhiteboardNode(card.dataset.canvasNode);
  if (cardTextarea && ui.whiteboardEditingNodeId !== card?.dataset.canvasNode) {
    event.preventDefault();
  }
  const handle = event.target.closest("[data-canvas-handle]");
  if (handle?.dataset.canvasHandle === "output" && card) {
    event.preventDefault();
    event.stopPropagation();
    const editorRect = elements.whiteboardEditor.getBoundingClientRect();
    const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState, editorRect);
    const source = whiteboardNodeById(card.dataset.canvasNode, documentState);
    ui.whiteboardEdgeDraft = { fromNode: card.dataset.canvasNode, x: point.x, y: point.y };
    ui.whiteboardDrag = {
      mode: "edge",
      documentId: state.activeDocument,
      pointerId: event.pointerId,
      nodeId: card.dataset.canvasNode,
      beforeCanvas: whiteboardCanvasSnapshot(documentState.canvas),
      sourcePoint: source ? whiteboardNodeSidePoint(source, "right") : null,
      editorRect,
      pending: point,
      frame: 0,
    };
    renderWhiteboard(documentState);
    return;
  }
  const resizeHandle = event.target.closest("[data-canvas-resize]");
  if (resizeHandle && card) {
    event.preventDefault();
    event.stopPropagation();
    const node = whiteboardNodeById(card.dataset.canvasNode, documentState);
    if (!node) return;
    ui.whiteboardDrag = {
      mode: "resize",
      documentId: state.activeDocument,
      pointerId: event.pointerId,
      nodeId: node.id,
      startX: event.clientX,
      startY: event.clientY,
      nodeWidth: node.width,
      nodeHeight: node.height,
      nodeX: node.x,
      nodeY: node.y,
      resizeCorner: resizeHandle.dataset.canvasResize || "se",
      nodeKind: node.kind,
      nodeAspectRatio: node.aspectRatio,
      zoom: whiteboardViewport(documentState).zoom,
      canvasSettings: { ...(documentState.canvas.settings ?? {}) },
      beforeCanvas: whiteboardCanvasSnapshot(documentState.canvas),
      card,
      edgePreview: createWhiteboardConnectedEdgePreview(documentState.canvas, [node.id]),
      pending: null,
      frame: 0,
    };
    card.classList.add("dragging");
    return;
  }
  if (card && ui.whiteboardEditingNodeId === card.dataset.canvasNode) return;
  if (event.target.closest("a, button, input, select, [contenteditable='true']") && !event.target.closest("[data-whiteboard-drag-handle]")) return;
  if (whiteboardNativeMediaControlHit(event)) return;
  if (card) {
    const normalizedCanvas = normalizeCanvas(documentState.canvas);
    const node = normalizedCanvas.nodes.find((item) => item.id === card.dataset.canvasNode);
    if (!node) return;
    const selectionIds = selectedWhiteboardNodeIds();
    const memberIds = selectionIds.length > 1
      ? selectionIds.filter((id) => id !== node.id)
      : node.kind === "group" ? containedCanvasNodeIds(normalizedCanvas, node.id) : [];
    const groupMembers = memberIds.map((id) => {
      const member = normalizedCanvas.nodes.find((item) => item.id === id);
      const memberCard = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(id)}"]`);
      return member && memberCard ? { id, x: member.x, y: member.y, card: memberCard } : null;
    }).filter(Boolean);
    ui.whiteboardDrag = {
      mode: "card-pending",
      documentId: state.activeDocument,
      pointerId: event.pointerId,
      nodeId: node.id,
      startX: event.clientX,
      startY: event.clientY,
      nodeX: node.x,
      nodeY: node.y,
      zoom: whiteboardViewport(documentState).zoom,
      canvasSettings: { ...(documentState.canvas.settings ?? {}) },
      beforeCanvas: whiteboardCanvasSnapshot(documentState.canvas),
      card,
      groupMembers,
      edgePreview: createWhiteboardConnectedEdgePreview(normalizedCanvas, [node.id, ...memberIds]),
      pending: null,
      frame: 0,
    };
    return;
  }
  event.preventDefault();
  selectWhiteboardNode(null);
  const editorRect = elements.whiteboardEditor.getBoundingClientRect();
  ui.whiteboardDrag = {
    mode: "select",
    documentId: state.activeDocument,
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    startWorld: whiteboardWorldPoint(event.clientX, event.clientY, documentState, editorRect),
    editorRect,
    pending: { clientX: event.clientX, clientY: event.clientY },
    frame: 0,
  };
  elements.whiteboardMarquee.style.left = `${event.clientX - editorRect.left}px`;
  elements.whiteboardMarquee.style.top = `${event.clientY - editorRect.top}px`;
  elements.whiteboardMarquee.style.width = "0";
  elements.whiteboardMarquee.style.height = "0";
  elements.whiteboardMarquee.hidden = false;
});

document.addEventListener("pointermove", (event) => {
  const drag = ui.whiteboardDrag;
  const documentState = activeWhiteboardDocument();
  if (!drag || drag.pointerId !== event.pointerId || drag.documentId !== state.activeDocument || !documentState) return;
  if (["edge", "multi-edge"].includes(drag.mode)) {
    const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState, drag.editorRect);
    drag.pending = point;
    scheduleWhiteboardDragPreview(drag);
    return;
  }
  if (drag.mode === "pan") {
    drag.pending = {
      x: drag.viewportX + event.clientX - drag.startX,
      y: drag.viewportY + event.clientY - drag.startY,
    };
    scheduleWhiteboardDragPreview(drag);
    return;
  }
  if (drag.mode === "select") {
    drag.pending = { clientX: event.clientX, clientY: event.clientY };
    scheduleWhiteboardDragPreview(drag);
    return;
  }
  const deltaX = event.clientX - drag.startX;
  const deltaY = event.clientY - drag.startY;
  if (drag.mode === "resize") {
    const corner = drag.resizeCorner || "se";
    const worldDeltaX = deltaX / drag.zoom;
    const worldDeltaY = deltaY / drag.zoom;
    const west = corner.includes("w");
    const north = corner.includes("n");
    const aspectRatio = Math.max(0.1, Number(drag.nodeAspectRatio) || drag.nodeWidth / drag.nodeHeight || 1);
    const horizontalWidth = drag.nodeWidth + (west ? -worldDeltaX : worldDeltaX);
    const verticalHeight = drag.nodeHeight + (north ? -worldDeltaY : worldDeltaY);
    const verticalWidth = verticalHeight * aspectRatio;
    const rawWidth = ["image", "video", "audio"].includes(drag.nodeKind)
      && Math.abs(verticalWidth - drag.nodeWidth) > Math.abs(horizontalWidth - drag.nodeWidth)
      ? verticalWidth
      : horizontalWidth;
    const width = snapCanvasValue(Math.max(180, rawWidth), drag.canvasSettings);
    const height = ["image", "video", "audio"].includes(drag.nodeKind)
      ? Math.max(100, width / aspectRatio)
      : snapCanvasValue(Math.max(100, drag.nodeHeight + (north ? -worldDeltaY : worldDeltaY)), drag.canvasSettings);
    drag.pending = {
      x: west ? drag.nodeX + drag.nodeWidth - width : drag.nodeX,
      y: north ? drag.nodeY + drag.nodeHeight - height : drag.nodeY,
      width,
      height,
    };
    scheduleWhiteboardDragPreview(drag);
    return;
  }
  if (drag.mode === "card-pending") {
    if (Math.hypot(deltaX, deltaY) < 4) return;
    drag.mode = "card";
    finishWhiteboardEditing();
    drag.card.classList.add("dragging");
    for (const member of drag.groupMembers ?? []) member.card.classList.add("dragging");
    drag.pausedVideos = [drag.card, ...(drag.groupMembers ?? []).map((member) => member.card)]
      .flatMap((item) => [...(item?.querySelectorAll("video") ?? [])])
      .map((video) => ({ video, resume: !video.paused }))
      .filter(({ video, resume }) => {
        if (resume) video.pause();
        return true;
      });
  }
  if (drag.mode === "card") event.preventDefault();
  const x = snapCanvasValue(drag.nodeX + deltaX / drag.zoom, drag.canvasSettings);
  const y = snapCanvasValue(drag.nodeY + deltaY / drag.zoom, drag.canvasSettings);
  drag.pending = { x, y };
  scheduleWhiteboardDragPreview(drag);
});

document.addEventListener("pointerup", (event) => {
  if (ui.whiteboardModifierSelectionPointer?.pointerId === event.pointerId) ui.whiteboardModifierSelectionPointer = null;
  const drag = ui.whiteboardDrag;
  if (!drag || drag.pointerId !== event.pointerId) return;
  const documentState = activeWhiteboardDocument();
  let createdNodeId = "";
  let selectionChanged = false;
  let edgeChanged = false;
  let pendingNodeCreateIntent = null;
  flushWhiteboardDragPreview(drag);
  if (["edge", "multi-edge"].includes(drag.mode) && documentState) {
    const dropElement = document.elementFromPoint(event.clientX, event.clientY);
    const targetHandleKind = drag.mode === "multi-edge" && drag.direction === "input" ? "output" : "input";
    const sourceIds = drag.mode === "multi-edge" ? drag.nodeIds : [drag.nodeId];
    const stackedElements = typeof document.elementsFromPoint === "function"
      ? document.elementsFromPoint(event.clientX, event.clientY)
      : [dropElement].filter(Boolean);
    const targetHandle = stackedElements
      .map((element) => element?.closest?.(`[data-canvas-handle="${targetHandleKind}"]`))
      .find((element) => element?.closest?.("[data-canvas-node]") && !sourceIds.includes(element.closest("[data-canvas-node]").dataset.canvasNode));
    // A group connector is much easier to use when the entire existing card is
    // a valid drop target. Handles remain the precise target, while card-body
    // fallback prevents an accidental blank-canvas node from being created.
    const targetCard = targetHandle?.closest?.("[data-canvas-node]")
      || stackedElements
        .map((element) => element?.closest?.("[data-canvas-node]"))
        .find((element) => element?.dataset.canvasNode && !sourceIds.includes(element.dataset.canvasNode));
    const geometricTargetId = canvasNodeIdAtPoint({
      nodes: normalizeCanvas(documentState.canvas).nodes,
      point: whiteboardWorldPoint(event.clientX, event.clientY, documentState, drag.editorRect),
      excludedNodeIds: sourceIds,
      padding: 8 / Math.max(0.2, normalizeCanvas(documentState.canvas).viewport.zoom),
    });
    const targetNodeId = targetCard?.dataset.canvasNode || geometricTargetId;
    if (targetNodeId && !sourceIds.includes(targetNodeId)) {
      const connections = sourceIds.map((sourceId) => drag.mode === "multi-edge" && drag.direction === "input"
        ? { fromNode: targetNodeId, toNode: sourceId }
        : { fromNode: sourceId, toNode: targetNodeId });
      const nextCanvas = connections.reduce((next, connection) => addCanvasEdge(next, connection), documentState.canvas);
      edgeChanged = normalizeCanvas(nextCanvas).edges.length > normalizeCanvas(documentState.canvas).edges.length;
      if (edgeChanged) {
        const capacity = checkWhiteboardReferenceCapacity(nextCanvas, connections.map((connection) => connection.toNode), {
          bulk: drag.mode === "multi-edge" || connections.length > 1,
        });
        if (capacity.ok) documentState.canvas = nextCanvas;
        else edgeChanged = false;
      }
    } else {
      const editorBounds = drag.editorRect || elements.whiteboardEditor.getBoundingClientRect();
      const insideEditor = event.clientX >= editorBounds.left && event.clientX <= editorBounds.right
        && event.clientY >= editorBounds.top && event.clientY <= editorBounds.bottom;
      const blockedByControl = stackedElements.some((element) => element?.closest?.("button, input, select, textarea, [contenteditable='true'], [data-canvas-edge], .whiteboard-generation-popover"));
      const blankCanvasDrop = insideEditor && !blockedByControl;
      if (blankCanvasDrop) {
        const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState, drag.editorRect);
        pendingNodeCreateIntent = {
          point,
          clientX: event.clientX,
          clientY: event.clientY,
          sourceIds,
          direction: drag.mode === "multi-edge" && drag.direction === "input" ? "input" : "output",
        };
      }
    }
    // Keep the dropped connector visible while the user chooses which card to
    // create. It becomes a formal edge on commit and is removed only when the
    // pending create intent is cancelled.
    if (!pendingNodeCreateIntent) ui.whiteboardEdgeDraft = null;
  }
  if (drag.mode === "select" && documentState) {
    const end = whiteboardWorldPoint(drag.pending?.clientX ?? event.clientX, drag.pending?.clientY ?? event.clientY, documentState, drag.editorRect);
    const selectionRect = {
      left: drag.startWorld.x,
      top: drag.startWorld.y,
      right: end.x,
      bottom: end.y,
    };
    const ids = canvasNodeIdsInRect(documentState.canvas, selectionRect);
    const edgeIds = canvasEdgeIdsInRect(documentState.canvas, selectionRect);
    const thinConnectorMarquee = Math.min(
      Math.abs(selectionRect.right - selectionRect.left),
      Math.abs(selectionRect.bottom - selectionRect.top),
    ) <= 32;
    if (edgeIds.length && thinConnectorMarquee) selectWhiteboardEdges(edgeIds);
    else if (ids.length) selectWhiteboardNodes(ids);
    else selectWhiteboardEdges(edgeIds);
    selectionChanged = true;
  }
  const changed = ["card", "pan", "resize"].includes(drag.mode) && Boolean(drag.pending);
  const canFinalizeGeometryInPlace = Boolean(
    documentState
    && changed
    && !drag.deferredRender
    && ["card", "pan", "resize"].includes(drag.mode),
  );
  if (documentState && changed) {
    if (drag.mode === "card") {
      const deltaX = drag.pending.x - drag.nodeX;
      const deltaY = drag.pending.y - drag.nodeY;
      documentState.canvas = updateCanvasNodes(documentState.canvas, [
        { id: drag.nodeId, ...drag.pending },
        ...(drag.groupMembers ?? []).map((member) => ({ id: member.id, x: member.x + deltaX, y: member.y + deltaY })),
      ]);
    }
    else if (drag.mode === "resize") documentState.canvas = updateCanvasNode(documentState.canvas, drag.nodeId, drag.pending);
    else documentState.canvas = updateCanvasViewport(documentState.canvas, drag.pending);
  }
  drag.card?.classList.remove("dragging");
  if (drag.card) {
    drag.card.style.transform = "";
    if (canFinalizeGeometryInPlace && drag.mode === "card") {
      drag.card.style.left = `${drag.pending.x}px`;
      drag.card.style.top = `${drag.pending.y}px`;
    } else if (drag.mode === "resize" && !canFinalizeGeometryInPlace) {
      drag.card.style.left = "";
      drag.card.style.top = "";
      drag.card.style.width = "";
      drag.card.style.height = "";
    }
  }
  for (const member of drag.groupMembers ?? []) {
    member.card.classList.remove("dragging");
    member.card.style.transform = "";
    if (canFinalizeGeometryInPlace && drag.mode === "card") {
      member.card.style.left = `${member.x + drag.pending.x - drag.nodeX}px`;
      member.card.style.top = `${member.y + drag.pending.y - drag.nodeY}px`;
    }
  }
  for (const { video, resume } of drag.pausedVideos ?? []) {
    if (resume && video.isConnected) void video.play().catch(() => {});
  }
  drag.captureElement?.classList.remove("is-dragging");
  if (drag.captureElement?.hasPointerCapture?.(drag.pointerId)) {
    drag.captureElement.releasePointerCapture(drag.pointerId);
  }
  elements.whiteboardEditor.classList.remove("panning");
  delete elements.whiteboardEditor.dataset.edgeTargetHandle;
  elements.whiteboardMarquee.hidden = true;
  elements.whiteboardMultiSelection.style.transform = "";
  if (drag.mode === "select"
    || (drag.mode === "pan" && drag.pending)
    || (drag.mode === "card" && drag.pending)
    || pendingNodeCreateIntent
    || (["edge", "multi-edge"].includes(drag.mode) && edgeChanged)) {
    ui.whiteboardIgnoreClick = true;
    // Chromium may dispatch the synthetic click from a completed drag in a
    // later task (not the pointerup task). Keep the guard alive briefly so an
    // edge drop on blank canvas cannot immediately close the attached composer
    // or select the newly-created downstream card by accident.
    setTimeout(() => { ui.whiteboardIgnoreClick = false; }, 160);
  }
  ui.whiteboardDrag = null;
  if (documentState && changed) {
    documentState.updatedAt = nowTime();
    persist({ documentIds: [state.activeDocument] });
  }
  if (documentState && edgeChanged) {
    documentState.updatedAt = nowTime();
    persist({ documentIds: [state.activeDocument] });
  }
  if (documentState && drag.beforeCanvas && (["card", "resize", "pan"].includes(drag.mode) || (["edge", "multi-edge"].includes(drag.mode) && edgeChanged))) {
    const label = drag.mode === "card" ? drag.groupMembers?.length ? "移动选中节点" : "移动卡片" : drag.mode === "resize" ? "调整卡片大小" : ["edge", "multi-edge"].includes(drag.mode) ? createdNodeId ? "新建并连接节点" : drag.mode === "multi-edge" ? "批量连接节点" : "连接卡片" : "移动白板视图";
    pushWhiteboardHistory(drag.beforeCanvas, { label });
  }
  if (documentState && canFinalizeGeometryInPlace && drag.mode === "pan" && elements.whiteboardEditor.dataset.virtualized === "true") {
    renderWhiteboard(documentState);
  } else if (documentState && canFinalizeGeometryInPlace) {
    renderWhiteboardMultiSelection(documentState);
    scheduleWhiteboardGenerationDialogPosition();
  } else if (documentState && (changed || selectionChanged || drag.deferredRender || ["edge", "multi-edge"].includes(drag.mode))) {
    renderWhiteboard(documentState);
    if (createdNodeId) selectWhiteboardNode(createdNodeId);
  }
  if (pendingNodeCreateIntent) openWhiteboardNodeCreateMenu(pendingNodeCreateIntent);
  // A normal click only selects. The shared AI operation bar is opened solely
  // by an explicit triple click, so closing it cannot be undone accidentally.
});

document.addEventListener("pointercancel", (event) => {
  if (ui.whiteboardModifierSelectionPointer?.pointerId === event.pointerId) ui.whiteboardModifierSelectionPointer = null;
  if (ui.whiteboardDrag?.pointerId !== event.pointerId) return;
  if (["edge", "multi-edge"].includes(ui.whiteboardDrag.mode)) ui.whiteboardEdgeDraft = null;
  delete elements.whiteboardEditor.dataset.edgeTargetHandle;
  ui.whiteboardDrag = null;
  const documentState = activeWhiteboardDocument();
  if (documentState) renderWhiteboard(documentState);
});

elements.whiteboardEditor.addEventListener("wheel", (event) => {
  if (!event.ctrlKey) return;
  const documentState = activeWhiteboardDocument();
  if (!documentState) return;
  event.preventDefault();
  const rect = elements.whiteboardEditor.getBoundingClientRect();
  const identity = `${workspaceIdentity()}::${state.activeDocument}`;
  const pending = ui.whiteboardWheelZoom?.identity === identity ? ui.whiteboardWheelZoom : null;
  const viewport = normalizeCanvas(documentState.canvas).viewport;
  scheduleWhiteboardWheelZoom({
    identity,
    zoom: (pending?.zoom ?? viewport.zoom) * Math.exp(-event.deltaY * 0.0015),
    localX: event.clientX - rect.left,
    localY: event.clientY - rect.top,
  });
}, { passive: false });

const updateWhiteboardCardsColor = (nodeIds, color) => {
  const documentState = activeWhiteboardDocument();
  const ids = [...new Set((nodeIds || []).map(String).filter(Boolean))];
  if (!documentState || !ids.length) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  documentState.canvas = updateCanvasNodes(documentState.canvas, ids.map((id) => ({ id, color })));
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: ids.length > 1 ? `修改 ${ids.length} 张卡片颜色` : "修改卡片颜色" });
  persist();
  renderWhiteboard(documentState);
  selectWhiteboardNodes(ids);
  return true;
};

const exportWhiteboardCards = async (nodeIds = []) => {
  const ids = [...new Set(nodeIds.map(String).filter(Boolean))];
  if (!ids.length) return false;
  for (const nodeId of ids) await exportWhiteboardCard(nodeId);
  if (ids.length > 1) showToast(`已完成 ${ids.length} 张卡片的另存为操作`);
  return true;
};

const focusWhiteboardNodes = (nodeIds = []) => {
  const documentState = activeWhiteboardDocument();
  const ids = [...new Set(nodeIds.map(String).filter(Boolean))].filter((id) => whiteboardNodeById(id, documentState));
  if (!documentState || !ids.length) return false;
  if (ids.length === 1) {
    focusWhiteboardNode(ids[0]);
    return true;
  }
  const bounds = canvasSelectionBounds(documentState.canvas, ids);
  if (!bounds) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const rect = elements.whiteboardEditor.getBoundingClientRect();
  const padding = 80;
  const zoom = Math.max(CANVAS_MIN_ZOOM, Math.min(1.35,
    Math.max(1, rect.width - padding * 2) / Math.max(1, bounds.width),
    Math.max(1, rect.height - padding * 2) / Math.max(1, bounds.height),
  ));
  documentState.canvas = updateCanvasViewport(documentState.canvas, {
    zoom,
    x: rect.width / 2 - (bounds.left + bounds.width / 2) * zoom,
    y: rect.height / 2 - (bounds.top + bounds.height / 2) * zoom,
  });
  ui.whiteboardFocusedNodeId = null;
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: `聚焦 ${ids.length} 张卡片` });
  persist();
  renderWhiteboard(documentState);
  selectWhiteboardNodes(ids);
  return true;
};

const createWhiteboardSelectionGenerationTarget = (nodeIds = [], channel = "text", { centered = false } = {}) => {
  const documentState = activeWhiteboardDocument();
  const ids = [...new Set(nodeIds.map(String).filter(Boolean))].filter((id) => whiteboardNodeById(id, documentState));
  if (!documentState || ids.length < 2) return "";
  const bounds = canvasSelectionBounds(documentState.canvas, ids);
  if (!bounds) return "";
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const targetNodeId = uid("canvas-node");
  const width = 260;
  const height = 160;
  let nextCanvas = addCanvasTextNode(documentState.canvas, {
    id: targetNodeId,
    text: "",
    kind: "text",
    width,
    height,
    x: snapCanvasValue(bounds.right + 120, documentState.canvas),
    y: snapCanvasValue(bounds.top + (bounds.height - height) / 2, documentState.canvas),
  });
  nextCanvas = ids.reduce((canvas, sourceNodeId) => addCanvasEdge(canvas, { fromNode: sourceNodeId, toNode: targetNodeId }), nextCanvas);
  const capacity = checkWhiteboardReferenceCapacity(nextCanvas, [targetNodeId], { channel, operation: "generate", bulk: true });
  if (!capacity.ok) return "";
  documentState.canvas = nextCanvas;
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: `为 ${ids.length} 张卡片创建${whiteboardGenerationSessionTitle(channel)}下游` });
  persist();
  renderWhiteboard(documentState);
  selectWhiteboardNode(targetNodeId);
  if (channel === "image") openWhiteboardImageDialog(targetNodeId, "auto", { centered });
  else if (channel === "video") openWhiteboardVideoDialog(targetNodeId, { centered });
  else openWhiteboardGenerateDialog(targetNodeId, { centered });
  return targetNodeId;
};

elements.whiteboardEditor.addEventListener("contextmenu", (event) => {
  const documentState = activeWhiteboardDocument();
  if (!documentState) return;
  closeWhiteboardNodeCreateMenu();
  event.preventDefault();
  event.stopPropagation();
  const card = event.target.closest("[data-canvas-node]");
  const edge = event.target.closest("[data-canvas-edge]");
  const point = whiteboardWorldPoint(event.clientX, event.clientY, documentState);
  const selectedBeforeContext = selectedWhiteboardNodeIds();
  const keepMultiSelection = Boolean(card && selectedBeforeContext.length > 1 && ui.whiteboardSelectedNodeIds.has(card.dataset.canvasNode));
  const target = card ? "card" : edge ? "edge" : "canvas";
  const contextNode = card ? whiteboardNodeById(card.dataset.canvasNode, documentState) : null;
  if (card) {
    if (!keepMultiSelection) selectWhiteboardNode(card.dataset.canvasNode);
  } else if (edge) selectWhiteboardEdge(edge.dataset.canvasEdge);
  else selectWhiteboardNode(null);
  const contextNodeIds = keepMultiSelection ? selectedBeforeContext : card ? [card.dataset.canvasNode] : [];
  ui.whiteboardContext = {
    target,
    nodeId: card?.dataset.canvasNode ?? null,
    nodeIds: contextNodeIds,
    multiSelection: keepMultiSelection,
    edgeId: edge?.dataset.canvasEdge ?? null,
    x: point.x,
    y: point.y,
    clientX: event.clientX,
    clientY: event.clientY,
  };
  elements.whiteboardMenu.dataset.multiSelection = String(keepMultiSelection);
  const batchActions = new Set(["toggle-generate", "generate-text", "generate-image", "generate-video", "copy", "cut", "duplicate", "save-as", "focus", "arrange", "toggle-color", "delete"]);
  elements.whiteboardMenu.querySelectorAll("[data-whiteboard-target]").forEach((item) => {
    const action = item.dataset.whiteboardAction || "";
    item.hidden = (keepMultiSelection && !batchActions.has(action))
      || !String(item.dataset.whiteboardTarget || "").split(/\s+/).includes(target)
      || item.hasAttribute("data-whiteboard-collapsible")
      || (item.hasAttribute("data-whiteboard-multi-only") && !keepMultiSelection)
      || (item.hasAttribute("data-whiteboard-text-only") && ["image", "video", "audio"].includes(contextNode?.kind))
      || (item.hasAttribute("data-whiteboard-text-transform") && ["image", "video", "audio"].includes(contextNode?.kind))
      || (item.hasAttribute("data-whiteboard-editable-text") && !["text", "generated"].includes(contextNode?.kind))
      || (item.hasAttribute("data-whiteboard-smart-split") && (!["text", "generated"].includes(contextNode?.kind) || !String(contextNode?.text ?? "").trim()))
      || (item.hasAttribute("data-whiteboard-web-reference") && ["image", "video", "audio", "group"].includes(contextNode?.kind))
      || (item.hasAttribute("data-whiteboard-media-only") && !keepMultiSelection && !["image", "video", "audio"].includes(contextNode?.kind));
  });
  elements.whiteboardMenu.querySelectorAll('[data-whiteboard-action^="toggle-"]').forEach((toggle) => {
    toggle.setAttribute("aria-expanded", "false");
  });
  syncWhiteboardGenerationMenuCapabilities(target);
  const pasteButton = elements.whiteboardMenu.querySelector('[data-whiteboard-action="paste"]');
  if (pasteButton) {
    pasteButton.disabled = false;
    pasteButton.title = "粘贴卡片、图片、文件或文字";
  }
  const smartSplitButton = elements.whiteboardMenu.querySelector('[data-whiteboard-action="smart-split"]');
  if (smartSplitButton) {
    smartSplitButton.disabled = Boolean(contextNode && ui.whiteboardSmartSplitNodeIds.has(contextNode.id));
    smartSplitButton.title = smartSplitButton.disabled ? "正在分析拆分节点" : "智能拆分";
  }
  elements.whiteboardMenu.querySelectorAll("[data-whiteboard-color]").forEach((swatch) => {
    const selectedColors = new Set(contextNodeIds.map((id) => whiteboardNodeById(id, documentState)?.color || "default"));
    swatch.setAttribute("aria-pressed", String(selectedColors.size === 1 && selectedColors.has(swatch.dataset.whiteboardColor)));
  });
  positionContextMenu(elements.whiteboardMenu, { x: event.clientX, y: event.clientY });
});

elements.whiteboardEditor.addEventListener("click", (event) => {
  const edge = event.target.closest("[data-canvas-edge]");
  if (!edge) return;
  event.preventDefault();
  event.stopPropagation();
  selectWhiteboardEdge(edge.dataset.canvasEdge);
});

elements.whiteboardEditor.addEventListener("dblclick", (event) => {
  const edge = event.target.closest("[data-canvas-edge]");
  if (!edge) return;
  event.preventDefault();
  event.stopPropagation();
  selectWhiteboardEdge(edge.dataset.canvasEdge);
  deleteWhiteboardEdge(edge.dataset.canvasEdge);
});

elements.whiteboardNodeCreateMenu.addEventListener("click", (event) => {
  const button = event.target.closest("[data-whiteboard-node-create]");
  if (!button || button.disabled) return;
  event.preventDefault();
  event.stopPropagation();
  commitWhiteboardNodeCreateIntent(button.dataset.whiteboardNodeCreate);
});

elements.whiteboardMenu.addEventListener("click", async (event) => {
  event.stopPropagation();
  const color = event.target.closest("[data-whiteboard-color]")?.dataset.whiteboardColor;
  const action = event.target.closest("[data-whiteboard-action]")?.dataset.whiteboardAction;
  const context = ui.whiteboardContext;
  if (color && context?.nodeId) {
    const contextNodeIds = context.multiSelection ? context.nodeIds : [context.nodeId];
    elements.whiteboardMenu.hidden = true;
    updateWhiteboardCardsColor(contextNodeIds, color);
    return;
  }
  const collapsibleMenuId = {
    "toggle-color": "whiteboardColorPalette",
    "toggle-generate": "whiteboardGenerateMenu",
    "toggle-reference": "whiteboardReferenceMenu",
    "toggle-transform": "whiteboardTransformMenu",
  }[action];
  if (collapsibleMenuId && context?.nodeId) {
    const menu = elements.whiteboardMenu.querySelector(`#${collapsibleMenuId}`);
    const toggle = elements.whiteboardMenu.querySelector(`[data-whiteboard-action="${action}"]`);
    const expanded = menu.hidden;
    elements.whiteboardMenu.querySelectorAll("[data-whiteboard-collapsible]").forEach((item) => {
      item.hidden = item !== menu || !expanded;
    });
    elements.whiteboardMenu.querySelectorAll('[data-whiteboard-action^="toggle-"]').forEach((item) => {
      item.setAttribute("aria-expanded", String(item === toggle && expanded));
    });
    requestAnimationFrame(() => {
      // A submenu action can open a generation dialog before this positioning
      // frame runs. Do not resurrect the now-closed context menu over the form.
      if (elements.whiteboardMenu.hidden) return;
      positionContextMenu(elements.whiteboardMenu, {
        x: Number.parseFloat(elements.whiteboardMenu.style.left) || 8,
        y: Number.parseFloat(elements.whiteboardMenu.style.top) || 8,
      });
    });
    return;
  }
  if (!action || !context) return;
  elements.whiteboardMenu.hidden = true;
  const contextNodeIds = context.multiSelection
    ? [...new Set((context.nodeIds || []).map(String).filter(Boolean))]
    : context.nodeId ? [context.nodeId] : [];
  const canvasCreateKind = {
    create: "plain",
    "create-text": "text",
    "create-image": "image",
    "create-video": "video",
    "create-audio": "audio",
  }[action];
  if (canvasCreateKind && context.target === "canvas") {
    setWhiteboardNodeCreateIntent({
      point: { x: context.x, y: context.y },
      clientX: context.clientX,
      clientY: context.clientY,
      sourceIds: [],
      direction: "output",
      origin: "canvas-context",
    });
    commitWhiteboardNodeCreateIntent(canvasCreateKind);
    return;
  }
  if (action === "paste") {
    await pasteIntoWhiteboard({ x: context.x, y: context.y });
    return;
  }
  if (action === "add-web") {
    openTextDialog({
      title: "添加网页",
      label: "网页地址",
      submitLabel: "添加",
      action: { type: "whiteboard-add-web", context: { x: context.x, y: context.y } },
    });
    return;
  }
  if (action === "reference-document") {
    openWhiteboardReferencePanel(context, "documents");
    return;
  }
  if (action === "reference-skill") {
    openWhiteboardReferencePanel(context, "skills");
    return;
  }
  if (action === "reference-book") {
    openWhiteboardReferencePanel(context, "books");
    return;
  }
  if (action === "upload-image") {
    ui.whiteboardImagePoint = { x: context.x, y: context.y, targetNodeId: "" };
    elements.whiteboardImageInput.value = "";
    elements.whiteboardImageInput.click();
    return;
  }
  if (action === "upload-card" && context.nodeId) {
    ui.whiteboardImagePoint = { x: context.x, y: context.y, targetNodeId: context.nodeId };
    elements.whiteboardImageInput.value = "";
    elements.whiteboardImageInput.click();
    return;
  }
  if (action === "reference-web" && context.nodeId) {
    openWhiteboardWebDialog(context.nodeId);
    return;
  }
  const documentState = activeWhiteboardDocument();
  if (!documentState) return;
  if (action === "edit-text" && context.nodeId) {
    const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(context.nodeId)}"]`);
    if (card) startWhiteboardEditing(card);
    return;
  }
  if (action === "upload-skill" && context.nodeId) {
    openSkillEditorFromWhiteboardText(context.nodeId).catch((error) => showToast(error.message || "文字卡片上传 Skill 失败"));
    return;
  }
  if (action === "save-history" && context.nodeId) {
    const documentState = activeWhiteboardDocument();
    const node = whiteboardNodeById(context.nodeId, documentState);
    if (!documentState || !["text", "generated"].includes(node?.kind)) return;
    const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
    const beforeCount = canvasNodeGenerationHistory(documentState.canvas, context.nodeId).length;
    documentState.canvas = snapshotCanvasNodeVersion(documentState.canvas, context.nodeId, { id: uid("canvas-version"), source: "manual" });
    const afterCount = canvasNodeGenerationHistory(documentState.canvas, context.nodeId).length;
    if (afterCount === beforeCount) {
      showToast(String(node.text || "").trim() ? "当前内容已存在于历史版本中，无需重复保存" : "空白卡片不会保存历史版本");
      return;
    }
    documentState.updatedAt = nowTime();
    pushWhiteboardHistory(beforeCanvas, { label: "手动保存卡片历史版本" });
    persist();
    showToast("已保存卡片历史版本");
    return;
  }
  if (action === "history" && context.nodeId) {
    openWhiteboardCardHistory(context.nodeId);
    return;
  }
  if (action === "preview" && context.nodeId) {
    openWhiteboardTextCardPreview(context.nodeId);
    return;
  }
  if (action === "copy" && context.nodeId) {
    copyWhiteboardCards(contextNodeIds);
    return;
  }
  if (action === "cut" && context.nodeId) {
    cutWhiteboardCards(contextNodeIds);
    return;
  }
  if (action === "duplicate" && context.nodeId) {
    duplicateWhiteboardCards(contextNodeIds);
    return;
  }
  if (action === "smart-split" && context.nodeId) {
    smartSplitWhiteboardCard(context.nodeId).catch((error) => showToast(`智能拆分分析失败：${error.message || "未知错误"}`));
    return;
  }
  if (action === "save-as" && context.nodeId) {
    exportWhiteboardCards(contextNodeIds).catch((error) => {
      if (error?.name !== "AbortError") showToast(error.message || "卡片另存失败");
    });
    return;
  }
  if (action === "reveal-media" && context.nodeId) {
    const node = whiteboardNodeById(context.nodeId);
    const relativePath = node?.file || node?.attachment?.relativePath;
    if (relativePath) revealWorkspaceTarget({ relativePath });
    else revealWorkspaceTarget({ fallbackCache: true });
    return;
  }
  if (action === "delete-edge" && context.edgeId) {
    deleteWhiteboardEdge(context.edgeId);
    return;
  }
  if (!context.nodeId) return;
  if (action === "focus") {
    focusWhiteboardNodes(contextNodeIds);
    return;
  }
  if (action === "arrange") {
    if (!context.multiSelection || contextNodeIds.length < 2) {
      showToast("请先多选至少两张卡片，再执行局部整理");
      return;
    }
    if (ui.whiteboardArrangePreview) resolveWhiteboardArrangePreview("restore", { announce: false });
    finishWhiteboardEditing();
    const layoutCanvas = localWhiteboardArrangeLayout(documentState.canvas, contextNodeIds);
    if (!layoutCanvas) {
      showToast("当前选中的卡片不足以生成整理方案");
      return;
    }
    ui.whiteboardArrangePreview = {
      workspaceId: workspaceIdentity(),
      documentId: state.activeDocument,
      scope: "selection",
      nodeIds: [...contextNodeIds],
      layoutCanvas: whiteboardCanvasSnapshot(layoutCanvas),
    };
    updateWhiteboardArrangeDecisionCopy("selection");
    elements.whiteboardArrangeDecision.hidden = false;
    elements.whiteboardEditor.classList.add("is-arrange-preview");
    renderWhiteboard(documentState);
    showToast("正在预览所选卡片的局部整理方案；请选择采用或还原");
    return;
  }
  if (action === "link-upstream") {
    openWhiteboardLinkDialog(context.nodeId);
    return;
  }
  if (action === "generate-text") {
    if (context.multiSelection) createWhiteboardSelectionGenerationTarget(contextNodeIds, "text", { centered: true });
    else openWhiteboardGenerateDialog(context.nodeId);
    return;
  }
  if (action === "generate-image") {
    if (context.multiSelection) createWhiteboardSelectionGenerationTarget(contextNodeIds, "image", { centered: true });
    else openWhiteboardImageDialog(context.nodeId);
    return;
  }
  if (action === "generate-video") {
    if (!availableGenerationConnections("video").length) {
      ui.settingsSection = "model";
      ui.modelSettingsChannel = "video";
      document.querySelector("#settingsButton").click();
      showToast("请先补全视频模型的 API Key 或 CLI 路径，并通过连接测试");
      return;
    }
    if (context.multiSelection) createWhiteboardSelectionGenerationTarget(contextNodeIds, "video", { centered: true });
    else openWhiteboardVideoDialog(context.nodeId);
    return;
  }
  if (action === "transform-project" || action === "transform-notebook") {
    openWhiteboardLandDialog(context.nodeId, action === "transform-notebook" ? "notebook" : "project");
    return;
  }
  if (action === "delete") {
    if (context.multiSelection) deleteWhiteboardNodes(contextNodeIds);
    else deleteWhiteboardNode(context.nodeId);
  }
});

document.addEventListener("keydown", (event) => {
  if (!activeWhiteboardDocument() || document.querySelector("dialog[open]:not(.whiteboard-generation-popover)")) return;
  const target = event.target instanceof Element ? event.target : null;
  const editingText = target?.matches("input, textarea, select")
    || target?.closest("[contenteditable='true']")
    || Boolean(ui.whiteboardEditingNodeId);
  const generationTextEditing = Boolean(editingText && target?.closest(".whiteboard-generation-popover"));
  if (event.code === "Space" && !event.isComposing && !event.ctrlKey && !event.metaKey && !event.altKey && (!editingText || generationTextEditing)) {
    if (!event.repeat && generationTextEditing) ui.whiteboardSpaceTextSnapshot = captureWhiteboardSpaceTextSnapshot(target);
    ui.whiteboardSpacePressed = true;
    if (!editingText) {
      elements.whiteboardEditor.classList.add("space-pan");
      event.preventDefault();
    }
    return;
  }
  if (editingText) return;
  const modifier = event.ctrlKey || event.metaKey;
  const key = event.key.toLowerCase();
  if (modifier && !event.shiftKey && key === "c") {
    const selectedIds = selectedWhiteboardNodeIds();
    if (ui.whiteboardSelectedDocumentId !== state.activeDocument || !selectedIds.length) return;
    if (!copyWhiteboardCards(selectedIds)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  if (modifier && !event.shiftKey && key === "x") {
    const selectedIds = selectedWhiteboardNodeIds();
    if (ui.whiteboardSelectedDocumentId !== state.activeDocument || !selectedIds.length) return;
    if (!cutWhiteboardCards(selectedIds)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  if (modifier && !event.shiftKey && key === "v") {
    // The paste event inspects the actual Windows clipboard and chooses
    // between an internal card record and media copied from another app.
    return;
  }
  if (modifier && !event.shiftKey && key === "z") {
    if (!undoWhiteboardAction()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  if (modifier && (key === "y" || (event.shiftKey && key === "z"))) {
    if (!redoWhiteboardAction()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  if (modifier || event.altKey || event.key !== "Delete") return;
  if (ui.whiteboardSelectedEdgeDocumentId === state.activeDocument && ui.whiteboardSelectedEdgeIds?.size) {
    event.preventDefault();
    event.stopImmediatePropagation();
    const edgeIds = [...ui.whiteboardSelectedEdgeIds];
    if (edgeIds.length > 1) deleteWhiteboardEdges(edgeIds);
    else deleteWhiteboardEdge(edgeIds[0]);
    return;
  }
  const selectedIds = selectedWhiteboardNodeIds();
  if (!selectedIds.length) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (selectedIds.length > 1) deleteWhiteboardNodes(selectedIds);
  else deleteWhiteboardNode(selectedIds[0]);
});

document.addEventListener("keyup", (event) => {
  if (event.code !== "Space") return;
  ui.whiteboardSpacePressed = false;
  ui.whiteboardSpaceTextSnapshot = null;
  elements.whiteboardEditor.classList.remove("space-pan");
});

window.addEventListener("blur", () => {
  ui.whiteboardSpacePressed = false;
  ui.whiteboardSpaceTextSnapshot = null;
  elements.whiteboardEditor.classList.remove("space-pan");
});

const focusWhiteboardNode = (nodeId, { recordHistory = true } = {}) => {
  const documentState = activeWhiteboardDocument();
  const node = whiteboardNodeById(nodeId, documentState);
  if (!documentState || !node) return;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const rect = elements.whiteboardEditor.getBoundingClientRect();
  const currentZoom = normalizeCanvas(documentState.canvas).viewport.zoom;
  const zoom = Math.max(0.8, Math.min(1.35, currentZoom));
  documentState.canvas = updateCanvasViewport(documentState.canvas, {
    zoom,
    x: rect.width / 2 - (node.x + node.width / 2) * zoom,
    y: rect.height / 2 - (node.y + node.height / 2) * zoom,
  });
  ui.whiteboardFocusedNodeId = nodeId;
  documentState.updatedAt = nowTime();
  if (recordHistory) pushWhiteboardHistory(beforeCanvas, { label: "聚焦卡片" });
  persist();
  renderWhiteboard(documentState);
};

const openWhiteboardWebDialog = (nodeId) => {
  const node = whiteboardNodeById(nodeId);
  if (!node || ["image", "video", "audio", "group"].includes(node.kind)) return;
  openTextDialog({
    title: node.kind === "web" ? "修改网页链接" : "引用网页",
    label: "网页地址",
    value: node.kind === "web" ? node.url : "",
    submitLabel: node.kind === "web" ? "保存" : "引用",
    action: { type: "whiteboard-reference-web", nodeId },
  });
};

const refreshWorkspaceReferenceCatalog = async ({ saveCurrentWorkspace = true } = {}) => {
  ui.whiteboardReferenceCatalog = { ...ui.whiteboardReferenceCatalog, loading: true, error: "" };
  renderReferencePanel();
  if (saveCurrentWorkspace) {
    try {
      await saveWorkspace({ throwOnError: true });
    } catch {
      // 引用目录是只读能力，当前文档的外部修改保护不应阻断浏览。
    }
  }
  try {
    const response = await fetch("/api/whiteboard/references");
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "作品与笔记目录读取失败");
    ui.whiteboardReferenceCatalog = { items: payload.items ?? [], loading: false, error: "" };
  } catch (error) {
    ui.whiteboardReferenceCatalog = { items: [], loading: false, error: error.message };
  }
  renderReferencePanel();
};

const openWhiteboardReferencePanel = async (context, mode = "documents") => {
  ui.whiteboardContext = { ...context };
  ui.referenceTarget = "whiteboard";
  ui.referenceMode = mode === "skills" ? "skills" : mode === "books" ? "books" : "documents";
  ui.referenceQuery = "";
  if (ui.referenceMode === "books") {
    bookDirectoryRequestController?.abort();
    bookDirectoryRequestSerial += 1;
    ui.bookSearch = {
      ...ui.bookSearch,
      importingId: "",
      selectedId: "",
      selectedBook: null,
      directory: null,
      directoryLoading: false,
      selectedChapterIds: [],
      chapterQuery: "",
      chapterPage: 1,
      error: "",
    };
  }
  ui.panel = "references";
  renderUtilityPanelState();
  if (ui.referenceMode === "skills") await Promise.all([refreshSkillLibrary(), refreshSkillCatalog()]);
  else if (ui.referenceMode === "books") await refreshBookSources();
  else await refreshWorkspaceReferenceCatalog();
  renderReferencePanel();
  requestAnimationFrame(() => document.querySelector("#referenceSearch")?.focus());
};

const openWhiteboardLinkDialog = (nodeId, { referenceAddSlot = "", mediaOnly = false } = {}) => {
  const documentState = activeWhiteboardDocument();
  const target = whiteboardNodeById(nodeId, documentState);
  if (!documentState || !target) return;
  const canvas = normalizeCanvas(documentState.canvas);
  const incoming = new Set(canvas.edges.filter((edge) => edge.toNode === nodeId).map((edge) => edge.fromNode));
  const smartEditSlot = elements.whiteboardVideoForm.dataset.nodeId === nodeId
    && elements.whiteboardVideoForm.elements.generationMode.value === "smart_edit"
    ? String(referenceAddSlot || "")
    : "";
  const candidates = canvas.nodes.filter((node) => node.id !== nodeId
    && (!mediaOnly || !["skill", "capability"].includes(node?.reference?.type))
    && (smartEditSlot === "primary"
      ? node.kind === "video" && node.file
      : smartEditSlot === "additional"
        ? ["image", "video", "audio"].includes(node.kind) && node.file
        : true));
  const visibleIds = new Set(candidates.map((node) => node.id));
  const preservedIncoming = canvas.nodes
    .filter((node) => node.id !== nodeId && incoming.has(node.id) && !visibleIds.has(node.id))
    .map((node) => `<input type="hidden" name="upstream" value="${escapeHtml(node.id)}" />`)
    .join("");
  elements.whiteboardLinkForm.dataset.nodeId = nodeId;
  elements.whiteboardLinkForm.dataset.referenceAddSlot = smartEditSlot;
  elements.whiteboardUpstreamList.innerHTML = preservedIncoming + (candidates
    .map((node) => whiteboardUpstreamCardMarkup(node, incoming.has(node.id)))
    .join("") || `<p class="panel-empty">${smartEditSlot === "primary" ? "当前白板没有可作为编辑视频的视频卡片" : smartEditSlot === "additional" ? "当前白板没有可用的图片、视频或音频卡片" : "当前没有其他卡片"}</p>`);
  elements.whiteboardLinkDialog.showModal();
};

