const switchWhiteboardGenerationType = (dialog, channel) => {
  const current = whiteboardGenerationConfigFor(dialog);
  const nodeId = current?.form.dataset.nodeId;
  if (!nodeId || !availableWhiteboardGenerationChannels().includes(channel)) return;
  reactivateWhiteboardGenerationIntent(nodeId);
  closeWhiteboardGenerationTypeMenus();
  if (channel === current.channel) return;
  const centered = dialog.classList.contains("is-expanded");
  saveWhiteboardGenerationDraft(dialog, { active: false, open: false });
  if (channel === "image") openWhiteboardImageDialog(nodeId, "auto", { centered });
  else if (channel === "video") openWhiteboardVideoDialog(nodeId, { centered });
  else if (channel === "audio") openWhiteboardAudioDialog(nodeId, { centered });
  else openWhiteboardGenerateDialog(nodeId, { centered });
  const documentState = activeWhiteboardDocument();
  if (documentState) renderWhiteboard(documentState);
};

let whiteboardGenerationDraftCacheRaw = null;
let whiteboardGenerationDraftCacheValue = null;
const WHITEBOARD_GENERATION_ACTIVE_DRAFT_KEY = "shensi-whiteboard-generation-active-draft-v1";

const storedWhiteboardGenerationActiveDraft = () => {
  try {
    const value = JSON.parse(localStorage.getItem(WHITEBOARD_GENERATION_ACTIVE_DRAFT_KEY) || "null");
    return value && typeof value === "object" ? value : null;
  } catch {
    return null;
  }
};

const readWhiteboardGenerationDraftCache = () => {
  try {
    const raw = localStorage.getItem(WHITEBOARD_GENERATION_DRAFT_CACHE_KEY) || "{}";
    if (raw === whiteboardGenerationDraftCacheRaw && whiteboardGenerationDraftCacheValue) {
      return whiteboardGenerationDraftCacheValue;
    }
    whiteboardGenerationDraftCacheRaw = raw;
    whiteboardGenerationDraftCacheValue = normalizeWhiteboardGenerationDraftCache(JSON.parse(raw));
    const active = storedWhiteboardGenerationActiveDraft();
    const activeKey = whiteboardGenerationDraftKey(active);
    if (activeKey && whiteboardGenerationDraftCacheValue.entries[activeKey]) {
      const session = { ...active, key: activeKey, collapsed: false, updatedAt: Math.max(0, Number(active.updatedAt) || Date.now()) };
      whiteboardGenerationDraftCacheValue.active = session;
      whiteboardGenerationDraftCacheValue.openSessions = [session];
    }
    return whiteboardGenerationDraftCacheValue;
  } catch {
    whiteboardGenerationDraftCacheRaw = "{}";
    whiteboardGenerationDraftCacheValue = normalizeWhiteboardGenerationDraftCache({});
    return whiteboardGenerationDraftCacheValue;
  }
};

const writeWhiteboardGenerationDraftCache = (cache, { normalized = false } = {}) => {
  try {
    const durableCache = normalized ? cache : normalizeWhiteboardGenerationDraftCache(cache);
    // The active/open pointer changes whenever a bar is opened or closed. Keep
    // it in a tiny independent record so that action never rewrites every long
    // prompt in the 120-entry draft cache on the renderer thread.
    const raw = JSON.stringify({ ...durableCache, active: null, openSessions: [] });
    if (raw !== whiteboardGenerationDraftCacheRaw) localStorage.setItem(WHITEBOARD_GENERATION_DRAFT_CACHE_KEY, raw);
    if (durableCache.active) localStorage.setItem(WHITEBOARD_GENERATION_ACTIVE_DRAFT_KEY, JSON.stringify(durableCache.active));
    else localStorage.removeItem(WHITEBOARD_GENERATION_ACTIVE_DRAFT_KEY);
    whiteboardGenerationDraftCacheRaw = raw;
    whiteboardGenerationDraftCacheValue = durableCache;
  } catch {}
};

window.addEventListener("storage", (event) => {
  if (![WHITEBOARD_GENERATION_DRAFT_CACHE_KEY, WHITEBOARD_GENERATION_ACTIVE_DRAFT_KEY].includes(event.key)) return;
  whiteboardGenerationDraftCacheRaw = null;
  whiteboardGenerationDraftCacheValue = null;
});

const markWhiteboardGenerationDraftDurable = () => {
  ui.whiteboardGenerationDraftRevision += 1;
  // Keep prompt edits in the same crash/restart recovery channel as the
  // workspace state. This is intentionally a checkpoint only: it does not
  // trigger a formal document save or alter generation routing.
  scheduleRecoveryCheckpoint(120);
};

const restoreInterruptedWhiteboardGenerationDraft = (job) => {
  const channel = String(job?.channel || "");
  const target = job?.target ?? {};
  const prompt = String(job?.request?.prompt || "").trim();
  if (!prompt || !["image", "video", "audio"].includes(channel)) return false;
  if (normalizedWorkspacePath(target.workspacePath) !== normalizedWorkspacePath(state.settings.workspacePath)) return false;
  const scope = whiteboardGenerationDraftScopeFor(channel, target.nodeId, {
    documentId: target.documentId,
    workspaceId: workspaceIdentity(),
  });
  const cache = readWhiteboardGenerationDraftCache();
  const key = whiteboardGenerationDraftKey(scope);
  const current = key ? cache.entries[key]?.values ?? {} : {};
  const jobUpdatedAt = Date.parse(job.updatedAt || job.failedAt || job.createdAt || "") || Date.now();
  // Do not let startup/recovery of an older failed attempt change the provider
  // currently selected by the user for this card. The prompt is still retained
  // in the durable job and can be recovered from the matching newest attempt.
  if (key && Number(cache.entries[key]?.updatedAt || 0) > jobUpdatedAt) return false;
  const settings = job.request?.settings ?? {};
  const values = {
    ...current,
    prompt,
    ...(Array.isArray(job.request?.referenceOrder) ? { referenceOrder: job.request.referenceOrder.map(String).filter(Boolean).join(",") } : {}),
    ...(Array.isArray(job.request?.promptReferenceSequence) ? { promptReferenceSequence: job.request.promptReferenceSequence.map(String).filter(Boolean).join(",") } : {}),
    ...(settings.connectionId ? { connectionId: String(settings.connectionId) } : {}),
    ...(settings.model ? { model: String(settings.model) } : {}),
    ...(job.request?.generationMode ? { generationMode: String(job.request.generationMode) } : {}),
    ...(job.request?.aspectRatio ? { aspectRatio: String(job.request.aspectRatio) } : {}),
    ...(job.request?.duration ? { duration: String(job.request.duration) } : {}),
    ...(job.request?.resolution ? { resolution: String(job.request.resolution) } : {}),
  };
  writeWhiteboardGenerationDraftCache(updateWhiteboardGenerationDraftCache(cache, scope, values, {
    active: false,
    open: false,
    updatedAt: jobUpdatedAt,
  }));
  markWhiteboardGenerationDraftDurable();
  return true;
};

const whiteboardGenerationDraftScopeFor = (channel, nodeId, { documentId = state.activeDocument, workspaceId = workspaceIdentity() } = {}) => ({
  workspaceId,
  documentId,
  nodeId,
  channel,
});

const whiteboardGenerationFormValues = (form) => Object.fromEntries(Array.from(form.elements)
  .filter((field) => field.name && !["submit", "button"].includes(field.type))
  .map((field) => [field.name, field.type === "checkbox" ? field.checked : field.value]));

const applyWhiteboardGenerationFormValues = (form, values = {}) => {
  const source = values && typeof values === "object" ? values : {};
  for (const field of Array.from(form.elements)) {
    if (!field.name || !(field.name in source)) continue;
    if (field.type === "checkbox") {
      field.checked = source[field.name] === true;
      continue;
    }
    const value = String(source[field.name] ?? "");
    if (field instanceof HTMLSelectElement && !Array.from(field.options).some((option) => option.value === value)) continue;
    field.value = value;
  }
};

const whiteboardGenerationDraftValues = (channel, nodeId) => {
  const cache = readWhiteboardGenerationDraftCache();
  const key = whiteboardGenerationDraftKey(whiteboardGenerationDraftScopeFor(channel, nodeId));
  return key ? cache.entries[key]?.values ?? null : null;
};

const whiteboardGenerationCapacityProfile = (nodeId, { channel = "", settings = null } = {}) => {
  let effectiveChannel = channel;
  let values = {};
  if (!effectiveChannel) {
    const openConfig = whiteboardGenerationConfigs().find((config) => (
      config.dialog.open
      && config.form.dataset.nodeId === nodeId
      && config.dialog.dataset.anchorDocumentId === state.activeDocument
      && config.dialog.dataset.anchorWorkspaceId === workspaceIdentity()
    ));
    if (openConfig) {
      effectiveChannel = openConfig.channel;
      values = whiteboardGenerationFormValues(openConfig.form);
    } else {
      const entries = Object.values(readWhiteboardGenerationDraftCache().entries)
        .filter((entry) => entry.workspaceId === workspaceIdentity() && entry.documentId === state.activeDocument && entry.nodeId === nodeId)
        .sort((left, right) => right.updatedAt - left.updatedAt);
      effectiveChannel = entries[0]?.channel || "";
      values = entries[0]?.values ?? {};
    }
  }
  let effectiveSettings = settings;
  if (!effectiveSettings && effectiveChannel === "text") effectiveSettings = activeGenerationProfile(state.settings, "text");
  if (!effectiveSettings && effectiveChannel === "image") effectiveSettings = currentImageGenerationSettings(values.connectionId, values.model);
  if (!effectiveSettings && effectiveChannel === "video") effectiveSettings = currentVideoGenerationSettings(values.connectionId, values.model);
  if (!effectiveSettings && effectiveChannel === "audio") effectiveSettings = currentAudioGenerationSettings(values.connectionId, values.model);
  const dynamicModels = effectiveSettings
    ? dynamicModelsForChannel(effectiveSettings.provider, effectiveSettings.adapter)
    : [];
  const limits = whiteboardConnectionReferenceLimits(effectiveSettings, { channel: effectiveChannel, dynamicModels });
  return {
    channel: effectiveChannel,
    settings: effectiveSettings,
    limits,
    structural: limits.structural === true,
    modelLabel: effectiveSettings?.model
      ? [effectiveSettings.provider, effectiveSettings.model].filter(Boolean).join(" · ")
      : "白板卡片",
  };
};

const whiteboardReferenceCapacityMessage = ({ violation, profile, nodeId, operation = "connect", bulk = false }) => {
  const target = violation.usage.target || whiteboardNodeById(nodeId);
  const targetLabel = target?.name || String(target?.text || "").replace(/\s+/g, " ").trim().slice(0, 24) || "目标卡片";
  const cancelled = operation === "generate" ? "未开始生成" : bulk ? "已取消整批连接" : "已取消连接";
  if (violation.kind === "media" && violation.limit === 0) {
    return `“${targetLabel}”包含媒体输入，但 ${profile.modelLabel} 不支持媒体参考；${cancelled}。请切换支持多模态输入的模型。`;
  }
  const referenceType = violation.kind === "media" ? "媒体参考" : "直接上游参考";
  const targetUsage = violation.kind === "media" && violation.usage.targetMediaReferenceCount
    ? `，其中目标卡片自身占用 ${violation.usage.targetMediaReferenceCount} 项`
    : "";
  const guidance = profile.structural
    ? `请将卡片参考控制在 ${violation.limit} 项以内。`
    : "请减少参考或切换支持更多参考的模型。";
  return `“${targetLabel}”的${referenceType}将达到 ${violation.count} 项${targetUsage}，超过 ${profile.modelLabel} 的 ${violation.limit} 项上限；${cancelled}。${guidance}`;
};

const checkWhiteboardReferenceCapacity = (canvas, targetNodeIds, {
  channel = "",
  settings = null,
  operation = "connect",
  bulk = false,
  notify = true,
  includeTargetMedia = null,
} = {}) => {
  for (const nodeId of [...new Set((targetNodeIds ?? []).map(String).filter(Boolean))]) {
    const profile = whiteboardGenerationCapacityProfile(nodeId, { channel, settings });
    const violation = whiteboardReferenceCapacityViolation(canvas, nodeId, {
      ...profile.limits,
      includeTargetMedia: includeTargetMedia ?? profile.channel === "text",
    });
    if (!violation) continue;
    const message = whiteboardReferenceCapacityMessage({ violation, profile, nodeId, operation, bulk });
    if (notify) showToast(message);
    return { ok: false, message, violation, profile };
  }
  return { ok: true };
};

const whiteboardGenerationDialogDraftScope = (dialog) => {
  const config = whiteboardGenerationConfigFor(dialog);
  const nodeId = config?.form.dataset.nodeId;
  if (!config || !nodeId) return null;
  return whiteboardGenerationDraftScopeFor(config.channel, nodeId, {
    documentId: dialog.dataset.anchorDocumentId || state.activeDocument,
    workspaceId: dialog.dataset.anchorWorkspaceId || workspaceIdentity(),
  });
};

const whiteboardGenerationDraftValuesEqual = (left = {}, right = {}) => {
  const leftKeys = Object.keys(left);
  const rightKeys = Object.keys(right);
  return leftKeys.length === rightKeys.length
    && leftKeys.every((key) => left[key] === right[key]);
};

const saveWhiteboardGenerationDraft = (dialog, {
  active = dialog?.open,
  open = dialog?.open,
  durable = true,
} = {}) => {
  const config = whiteboardGenerationConfigFor(dialog);
  const scope = whiteboardGenerationDialogDraftScope(dialog);
  if (!config || !scope) return;
  const previous = readWhiteboardGenerationDraftCache();
  const key = whiteboardGenerationDraftKey(scope);
  const values = whiteboardGenerationFormValues(config.form);
  const existing = key ? previous.entries[key] : null;
  const activeMatches = active ? previous.active?.key === key : previous.active?.key !== key;
  const valuesChanged = !existing || !whiteboardGenerationDraftValuesEqual(existing.values, values);
  if (!valuesChanged && activeMatches) return;
  const cache = updateWhiteboardGenerationDraftCache(
    previous,
    scope,
    values,
    { active, open, collapsed: false },
  );
  writeWhiteboardGenerationDraftCache(cache, { normalized: true });
  if (durable && valuesChanged) markWhiteboardGenerationDraftDurable();
};

const dismissWhiteboardGenerationDialogsOutsideActiveSurface = () => {
  const activeDocumentKind = state.documents[state.activeDocument]?.documentKind || "";
  const activeWorkspaceId = workspaceIdentity();
  for (const dialog of whiteboardGenerationDialogs()) {
    if (!dialog.open || whiteboardGenerationSurfaceIsActive({
      anchorWorkspaceId: dialog.dataset.anchorWorkspaceId,
      anchorDocumentId: dialog.dataset.anchorDocumentId,
      activeWorkspaceId,
      activeDocumentId: state.activeDocument,
      activeDocumentKind,
    })) continue;
    saveWhiteboardGenerationDraft(dialog, { active: false, open: false });
    dialog.close();
  }
};

const flushWhiteboardGenerationDrafts = () => {
  whiteboardGenerationDialogs().filter((dialog) => dialog.open).forEach((dialog) => saveWhiteboardGenerationDraft(dialog));
};

const deactivateWhiteboardGenerationDialogDraft = (dialog) => {
  const scope = whiteboardGenerationDialogDraftScope(dialog);
  if (!scope) return;
  const previous = readWhiteboardGenerationDraftCache();
  const next = deactivateWhiteboardGenerationDraft(previous, scope);
  if (JSON.stringify(previous) !== JSON.stringify(next)) {
    writeWhiteboardGenerationDraftCache(next);
    markWhiteboardGenerationDraftDurable();
  }
};

const closeWhiteboardGenerationSessionsForNodes = (nodeIds = [], {
  documentId = state.activeDocument,
  workspaceId = workspaceIdentity(),
} = {}) => {
  const ids = new Set(nodeIds.map(String).filter(Boolean));
  if (!ids.size) return;
  for (const dialog of whiteboardGenerationDialogs()) {
    if (!dialog.open) continue;
    const scope = whiteboardGenerationDialogDraftScope(dialog);
    if (scope?.workspaceId === workspaceId && scope.documentId === documentId && ids.has(scope.nodeId)) dialog.close();
  }
  let cache = readWhiteboardGenerationDraftCache();
  let changed = false;
  for (const session of [...cache.openSessions]) {
    if (session.workspaceId !== workspaceId || session.documentId !== documentId || !ids.has(session.nodeId)) continue;
    cache = deactivateWhiteboardGenerationDraft(cache, session);
    changed = true;
  }
  if (changed) {
    writeWhiteboardGenerationDraftCache(cache);
    markWhiteboardGenerationDraftDurable();
  }
  renderWhiteboardGenerationCollapsedSessions();
};

const whiteboardGenerationAnchorLabel = (node) => {
  const compactText = String(node?.text ?? "").replace(/\s+/g, " ").trim();
  const label = node?.name || compactText.slice(0, 32) || whiteboardNodeKindLabel(node) || "空白卡片";
  return `目标卡片：${label}`;
};

const syncWhiteboardGenerationAnchorLabel = (dialog, nodeId) => {
  const label = dialog.querySelector(".whiteboard-generation-anchor-label");
  const node = whiteboardNodeById(nodeId);
  if (label) label.textContent = whiteboardGenerationAnchorLabel(node);
};

const whiteboardGenerationSessionTitle = (channel) => ({
  text: "生成文本",
  image: "生成图片",
  video: "生成视频",
  audio: "生成音频",
}[channel] || "生成内容");

const syncWhiteboardCardGenerationTypeIndicator = (nodeId, channel) => {
  const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(nodeId)}"]`);
  const visibleText = card?.querySelector(`[data-canvas-text="${CSS.escape(nodeId)}"]`)?.value ?? "";
  if (!card || card.dataset.generatedContent === "true" || card.dataset.cardHasText === "true" || String(visibleText).trim() || card.hasAttribute("data-generation-job-id")) {
    card?.querySelector(":scope > .whiteboard-card-generation-type")?.remove();
    return;
  }
  const labels = { text: "文字生成", image: "图片生成", video: "视频生成", audio: "音频生成" };
  const icons = { text: "\uE8D2", image: "\uEB9F", video: "\uE714", audio: "\uE8D6" };
  const label = labels[channel];
  if (!label) return;
  let indicator = card.querySelector(":scope > .whiteboard-card-generation-type");
  if (!indicator) {
    indicator = document.createElement("span");
    indicator.className = "whiteboard-card-generation-type";
    card.prepend(indicator);
  }
  indicator.dataset.generationCardType = channel;
  indicator.title = label;
  indicator.setAttribute("aria-label", label);
  indicator.innerHTML = icon(icons[channel] || "\uE8D2");
};

let whiteboardGenerationCollapsedLayerElement = null;
const whiteboardGenerationCollapsedLayer = () => {
  if (whiteboardGenerationCollapsedLayerElement?.isConnected) return whiteboardGenerationCollapsedLayerElement;
  const layer = document.createElement("div");
  layer.className = "whiteboard-generation-session-layer";
  layer.id = "whiteboardGenerationCollapsedSessions";
  layer.hidden = true;
  layer.addEventListener("click", (event) => {
    const guidanceButton = event.target.closest("[data-whiteboard-guidance-session]");
    if (!guidanceButton) return;
    const session = ui.whiteboardGuidance;
    if (!session.active || session.workspacePath !== state.settings.workspacePath || session.documentId !== state.activeDocument || !whiteboardNodeById(session.nodeId)) return;
    session.collapsed = false;
    if (!elements.whiteboardGuidanceDialog.open) elements.whiteboardGuidanceDialog.showModal();
    renderWhiteboardGuidanceDialog();
    renderWhiteboardGenerationCollapsedSessions();
  });
  document.body.append(layer);
  whiteboardGenerationCollapsedLayerElement = layer;
  return layer;
};

const positionWhiteboardGenerationCollapsedSessions = () => {
  const layer = whiteboardGenerationCollapsedLayerElement;
  if (!layer?.isConnected || layer.hidden || !activeWhiteboardDocument()) return;
  const editorRect = elements.whiteboardEditor.getBoundingClientRect();
  const margin = 10;
  const gap = 10;
  layer.querySelectorAll("[data-whiteboard-guidance-session]").forEach((button) => {
    const nodeId = button.dataset.whiteboardGuidanceNodeId;
    const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(nodeId)}"]`);
    if (!card) {
      button.hidden = true;
      return;
    }
    button.hidden = false;
    const cardRect = card.getBoundingClientRect();
    const width = Math.max(1, Math.min(cardRect.width, editorRect.width - margin * 2));
    button.style.width = `${Math.round(width)}px`;
    const buttonRect = button.getBoundingClientRect();
    const minLeft = editorRect.left + margin;
    const maxLeft = Math.max(minLeft, editorRect.right - buttonRect.width - margin);
    const preferredTop = cardRect.bottom + gap;
    const preferredLeft = cardRect.left + (cardRect.width - buttonRect.width) / 2;
    button.style.left = `${Math.round(Math.min(Math.max(preferredLeft, minLeft), maxLeft))}px`;
    button.style.top = `${Math.round(preferredTop)}px`;
  });
};

const renderWhiteboardGenerationCollapsedSessions = () => {
  const layer = whiteboardGenerationCollapsedLayer();
  const documentState = activeWhiteboardDocument();
  if (!documentState) {
    layer.innerHTML = "";
    layer.hidden = true;
    return;
  }
  layer.innerHTML = "";
  const guidance = ui.whiteboardGuidance;
  const guidanceVisible = Boolean(guidance.active
    && guidance.collapsed
    && !elements.whiteboardGuidanceDialog.open
    && guidance.workspacePath === state.settings.workspacePath
    && guidance.documentId === state.activeDocument
    && whiteboardNodeById(guidance.nodeId, documentState));
  if (guidanceVisible) {
    layer.insertAdjacentHTML("beforeend", `<button class="whiteboard-generation-session-dock guidance" type="button" data-whiteboard-guidance-session data-whiteboard-guidance-node-id="${escapeHtml(guidance.nodeId)}" title="展开创作引导" aria-label="展开创作引导"><span><strong>创作引导</strong><small>${escapeHtml(whiteboardGenerationAnchorLabel(whiteboardNodeById(guidance.nodeId, documentState)))}</small></span>${icon("\uE70D", "展开创作引导")}</button>`);
  }
  layer.hidden = !guidanceVisible;
  localizeUi(layer, globalUiPreferences.uiLanguage);
  positionWhiteboardGenerationCollapsedSessions();
};

const ensureWhiteboardGenerationAnchorRoom = (nodeId, minimumUsableHeight = 100) => {
  const documentState = activeWhiteboardDocument();
  const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(nodeId)}"]`);
  if (!documentState || !card) return;
  const margin = 10;
  const gap = 10;
  const editorRect = elements.whiteboardEditor.getBoundingClientRect();
  const cardRect = card.getBoundingClientRect();
  const preferredTop = cardRect.bottom + gap;
  const maximumTop = window.innerHeight - minimumUsableHeight - margin;
  const requiredShift = Math.max(0, preferredTop - maximumTop);
  const availableShift = Math.max(0, cardRect.top - editorRect.top - margin);
  const shift = Math.min(requiredShift, availableShift);
  if (shift <= 0) return;
  const viewport = normalizeCanvas(documentState.canvas).viewport;
  documentState.canvas = updateCanvasViewport(documentState.canvas, { y: viewport.y - shift });
  documentState.updatedAt = nowTime();
  persist();
  renderWhiteboard(documentState);
};

const positionWhiteboardGenerationDialog = (dialog, nodeId = dialog?.dataset.anchorNodeId) => {
  if (!dialog?.open || !nodeId) return;
  if (dialog.dataset.anchorDocumentId !== state.activeDocument || dialog.dataset.anchorWorkspaceId !== workspaceIdentity()) {
    dialog.close();
    return;
  }
  const card = elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(nodeId)}"]`);
  if (!card) return;
  const margin = 10;
  const gap = 10;
  const editorRect = elements.whiteboardEditor.getBoundingClientRect();
  const cardRect = card.getBoundingClientRect();
  const horizontalBounds = (dialogRect) => {
    const viewportMinLeft = margin;
    const viewportMaxLeft = Math.max(viewportMinLeft, window.innerWidth - dialogRect.width - margin);
    const visibleEditorWidth = Math.max(0, Math.min(window.innerWidth - margin, editorRect.right) - Math.max(margin, editorRect.left));
    if (dialogRect.width > visibleEditorWidth - margin) return { minLeft: viewportMinLeft, maxLeft: viewportMaxLeft, viewportBounded: true };
    return {
      minLeft: Math.max(viewportMinLeft, editorRect.left + margin),
      maxLeft: Math.min(viewportMaxLeft, Math.max(editorRect.left + margin, editorRect.right - dialogRect.width - margin)),
      viewportBounded: false,
    };
  };
  if (dialog.classList.contains("is-expanded")) {
    dialog.style.maxHeight = `${Math.max(160, Math.floor(Math.min(window.innerHeight - margin * 2, editorRect.height - 24)))}px`;
    const dialogRect = dialog.getBoundingClientRect();
    const { minLeft, maxLeft, viewportBounded } = horizontalBounds(dialogRect);
    const visibleEditorLeft = Math.max(margin, editorRect.left);
    const visibleEditorRight = Math.min(window.innerWidth - margin, editorRect.right);
    const preferredLeft = viewportBounded
      ? (window.innerWidth - dialogRect.width) / 2
      : visibleEditorLeft + (Math.max(0, visibleEditorRight - visibleEditorLeft) - dialogRect.width) / 2;
    dialog.style.left = `${Math.round(Math.min(Math.max(preferredLeft, minLeft), maxLeft))}px`;
    dialog.style.top = `${Math.round(editorRect.top + Math.max(12, (editorRect.height - Math.min(dialogRect.height, editorRect.height - 24)) / 2))}px`;
    return;
  }
  const preferredTop = cardRect.bottom + gap;
  const top = preferredTop;
  dialog.style.maxHeight = `${Math.max(96, Math.floor(window.innerHeight - top - margin))}px`;
  const dialogRect = dialog.getBoundingClientRect();
  const { minLeft, maxLeft, viewportBounded } = horizontalBounds(dialogRect);
  const preferredLeft = viewportBounded
    ? (window.innerWidth - dialogRect.width) / 2
    : cardRect.left + (cardRect.width - dialogRect.width) / 2;
  dialog.style.left = `${Math.round(Math.min(Math.max(preferredLeft, minLeft), maxLeft))}px`;
  dialog.style.top = `${Math.round(top)}px`;
};

let whiteboardGenerationPositionFrame = 0;
const positionWhiteboardGenerationSurfaces = () => {
  whiteboardGenerationDialogs().forEach((dialog) => positionWhiteboardGenerationDialog(dialog));
  positionWhiteboardGenerationCollapsedSessions();
};

const flushWhiteboardGenerationDialogPosition = () => {
  if (whiteboardGenerationPositionFrame) cancelAnimationFrame(whiteboardGenerationPositionFrame);
  whiteboardGenerationPositionFrame = 0;
  positionWhiteboardGenerationSurfaces();
};

const scheduleWhiteboardGenerationDialogPosition = () => {
  const hasOpenDialog = whiteboardGenerationDialogs().some((dialog) => dialog.open);
  const hasGuidanceSession = Boolean(whiteboardGenerationCollapsedLayerElement?.querySelector("[data-whiteboard-guidance-session]"));
  if (whiteboardGenerationPositionFrame || (!hasOpenDialog && !hasGuidanceSession)) return;
  whiteboardGenerationPositionFrame = requestAnimationFrame(() => {
    whiteboardGenerationPositionFrame = 0;
    positionWhiteboardGenerationSurfaces();
  });
};

const setWhiteboardGenerationDialogExpanded = (dialog, expanded, { position = true } = {}) => {
  if (!dialog?.open) return;
  dialog.classList.toggle("is-expanded", expanded);
  const button = dialog.querySelector("[data-whiteboard-generation-expand]");
  if (button) {
    const label = expanded ? "退出居中展开" : "居中展开生成窗口";
    const localizedLabel = uiText(label);
    button.setAttribute("aria-expanded", String(expanded));
    button.innerHTML = icon(expanded ? "\uE73F" : "\uE740", localizedLabel);
    button.title = localizedLabel;
    button.setAttribute("aria-label", localizedLabel);
  }
  if (position) positionWhiteboardGenerationDialog(dialog);
};

const closeWhiteboardGenerationDialogsOutside = (target) => {
  whiteboardGenerationDialogs().filter((dialog) => dialog.open).forEach((dialog) => {
    if (dialog.contains(target)) return;
    const anchorId = dialog.dataset.anchorNodeId;
    const anchorCard = anchorId
      ? elements.whiteboardSurface.querySelector(`[data-canvas-node="${CSS.escape(anchorId)}"]`)
      : null;
    // The generator belongs to its anchor card in both docked and centered
    // layouts. Interacting with that card (especially its output handle) must
    // not be interpreted as an outside dismissal.
    if (anchorCard?.contains(target)) return;
    dialog.close();
  });
};

const hideWhiteboardGenerationSessionsOutsideChannel = (channel) => {
  if (!channel) return;
  let cache = readWhiteboardGenerationDraftCache();
  let changed = false;
  for (const session of [...cache.openSessions]) {
    if (session.workspaceId !== workspaceIdentity() || session.documentId !== state.activeDocument || session.channel === channel) continue;
    cache = deactivateWhiteboardGenerationDraft(cache, session);
    changed = true;
  }
  if (changed) {
    writeWhiteboardGenerationDraftCache(cache);
    markWhiteboardGenerationDraftDurable();
  }
};

const prepareWhiteboardGenerationDialogSwitch = (channel, nodeId) => {
  const targetKey = whiteboardGenerationDraftKey(whiteboardGenerationDraftScopeFor(channel, nodeId));
  whiteboardGenerationDialogs().filter((dialog) => dialog.open).forEach((dialog) => {
    const currentScope = whiteboardGenerationDialogDraftScope(dialog);
    const currentKey = whiteboardGenerationDraftKey(currentScope);
    if (!currentKey || currentKey === targetKey) return;
    saveWhiteboardGenerationDraft(dialog, { active: false, open: false });
    // Reuse the already-open surface when moving between cards in the same
    // generation channel. Closing and immediately showing the same <dialog>
    // queues a stale close event; under fast context-menu switching that event
    // can arrive after the new anchor is initialized and close the new session.
    // Keeping the surface open also avoids a visible native-control flash.
    if (whiteboardGenerationConfigFor(dialog)?.channel === channel) return;
    dialog.close();
  });
  hideWhiteboardGenerationSessionsOutsideChannel(channel);
  renderWhiteboardGenerationCollapsedSessions();
};

const primeWhiteboardGenerationDialog = (dialog, nodeId, { centered = false } = {}) => {
  cancelWhiteboardCardOpen();
  collapseWhiteboardContextMenu();
  const config = whiteboardGenerationConfigFor(dialog);
  if (config?.form) config.form.dataset.nodeId = nodeId;
  dialog.dataset.anchorNodeId = nodeId;
  dialog.dataset.anchorDocumentId = state.activeDocument;
  dialog.dataset.anchorWorkspaceId = workspaceIdentity();
  ui.whiteboardLastGenerationChannel = config?.channel || "text";
  dialog.setAttribute("aria-busy", "true");
  dialog.inert = true;
  if (!dialog.open) dialog.show();
  setWhiteboardGenerationDialogExpanded(dialog, centered, { position: false });
  syncWhiteboardGenerationAnchorLabel(dialog, nodeId);
};

const scheduleUiInitializationAfterPaint = (callback, { timeout = 160 } = {}) => {
  let dispatched = false;
  let fallbackTimer = null;
  const dispatch = () => {
    if (dispatched) return;
    dispatched = true;
    if (fallbackTimer !== null) {
      clearTimeout(fallbackTimer);
      fallbackTimer = null;
    }
    scheduleUiBackgroundTask(callback, {
      timeout: Math.max(300, timeout),
      // UI initialization is user-requested and should start quickly, while
      // still yielding if a second click/key is already being processed.
      interactionGrace: 56,
    });
  };
  if (typeof requestAnimationFrame === "function") requestAnimationFrame(dispatch);
  // A hidden/throttled window may not receive a paint callback at all. The
  // dialog is already modal and inert at this point, so leaving initialization
  // behind an unbounded RAF would make every control in the app appear dead.
  fallbackTimer = setTimeout(dispatch, Math.max(0, Number(timeout) || 160));
};

const showWhiteboardGenerationDialog = (dialog, nodeId, focusTarget) => {
  // A card click schedules a delayed open so a drag can still start. When an
  // explicit open has already reached this point, cancel that pending callback;
  // otherwise it can reopen/reinitialize the same form just after the user
  // starts typing and make the first keystrokes appear to be ignored.
  cancelWhiteboardCardOpen();
  collapseWhiteboardContextMenu();
  ensureWhiteboardGenerationAnchorRoom(nodeId);
  dialog.dataset.anchorNodeId = nodeId;
  dialog.dataset.anchorDocumentId = state.activeDocument;
  dialog.dataset.anchorWorkspaceId = workspaceIdentity();
  ui.whiteboardLastGenerationChannel = whiteboardGenerationConfigFor(dialog)?.channel || "text";
  if (!dialog.open) dialog.show();
  // primeWhiteboardGenerationDialog already established the requested initial
  // layout. Keep any expand/collapse choice made while deferred form setup was
  // running instead of restoring the stale option captured at open time.
  for (const other of whiteboardGenerationDialogs()) {
    if (other === dialog || !other.open) continue;
    saveWhiteboardGenerationDraft(other, { active: false, open: false });
    other.close();
  }
  hideWhiteboardGenerationSessionsOutsideChannel(whiteboardGenerationConfigFor(dialog)?.channel);
  syncWhiteboardGenerationAnchorLabel(dialog, nodeId);
  dialog.scrollTop = 0;
  closeWhiteboardGenerationMentionMenu(dialog.querySelector("form"));
  initializeWhiteboardPromptHistory(dialog.querySelector("form"));
  saveWhiteboardGenerationDraft(dialog, { active: true, open: true, durable: false });
  syncWhiteboardCardGenerationTypeIndicator(nodeId, whiteboardGenerationConfigFor(dialog)?.channel);
  renderWhiteboardGenerationCollapsedSessions();
  renderWhiteboardGenerationTypeMenu(dialog);
  requestAnimationFrame(() => {
    if (!dialog.open || dialog.dataset.anchorNodeId !== nodeId) return;
    positionWhiteboardGenerationDialog(dialog, nodeId);
    const richFocusTarget = focusTarget?.closest?.(".whiteboard-generation-prompt-editor")?.querySelector?.(".whiteboard-generation-inline-mentions");
    if (richFocusTarget) {
      richFocusTarget.scrollIntoView({ block: "center", inline: "nearest" });
      const selection = document.getSelection();
      const hasLiveSelection = document.activeElement === richFocusTarget
        && selection?.rangeCount
        && richFocusTarget.contains(selection.anchorNode);
      if (!hasLiveSelection) placeWhiteboardRichPromptCaretAtEnd(richFocusTarget.closest("form"), { focus: true });
    } else {
      focusTarget?.focus({ preventScroll: true });
    }
    dialog.scrollTop = 0;
    saveWhiteboardGenerationDraft(dialog, { active: true, open: true, durable: false });
    // Ready means all synchronous positioning/focus/draft work has finished.
    // Previously the flag was cleared one frame early, so an immediate Close
    // or type switch could land inside this final block and feel ignored.
    dialog.removeAttribute("aria-busy");
    dialog.inert = false;
  });
};

const whiteboardGenerationExplicitReferenceIds = (form) => new Set(String(form?.elements?.explicitReferences?.value || "")
  .split(",")
  .map((value) => value.trim())
  .filter(Boolean));

const writeWhiteboardGenerationExplicitReferenceIds = (form, ids) => {
  if (!form?.elements?.explicitReferences) return;
  form.elements.explicitReferences.value = [...ids].join(",");
  form.elements.explicitReferences.dispatchEvent(new Event("change", { bubbles: true }));
};

const whiteboardGenerationStoredReferenceOrder = (form) => String(form?.elements?.referenceOrder?.value || "")
  .split(",")
  .map((value) => value.trim())
  .filter(Boolean);

const whiteboardGenerationPromptReferenceSequence = (form) => String(form?.elements?.promptReferenceSequence?.value || "")
  .split(",")
  .map((value) => value.trim())
  .filter(Boolean);

const writeWhiteboardGenerationPromptReferenceSequence = (form, ids = []) => {
  if (!form?.elements?.promptReferenceSequence) return;
  // This sequence intentionally keeps duplicates. It records the semantic
  // occurrence order in the prompt and must never be used to sort the tray.
  form.elements.promptReferenceSequence.value = ids.map(String).filter(Boolean).join(",");
};

const whiteboardGenerationUsesMediaModel = (form) => (
  form === elements.whiteboardImageForm || form === elements.whiteboardVideoForm || form === elements.whiteboardAudioForm
);

const whiteboardGenerationNodesForForm = (form, nodes = []) => (
  whiteboardGenerationUsesMediaModel(form)
    ? nodes.filter((node) => !["skill", "capability"].includes(node?.reference?.type))
    : nodes
);

const whiteboardGenerationReferenceOrder = (form) => {
  const nodeId = String(form?.dataset?.nodeId || "").trim();
  const documentState = activeWhiteboardDocument?.();
  const upstream = nodeId && documentState
    ? whiteboardGenerationNodesForForm(form, whiteboardGenerationSources(documentState.canvas, nodeId).upstream)
    : [];
  // Incoming edge order is the single source of truth for the visible tray.
  // A stale draft or a generation result must not be able to reorder it.
  if (upstream.length) return upstream.map((node) => node.id);
  const stored = whiteboardGenerationStoredReferenceOrder(form);
  if (stored.length) return stored;
  return Array.isArray(whiteboardNodeById(nodeId)?.generation?.referenceOrder)
    ? whiteboardNodeById(nodeId).generation.referenceOrder.map(String).filter(Boolean)
    : [];
};

const writeWhiteboardGenerationReferenceOrder = (form, ids = []) => {
  if (!form?.elements?.referenceOrder) return;
  form.elements.referenceOrder.value = ids.map(String).filter(Boolean).join(",");
};

const orderWhiteboardGenerationNodes = (nodes = [], form = null) => {
  const preferred = whiteboardGenerationReferenceOrder(form);
  if (!preferred.length) return nodes;
  const rank = new Map();
  preferred.forEach((id, index) => { if (!rank.has(id)) rank.set(id, index); });
  return nodes
    .map((node, index) => ({ node, index, rank: rank.has(node.id) ? rank.get(node.id) : Number.MAX_SAFE_INTEGER }))
    .sort((left, right) => (left.rank - right.rank) || (left.index - right.index))
    .map(({ node }) => node);
};

const syncWhiteboardGenerationPromptReferenceSequenceFromEditor = (form) => {
  const editor = whiteboardGenerationRichPrompt(form);
  if (!editor) return [];
  const ids = [...editor.querySelectorAll("[data-rich-mention-node-id]")]
    .map((mention) => String(mention.dataset.richMentionNodeId || "").trim())
    .filter(Boolean);
  writeWhiteboardGenerationPromptReferenceSequence(form, ids);
  return ids;
};

const migrateWhiteboardGenerationReferenceOrder = (form, upstream = []) => {
  if (!form || !upstream.length) return false;
  const stored = whiteboardGenerationStoredReferenceOrder(form);
  const canonical = upstream.map((node) => node.id);
  if (stored.length && stored.length === canonical.length && stored.every((id, index) => id === canonical[index])) return false;
  // Older releases incorrectly persisted prompt mention order in
  // referenceOrder. Repair that field from the durable incoming-edge order.
  writeWhiteboardGenerationReferenceOrder(form, canonical);
  return true;
};

const migrateWhiteboardGenerationPromptReferenceSequence = (form, upstream = []) => {
  if (!form || !upstream.length || whiteboardGenerationPromptReferenceSequence(form).length) return false;
  const input = whiteboardGenerationPromptInput(form);
  const prompt = String(input?.value || "");
  if (!prompt) return false;
  // Before the order bug was fixed, the hidden referenceOrder field held the
  // prompt occurrence order. Use it once as a legacy alias map so existing
  // labels can be mapped back to node IDs without changing the prompt text.
  const legacyStoredOrder = whiteboardGenerationStoredReferenceOrder(form);
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const legacyStoredAliases = legacyStoredOrder.length
    ? whiteboardGenerationReferenceAliases(upstream, legacyStoredOrder)
    : new Map();
  const legacyAliases = whiteboardGenerationLegacyReferenceAliases(upstream);
  const nodeByLabel = new Map();
  upstream.forEach((node) => {
    if (legacyAliases.has(node.id)) nodeByLabel.set(legacyAliases.get(node.id), node);
    if (aliases.has(node.id)) nodeByLabel.set(aliases.get(node.id), node);
    // Give the pre-fix persisted order the final say while migrating. This
    // is the only moment old labels are interpreted; the field is replaced
    // with the canonical edge order immediately afterwards.
    if (legacyStoredAliases.has(node.id)) nodeByLabel.set(legacyStoredAliases.get(node.id), node);
  });
  const orderedIds = [];
  for (const match of prompt.matchAll(/@「([^」]+)」/gu)) {
    const node = nodeByLabel.get(match[1]);
    if (node) orderedIds.push(node.id);
  }
  if (!orderedIds.length) return false;
  writeWhiteboardGenerationPromptReferenceSequence(form, orderedIds);
  return true;
};

const refreshWhiteboardGenerationInlineMentionLabels = (form, aliases) => {
  const editor = whiteboardGenerationRichPrompt(form);
  if (!editor || !(aliases instanceof Map)) return false;
  let changed = false;
  editor.querySelectorAll("[data-rich-mention-node-id]").forEach((mention) => {
    const nodeId = String(mention.dataset.richMentionNodeId || "").trim();
    const label = String(aliases.get(nodeId) || "").trim();
    if (!nodeId || !label) return;
    const token = `@「${label}」`;
    if (mention.dataset.richMentionToken !== token) {
      mention.dataset.richMentionToken = token;
      changed = true;
    }
    const title = `${label}；右键替换参考`;
    if (mention.title !== title) {
      mention.title = title;
      changed = true;
    }
    const strong = mention.querySelector("strong");
    if (strong && strong.textContent !== label) {
      strong.textContent = label;
      changed = true;
    }
  });
  if (changed) syncWhiteboardGenerationPromptReferenceSequenceFromEditor(form);
  return changed;
};

const whiteboardGenerationIncludesTarget = (form) => form?.elements?.includeTargetReference?.value === "true";

const writeWhiteboardGenerationIncludesTarget = (form, include) => {
  if (!form?.elements?.includeTargetReference) return;
  form.elements.includeTargetReference.value = include ? "true" : "";
  form.elements.includeTargetReference.dispatchEvent(new Event("change", { bubbles: true }));
};

const whiteboardGenerationReferenceSemanticLabel = (node) => {
  const reference = node?.reference;
  const skillReference = ["skill", "capability"].includes(reference?.type);
  const selectionNames = skillReference
    ? (reference.skillSelections ?? []).map((selection) => selection?.name || selection?.id || selection?.relativePath).filter(Boolean)
    : [];
  const source = skillReference
    ? reference.title || selectionNames.join("、") || reference.id || node?.name
    : node?.name || whiteboardNodeKindLabel(node) || String(node?.text || "").split(/\r?\n/).find(Boolean);
  return String(source || "上游卡片")
    .replace(/[「」\r\n]/gu, " ")
    .replace(/\s+/gu, " ")
    .trim()
    .slice(0, 80) || "上游卡片";
};

const whiteboardGenerationReferenceTypeLabel = (node) => node?.reference?.type === "capability"
  ? node.reference.nodeType === "group" ? "模组" : "模块"
  : node?.reference?.type === "skill" ? "Skill" : whiteboardNodeKindLabel(node) || "文字卡片";

const whiteboardGenerationReferenceSearchText = (node, displayLabel = "") => {
  const reference = node?.reference;
  const skillTerms = ["skill", "capability"].includes(reference?.type)
    ? [
        reference.title,
        reference.id,
        ...(reference.skillSelections ?? []).flatMap((selection) => [selection?.name, selection?.id, selection?.relativePath]),
      ]
    : [];
  return [displayLabel, node?.name, whiteboardGenerationReferenceTypeLabel(node), ...skillTerms, whiteboardNodeSummary(node)]
    .map((value) => String(value || ""))
    .join(" ")
    .toLowerCase();
};

const whiteboardGenerationReferenceAliases = (upstream = [], referenceOrder = []) => {
  const ordered = Array.isArray(referenceOrder) && referenceOrder.length
    ? orderWhiteboardGenerationNodes(upstream, { elements: { referenceOrder: { value: referenceOrder.join(",") } } })
    : upstream;
  return new Map(ordered.map((node, index) => {
    const sequence = index + 1;
    const label = node.kind === "image"
      ? `图片${sequence}`
      : node.kind === "video"
        ? `视频${sequence}`
        : whiteboardGenerationReferenceSemanticLabel(node);
    return [node.id, label];
  }));
};

// Provider-facing prompts may not contain Shensi's internal @「…」 markers.
// Keep this list tied to the currently resolved upstream nodes so a user's
// ordinary @ text, or an unresolved marker, is never silently removed.
const whiteboardGenerationProviderReferenceTokens = (generationContext = {}) => {
  const upstream = Array.isArray(generationContext.upstream) ? generationContext.upstream : [];
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  return [...new Set([...aliases.values()]
    .map((label) => String(label || "").trim())
    .filter(Boolean)
    .map((label) => `@「${label}」`))];
};

// Drafts created before the global sequence numbering used per-media counters.
// Keep those labels readable long enough for the rich editor to migrate them
// to the current node-id-backed labels without losing an inserted reference.
const whiteboardGenerationLegacyReferenceAliases = (upstream = []) => {
  const counters = { image: 0, video: 0 };
  return new Map(upstream.map((node) => {
    if (["image", "video"].includes(node.kind)) counters[node.kind] += 1;
    const label = node.kind === "image"
      ? `图片${counters.image}`
      : node.kind === "video"
        ? `视频${counters.video}`
        : node.name || whiteboardNodeKindLabel(node) || String(node.text || "").split(/\r?\n/).find(Boolean)?.slice(0, 36) || "上游卡片";
    return [node.id, label];
  }));
};

const whiteboardGenerationReferenceMarkup = (node, explicit = false, {
  target = false,
  displayLabel = "",
  referenceIndex = 0,
  frameLabel = "",
  referenceGroup = "",
  draggable = !target,
  extraClass = "",
} = {}) => {
  const mediaNode = ["image", "video", "audio"].includes(node.kind) && node.file;
  const label = whiteboardGenerationReferenceSemanticLabel(node);
  const visibleLabel = displayLabel || label;
  const compactText = String(node.text ?? "").replace(/\s+/g, " ").trim();
  const preview = node.kind === "image" && node.file
    ? `<span class="whiteboard-generation-reference-preview image" data-attachment-preview="image" title="${escapeHtml(label)}"><img src="${escapeHtml(whiteboardAttachmentUrl(node))}" alt="${escapeHtml(label)}" loading="lazy" decoding="async" /></span>`
    : node.kind === "video" && node.file
      ? `<span class="whiteboard-generation-reference-preview video whiteboard-static-video-preview" data-attachment-preview="video" data-attachment-src="${escapeHtml(`${whiteboardAttachmentUrl(node)}#t=0.001`)}" title="${escapeHtml(label)}">${node.thumbnailRelativePath ? `<img src="${escapeHtml(workspaceAttachmentUrl(node.thumbnailRelativePath, state.activeDocument))}" alt="${escapeHtml(label)}" loading="lazy" decoding="async" />` : `<span class="whiteboard-card-overview-placeholder">${icon("\uE714", "视频")}</span>`}<span class="attachment-video-play" aria-hidden="true">${icon("\uE768")}</span></span>`
      : node.kind === "audio" && node.file
    ? `<span class="whiteboard-generation-reference-preview audio" title="${escapeHtml(label)}"><audio src="${escapeHtml(whiteboardAttachmentUrl(node))}" preload="metadata" aria-label="${escapeHtml(label)}"></audio><button class="whiteboard-generation-audio-play" type="button" data-whiteboard-generation-audio-play aria-label="${escapeHtml(`播放${label}`)}" title="${escapeHtml(`播放${label}`)}">${icon("\uE768", "播放音频")}</button></span>`
      : `<span class="whiteboard-generation-reference-preview text"><span>${escapeHtml(compactText.slice(0, 90) || "空白卡片")}</span></span>`;
  const detail = mediaNode
    ? whiteboardNodeKindLabel(node)
    : ["skill", "capability"].includes(node.reference?.type)
      ? whiteboardGenerationReferenceTypeLabel(node)
      : `${compactText.length} 字`;
  const mediaBadge = mediaNode && (frameLabel || referenceIndex > 0)
    ? `<span class="whiteboard-generation-reference-index${frameLabel ? " is-frame-label" : ""}" aria-hidden="true">${escapeHtml(frameLabel || referenceIndex)}</span>`
    : "";
  const controls = target
    ? ""
    : `<button class="icon-button bare whiteboard-generation-reference-remove" type="button" data-remove-whiteboard-generation-reference="${escapeHtml(node.id)}" title="移除参考并断开连线" aria-label="移除 ${escapeHtml(label)} 并断开连线">${icon("\uE711", "移除参考并断开连线")}</button>`;
  return `<article class="whiteboard-generation-reference${mediaNode ? " is-media" : ""}${explicit ? " is-explicit" : ""}${target ? " is-target" : ""}${extraClass ? ` ${escapeHtml(extraClass)}` : ""}" data-generation-reference="${escapeHtml(node.id)}" data-generation-reference-role="${target ? "target" : "upstream"}"${referenceGroup ? ` data-generation-reference-group="${escapeHtml(referenceGroup)}"` : ""}${!target && draggable ? ` draggable="true" aria-label="${escapeHtml(`拖拽 ${visibleLabel} 插入提示词，或调整引用顺序`)}"` : ""}>${preview}${mediaBadge}<span class="whiteboard-generation-reference-meta"><strong title="${escapeHtml(label)}">${target ? `${escapeHtml(uiText("当前卡片"))}｜` : ""}${escapeHtml(visibleLabel)}</strong><small>${escapeHtml(detail)}</small></span>${controls}</article>`;
};

const updateWhiteboardGenerationMentionAliases = (form, aliases, previousAliases = null) => {
  const editor = whiteboardGenerationRichPrompt(form);
  const input = whiteboardGenerationPromptInput(form);
  if (!editor && !input) return;
  if (editor) {
    editor.querySelectorAll("[data-rich-mention-node-id]").forEach((mention) => {
      const label = aliases.get(mention.dataset.richMentionNodeId);
      if (!label) return;
      mention.dataset.richMentionToken = `@「${label}」`;
      mention.title = `${label}；右键替换参考`;
      const strong = mention.querySelector("strong");
      if (strong) strong.textContent = label;
    });
    syncWhiteboardRichPromptValue(form);
    rememberWhiteboardRichPromptSelection(form);
    return;
  }
  if (!previousAliases) return;
  const replacements = [...previousAliases.entries()]
    .map(([nodeId, oldLabel]) => [oldLabel, aliases.get(nodeId)])
    .filter(([, nextLabel]) => nextLabel && nextLabel !== undefined)
    .filter(([oldLabel, nextLabel]) => oldLabel !== nextLabel);
  if (!replacements.length) return;
  const replacementMap = new Map(replacements);
  const labels = [...replacementMap.keys()].sort((a, b) => b.length - a.length);
  const tokenPattern = new RegExp(`@「(${labels.map((label) => String(label).replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")).join("|")})」`, "gu");
  const nextValue = String(input.value || "").replace(tokenPattern, (_, label) => `@「${replacementMap.get(label) || label}」`);
  if (nextValue === input.value) return;
  input.value = nextValue;
  input.dispatchEvent(new Event("input", { bubbles: true }));
};

const whiteboardGenerationFormsForNode = (nodeId) => whiteboardGenerationConfigs()
  .map((config) => config.form)
  .filter((form) => form?.dataset?.nodeId === String(nodeId));

const whiteboardGenerationDraftEntriesForNode = (cache, nodeId) => Object.entries(cache?.entries || {})
  .filter(([, entry]) => entry?.workspaceId === workspaceIdentity()
    && entry?.documentId === state.activeDocument
    && entry?.nodeId === String(nodeId));

const whiteboardGenerationTokenPattern = (label) => new RegExp(
  `@「${String(label).replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}」`,
  "gu",
);

const rewriteWhiteboardGenerationDraftReferenceAliases = (nodeId, previousAliases, aliases) => {
  const replacements = [...previousAliases.entries()]
    .map(([sourceId, oldLabel]) => ({ sourceId, oldLabel, newLabel: aliases.get(sourceId) }))
    .filter((item) => item.newLabel && item.oldLabel !== item.newLabel);
  if (!replacements.length) return false;
  const cache = readWhiteboardGenerationDraftCache();
  let changed = false;
  for (const [key, entry] of whiteboardGenerationDraftEntriesForNode(cache, nodeId)) {
    const promptKey = entry.channel === "text" ? "instruction" : "prompt";
    const explicitIds = new Set(String(entry.values?.explicitReferences || "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean));
    let prompt = String(entry.values?.[promptKey] || "");
    for (const { sourceId, oldLabel, newLabel } of replacements) {
      if (!explicitIds.has(sourceId)) continue;
      prompt = prompt.replace(whiteboardGenerationTokenPattern(oldLabel), `@「${newLabel}」`);
    }
    if (prompt === String(entry.values?.[promptKey] || "")) continue;
    cache.entries[key] = { ...entry, values: { ...entry.values, [promptKey]: prompt } };
    changed = true;
  }
  if (changed) {
    writeWhiteboardGenerationDraftCache(cache);
    markWhiteboardGenerationDraftDurable();
  }
  return changed;
};

const reorderWhiteboardGenerationReferences = (form, sourceNodeId, destinationNodeId, placement = "before") => {
  const documentState = activeWhiteboardDocument();
  const targetNodeId = form?.dataset.nodeId;
  if (!documentState || !targetNodeId || !sourceNodeId || !destinationNodeId || sourceNodeId === destinationNodeId) return false;
  const upstream = whiteboardGenerationSources(documentState.canvas, targetNodeId).upstream;
  // Dragging acts on the order the user sees, not on an obsolete edge array
  // captured before the last render. The edge order remains canonical after
  // the move; the prompt occurrence sequence is never touched here.
  const orderedIds = orderWhiteboardGenerationNodes(upstream, form).map((node) => node.id);
  const displayedUpstream = orderedIds.map((id) => upstream.find((node) => node.id === id)).filter(Boolean);
  const previousAliases = whiteboardGenerationReferenceAliases(displayedUpstream);
  const sourceIndex = orderedIds.indexOf(sourceNodeId);
  if (sourceIndex < 0 || !orderedIds.includes(destinationNodeId)) return false;
  orderedIds.splice(sourceIndex, 1);
  const destinationIndex = orderedIds.indexOf(destinationNodeId);
  orderedIds.splice(destinationIndex + (placement === "after" ? 1 : 0), 0, sourceNodeId);
  if (orderedIds.every((id, index) => id === upstream[index]?.id)) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  documentState.canvas = reorderCanvasIncomingEdges(documentState.canvas, targetNodeId, orderedIds);
  const reordered = whiteboardGenerationSources(documentState.canvas, targetNodeId).upstream;
  const aliases = whiteboardGenerationReferenceAliases(reordered);
  whiteboardGenerationFormsForNode(targetNodeId).forEach((generationForm) => {
    writeWhiteboardGenerationReferenceOrder(generationForm, reordered.map((node) => node.id));
    updateWhiteboardGenerationMentionAliases(generationForm, aliases, previousAliases);
    saveWhiteboardGenerationDraft(generationForm.closest("dialog"), { active: generationForm.closest("dialog")?.open, open: generationForm.closest("dialog")?.open });
  });
  rewriteWhiteboardGenerationDraftReferenceAliases(targetNodeId, previousAliases, aliases);
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: "调整生成参考顺序" });
  persist();
  renderWhiteboard(documentState);
  whiteboardGenerationFormsForNode(targetNodeId).forEach((generationForm) => {
    renderWhiteboardGenerationReferences(generationForm.querySelector(".whiteboard-generation-references"), targetNodeId);
  });
  return true;
};

const setWhiteboardGenerationAudioPreviewState = (preview, playing) => {
  const button = preview?.querySelector?.("[data-whiteboard-generation-audio-play]");
  const audio = preview?.querySelector?.("audio");
  if (!button || !audio) return;
  const label = audio.getAttribute("aria-label") || "音频";
  button.dataset.playing = playing ? "true" : "false";
  button.innerHTML = icon(playing ? "\uE769" : "\uE768", playing ? "暂停音频" : "播放音频");
  button.title = `${playing ? "暂停" : "播放"}${label}`;
  button.setAttribute("aria-label", `${playing ? "暂停" : "播放"}${label}`);
};

const toggleWhiteboardGenerationAudioPreview = async (button) => {
  const preview = button?.closest?.(".whiteboard-generation-reference-preview.audio");
  const audio = preview?.querySelector?.("audio");
  if (!preview || !audio) return;
  if (!audio.paused) {
    audio.pause();
    setWhiteboardGenerationAudioPreviewState(preview, false);
    return;
  }
  document.querySelectorAll(".whiteboard-generation-reference-preview.audio audio").forEach((other) => {
    if (other === audio || other.paused) return;
    other.pause();
    setWhiteboardGenerationAudioPreviewState(other.closest(".whiteboard-generation-reference-preview.audio"), false);
  });
  try {
    await audio.play();
    setWhiteboardGenerationAudioPreviewState(preview, true);
    audio.addEventListener("ended", () => setWhiteboardGenerationAudioPreviewState(preview, false), { once: true });
  } catch (error) {
    setWhiteboardGenerationAudioPreviewState(preview, false);
    showToast(`音频无法播放：${error.message || "请检查原文件"}`);
  }
};

const whiteboardGenerationReferenceRenderCache = new WeakMap();

const whiteboardVideoFrameLabel = (index, mode) => {
  const english = globalUiPreferences.uiLanguage === "en-US";
  if (mode === "first_last_frame") return uiText(index === 0 ? "首帧" : "尾帧");
  return english ? `Frame ${index + 1}` : `第${index + 1}帧`;
};

const whiteboardVideoEmptyFrameMarkup = (index, mode) => {
  const label = whiteboardVideoFrameLabel(index, mode);
  return `<button class="whiteboard-generation-reference-add whiteboard-video-empty-frame" type="button" data-whiteboard-generation-add-reference data-video-frame-slot="${index}" aria-haspopup="menu" aria-expanded="false" title="${escapeHtml(`${label}：${uiText("添加参考")}`)}"><span class="whiteboard-generation-reference-add-glyph" aria-hidden="true">+</span><span>${escapeHtml(label)}</span></button>`;
};

const whiteboardVideoTransitionMarkup = (transition) => {
  const prompt = String(transition?.prompt || "").trim();
  const duration = Number(transition?.duration) || 4;
  const ariaLabel = globalUiPreferences.uiLanguage === "en-US"
    ? `Edit content description from frame ${transition.index + 1} to frame ${transition.index + 2}`
    : `编辑第 ${transition.index + 1} 帧到第 ${transition.index + 2} 帧的内容描述`;
  return `<button class="whiteboard-video-transition-slot${prompt ? " has-content" : ""}" type="button" data-whiteboard-video-transition-index="${transition.index}" aria-label="${escapeHtml(ariaLabel)}" title="${escapeHtml(prompt || uiText("添加内容描述"))}">${prompt ? `<strong>${duration}s</strong><small>${escapeHtml(prompt)}</small>` : `<span aria-hidden="true">+</span><small>${escapeHtml(uiText("内容描述"))}</small>`}</button>`;
};

const whiteboardVideoSmartEditEmptyPrimaryMarkup = () => `<button class="whiteboard-generation-reference-add whiteboard-smart-edit-primary-empty" type="button" data-whiteboard-generation-add-reference data-smart-edit-slot="primary" aria-haspopup="menu" aria-expanded="false" title="${escapeHtml(uiText("添加编辑视频"))}"><span class="whiteboard-generation-reference-add-glyph" aria-hidden="true">+</span><span>${escapeHtml(uiText("编辑视频"))}</span></button>`;

const whiteboardVideoSmartEditAddMarkup = () => `<button class="whiteboard-generation-reference-add whiteboard-smart-edit-reference-add" type="button" data-whiteboard-generation-add-reference data-smart-edit-slot="additional" aria-haspopup="menu" aria-expanded="false" title="${escapeHtml(uiText("添加参考内容"))}"><span class="whiteboard-generation-reference-add-glyph" aria-hidden="true">+</span><span>${escapeHtml(uiText("添加参考"))}</span></button>`;

const whiteboardVideoSmartEditMarkup = ({ nodes, explicitIds, aliases }) => {
  const mediaNodes = nodes.filter((node) => ["image", "video", "audio"].includes(node.kind) && node.file);
  const ordered = smartEditOrderedReferences(mediaNodes);
  const primary = ordered[0]?.kind === "video" ? ordered[0] : null;
  const additional = (primary ? ordered.slice(1) : mediaNodes).slice(0, SMART_EDIT_MAX_ADDITIONAL_REFERENCES);
  const primaryMarkup = primary
    ? whiteboardGenerationReferenceMarkup(primary, explicitIds.has(primary.id), {
      displayLabel: uiText("编辑视频"),
      referenceIndex: 1,
      frameLabel: uiText("编辑视频"),
      referenceGroup: "smart-edit-primary",
      draggable: false,
      extraClass: "is-smart-edit-primary",
    })
    : whiteboardVideoSmartEditEmptyPrimaryMarkup();
  const referenceMarkup = additional.map((node, index) => whiteboardGenerationReferenceMarkup(node, explicitIds.has(node.id), {
    displayLabel: aliases.get(node.id) || "",
    referenceIndex: index + 1,
    referenceGroup: "smart-edit-additional",
    extraClass: "is-smart-edit-additional",
  })).join("");
  const addMarkup = additional.length < SMART_EDIT_MAX_ADDITIONAL_REFERENCES ? whiteboardVideoSmartEditAddMarkup() : "";
  return `<div class="whiteboard-smart-edit-slots"><section class="whiteboard-smart-edit-slot is-primary"><header><strong>${escapeHtml(uiText("编辑视频"))}</strong></header><div>${primaryMarkup}</div></section><section class="whiteboard-smart-edit-slot is-references" tabindex="0"><header><strong>${escapeHtml(uiText("参考内容"))}</strong><small>${additional.length}/${SMART_EDIT_MAX_ADDITIONAL_REFERENCES}</small></header><div class="whiteboard-smart-edit-reference-stack">${referenceMarkup}${addMarkup}</div></section></div>`;
};

const whiteboardVideoReferenceListMarkup = ({ form, nodes, explicitIds, aliases, addReferenceButton }) => {
  const mode = String(form?.elements?.generationMode?.value || "smart_params");
  if (mode === "first_last_frame") {
    const frames = nodes.filter((node) => node.kind === "image" && node.file).slice(0, 2);
    const slots = Array.from({ length: 2 }, (_, index) => frames[index]
      ? whiteboardGenerationReferenceMarkup(frames[index], explicitIds.has(frames[index].id), {
        displayLabel: aliases.get(frames[index].id) || "",
        referenceIndex: index + 1,
        frameLabel: whiteboardVideoFrameLabel(index, mode),
      })
      : whiteboardVideoEmptyFrameMarkup(index, mode));
    const swapLabel = uiText("互换首帧与尾帧");
    return `${slots[0]}<button class="whiteboard-video-frame-swap" type="button" data-whiteboard-video-frame-swap${frames.length < 2 ? " disabled" : ""} title="${escapeHtml(swapLabel)}" aria-label="${escapeHtml(swapLabel)}">${icon("\uE8AB", swapLabel)}</button>${slots[1]}`;
  }
  if (mode === "smart_multiframe") {
    const frames = nodes.filter((node) => node.kind === "image" && node.file);
    const transitions = normalizeSmartMultiframeTransitions(form.elements.multiframeTransitions?.value, {
      frameCount: frames.length,
      defaultDuration: Number(form.elements.duration?.value) || 4,
    });
    if (form.elements.multiframeTransitions) form.elements.multiframeTransitions.value = JSON.stringify(transitions);
    const markup = [];
    frames.forEach((node, index) => {
      markup.push(whiteboardGenerationReferenceMarkup(node, explicitIds.has(node.id), {
        displayLabel: aliases.get(node.id) || "",
        referenceIndex: index + 1,
        frameLabel: whiteboardVideoFrameLabel(index, mode),
      }));
      if (index < frames.length - 1) markup.push(whiteboardVideoTransitionMarkup(transitions[index]));
    });
    if (frames.length < SMART_MULTIFRAME_MAX_FRAMES) markup.push(whiteboardVideoEmptyFrameMarkup(frames.length, mode));
    return markup.join("");
  }
  if (mode === "smart_edit") return whiteboardVideoSmartEditMarkup({ nodes, explicitIds, aliases });
  return `${nodes.map((node, index) => whiteboardGenerationReferenceMarkup(node, explicitIds.has(node.id), { displayLabel: aliases.get(node.id) || "", referenceIndex: index + 1 })).join("")}${addReferenceButton}`;
};

function renderWhiteboardGenerationReferences(container, nodeId) {
  if (!container) return;
  const form = container.closest("form");
  const { target, upstream: sourceUpstream } = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, nodeId);
  const rawUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  migrateWhiteboardGenerationPromptReferenceSequence(form, rawUpstream);
  migrateWhiteboardGenerationReferenceOrder(form, rawUpstream);
  const upstream = orderWhiteboardGenerationNodes(rawUpstream, form);
  const targetHasInput = Boolean(target && whiteboardGenerationInputSummary(target));
  const includeTarget = false;
  if (whiteboardGenerationIncludesTarget(form)) writeWhiteboardGenerationIncludesTarget(form, false);
  const visibleInputs = [...upstream];
  const generationInputs = [...upstream];
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  // Keep focused editors intact while refreshing only the visible labels and
  // serialized tokens for existing mentions. This preserves the caret and
  // prompt text position when the top tray changes asynchronously.
  refreshWhiteboardGenerationInlineMentionLabels(form, aliases);
  const upstreamIds = new Set(upstream.map((node) => node.id));
  const explicitIds = new Set([...whiteboardGenerationExplicitReferenceIds(form)].filter((id) => upstreamIds.has(id)));
  if (explicitIds.size !== whiteboardGenerationExplicitReferenceIds(form).size) writeWhiteboardGenerationExplicitReferenceIds(form, explicitIds);
  const english = globalUiPreferences.uiLanguage === "en-US";
  const canAddReferences = form === elements.whiteboardImageForm || form === elements.whiteboardVideoForm || form === elements.whiteboardAudioForm;
  const mediaReferenceLabel = form === elements.whiteboardImageForm ? "图片" : form === elements.whiteboardVideoForm ? "视频" : "音频";
  const inputSummary = english
    ? `${generationInputs.length} ${generationInputs.length === 1 ? "upstream item" : "upstream items"} will be read; the target card is output-only${upstream.length ? "; use @ to mark upstream priority" : ""}${explicitIds.size ? `; ${explicitIds.size} marked` : ""}`
    : `${generationInputs.length} 项上游会真实读取；目标卡片只用于写入结果${upstream.length ? "；@ 可标记上游重点" : ""}${explicitIds.size ? `，已标记 ${explicitIds.size} 项` : ""}`;
  const addReferenceButton = canAddReferences
    ? `<button class="whiteboard-generation-reference-add" type="button" data-whiteboard-generation-add-reference aria-haspopup="menu" aria-expanded="false" title="${escapeHtml(uiText("添加参考"))}"><span class="whiteboard-generation-reference-add-glyph" aria-hidden="true">+</span><span>${escapeHtml(uiText("添加参考"))}</span></button>`
    : "";
  const addReferenceMenu = canAddReferences
    ? `<div class="whiteboard-generation-reference-add-menu" data-whiteboard-generation-reference-add-menu role="menu" aria-label="添加${mediaReferenceLabel}参考" popover="manual" hidden><button type="button" role="menuitem" data-whiteboard-generation-reference-source="canvas">${icon("\uE8F1")}<span><strong>白板已有卡片</strong><small>选择当前白板中的一张或多张卡片</small></span></button><button type="button" role="menuitem" data-whiteboard-generation-reference-source="upload">${icon("\uE898")}<span><strong>上传本地文件</strong><small>上传后自动建立卡片并连接为上游</small></span></button><button type="button" role="menuitem" data-whiteboard-generation-reference-source="history">${icon("\uE81C")}<span><strong>全部资产</strong><small>复用已上传或生成过的资产</small></span></button></div>`
    : "";
  const referenceListMarkup = form === elements.whiteboardVideoForm
    ? whiteboardVideoReferenceListMarkup({ form, nodes: visibleInputs, explicitIds, aliases, addReferenceButton })
    : `${visibleInputs.map((node, index) => whiteboardGenerationReferenceMarkup(node, explicitIds.has(node.id), { displayLabel: aliases.get(node.id) || "", referenceIndex: index + 1 })).join("")}${addReferenceButton}`;
  const referenceHeader = visibleInputs.length
    ? `<header><span class="whiteboard-generation-reference-heading"><strong>${escapeHtml(uiText("参考"))}</strong><small>${escapeHtml(inputSummary)}</small></span><button class="whiteboard-generation-reference-clear" type="button" data-clear-whiteboard-generation-references title="${escapeHtml(uiText("清空全部参考"))}" aria-label="${escapeHtml(uiText("清空全部参考"))}">${icon("\uE711", "清空全部参考")}<span>${escapeHtml(uiText("清空参考"))}</span></button></header>`
    : "";
  const markup = visibleInputs.length || canAddReferences
    ? `${referenceHeader}<div class="whiteboard-generation-reference-list">${referenceListMarkup}</div>${addReferenceMenu}`
    : "";
  container.classList.toggle("is-media-reference-picker", canAddReferences);
  container.classList.toggle("has-references", visibleInputs.length > 0);
  container.hidden = visibleInputs.length === 0 && !canAddReferences;
  if (whiteboardGenerationReferenceRenderCache.get(container) !== markup) {
    container.innerHTML = markup;
    whiteboardGenerationReferenceRenderCache.set(container, markup);
  }
  renderWhiteboardGenerationInlineMentions(form);
  const dialog = container.closest("dialog");
  if (dialog?.open) requestAnimationFrame(() => positionWhiteboardGenerationDialog(dialog));
}

const positionWhiteboardGenerationReferenceAddMenu = (container) => {
  const button = container?.querySelector('[data-whiteboard-generation-add-reference][aria-expanded="true"]')
    || container?.querySelector("[data-whiteboard-generation-add-reference]");
  const menu = container?.querySelector("[data-whiteboard-generation-reference-add-menu]");
  if (!button || !menu || menu.hidden || button.getAttribute("aria-expanded") !== "true") return;
  const margin = 10;
  const gap = 6;
  const buttonRect = button.getBoundingClientRect();
  const width = Math.min(320, Math.max(240, window.innerWidth - margin * 2));
  menu.style.width = `${Math.round(width)}px`;
  const height = Math.min(menu.scrollHeight, window.innerHeight - margin * 2);
  const belowTop = buttonRect.bottom + gap;
  const top = belowTop + height <= window.innerHeight - margin
    ? belowTop
    : Math.max(margin, buttonRect.top - gap - height);
  menu.style.left = `${Math.round(Math.min(Math.max(buttonRect.left, margin), window.innerWidth - width - margin))}px`;
  menu.style.top = `${Math.round(top)}px`;
};

const setWhiteboardGenerationReferenceAddMenuOpen = (container, open, activeButton = null) => {
  const buttons = [...(container?.querySelectorAll?.("[data-whiteboard-generation-add-reference]") || [])];
  const button = activeButton || buttons.find((item) => item.getAttribute("aria-expanded") === "true") || buttons[0];
  const menu = container?.querySelector("[data-whiteboard-generation-reference-add-menu]");
  if (!button || !menu) return;
  if (!open) {
    if (menu.matches?.(":popover-open")) {
      try { menu.hidePopover(); } catch {}
    }
    menu.hidden = true;
    buttons.forEach((item) => item.setAttribute("aria-expanded", "false"));
    return;
  }
  menu.hidden = false;
  if (typeof menu.showPopover === "function" && !menu.matches(":popover-open")) {
    try { menu.showPopover(); } catch {}
  }
  buttons.forEach((item) => item.setAttribute("aria-expanded", String(item === button)));
  positionWhiteboardGenerationReferenceAddMenu(container);
  requestAnimationFrame(() => positionWhiteboardGenerationReferenceAddMenu(container));
};

const whiteboardGenerationPromptInput = (form) => form?.elements?.instruction || form?.elements?.prompt;
const whiteboardGenerationRichPrompt = (form) => form?.querySelector(".whiteboard-generation-inline-mentions");
// Browser paste engines use different block elements for the same visual
// paragraph.  The generation prompt intentionally stores plain text (not
// arbitrary rich styling), but block boundaries must survive every
// serialize/rebuild cycle, especially when inserting an @ reference triggers
// a sync of the contenteditable editor into the hidden textarea.

// The editor element itself is a DIV container, not user content. Serialize
// only its children so the synthetic wrapper newline is omitted while real
// trailing BR/block newlines remain intact.
const serializeWhiteboardRichPromptRaw = (editor) => [...(editor?.childNodes || [])]
  .map(serializeWhiteboardRichPromptNode)
  .join("");

const serializeWhiteboardRichPrompt = (editor) => serializeWhiteboardRichPromptRaw(editor)
  .slice(0, WHITEBOARD_RICH_PROMPT_MAX_CHARACTERS);

const whiteboardGenerationPromptCharacterCount = (value) => Array.from(String(value ?? "")).length;

const updateWhiteboardGenerationPromptCounts = (form) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  const totalOutput = form?.querySelector?.("[data-whiteboard-prompt-total-count]");
  const selectionOutput = form?.querySelector?.("[data-whiteboard-prompt-selection-count]");
  if (!input || !totalOutput || !selectionOutput) return;
  const editorOwnsValue = editor && document.activeElement === editor;
  const value = editorOwnsValue ? serializeWhiteboardRichPrompt(editor) : String(input.value || "");
  let selectedCount = 0;
  if (editorOwnsValue) {
    const selection = document.getSelection();
    if (selection?.rangeCount && editor.contains(selection.anchorNode) && editor.contains(selection.focusNode)) {
      try {
        selectedCount = whiteboardGenerationPromptCharacterCount(
          serializeWhiteboardRichPromptNode(selection.getRangeAt(0).cloneContents()),
        );
      } catch {}
    }
  } else if (document.activeElement === input && Number.isFinite(input.selectionStart)) {
    selectedCount = whiteboardGenerationPromptCharacterCount(input.value.slice(
      input.selectionStart,
      input.selectionEnd ?? input.selectionStart,
    ));
  }
  selectionOutput.textContent = `已选 ${selectedCount.toLocaleString("zh-CN")} 字`;
  totalOutput.textContent = `共 ${whiteboardGenerationPromptCharacterCount(value).toLocaleString("zh-CN")} 字`;
};

const whiteboardRichPromptBeforeCaret = (editor) => {
  const selection = document.getSelection();
  if (!selection?.rangeCount || !editor?.contains(selection.anchorNode)) return serializeWhiteboardRichPrompt(editor);
  return serializeWhiteboardRichPromptBeforePoint(editor, selection.anchorNode, selection.anchorOffset);
};

const syncWhiteboardRichPromptValue = (form) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  if (!input || !editor) return;
  const rawValue = serializeWhiteboardRichPromptRaw(editor);
  input.value = rawValue.slice(0, WHITEBOARD_RICH_PROMPT_MAX_CHARACTERS);
  if (rawValue.length > WHITEBOARD_RICH_PROMPT_MAX_CHARACTERS && editor.dataset.limitRepairing !== "true") {
    editor.dataset.limitRepairing = "true";
    renderWhiteboardGenerationInlineMentions(form, { force: true });
    delete editor.dataset.limitRepairing;
    placeWhiteboardRichPromptCaretAtEnd(form, { focus: document.activeElement === editor });
    if (editor.dataset.limitNoticeShown !== "true") {
      editor.dataset.limitNoticeShown = "true";
      showToast(`生成要求最多 ${WHITEBOARD_RICH_PROMPT_MAX_CHARACTERS.toLocaleString("zh-CN")} 字，超出内容未写入`);
    }
  } else if (rawValue.length < WHITEBOARD_RICH_PROMPT_MAX_CHARACTERS) {
    delete editor.dataset.limitNoticeShown;
  }
  syncWhiteboardGenerationPromptReferenceSequenceFromEditor(form);
};

const whiteboardRichPromptOffsetForPoint = (editor, container, offset) => {
  if (!editor || !container || (!editor.contains(container) && container !== editor)) return null;
  try {
    return serializeWhiteboardRichPromptBeforePoint(editor, container, offset).length;
  } catch {
    return null;
  }
};

const whiteboardRichPromptSelectionOffsets = (editor, range = null) => {
  const activeRange = range || (() => {
    const selection = document.getSelection();
    return selection?.rangeCount ? selection.getRangeAt(0) : null;
  })();
  if (!editor || !activeRange
    || (!editor.contains(activeRange.startContainer) && activeRange.startContainer !== editor)
    || (!editor.contains(activeRange.endContainer) && activeRange.endContainer !== editor)) return null;
  const start = whiteboardRichPromptOffsetForPoint(editor, activeRange.startContainer, activeRange.startOffset);
  const end = whiteboardRichPromptOffsetForPoint(editor, activeRange.endContainer, activeRange.endOffset);
  return Number.isFinite(start) && Number.isFinite(end) ? { start, end } : null;
};

const whiteboardRichPromptRawTextOffset = (value, requestedOffset) => {
  const text = String(value || "");
  const target = Math.max(0, Number(requestedOffset) || 0);
  let logicalOffset = 0;
  for (let rawOffset = 0; rawOffset < text.length; rawOffset += 1) {
    if (text[rawOffset] === WHITEBOARD_RICH_PROMPT_CARET_GUARD) continue;
    if (logicalOffset === target) return rawOffset;
    logicalOffset += 1;
  }
  return text.length;
};

const whiteboardRichPromptCaretPointAtOffset = (editor, requestedOffset) => {
  const target = Math.max(0, Math.min(serializeWhiteboardRichPrompt(editor).length, Number(requestedOffset) || 0));
  let consumed = 0;
  let found = null;
  const beforeNode = (node) => ({ container: node.parentNode, offset: [...node.parentNode.childNodes].indexOf(node) });
  const afterNode = (node) => {
    const point = beforeNode(node);
    return { container: point.container, offset: point.offset + 1 };
  };
  const beforeAtomicNode = (node) => node.previousSibling?.nodeType === Node.TEXT_NODE
    && node.previousSibling.data.includes(WHITEBOARD_RICH_PROMPT_CARET_GUARD)
    ? {
      container: node.previousSibling,
      offset: whiteboardRichPromptRawTextOffset(node.previousSibling.data, serializeWhiteboardRichPromptNode(node.previousSibling).length),
    }
    : beforeNode(node);
  const afterAtomicNode = (node) => node.nextSibling?.nodeType === Node.TEXT_NODE
    && node.nextSibling.data.includes(WHITEBOARD_RICH_PROMPT_CARET_GUARD)
    ? { container: node.nextSibling, offset: whiteboardRichPromptRawTextOffset(node.nextSibling.data, 0) }
    : afterNode(node);
  const walk = (parent) => {
    for (const node of [...parent.childNodes]) {
      if (found) return;
      if (node.nodeType === Node.TEXT_NODE) {
        const length = serializeWhiteboardRichPromptNode(node).length;
        if (target <= consumed + length) {
          found = { container: node, offset: whiteboardRichPromptRawTextOffset(node.data, target - consumed) };
          return;
        }
        consumed += length;
        continue;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) continue;
      if (node.matches("[data-rich-mention-token]")) {
        const length = String(node.dataset.richMentionToken || "").length;
        if (target <= consumed) {
          found = beforeAtomicNode(node);
          return;
        }
        if (target < consumed + length) {
          found = target - consumed < length / 2 ? beforeAtomicNode(node) : afterAtomicNode(node);
          return;
        }
        consumed += length;
        if (target === consumed) {
          found = afterAtomicNode(node);
          return;
        }
        continue;
      }
      if (node.tagName === "BR") {
        if (target <= consumed) {
          found = beforeNode(node);
          return;
        }
        consumed += 1;
        if (target <= consumed) {
          found = afterNode(node);
          return;
        }
        continue;
      }
      walk(node);
      if (found) return;
      if (node.tagName === "DIV") {
        if (target <= consumed) {
          found = afterNode(node);
          return;
        }
        consumed += 1;
        if (target <= consumed) {
          found = afterNode(node);
          return;
        }
      }
    }
  };
  walk(editor);
  return found || { container: editor, offset: editor.childNodes.length };
};

const rememberWhiteboardRichPromptSelection = (form, range = null) => {
  const editor = whiteboardGenerationRichPrompt(form);
  const selection = document.getSelection();
  const activeRange = range || (selection?.rangeCount ? selection.getRangeAt(0) : null);
  const offsets = whiteboardRichPromptSelectionOffsets(editor, activeRange);
  if (!activeRange || !offsets) return false;
  form._whiteboardRichPromptRange = activeRange.cloneRange();
  form._whiteboardRichPromptSelectionOffsets = { ...offsets };
  return true;
};

const placeWhiteboardRichPromptSelectionAtOffsets = (form, offsets, { focus = false } = {}) => {
  const editor = whiteboardGenerationRichPrompt(form);
  if (!editor) return false;
  if (!focus && document.activeElement !== editor) return false;
  if (focus) editor.focus({ preventScroll: true });
  const start = Math.max(0, Math.min(Number(offsets?.start) || 0, Number(offsets?.end) || 0));
  const end = Math.max(start, Math.max(Number(offsets?.start) || 0, Number(offsets?.end) || 0));
  const startPoint = whiteboardRichPromptCaretPointAtOffset(editor, start);
  const endPoint = whiteboardRichPromptCaretPointAtOffset(editor, end);
  if (!startPoint?.container || !endPoint?.container) return false;
  const range = document.createRange();
  range.setStart(startPoint.container, startPoint.offset);
  range.setEnd(endPoint.container, endPoint.offset);
  const selection = document.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);
  rememberWhiteboardRichPromptSelection(form, range);
  return true;
};

const placeWhiteboardRichPromptCaretAtOffset = (form, offset, options = {}) => placeWhiteboardRichPromptSelectionAtOffsets(
  form,
  { start: offset, end: offset },
  options,
);

const stabilizeWhiteboardRichPromptSelection = (form) => {
  const editor = whiteboardGenerationRichPrompt(form);
  const remembered = form?._whiteboardRichPromptSelectionOffsets;
  if (!editor || document.activeElement !== editor) return false;
  const live = whiteboardRichPromptSelectionOffsets(editor);
  if (!live) {
    if (remembered) return placeWhiteboardRichPromptSelectionAtOffsets(form, remembered, { focus: true });
    placeWhiteboardRichPromptCaretAtEnd(form, { focus: true });
    return true;
  }
  if (!remembered || (live.start === remembered.start && live.end === remembered.end)) {
    rememberWhiteboardRichPromptSelection(form);
    return false;
  }
  // A valid live selection belongs to Chromium/IME and is normally newer than
  // our cached selection. Overwriting it here is what pulled the first
  // committed character back to offset 0 and made subsequent input appear in
  // reverse order. The sole exception is a caret that we deliberately placed
  // beside an atomic @ mention: Chromium can remap that boundary to the start
  // of the editor immediately before compositionstart, so preserve only that
  // explicit atomic boundary.
  const rememberedIsAtomicBoundary = remembered.start === remembered.end
    && whiteboardRichPromptMentionRanges(editor).some((item) => (
      item.start === remembered.start || item.end === remembered.start
    ));
  if (rememberedIsAtomicBoundary) {
    return placeWhiteboardRichPromptSelectionAtOffsets(form, remembered, { focus: true });
  }
  rememberWhiteboardRichPromptSelection(form);
  return false;
};

const placeWhiteboardRichPromptCaretAtEnd = (form, { focus = false } = {}) => {
  const editor = whiteboardGenerationRichPrompt(form);
  if (!editor) return;
  placeWhiteboardRichPromptCaretAtOffset(form, serializeWhiteboardRichPrompt(editor).length, { focus });
};

const whiteboardPromptHistorySnapshotFor = (form) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  const liveSelection = editor && document.activeElement === editor
    ? whiteboardRichPromptSelectionOffsets(editor)
    : null;
  const inputSelection = input && Number.isFinite(input.selectionStart)
    ? { start: input.selectionStart, end: Number.isFinite(input.selectionEnd) ? input.selectionEnd : input.selectionStart }
    : null;
  return normalizeWhiteboardPromptHistorySnapshot({
    value: input?.value || "",
    explicitReferences: form?.elements?.explicitReferences?.value || "",
    referenceOrder: form?.elements?.referenceOrder?.value || "",
    promptReferenceSequence: form?.elements?.promptReferenceSequence?.value || "",
    includeTargetReference: form?.elements?.includeTargetReference?.value || "",
    multiframeTransitions: form?.elements?.multiframeTransitions?.value || "",
    selection: liveSelection || inputSelection || form?._whiteboardRichPromptSelectionOffsets || null,
  });
};

const initializeWhiteboardPromptHistory = (form) => {
  if (!form) return;
  form._whiteboardPromptHistory = createWhiteboardPromptHistory(whiteboardPromptHistorySnapshotFor(form));
  form._whiteboardPromptHistoryRecordQueued = false;
  form._whiteboardPromptHistoryApplying = false;
};

const recordWhiteboardPromptHistory = (form) => {
  if (!form || form._whiteboardPromptHistoryApplying) return false;
  const input = whiteboardGenerationPromptInput(form);
  if (whiteboardGenerationRichPrompt(form)) syncWhiteboardRichPromptValue(form);
  const nextHistory = pushWhiteboardPromptHistory(
    form._whiteboardPromptHistory || createWhiteboardPromptHistory(),
    whiteboardPromptHistorySnapshotFor(form),
  );
  const previous = form._whiteboardPromptHistory;
  form._whiteboardPromptHistory = nextHistory;
  return !previous || previous.index !== nextHistory.index || previous.entries?.length !== nextHistory.entries?.length
    || previous.entries?.[previous.index]?.value !== nextHistory.entries?.[nextHistory.index]?.value
    || input?.value !== previous.entries?.[previous.index]?.value;
};

const queueWhiteboardPromptHistoryRecord = (form) => {
  if (!form || form._whiteboardPromptHistoryApplying || form._whiteboardPromptHistoryRecordQueued) return;
  form._whiteboardPromptHistoryRecordQueued = true;
  queueMicrotask(() => {
    form._whiteboardPromptHistoryRecordQueued = false;
    recordWhiteboardPromptHistory(form);
  });
};

const restoreWhiteboardPromptHistorySnapshot = (form, snapshot) => {
  if (!form || !snapshot) return false;
  const input = whiteboardGenerationPromptInput(form);
  if (!input) return false;
  const normalized = normalizeWhiteboardPromptHistorySnapshot(snapshot);
  form._whiteboardPromptHistoryApplying = true;
  try {
    input.value = normalized.value;
    for (const [name, value] of [
      ["explicitReferences", normalized.explicitReferences],
      ["referenceOrder", normalized.referenceOrder],
      ["promptReferenceSequence", normalized.promptReferenceSequence],
      ["includeTargetReference", normalized.includeTargetReference],
      ["multiframeTransitions", normalized.multiframeTransitions],
    ]) {
      const field = form.elements?.[name];
      if (field) field.value = value;
    }
    renderWhiteboardGenerationInlineMentions(form, { force: true });
    const references = form.querySelector(".whiteboard-generation-references");
    if (references) renderWhiteboardGenerationReferences(references, form.dataset.nodeId);
    if (normalized.selection) {
      if (whiteboardGenerationRichPrompt(form)) placeWhiteboardRichPromptSelectionAtOffsets(form, normalized.selection, { focus: true });
      else {
        input.focus({ preventScroll: true });
        input.setSelectionRange?.(normalized.selection.start, normalized.selection.end);
      }
    }
    saveWhiteboardGenerationDraft(form.closest("dialog"), { active: true, open: true });
  } finally {
    form._whiteboardPromptHistoryApplying = false;
  }
  return true;
};

const stepWhiteboardPromptHistoryForForm = (form, direction) => {
  const current = form?._whiteboardPromptHistory;
  if (!form || !current) return false;
  const result = stepWhiteboardPromptHistory(current, direction);
  if (!result.changed || !result.snapshot) return false;
  form._whiteboardPromptHistory = result.history;
  return restoreWhiteboardPromptHistorySnapshot(form, result.snapshot);
};

const whiteboardPromptHistoryEventTargetsPrompt = (form, event) => {
  const target = event?.target;
  const input = whiteboardGenerationPromptInput(form);
  if (target === input || target?.closest?.(".whiteboard-generation-prompt-editor")) return true;
  return ["explicitReferences", "referenceOrder", "promptReferenceSequence", "includeTargetReference", "multiframeTransitions"].includes(target?.name);
};

const whiteboardRichPromptMentionRanges = (editor) => [...editor.querySelectorAll("[data-rich-mention-token]")]
  .map((mention) => {
    const parent = mention.parentNode;
    const index = parent ? [...parent.childNodes].indexOf(mention) : -1;
    const start = index >= 0 ? whiteboardRichPromptOffsetForPoint(editor, parent, index) : null;
    const length = String(mention.dataset.richMentionToken || "").length;
    return Number.isFinite(start) ? { mention, start, end: start + length } : null;
  })
  .filter(Boolean);

const moveWhiteboardRichPromptCaretAcrossMention = (form, event) => {
  if (!form || !["ArrowLeft", "ArrowRight"].includes(event.key) || event.shiftKey
    || event.ctrlKey || event.metaKey || event.altKey || event.isComposing) return false;
  const editor = whiteboardGenerationRichPrompt(form);
  const selection = document.getSelection();
  if (!editor || !selection?.rangeCount || !selection.isCollapsed || !editor.contains(selection.anchorNode)) return false;
  const offsets = whiteboardRichPromptSelectionOffsets(editor, selection.getRangeAt(0));
  if (!offsets) return false;
  const ranges = whiteboardRichPromptMentionRanges(editor);
  const mentionRange = event.key === "ArrowLeft"
    ? [...ranges].reverse().find((item) => item.end === offsets.start)
    : ranges.find((item) => item.start === offsets.start);
  if (!mentionRange) return false;
  event.preventDefault();
  event.stopPropagation();
  return placeWhiteboardRichPromptCaretAtOffset(form, event.key === "ArrowLeft" ? mentionRange.start : mentionRange.end, { focus: true });
};

const whiteboardGenerationMentionAtCaret = (input, editor = null) => {
  if (!input) return null;
  const beforeCaret = editor?.isContentEditable
    ? whiteboardRichPromptBeforeCaret(editor)
    : input.value.slice(0, Number.isFinite(input.selectionStart) ? input.selectionStart : input.value.length);
  const caret = beforeCaret.length;
  const match = beforeCaret.match(/@([^@\s]*)$/u);
  return match ? { start: caret - match[0].length, end: caret, query: String(match[1] || "").toLowerCase() } : null;
};

const whiteboardGenerationCaretRect = (editor) => {
  const selection = document.getSelection();
  if (!editor || !selection?.rangeCount || !editor.contains(selection.anchorNode)) return null;
  const range = selection.getRangeAt(0).cloneRange();
  range.collapse(false);
  const clientRects = [...range.getClientRects()];
  const rect = clientRects.at(-1) || range.getBoundingClientRect();
  if (rect && (rect.width || rect.height || rect.top || rect.left)) return rect;
  const editorRect = editor.getBoundingClientRect();
  const computed = getComputedStyle(editor);
  const lineHeight = Number.parseFloat(computed.lineHeight) || 22;
  return { left: editorRect.left + 12, right: editorRect.left + 12, top: editorRect.top + 12, bottom: editorRect.top + 12 + lineHeight, width: 0, height: lineHeight };
};

const positionWhiteboardGenerationMentionMenu = (form) => {
  const editor = whiteboardGenerationRichPrompt(form);
  const menu = whiteboardGenerationMentionMenuFor(form);
  if (!editor || !menu || menu.hidden) return false;
  const replacementMention = form?._whiteboardMentionReplacement?.mention;
  const replacementRect = replacementMention?.isConnected && editor.contains(replacementMention)
    ? replacementMention.getBoundingClientRect()
    : null;
  const caretRect = replacementRect || whiteboardGenerationCaretRect(editor);
  const editorRect = editor.getBoundingClientRect();
  const anchor = caretRect || editorRect;
  const inset = 12;
  const width = Math.min(360, Math.max(260, Math.min(editorRect.width, window.innerWidth - inset * 2)));
  menu.style.width = `${width}px`;
  menu.style.maxHeight = `${Math.min(220, Math.max(96, window.innerHeight - inset * 2))}px`;
  const measured = menu.getBoundingClientRect();
  const height = Math.min(measured.height || 180, window.innerHeight - inset * 2);
  const left = Math.min(Math.max(inset, window.innerWidth - width - inset), Math.max(inset, anchor.left));
  const below = Math.min(Math.max(inset, window.innerHeight - height - inset), Math.max(inset, anchor.bottom + 6));
  const above = anchor.top - height - 6;
  const preferredTop = anchor.bottom + 6 + height <= window.innerHeight - inset || above < inset ? below : above;
  const top = Math.min(Math.max(inset, preferredTop), Math.max(inset, window.innerHeight - height - inset));
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
  return true;
};

const whiteboardGenerationMentionOptionsMarkup = (nodes, aliases, { currentNodeId = "" } = {}) => nodes.map((node, index) => {
  const label = aliases.get(node.id) || "上游卡片";
  const preview = node.kind === "image" && node.file
    ? `<span class="whiteboard-generation-mention-preview"><img src="${escapeHtml(whiteboardAttachmentUrl(node))}" alt="" loading="lazy" /></span>`
    : node.kind === "video" && node.file
      ? `<span class="whiteboard-generation-mention-preview"><video src="${escapeHtml(whiteboardAttachmentUrl(node))}" muted playsinline preload="metadata"></video><i aria-hidden="true">${icon("\uE768")}</i></span>`
      : `<span class="whiteboard-generation-mention-icon">${["skill", "capability"].includes(node.reference?.type) ? icon("\uE943") : node.kind === "audio" ? icon("\uE8D6") : icon("\uE8A5")}</span>`;
  const shortcut = index < 9 ? `<kbd aria-label="按数字 ${index + 1} 选择">${index + 1}</kbd>` : "";
  const current = String(node.id) === String(currentNodeId);
  return `<button type="button" role="option" data-insert-whiteboard-generation-reference="${escapeHtml(node.id)}" aria-selected="${current}"${current ? " aria-current=\"true\"" : ""}${index < 9 ? ` data-mention-shortcut="${index + 1}"` : ""}>${preview}<strong>${escapeHtml(label)}</strong><small title="${escapeHtml(label)}">${escapeHtml(whiteboardGenerationReferenceTypeLabel(node))}${current ? " · 当前参考" : ""}</small>${shortcut}</button>`;
}).join("");

const renderWhiteboardGenerationMentionMenu = (form) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  const menu = portalWhiteboardGenerationMentionMenu(form);
  const mention = whiteboardGenerationMentionAtCaret(input, editor);
  if (!input || !menu || !mention) {
    closeWhiteboardGenerationMentionMenu(form);
    return;
  }
  clearWhiteboardGenerationMentionReplacement(form);
  const { upstream: sourceUpstream } = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, form.dataset.nodeId);
  const rawUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  const upstream = orderWhiteboardGenerationNodes(rawUpstream, form);
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const matches = upstream.filter((node) => {
    const label = whiteboardGenerationReferenceSearchText(node, aliases.get(node.id));
    return !mention.query || label.includes(mention.query);
  });
  if (!matches.length) {
    menu.replaceChildren();
    closeWhiteboardGenerationMentionMenu(form);
    return;
  }
  menu.innerHTML = whiteboardGenerationMentionOptionsMarkup(matches, aliases);
  menu.hidden = false;
  requestAnimationFrame(() => positionWhiteboardGenerationMentionMenu(form));
};

const openWhiteboardGenerationMentionReplacementMenu = (form, mention) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  const menu = portalWhiteboardGenerationMentionMenu(form);
  if (!input || !editor || !menu || !mention || !editor.contains(mention)) return false;
  syncWhiteboardRichPromptValue(form);
  const ranges = whiteboardRichPromptMentionRanges(editor);
  const occurrenceIndex = ranges.findIndex((item) => item.mention === mention);
  const occurrence = ranges[occurrenceIndex];
  if (!occurrence || occurrenceIndex < 0) return false;
  const referenceIds = ranges.map((item) => String(item.mention.dataset.richMentionNodeId || "").trim()).filter(Boolean);
  const prompt = String(input.value || "");
  const anchorLength = 64;
  form._whiteboardMentionReplacement = {
    mention,
    prompt,
    targetNodeId: String(form.dataset.nodeId || ""),
    documentId: String(state.activeDocument || ""),
    workspaceId: workspaceIdentity(),
    occurrenceIndex,
    occurrence: {
      id: String(mention.dataset.richMentionNodeId || "").trim(),
      start: occurrence.start,
      end: occurrence.end,
      token: String(mention.dataset.richMentionToken || ""),
    },
    beforeAnchor: prompt.slice(Math.max(0, occurrence.start - anchorLength), occurrence.start),
    afterAnchor: prompt.slice(occurrence.end, occurrence.end + anchorLength),
    referenceIds,
  };
  const { upstream: sourceUpstream } = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, form.dataset.nodeId);
  const rawUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  const upstream = orderWhiteboardGenerationNodes(rawUpstream, form);
  if (!upstream.length) {
    closeWhiteboardGenerationMentionMenu(form);
    return false;
  }
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  menu.dataset.referenceReplacement = "true";
  menu.setAttribute("aria-label", "替换当前参考");
  menu.innerHTML = `<p class="whiteboard-generation-reference-replacement-note">选择新的参考，其他引用顺序保持不变</p>${whiteboardGenerationMentionOptionsMarkup(upstream, aliases, {
    currentNodeId: form._whiteboardMentionReplacement.occurrence.id,
  })}`;
  menu.hidden = false;
  requestAnimationFrame(() => positionWhiteboardGenerationMentionMenu(form));
  return true;
};

const renderWhiteboardGenerationInlineMentions = (form, { force = false } = {}) => {
  const tray = whiteboardGenerationRichPrompt(form);
  const input = whiteboardGenerationPromptInput(form);
  if (!tray || !input) return;
  const userOwnsEditor = document.activeElement === tray
    || tray.dataset.userEditing === "true"
    || tray.dataset.editing === "true"
    || tray.dataset.composing === "true";
  // While the rich editor owns focus its DOM is the authoritative value. Draft
  // restoration, capability refreshes and reference refreshes can update the
  // hidden submission field asynchronously. Rebuilding the focused subtree
  // from that stale value discards freshly typed text and resets Chromium's
  // selection. Preserve the live editor and immediately repair the hidden
  // field instead. Programmatic initialization still renders normally before
  // focus, and callers may explicitly force a rebuild when no user edit exists.
  if (!force && userOwnsEditor) {
    syncWhiteboardRichPromptValue(form);
    return;
  }
  const { upstream: sourceUpstream } = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, form.dataset.nodeId);
  const rawUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  migrateWhiteboardGenerationPromptReferenceSequence(form, rawUpstream);
  migrateWhiteboardGenerationReferenceOrder(form, rawUpstream);
  const upstream = orderWhiteboardGenerationNodes(rawUpstream, form);
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const legacyAliases = whiteboardGenerationLegacyReferenceAliases(upstream);
  const nodeByLabel = new Map(upstream.map((node) => [legacyAliases.get(node.id), node]));
  upstream.forEach((node) => nodeByLabel.set(aliases.get(node.id), node));
  const nodeById = new Map(upstream.map((node) => [node.id, node]));
  const promptReferenceSequence = whiteboardGenerationPromptReferenceSequence(form);
  const tokenPattern = /@「([^」]+)」/gu;
  const desiredTokens = [...input.value.matchAll(tokenPattern)].map((match) => match[0]);
  const renderedMentions = [...tray.querySelectorAll("[data-rich-mention-token]")];
  const renderedTokens = renderedMentions.map((item) => item.dataset.richMentionToken || "");
  const renderedReferenceIds = renderedMentions
    .map((item) => String(item.dataset.richMentionNodeId || "").trim())
    .filter(Boolean);
  const expectedReferenceIds = desiredTokens.map((token, index) => {
    const persistedId = String(promptReferenceSequence[index] || "").trim();
    if (persistedId && nodeById.has(persistedId)) return persistedId;
    return nodeByLabel.get(token.slice(2, -1))?.id || "";
  }).filter(Boolean);
  const renderedEditorAlreadyMatches = serializeWhiteboardRichPromptRaw(tray) === input.value
    && desiredTokens.length === renderedTokens.length
    && desiredTokens.every((token, index) => token === renderedTokens[index])
    && whiteboardPromptReferenceIdentityMatches(expectedReferenceIds, renderedReferenceIds);
  if (renderedEditorAlreadyMatches) return;
  let cursor = 0;
  let markup = "";
  let mentionIndex = 0;
  for (const match of input.value.matchAll(tokenPattern)) {
    markup += escapeHtml(input.value.slice(cursor, match.index)).replace(/\n/g, "<br>");
    // Prefer the persisted node-id sequence. Labels are display text and may
    // belong to an older tray order; using them as identity is what caused
    // the lower chips to show 图片6 while the top tray showed 图片1.
    const node = nodeById.get(promptReferenceSequence[mentionIndex]) || nodeByLabel.get(match[1]);
    mentionIndex += 1;
    if (!node) {
      markup += escapeHtml(match[0]);
    } else {
      const label = aliases.get(node.id) || whiteboardNodeKindLabel(node);
      const preview = node.kind === "image" && node.file
        ? `<img src="${escapeHtml(whiteboardAttachmentUrl(node))}" alt="" loading="lazy" />`
        : node.kind === "video" && node.file
          ? `<video src="${escapeHtml(whiteboardAttachmentUrl(node))}" muted playsinline preload="metadata"></video><i aria-hidden="true">${icon("\uE768")}</i>`
          : node.kind === "audio" && node.file
            ? `<span class="whiteboard-generation-inline-icon audio" aria-hidden="true">${icon("\uE8D6")}</span>`
            : ["skill", "capability"].includes(node.reference?.type)
              ? `<span class="whiteboard-generation-inline-icon skill" aria-hidden="true">${icon("\uE943")}</span>`
              : `<span class="whiteboard-generation-inline-icon text" aria-hidden="true">${icon("\uE8A5")}</span>`;
      markup += `${WHITEBOARD_RICH_PROMPT_CARET_GUARD}<span class="whiteboard-generation-inline-mention" data-rich-mention-token="${escapeHtml(match[0])}" data-rich-mention-node-id="${escapeHtml(node.id)}" contenteditable="false" title="${escapeHtml(`${label}；右键替换参考`)}">${preview}<strong>${escapeHtml(label)}</strong></span>${WHITEBOARD_RICH_PROMPT_CARET_GUARD}`;
    }
    cursor = Number(match.index) + match[0].length;
  }
  markup += escapeHtml(input.value.slice(cursor)).replace(/\n/g, "<br>");
  tray.innerHTML = markup;
  updateWhiteboardGenerationPromptCounts(form);
};

const insertWhiteboardGenerationMention = (form, nodeId) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  const menu = whiteboardGenerationMentionMenuFor(form);
  const sourceUpstream = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, form?.dataset.nodeId).upstream;
  const allowedUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  const node = allowedUpstream.find((item) => item.id === nodeId);
  if (!input || !node) return;
  const upstream = orderWhiteboardGenerationNodes(allowedUpstream, form);
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const label = String(aliases.get(node.id) || "上游卡片").replace(/[「」\r\n]/g, " ").trim();
  const token = `@「${label}」 `;
  const selection = document.getSelection();
  const selectedRange = selection?.rangeCount && editor?.contains(selection.anchorNode)
    ? selection.getRangeAt(0).cloneRange()
    : null;
  const rememberedRange = form._whiteboardRichPromptRange?.cloneRange?.();
  const activeRange = selectedRange
    || (rememberedRange && editor?.contains(rememberedRange.startContainer) ? rememberedRange : null);
  if (activeRange) syncWhiteboardRichPromptValue(form);
  const existingMentionOccurrences = editor
    ? whiteboardRichPromptMentionRanges(editor).map((item) => ({
        id: String(item.mention?.dataset?.richMentionNodeId || "").trim(),
        start: item.start,
        end: item.end,
      }))
    : [];
  const richOffsets = activeRange ? whiteboardRichPromptSelectionOffsets(editor, activeRange) : null;
  let start = richOffsets?.start ?? (Number.isFinite(input.selectionStart) ? input.selectionStart : input.value.length);
  let end = richOffsets?.end ?? (Number.isFinite(input.selectionEnd) ? input.selectionEnd : start);
  const localMention = start === end ? input.value.slice(0, start).match(/@([^@\s]*)$/u) : null;
  const localMentionStart = localMention ? Math.max(0, start - localMention[0].length) : start;
  const followsAtomicMention = Boolean(localMention && editor && whiteboardRichPromptMentionRanges(editor)
    .some((item) => item.start === localMentionStart && item.end === start));
  if (localMention && !followsAtomicMention) start = localMentionStart;
  // The occurrence sequence is semantic identity, not display order. Update it
  // before rebuilding the rich prompt; otherwise inserting in front of an
  // existing mention lets the new token inherit that older occurrence's ID,
  // so the selected reference and the inserted chip visibly disagree.
  writeWhiteboardGenerationPromptReferenceSequence(form, whiteboardPromptReferenceSequenceAfterInsertion(
    existingMentionOccurrences,
    start,
    end,
    node.id,
  ));
  input.setRangeText(token, start, end, "end");
  const caret = Math.min(input.value.length, start + token.length);
  input.setSelectionRange?.(caret, caret);
  // Rebuild once from the updated serialized value, then restore the logical
  // caret below. This keeps insertion at the remembered rich-editor position
  // even when clicking a top reference button temporarily moves DOM focus.
  renderWhiteboardGenerationInlineMentions(form, { force: true });
  input.dispatchEvent(new Event("input", { bubbles: true }));
  const ids = whiteboardGenerationExplicitReferenceIds(form);
  ids.add(node.id);
  writeWhiteboardGenerationExplicitReferenceIds(form, ids);
  syncWhiteboardGenerationPromptReferenceSequenceFromEditor(form);
  closeWhiteboardGenerationMentionMenu(form);
  const referenceContainer = form.querySelector(".whiteboard-generation-references");
  renderWhiteboardGenerationReferences(referenceContainer, form.dataset.nodeId);
  const restoreCaret = () => {
    if (editor) {
      placeWhiteboardRichPromptCaretAtOffset(form, caret, { focus: true });
    } else {
      input.focus({ preventScroll: true });
      input.setSelectionRange(caret, caret);
    }
  };
  // Restore the logical caret before the next input event can arrive. Keep a
  // second frame-level correction because rebuilding the reference tray may
  // still move focus in Chromium after this click handler returns.
  restoreCaret();
  requestAnimationFrame(() => {
    restoreCaret();
  });
};

const replaceWhiteboardGenerationMention = (form, nodeId) => {
  const replacement = form?._whiteboardMentionReplacement;
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  if (!replacement || !input || !editor) return false;
  syncWhiteboardRichPromptValue(form);
  const ranges = whiteboardRichPromptMentionRanges(editor);
  const currentRange = ranges[replacement.occurrenceIndex];
  const currentPrompt = String(input.value || "");
  const anchorLength = 64;
  const current = {
    prompt: currentPrompt,
    targetNodeId: String(form.dataset.nodeId || ""),
    documentId: String(state.activeDocument || ""),
    workspaceId: workspaceIdentity(),
    occurrenceIndex: replacement.occurrenceIndex,
    occurrence: currentRange ? {
      id: String(currentRange.mention.dataset.richMentionNodeId || "").trim(),
      start: currentRange.start,
      end: currentRange.end,
      token: String(currentRange.mention.dataset.richMentionToken || ""),
    } : null,
    beforeAnchor: currentRange ? currentPrompt.slice(Math.max(0, currentRange.start - anchorLength), currentRange.start) : "",
    afterAnchor: currentRange ? currentPrompt.slice(currentRange.end, currentRange.end + anchorLength) : "",
    referenceIds: ranges.map((item) => String(item.mention.dataset.richMentionNodeId || "").trim()).filter(Boolean),
  };
  if (!whiteboardPromptReferenceReplacementIsSafe(replacement, current)) {
    closeWhiteboardGenerationMentionMenu(form);
    showToast("参考位置已经变化，原内容未修改；请重新右键需要替换的参考");
    return false;
  }
  const { upstream: sourceUpstream } = whiteboardGenerationSources(activeWhiteboardDocument()?.canvas, form.dataset.nodeId);
  const rawUpstream = whiteboardGenerationNodesForForm(form, sourceUpstream);
  const upstream = orderWhiteboardGenerationNodes(rawUpstream, form);
  const node = upstream.find((item) => item.id === String(nodeId));
  if (!node) {
    closeWhiteboardGenerationMentionMenu(form);
    showToast("所选参考已不在当前上游中，原内容未修改");
    return false;
  }
  if (node.id === replacement.occurrence.id) {
    closeWhiteboardGenerationMentionMenu(form);
    return true;
  }
  recordWhiteboardPromptHistory(form);
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const label = String(aliases.get(node.id) || "上游卡片").replace(/[「」\r\n]/g, " ").trim();
  const token = `@「${label}」`;
  const occurrences = ranges.map((item) => ({
    id: String(item.mention.dataset.richMentionNodeId || "").trim(),
    start: item.start,
    end: item.end,
  }));
  const nextReferenceIds = whiteboardPromptReferenceSequenceAfterReplacement(
    occurrences,
    currentRange.start,
    currentRange.end,
    [{ id: node.id, start: 0, end: token.length }],
  );
  writeWhiteboardGenerationPromptReferenceSequence(form, nextReferenceIds);
  input.setRangeText(token, currentRange.start, currentRange.end, "end");
  const explicitIds = whiteboardGenerationExplicitReferenceIds(form);
  if (!nextReferenceIds.includes(replacement.occurrence.id)) explicitIds.delete(replacement.occurrence.id);
  explicitIds.add(node.id);
  writeWhiteboardGenerationExplicitReferenceIds(form, explicitIds);
  renderWhiteboardGenerationInlineMentions(form, { force: true });
  syncWhiteboardGenerationPromptReferenceSequenceFromEditor(form);
  input.dispatchEvent(new Event("input", { bubbles: true }));
  renderWhiteboardGenerationReferences(form.querySelector(".whiteboard-generation-references"), form.dataset.nodeId);
  const caret = currentRange.start + token.length;
  closeWhiteboardGenerationMentionMenu(form);
  requestAnimationFrame(() => placeWhiteboardRichPromptCaretAtOffset(form, caret, { focus: true }));
  showToast(`已将当前参考替换为${label}，其他参考顺序保持不变`);
  return true;
};

const placeWhiteboardGenerationReferenceDropCaret = (editor, clientX, clientY) => {
  if (!editor) return false;
  const droppedMention = document.elementFromPoint?.(clientX, clientY)?.closest?.("[data-rich-mention-token]");
  if (droppedMention && editor.contains(droppedMention)) {
    const mentionRange = whiteboardRichPromptMentionRanges(editor).find((item) => item.mention === droppedMention);
    if (mentionRange) {
      const rect = droppedMention.getBoundingClientRect();
      const offset = whiteboardPromptAtomicDropOffset({
        start: mentionRange.start,
        end: mentionRange.end,
        clientX,
        left: rect.left,
        width: rect.width,
      });
      return placeWhiteboardRichPromptCaretAtOffset(editor.closest("form"), offset, { focus: true });
    }
  }
  let range = null;
  if (typeof document.caretRangeFromPoint === "function") {
    range = document.caretRangeFromPoint(clientX, clientY);
  } else if (typeof document.caretPositionFromPoint === "function") {
    const position = document.caretPositionFromPoint(clientX, clientY);
    if (position) {
      range = document.createRange();
      range.setStart(position.offsetNode, position.offset);
      range.collapse(true);
    }
  }
  if (!range || !editor.contains(range.startContainer)) {
    placeWhiteboardRichPromptCaretAtEnd(editor.closest("form"), { focus: true });
    return false;
  }
  const selection = document.getSelection();
  selection?.removeAllRanges();
  selection?.addRange(range);
  editor.focus({ preventScroll: true });
  return true;
};

const removeWhiteboardGenerationMention = (form, sourceNodeId, sourceLabels = []) => {
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  if (!input) return false;
  if (editor) syncWhiteboardRichPromptValue(form);
  let removed = false;
  editor?.querySelectorAll("[data-rich-mention-node-id]").forEach((mention) => {
    if (mention.dataset.richMentionNodeId !== String(sourceNodeId)) return;
    mention.remove();
    removed = true;
  });
  const explicitIds = whiteboardGenerationExplicitReferenceIds(form);
  const wasExplicit = explicitIds.has(String(sourceNodeId));
  let removedSerializedToken = false;
  const labelsToRemove = [...new Set((Array.isArray(sourceLabels) ? sourceLabels : [sourceLabels]).map(String).filter(Boolean))];
  if (!removed && wasExplicit && labelsToRemove.length) {
    const escapedLabels = labelsToRemove.map((label) => label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    const tokenPattern = new RegExp(`@「(${escapedLabels.join("|")})」[ \\t]*`, "gu");
    const nextValue = String(input.value || "").replace(tokenPattern, "");
    removedSerializedToken = nextValue !== input.value;
    input.value = nextValue;
  }
  explicitIds.delete(String(sourceNodeId));
  const orderedIds = whiteboardGenerationReferenceOrder(form).filter((id) => id !== String(sourceNodeId));
  writeWhiteboardGenerationReferenceOrder(form, orderedIds);
  if (wasExplicit || removed) writeWhiteboardGenerationExplicitReferenceIds(form, explicitIds);
  if (removed) syncWhiteboardRichPromptValue(form);
  if (removed || removedSerializedToken || wasExplicit) {
    input.dispatchEvent(new Event("input", { bubbles: true }));
    if (editor) renderWhiteboardGenerationInlineMentions(form, { force: true });
  }
  return removed || removedSerializedToken || wasExplicit;
};

const removeWhiteboardGenerationReferenceFromDrafts = (targetNodeId, sourceNodeId, sourceLabels = []) => {
  const labels = [...new Set((Array.isArray(sourceLabels) ? sourceLabels : [sourceLabels]).map(String).filter(Boolean))];
  if (!labels.length) return false;
  const cache = readWhiteboardGenerationDraftCache();
  let changed = false;
  for (const [key, entry] of whiteboardGenerationDraftEntriesForNode(cache, targetNodeId)) {
    const explicitIds = new Set(String(entry.values?.explicitReferences || "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean));
    if (!explicitIds.has(String(sourceNodeId))) continue;
    const promptKey = entry.channel === "text" ? "instruction" : "prompt";
    const prompt = String(entry.values?.[promptKey] || "");
    const escapedLabels = labels.map((label) => label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    const tokenPattern = new RegExp(`@「(?:${escapedLabels.join("|")})」[ \\t]*`, "gu");
    const nextPrompt = prompt.replace(tokenPattern, "");
    explicitIds.delete(String(sourceNodeId));
    cache.entries[key] = {
      ...entry,
      values: {
        ...entry.values,
        [promptKey]: nextPrompt,
        explicitReferences: [...explicitIds].join(","),
      },
    };
    changed = true;
  }
  if (changed) {
    writeWhiteboardGenerationDraftCache(cache);
    markWhiteboardGenerationDraftDurable();
  }
  return changed;
};

const removeWhiteboardGenerationReferencesForEdges = (canvas, edgeIds = [], afterCanvas = canvas) => {
  const selectedEdgeIds = new Set((Array.isArray(edgeIds) ? edgeIds : [edgeIds]).map(String).filter(Boolean));
  if (!selectedEdgeIds.size) return false;
  const normalized = normalizeCanvas(canvas);
  const normalizedAfter = normalizeCanvas(afterCanvas);
  const affected = new Map();
  normalized.edges
    .filter((edge) => selectedEdgeIds.has(String(edge.id)) && edge.fromNode && edge.toNode)
    .forEach((edge) => {
      const sources = affected.get(edge.toNode) || new Set();
      sources.add(edge.fromNode);
      affected.set(edge.toNode, sources);
    });
  let changed = false;
  for (const [targetNodeId, sourceNodeIds] of affected) {
    const upstream = whiteboardGenerationSources(normalized, targetNodeId).upstream;
    const aliases = whiteboardGenerationReferenceAliases(upstream);
    const legacyAliases = whiteboardGenerationLegacyReferenceAliases(upstream);
    for (const sourceNodeId of sourceNodeIds) {
      const sourceLabels = [aliases.get(sourceNodeId), legacyAliases.get(sourceNodeId)].filter(Boolean);
      whiteboardGenerationFormsForNode(targetNodeId).forEach((generationForm) => {
        changed = removeWhiteboardGenerationMention(generationForm, sourceNodeId, sourceLabels) || changed;
      });
      changed = removeWhiteboardGenerationReferenceFromDrafts(targetNodeId, sourceNodeId, sourceLabels) || changed;
    }
    const remaining = whiteboardGenerationSources(normalizedAfter, targetNodeId).upstream;
    const remainingAliases = whiteboardGenerationReferenceAliases(remaining);
    whiteboardGenerationFormsForNode(targetNodeId).forEach((generationForm) => {
      updateWhiteboardGenerationMentionAliases(generationForm, remainingAliases, aliases);
    });
    changed = rewriteWhiteboardGenerationDraftReferenceAliases(targetNodeId, aliases, remainingAliases) || changed;
  }
  return changed;
};

const removeWhiteboardGenerationReference = (targetNodeId, sourceNodeId) => {
  const documentState = activeWhiteboardDocument();
  if (!documentState || !targetNodeId || !sourceNodeId) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const edgeIds = normalizeCanvas(documentState.canvas).edges
    .filter((edge) => edge.fromNode === sourceNodeId && edge.toNode === targetNodeId)
    .map((edge) => edge.id);
  if (!edgeIds.length) return false;
  const afterCanvas = edgeIds.reduce((canvas, edgeId) => removeCanvasEdge(canvas, edgeId), documentState.canvas);
  removeWhiteboardGenerationReferencesForEdges(documentState.canvas, edgeIds, afterCanvas);
  documentState.canvas = afterCanvas;
  if (edgeIds.includes(ui.whiteboardSelectedEdgeId)) selectWhiteboardEdge(null);
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: "移除生成参考" });
  persist();
  renderWhiteboard(documentState);
  renderWhiteboardGenerationReferences(elements.whiteboardTextReferences, elements.whiteboardGenerateForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardImageReferences, elements.whiteboardImageForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardVideoReferences, elements.whiteboardVideoForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardAudioReferences, elements.whiteboardAudioForm.dataset.nodeId);
  requestAnimationFrame(() => whiteboardGenerationDialogs().forEach((dialog) => positionWhiteboardGenerationDialog(dialog)));
  showToast("已移除上游参考并断开连线，按 Ctrl+Z 可恢复");
  return true;
};

const clearWhiteboardGenerationReferenceDrafts = (targetNodeId, sourceLabels = []) => {
  const labels = [...new Set(sourceLabels.map(String).map((value) => value.trim()).filter(Boolean))];
  const tokenPattern = labels.length
    ? new RegExp(`@「(?:${labels.map((label) => label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})」[ \\t]*`, "gu")
    : null;
  const cache = readWhiteboardGenerationDraftCache();
  let changed = false;
  for (const [key, entry] of whiteboardGenerationDraftEntriesForNode(cache, targetNodeId)) {
    const promptKey = entry.channel === "text" ? "instruction" : "prompt";
    const previousValues = entry.values || {};
    const previousPrompt = String(previousValues[promptKey] || "");
    const nextPrompt = tokenPattern ? previousPrompt.replace(tokenPattern, "") : previousPrompt;
    const nextValues = {
      ...previousValues,
      [promptKey]: nextPrompt,
      explicitReferences: "",
      referenceOrder: "",
      promptReferenceSequence: "",
      ...(entry.channel === "video" ? { multiframeTransitions: "" } : {}),
    };
    const entryChanged = nextPrompt !== previousPrompt
      || String(previousValues.explicitReferences || "") !== ""
      || String(previousValues.referenceOrder || "") !== ""
      || String(previousValues.promptReferenceSequence || "") !== ""
      || (entry.channel === "video" && String(previousValues.multiframeTransitions || "") !== "");
    if (!entryChanged) continue;
    cache.entries[key] = { ...entry, values: nextValues, updatedAt: Date.now() };
    changed = true;
  }
  if (changed) {
    writeWhiteboardGenerationDraftCache(cache);
    markWhiteboardGenerationDraftDurable();
  }
  return changed;
};

const clearWhiteboardGenerationMentions = (form, sourceLabels = []) => {
  if (!form) return false;
  const input = whiteboardGenerationPromptInput(form);
  const editor = whiteboardGenerationRichPrompt(form);
  if (!input) return false;
  recordWhiteboardPromptHistory(form);
  if (editor) syncWhiteboardRichPromptValue(form);
  const mentions = [...(editor?.querySelectorAll("[data-rich-mention-node-id]") || [])];
  mentions.forEach((mention) => mention.remove());
  if (editor) syncWhiteboardRichPromptValue(form);
  else {
    const labels = [...new Set(sourceLabels.map(String).map((value) => value.trim()).filter(Boolean))];
    if (labels.length) {
      const tokenPattern = new RegExp(`@「(?:${labels.map((label) => label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})」[ \\t]*`, "gu");
      input.value = String(input.value || "").replace(tokenPattern, "");
    }
  }
  writeWhiteboardGenerationExplicitReferenceIds(form, new Set());
  writeWhiteboardGenerationReferenceOrder(form, []);
  writeWhiteboardGenerationPromptReferenceSequence(form, []);
  if (form.elements?.multiframeTransitions) form.elements.multiframeTransitions.value = "";
  renderWhiteboardGenerationInlineMentions(form, { force: true });
  input.dispatchEvent(new Event("input", { bubbles: true }));
  return mentions.length > 0 || sourceLabels.length > 0;
};

const clearWhiteboardGenerationReferences = (targetNodeId) => {
  const documentState = activeWhiteboardDocument();
  if (!documentState || !targetNodeId) return false;
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  const upstream = whiteboardGenerationSources(documentState.canvas, targetNodeId).upstream;
  const directEdgeIds = normalizeCanvas(documentState.canvas).edges
    .filter((edge) => edge.toNode === targetNodeId)
    .map((edge) => edge.id);
  const forms = whiteboardGenerationFormsForNode(targetNodeId);
  const hasDraftReferences = forms.some((form) => (
    whiteboardGenerationExplicitReferenceIds(form).size > 0
    || whiteboardGenerationStoredReferenceOrder(form).length > 0
    || whiteboardGenerationPromptReferenceSequence(form).length > 0
    || Boolean(whiteboardGenerationRichPrompt(form)?.querySelector("[data-rich-mention-node-id]"))
    || Boolean(String(whiteboardGenerationPromptInput(form)?.value || "").match(/@「[^」]+」/u))
  ));
  // Recovery can restore the prompt draft one frame before incoming edges, or
  // restore edges before the form fields. Treat the operation as idempotent and
  // clear whichever durable/in-memory references are currently available.
  if (!upstream.length && !directEdgeIds.length && !hasDraftReferences) return false;
  const aliases = whiteboardGenerationReferenceAliases(upstream);
  const legacyAliases = whiteboardGenerationLegacyReferenceAliases(upstream);
  const sourceLabels = upstream.flatMap((node) => [
    aliases.get(node.id),
    legacyAliases.get(node.id),
    whiteboardGenerationReferenceSemanticLabel(node),
  ]).filter(Boolean);
  // Publish the edge-free in-memory canvas before any prompt input/change
  // events can render the tray. Otherwise that synchronous render sees the
  // old incoming edges and repopulates referenceOrder immediately after it
  // was cleared.
  documentState.canvas = directEdgeIds.reduce((canvas, edgeId) => removeCanvasEdge(canvas, edgeId), documentState.canvas);
  forms.forEach((form) => clearWhiteboardGenerationMentions(form, sourceLabels));
  clearWhiteboardGenerationReferenceDrafts(targetNodeId, sourceLabels);
  closeWhiteboardVideoTransitionEditor();
  if (directEdgeIds.includes(ui.whiteboardSelectedEdgeId)) selectWhiteboardEdge(null);
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: "清空生成参考" });
  persist();
  renderWhiteboard(documentState);
  renderWhiteboardGenerationReferences(elements.whiteboardTextReferences, elements.whiteboardGenerateForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardImageReferences, elements.whiteboardImageForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardVideoReferences, elements.whiteboardVideoForm.dataset.nodeId);
  renderWhiteboardGenerationReferences(elements.whiteboardAudioReferences, elements.whiteboardAudioForm.dataset.nodeId);
  requestAnimationFrame(() => whiteboardGenerationDialogs().forEach((dialog) => positionWhiteboardGenerationDialog(dialog)));
  showToast(`已清空 ${upstream.length} 项参考及输入框中的对应引用，按 Ctrl+Z 可恢复白板连线`);
  return true;
};

const openWhiteboardGenerateDialog = (nodeId, { centered = false } = {}) => {
  if (!hasAvailableTextGenerationExecutor()) {
    showToast("请先连接可用的 Chat 模型，或完成 Agent 引擎安装与连接");
    return;
  }
  const node = whiteboardNodeById(nodeId);
  if (!node) return;
  // Opening a generation type is an explicit new intent. It reverses a prior
  // Close choice but keeps the saved prompt, so generated cards remain
  // click-to-open after a successful run.
  primeWhiteboardGenerationDialog(elements.whiteboardGenerateDialog, nodeId, { centered });
  scheduleUiInitializationAfterPaint(() => {
    if (!elements.whiteboardGenerateDialog.open
      || elements.whiteboardGenerateDialog.dataset.anchorNodeId !== nodeId
      || elements.whiteboardGenerateDialog.dataset.anchorDocumentId !== state.activeDocument) return;
    reactivateWhiteboardGenerationIntent(nodeId);
    prepareWhiteboardGenerationDialogSwitch("text", nodeId);
    elements.whiteboardGenerateForm.dataset.nodeId = nodeId;
    elements.whiteboardGenerateForm.elements.explicitReferences.value = "";
    elements.whiteboardGenerateForm.elements.referenceOrder.value = "";
    elements.whiteboardGenerateForm.elements.promptReferenceSequence.value = "";
    elements.whiteboardGenerateForm.elements.includeTargetReference.value = "";
    elements.whiteboardGenerateForm.elements.instruction.value = whiteboardGenerationPromptFor(node, "text");
    elements.whiteboardGenerateForm.elements.autoSkills.checked = false;
    elements.whiteboardGenerateForm.elements.guided.checked = false;
    delete elements.whiteboardGenerateForm.dataset.guidedByAutoSkills;
    setWhiteboardAutoSkillStatus();
    elements.whiteboardTextRuntimePanel.hidden = true;
    elements.whiteboardTextRuntimeButton.setAttribute("aria-expanded", "false");
    const draftValues = whiteboardGenerationDraftValues("text", nodeId);
    const rememberedValues = whiteboardRememberedGenerationProfile("text");
    const cardValues = whiteboardGenerationProfileForNode(node, "text");
    Object.assign(rememberedValues, cardValues);
    const firstTextProfileId = textGenerationProfilesForMode("agent")[0]?.id || "";
    renderWhiteboardGenerateControls({
      ...rememberedValues,
      ...(draftValues ?? {}),
      connectionId: String(draftValues?.connectionId || rememberedValues.connectionId || firstTextProfileId),
      model: String(draftValues?.model || rememberedValues.model || ""),
    });
    renderWebSearchButton();
    applyWhiteboardGenerationFormValues(elements.whiteboardGenerateForm, draftValues);
    // The visible rich editor is the source of truth for submission. Rebuild it
    // after restoring a per-card draft so the hidden form field and editor start
    // from the same value before the user can submit.
    renderWhiteboardGenerationInlineMentions(elements.whiteboardGenerateForm, { force: true });
    if (elements.whiteboardGenerateForm.elements.guided.checked) setWhiteboardAutoSkillStatus("已恢复创作引导设置，提交前会重新核对引导 Skill");
    else if (elements.whiteboardGenerateForm.elements.autoSkills.checked) setWhiteboardAutoSkillStatus("按任务自动引用");
    else setWhiteboardAutoSkillStatus();
    renderWhiteboardGenerationReferences(elements.whiteboardTextReferences, nodeId);
    showWhiteboardGenerationDialog(elements.whiteboardGenerateDialog, nodeId, elements.whiteboardGenerateForm.elements.instruction);
  });
};

const generationConnectionOptionLabels = (channel, profiles = []) => {
  const baseLabels = profiles.map((profile) => generationProfileLabel(profile, channel));
  const counts = new Map();
  baseLabels.forEach((label) => counts.set(label, (counts.get(label) || 0) + 1));
  return profiles.map((profile, index) => {
    const base = baseLabels[index];
    if ((counts.get(base) || 0) <= 1) return base;
    const adapter = profile.adapter === "cli" ? "CLI" : profile.adapter === "api" ? "API" : String(profile.adapter || "连接");
    const suffix = String(profile.id || index + 1).replace(/^.*?([a-z0-9]{6})$/i, "$1");
    return `${base} · ${adapter} · ${suffix}`;
  });
};

const isDreaminaCliProfile = (profile = null) => String(profile?.provider || "").trim() === "即梦"
  && String(profile?.adapter || "").trim().toLowerCase() === "cli"
  && Boolean(String(profile?.dreaminaCliProfile || "").trim());
const dreaminaPickerProfiles = (_channel, profiles = []) => profiles;
const whiteboardPickerProfile = (channel, profileId = "", model = "") => {
  const requestedId = String(profileId || "").trim();
  return generationSettingsForChannel(state.settings, channel, requestedId, model ? { model } : {});
};
const whiteboardPickerIdForProfile = (_channel, profileId = "", _profiles = []) => profileId;

const mediaConnectionOptionsMarkup = (channel, profiles) => {
  const pickerProfiles = dreaminaPickerProfiles(channel, profiles);
  const labels = generationConnectionOptionLabels(channel, pickerProfiles);
  return pickerProfiles.map((profile, index) => `<option value="${escapeHtml(profile.id)}">${escapeHtml(labels[index])}</option>`).join("");
};

const imageModelsForConnection = (profile) => {
  if (!profile) return [];
  const models = getProviderImageModelOptions(profile.provider, profile.adapter).filter((model) => model.available !== false);
  if (getProviderPreset(profile.provider).custom === true && profile.model && !models.some((model) => model.slug === profile.model)) {
    return [{ slug: profile.model, label: profile.model }, ...models];
  }
  return models;
};

const whiteboardAspectRatioShortLabel = (value) => value === "auto" ? "Auto" : String(value || "");

const whiteboardAspectRatioGlyphMarkup = (value) => {
  const source = String(value || "auto");
  const parsed = source.match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
  if (!parsed) {
    return '<span class="whiteboard-aspect-ratio-glyph adaptive" style="--aspect-glyph-width:24px;--aspect-glyph-height:16px" aria-hidden="true"></span>';
  }
  const widthRatio = Math.max(0.1, Number(parsed[1]) || 1);
  const heightRatio = Math.max(0.1, Number(parsed[2]) || 1);
  const scale = Math.min(28 / widthRatio, 20 / heightRatio);
  const width = Math.max(7, Math.round(widthRatio * scale * 10) / 10);
  const height = Math.max(7, Math.round(heightRatio * scale * 10) / 10);
  return `<span class="whiteboard-aspect-ratio-glyph" style="--aspect-glyph-width:${width}px;--aspect-glyph-height:${height}px" aria-hidden="true"></span>`;
};

const selectedOptionLabel = (field, fallback = "") => String(
  field?.selectedOptions?.[0]?.textContent || field?.value || fallback,
).trim();

const syncWhiteboardImageSettingsControls = () => {
  const form = elements.whiteboardImageForm;
  if (!form?.elements?.aspectRatio || !elements.whiteboardImageSettingsSummary) return;
  const aspectOrder = new Map(["auto", "21:9", "16:9", "3:2", "4:3", "1:1", "3:4", "2:3", "9:16"].map((value, index) => [value, index]));
  const aspectValues = [...form.elements.aspectRatio.options]
    .map((option) => option.value)
    .sort((left, right) => (aspectOrder.get(left) ?? 99) - (aspectOrder.get(right) ?? 99));
  elements.whiteboardImageAspectChoices.innerHTML = aspectValues.map((value) => {
    const selected = form.elements.aspectRatio.value === value;
    return `<button type="button" data-image-setting="aspectRatio" data-image-setting-value="${escapeHtml(value)}" aria-pressed="${selected}" class="${selected ? "selected" : ""}">${whiteboardAspectRatioGlyphMarkup(value)}<span>${escapeHtml(whiteboardAspectRatioShortLabel(value))}</span></button>`;
  }).join("");
  const qualityValues = [...form.elements.quality.options].map((option) => ({
    value: option.value,
    label: String(option.textContent || option.value).trim(),
  }));
  elements.whiteboardImageQualityChoices.innerHTML = qualityValues.map(({ value, label }) => {
    const selected = form.elements.quality.value === value;
    return `<button type="button" data-image-setting="quality" data-image-setting-value="${escapeHtml(value)}" aria-pressed="${selected}" class="${selected ? "selected" : ""}">${escapeHtml(label)}</button>`;
  }).join("");
  const selectedCount = String(form.elements.imageCount?.value || "1");
  elements.whiteboardImageCountChoices.querySelectorAll("[data-image-setting-value]").forEach((button) => {
    const selected = button.dataset.imageSettingValue === selectedCount;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  const ratio = whiteboardAspectRatioShortLabel(form.elements.aspectRatio.value || "auto");
  const quality = selectedOptionLabel(form.elements.quality, "标准");
  elements.whiteboardImageSettingsSummary.textContent = `${ratio} · ${quality} · ${selectedCount}张`;
  elements.whiteboardImageSettingsTrigger.title = `比例 ${ratio}；清晰度 ${quality}；生成 ${selectedCount} 张`;
};

const setWhiteboardImageSetting = (name, value) => {
  const field = elements.whiteboardImageForm?.elements?.[name];
  if (!field || ![...field.options].some((option) => option.value === String(value))) return false;
  field.value = String(value);
  field.dispatchEvent(new Event("input", { bubbles: true }));
  field.dispatchEvent(new Event("change", { bubbles: true }));
  syncWhiteboardImageSettingsControls();
  return true;
};

const syncWhiteboardImageCapabilityOptions = () => {
  const form = elements.whiteboardImageForm;
  const profile = whiteboardPickerProfile("image", form.elements.connectionId.value, form.elements.model.value);
  if (!profile) return;
  const model = String(form.elements.model.value || profile.model || "").trim();
  const capabilities = imageModelCapabilities(profile.provider, model, dynamicModelsForChannel(profile.provider, profile.adapter));
  const previousRatio = form.elements.aspectRatio.value || "auto";
  const previousQuality = form.elements.quality.value || DEFAULT_IMAGE_GENERATION_QUALITY;
  const ratioLabels = { auto: "自适应", "21:9": "21:9 超宽屏", "16:9": "16:9 横屏", "3:2": "3:2 横向", "4:3": "4:3 横向", "1:1": "1:1 方形", "3:4": "3:4 竖向", "2:3": "2:3 竖向", "9:16": "9:16 竖屏" };
  const qualityLabels = { standard: "标准", high: "高清", "1k": "1K", "2k": "2K", "4k": "4K" };
  const aspectRatios = [...new Set(["auto", ...capabilities.aspectRatios])];
  form.elements.aspectRatio.innerHTML = aspectRatios.map((value) => `<option value="${value}">${ratioLabels[value] || value}</option>`).join("");
  form.elements.quality.innerHTML = capabilities.resolutions.map((value) => `<option value="${value}">${qualityLabels[value] || value.toUpperCase()}</option>`).join("");
  form.elements.aspectRatio.value = aspectRatios.includes(previousRatio) ? previousRatio : "auto";
  form.elements.quality.value = capabilities.resolutions.includes(previousQuality)
    ? previousQuality
    : capabilities.resolutions.includes(DEFAULT_IMAGE_GENERATION_QUALITY)
      ? DEFAULT_IMAGE_GENERATION_QUALITY
      : capabilities.resolutions[0] || "standard";
  syncWhiteboardImageSettingsControls();
};

const compactWhiteboardMediaModelLabel = (model) => {
  return modelPickerDisplayName(model)
    .replace(/\s*[（(](?:即梦|Dreamina)\s+CLI[）)]\s*$/iu, "")
    .trim();
};

const WHITEBOARD_VIDEO_MODEL_VISUAL_ORDER = new Map([
  "seedance2.5",
  "seedance2.0_vip",
  "seedance2.0fast_vip",
  "seedance2.0mini",
  "seedance2.0",
  "seedance2.0fast",
  "seedance1.5pro",
  "seedance1.0fast",
  "seedance1.0",
].map((slug, index) => [slug, index]));

const sortWhiteboardVideoModels = (models = []) => models
  .map((model, index) => ({ model, index }))
  .sort((left, right) => {
    const leftOrder = WHITEBOARD_VIDEO_MODEL_VISUAL_ORDER.get(left.model.slug);
    const rightOrder = WHITEBOARD_VIDEO_MODEL_VISUAL_ORDER.get(right.model.slug);
    if (leftOrder === undefined && rightOrder === undefined) return left.index - right.index;
    if (leftOrder === undefined) return 1;
    if (rightOrder === undefined) return -1;
    return leftOrder - rightOrder;
  })
  .map(({ model }) => model);

const whiteboardMediaPickers = () => [
  { select: elements.whiteboardImageForm?.elements?.connectionId, trigger: elements.whiteboardImageConnectionTrigger, label: elements.whiteboardImageConnectionLabel, menu: elements.whiteboardImageConnectionMenu },
  { select: elements.whiteboardImageForm?.elements?.model, trigger: elements.whiteboardImageModelTrigger, label: elements.whiteboardImageModelLabel, menu: elements.whiteboardImageModelMenu },
  { select: elements.whiteboardVideoForm?.elements?.connectionId, trigger: elements.whiteboardVideoConnectionTrigger, label: elements.whiteboardVideoConnectionLabel, menu: elements.whiteboardVideoConnectionMenu },
  { select: elements.whiteboardVideoForm?.elements?.model, trigger: elements.whiteboardVideoModelTrigger, label: elements.whiteboardVideoModelLabel, menu: elements.whiteboardVideoModelMenu },
  { select: elements.whiteboardAudioForm?.elements?.connectionId, trigger: elements.whiteboardAudioConnectionTrigger, label: elements.whiteboardAudioConnectionLabel, menu: elements.whiteboardAudioConnectionMenu },
  { select: elements.whiteboardAudioForm?.elements?.model, trigger: elements.whiteboardAudioModelTrigger, label: elements.whiteboardAudioModelLabel, menu: elements.whiteboardAudioModelMenu },
];

const whiteboardFloatingMenuIsOpen = (menu) => {
  if (!menu) return false;
  try {
    if (typeof menu.showPopover === "function") return menu.matches(":popover-open");
  } catch {}
  return !menu.hidden;
};

const clearWhiteboardFloatingDropupPosition = (menu) => {
  if (!menu) return;
  menu.style.removeProperty("left");
  menu.style.removeProperty("right");
  menu.style.removeProperty("top");
  menu.style.removeProperty("bottom");
  menu.style.removeProperty("width");
  menu.style.removeProperty("max-height");
  menu.style.removeProperty("inset");
};

const syncWhiteboardFloatingDropupState = (menu, trigger, openState = null) => {
  if (!menu) return false;
  const open = typeof openState === "boolean" ? openState : whiteboardFloatingMenuIsOpen(menu);
  menu.hidden = !open;
  trigger?.setAttribute("aria-expanded", String(open));
  if (!open) clearWhiteboardFloatingDropupPosition(menu);
  return open;
};

const positionWhiteboardFloatingDropup = (menu, trigger) => {
  if (!menu || !trigger || !whiteboardFloatingMenuIsOpen(menu)) return;
  const viewportMargin = 10;
  const gap = 6;
  const control = trigger.closest(".whiteboard-media-picker, .whiteboard-media-mode-option") || trigger;
  const controlRect = control.getBoundingClientRect();
  const width = Math.max(1, controlRect.width);
  const left = Math.max(viewportMargin, Math.min(controlRect.left, window.innerWidth - width - viewportMargin));
  const availableAbove = Math.max(72, controlRect.top - gap - viewportMargin);
  const preferredMaxHeight = menu === elements.whiteboardVideoModeMenu ? 260 : 320;
  menu.style.position = "fixed";
  menu.style.inset = "auto";
  menu.style.left = `${Math.round(left)}px`;
  menu.style.right = "auto";
  menu.style.top = "auto";
  menu.style.bottom = `${Math.round(window.innerHeight - controlRect.top + gap)}px`;
  menu.style.width = `${Math.round(width)}px`;
  menu.style.maxHeight = `${Math.round(Math.min(preferredMaxHeight, availableAbove))}px`;
};

const openWhiteboardFloatingDropup = (menu, trigger) => {
  if (!menu || !trigger) return;
  menu.hidden = false;
  if (typeof menu.showPopover === "function") {
    try {
      if (!menu.matches(":popover-open")) menu.showPopover();
    } catch {}
  }
  positionWhiteboardFloatingDropup(menu, trigger);
  requestAnimationFrame(() => positionWhiteboardFloatingDropup(menu, trigger));
};

const closeWhiteboardFloatingDropup = (menu) => {
  if (!menu) return;
  if (typeof menu.hidePopover === "function") {
    try {
      if (menu.matches(":popover-open")) menu.hidePopover();
    } catch {}
  }
  syncWhiteboardFloatingDropupState(menu, null, false);
};

const positionOpenWhiteboardFloatingDropups = () => {
  for (const picker of whiteboardMediaPickers()) {
    if (whiteboardFloatingMenuIsOpen(picker.menu)) positionWhiteboardFloatingDropup(picker.menu, picker.trigger);
  }
  if (whiteboardFloatingMenuIsOpen(elements.whiteboardVideoModeMenu)) {
    positionWhiteboardFloatingDropup(elements.whiteboardVideoModeMenu, elements.whiteboardVideoModeTrigger);
  }
};

const closeWhiteboardMediaPickerMenus = (except = null) => {
  const exceptMenu = except?.menu || except;
  for (const picker of whiteboardMediaPickers()) {
    if (picker.menu === exceptMenu) continue;
    closeWhiteboardFloatingDropup(picker.menu);
    picker.trigger?.setAttribute("aria-expanded", "false");
  }
};

const syncWhiteboardMediaPicker = (picker) => {
  const { select, trigger, label, menu } = picker || {};
  if (!select || !trigger || !label || !menu) return;
  const options = [...select.options];
  const current = options.find((option) => option.value === select.value)
    || options.find((option) => !option.disabled)
    || options[0];
  label.textContent = current?.textContent?.trim() || "请选择";
  trigger.disabled = select.disabled || !options.some((option) => !option.disabled);
  trigger.title = current?.title || label.textContent;
  menu.innerHTML = options.map((option) => `
    <button type="button" role="option" data-whiteboard-media-picker-value="${escapeHtml(option.value)}" aria-selected="${option.value === select.value}" ${option.disabled ? "disabled" : ""} title="${escapeHtml(option.title || option.textContent || option.value)}">
      <span>${escapeHtml(option.textContent || option.value)}</span>${option.value === select.value ? icon("\uE73E", "已选择") : ""}
    </button>
  `).join("");
};

const syncWhiteboardMediaPickers = (...selects) => {
  const selected = new Set(selects.filter(Boolean));
  for (const picker of whiteboardMediaPickers()) {
    if (!selected.size || selected.has(picker.select)) syncWhiteboardMediaPicker(picker);
  }
};

const syncWhiteboardImageModelOptions = (preferredModel = "") => {
  const form = elements.whiteboardImageForm;
  const input = form.elements.model;
  const profile = whiteboardPickerProfile("image", form.elements.connectionId.value);
  const models = imageModelsForConnection(profile);
  const previous = String(preferredModel || input.value || "");
  input.innerHTML = models.length
    ? models.map((model) => `<option value="${escapeHtml(model.slug)}" title="${escapeHtml(model.label || model.slug)}">${escapeHtml(compactWhiteboardMediaModelLabel(model))}</option>`).join("")
    : '<option value="" disabled>当前连接没有可选择的图片模型</option>';
  input.disabled = !models.length;
  input.value = models.some((model) => model.slug === previous)
    ? previous
    : models.some((model) => model.slug === profile?.model)
      ? profile.model
      : models[0]?.slug || profile?.model || "";
  syncWhiteboardImageCapabilityOptions();
  syncWhiteboardMediaPickers(form.elements.connectionId, input);
};

const whiteboardMediaSettingsPanelIsOpen = (trigger) => trigger?.getAttribute("aria-expanded") === "true";

const positionWhiteboardMediaSettingsPanel = (panel, trigger, { maxWidth = 410 } = {}) => {
  if (!panel || !trigger || panel.hidden || !whiteboardMediaSettingsPanelIsOpen(trigger)) return;
  const margin = 10;
  const gap = 8;
  const triggerRect = trigger.getBoundingClientRect();
  const width = Math.min(maxWidth, Math.max(260, window.innerWidth - margin * 2));
  panel.style.width = `${Math.round(width)}px`;
  panel.style.maxHeight = "none";
  const naturalHeight = Math.min(Math.max(panel.scrollHeight + 2, panel.getBoundingClientRect().height), window.innerHeight - margin * 2);
  panel.style.maxHeight = `${Math.floor(naturalHeight)}px`;
  panel.style.left = `${Math.round(Math.min(Math.max(triggerRect.right - width, margin), window.innerWidth - width - margin))}px`;
  const preferredAbove = triggerRect.top - gap - naturalHeight;
  const preferredBelow = triggerRect.bottom + gap;
  const top = preferredAbove >= margin
    ? preferredAbove
    : preferredBelow + naturalHeight <= window.innerHeight - margin
      ? preferredBelow
      : Math.min(Math.max(triggerRect.bottom - naturalHeight, margin), window.innerHeight - margin - naturalHeight);
  panel.style.top = `${Math.round(top)}px`;
};

const setWhiteboardMediaSettingsPanelOpen = ({ panel, trigger, open, sync, position }) => {
  if (!panel || !trigger) return;
  if (!open) {
    if (panel.matches?.(":popover-open")) {
      try { panel.hidePopover(); } catch {}
    }
    panel.hidden = true;
    trigger.setAttribute("aria-expanded", "false");
    return;
  }
  trigger.scrollIntoView({ block: "nearest", inline: "nearest" });
  panel.hidden = false;
  if (typeof panel.showPopover === "function" && !panel.matches(":popover-open")) {
    try { panel.showPopover(); } catch {}
  }
  trigger.setAttribute("aria-expanded", "true");
  sync?.();
  position?.();
  requestAnimationFrame(position);
};

const whiteboardImageSettingsPanelIsOpen = () => whiteboardMediaSettingsPanelIsOpen(elements.whiteboardImageSettingsTrigger);
const positionWhiteboardImageSettingsPanel = () => positionWhiteboardMediaSettingsPanel(elements.whiteboardImageSettingsPanel, elements.whiteboardImageSettingsTrigger);
const setWhiteboardImageSettingsPanelOpen = (open) => setWhiteboardMediaSettingsPanelOpen({
  panel: elements.whiteboardImageSettingsPanel,
  trigger: elements.whiteboardImageSettingsTrigger,
  open,
  sync: syncWhiteboardImageSettingsControls,
  position: positionWhiteboardImageSettingsPanel,
});

const audioModelsForConnection = (profile, preferredModel = "") => {
  if (!profile) return [];
  const probe = mediaCapabilityProbeFor("audio", profile);
  const probeHasAuthoritativeCatalogue = probe?.visibilityChecked === true
    && Array.isArray(probe.models)
    && probe.models.length > 0;
  const models = getProviderAudioModelOptions(profile.provider, profile.adapter)
    .filter((model) => model.available !== false
      && (!probeHasAuthoritativeCatalogue || modelAllowedByMediaProbe(probe, model.slug) !== false));
  for (const slug of probeModelIds(probe?.models)) {
    if (models.some((model) => model.slug === slug)) continue;
    models.push({ slug, label: String(probe?.modelNames?.[slug] || slug), capabilities: ["audio_generation"] });
  }
  const requestedModel = String(preferredModel || profile.model || "").trim();
  if (requestedModel && !models.some((model) => model.slug === requestedModel)) {
    models.unshift({ slug: requestedModel, label: requestedModel, capabilities: ["audio_generation"] });
  }
  return models;
};

const inferredWhiteboardAudioType = (model = "") => /^speech-|^vocal-v3$/i.test(model)
  ? "speech"
  : /vocal-music|mureka/i.test(model) ? "music" : "sound";

const syncWhiteboardAudioSettingsControls = ({ applyModelDefaults = false } = {}) => {
  const form = elements.whiteboardAudioForm;
  if (!form) return;
  const model = String(form.elements.model?.value || "");
  const speechModel = /^speech-|^vocal-v3$/i.test(model);
  const musicModel = /vocal-music|mureka/i.test(model);
  const soundModel = !speechModel && !musicModel;
  if (applyModelDefaults || !form.elements.audioType.value) form.elements.audioType.value = inferredWhiteboardAudioType(model);
  if (speechModel) form.elements.audioType.value = "speech";
  if (musicModel) form.elements.audioType.value = "music";
  if (soundModel) form.elements.audioType.value = "sound";
  [...form.elements.audioType.options].forEach((option) => {
    option.disabled = (speechModel && option.value !== "speech")
      || (musicModel && option.value !== "music")
      || (soundModel && option.value !== "sound");
  });
  const speech = form.elements.audioType.value === "speech";
  elements.whiteboardAudioVoiceField.hidden = !speech;
  elements.whiteboardAudioSpeedField.hidden = !speech;
  const typeLabel = form.elements.audioType.selectedOptions[0]?.textContent || "自动";
  const languageLabel = form.elements.language.selectedOptions[0]?.textContent || "中文";
  const formatLabel = String(form.elements.format.value || "wav").toUpperCase();
  elements.whiteboardAudioSettingsSummary.textContent = `${typeLabel} · ${languageLabel} · ${formatLabel}`;
};

const syncWhiteboardAudioModelOptions = (preferredModel = "", { applyModelDefaults = false } = {}) => {
  const form = elements.whiteboardAudioForm;
  const profile = whiteboardPickerProfile("audio", form.elements.connectionId.value);
  if (!profile) return;
  const previousModel = String(preferredModel || form.elements.model.value || profile.model || "").trim();
  const models = audioModelsForConnection(profile, previousModel);
  form.elements.model.innerHTML = models.length
    ? models.map((model) => `<option value="${escapeHtml(model.slug)}" title="${escapeHtml(model.label || model.slug)}">${escapeHtml(compactWhiteboardMediaModelLabel(model))}</option>`).join("")
    : '<option value="" disabled>当前连接没有可选择的音频模型</option>';
  form.elements.model.disabled = !models.length;
  form.elements.model.value = models.some((model) => model.slug === previousModel)
    ? previousModel
    : models.some((model) => model.slug === profile.model) ? profile.model : models[0]?.slug || "";
  syncWhiteboardAudioSettingsControls({ applyModelDefaults });
  syncWhiteboardMediaPickers(form.elements.connectionId, form.elements.model);
};

const whiteboardAudioSettingsPanelIsOpen = () => whiteboardMediaSettingsPanelIsOpen(elements.whiteboardAudioSettingsTrigger);
const positionWhiteboardAudioSettingsPanel = () => positionWhiteboardMediaSettingsPanel(elements.whiteboardAudioSettingsPanel, elements.whiteboardAudioSettingsTrigger);
