const openWhiteboardImageDialog = (nodeId, aspectRatio = "auto", { allowUnavailable = false, centered = false } = {}) => {
  const sourceProfiles = allowUnavailable
    ? generationConnectionsForDraftRecovery("image")
    : visibleGenerationPickerProfiles(state.settings, "image");
  const profiles = dreaminaPickerProfiles("image", sourceProfiles);
  if (!profiles.length) {
    showToast("请先在模型设置中配置可用的图片 API 或 CLI 连接");
    return;
  }
  const node = whiteboardNodeById(nodeId);
  if (!node) return;
  primeWhiteboardGenerationDialog(elements.whiteboardImageDialog, nodeId, { centered });
  scheduleUiInitializationAfterPaint(() => {
    if (!elements.whiteboardImageDialog.open
      || elements.whiteboardImageDialog.dataset.anchorNodeId !== nodeId
      || elements.whiteboardImageDialog.dataset.anchorDocumentId !== state.activeDocument) return;
    reactivateWhiteboardGenerationIntent(nodeId);
    prepareWhiteboardGenerationDialogSwitch("image", nodeId);
    elements.whiteboardImageForm.dataset.nodeId = nodeId;
    setWhiteboardGenerationSubmitBusy(elements.whiteboardImageForm, whiteboardMediaSubmissionLocks.has(whiteboardMediaSubmissionKey({ channel: "image", nodeId })));
    elements.whiteboardImageForm.elements.explicitReferences.value = "";
    elements.whiteboardImageForm.elements.referenceOrder.value = "";
    elements.whiteboardImageForm.elements.promptReferenceSequence.value = "";
    elements.whiteboardImageForm.elements.includeTargetReference.value = "";
    elements.whiteboardImageForm.elements.prompt.value = whiteboardGenerationPromptFor(node, "image");
    elements.whiteboardImageForm.elements.aspectRatio.value = aspectRatio || DEFAULT_IMAGE_GENERATION_ASPECT_RATIO;
    elements.whiteboardImageForm.elements.quality.value = DEFAULT_IMAGE_GENERATION_QUALITY;
    elements.whiteboardImageForm.elements.imageCount.value = "1";
    elements.whiteboardImageForm.elements.connectionId.innerHTML = mediaConnectionOptionsMarkup("image", profiles);
    const rememberedValues = whiteboardRememberedGenerationProfile("image");
    const rememberedConnectionId = profiles.some((profile) => profile.id === rememberedValues.connectionId)
      ? rememberedValues.connectionId
      : "";
    const draftValues = whiteboardGenerationDraftValues("image", nodeId);
    const cardValues = whiteboardGenerationProfileForNode(node, "image");
    const preferredConnectionId = String(draftValues?.connectionId || cardValues.connectionId || rememberedConnectionId || "");
    rememberedValues.connectionId = preferredConnectionId;
    elements.whiteboardImageForm.elements.connectionId.value = profiles.some((profile) => profile.id === rememberedValues.connectionId)
      ? rememberedValues.connectionId
      : preferredDefaultImageProfile(profiles)?.id || profiles[0].id;
    const draftConnectionId = whiteboardPickerIdForProfile("image", draftValues?.connectionId, sourceProfiles);
    if (draftConnectionId && profiles.some((profile) => profile.id === draftConnectionId)) {
      elements.whiteboardImageForm.elements.connectionId.value = draftConnectionId;
    }
    syncWhiteboardImageModelOptions(draftValues?.model || cardValues.model || rememberedValues.model);
    applyWhiteboardGenerationFormValues(elements.whiteboardImageForm, draftValues);
    // Applying a draft can change the connection after the first model list
    // was built. Rebuild once more so the selected model always belongs to the
    // restored connection instead of falling back to its first option.
    syncWhiteboardImageModelOptions(String(draftValues?.model || cardValues.model || rememberedValues.model || ""));
    syncWhiteboardMediaPickers(elements.whiteboardImageForm.elements.connectionId, elements.whiteboardImageForm.elements.model);
    elements.whiteboardImageForm.elements.prompt.value = sanitizeMediaProviderPrompt(elements.whiteboardImageForm.elements.prompt.value);
    renderWhiteboardGenerationInlineMentions(elements.whiteboardImageForm, { force: true });
    syncWhiteboardImageCapabilityOptions();
    setWhiteboardImageSettingsPanelOpen(false);
    renderWhiteboardGenerationReferences(elements.whiteboardImageReferences, nodeId);
    showWhiteboardGenerationDialog(elements.whiteboardImageDialog, nodeId, elements.whiteboardImageForm.elements.prompt);
    renderWhiteboardGenerationCredit("image");
  });
};

const videoModelsForConnection = (profile, preferredModel = "") => {
  if (!profile) return [];
  const probe = mediaCapabilityProbeFor("video", profile);
  const probeHasAuthoritativeCatalogue = probe?.visibilityChecked === true
    && Array.isArray(probe.models)
    && probe.models.length > 0;
  const models = getProviderVideoModelOptions(profile.provider, profile.adapter)
    .filter((model) => model.available !== false
      && (!probeHasAuthoritativeCatalogue || modelAllowedByMediaProbe(probe, model.slug) !== false));
  if (profile.adapter === "cli" && profile.cliPath === LIBTV_CLI_ALIAS && String(profile.provider || "").toLowerCase() === "libtv") {
    for (const slug of probeModelIds(probe?.models)) {
      if (models.some((model) => model.slug === slug)) continue;
      const label = String(probe?.modelNames?.[slug] || probe?.modelCapabilities?.[slug]?.modelName || slug);
      models.push({ slug, label, capabilities: ["video_generation"] });
    }
  }
  const requestedModel = String(preferredModel || profile.model || "").trim();
  if (getProviderPreset(profile.provider).custom === true && requestedModel && !models.some((model) => model.slug === requestedModel)) {
    return sortWhiteboardVideoModels([{ slug: requestedModel, label: requestedModel }, ...models]);
  }
  return sortWhiteboardVideoModels(models);
};

const whiteboardVideoRatioShortLabel = whiteboardAspectRatioShortLabel;

const syncWhiteboardVideoSettingsControls = () => {
  const form = elements.whiteboardVideoForm;
  if (!form?.elements?.aspectRatio || !elements.whiteboardVideoSettingsSummary) return;
  const aspectOrder = new Map(["auto", "16:9", "4:3", "1:1", "3:4", "9:16", "21:9"].map((value, index) => [value, index]));
  const aspectValues = [...form.elements.aspectRatio.options]
    .map((option) => option.value)
    .sort((left, right) => (aspectOrder.get(left) ?? 99) - (aspectOrder.get(right) ?? 99));
  elements.whiteboardVideoAspectChoices.innerHTML = aspectValues.map((value) => {
    const selected = form.elements.aspectRatio.value === value;
    return `<button type="button" data-video-setting="aspectRatio" data-video-setting-value="${escapeHtml(value)}" aria-pressed="${selected}" class="${selected ? "selected" : ""}">${whiteboardAspectRatioGlyphMarkup(value)}<span>${escapeHtml(whiteboardVideoRatioShortLabel(value))}</span></button>`;
  }).join("");
  const resolutionValues = [...form.elements.resolution.options].map((option) => option.value);
  elements.whiteboardVideoResolutionChoices.innerHTML = resolutionValues.map((value) => {
    const selected = form.elements.resolution.value === value;
    return `<button type="button" data-video-setting="resolution" data-video-setting-value="${escapeHtml(value)}" aria-pressed="${selected}" class="${selected ? "selected" : ""}">${escapeHtml(value.toUpperCase())}</button>`;
  }).join("");
  const durationValues = [...form.elements.duration.options].map((option) => option.value);
  const durationIndex = Math.max(0, durationValues.indexOf(form.elements.duration.value));
  elements.whiteboardVideoDurationRange.max = String(Math.max(0, durationValues.length - 1));
  elements.whiteboardVideoDurationRange.value = String(durationIndex);
  elements.whiteboardVideoDurationRange.disabled = durationValues.length < 2;
  const durationValue = durationValues[durationIndex] || form.elements.duration.value || "";
  const durationLabel = Number(durationValue) > 0
    ? `${durationValue} s`
    : form.dataset.videoDurationDerived === "true" ? "跟随参考" : "自动";
  elements.whiteboardVideoDurationOutput.value = durationLabel;
  const selectedAudio = String(form.elements.generateAudio?.value || "true");
  elements.whiteboardVideoAudioChoices.querySelectorAll("[data-video-setting-value]").forEach((button) => {
    const selected = button.dataset.videoSettingValue === selectedAudio;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  const selectedCount = String(form.elements.videoCount?.value || "1");
  elements.whiteboardVideoCountChoices.querySelectorAll("[data-video-setting-value]").forEach((button) => {
    const selected = button.dataset.videoSettingValue === selectedCount;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  const ratio = whiteboardVideoRatioShortLabel(form.elements.aspectRatio.value || "auto");
  const resolution = String(form.elements.resolution.value || "").toUpperCase();
  const duration = String(form.elements.duration.value || "0");
  const durationSummary = Number(duration) > 0
    ? `${duration}s`
    : form.dataset.videoDurationDerived === "true" ? "跟随参考" : "自动";
  const count = String(form.elements.videoCount?.value || "1");
  const audioEnabled = selectedAudio !== "false";
  const audio = audioEnabled ? "生成音频" : "关闭音频";
  elements.whiteboardVideoSettingsSummary.innerHTML = `${escapeHtml(`${ratio} · ${resolution} · ${durationSummary} · ${count}个 · `)}<span class="whiteboard-video-audio-state" title="${audio}" aria-label="${audio}">${icon(audioEnabled ? "\uE767" : "\uE74F", audio)}</span>`;
  elements.whiteboardVideoSettingsTrigger.title = `比例 ${ratio}；清晰度 ${resolution}；时长 ${durationSummary}；生成 ${count} 个；${audio}`;
};

const setWhiteboardVideoSetting = (name, value) => {
  const field = elements.whiteboardVideoForm?.elements?.[name];
  if (!field || ![...field.options].some((option) => option.value === String(value))) return false;
  field.value = String(value);
  field.dispatchEvent(new Event("input", { bubbles: true }));
  field.dispatchEvent(new Event("change", { bubbles: true }));
  syncWhiteboardVideoSettingsControls();
  return true;
};

const whiteboardVideoSettingsPanelIsOpen = () => whiteboardMediaSettingsPanelIsOpen(elements.whiteboardVideoSettingsTrigger);
const positionWhiteboardVideoSettingsPanel = () => positionWhiteboardMediaSettingsPanel(elements.whiteboardVideoSettingsPanel, elements.whiteboardVideoSettingsTrigger);
