elements.whiteboardImageForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  syncWhiteboardRichPromptValue(elements.whiteboardImageForm);
  writeWhiteboardGenerationReferenceOrder(elements.whiteboardImageForm, whiteboardGenerationReferenceOrder(elements.whiteboardImageForm));
  const formData = new FormData(elements.whiteboardImageForm);
  const nodeId = elements.whiteboardImageForm.dataset.nodeId;
  const prompt = String(formData.get("prompt") ?? "").trim();
  if (!prompt) {
    showToast("请先输入画面描述");
    elements.whiteboardImageForm.querySelector('[contenteditable="true"][aria-label="画面描述"]')?.focus();
    return;
  }
  persistWhiteboardGenerationProfile("image", whiteboardGenerationFormValues(elements.whiteboardImageForm));
  const submissionLockKey = whiteboardMediaSubmissionKey({ channel: "image", nodeId });
  const submissionLockToken = acquireWhiteboardMediaSubmissionLock(submissionLockKey, "image");
  if (!submissionLockToken) {
    showToast("本次图片提交正在创建后台任务，请勿重复点击");
    return;
  }
  setWhiteboardGenerationSubmitBusy(elements.whiteboardImageForm, true);
  const sourceDocumentId = state.activeDocument;
  const sourceWorkspaceKind = state.workspaceKind;
  const sourceWorkspacePath = state.settings.workspacePath;
  const candidateKey = whiteboardCandidateKey(nodeId, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
  try {
    const submissionFeedback = beginWhiteboardSubmissionFeedback({
      nodeId,
      workspacePath: sourceWorkspacePath,
      documentId: sourceDocumentId,
      channel: "image",
      prompt,
    });
    elements.whiteboardImageDialog.close();
    const requestedAspectRatio = String(formData.get("aspectRatio") ?? "auto");
    const connectionId = String(formData.get("connectionId") ?? "");
    const selectedModel = String(formData.get("model") ?? "").trim();
    const imageCount = Math.max(1, Math.min(4, Number(formData.get("imageCount")) || 1));
    const imageSettings = currentImageGenerationSettings(connectionId, selectedModel);
    if (!(await ensureDreaminaGenerationAccountAvailable(imageSettings, { channel: "image" }))) {
      cancelWhiteboardSubmissionFeedback(candidateKey, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
      finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
      return;
    }
    const includeTarget = formData.get("includeTargetReference") === "true";
    try {
      await hydrateWhiteboardWebReferences(nodeId, { includeTarget });
  } catch (error) {
    showToast(`网页资料读取失败，未开始生成：${error.message}`);
    cancelWhiteboardSubmissionFeedback(candidateKey, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    return;
  }
  const referenceOrder = String(formData.get("referenceOrder") ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  const promptReferenceSequence = String(formData.get("promptReferenceSequence") ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  const generationContext = whiteboardGenerationContext(nodeId, String(formData.get("explicitReferences") ?? "").split(",").filter(Boolean), prompt, {
    includeTarget,
    referenceOrder,
  });
  const { upstream, modelAttachments } = generationContext;
  const referencePlan = whiteboardMediaReferencePlan({ channel: "image", settings: imageSettings, modelAttachments });
  const imageCapabilities = imageModelCapabilities(imageSettings?.provider, imageSettings?.model, dynamicModelsForChannel(imageSettings?.provider, imageSettings?.adapter));
  const aspectRatio = whiteboardResolvedAspectRatio({
    requestedRatio: requestedAspectRatio,
    nodeId,
    prompt: `${prompt}\n${upstream.map(whiteboardNodeSummary).join("\n")}`,
    channel: "image",
    allowedRatios: imageCapabilities.aspectRatios,
    includeTarget: generationContext.targetIsInput,
  });
  const [ratioWidth, ratioHeight] = aspectRatio.split(":").map(Number);
  if (!nodeId || !prompt || !imageSettings) {
    cancelWhiteboardSubmissionFeedback(candidateKey, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    return;
  }
  if (!checkWhiteboardReferenceCapacity(activeWhiteboardDocument()?.canvas, [nodeId], {
    channel: "image",
    settings: imageSettings,
    operation: "generate",
    includeTargetMedia: generationContext.targetIsInput,
  }).ok || !preflightWhiteboardMediaSubmission({ referencePlan, generationContext, prompt })) {
    cancelWhiteboardSubmissionFeedback(candidateKey, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    return;
  }
  // The connection and model selected here belong to this job only. A card
  // generation must never rewrite the user's configured/default model.
  const previousGenerationJobId = String(whiteboardCandidateFor(nodeId, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId })?.jobId
    || whiteboardNodeById(nodeId)?.generation?.jobId
    || "");
  const beforeCanvas = whiteboardCanvasSnapshot(state.documents[sourceDocumentId]?.canvas);
  let durableJob = null;
  let providerGenerationSucceeded = false;
  let cardApplyConfirmed = false;
  try {
    const effectivePrompt = await buildWhiteboardMediaProviderPrompt({ prompt, channel: "image", generationContext, referencePlan });
    updateWhiteboardGenerationCandidate(candidateKey, { progressPercent: 28 });
    durableJob = await createWhiteboardMediaGenerationJob({
      channel: "image",
      target: whiteboardGenerationJobTarget({ workspaceKind: sourceWorkspaceKind, workspacePath: sourceWorkspacePath, documentId: sourceDocumentId, nodeId }),
      forceNewGeneration: true,
      regenerationOfJobId: previousGenerationJobId,
      request: {
        interactionStartedAt: new Date(submissionFeedback.startedAt || Date.now()).toISOString(),
        prompt: effectivePrompt,
        displayPrompt: prompt,
        providerPromptReferenceTokens: whiteboardGenerationProviderReferenceTokens(generationContext),
        referenceOrder,
        promptReferenceSequence,
        settings: { ...imageSettings, workspacePath: sourceWorkspacePath },
        generationProfile: whiteboardGenerationProfileFromSettings(imageSettings, "chat"),
        aspectRatio,
        quality: formData.get("quality"),
        imageCount,
        referenceMedia: referencePlan.directReferences,
        novelCover: isNovelCoverRequest(prompt)
          ? novelCoverAssetMetadata({ contract: novelCoverContractForMediaPrompt(prompt) })
          : null,
      },
    });
    updateWhiteboardGenerationCandidate(candidateKey, {
      jobId: durableJob.id,
      status: durableJob.status,
      providerStatus: durableJob.providerStatus,
      model: String(durableJob.request?.settings?.model || durableJob.settings?.model || imageSettings?.model || ""),
      providerTaskId: durableJob.providerTaskId,
      submissionState: durableJob.submissionState,
      submittedAt: durableJob.submittedAt,
      progressPercent: durableJob.progressPercent,
    });
    // The lock prevents an accidental double click only until the durable job
    // exists. A later deliberate click is a replacement request and must be
    // allowed to reach the server while this task continues in the background.
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    durableJob = await waitForWhiteboardGenerationJob(durableJob.id, candidateKey);
    if (durableJob.status !== "complete") throw new Error(mediaGenerationErrorText(durableJob) || "图片生成失败");
    if (!whiteboardCandidateBelongsToJob(candidateKey, durableJob.id)) return;
    providerGenerationSucceeded = true;
    const background = normalizedWorkspacePath(sourceWorkspacePath) !== normalizedWorkspacePath(state.settings.workspacePath);
    await applyCompletedWhiteboardGenerationJob(durableJob, { beforeCanvas });
    cardApplyConfirmed = true;
    showToast(background
      ? "图片已生成并保存到发起任务的原白板"
      : `图片已生成并读取 ${upstream.length} 个上游节点，${requestedAspectRatio === "auto" ? "自适应画幅" : "画幅"}为 ${aspectRatio}`);
  } catch (error) {
    const ownsCandidate = durableJob
      ? whiteboardCandidateBelongsToJob(candidateKey, durableJob.id)
      : Boolean(ui.whiteboardCandidates.get(candidateKey) && !ui.whiteboardCandidates.get(candidateKey)?.jobId);
    if (!ownsCandidate) return;
    const providerCompleted = durableJob?.status === "complete";
    const interruptedJob = durableJob
      ? providerCompleted
        ? completedWhiteboardApplyPendingJob(durableJob, error)
        : { ...durableJob, error: durableJob.error || error.message }
      : null;
    stopWhiteboardGenerationCandidate(candidateKey, { remove: !whiteboardMediaJobHoldsCard(interruptedJob) });
    if (interruptedJob) showInterruptedWhiteboardGenerationJob(interruptedJob);
    if (state.activeDocument === sourceDocumentId && state.settings.workspacePath === sourceWorkspacePath) renderWhiteboard(activeWhiteboardDocument());
    if (providerCompleted) {
      retryCompletedWhiteboardGenerationApply(durableJob, { beforeCanvas });
      showToast("图片已生成，正在重试写入卡片；不会重复提交或扣费");
    } else if (dreaminaFailureNeedsVerification({ error, job: durableJob })) {
      const failure = dreaminaFailureDiagnosis(dreaminaFailureInput({ error, job: durableJob }));
      openDreaminaReverifyDialog({ settings: imageSettings });
      showToast(`即梦图片账号需要核验。${failure.resolution}`);
    } else if (String(error?.code || "").toUpperCase() === "DREAMINA_PROFILE_SWITCH_BLOCKED") {
      openDreaminaProfileLockDialog(error.details || {});
    } else showToast(`图片生成失败：${error.message}`);
  } finally {
    if (cardApplyConfirmed || !providerGenerationSucceeded) {
      finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    }
  }
  } catch (error) {
    cancelWhiteboardSubmissionFeedback(candidateKey, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "image", form: elements.whiteboardImageForm });
    showToast(`图片生成未开始：${error?.message || "提交前检查失败，请重试"}`);
  }
});

