const materializeWhiteboardVideoGenerationTargets = (nodeId, requestedCount, {
  documentId = state.activeDocument,
  workspacePath = state.settings.workspacePath,
} = {}) => {
  if (state.activeDocument !== documentId
    || normalizedWorkspacePath(state.settings.workspacePath) !== normalizedWorkspacePath(workspacePath)) return [];
  const documentState = activeWhiteboardDocument();
  const source = whiteboardNodeById(nodeId, documentState);
  const count = [1, 2, 3, 4].includes(Number(requestedCount)) ? Number(requestedCount) : 1;
  if (!documentState || !source || count === 1) return source ? [nodeId] : [];
  const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
  let canvas = documentState.canvas;
  const nodeIds = [nodeId];
  for (let index = 1; index < count; index += 1) {
    const duplicated = duplicateCanvasNodeBelow(canvas, nodeId, {
      id: uid(["image", "video", "audio"].includes(source.kind) ? "canvas-file" : "canvas-node"),
      inheritEdges: "upstream",
    });
    if (!duplicated.nodeId) break;
    canvas = duplicated.canvas;
    nodeIds.push(duplicated.nodeId);
  }
  if (nodeIds.length !== count) return [];
  documentState.canvas = canvas;
  documentState.updatedAt = nowTime();
  pushWhiteboardHistory(beforeCanvas, { label: `创建 ${count} 个视频生成目标` });
  persist();
  renderWhiteboard(documentState);
  return nodeIds;
};

const compositeLongVideoManifestForNode = (nodeId, documentState = activeWhiteboardDocument()) => (
  whiteboardNodeById(nodeId, documentState)?.generation?.compositeLongVideo || null
);

const saveCompositeLongVideoManifest = (nodeId, manifest, { render = true } = {}) => {
  const documentState = activeWhiteboardDocument();
  const node = whiteboardNodeById(nodeId, documentState);
  if (!node || !manifest) return false;
  node.generation = {
    ...(node.generation || {}),
    channel: "video",
    origin: "composite-long-video",
    compositeLongVideo: clone(manifest),
  };
  documentState.updatedAt = nowTime();
  persist();
  if (render) renderWhiteboard(documentState);
  const processDialog = document.querySelector("#compositeLongVideoProcessDialog");
  if (processDialog?.open && processDialog.dataset.nodeId === nodeId) renderCompositeLongVideoProcessDialog(nodeId);
  return true;
};

const compositeLongVideoStatusLabel = (status = "") => ({
  planned: "等待开始",
  ready: "准备提交",
  running: "正在生成",
  awaiting_next_segment: "准备下一段",
  paused_manual_action_required: "已暂停，等待手动处理",
  ready_to_concat: "等待拼接",
  concatenating: "正在拼接",
  complete: "已完成",
}[status] || status || "等待开始");

const ensureCompositeLongVideoProcessDialog = () => {
  let dialog = document.querySelector("#compositeLongVideoProcessDialog");
  if (dialog) return dialog;
  dialog = document.createElement("dialog");
  dialog.id = "compositeLongVideoProcessDialog";
  dialog.className = "composite-long-video-process-dialog";
  dialog.innerHTML = `<section><header><div><p class="eyebrow">超长视频</p><h3>生成过程</h3></div><button class="icon-button bare" type="button" data-close-composite-long-video-process aria-label="关闭">${icon("\uE711", "关闭")}</button></header><div data-composite-long-video-process-body></div></section>`;
  document.body.append(dialog);
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog || event.target.closest("[data-close-composite-long-video-process]")) dialog.close();
  });
  return dialog;
};

const renderCompositeLongVideoProcessDialog = (nodeId) => {
  const dialog = ensureCompositeLongVideoProcessDialog();
  const manifest = compositeLongVideoManifestForNode(nodeId);
  if (!manifest) return false;
  dialog.dataset.nodeId = nodeId;
  const body = dialog.querySelector("[data-composite-long-video-process-body]");
  const segments = Array.isArray(manifest.segments) ? manifest.segments : [];
  body.innerHTML = `
    <div class="composite-long-video-summary">
      <span><small>总时长</small><strong>${Number(manifest.totalDuration) || 0} 秒</strong></span>
      <span><small>进度</small><strong>${Number(manifest.completedSegments) || 0}/${segments.length}</strong></span>
      <span><small>状态</small><strong>${escapeHtml(compositeLongVideoStatusLabel(manifest.status))}</strong></span>
      <span><small>实际积分</small><strong>${Number(manifest.actualCredits) > 0 ? Number(manifest.actualCredits) : "待回执"}</strong></span>
    </div>
    <p class="composite-long-video-cost-note">不会自动重新提交失败片段。网络查询可以恢复，但任何新的计费生成都必须由用户手动确认。</p>
    <div class="composite-long-video-segments">
      ${segments.map((segment) => {
        const references = Array.isArray(segment.effectiveReferences) && segment.effectiveReferences.length
          ? segment.effectiveReferences
          : segment.sourceReferences || [];
        const failed = segment.status === "awaiting_manual_retry";
        const stale = segment.downstreamContinuityStale === true;
        return `<article class="composite-long-video-segment" data-segment-status="${escapeHtml(segment.status)}">
          <header><strong>第 ${segment.index + 1} 段 · ${segment.duration} 秒</strong><span>${escapeHtml(failed ? "生成失败，已暂停" : segment.status === "completed" ? "已完成" : segment.status === "submitted" ? "正在生成" : "等待生成")}</span></header>
          ${stale ? '<p class="warning">上游片段已重新生成，本段衔接基线可能过期；系统不会自动重生。</p>' : ""}
          <details><summary>分段提示词</summary><pre>${escapeHtml(segment.prompt || "")}</pre></details>
          <details><summary>参考与衔接（${references.length}）</summary><ul>${references.length ? references.map((reference) => `<li>${escapeHtml(reference.continuityFrame ? "上一段稳定尾帧" : reference.name || reference.id || reference.relativePath || reference.kind || "参考物")}</li>`).join("") : "<li>本段没有可用参考物</li>"}</ul></details>
          ${segment.output?.relativePath ? `<p class="composite-long-video-output">输出：${escapeHtml(segment.output.name || segment.output.relativePath)}</p>` : ""}
          ${segment.childJobId ? `<p class="composite-long-video-task-id">任务：${escapeHtml(segment.childJobId)}${segment.providerTaskId ? ` · ${escapeHtml(segment.providerTaskId)}` : ""}</p>` : ""}
          ${segment.error ? `<p class="error">${escapeHtml(segment.error)}</p>` : ""}
          ${failed ? `<button class="secondary-button" type="button" data-composite-long-video-retry="${segment.index}">手动重新生成此片段</button>` : ""}
        </article>`;
      }).join("")}
    </div>`;
  if (!dialog.open) dialog.showModal();
  return true;
};

const extractCompositeLongVideoTailFrame = async ({ workspacePath, attachment }) => {
  const response = await fetch("/api/workspace/video-frame", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ workspacePath, relativePath: attachment.relativePath, position: "last", currentTimeMs: 0 }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload.attachment?.relativePath) throw new Error(payload.message || "无法提取分段稳定尾帧");
  return { ...payload.attachment, kind: "continuity_frame", continuityFrame: true, frameTimeMs: payload.frameTimeMs };
};

const concatCompositeLongVideoOutputs = async ({ workspacePath, manifest }) => {
  const relativePaths = manifest.segments.map((segment) => segment.output?.relativePath).filter(Boolean);
  if (relativePaths.length !== manifest.segments.length) throw new Error("仍有分段没有生成结果，不能拼接");
  const response = await fetch("/api/workspace/video-concat", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ workspacePath, relativePaths, name: `超长视频-${manifest.totalDuration}秒.mp4` }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload.attachment?.relativePath) throw new Error(payload.message || "超长视频拼接失败");
  return payload.attachment;
};

const runCompositeLongVideoManifest = async ({ nodeId, manifest, workspaceKind, workspacePath, documentId, beforeCanvas, onFirstJobCreated = null }) => {
  const candidateKey = whiteboardCandidateKey(nodeId, { workspacePath, documentId });
  let current = clone(manifest);
  let firstJobCreatedNotified = false;
  const settings = currentVideoGenerationSettings(current.settings?.connectionId, current.settings?.model);
  if (!settings) throw new Error("原超长视频配置已不存在，未提交新的计费任务");
  for (let index = Math.max(0, Number(current.activeSegmentIndex) || 0); index < current.segments.length; index += 1) {
    const existing = current.segments[index];
    if (existing.status === "completed" && !existing.downstreamContinuityStale) continue;
    if (existing.status === "awaiting_manual_retry") break;
    const continuityFrame = index > 0 ? current.segments[index - 1]?.continuityFrame : null;
    current = prepareCompositeLongVideoSegment(current, index, { continuityFrame });
    saveCompositeLongVideoManifest(nodeId, current);
    updateWhiteboardGenerationCandidate(candidateKey, { progressPercent: Math.max(5, Math.round(index / current.segments.length * 90)), status: "running" });
    let childJob = null;
    try {
      const segment = current.segments[index];
      childJob = await createWhiteboardMediaGenerationJob({
        channel: "video",
        target: {
          ...whiteboardGenerationJobTarget({ workspaceKind, workspacePath, documentId, nodeId }),
          targetType: "composite-long-video-segment",
          artifactId: current.id,
        },
        request: {
          submissionId: `${current.id}:${segment.segmentId}:attempt:${Math.max(1, Number(segment.attempt) + 1)}`,
          interactionStartedAt: current.interactionStartedAt || current.createdAt,
          prompt: segment.prompt,
          displayPrompt: segment.localPrompt,
          providerPromptReferenceTokens: current.providerPromptReferenceTokens || [],
          settings: { ...settings, workspacePath },
          aspectRatio: current.settings.aspectRatio,
          generationMode: "smart_params",
          duration: segment.duration,
          resolution: current.settings.resolution,
          generateAudio: current.settings.generateAudio !== false,
          videoCount: 1,
          referenceMedia: segment.effectiveReferences,
        },
      });
      current = markCompositeLongVideoSegmentSubmitted(current, index, { childJobId: childJob.id, providerTaskId: childJob.providerTaskId });
      saveCompositeLongVideoManifest(nodeId, current);
      updateWhiteboardGenerationCandidate(candidateKey, {
        jobId: childJob.id,
        status: childJob.status,
        providerStatus: childJob.providerStatus,
        model: String(childJob.request?.settings?.model || childJob.settings?.model || settings?.model || ""),
        providerTaskId: childJob.providerTaskId,
        submissionState: childJob.submissionState,
        submittedAt: childJob.submittedAt,
        progressPercent: childJob.progressPercent || 10,
      });
      if (!firstJobCreatedNotified) {
        firstJobCreatedNotified = true;
        onFirstJobCreated?.(childJob);
      }
      childJob = await waitForWhiteboardGenerationJob(childJob.id, candidateKey);
      if (childJob.status !== "complete") throw new Error(mediaGenerationErrorText(childJob) || `第 ${index + 1} 段生成失败`);
      const output = childJob.result?.attachment;
      if (!output?.relativePath) throw new Error(`第 ${index + 1} 段缺少已校验的视频文件`);
      const tailFrame = index < current.segments.length - 1
        ? await extractCompositeLongVideoTailFrame({ workspacePath, attachment: output })
        : null;
      current = markCompositeLongVideoSegmentCompleted(current, index, {
        output,
        continuityFrame: tailFrame,
        actualCredits: childJob.actualCredits ?? childJob.result?.actualCredits,
      });
      current.segments[index].providerTaskId = childJob.providerTaskId || current.segments[index].providerTaskId;
      await markWhiteboardGenerationJobApplied(childJob.id);
      saveCompositeLongVideoManifest(nodeId, current);
    } catch (error) {
      if (childJob && !whiteboardCandidateBelongsToJob(candidateKey, childJob.id)) return current;
      current = markCompositeLongVideoSegmentFailed(current, index, error.message);
      saveCompositeLongVideoManifest(nodeId, current);
      stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
      renderCompositeLongVideoProcessDialog(nodeId);
      showToast(`超长视频已在第 ${index + 1} 段暂停；不会自动重新生成或扣费`);
      return current;
    }
  }
  if (current.status !== "ready_to_concat") return current;
  current = { ...current, status: "concatenating", updatedAt: new Date().toISOString() };
  saveCompositeLongVideoManifest(nodeId, current);
  const attachment = await concatCompositeLongVideoOutputs({ workspacePath, manifest: current });
  const landingJob = await createWhiteboardClientGenerationJob({
    channel: "video",
    target: whiteboardGenerationJobTarget({ workspaceKind, workspacePath, documentId, nodeId }),
    request: { prompt: current.prompt, interactionStartedAt: current.interactionStartedAt || current.createdAt, aspectRatio: current.settings.aspectRatio, generationMode: COMPOSITE_LONG_VIDEO_MODE, duration: current.totalDuration },
  });
  const completedLandingJob = await completeWhiteboardGenerationJob(landingJob.id, { attachment, elapsedMs: Date.now() - Date.parse(current.interactionStartedAt || current.createdAt) });
  await applyCompletedWhiteboardGenerationJob(completedLandingJob, { beforeCanvas });
  current = { ...current, status: "complete", combinedOutput: attachment, completedAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
  saveCompositeLongVideoManifest(nodeId, current, { render: false });
  stopWhiteboardGenerationCandidate(candidateKey, { remove: true });
  renderWhiteboard(activeWhiteboardDocument());
  showToast(`超长视频已完成：${current.segments.length} 个分段已生成、校验并拼接`);
  return current;
};

const resumeCompositeLongVideoSegmentManually = async (nodeId, segmentIndex) => {
  const manifest = compositeLongVideoManifestForNode(nodeId);
  if (!manifest) return;
  const segment = manifest.segments?.[segmentIndex];
  if (!segment || segment.status !== "awaiting_manual_retry") return;
  if (!window.confirm(`重新生成第 ${segmentIndex + 1} 段将创建新的计费任务。确定继续吗？`)) return;
  let current = requestCompositeLongVideoManualRetry(manifest, segmentIndex);
  saveCompositeLongVideoManifest(nodeId, current);
  ensureCompositeLongVideoProcessDialog().close();
  beginWhiteboardGenerationCandidate({ nodeId, workspacePath: state.settings.workspacePath, documentId: state.activeDocument, channel: "video", kind: "video", prompt: current.prompt });
  try {
    await runCompositeLongVideoManifest({
      nodeId,
      manifest: current,
      workspaceKind: state.workspaceKind,
      workspacePath: state.settings.workspacePath,
      documentId: state.activeDocument,
      beforeCanvas: whiteboardCanvasSnapshot(activeWhiteboardDocument()?.canvas),
    });
  } catch (error) {
    showToast(`超长视频继续失败：${error.message}`);
  }
};

const compositeLongVideoRecoveryFlights = new Map();

const recoverCompositeLongVideoChildJob = async (job) => {
  if (!job?.id || job.target?.targetType !== "composite-long-video-segment") return false;
  if (normalizedWorkspacePath(job.target.workspacePath) !== normalizedWorkspacePath(state.settings.workspacePath)
    || job.target.documentId !== state.activeDocument) return false;
  const nodeId = job.target.nodeId;
  let manifest = compositeLongVideoManifestForNode(nodeId);
  if (!manifest || manifest.id !== job.target.artifactId) return false;
  const segmentIndex = manifest.segments.findIndex((segment) => segment.childJobId === job.id);
  if (segmentIndex < 0) return false;
  if (compositeLongVideoRecoveryFlights.has(job.id)) return true;
  const settle = async (resolvedJob) => {
    manifest = compositeLongVideoManifestForNode(nodeId) || manifest;
    if (manifest.segments[segmentIndex]?.status === "completed") return true;
    if (resolvedJob.status !== "complete") {
      manifest = markCompositeLongVideoSegmentFailed(manifest, segmentIndex, mediaGenerationErrorText(resolvedJob) || "分段任务中断");
      saveCompositeLongVideoManifest(nodeId, manifest);
      return true;
    }
    const output = resolvedJob.result?.attachment;
    if (!output?.relativePath) throw new Error("恢复的超长视频分段缺少本地文件");
    const tailFrame = segmentIndex < manifest.segments.length - 1
      ? await extractCompositeLongVideoTailFrame({ workspacePath: job.target.workspacePath, attachment: output })
      : null;
    manifest = markCompositeLongVideoSegmentCompleted(manifest, segmentIndex, { output, continuityFrame: tailFrame, actualCredits: resolvedJob.actualCredits ?? resolvedJob.result?.actualCredits });
    manifest.segments[segmentIndex].providerTaskId = resolvedJob.providerTaskId || manifest.segments[segmentIndex].providerTaskId;
    await markWhiteboardGenerationJobApplied(resolvedJob.id);
    saveCompositeLongVideoManifest(nodeId, manifest);
    await runCompositeLongVideoManifest({
      nodeId,
      manifest,
      workspaceKind: job.target.workspaceKind,
      workspacePath: job.target.workspacePath,
      documentId: job.target.documentId,
      beforeCanvas: whiteboardCanvasSnapshot(activeWhiteboardDocument()?.canvas),
    });
    return true;
  };
  const operation = (MEDIA_JOB_ACTIVE_STATUSES.has(job.status)
    ? waitForWhiteboardGenerationJob(job.id, whiteboardCandidateKey(nodeId, { workspacePath: job.target.workspacePath, documentId: job.target.documentId })).then(settle)
    : settle(job))
    .catch((error) => {
      const current = compositeLongVideoManifestForNode(nodeId);
      if (current) saveCompositeLongVideoManifest(nodeId, markCompositeLongVideoSegmentFailed(current, segmentIndex, error.message));
      return false;
    })
    .finally(() => compositeLongVideoRecoveryFlights.delete(job.id));
  compositeLongVideoRecoveryFlights.set(job.id, operation);
  return true;
};

document.addEventListener("click", (event) => {
  const processButton = event.target.closest("[data-composite-long-video-process]");
  if (processButton) {
    event.preventDefault();
    event.stopPropagation();
    renderCompositeLongVideoProcessDialog(processButton.dataset.compositeLongVideoProcess);
    return;
  }
  const retryButton = event.target.closest("[data-composite-long-video-retry]");
  if (retryButton) {
    const dialog = retryButton.closest("#compositeLongVideoProcessDialog");
    void resumeCompositeLongVideoSegmentManually(dialog?.dataset.nodeId || "", Number(retryButton.dataset.compositeLongVideoRetry));
  }
});

elements.whiteboardVideoForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  syncWhiteboardRichPromptValue(elements.whiteboardVideoForm);
  writeWhiteboardGenerationReferenceOrder(elements.whiteboardVideoForm, whiteboardGenerationReferenceOrder(elements.whiteboardVideoForm));
  const formData = new FormData(elements.whiteboardVideoForm);
  const nodeId = elements.whiteboardVideoForm.dataset.nodeId;
  const rawPrompt = String(formData.get("prompt") ?? "").trim();
  if (!rawPrompt) {
    showToast("请先输入画面描述");
    elements.whiteboardVideoForm.querySelector('[contenteditable="true"][aria-label="画面描述"]')?.focus();
    return;
  }
  persistWhiteboardGenerationProfile("video", whiteboardGenerationFormValues(elements.whiteboardVideoForm));
  const submissionLockKey = whiteboardMediaSubmissionKey({ channel: "video", nodeId });
  const submissionLockToken = acquireWhiteboardMediaSubmissionLock(submissionLockKey, "video");
  if (!submissionLockToken) {
    showToast("本次视频提交正在创建后台任务，请勿重复点击");
    return;
  }
  setWhiteboardGenerationSubmitBusy(elements.whiteboardVideoForm, true);
  const sourceDocumentId = state.activeDocument;
  const sourceWorkspaceKind = state.workspaceKind;
  const sourceWorkspacePath = state.settings.workspacePath;
  const initialCandidateKey = whiteboardCandidateKey(nodeId, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
  const cancelSubmissionFeedback = () => cancelWhiteboardSubmissionFeedback(initialCandidateKey, {
    workspacePath: sourceWorkspacePath,
    documentId: sourceDocumentId,
  });
  let submissionAttemptId = "";
  try {
    const submissionFeedback = beginWhiteboardSubmissionFeedback({
      nodeId,
      workspacePath: sourceWorkspacePath,
      documentId: sourceDocumentId,
      channel: "video",
      prompt: rawPrompt,
    });
    submissionAttemptId = submissionFeedback.submissionAttemptId;
    elements.whiteboardVideoDialog.close();
    const connectionId = String(formData.get("connectionId") ?? "");
    const selectedModel = String(formData.get("model") ?? "").trim();
    const videoSettings = currentVideoGenerationSettings(connectionId, selectedModel);
    if (!(await ensureDreaminaGenerationAccountAvailable(videoSettings, { channel: "video" }))) {
      cancelSubmissionFeedback();
      finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
      return;
    }
    const requestedAspectRatio = String(formData.get("aspectRatio") ?? "auto");
    const generationMode = String(formData.get("generationMode") || "smart_params");
    const frameCount = whiteboardVideoFrameNodes().length;
    const multiframeTransitions = normalizeSmartMultiframeTransitions(formData.get("multiframeTransitions"), {
      frameCount,
      defaultDuration: Number(formData.get("duration")) || 4,
    });
    const prompt = generationMode === "smart_multiframe"
      ? compileSmartMultiframePrompt(multiframeTransitions, { frameCount, defaultDuration: Number(formData.get("duration")) || 4 })
      : rawPrompt;
    const generateAudio = String(formData.get("generateAudio") || "true") !== "false";
    const videoCount = [1, 2, 3, 4].includes(Number(formData.get("videoCount"))) ? Number(formData.get("videoCount")) : 1;
    const includeTarget = formData.get("includeTargetReference") === "true";
    try {
      await hydrateWhiteboardWebReferences(nodeId, { includeTarget });
  } catch (error) {
    cancelSubmissionFeedback();
    showToast(`网页资料读取失败，未开始生成：${error.message}`);
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    return;
  }
  const referenceOrder = String(formData.get("referenceOrder") ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  const promptReferenceSequence = String(formData.get("promptReferenceSequence") ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  const generationContext = whiteboardGenerationContext(nodeId, String(formData.get("explicitReferences") ?? "").split(",").filter(Boolean), prompt, {
    includeTarget,
    referenceOrder,
  });
  const { upstream } = generationContext;
  let allModelAttachments = generationContext.modelAttachments;
  if (generationMode === "smart_edit") allModelAttachments = await hydrateWhiteboardSmartEditReferences(allModelAttachments);
  const modelAttachments = videoReferencesForGenerationMode(allModelAttachments, generationMode);
  const referencePlan = whiteboardMediaReferencePlan({ channel: "video", settings: videoSettings, modelAttachments, generationMode });
  const capabilities = videoModelCapabilitiesForProfile(videoSettings, videoSettings?.model);
  const aspectRatio = whiteboardResolvedAspectRatio({
    requestedRatio: requestedAspectRatio,
    nodeId,
    prompt: `${prompt}\n${upstream.map(whiteboardNodeSummary).join("\n")}`,
    channel: "video",
    allowedRatios: capabilities.aspectRatios,
    includeTarget: generationContext.targetIsInput,
  });
  if (generationMode === "smart_multiframe" && frameCount < 2) {
    cancelSubmissionFeedback();
    showToast("智能多帧至少需要 2 张图片；请先补齐参考帧，未提交计费任务");
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    return;
  }
  if (!nodeId || !prompt || !videoSettings) {
    cancelSubmissionFeedback();
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    return;
  }
  if (!checkWhiteboardReferenceCapacity(activeWhiteboardDocument()?.canvas, [nodeId], {
    channel: "video",
    settings: videoSettings,
    operation: "generate",
    includeTargetMedia: generationContext.targetIsInput,
  }).ok || !preflightWhiteboardMediaSubmission({ referencePlan, generationContext, prompt })) {
    cancelSubmissionFeedback();
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    return;
  }
  const previousGenerationJobId = String(whiteboardCandidateFor(nodeId, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId })?.jobId
    || whiteboardNodeById(nodeId)?.generation?.jobId
    || "");
  let pendingApplyCount = 0;
  const beforeCanvas = whiteboardCanvasSnapshot(state.documents[sourceDocumentId]?.canvas);
  // Keep model choice scoped to this job so a VIP/alternate generation does
  // not mutate the tested connection profile or invalidate its probe evidence.
  setWhiteboardVideoSettingsPanelOpen(false);
  updateWhiteboardGenerationCandidate(initialCandidateKey, { prompt });
  try {
    const effectivePrompt = await buildWhiteboardMediaProviderPrompt({ prompt, channel: "video", generationContext, referencePlan });
    if (generationMode === "long_video") {
      const duration = Number(formData.get("duration"));
      const manifest = {
        ...createCompositeLongVideoManifest({
        id: uid("long-video"),
        cardId: nodeId,
        duration,
        prompt: effectivePrompt,
        globalBible: `画幅 ${aspectRatio}；模型 ${videoSettings.model}；保持用户原始参考物中的人物身份、服装、场景、道具、光线、色彩与镜头风格。`,
        references: referencePlan.directReferences,
        providerPromptReferenceTokens: whiteboardGenerationProviderReferenceTokens(generationContext),
        settings: {
          connectionId: videoSettings.connectionId || videoSettings.id || connectionId,
          model: videoSettings.model,
          aspectRatio,
          resolution: String(formData.get("resolution") || "720p"),
          generateAudio,
        },
        }),
        interactionStartedAt: new Date(submissionFeedback.startedAt || Date.now()).toISOString(),
      };
      saveCompositeLongVideoManifest(nodeId, manifest);
      await runCompositeLongVideoManifest({
        nodeId,
        manifest,
        workspaceKind: sourceWorkspaceKind,
        workspacePath: sourceWorkspacePath,
        documentId: sourceDocumentId,
        beforeCanvas,
        onFirstJobCreated: () => finishWhiteboardMediaSubmissionAttempt({
          key: submissionLockKey,
          token: submissionLockToken,
          channel: "video",
          form: elements.whiteboardVideoForm,
        }),
      });
      return;
    }
    const targetNodeIds = materializeWhiteboardVideoGenerationTargets(nodeId, videoCount, {
      documentId: sourceDocumentId,
      workspacePath: sourceWorkspacePath,
    });
    if (targetNodeIds.length !== videoCount) throw new Error("无法建立全部视频生成目标卡片");
    const batchStartedAt = Number(ui.whiteboardCandidates.get(initialCandidateKey)?.startedAt) || Date.now();
    targetNodeIds.slice(1).forEach((targetNodeId) => beginWhiteboardGenerationCandidate({
      nodeId: targetNodeId,
      workspacePath: sourceWorkspacePath,
      documentId: sourceDocumentId,
      channel: "video",
      text: "",
      kind: "video",
      prompt,
      createdAt: batchStartedAt,
      startedAt: batchStartedAt,
    }));
    renderWhiteboard(activeWhiteboardDocument());
    const results = await Promise.all(targetNodeIds.map(async (targetNodeId, index) => {
      const candidateKey = whiteboardCandidateKey(targetNodeId, { workspacePath: sourceWorkspacePath, documentId: sourceDocumentId });
      let durableJob = null;
      try {
        updateWhiteboardGenerationCandidate(candidateKey, { progressPercent: 24 });
        durableJob = await createWhiteboardMediaGenerationJob({
          channel: "video",
          target: whiteboardGenerationJobTarget({ workspaceKind: sourceWorkspaceKind, workspacePath: sourceWorkspacePath, documentId: sourceDocumentId, nodeId: targetNodeId }),
          forceNewGeneration: true,
          regenerationOfJobId: targetNodeId === nodeId ? previousGenerationJobId : "",
      request: {
        interactionStartedAt: new Date(submissionFeedback.startedAt || Date.now()).toISOString(),
        prompt: effectivePrompt,
        displayPrompt: prompt,
        providerPromptReferenceTokens: whiteboardGenerationProviderReferenceTokens(generationContext),
        referenceOrder,
        promptReferenceSequence,
        settings: { ...videoSettings, workspacePath: sourceWorkspacePath },
        generationProfile: whiteboardGenerationProfileFromSettings(videoSettings, "chat"),
            aspectRatio,
            generationMode,
            duration: generationMode === "smart_multiframe" && multiframeTransitions.length === 1
              ? multiframeTransitions[0].duration
              : Number(formData.get("duration")),
            resolution: formData.get("resolution"),
            generateAudio,
            videoCount,
            batchIndex: index + 1,
            referenceMedia: referencePlan.directReferences,
            multiframeTransitions,
            multiframeDuration: generationMode === "smart_multiframe"
              ? smartMultiframeDurationTotal(multiframeTransitions, { frameCount })
              : 0,
          },
        });
        updateWhiteboardGenerationCandidate(candidateKey, {
          jobId: durableJob.id,
          status: durableJob.status,
          providerStatus: durableJob.providerStatus,
          model: String(durableJob.request?.settings?.model || durableJob.settings?.model || videoSettings?.model || ""),
          providerTaskId: durableJob.providerTaskId,
          submissionState: durableJob.submissionState,
          submittedAt: durableJob.submittedAt,
          progressPercent: durableJob.progressPercent,
        });
        if (targetNodeId === nodeId) {
          finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
        }
        durableJob = await waitForWhiteboardGenerationJob(durableJob.id, candidateKey);
        if (durableJob.status !== "complete") throw new Error(mediaGenerationErrorText(durableJob) || "视频生成失败");
        if (!whiteboardCandidateBelongsToJob(candidateKey, durableJob.id)) return { ok: false, replaced: true, targetNodeId };
        await applyCompletedWhiteboardGenerationJob(durableJob, {
          beforeCanvas: whiteboardCanvasSnapshot(state.documents[sourceDocumentId]?.canvas ?? beforeCanvas),
        });
        return { ok: true, targetNodeId };
      } catch (error) {
        const ownsCandidate = durableJob
          ? whiteboardCandidateBelongsToJob(candidateKey, durableJob.id)
          : Boolean(ui.whiteboardCandidates.get(candidateKey) && !ui.whiteboardCandidates.get(candidateKey)?.jobId);
        if (!ownsCandidate) return { ok: false, replaced: true, targetNodeId };
        const providerCompleted = durableJob?.status === "complete";
        const interruptedJob = durableJob
          ? providerCompleted
            ? completedWhiteboardApplyPendingJob(durableJob, error)
            : { ...durableJob, error: durableJob.error || error.message }
          : null;
        stopWhiteboardGenerationCandidate(candidateKey, { remove: !whiteboardMediaJobHoldsCard(interruptedJob) });
        if (interruptedJob) showInterruptedWhiteboardGenerationJob(interruptedJob);
        if (providerCompleted) retryCompletedWhiteboardGenerationApply(durableJob, {
          beforeCanvas: whiteboardCanvasSnapshot(state.documents[sourceDocumentId]?.canvas ?? beforeCanvas),
        });
        return {
          ok: providerCompleted,
          pendingApply: providerCompleted,
          targetNodeId,
          error: error.message,
          requiresAccountVerification: dreaminaFailureNeedsVerification({ error, job: durableJob }),
          verificationResolution: dreaminaFailureDiagnosis(dreaminaFailureInput({ error, job: durableJob })).resolution,
        };
      }
    }));
    if (state.activeDocument === sourceDocumentId && normalizedWorkspacePath(state.settings.workspacePath) === normalizedWorkspacePath(sourceWorkspacePath)) {
      renderWhiteboard(activeWhiteboardDocument());
    }
    const activeResults = results.filter((result) => !result.replaced);
    if (!activeResults.length) return;
    const completed = activeResults.filter((result) => result.ok).length;
    const failed = activeResults.length - completed;
    const pendingApply = activeResults.filter((result) => result.pendingApply).length;
    pendingApplyCount = pendingApply;
    const background = normalizedWorkspacePath(sourceWorkspacePath) !== normalizedWorkspacePath(state.settings.workspacePath);
    const requiresAccountVerification = activeResults.some((result) => result.requiresAccountVerification);
    if (requiresAccountVerification) {
      openDreaminaReverifyDialog({ settings: videoSettings });
      showToast(`即梦视频账号需要核验。${activeResults.find((result) => result.requiresAccountVerification)?.verificationResolution || "核验完成后可点击“找回结果”。"}`);
    } else if (pendingApply && !failed) showToast(`${pendingApply} 个视频已生成，正在自动重试写入卡片；不会重复提交或扣费`);
    else if (completed && !failed) showToast(background
      ? `${completed} 个视频已生成并保存到发起任务的原白板`
      : `${completed} 个视频已生成并读取 ${upstream.length} 个上游节点，${requestedAspectRatio === "auto" ? "自适应画幅" : "画幅"}为 ${aspectRatio}`);
    else if (completed) showToast(`已完成 ${completed} 个视频，${failed} 个未完成：${activeResults.find((result) => !result.ok)?.error || "请重试"}`);
    else showToast(`视频生成失败：${activeResults[0]?.error || "请重试"}`);
  } catch (error) {
    if (submissionAttemptId
      && ui.whiteboardCandidates.get(initialCandidateKey)?.submissionAttemptId !== submissionAttemptId) return;
    stopWhiteboardGenerationCandidate(initialCandidateKey, { remove: true });
    if (state.activeDocument === sourceDocumentId && state.settings.workspacePath === sourceWorkspacePath) renderWhiteboard(activeWhiteboardDocument());
    if (dreaminaFailureNeedsVerification({ error })) {
      const failure = dreaminaFailureDiagnosis(dreaminaFailureInput({ error }));
      openDreaminaReverifyDialog({ settings: videoSettings });
      showToast(`即梦视频账号需要核验。${failure.resolution}`);
      return;
    }
    if (String(error?.code || "").toUpperCase() === "DREAMINA_PROFILE_SWITCH_BLOCKED") {
      openDreaminaProfileLockDialog(error.details || {});
    } else showToast(`视频生成失败：${error.message}`);
  } finally {
    persist();
    if (pendingApplyCount === 0) {
      finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    }
  }
  } catch (error) {
    cancelSubmissionFeedback();
    finishWhiteboardMediaSubmissionAttempt({ key: submissionLockKey, token: submissionLockToken, channel: "video", form: elements.whiteboardVideoForm });
    showToast(`视频生成未开始：${error?.message || "提交前检查失败，请重试"}`);
  }
});

