    const target = clone(explicitTarget || (agentPureReview ? safeAgentReviewFallback : anchoredAgentIntentTarget || { documentId: boundDocumentId }));
    if (agentPureReview && agentReviewScopeDocumentIds.length) target.reviewScopeDocumentIds = [...agentReviewScopeDocumentIds];
