    target.moduleId ||= inTaskWorkspace(() => moduleForDocument(target.documentId));
    if (agentCreativeMutationPlan?.primaryTargets?.length) target.creativeMutationPlan = clone(agentCreativeMutationPlan);
    const agentAssociationSnapshot = Object.freeze({ ...createTurnContextSnapshot({
      conversation,
      workspaceKind: submittedTaskContextSnapshot.workspaceKind,
      workspacePath: submittedTaskContextSnapshot.workspacePath,
      workspaceName: submittedTaskContextSnapshot.workspaceName,
      activeDocumentId: submittedTaskContextSnapshot.activeDocumentId,
      documents: taskWorkspaceSourceState.documents,
    }), ...submittedTaskContextSnapshot,
      boundDocumentId,
      associationEnabled: requestsCurrentDocument(prompt),
    });
    const associationScopedPriorMessages = conversationMessagesForActiveAssociation([
      ...(conversation.messages ?? taskWorkspaceSourceState.messages ?? []),
      { id: "current-agent-association", role: "user", content: prompt, turnContextSnapshot: agentAssociationSnapshot },
    ]).slice(0, -1);
    const previousUserMessage = [...associationScopedPriorMessages]
      .reverse()
      .find((message) => message.role === "user");
    const previousAssistantMessage = [...associationScopedPriorMessages]
      .reverse()
      .find((message) => message.role === "assistant");
    const activeReferenceScope = ensureConversationReferenceContext(conversation);
    const composerMessageReferenceScope = conversationComposerReferenceScope(conversation);
