      landing: agentGenerationAndLandingRequested || agentLandingOnlyRequested,
      targetDocumentId: target.documentId,
      target: { ...target, revision: agentExpectedRevisions[target.documentId] || "", title: taskWorkspaceSourceState.documents[target.documentId]?.title || target.title || "" },
      targetDocumentIds: agentAuthorizationTargetIds,
      expectedRevisions: agentExpectedRevisions,
      targetExists: Boolean(taskWorkspaceSourceState.documents[target.documentId]),
      targetTitle: taskWorkspaceSourceState.documents[target.documentId]?.title || target.title || "",
      targetModuleId: target.moduleId,
      contextDomain: target.contextDomain || inTaskWorkspace(() => documentContextDomain(target.documentId)),
      hasResources,
      continuesCreativeThread,
      preparedCreativeContext: inTaskWorkspace(() => preparedNovelProductionContext(target)),
