document.querySelector('[data-agent-permission-surface="quick"]')?.addEventListener("click", async (event) => {
  const button = event.target.closest("[data-agent-permission-mode]");
  if (!button) return;
  const previousMode = normalizeAgentPermissionMode(state.settings?.agentPermissionMode);
  const nextMode = normalizeAgentPermissionMode(button.dataset.agentPermissionMode);
  document.querySelector('#conversationPermissionMenu').open = false;
  if (nextMode === previousMode) return;
  const buttons = [...document.querySelectorAll('[data-agent-permission-surface="quick"] [data-agent-permission-mode]')];
  buttons.forEach((item) => { item.disabled = true; });
  state.settings = { ...state.settings, agentPermissionMode: nextMode };
  persist();
  renderQuickModelSelector();
  try {
    ui.codexAgent.status = await requestAgentPermissionModeStatus(nextMode);
    renderCodexAgentPanel();
    showToast(`已切换为“${agentPermissionModeInfo(nextMode).label}”；仅影响新任务`);
  } catch (error) {
    state.settings = { ...state.settings, agentPermissionMode: previousMode };
    persist();
    renderQuickModelSelector();
    showToast(error.message || "Agent 权限档位切换失败");
  } finally {
    buttons.forEach((item) => { item.disabled = false; });
  }
});

elements.quickAgentEngine?.addEventListener("change", async (event) => {
  const requestedProfileId = String(event.target.value || "");
  try {
    const profile = exactAgentTextProfile(requestedProfileId);
    if (!profile) throw new Error("所选 Agent 配置不存在");
    const engine = agentEngineForTextProfile(profile);
    if (!engine) throw new Error("所选配置没有可执行的 Agent 运行器");
    state.settings = { ...state.settings, activeTextAgentConnectionId: profile.id };
    persist();
    renderQuickModelSelector();
    activeAgentProfileSwitchPromise = (async () => {
      if (activeAgentEngine() === engine) return;
      const response = await fetch("/api/codex-agent/engine", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ engine }),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw new Error(payload.message || "Agent 配置切换失败");
      if (String(state.settings.activeTextAgentConnectionId || "") !== requestedProfileId) return;
      ui.codexAgent.status = payload;
      if (payload.provider === "codex_agent") await ensureCodexAgentProject();
      renderCodexAgentPanel();
      renderQuickModelSelector();
    })();
    await activeAgentProfileSwitchPromise;
    if (String(state.settings.activeTextAgentConnectionId || "") !== requestedProfileId) return;
    void hydrateAgentProfileModelCatalog(profile)
      .then(() => {
        if (String(state.settings.activeTextAgentConnectionId || "") === requestedProfileId) renderQuickModelSelector();
      })
      .catch((error) => {
        if (String(state.settings.activeTextAgentConnectionId || "") === requestedProfileId) showToast(error.message || "Agent 模型目录读取失败");
      });
    schedulePublicTextConnectionVerification(activeAgentTextProfile(state.settings), {
      scope: "quick-agent",
      executionSurface: "agent",
      currentProfile: () => activeAgentTextProfile(state.settings),
    });
  } catch (error) {
    if (String(state.settings.activeTextAgentConnectionId || "") !== requestedProfileId
      || String(elements.quickAgentEngine?.value || "") !== requestedProfileId) return;
    showToast(error.message || "Agent 引擎切换失败");
    await refreshCodexAgentStatus();
  }
});

