  if (interactionButton && interactionCard) {
    void resolveCodexAgentInteraction({ card: interactionCard, action: interactionButton.dataset.codexInteractionAction, button: interactionButton });
    return;
  }
  const button = event.target.closest("[data-codex-decision]");
