elements.mediaAssetMenu.addEventListener("click", async (event) => {
  const action = event.target.closest("[data-media-asset-action]")?.dataset.mediaAssetAction;
  const context = ui.mediaAssetContext;
  elements.mediaAssetMenu.hidden = true;
  ui.mediaAssetContext = null;
  if (!action || !context) return;
  if (action === "open" && context.relativePath) {
    await openWorkspaceMediaFile(context.relativePath);
    return;
  }
  if (action === "reveal") {
    const revealPath = context.revealRelativePath || context.relativePath;
    await revealWorkspaceTarget(revealPath
      ? { workspacePath: context.workspacePath, workspaceKind: context.workspaceKind, documentId: context.documentId, relativePath: revealPath }
      : { workspacePath: context.workspacePath, workspaceKind: context.workspaceKind, documentId: context.documentId });
    return;
  }
  if (!context.assetId && action === "copy" && context.kind === "image") {
    await copyWhiteboardImageAttachment({ relativePath: context.relativePath, workspacePath: context.workspacePath, documentId: context.documentId });
    return;
  }
  if (!context.assetId && action === "save" && context.kind) {
    const name = String(context.relativePath || "").split(/[\\/]/).at(-1) || `白板${context.kind}`;
    await saveWhiteboardMedia({ relativePath: context.relativePath, name, kind: context.kind, downloadName: context.downloadName, workspacePath: context.workspacePath, documentId: context.documentId });
    return;
  }
  if (context.assetId) {
    if (context.historyNodeId) {
      if (action === "delete") deleteWhiteboardCardHistoryVersion(context.assetId);
      else if (action === "save" && context.kind) {
        const asset = whiteboardCardHistoryModel(context.historyNodeId).find((entry) => entry.id === context.assetId);
        if (asset) await exportWhiteboardAsset(asset);
      }
      return;
    }
    elements.whiteboardAssetList
      ?.querySelector(`[data-whiteboard-asset="${CSS.escape(context.assetId)}"] [data-whiteboard-asset-action="${CSS.escape(action)}"]`)
      ?.click();
  }
});

