elements.chatFeed.addEventListener("contextmenu", (event) => {
  const media = event.target.closest("[data-generated-media-path]");
  const relativePath = media?.dataset.generatedMediaPath;
  const downloadName = media?.dataset.generatedMediaDownloadName || "";
  const revealRelativePath = media?.dataset.mediaBatchDirectory || "";
  const revealKind = media?.dataset.mediaDirectoryKind || "";
  if (openMediaAssetContextMenu(event, relativePath, { downloadName, revealRelativePath, revealKind })) return;
  const selectedText = selectedChatMessageText(event.target.closest("[data-message]")?.dataset.message || "");
  if (selectedText) showReadOnlySelectionContextMenu(event, selectedText);
});

const rememberExecutionProcessDisclosure = (process, disclosureState) => {
  if (!process?.classList.contains("execution-process")) return false;
  const messageId = process.closest("[data-message]")?.dataset.message || "";
  const message = state.messages.find((entry) => entry.id === messageId);
  if (!message?.execution) return false;
  const normalizedState = disclosureState === "expanded" ? "expanded" : "collapsed";
  process.dataset.disclosureState = normalizedState;
  if (message.execution.processDisclosure === normalizedState) return true;
  message.execution = { ...message.execution, processDisclosure: normalizedState };
  persist();
  return true;
};

elements.chatFeed.addEventListener("toggle", (event) => {
  const process = event.target;
  if (!process?.classList?.contains("execution-process")) return;
  const disclosureState = process.open ? "expanded" : "collapsed";
  if (process.dataset.disclosureState === disclosureState) return;
  rememberExecutionProcessDisclosure(process, disclosureState);
}, true);

elements.chatFeed.addEventListener("click", (event) => {
  if (!ui.conversationPreview) return;
  event.stopImmediatePropagation();
  if (event.target.closest("[data-close-history-preview]")) closeConversationPreview();
  else if (event.target.closest("[data-jump-history-owner]")) void jumpToConversationOwner();
}, true);

elements.chatFeed.addEventListener("click", async (event) => {
  const landedDocumentButton = event.target.closest("[data-open-landed-document]");
  const landedDocumentId = landedDocumentButton?.dataset.openLandedDocument;
  if (landedDocumentId) {
    event.preventDefault();
    try {
    const targetWorkspaceKind = landedDocumentButton.dataset.landedWorkspaceKind === "notebook" ? "notebook" : "project";
    const targetWorkspacePath = String(landedDocumentButton.dataset.landedWorkspacePath || "");
    const targetWorkspaceName = String(landedDocumentButton.dataset.landedWorkspaceName || "");
    const sameWorkspace = targetWorkspaceKind === state.workspaceKind
      && (!targetWorkspacePath || normalizedWorkspacePath(targetWorkspacePath) === normalizedWorkspacePath(state.settings.workspacePath));
    if (!sameWorkspace && targetWorkspacePath) {
      const switched = await (targetWorkspaceKind === "notebook"
        ? switchNotebook({ workspacePath: targetWorkspacePath, name: targetWorkspaceName })
        : switchProject({ workspacePath: targetWorkspacePath, name: targetWorkspaceName }));
      if (!switched) return;
    }
    if (!await refreshVerifiedAgentDocuments([landedDocumentId])) return;
    if (!state.documents[landedDocumentId]) {
      showToast(`已切换到目标${targetWorkspaceKind === "notebook" ? "笔记本" : "作品"}，但未找到该文档，请刷新后重试`);
      return;
    }
    selectDocument(landedDocumentId);
    if (state.activeDocument !== landedDocumentId) throw new Error("目标文档定位失败");
    } catch (error) { showToast(`打开已写入文档失败：${error.message}`); }
    return;
  }
  const olderMessagesButton = event.target.closest("[data-load-older-messages]");
  if (olderMessagesButton) {
    event.preventDefault();
    const conversationKey = `${workspaceIdentity()}::${activeConversation()?.id || state.activeConversationId || ""}`;
    touchBoundedMap(
      ui.chatFeedWindowLimits,
      conversationKey,
      Number(olderMessagesButton.dataset.loadOlderMessages) || DEFAULT_CONVERSATION_DISPLAY_LIMIT,
      CHAT_FEED_WINDOW_CACHE_LIMIT,
    );
    renderMessages();
    return;
  }
  const messageContentToggle = event.target.closest("[data-toggle-message-content]");
  if (messageContentToggle) {
    event.preventDefault();
    const messageId = messageContentToggle.dataset.toggleMessageContent;
    const expanded = !ui.expandedMessageIds.has(messageId);
    if (expanded) ui.expandedMessageIds.add(messageId);
    else ui.expandedMessageIds.delete(messageId);
    const content = messageContentToggle.closest(".message")?.querySelector(".message-collapsible-content");
    content?.classList.toggle("is-expanded", expanded);
    messageContentToggle.setAttribute("aria-expanded", String(expanded));
    messageContentToggle.textContent = uiText(expanded ? "收起全文" : "展开全文");
    return;
  }
  const codexApprovalButton = event.target.closest("[data-agent-task-details] [data-codex-decision]");
  if (codexApprovalButton) {
    event.preventDefault();
    event.stopPropagation();
    const card = codexApprovalButton.closest("[data-codex-approval]");
    await resolveCodexAgentApproval({
      id: card?.dataset.codexApproval || "",
      decision: codexApprovalButton.dataset.codexDecision || "",
      button: codexApprovalButton,
    });
    return;
  }
  const cancelPreparation = event.target.closest("[data-cancel-preparation]")?.dataset.cancelPreparation;
  if (cancelPreparation) {
    event.preventDefault();
    event.stopPropagation();
    await stopCodexAgentTurn("", cancelPreparation);
    return;
  }
  const stopCodexTurn = event.target.closest("[data-stop-codex-turn]")?.dataset.stopCodexTurn;
  if (stopCodexTurn) {
    event.preventDefault();
    await stopCodexAgentTurn(stopCodexTurn);
    return;
  }
  const undoCodexTurn = event.target.closest("[data-codex-undo-turn]")?.dataset.codexUndoTurn;
  if (undoCodexTurn) {
    event.preventDefault();
    await undoCodexAgentTurn(undoCodexTurn);
    return;
  }
  const backgroundRun = event.target.closest("[data-background-run]");
  if (backgroundRun) {
    event.preventDefault();
    const process = backgroundRun.closest(".execution-process");
    if (process) {
      rememberExecutionProcessDisclosure(process, "collapsed");
      process.open = false;
    }
    showToast("任务已转入后台等待；安全候选与心跳会继续保存，可随时回来查看。");
    return;
  }
  const candidateHistoryToggle = event.target.closest("[data-candidate-history]");
  if (candidateHistoryToggle) {
    event.preventDefault();
    const messageElement = candidateHistoryToggle.closest("[data-message]");
    const message = state.messages.find((entry) => entry.id === messageElement?.dataset.message);
    if (!message?.candidateHistory?.length) return;
    const existing = messageElement.querySelector(".candidate-history-panel");
    if (existing) {
      existing.remove();
      return;
    }
    const panel = document.createElement("div");
    panel.className = "candidate-history-panel";
    panel.innerHTML = message.candidateHistory.map((entry, index) => `<div class="candidate-history-item">
      <div class="candidate-history-item-header"><strong>历史版本 ${message.candidateHistory.length - index}</strong><span>${escapeHtml(entry.time || "")}</span></div>
      <div class="candidate-history-item-copy">${proseToHtml(entry.text)}</div>
      <button class="secondary-button compact" type="button" data-restore-candidate-history="${escapeHtml(message.id)}" data-restore-index="${index}">恢复此版本</button>
    </div>`).join("");
    candidateHistoryToggle.after(panel);
    return;
  }
  const restoreCandidateHistory = event.target.closest("[data-restore-candidate-history]");
  if (restoreCandidateHistory) {
    event.preventDefault();
    const messageElement = restoreCandidateHistory.closest("[data-message]");
    const message = state.messages.find((entry) => entry.id === messageElement?.dataset.message);
    const index = Number(restoreCandidateHistory.dataset.restoreIndex);
    const entry = message?.candidateHistory?.[index];
    if (!entry) return;
    message.candidateHistory ??= [];
    message.candidateHistory.unshift({
      text: message.candidate,
      target: clone(message.target ?? null),
      time: `今天 ${nowTime()}`,
      requestId: message.execution?.requestId ?? "",
    });
    message.candidateHistory.splice(index + 1, 1);
    message.candidate = entry.text;
    if (entry.target) message.target = clone(entry.target);
    persist();
    renderMessages();
    showToast("已恢复历史版本；当前候选已存入历史");
    return;
  }
  const generationAttemptAction = event.target.closest("[data-generation-attempt-action][data-generation-attempt-id]");
  if (generationAttemptAction) {
    event.preventDefault();
    const messageElement = generationAttemptAction.closest("[data-message]");
    const message = state.messages.find((entry) => entry.id === messageElement?.dataset.message);
    generationAttemptAction.disabled = true;
    try {
      await handleGenerationAttemptAction({
        message,
        action: generationAttemptAction.dataset.generationAttemptAction,
        requestId: generationAttemptAction.dataset.generationAttemptId,
      });
    } catch (error) {
      showToast(error.message || "正文任务操作失败");
    } finally {
      if (generationAttemptAction.isConnected) generationAttemptAction.disabled = false;
    }
    return;
  }
  const mediaAction = event.target.closest("[data-media-job-action][data-media-job-id]");
  if (mediaAction) {
    event.preventDefault();
    event.stopPropagation();
    mediaAction.disabled = true;
    try {
      await handleMediaGenerationActionElement(mediaAction);
    } catch (error) {
      showToast(error.message || uiText("媒体任务操作失败"));
      const current = await fetchWhiteboardGenerationJob(mediaAction.dataset.mediaJobId).catch(() => null);
      if (current) updateMediaJobTargetAfterAction(current);
    } finally {
      if (mediaAction.isConnected) mediaAction.disabled = false;
    }
    return;
  }
  const generatedMediaPreview = event.target.closest(".generated-image-preview[data-attachment-preview]");
  if (generatedMediaPreview) {
    if (event.target.closest("video") && generatedMediaPreview.classList.contains("generated-video-preview")) return;
    event.stopPropagation();
    openAttachmentPreview(generatedMediaPreview);
    return;
  }
  const insertGeneratedMedia = event.target.closest("[data-insert-generated-media]")?.dataset.insertGeneratedMedia;
  if (insertGeneratedMedia) {
    const attachment = state.messages.flatMap((message) => [...(message.generatedImages ?? []), ...(message.generatedVideos ?? [])]).find((item) => item.relativePath === insertGeneratedMedia);
    if (attachment) insertMediaAttachmentAtEditor(attachment);
    return;
  }
  const generatedMedia = event.target.closest("[data-reveal-generated-media]")?.dataset.revealGeneratedMedia;
  if (generatedMedia) {
    revealWorkspaceTarget({ relativePath: generatedMedia });
    return;
  }
  const applyPlan = event.target.closest("[data-apply-workspace-plan]")?.dataset.applyWorkspacePlan;
  if (applyPlan) {
    applyWorkspaceOperationPlan(applyPlan);
    return;
  }
  const cancelPlan = event.target.closest("[data-cancel-workspace-plan]")?.dataset.cancelWorkspacePlan;
  if (cancelPlan) {
    cancelWorkspaceOperationPlan(cancelPlan);
    return;
  }
  const resumeJob = event.target.closest("[data-resume-job]")?.dataset.resumeJob;
  if (resumeJob) {
    const job = (state.longFormJobs ?? []).find((item) => item.id === resumeJob);
    if (!job || !["paused", "failed"].includes(job.status)) return;
    sendMessage("继续长篇自动任务");
    return;
  }
  const cancelRun = event.target.closest("[data-cancel-run]")?.dataset.cancelRun;
  if (cancelRun) {
    cancelConversationRun(cancelRun);
    return;
  }
  const supplementQueued = event.target.closest("[data-supplement-queued]")?.dataset.supplementQueued;
  if (supplementQueued) {
    supplementQueuedMessage(supplementQueued);
    return;
  }
  const editQueued = event.target.closest("[data-edit-queued]")?.dataset.editQueued;
  if (editQueued) {
    const item = activeConversation()?.queue?.find((queued) => queued.id === editQueued);
    if (item?.state === "queued" || !item?.state) {
      item.state = "editing";
      item.leaseId = "";
      item.claimedAt = 0;
      persist();
      renderMessages();
      requestAnimationFrame(() => elements.chatFeed.querySelector(`[data-queued-inline-editor="${CSS.escape(editQueued)}"]`)?.focus());
    }
    return;
  }
  const sendEditedQueued = event.target.closest("[data-send-edited-queued]")?.dataset.sendEditedQueued;
  if (sendEditedQueued) {
    const editor = elements.chatFeed.querySelector(`[data-queued-inline-editor="${CSS.escape(sendEditedQueued)}"]`);
    updateQueuedMessage(sendEditedQueued, editor?.value || "");
    renderMessages();
    return;
  }
  const deleteQueued = event.target.closest("[data-delete-queued]")?.dataset.deleteQueued;
  if (deleteQueued) {
    deleteQueuedMessage(deleteQueued);
    return;
  }
  const messageToCard = event.target.closest("[data-message-to-card]")?.dataset.messageToCard;
  if (messageToCard) {
    addConversationToWhiteboard(messageToCard);
    return;
  }
  const branchSwitch = event.target.closest("[data-switch-answer-branch]");
  if (branchSwitch) {
    switchAnswerBranch(branchSwitch.dataset.switchAnswerBranch, branchSwitch.dataset.branchDirection);
    return;
  }
  const candidateBranchSwitch = event.target.closest("[data-switch-candidate-branch]");
  if (candidateBranchSwitch) {
    switchCandidateDraftBranch(candidateBranchSwitch.dataset.switchCandidateBranch, {
      direction: Number(candidateBranchSwitch.dataset.candidateBranchDirection),
    });
    return;
  }
  const viewCandidateBranches = event.target.closest("[data-view-candidate-branches]");
  if (viewCandidateBranches) {
    openCandidateComparison(viewCandidateBranches.dataset.viewCandidateBranches);
    return;
  }
  const copy = event.target.closest("[data-copy-message]");
  if (copy) {
    copyMessage(copy.dataset.copyMessage);
    return;
  }
  const edit = event.target.closest("[data-edit-message]");
  if (edit) {
    beginMessageEdit(edit.dataset.editMessage);
    return;
  }
  const cancelEdit = event.target.closest("[data-cancel-message-edit]");
  if (cancelEdit) {
    cancelMessageEdit();
    return;
  }
  const rollback = event.target.closest("[data-rollback]");
  if (rollback) {
    await stopConversationTaskForSourceMessage(rollback.dataset.rollback);
    await rollbackToMessage(rollback.dataset.rollback);
  }
});

