root.addEventListener("click", (event) => {
  const frameTrigger = event.target.closest("[data-video-frame-trigger]");
  if (frameTrigger) {
    openVideoFrameMenu(event, frameTrigger);
    return;
  }
  if (event.target.closest("[data-remove-attachment], #attachmentPreviewDialog")) return;
  const preview = event.target.closest("[data-attachment-preview]");
  if (!preview) return;
  const whiteboardCard = preview.closest("[data-canvas-node]");
  const explicitFullscreen = preview.matches("button[data-attachment-fullscreen='true']");
  if (whiteboardCard && !explicitFullscreen) return;
  openAttachmentPreview(preview);
});

