const supplementDirectInstruction = async () => {
  const content = String(elements.chatInput.value || "").trim();
  if (!content) {
    showToast("请输入补充指令内容");
    return;
  }
  const pending = runningConversationMessage();
  const conversation = activeConversation();
  const liveTarget = conversationHasLiveSupplementTarget(conversation);
  if (!liveTarget) {
    elements.chatForm.requestSubmit();
    return;
  }
  const supplementButton = document.querySelector("#supplementButton");
  if (supplementButton) supplementButton.disabled = true;
  try {
    const queuedItem = enqueueMessage(content, {
      executionSurface: pending?.execution?.strength === "agent" || ui.codexAgent.status?.provider === "codex_agent" ? "agent" : "chat",
      conversationId: conversation?.id || "",
      runtimeSupplement: true,
      supplementTargetSourceMessageId: pending?.execution?.sourceMessageId || "",
      silent: true,
    });
    if (!queuedItem) return;
    elements.chatInput.value = "";
    clearActiveComposerDraft();
    if (pending) {
      await supplementQueuedMessage(queuedItem.id);
    } else {
      queuedItem.supplementDeferred = true;
      persist();
      renderMessages();
      showToast("补充要求已绑定正在准备的任务，将在下一安全边界生效");
    }
  } catch (error) {
    showToast(error.message || "补充指令失败");
  } finally {
    if (supplementButton) supplementButton.disabled = false;
  }
};

document.querySelector("#supplementButton")?.addEventListener("click", () => {
  if (ui.conversationPreview) return;
  void supplementDirectInstruction();
});

const syncSupplementButtonVisibility = () => {
  const supplementButton = document.querySelector("#supplementButton");
  if (!supplementButton) return;
  const conversation = activeConversation();
  const liveTarget = conversationHasLiveSupplementTarget(conversation);
  supplementButton.hidden = false;
  supplementButton.title = liveTarget
    ? "补充当前任务；不会中断正在进行的工作"
    : "当前没有进行中的任务；点击后作为新指令发送";
  supplementButton.setAttribute("aria-label", supplementButton.title);
};

const clearComposerFileDragState = () => elements.chatForm.classList.remove("is-file-dragover");
["dragenter", "dragover"].forEach((eventName) => {
  elements.chatForm.addEventListener(eventName, (event) => {
    if (!composerDataTransferHasFiles(event.dataTransfer)) return;
    event.preventDefault();
    event.stopPropagation();
    if (conversationPreviewBlocksComposerMutation({ notify: false })) {
      if (event.dataTransfer) event.dataTransfer.dropEffect = "none";
      return;
    }
    if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
    elements.chatForm.classList.add("is-file-dragover");
  });
});
elements.chatForm.addEventListener("dragleave", (event) => {
  if (event.relatedTarget && elements.chatForm.contains(event.relatedTarget)) return;
  clearComposerFileDragState();
});
elements.chatForm.addEventListener("drop", async (event) => {
  if (!composerDataTransferHasFiles(event.dataTransfer)) return;
  event.preventDefault();
  event.stopPropagation();
  clearComposerFileDragState();
  if (conversationPreviewBlocksComposerMutation()) return;
  const files = Array.from(event.dataTransfer?.files ?? []);
  if (!files.length || ui.uploadingAttachments) return;
  if (await requestTemporaryNotebookPromotion("attachment", state.activeDocument)) return;
  await addAttachments(files);
  elements.chatInput?.focus({ preventScroll: true });
});
window.addEventListener("dragend", clearComposerFileDragState);
window.addEventListener("drop", clearComposerFileDragState);

