elements.textDialogForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const action = ui.dialogAction;
  const value = (ui.dialogMultiline
    ? document.querySelector("#textDialogTextarea").value
    : document.querySelector("#textDialogInput").value).trim();
  if (!value && action?.type !== "history-version-note") {
    showToast(action?.type === "queue-edit" ? "排队指令不能为空" : "名称不能为空");
    return;
  }
  const createKind = ui.dialogCreateKind;
  const selectedLocation = action?.locations?.find((location) => location.id === document.querySelector("#textDialogLocation").value) ?? null;
  elements.textDialog.close();
  // Detach this submission before awaiting any file operation. A user may
  // immediately open the dialog again; completion of the previous operation
  // must not clear or overwrite the newer dialog's action state.
  ui.dialogAction = null;
  ui.dialogMultiline = false;
  ui.dialogCreateKind = "document";
  if (action?.type === "project-create") await createProject(value);
  if (action?.type === "notebook-create") await createNotebook(value);
  if (action?.type === "project-rename") await renameProject(action.target, value);
  if (action?.type === "notebook-rename") await renameNotebook(action.target, value);
  if (action?.type === "document-create" && createKind === "document") createDocument(value, selectedLocation);
  if (action?.type === "document-create" && createKind === "folder") await createFolder(value, selectedLocation);
  if (action?.type === "document-create" && createKind === "whiteboard") createDocument(value, selectedLocation, { kind: "whiteboard" });
  if (action?.type === "document-rename") renameDocument(action.documentId, value);
  if (action?.type === "folder-rename") await renameFolder(action.folderId, value, action);
  if (action?.type === "conversation-rename") renameConversation(action.conversationId, value);
  if (action?.type === "history-version-name") await updateHistoryVersionMetadata(action.scope, action.versionId, { name: value });
  if (action?.type === "history-version-note") await updateHistoryVersionMetadata(action.scope, action.versionId, { note: value });
  if (action?.type === "queue-edit") updateQueuedMessage(action.queueId, value);
  if (action?.type === "whiteboard-add-web") {
    const url = normalizeWhiteboardUrl(value);
    if (!url) showToast("请输入有效的 HTTP 或 HTTPS 网页地址");
    else {
      try {
        showToast("正在读取网页正文和可进入的详情页…");
        const webSnapshot = await readWhiteboardWebSnapshot(url);
        const nodeId = addWhiteboardCard({
          ...action.context,
          kind: "web",
          url,
          webSnapshot,
          width: 320,
          height: 150,
        });
        if (nodeId) selectWhiteboardNode(nodeId);
        showToast(`网页正文已读取：${webSnapshot.pages?.length || 1} 页，${webSnapshot.contentCharacters || webSnapshot.text.length} 字`);
      } catch (error) {
        showToast(`网页引用失败：${error.message}`);
      }
    }
  }
  if (action?.type === "whiteboard-reference-web") {
    const url = normalizeWhiteboardUrl(value);
    const documentState = activeWhiteboardDocument();
    const node = documentState ? whiteboardNodeById(action.nodeId, documentState) : null;
    if (!url) showToast("请输入有效的 HTTP 或 HTTPS 网页地址");
    else if (node) {
      try {
        showToast("正在读取网页正文和可进入的详情页…");
        const webSnapshot = await readWhiteboardWebSnapshot(url);
        const beforeCanvas = whiteboardCanvasSnapshot(documentState.canvas);
        documentState.canvas = updateCanvasNode(documentState.canvas, action.nodeId, { kind: "web", url, webSnapshot });
        documentState.updatedAt = nowTime();
        pushWhiteboardHistory(beforeCanvas, { label: node.kind === "web" ? "修改网页链接" : "引用网页" });
        persist();
        renderWhiteboard(documentState);
        selectWhiteboardNode(action.nodeId);
        showToast(node.kind === "web" ? "网页链接及正文已更新" : "卡片已引用网页正文");
      } catch (error) {
        showToast(`网页引用失败：${error.message}`);
      }
    }
  }
});

