elements.moveDocumentTree.addEventListener("click", (event) => {
  const targetButton = event.target.closest("[data-move-document-target]");
  if (!targetButton) return;
  event.preventDefault();
  event.stopPropagation();
  const targetKey = targetButton.dataset.moveDocumentTarget;
  if (!ui.documentTransferTargets.has(targetKey)) return;
  elements.moveDocumentTarget.value = targetKey;
  elements.moveDocumentTree.querySelectorAll("[data-move-document-target]").forEach((button) => {
    const selected = button.dataset.moveDocumentTarget === targetKey;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-selected", String(selected));
  });
  updateMoveDocumentTargetSummary(elements.moveDocumentTree.querySelectorAll("[data-move-document-target]").length);
});
elements.moveDocumentTree.addEventListener("toggle", (event) => {
  const branch = event.target.closest?.("[data-move-document-tree-key]");
  if (!branch) return;
  if (branch.open) ui.moveDocumentExpandedKeys.add(branch.dataset.moveDocumentTreeKey);
  else ui.moveDocumentExpandedKeys.delete(branch.dataset.moveDocumentTreeKey);
}, true);

elements.moveDocumentForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const context = ui.moveDocumentContext ? clone(ui.moveDocumentContext) : null;
  const target = selectedMoveDocumentTarget();
  if ((!context?.documentIds?.length && !context?.sourceFolder) || !target) {
    showToast("请选择完整目标位置");
    return;
  }
  elements.moveDocumentSubmit.disabled = true;
  elements.moveDocumentSubmit.textContent = "正在移动…";
  try {
    const payload = await executeDocumentTransfer({
      operation: "move",
      sourceWorkspaceKind: context.sourceWorkspaceKind,
      sourceWorkspacePath: context.sourceWorkspacePath,
      documentIds: context.documentIds,
      sourceFolder: context.sourceFolder,
      containsWhiteboard: context.containsWhiteboard,
      target,
    });
    elements.moveDocumentDialog.close();
    const transferredDocumentId = payload?.transferred?.[0]?.targetDocumentId || "";
    if (context.promotionIntent) resumeTemporaryNotebookIntent(context.promotionIntent, transferredDocumentId);
  } catch (error) {
    showToast(`移动失败：${error.message}`);
    elements.moveDocumentSubmit.disabled = false;
    elements.moveDocumentSubmit.textContent = "确认移动";
  }
});

