const desktopControlBridge = desktopWindowControl();
desktopControlBridge?.onMaximizedChanged?.((maximized) => applyWindowControlState(maximized));
desktopControlBridge?.onFullscreenChanged?.((fullscreen) => {
  if (fullscreen || !elements.workspace.classList.contains("editor-fullscreen-active")) return;
  elements.workspace.classList.remove("editor-fullscreen-active");
  document.querySelector(".app-shell")?.classList.remove("editor-fullscreen-active");
  syncNoteFullscreenState();
});
let desktopClosePreparationActive = false;
desktopControlBridge?.onCloseRequested?.(async () => {
  if (desktopClosePreparationActive) return;
  desktopClosePreparationActive = true;
  const deadline = (promise, milliseconds, fallback) => Promise.race([
    Promise.resolve(promise),
    new Promise((resolveDeadline) => setTimeout(() => resolveDeadline(fallback), milliseconds)),
  ]);
  let saved = false;
  try {
    saved = await deadline(flushWorkspaceSave(), 7_000, false) === true;
    if (!saved) {
      await deadline(flushRecoveryCheckpoint({ keepalive: true }), 2_500, null).catch(() => null);
      showToast("正式保存未及时完成，已保留本地恢复检查点并继续退出");
    }
    await deadline(generationSecretWritePromise, 2_500, null).catch((error) => {
      showToast(`凭证安全存储未及时完成：${error.message}`);
    });
  } finally {
    await desktopControlBridge.confirmClose?.(true);
    desktopClosePreparationActive = false;
  }
});
void syncWindowControlState();
