elements.trashDialog.addEventListener("click", (event) => {
  if (event.target === elements.trashDialog) {
    closeTrashDialog();
    return;
  }
  if (event.target.closest("#clearTrashButton")) {
    const count = allTrashEntries().length;
    if (!count || ui.trashClearing) return;
    ui.trashDeleteId = null;
    ui.trashDeleteAll = true;
    document.querySelector("#trashDeleteCopy").textContent = `回收站中的 ${count} 项将被永久删除，包括其中的历史版本。此操作无法撤销。`;
    elements.trashDeleteDialog.showModal();
    return;
  }
  const toggle = event.target.closest("[data-trash-toggle]");
  if (toggle) {
    const key = toggle.dataset.trashToggle;
    if (ui.trashExpanded.has(key)) ui.trashExpanded.delete(key);
    else ui.trashExpanded.add(key);
    renderTrashDialog();
    return;
  }
  const preview = event.target.closest("[data-trash-preview]");
  if (preview) {
    openTrashPreview(preview.dataset.trashPreview, preview.dataset.trashDocument || null);
    return;
  }
  const restore = event.target.closest("[data-trash-restore]");
  if (restore) {
    restoreTrashDocument(restore.dataset.trashRestore);
    return;
  }
  const remove = event.target.closest("[data-trash-permanent]");
  if (remove) {
    const entry = trashEntryById(remove.dataset.trashPermanent);
    if (!entry) return;
    ui.trashDeleteAll = false;
    ui.trashDeleteId = entry.trashId;
    document.querySelector("#trashDeleteCopy").textContent = entry.kind === "skill"
      ? `“${trashEntryTitle(entry)}”将被永久删除。${entry.recoveryHint || "此 Skill 将无法恢复。"}`
      : entry.kind === "custom-theme"
        ? `“${trashEntryTitle(entry)}”及其全部主题历史将被永久删除，无法恢复。`
      : `“${trashEntryTitle(entry)}”将被永久删除，且无法通过历史版本恢复。`;
    elements.trashDeleteDialog.showModal();
  }
});

elements.trashPreviewDialog.addEventListener("click", (event) => {
  if (event.target === elements.trashPreviewDialog || event.target.closest("#closeTrashPreview")) {
    closeTrashPreview();
    return;
  }
  if (event.target.closest("#restoreTrashPreview") && ui.trashPreview) {
    const { trashId } = ui.trashPreview;
    closeTrashPreview();
    restoreTrashDocument(trashId);
    return;
  }
  if (event.target.closest("#deleteTrashPreview") && ui.trashPreview) {
    const entry = state.trash.find((item) => item.trashId === ui.trashPreview.trashId);
    if (!entry) return;
    ui.trashDeleteAll = false;
    ui.trashDeleteId = entry.trashId;
    document.querySelector("#trashDeleteCopy").textContent = `“${trashEntryTitle(entry)}”将被永久删除，且无法通过历史版本恢复。`;
    closeTrashPreview();
    elements.trashDeleteDialog.showModal();
  }
});

elements.trashPreviewDialog.addEventListener("cancel", () => {
  ui.trashPreview = null;
});

elements.trashDialog.addEventListener("cancel", () => {
  ui.trashExpanded = new Set();
});

document.querySelector("#cancelTrashDelete").addEventListener("click", () => {
  ui.trashDeleteId = null;
  ui.trashDeleteAll = false;
  elements.trashDeleteDialog.close();
});

document.querySelector("#trashDeleteForm").addEventListener("submit", (event) => {
  event.preventDefault();
  elements.trashDeleteDialog.close();
  if (ui.trashDeleteAll) void permanentlyDeleteAllTrashEntries();
  else if (ui.trashDeleteId) void permanentlyDeleteTrashEntry(ui.trashDeleteId);
  ui.trashDeleteId = null;
  ui.trashDeleteAll = false;
});

elements.trashDeleteDialog.addEventListener("cancel", () => {
  ui.trashDeleteId = null;
  ui.trashDeleteAll = false;
});

const renderAccountSettings = () => {
  const signedIn = Boolean(ui.account.authenticated);
  document.querySelectorAll("[data-account-view]").forEach((view) => {
    view.hidden = view.dataset.accountView !== (signedIn ? "signed-in" : "signed-out");
  });

  const profile = ui.account.profile ?? {};
  const nickname = String(profile.nickname || "神思用户");
  const accountId = String(profile.accountId || "--");
  const nicknameField = document.querySelector("[data-account-profile-nickname]");
  const accountIdField = document.querySelector("[data-account-profile-id]");
  if (nicknameField) nicknameField.textContent = nickname;
  if (accountIdField) accountIdField.textContent = accountId;

  const accountEntry = document.querySelector("#accountEntryButton");
  accountEntry.dataset.accountState = signedIn ? "signed-in" : "signed-out";
  accountEntry.title = uiText(signedIn ? nickname : "账户服务未开放，查看说明");
  accountEntry.setAttribute("aria-label", uiText(signedIn ? `${nickname}，打开账户设置` : "账户服务未开放，查看账户设置说明"));

  const signOut = document.querySelector("#accountSignOut");
  if (signOut) signOut.disabled = !signedIn;
};

const OFFLINE_WORKFLOW_TOOLS = Object.freeze([
  { id: "shensi/document.read", label: "读取指定文档" },
  { id: "shensi/workspace.search", label: "搜索当前工作区" },
  { id: "shensi/context.read", label: "读取指定上下文" },
]);
const OFFLINE_WORKFLOW_TOOL_IDS = new Set(OFFLINE_WORKFLOW_TOOLS.map((tool) => tool.id));
const OFFLINE_WORKFLOW_PERMISSION_IDS = new Set([
  "context.read",
  "document.read",
  "document.write_draft",
  "artifact.write_draft",
  "memory.propose",
  "tool.invoke",
]);
const DESKTOP_WORKFLOW_STEP_KINDS = new Set(["tool", "transform", "emit"]);

const presetOfflineWorkflowDefinition = (mode = ui.automation.workflowMode) => {
  const documentId = state.activeDocument;
  const common = {
    schemaVersion: 3,
    version: "1.0.0",
    runtime: "declarative",
  };
  if (mode === "search-workspace") {
    return {
      manifest: {
        ...common,
        id: "desktop.offline-workspace-search",
        name: "桌面端工作区搜索",
        capabilities: ["user.desktop_offline_workspace_search"],
        permissions: ["context.read", "tool.invoke"],
        tools: ["shensi/workspace.search"],
        workflow: { steps: [{ id: "search-workspace", kind: "tool", tool: "shensi/workspace.search", input: { query: "$inputs.query", limit: 12 } }] },
        outputContract: { type: "review_result", schemaVersion: 1 },
      },
      inputs: { query: String(document.querySelector("#workflowQuery")?.value || "").trim() },
    };
  }
  if (mode === "read-context") {
    return {
      manifest: {
        ...common,
        id: "desktop.offline-context-read",
        name: "桌面端上下文读取",
        capabilities: ["user.desktop_offline_context_read"],
        permissions: ["context.read", "tool.invoke"],
        tools: ["shensi/context.read"],
        workflow: { steps: [{ id: "read-context", kind: "tool", tool: "shensi/context.read", input: { documentIds: "$inputs.documentIds", maxCharsPerDocument: 20_000 } }] },
        outputContract: { type: "review_result", schemaVersion: 1 },
      },
      inputs: { documentIds: [documentId].filter(Boolean) },
    };
  }
  if (mode === "custom-declarative") return {
    manifest: {
      ...common,
      id: "user.desktop-custom-declarative",
      name: "桌面端自定义声明式 DAG",
      capabilities: ["user.desktop_custom_declarative"],
      permissions: ["artifact.write_draft"],
      tools: [],
      workflow: { steps: [
        { id: "select-input", kind: "transform", operation: "select", source: "$inputs" },
        { id: "emit-draft", kind: "emit", channel: "artifact_draft", source: "$steps.select-input", needs: ["select-input"] },
      ] },
      outputContract: { type: "artifact_draft", schemaVersion: 1 },
    },
    inputs: { instruction: "在这里填写声明式 Workflow 输入" },
  };
  return {
    manifest: {
      ...common,
      id: "desktop.offline-document-draft",
      name: "桌面端文档草稿读取",
      capabilities: ["user.desktop_offline_document_draft"],
      permissions: ["document.read", "artifact.write_draft", "tool.invoke"],
      tools: ["shensi/document.read"],
      workflow: { steps: [
        { id: "read-document", kind: "tool", tool: "shensi/document.read", input: { documentId: "$inputs.documentId" } },
        { id: "emit-draft", kind: "emit", channel: "artifact_draft", source: "$steps.read-document.markdown", needs: ["read-document"] },
      ] },
      outputContract: { type: "artifact_draft", schemaVersion: 1 },
    },
    inputs: { documentId },
  };
};

const workflowValueText = (value) => typeof value === "string" ? value : JSON.stringify(value ?? null, null, 2);

const seedWorkflowEditors = (mode = ui.automation.workflowMode, { force = false } = {}) => {
  const manifestEditor = document.querySelector("#workflowManifestEditor");
  const inputsEditor = document.querySelector("#workflowInputsEditor");
  if (!manifestEditor || !inputsEditor || (!force && manifestEditor.value.trim() && inputsEditor.value.trim())) return;
  const definition = presetOfflineWorkflowDefinition(mode);
  manifestEditor.value = JSON.stringify(definition.manifest, null, 2);
  inputsEditor.value = JSON.stringify(definition.inputs, null, 2);
};

const parseWorkflowJsonObject = (source, label) => {
  let value;
  try {
    value = JSON.parse(String(source || ""));
  } catch (error) {
    throw new Error(`${label} 不是有效 JSON：${error.message}`);
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(`${label} 必须是 JSON 对象`);
  return value;
};

const workflowDefinitionFromEditors = () => {
  const manifest = parseWorkflowJsonObject(document.querySelector("#workflowManifestEditor")?.value, "Manifest");
  const inputs = parseWorkflowJsonObject(document.querySelector("#workflowInputsEditor")?.value, "Inputs");
  if (manifest.runtime !== "declarative") throw new Error("桌面入口只允许 runtime=declarative；不会把脚本运行时降级到主进程执行");
  const permissions = [...new Set((Array.isArray(manifest.permissions) ? manifest.permissions : []).map((item) => String(item).trim()).filter(Boolean))];
  const tools = [...new Set((Array.isArray(manifest.tools) ? manifest.tools : []).map((item) => String(item).trim()).filter(Boolean))];
  const unsupportedPermissions = permissions.filter((permission) => !OFFLINE_WORKFLOW_PERMISSION_IDS.has(permission));
  const unsupportedTools = tools.filter((tool) => !OFFLINE_WORKFLOW_TOOL_IDS.has(tool));
  const steps = Array.isArray(manifest.workflow?.steps) ? manifest.workflow.steps : [];
  const unsupportedStepKinds = [...new Set(steps.map((step) => String(step?.kind || "")).filter((kind) => !DESKTOP_WORKFLOW_STEP_KINDS.has(kind)))];
  const hiddenTools = [...new Set(steps.filter((step) => step?.kind === "tool").map((step) => String(step.tool || "")).filter((tool) => !OFFLINE_WORKFLOW_TOOL_IDS.has(tool)))];
  const unsupportedTransforms = [...new Set(steps.filter((step) => step?.kind === "transform" && !["select", "merge"].includes(step.operation)).map((step) => String(step.operation || "")))];
  const unsupportedChannels = [...new Set(steps.filter((step) => step?.kind === "emit" && !["draft", "artifact_draft", "memory_proposal"].includes(step.channel ?? "draft")).map((step) => String(step.channel || "")))];
  const issues = [
    unsupportedPermissions.length ? `不支持的权限：${unsupportedPermissions.join("、")}` : "",
    unsupportedTools.length || hiddenTools.length ? `只允许三个只读工具；发现：${[...new Set([...unsupportedTools, ...hiddenTools])].join("、")}` : "",
    unsupportedStepKinds.length ? `桌面入口不执行这些步骤类型：${unsupportedStepKinds.join("、")}；当前只允许 tool、transform、emit` : "",
    unsupportedTransforms.length ? `不支持的声明式转换：${unsupportedTransforms.join("、")}` : "",
    unsupportedChannels.length ? `不支持的草稿通道：${unsupportedChannels.join("、")}` : "",
    steps.length > 64 ? "Workflow 步骤不能超过 64 项" : "",
  ].filter(Boolean);
  if (issues.length) throw new Error(issues.join("；"));
  return { manifest: { ...manifest, permissions, tools }, inputs };
};

const renderWorkflowPermissionPreview = () => {
  const mode = document.querySelector("#workflowMode")?.value || ui.automation.workflowMode;
  ui.automation.workflowMode = mode;
  const queryField = document.querySelector("[data-workflow-query-field]");
  if (queryField) queryField.hidden = mode !== "search-workspace";
  const preview = document.querySelector("#workflowPermissionPreview");
  const editorStatus = document.querySelector("#workflowEditorStatus");
  const confirm = document.querySelector("#confirmWorkflowRun");
  const runButton = document.querySelector("#runOfflineWorkflow");
  if (!preview) return;
  seedWorkflowEditors(mode);
  const toolLabels = new Map(OFFLINE_WORKFLOW_TOOLS.map((tool) => [tool.id, tool.label]));
  try {
    const definition = workflowDefinitionFromEditors();
    preview.classList.remove("invalid");
    preview.innerHTML = `
      <div><small>运行时</small><strong>声明式、本机隔离</strong></div>
      <div><small>本次权限</small><strong>${definition.manifest.permissions.map(escapeHtml).join(" · ") || "无"}</strong></div>
      <div><small>本次工具</small><strong>${definition.manifest.tools.map((id) => `${escapeHtml(toolLabels.get(id) || id)} <code>${escapeHtml(id)}</code>`).join(" · ") || "无"}</strong></div>
      <div><small>硬边界</small><strong>无网络工具 · 无直接写入 · 最多运行一轮</strong></div>
      <details><summary>本机可用的全部只读工具（3）</summary><ul>${OFFLINE_WORKFLOW_TOOLS.map((tool) => `<li><code>${escapeHtml(tool.id)}</code><span>${escapeHtml(tool.label)}</span></li>`).join("")}</ul></details>`;
    if (editorStatus) editorStatus.textContent = `Manifest 预检通过 · ${definition.manifest.workflow?.steps?.length || 0} 个 DAG 步骤`;
    if (confirm) confirm.disabled = false;
    if (runButton) runButton.disabled = confirm?.checked !== true || ui.automation.workflowRunning;
  } catch (error) {
    preview.classList.add("invalid");
    preview.innerHTML = `<section class="workflow-error" role="alert"><strong>Manifest 预检未通过</strong><p>${escapeHtml(error.message)}</p></section><details><summary>本机可用的全部只读工具（3）</summary><ul>${OFFLINE_WORKFLOW_TOOLS.map((tool) => `<li><code>${escapeHtml(tool.id)}</code><span>${escapeHtml(tool.label)}</span></li>`).join("")}</ul></details>`;
    if (editorStatus) editorStatus.textContent = "请修正 JSON 或权限声明";
    if (confirm) {
      confirm.checked = false;
      confirm.disabled = true;
    }
    if (runButton) runButton.disabled = true;
  }
};

const renderWorkflowResult = () => {
  const container = document.querySelector("#workflowResult");
  const status = document.querySelector("#workflowRunStatus");
  if (!container || !status) return;
  if (ui.automation.workflowRunning) {
    status.textContent = "正在本机运行…";
    container.innerHTML = '<p class="settings-empty">正在执行已确认的只读 Workflow…</p>';
    return;
  }
  if (ui.automation.workflowError) {
    status.textContent = "运行失败";
    container.innerHTML = `<section class="workflow-error" role="alert"><strong>Workflow 未执行完成</strong><p>${escapeHtml(ui.automation.workflowError)}</p></section>`;
    return;
  }
  const result = ui.automation.workflowResult;
  if (!result) {
    status.textContent = "等待确认";
    container.innerHTML = '<p class="settings-empty">尚未运行 Workflow。</p>';
    return;
  }
  status.textContent = "运行完成，等待审阅";
  const emissionMarkup = (result.emissions ?? []).map((emission, index) => {
    const adoptable = ["draft", "artifact_draft"].includes(emission.channel);
    return `<article class="workflow-emission" data-workflow-emission="${index}"><header><strong>${escapeHtml(emission.channel || "草稿")}</strong><small>Workflow 只生成草稿，尚未写入文档</small></header><textarea data-workflow-emission-review="${index}" spellcheck="false">${escapeHtml(workflowValueText(emission.value))}</textarea><footer>${adoptable ? `<button class="primary-button compact" type="button" data-adopt-workflow-emission="${index}">采用到当前文档</button>` : '<span>该结果类型仅供审阅，不能直接写入。</span>'}</footer></article>`;
  }).join("");
  const resultEntries = Object.entries(result.results ?? {});
  const audit = Array.isArray(result.audit) ? result.audit : [];
  container.innerHTML = `
    <section class="workflow-policy-result"><strong>安全策略已执行</strong><span>网络：关闭</span><span>直接写入：禁止</span><span>工具调用：${audit.filter((item) => item.type === "tool").length}</span></section>
    ${emissionMarkup || '<p class="settings-empty">本次没有生成可采用草稿；请在下方审阅只读结果。</p>'}
    <details class="workflow-raw-result" open><summary>只读执行结果</summary><pre>${escapeHtml(JSON.stringify(Object.fromEntries(resultEntries), null, 2))}</pre></details>
    <details class="workflow-raw-result"><summary>执行审计（${audit.length}）</summary><pre>${escapeHtml(JSON.stringify(audit, null, 2))}</pre></details>`;
};

const runOfflineWorkflowFromDesktop = async () => {
  const confirmation = document.querySelector("#confirmWorkflowRun");
  if (confirmation?.checked !== true) {
    showToast("请先核对权限并明确确认本轮 Workflow");
    return;
  }
  if (workspaceHasNoActiveEntry() || !state.settings.workspacePath) {
    showToast("请先打开并保存一个作品或笔记工作区");
    return;
  }
  let definition;
  try {
    definition = workflowDefinitionFromEditors();
  } catch (error) {
    showToast(error.message);
    renderWorkflowPermissionPreview();
    return;
  }
  if (ui.automation.workflowMode === "search-workspace" && !definition.inputs.query) {
    showToast("请输入工作区搜索关键词");
    return;
  }
  ui.automation.workflowRunning = true;
  ui.automation.workflowResult = null;
  ui.automation.workflowError = "";
  renderWorkflowResult();
  const button = document.querySelector("#runOfflineWorkflow");
  if (button) button.disabled = true;
  try {
    const response = await fetch("/api/workflows/execute", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        workspacePath: state.settings.workspacePath,
        confirmed: true,
        manifest: definition.manifest,
        inputs: definition.inputs,
        modelEnabled: false,
      }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !payload.ok) throw new Error(payload.message || `Workflow 执行失败（HTTP ${response.status}）`);
    ui.automation.workflowResult = payload.result;
  } catch (error) {
    ui.automation.workflowError = String(error.message || error);
  } finally {
    ui.automation.workflowRunning = false;
    if (confirmation) confirmation.checked = false;
    if (button) button.disabled = true;
    renderWorkflowResult();
  }
};

const adoptWorkflowEmission = async (index, button) => {
  const emission = ui.automation.workflowResult?.emissions?.[Number(index)];
  const documentState = activeEditableDocument();
  if (!emission || !["draft", "artifact_draft"].includes(emission.channel)) return;
  if (!documentState) {
    showToast("请先打开可编辑的正文或笔记文档");
    return;
  }
  const textarea = document.querySelector(`[data-workflow-emission-review="${CSS.escape(String(index))}"]`);
  const reviewedText = String(textarea?.value || "").trim();
  if (!reviewedText) {
    showToast("审阅结果为空，未写入文档");
    return;
  }
  if (!window.confirm(uiText(`确认把已审阅的 Workflow 草稿追加到“${documentState.title || "当前文档"}”？写入前会保存历史版本。`))) return;
  const documentId = state.activeDocument;
  const rollbackDocument = clone(documentState);
  const rollbackHistory = clone(state.histories?.[documentId] ?? []);
  if (button) button.disabled = true;
  try {
    snapshotDocument(documentId, "采用 Workflow 草稿前", { force: true, operations: [{ type: "workflow-adoption", workflowId: ui.automation.workflowResult?.plan?.manifest?.id || "desktop-offline-workflow" }] });
    const addition = proseToHtml(reviewedText) || `<p>${escapeHtml(reviewedText)}</p>`;
    documentState.html = sanitizeDocumentHtml(`${documentState.html || ""}${addition}`);
    documentState.markdown = htmlToMarkdown(documentState.html);
    documentState.updatedAt = nowTime();
    persist();
    await saveWorkspace({ throwOnError: true });
    renderEditor();
    recordActivity({ type: "edit", label: `采用 Workflow 草稿到${documentState.title || "当前文档"}`, documentId });
    if (button) button.textContent = "已采用";
    showToast("已采用审阅后的草稿，写入前版本已保存");
  } catch (error) {
    state.documents[documentId] = rollbackDocument;
    state.histories[documentId] = rollbackHistory;
    persist();
    if (button) button.disabled = false;
    showToast(`Workflow 草稿采用失败：${error.message}`);
  }
};

const EXPERIENCE_KIND_LABELS = Object.freeze({ method: "方法", style_preference: "写作偏好", avoidance: "避坑经验" });
const EXPERIENCE_SCOPE_LABELS = Object.freeze({ project: "当前作品", series: "系列", genre: "题材", author: "作者全局" });
