const setSkillFormCapabilities = (form, capabilities = []) => {
  const values = [...new Set(capabilities.filter((item) => SKILL_CAPABILITY_LABELS[item]))];
  form.dataset.skillCapabilities = JSON.stringify(values);
  renderSkillCategoryChecklist(skillCapabilityCategoryIds(values));
};

const setSkillTriggerCompatibilityStatus = (form, visible = false) => {
  const status = form?.querySelector("#skillTriggerCompatibility");
  if (!status) return;
  status.hidden = !visible;
  status.textContent = visible
    ? uiText("已忽略不受支持的自然语言触发条件或过短关键词；其余有效关键词仍会用于自动匹配。")
    : "";
};

const skillDraftFromForm = (form) => ({
  id: form.elements.id.value,
  version: form.elements.version.value,
  name: form.elements.name.value,
  author: form.elements.author.value,
  description: form.elements.description.value,
  prototypeId: form.elements.prototypeId.value,
  prototypeName: form.elements.prototypeName.value,
  prototypeFingerprint: form.elements.prototypeFingerprint.value,
  derivativeCopy: String(form.elements.derivativeCopy.value).toLowerCase() === "true",
  upstreamId: form.elements.upstreamId.value,
  upstreamVersion: form.elements.upstreamVersion.value,
  changeSummary: form.elements.changeSummary.value,
  capabilityBoundary: form.elements.capabilityBoundary.value,
  workspaceModes: [form.elements.workspaceMode.value].filter(Boolean),
  capabilities: JSON.parse(form.dataset.skillCapabilities || "[]"),
  triggerKeywords: String(form.elements.triggerKeywords.value || "").split(/[，,\n]/).map((item) => item.trim()).filter(Boolean),
  triggerConditions: String(form.elements.triggerConditions.value || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean),
  body: form.elements.body.value,
});

const applySkillDraftToForm = (form, incomingDraft = {}, { preserveExisting = false } = {}) => {
  const existingTriggerCompatibilityWarning = form.dataset.skillTriggerCompatibilityWarning === "true";
  const currentCategoryIds = preserveExisting
    ? [...form.querySelectorAll('#skillCapabilityChecklist input[type="checkbox"]:checked')].map((input) => input.value)
    : [];
  const draft = preserveExisting ? mergeSkillDraftValues(skillDraftFromForm(form), incomingDraft) : incomingDraft;
  form.elements.id.value = draft.id || "";
  form.elements.version.value = draft.version || "1.0.0";
  form.elements.name.value = draft.name || "";
  form.elements.author.value = draft.author || "";
  form.elements.description.value = draft.description || "";
  form.elements.prototypeId.value = draft.prototypeId || "";
  form.elements.prototypeName.value = draft.prototypeName || "";
  form.elements.prototypeFingerprint.value = draft.prototypeFingerprint || "";
  form.elements.derivativeCopy.value = draft.derivativeCopy ? "true" : "false";
  form.elements.upstreamId.value = draft.upstreamId || "";
  form.elements.upstreamVersion.value = draft.upstreamVersion || "";
  form.elements.changeSummary.value = draft.changeSummary || "";
  document.querySelector("#skillPrototypeFields").hidden = !draft.prototypeId;
  form.elements.capabilityBoundary.value = draft.capabilityBoundary || "";
  form.elements.workspaceMode.value = draft.workspaceModes?.[0] || "";
  if (preserveExisting) {
    const capabilities = mergeSkillDraftValues(
      { capabilities: JSON.parse(form.dataset.skillCapabilities || "[]") },
      { capabilities: draft.capabilities ?? [] },
    ).capabilities;
    form.dataset.skillCapabilities = JSON.stringify(capabilities);
    renderSkillCategoryChecklist([...new Set([...currentCategoryIds, ...skillCapabilityCategoryIds(capabilities)])]);
  } else {
    setSkillFormCapabilities(form, draft.capabilities ?? []);
  }
  form.elements.triggerKeywords.value = (draft.triggerKeywords ?? []).join("，");
  form.elements.triggerConditions.value = (draft.triggerConditions ?? []).join("\n");
  const triggerCompatibilityWarning = Boolean(
    (preserveExisting && existingTriggerCompatibilityWarning)
    || draft.ignoredTriggerKeywords?.length
    || draft.ignoredTriggerConditions?.length,
  );
  form.dataset.skillTriggerCompatibilityWarning = triggerCompatibilityWarning ? "true" : "false";
  setSkillTriggerCompatibilityStatus(form, triggerCompatibilityWarning);
  form.elements.body.value = draft.body || "";
};

const notebookDocumentSkillBody = (documentState) => {
  if (!documentState || documentState.documentKind === "whiteboard") return "";
  const importedHtmlUnchanged = documentState.importedHtmlRevision
    && documentState.importedHtmlRevision === contentRevision(documentState.html);
  if (importedHtmlUnchanged && String(documentState.markdown || "").trim()) return String(documentState.markdown).trim();
  return (htmlToMarkdown(documentState.html || "") || String(documentState.markdown || "")).trim();
};

const skillTrustLabel = (skill = {}) => skill.trustLevel === "official" ? "官方" : skill.trustLevel === "verified" ? "已验证" : skill.trustLevel === "community" ? "社区" : "本地";

const updateSkillDetailRating = (rating = 0) => {
  const value = Math.max(0, Math.min(5, Number(rating) || 0));
  document.querySelectorAll("[data-marketplace-rating]").forEach((button) => {
    const active = Number(button.dataset.marketplaceRating) <= value;
    button.classList.toggle("selected", active);
    button.setAttribute("aria-checked", String(Number(button.dataset.marketplaceRating) === value));
  });
  document.querySelector("#skillDetailRatingLabel").textContent = value ? `${value} 星` : "未选择";
};

const renderSkillDetailReviews = (reviews = []) => {
  const list = document.querySelector("#skillDetailReviewList");
  list.innerHTML = reviews.length ? reviews.map((review) => {
    const name = String(review.authorName || "神思用户");
    const initial = [...name][0] || "神";
    const avatar = review.avatarUrl
      ? `<img src="${escapeHtml(review.avatarUrl)}" alt="" />`
      : `<span>${escapeHtml(initial)}</span>`;
    const rawDate = review.updatedAt || review.createdAt;
    const timestamp = Number(rawDate) || Date.parse(rawDate || "");
    const date = Number.isFinite(timestamp) ? new Date(timestamp).toLocaleDateString("zh-CN") : "";
    return `<article class="skill-review-entry"><div class="skill-review-avatar">${avatar}</div><div><header><strong>${escapeHtml(name)}</strong><span>${"★".repeat(Math.max(1, Math.min(5, Number(review.rating) || 1)))} <small>${escapeHtml(date)}</small></span></header><p>${escapeHtml(review.comment || "")}</p></div></article>`;
  }).join("") : '<p class="settings-empty">还没有文字点评。</p>';
};

const capabilityStructureSkillDescriptor = (slot = {}, includedById = new Map()) => {
  const skillId = String(slot.skillId || "");
  const descriptorId = String(slot.compositeChildId || skillId);
  const included = includedById.get(descriptorId) || {};
  const local = capabilityTemplateSkill(skillId) || {};
  const listValue = (primary, secondary, fallback = []) => Array.isArray(primary)
    ? primary
    : Array.isArray(secondary) ? secondary : fallback;
  return {
    skillId: descriptorId,
    name: included.name || local.name || slot.name || skillId || "未装配 Skill",
    description: included.description || local.description || slot.description || "未附带功能说明",
    capabilityBoundary: included.capabilityBoundary || local.capabilityBoundary || "未声明能力边界",
    capabilities: listValue(included.capabilities, local.capabilities, local.replacementCapabilities ?? slot.capabilities ?? []),
    workspaceModes: listValue(included.workspaceModes, local.workspaceModes, slot.workspaceModes ?? []),
    inputRequirements: listValue(included.inputRequirements, local.inputRequirements),
    outputContract: included.outputContract || local.outputContract || "生成候选内容，不直接获得落盘或系统权限",
    triggerKeywords: listValue(included.triggerKeywords, local.triggerKeywords, slot.triggerKeywords ?? []),
    triggerConditions: listValue(included.triggerConditions, local.triggerConditions, slot.triggerRules ? [slot.triggerRules] : []),
    sourceLabel: included.sourceLabel || local.sourceLabel || (skillId.startsWith("builtin:") ? "神思官方内嵌固定插槽" : "结构发布快照"),
    detailAvailable: included.detailAvailable === undefined ? Boolean(local.id) : included.detailAvailable !== false,
  };
};

const capabilityStructureListText = (values = [], labels = null, fallback = "未声明") => {
  const items = [...new Set((Array.isArray(values) ? values : []).map((value) => String(value || "").trim()).filter(Boolean))];
  if (!items.length) return fallback;
  return items.map((value) => labels?.[value] || value).join("、");
};

const renderCapabilityStructureSkill = (slot = {}, includedById = new Map()) => {
  const role = capabilityRoleLabel(slot.role);
  if (!slot.skillId) {
    return `<div class="capability-structure-skill is-empty" data-capability-structure-empty-slot="${escapeHtml(slot.id || "")}"><span class="capability-structure-skill-mark" aria-hidden="true">+</span><span class="capability-structure-skill-copy"><strong>${escapeHtml(slot.name || "空插槽")}</strong><small>尚未装配 Skill</small></span><span class="capability-structure-skill-meta">${escapeHtml(role)} · Skill</span></div>`;
  }
  const descriptor = capabilityStructureSkillDescriptor(slot, includedById);
  const capabilityLabels = capabilityStructureListText(descriptor.capabilities, SKILL_CAPABILITY_LABELS);
  const modeLabels = capabilityStructureListText(descriptor.workspaceModes, {
    project: "作品模式",
    notebook: "笔记模式",
    general: "通用模式",
  }, "通用模式");
  const triggers = capabilityStructureListText([...descriptor.triggerKeywords, ...descriptor.triggerConditions], null, "仅在显式引用或兼容插槽命中时使用");
  const unavailable = descriptor.detailAvailable ? "" : '<p class="capability-structure-skill-warning">发布快照未包含完整说明；安装对应 Skill 后才能核对全部能力。</p>';
  return `<details class="capability-structure-skill" data-capability-structure-skill="${escapeHtml(descriptor.skillId)}">
    <summary>
      <span class="capability-structure-skill-mark" aria-hidden="true">{}</span>
      <span class="capability-structure-skill-copy"><strong>${escapeHtml(descriptor.name)}</strong><small>${escapeHtml(descriptor.description)}</small></span>
      <span class="capability-structure-skill-meta">${escapeHtml(role)} · Skill</span>
      <span class="capability-structure-disclosure">查看详情</span>
    </summary>
    <div class="capability-structure-skill-detail">
      ${unavailable}
      <dl>
        <div><dt>能力说明</dt><dd>${escapeHtml(capabilityLabels)}</dd></div>
        <div><dt>能力边界</dt><dd>${escapeHtml(descriptor.capabilityBoundary)}</dd></div>
        <div><dt>适用空间</dt><dd>${escapeHtml(modeLabels)}</dd></div>
        <div><dt>输入要求</dt><dd>${escapeHtml(capabilityStructureListText(descriptor.inputRequirements, null, "仅使用当前任务明确授权的内容"))}</dd></div>
        <div><dt>输出约定</dt><dd>${escapeHtml(descriptor.outputContract)}</dd></div>
        <div><dt>触发条件</dt><dd>${escapeHtml(triggers)}</dd></div>
        <div><dt>来源</dt><dd>${escapeHtml(descriptor.sourceLabel)}</dd></div>
      </dl>
    </div>
  </details>`;
};

const renderCapabilityStructureDetail = (skill = {}) => {
  const payload = skill.payload;
  const bundle = payload?.bundle;
  const root = bundle ? capabilityTemplateNode(bundle, payload.rootType, payload.rootId) : null;
  if (!root) return '<section class="capability-structure-detail"><p class="capability-structure-unavailable">这个版本没有可读取的内部结构。</p></section>';
  const includedById = new Map((skill.includedSkills ?? [])
    .filter((entry) => entry?.skillId)
    .map((entry) => [String(entry.skillId), entry]));
  const uniqueSkillIds = new Set((bundle.modules ?? []).flatMap((module) => (module.slots ?? []).map((slot) => slot.compositeChildId || slot.skillId).filter(Boolean)));
  const groupMap = new Map((bundle.groups ?? []).map((node) => [node.id, node]));
  const moduleMap = new Map((bundle.modules ?? []).map((node) => [node.id, node]));
  const nodeFor = (nodeType, nodeId) => nodeType === "template"
    ? (bundle.template?.id === nodeId ? bundle.template : null)
    : nodeType === "group" ? groupMap.get(nodeId) : moduleMap.get(nodeId);
  const chunks = [];
  const stack = [{ kind: "node", nodeType: payload.rootType, nodeId: payload.rootId, role: "", depth: 0 }];
  const maximumEntries = 500;
  let renderedEntries = 0;
  let truncated = false;
  while (stack.length) {
    const token = stack.pop();
    if (token.kind === "close") {
      chunks.push("</div></details>");
      continue;
    }
    if (renderedEntries >= maximumEntries) {
      if (!truncated) chunks.push('<p class="capability-structure-truncated">结构超过 500 个展示项，剩余内容请下载后在 Skill 管理中查看。</p>');
      truncated = true;
      continue;
    }
    renderedEntries += 1;
    if (token.kind === "skill") {
      chunks.push(renderCapabilityStructureSkill(token.slot, includedById));
      continue;
    }
    const node = nodeFor(token.nodeType, token.nodeId);
    if (!node) {
      chunks.push(`<p class="capability-structure-missing">引用的${token.nodeType === "group" ? "模组" : "模块"}不存在：${escapeHtml(token.nodeId)}</p>`);
      continue;
    }
    const typeLabel = capabilityAssetTypeLabel(token.nodeType);
    const children = token.nodeType === "module" ? (node.slots ?? []) : (node.items ?? []);
    const countLabel = token.nodeType === "module" ? `${children.length} 个 Skill 插槽` : `${children.length} 个直属节点`;
    const relationLabel = capabilityRelationLabel(node.relationType || "parallel");
    const meta = [token.role ? capabilityRoleLabel(token.role) : "", `子项${relationLabel}`, countLabel].filter(Boolean).join(" · ");
    const expanded = token.depth < 3 ? " open" : "";
    chunks.push(`<details class="capability-structure-node" data-capability-structure-node-type="${escapeHtml(token.nodeType)}" data-capability-structure-node-id="${escapeHtml(node.id)}"${expanded}>
      <summary>
        <span class="capability-structure-node-mark">${escapeHtml(typeLabel.slice(-1))}</span>
        <span class="capability-structure-node-copy"><strong>${escapeHtml(node.name || typeLabel)}</strong><small>${escapeHtml(node.description || "未填写功能说明")}</small></span>
        <span class="capability-structure-node-meta">${escapeHtml(meta)}</span>
      </summary>
      <div class="capability-structure-children">
        ${node.triggerRules ? `<p class="capability-structure-policy"><strong>触发：</strong>${escapeHtml(node.triggerRules)}</p>` : ""}`);
    stack.push({ kind: "close" });
    if (token.nodeType === "module") {
      for (let index = children.length - 1; index >= 0; index -= 1) stack.push({ kind: "skill", slot: children[index] });
    } else {
      for (let index = children.length - 1; index >= 0; index -= 1) {
        const placement = children[index];
        stack.push({
          kind: "node",
          nodeType: placement.targetType,
          nodeId: placement.targetId,
          role: placement.role || "peer",
          depth: token.depth + 1,
        });
      }
    }
  }
  const slotCount = (bundle.modules ?? []).reduce((total, module) => total + (module.slots?.length ?? 0), 0);
  return `<section class="capability-structure-detail">
    <header class="capability-structure-heading">
      <span><strong>内部结构与 Skill</strong><small>展开模组或模块查看结构；点击任一 Skill 可单独查看完整能力说明。</small></span>
      <small>${slotCount} 个插槽 · ${uniqueSkillIds.size} 个不同 Skill</small>
    </header>
    <div class="capability-structure-tree">${chunks.join("")}</div>
  </section>`;
};

const openSkillDetail = async ({ kind = "mine", id = "", version = "" } = {}) => {
  if (!id) return;
  const marketplace = kind === "marketplace";
  const official = kind === "official";
  const capabilityAsset = kind === "capability-asset";
  const localOfficial = kind === "mine"
    && (ui.skillCatalog.user ?? []).some((skill) => skill.id === id && skill.trustLevel === "official");
  const response = await fetch(capabilityAsset ? "/api/skills/capability-assets/read" : official ? "/api/skills/official/read" : marketplace ? "/api/skill-marketplace/read" : "/api/skills/read", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id, version, includePayload: capabilityAsset || marketplace, includeContent: official || marketplace || localOfficial }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "详情读取失败");
  const skill = capabilityAsset ? payload.asset : payload.skill;
  const assetType = skill.assetType || "skill";
  elements.skillDetailDialog.classList.toggle("is-capability-detail", assetType !== "skill");
  const typeLabel = capabilityAssetTypeLabel(assetType);
  const ratingId = capabilityAsset ? skill.marketplaceId : marketplace ? skill.id : "";
  const userReview = skill.userReview || null;
  const reviews = Array.isArray(skill.reviews) ? skill.reviews : [];
  const userRating = Number(skill.userRating || userReview?.rating) || 0;
  ui.skillDetail = {
    kind,
    id,
    version,
    assetType,
    ratingId,
    rating: userRating,
    ratingDraft: userRating,
    reviewDraft: String(userReview?.comment || ""),
    reviews,
    item: skill,
  };
  document.querySelector("#skillDetailTitle").textContent = skill.name || `${typeLabel}详情`;
  document.querySelector("#skillDetailDescription").textContent = skill.description || "";
  document.querySelector("#skillDetailBoundary").textContent = assetType === "skill"
    ? skill.capabilityBoundary || skill.description || "未声明"
    : "只定义可被任务路由调动的能力结构，不获得文件、正史、记忆或落盘权限。";
  const compositeCapabilityAsset = capabilityAsset && Boolean(skill.integrationSkillId);
  const importedCompositeAsset = compositeCapabilityAsset && skill.origin === "imported";
  const githubCapabilityAsset = compositeCapabilityAsset && skill.sourceType === "github";
  document.querySelector("#skillDetailTags").innerHTML = official
    ? `<span class="skill-origin-tag developer">官方内嵌</span><span class="skill-trust-tag official">${skillTrustLabel(skill)}</span>`
    : marketplace
    ? `<span class="skill-origin-tag downloaded">广场</span><span class="skill-origin-tag">${escapeHtml(typeLabel)}</span><span class="skill-trust-tag ${escapeHtml(skill.trustLevel || "community")}">${skillTrustLabel(skill)}</span>`
    : capabilityAsset
      ? `${githubCapabilityAsset ? '<span class="skill-origin-tag downloaded">GitHub 下载</span><span class="skill-trust-tag community">复合 Skill</span>' : importedCompositeAsset ? '<span class="skill-origin-tag imported">导入</span><span class="skill-trust-tag local">复合 Skill</span>' : '<span class="skill-origin-tag downloaded">广场</span>'}<span class="skill-origin-tag">${escapeHtml(typeLabel)}</span>${skill.trustLevel === "official" ? `<span class="skill-trust-tag official">官方</span>` : ""}${skill.active ? `<span class="skill-trust-tag verified">当前面板</span>` : ""}`
      : `<span class="skill-origin-tag ${escapeHtml(skill.origin || "imported")}">${skillOriginLabel(skill)}</span>${skill.trustLevel && skill.trustLevel !== "local" ? `<span class="skill-trust-tag ${escapeHtml(skill.trustLevel)}">${skillTrustLabel(skill)}</span>` : ""}`;
  const modes = (skill.workspaceModes ?? []).map((mode) => mode === "project" ? "作品模式" : mode === "notebook" ? "笔记模式" : "通用模式").join("、") || "通用模式";
  const capabilities = assetType === "skill" ? skillCapabilityCategoryLabels(skill.capabilities ?? []).join("、") || "辅助" : typeLabel;
  const authored = (value, fallback = "未声明") => `<span class="skill-authored-copy">${escapeHtml(String(value || fallback))}</span>`;
  const inputs = (skill.inputRequirements ?? []).join("、") || "仅使用当前任务明确授权的内容";
  const triggers = [...(skill.triggerKeywords ?? []), ...(skill.triggerConditions ?? [])].join("、") || "仅在显式引用或兼容插槽命中时使用";
  if (assetType === "skill") {
    const fullSource = (official || skill.trustLevel === "official") && skill.content
      ? `<details class="official-skill-source" open><summary>完整开源 Skill 内容</summary><pre>${escapeHtml(skill.content)}</pre></details>` : "";
    document.querySelector("#skillDetailContent").innerHTML = `<dl class="skill-detail-key-points"><div><dt>主要用途</dt><dd>${authored(skill.description)}</dd></div><div><dt>能力说明</dt><dd>${escapeHtml(capabilities)}</dd></div><div><dt>输入要求</dt><dd>${authored(inputs)}</dd></div><div><dt>输出约定</dt><dd>${authored(skill.outputContract, "生成候选内容，不直接获得落盘或系统权限")}</dd></div><div><dt>调用条件</dt><dd>${authored(triggers)}</dd></div></dl>${fullSource}`;
  } else {
    const assetBundle = skill.payload?.bundle;
    const nodeCount = Number(skill.nodeCount) || (assetBundle ? assetBundle.groups.length + assetBundle.modules.length : 0);
    const slotCount = Number(skill.slotCount) || (assetBundle ? assetBundle.modules.reduce((total, module) => total + module.slots.length, 0) : 0);
    const compositeDetails = compositeCapabilityAsset
      ? `<div><dt>结构转换</dt><dd>由内置“复合 Skill 结构转换”识别根 Skill、子 Skill、原始层级和运行关系；子 Skill 不会分散显示在“我的 Skill”列表。</dd></div><div><dt>整体插件用法</dt><dd>${escapeHtml(skill.usageGuidance || "将整体插件 Skill 插入插槽，由插槽限制本轮实际能力。")}</dd></div><div><dt>修改规则</dt><dd>${escapeHtml(skill.modificationGuidance || "修改结构前请确认内部职责和运行关系仍然一致。")}</dd></div>`
      : "";
    const runtimeStatus = compositeCapabilityAsset
      ? "整体插件尚未插入插槽时不参与任务；插入后仅加载当前插槽授权能力对应的子 Skill"
      : skill.active ? "当前运行面板" : assetType === "template" ? "未启用，不参与任务路由" : "下载到能力库，放入当前面板后生效";
    document.querySelector("#skillDetailContent").innerHTML = `<div class="capability-detail-content"><dl class="skill-detail-key-points"><div><dt>结构类型</dt><dd>${escapeHtml(typeLabel)}</dd></div><div><dt>包含节点</dt><dd>${nodeCount} 个模块或模组</dd></div><div><dt>包含插槽</dt><dd>${slotCount} 个 Skill 插槽</dd></div><div><dt>关系</dt><dd>${escapeHtml(capabilityRelationLabel(skill.relationType || assetBundle?.template?.relationType || "parallel"))}</dd></div><div><dt>运行状态</dt><dd>${runtimeStatus}</dd></div>${compositeDetails}</dl>${renderCapabilityStructureDetail(skill)}</div>`;
  }
  document.querySelector("#skillDetailMetadata").innerHTML = `<div><dt>作者</dt><dd>${escapeHtml(skill.author || "未声明")}</dd></div><div><dt>版本</dt><dd>${escapeHtml(skill.version || "-")}</dd></div><div><dt>类型</dt><dd>${escapeHtml(typeLabel)}</dd></div><div><dt>能力板块</dt><dd>${escapeHtml(capabilities)}</dd></div><div><dt>来源</dt><dd>${escapeHtml(skill.sourceLabel || (official ? "神思官方内嵌固定插槽" : marketplace ? "Skill 广场" : githubCapabilityAsset ? "GitHub 下载" : importedCompositeAsset ? "本地 Skill 包" : capabilityAsset ? "Skill 广场" : "本地 Skill 库"))}</dd></div>`;
  document.querySelector("#skillDetailRating").hidden = !ratingId;
  document.querySelector("#skillDetailRatingEditorTitle").textContent = `发表对这个${typeLabel}的评分与点评`;
  const aggregateRating = Number(skill.rating) || 0;
  document.querySelector("#skillDetailAggregateRating").textContent = aggregateRating ? `${aggregateRating.toFixed(1)} / 5` : "暂无评分";
  document.querySelector("#skillDetailRatingCount").textContent = `${Number(skill.ratingCount) || reviews.length} 条点评`;
  document.querySelector("#skillDetailReviewText").value = ui.skillDetail.reviewDraft;
  renderSkillDetailReviews(reviews);
  document.querySelector("#editSkillFromDetail").hidden = !(assetType === "skill" && ["official", "mine"].includes(kind));
  document.querySelector("#copyOfficialSkillFromDetail").hidden = !(assetType === "skill" || capabilityAsset || marketplace && skill.installedAssetId);
  updateSkillDetailRating(ui.skillDetail.ratingDraft);
  elements.skillDetailDialog.showModal();
  elements.skillDetailDialog.scrollTop = 0;
};

const copySkillForEditing = async (id, kind = "mine", { closeDetail = true } = {}) => {
  const response = await fetch("/api/skills/copy", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id, kind }) });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "复制 Skill 失败");
  if (closeDetail && elements.skillDetailDialog.open) elements.skillDetailDialog.close();
  await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
  showToast(`已创建 ${payload.skill?.name || "可编辑副本"}；请重新命名后保存`);
  await openSkillEditor(payload.skill?.id || "");
};

const editOfficialSkillDirectly = async (id, { closeDetail = true } = {}) => {
  const response = await fetch("/api/skills/official/edit", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id }) });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "官方 Skill 编辑版本创建失败");
  if (closeDetail && elements.skillDetailDialog.open) elements.skillDetailDialog.close();
  await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
  showToast("官方基线已写入历史；本次修改会保存为新版本");
  await openSkillEditor(payload.skill?.id || "");
};

const copyCapabilityForEditing = async ({ assetId = "", scopeType = "", scopeId = "" } = {}) => {
  await persistCapabilityTemplateDraftBeforeLibraryMutation();
  const response = await fetch("/api/skills/capability-assets/copy", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ assetId, scopeType, scopeId }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "能力资产复制失败");
  if (payload.capabilityTemplate) applyCapabilityTemplatePayload(payload);
  await refreshSkillCatalog({ force: true });
  const asset = capabilityAssetById(payload.asset?.id) || payload.asset;
  showToast(`${asset?.name || "能力资产副本"}已创建；必须重新命名并修改内容或结构后才能分享`);
  if (asset?.assetType !== "template") await openCapabilityAssetForEditing(asset);
  return asset;
};

const renderSkillHistory = () => {
  if (ui.skillHistoryKind === "official") {
    const skill = [...(ui.skillCatalog.builtins ?? []), ...(ui.skillCatalog.fixedSlots ?? [])]
      .find((item) => item.id === ui.skillHistoryId);
    if (!skill) return false;
    document.querySelector("#skillHistoryTitle").textContent = `${skill.name} · 官方版本`;
    document.querySelector("#skillHistoryDescription").textContent = "官方内嵌基线不属于用户的本地历史快照，不占本地历史空间；直接修改后形成的本地版本可在“我的 Skill”中删除。";
    const versions = skill.versions?.length ? [...skill.versions] : [{ version: skill.version || "1.0.0", description: skill.description }];
    elements.skillHistoryList.innerHTML = versions.sort((left, right) => String(right.version).localeCompare(String(left.version), undefined, { numeric: true })).map((version, index) => `<article class="skill-history-entry"><div><strong>v${escapeHtml(version.version || skill.version || "1.0.0")}${index === 0 ? ` <span class="skill-history-active">当前官方版本</span>` : ""}</strong><small>神思官方内嵌</small><p>${escapeHtml(version.description || version.changeSummary || skill.description || "官方固定插槽 Skill")}</p></div><span class="skill-history-actions"><button class="secondary-button compact" type="button" data-skill-history-detail="${escapeHtml(version.version || skill.version || "1.0.0")}">查看</button></span></article>`).join("");
    return true;
  }
  if (ui.skillHistoryKind === "marketplace") {
    const skill = marketplaceCatalogItemById(ui.skillHistoryId);
    if (!skill) return false;
    document.querySelector("#skillHistoryTitle").textContent = `${skill.name} · 发布历史`;
    document.querySelector("#skillHistoryDescription").textContent = "云端版本不占本地历史空间；下载者可选择具体版本下载，但只有创作者能删除自己发布的云端版本。下载后本地先只保留所选版本。";
    const versions = [...(skill.versions ?? [])].sort((left, right) => Number(right.publishedAt) - Number(left.publishedAt));
    const ownedVersionIds = new Set((ui.skillCatalog.marketplace?.submissions ?? []).map((item) => item.id));
    elements.skillHistoryList.innerHTML = versions.map((version, index) => {
      const date = new Date(version.publishedAt || 0);
      const status = version.status === "yanked" ? ` <span class="skill-status failed">已下架</span>` : index === 0 ? ` <span class="skill-history-active">最新发布</span>` : "";
      const creatorDelete = ownedVersionIds.has(version.id)
        ? `<button class="danger-button compact" type="button" data-marketplace-version-delete="${escapeHtml(version.id)}">删除云端版本</button>`
        : "";
      return `<article class="skill-history-entry"><div><strong>v${escapeHtml(version.version)}${status}</strong><small>${escapeHtml(Number.isNaN(date.getTime()) ? "" : date.toLocaleString("zh-CN"))} · ${escapeHtml(version.author || "未声明作者")}</small><p>${escapeHtml(version.description || "未提供版本说明")}</p></div><span class="skill-history-actions"><button class="secondary-button compact" type="button" data-skill-history-detail="${escapeHtml(version.id)}">查看</button><button class="primary-button compact" type="button" data-marketplace-version-install="${escapeHtml(version.id)}" ${version.status === "yanked" ? "disabled" : ""}>下载此版本</button>${creatorDelete}</span></article>`;
    }).join("") || `<p class="settings-empty">尚无历史版本。</p>`;
    return true;
  }
  if (ui.skillHistoryKind === "capability-asset") {
    const asset = (ui.skillCatalog.capabilityAssets ?? []).find((item) => item.id === ui.skillHistoryId);
    if (!asset) return false;
    document.querySelector("#skillHistoryTitle").textContent = `${asset.name} · 历史版本`;
    document.querySelector("#skillHistoryDescription").textContent = "可查看并删除下载或修改形成的本地版本；当前版本需先切换后才能删除。";
    elements.skillHistoryList.innerHTML = [...(asset.versions ?? [])].sort((left, right) => Number(right.version) - Number(left.version)).map((version) => {
      const active = Number(version.version) === Number(asset.version);
      const date = new Date(version.installedAt || 0);
      return `<article class="skill-history-entry"><div><strong>v${escapeHtml(version.version)}${active ? ` <span class="skill-history-active">当前版本</span>` : ""}</strong><small>${escapeHtml(Number.isNaN(date.getTime()) ? "" : date.toLocaleString("zh-CN"))}</small><p>${escapeHtml(version.source === "edited" ? "本地修改版本" : "从广场下载的版本")}</p></div><span class="skill-history-actions"><button class="secondary-button compact" type="button" data-capability-asset-history-detail="${escapeHtml(version.version)}">查看</button><button class="danger-button compact" type="button" data-capability-asset-history-delete="${escapeHtml(version.version)}" ${active ? 'disabled title="当前版本需先切换后删除"' : ""}>删除版本</button></span></article>`;
    }).join("") || `<p class="settings-empty">尚无历史版本。</p>`;
    return true;
  }
  const skill = (ui.skillCatalog.user ?? []).find((item) => item.id === ui.skillHistoryId);
  if (!skill) return false;
  document.querySelector("#skillHistoryTitle").textContent = `${skill.name} · 历史版本`;
  document.querySelector("#skillHistoryDescription").textContent = "可查看、恢复或删除本地版本。删除正在使用的版本时会自动切换到最近保留版本；至少保留一个版本。";
  const versions = [...(skill.versions ?? [])].sort((left, right) => Number(right.installedAt) - Number(left.installedAt));
  elements.skillHistoryList.innerHTML = versions.map((version) => {
    const active = version.version === skill.version;
    const date = new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }).format(new Date(version.installedAt || 0));
    const status = version.testStatus === "passed" ? "测试通过" : version.testStatus === "failed" ? "测试失败" : "尚未测试";
    const soleVersion = versions.length <= 1;
    return `<article class="skill-history-entry" data-skill-history-version="${escapeHtml(version.version)}"><div><strong>v${escapeHtml(version.version)}${active ? ` <span class="skill-history-active">当前版本</span>` : ""}</strong><small>${escapeHtml(date)} · ${escapeHtml(status)}</small><p>${escapeHtml(version.testSummary || "尚未测试")}</p></div><span class="skill-history-actions"><button class="secondary-button compact" type="button" data-skill-history-detail="${escapeHtml(version.version)}">查看</button><button class="primary-button compact" type="button" data-skill-history-restore="${escapeHtml(version.version)}" ${active ? "disabled" : ""}>恢复</button><button class="danger-button compact" type="button" data-skill-history-delete="${escapeHtml(version.version)}" ${soleVersion ? 'disabled title="至少保留一个版本"' : ""}>删除版本</button></span></article>`;
  }).join("") || `<p class="settings-empty">尚无历史版本。</p>`;
  return true;
};

const openSkillHistory = (skillId, kind = "mine") => {
  ui.skillHistoryId = skillId;
  ui.skillHistoryKind = kind;
  if (!renderSkillHistory()) return showToast("Skill 不存在");
  elements.skillHistoryDialog.showModal();
};

const marketplaceShareCandidates = () => {
  return (ui.skillCatalog.user ?? [])
    .filter((skill) => skill.testStatus === "passed" && skill.origin !== "downloaded" && skill.trustLevel !== "official")
    .map((skill) => ({ key: `skill|${skill.id}`, assetType: "skill", id: skill.id, name: skill.name, version: skill.version, origin: skillOriginLabel(skill) }));
};

const shareMarketplaceCandidate = async (candidate) => {
  if (!candidate) throw new Error("请选择要分享的项目");
  const endpoint = candidate.assetType === "skill" ? "/api/skill-marketplace/share" : "/api/skill-marketplace/share-capability";
  const body = candidate.assetType === "skill"
    ? { id: candidate.id }
    : { scopeType: candidate.scopeType, scopeId: candidate.scopeId };
  const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "分享到广场失败");
  await refreshSkillCatalog({ force: true });
  return payload;
};

const shareCapabilityToMarketplace = async (scopeType, scopeId) => {
  const node = capabilityTemplateNode(capabilityTemplateBundle(), scopeType, scopeId);
  const candidate = { assetType: scopeType, scopeType, scopeId, name: node?.name || "能力结构" };
  const payload = await shareMarketplaceCandidate(candidate);
  showToast(payload.alreadyPublished ? "这个版本已在本机广场中，尚未上传云端" : `${candidate.name} 已发布到本机广场，尚未上传云端`);
};

const shareCapabilityAssetToMarketplace = async (asset) => {
  if (!asset) throw new Error("能力资产不存在");
  const response = await fetch("/api/skill-marketplace/share-capability", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ assetId: asset.id }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "分享到广场失败");
  await refreshSkillCatalog({ force: true });
  showToast(payload.alreadyPublished ? "这个版本已在本机广场中，尚未上传云端" : `${asset.name} 已发布到本机广场，尚未上传云端`);
};

const shareSkillToMarketplaceById = async (id) => {
  const skill = (ui.skillCatalog.user ?? []).find((item) => item.id === id);
  if (!skill) throw new Error("Skill 不存在");
  const payload = await shareMarketplaceCandidate({ assetType: "skill", id, name: skill.name });
  showToast(payload.alreadyPublished ? "这个 Skill 版本已在本机广场中，尚未上传云端" : `${skill.name} 已发布到本机广场，尚未上传云端`);
};

const unpublishMarketplacePublication = async (item) => {
  if (!item || !marketplaceItemPublishedByUser(item, ui.skillCatalog.marketplace?.submissions ?? [])) throw new Error("只能下架当前账号发布的内容");
  if (!window.confirm(uiText(`下架“${item.name}”的当前发布版本？已下载用户的本地副本和历史版本不会被删除。`))) return;
  const response = await fetch("/api/skill-marketplace/unpublish", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id: item.id }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "广场内容下架失败");
  await refreshSkillCatalog({ force: true });
  ui.skillMarketplaceView = "published";
  renderSkillSettings();
  showToast(payload.alreadyUnpublished ? "这个版本已经下架" : "已下架；发布快照和本地历史版本仍然保留");
};

const beginMarketplaceRepublish = async (item) => {
  if (!item || !marketplaceItemPublishedByUser(item, ui.skillCatalog.marketplace?.submissions ?? [])) throw new Error("只能编辑当前账号发布的内容");
  const assetType = item.assetType || "skill";
  if (assetType === "skill") {
    const localSkill = (ui.skillCatalog.user ?? []).find((skill) => skill.skillId === item.skillId
      || skill.id === item.skillId
      || skill.id === `user:${item.skillId}`);
    if (!localSkill) throw new Error("原 Skill 已不在本机；请先从历史备份恢复后再发布新版");
    ui.marketplaceRepublish = { publicationId: item.id, assetType, skillId: localSkill.id };
    await openSkillEditor(localSkill.id);
    document.querySelector("#skillEditorTitle").textContent = "编辑并发布新版";
    document.querySelector("#skillEditorDescription").textContent = "保存后会先形成新的本地历史版本，再把该不可变版本发布为广场最新版本。";
    document.querySelector("#skillEditorSubmit").textContent = "保存并发布新版";
    return;
  }
  const asset = (ui.skillCatalog.capabilityAssets ?? []).find((candidate) => candidate.id === item.sourceId
    || candidate.marketplaceId === item.id
    || (candidate.versions ?? []).some((version) => version.marketplaceId === item.id));
  let scopeId = item.sourceId;
  if (asset) {
    await openCapabilityAssetForEditing(asset);
    const currentAsset = capabilityAssetById(asset.id) || asset;
    if (assetType === "template" && currentAsset.active !== true) return;
    scopeId = assetType === "template" ? capabilityTemplateBundle()?.template?.id : currentAsset.localRootId;
  } else {
    const node = capabilityTemplateNode(capabilityTemplateBundle(), assetType, scopeId);
    if (!node) throw new Error(`原${capabilityAssetTypeLabel(assetType)}已不在当前面板中，无法编辑发布新版`);
    ui.skillSettingsTab = "slots";
    ui.capabilityTemplatePath = assetType === "template" ? [] : [{ scopeType: assetType, scopeId }];
    document.querySelectorAll("[data-skill-settings-tab]").forEach((button) => button.classList.toggle("active", button.dataset.skillSettingsTab === "slots"));
    renderSkillSettings();
  }
  if (!scopeId) throw new Error(`找不到要编辑的${capabilityAssetTypeLabel(assetType)}`);
  ui.marketplaceRepublish = { publicationId: item.id, assetType, scopeId, assetId: asset?.id || "" };
  openCapabilityNodeEditor({ scopeType: assetType, scopeId });
  document.querySelector("#capabilityNodeEditorTitle").textContent = `编辑并发布新版${capabilityAssetTypeLabel(assetType)}`;
  elements.capabilityNodeEditorForm.querySelector('[type="submit"]').textContent = "保存并发布新版";
};

const updateMarketplaceShareSummary = () => {
  const select = document.querySelector("#skillMarketplaceShareSelect");
  const submit = document.querySelector("#submitSkillMarketplaceShare");
  const candidate = marketplaceShareCandidates().find((item) => item.key === select.value);
  submit.disabled = !candidate;
  document.querySelector("#skillMarketplaceShareSummary").textContent = candidate
    ? `${candidate.name} · ${capabilityAssetTypeLabel(candidate.assetType)} · v${candidate.version} · ${candidate.origin}。分享前会重新检查；后续修改不会替换本次版本快照。`
    : "当前没有可分享的项目。Skill 需要先测试通过；模块、模组和面板需要先保存在当前面板中。";
};

const openSkillMarketplaceShare = () => {
  const select = document.querySelector("#skillMarketplaceShareSelect");
  const candidates = marketplaceShareCandidates();
  select.innerHTML = candidates.length
    ? candidates.map((candidate) => `<option value="${escapeHtml(candidate.key)}">${escapeHtml(capabilityAssetTypeLabel(candidate.assetType))} · ${escapeHtml(candidate.name)} · v${escapeHtml(candidate.version)}</option>`).join("")
    : `<option value="">暂无可分享项目</option>`;
  select.disabled = !candidates.length;
  updateMarketplaceShareSummary();
  elements.skillMarketplaceShareDialog.showModal();
};

const capabilityAssetById = (id) => (ui.skillCatalog.capabilityAssets ?? []).find((asset) => asset.id === id) || null;

const persistCapabilityTemplateDraftBeforeLibraryMutation = async () => {
  if (!ui.capabilityTemplateDirty) return;
  await saveCapabilityTemplateScope();
};

const activateCapabilityAssetTemplate = async (asset) => {
  if (!asset || asset.assetType !== "template") throw new Error("只有面板可以切换启用");
  if (asset.active) return asset;
  if (!window.confirm(uiText(`切换启用面板“${asset.name}”？当前面板仍会保留在历史版本中，整个神思同时只运行这一套面板。`))) return null;
  await persistCapabilityTemplateDraftBeforeLibraryMutation();
  const response = await fetch("/api/skills/capability-assets/activate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: asset.id }) });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.message || "面板切换失败");
  applyCapabilityTemplatePayload(payload);
  await refreshSkillCatalog({ force: true });
  showToast(`${asset.name} 已成为当前唯一运行面板`);
  return capabilityAssetById(asset.id);
};

const openCapabilityAssetForEditing = async (asset) => {
  if (!asset) throw new Error("能力资产不存在");
  if (asset.compositeRouting && !window.confirm(uiText("该复合 Skill 含内部任务路由或任务分工。修改子 Skill、模块、模组、关系或职责后，必须同步修改整体插件 Skill 的内部路由与分工规则，否则可能漏调用、重复调用或顺序失效。继续编辑结构？"))) return;
  let current = asset;
  if (asset.assetType === "template" && !asset.active) {
    current = await activateCapabilityAssetTemplate(asset);
    if (!current) return;
  }
  const bundle = capabilityTemplateBundle();
  if (asset.assetType !== "template" && !capabilityTemplateNode(bundle, asset.assetType, asset.localRootId)) throw new Error("这个能力结构未载入当前面板库，请重新下载");
  ui.skillSettingsTab = "slots";
  ui.capabilityTemplatePath = asset.assetType === "template" ? [] : [{ scopeType: asset.assetType, scopeId: asset.localRootId }];
  document.querySelectorAll("[data-skill-settings-tab]").forEach((button) => button.classList.toggle("active", button.dataset.skillSettingsTab === "slots"));
  renderSkillSettings();
  showToast(`已进入${capabilityAssetTypeLabel(asset.assetType)}编辑`);
};

const openCapabilityAssetHistory = (asset) => {
  if (!asset) return;
  if (asset.assetType === "template" && !asset.active) {
    openSkillHistory(asset.id, "capability-asset");
    return;
  }
  const scopeId = asset.assetType === "template" ? capabilityTemplateBundle()?.template?.id : asset.localRootId;
  if (scopeId) openCapabilityHistory(asset.assetType, scopeId);
};

const runCapabilityAssetAction = async (asset, action) => {
  if (!asset) throw new Error("能力资产不存在");
  const typeLabel = capabilityAssetTypeLabel(asset.assetType);
  if (action === "detail") return openSkillDetail({ kind: "capability-asset", id: asset.id });
  if (action === "history") return openCapabilityAssetHistory(asset);
  if (action === "edit") return openCapabilityAssetForEditing(asset);
  if (action === "copy") return copyCapabilityForEditing({ assetId: asset.id });
  if (action === "edit-skill") {
    if (!asset.integrationSkillId) throw new Error("整体插件 Skill 不存在");
    if (asset.compositeRouting && !window.confirm(uiText("该复合 Skill 含内部任务路由或任务分工。修改总控 Skill 时必须同步核对全部子 Skill 的职责和结构关系，否则可能漏调用、重复调用或顺序失效。继续编辑整体插件？"))) return;
    return openSkillEditor(asset.integrationSkillId);
  }
  if (action === "activate") return activateCapabilityAssetTemplate(asset);
  if (action === "test") {
    const response = await fetch("/api/skills/capability-assets/test", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: asset.id }) });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || `${typeLabel}测试失败`);
    await refreshSkillCatalog({ force: true });
    showToast(payload.test?.summary || `${typeLabel}测试通过`);
    return;
  }
  if (action === "export") {
    const response = await fetch("/api/skills/capability-assets/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: asset.id }) });
    if (!response.ok) throw new Error((await response.json().catch(() => ({}))).message || `${typeLabel}导出失败`);
    await saveBlobLocally({
      blob: await response.blob(),
      fileName: responseDownloadFileName(response, `${cleanDownloadFileName(asset.name, typeLabel)}.shensi-capability.json`),
      mimeType: "application/vnd.shensi.capability+json",
      extension: ".json",
    });
    showToast(`${typeLabel}已导出`);
    return;
  }
  if (action === "export-skill") {
    if (!asset.integrationSkillId) throw new Error("整体插件 Skill 不存在");
    const response = await fetch("/api/skills/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: asset.integrationSkillId }) });
    if (!response.ok) throw new Error((await response.json().catch(() => ({}))).message || "复合 Skill 导出失败");
    await saveBlobLocally({
      blob: await response.blob(),
      fileName: responseDownloadFileName(response, `${cleanDownloadFileName(asset.name, "Skill")}.skill`),
      mimeType: "application/vnd.shensi.skill+zip",
      extension: ".skill",
    });
    showToast("完整复合 Skill 包已导出");
    return;
  }
  if (action === "delete") {
    const compositeAsset = Boolean(asset.integrationSkillId);
    const confirmation = compositeAsset
      ? `删除复合 Skill“${asset.name}”？整体插件及其模块、模组结构会一起进入回收站并保留 30 天；永久清理后只能重新导入原 Skill 包。`
      : `删除下载的${typeLabel}“${asset.name}”？${asset.assetType === "template" ? "下载记录会移除。" : "它在当前面板库中的节点和引用位置也会移除。"}`;
    if (!window.confirm(uiText(confirmation))) return;
    await persistCapabilityTemplateDraftBeforeLibraryMutation();
    const response = await fetch("/api/skills/capability-assets/delete", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: asset.id }) });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || `${typeLabel}删除失败`);
    if (payload.trash) {
      ui.skillTrash = [payload.trash, ...ui.skillTrash.filter((item) => item.trashId !== payload.trash.trashId)];
      renderTrashButton();
    }
    await refreshSkillCatalog({ force: true });
    showToast(compositeAsset ? "复合 Skill 已移入回收站，将保留 30 天" : `${typeLabel}已删除；需要时可从原来源重新下载`);
  }
};

const openSkillEditor = async (skillId = "", { sourceDocumentId = "", sourceDraft = null, importContent = "", importDraft = null } = {}) => {
  ui.editingSkillId = skillId || null;
  ui.skillImportContent = importContent || "";
  ui.skillEditorOrigin = importContent ? "imported" : "created";
  const form = elements.skillEditorForm;
  const sourceDocument = sourceDocumentId ? state.documents[sourceDocumentId] : null;
  const sourceBody = sourceDocument ? notebookDocumentSkillBody(sourceDocument) : "";
  const sourceDraftBody = String(sourceDraft?.body || "").trim();
  const sourceTitle = sourceDocument?.title || String(sourceDraft?.title || "").trim();
  const hasSource = Boolean(sourceDocument || sourceDraftBody);
  form.reset();
  setSkillEditorValidation(form);
  form.dataset.skillTriggerCompatibilityWarning = "false";
  setSkillTriggerCompatibilityStatus(form, false);
  document.querySelector("#skillPrototypeFields").hidden = true;
  form.dataset.sourceDocument = sourceDocumentId || "";
  form.elements.version.value = "1.0.0";
  setSkillFormCapabilities(form, []);
  document.querySelector("#skillEditorTitle").textContent = skillId ? "编辑为新版本" : sourceDocument ? "从笔记上传 Skill" : sourceDraftBody ? "从文字卡片上传 Skill" : "新建 Skill";
  document.querySelector("#skillEditorDescription").textContent = hasSource
    ? "来源正文已经填入下方 Markdown 指令。请补全注册信息；保存只执行本地静态校验，模型增强测试可以稍后单独运行。"
    : importContent ? "已自动识别 Markdown 中的注册信息。请核对缺失字段；必要时可使用 AI 自动提取。"
      : "先保存到本机并执行静态校验，不会因模型连接不可用而阻止创建。";
  const sourceLabel = document.querySelector("#skillEditorSource");
  sourceLabel.hidden = !hasSource;
  sourceLabel.textContent = sourceDocument ? `来源笔记：${sourceDocument.title}` : sourceDraftBody ? `来源白板文字卡片：${sourceTitle || "未命名卡片"}` : "";
  document.querySelector("#skillEditorSubmit").textContent = hasSource ? "保存为 Skill" : "保存 Skill";
  document.querySelector("#extractSkillWithAi").hidden = !importContent;
  if (skillId) {
    const response = await fetch("/api/skills/read", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: skillId, includeContent: true }) });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 读取失败");
    const skill = payload.skill;
    ui.skillEditorOrigin = ["imported", "downloaded"].includes(skill.origin) ? "imported" : "created";
    form.elements.id.value = skill.skillId;
    form.elements.id.readOnly = true;
    form.elements.version.value = incrementSkillVersion(skill.version);
    form.elements.name.value = skill.name;
    form.elements.author.value = skill.author;
    form.elements.description.value = skill.description;
    form.elements.prototypeId.value = skill.prototypeId || "";
    form.elements.prototypeName.value = skill.prototypeName || "";
    form.elements.prototypeFingerprint.value = skill.prototypeFingerprint || "";
    form.elements.derivativeCopy.value = skill.derivativeCopy ? "true" : "false";
    form.elements.upstreamId.value = skill.upstreamId || "";
    form.elements.upstreamVersion.value = skill.upstreamVersion || "";
    form.elements.changeSummary.value = skill.changeSummary || "";
    document.querySelector("#skillPrototypeFields").hidden = !skill.prototypeId;
    form.elements.capabilityBoundary.value = skill.capabilityBoundary || skill.description;
    form.elements.workspaceMode.value = skill.workspaceModes?.[0] || "";
    setSkillFormCapabilities(form, skill.capabilities ?? []);
    form.elements.triggerKeywords.value = (skill.triggerKeywords ?? []).join("，");
    form.elements.triggerConditions.value = (skill.triggerConditions ?? []).join("\n");
    form.elements.body.value = skill.body || "";
  } else if (importDraft) {
    applySkillDraftToForm(form, importDraft);
  } else {
    form.elements.id.readOnly = false;
    if (hasSource) {
      if (!(sourceDocument ? sourceBody : sourceDraftBody)) throw new Error("当前正文为空，无法上传为 Skill");
      form.elements.name.value = sourceTitle || "未命名 Skill";
      if (sourceDocument) {
        form.elements.workspaceMode.value = "notebook";
        form.elements.body.value = sourceBody;
      } else {
        form.elements.workspaceMode.value = state.workspaceKind === "notebook" ? "notebook" : "project";
        form.elements.body.value = sourceDraftBody;
      }
      setSkillFormCapabilities(form, ["custom_writer"]);
      form.elements.capabilityBoundary.value = "只根据当前来源正文和用户要求生成文本候选，不接管任务路由、其他本地文档读取、正史判断、记忆更新或文件落盘。";
    }
  }
  elements.skillEditorDialog.showModal();
  requestAnimationFrame(() => {
    elements.skillEditorDialog.scrollTop = 0;
    form.scrollTop = 0;
    form.elements.id.focus();
  });
};

const openSkillEditorFromNotebookDocument = async (documentId) => {
  const documentState = state.documents[documentId];
  if (state.workspaceKind !== "notebook" || !documentState || documentState.virtual || documentState.documentKind === "whiteboard") {
    throw new Error("只有普通笔记文档可以上传为 Skill");
  }
  await openSkillEditor("", { sourceDocumentId: documentId });
};

const openSkillEditorFromWhiteboardText = async (nodeId) => {
  const node = whiteboardNodeById(nodeId);
  const body = String(node?.text || "").trim();
  if (!node || ["image", "video", "audio", "group"].includes(node.kind) || !body) {
    throw new Error("只有包含正文的文字卡片可以上传为 Skill");
  }
  const title = body.split(/\r?\n/).map((line) => line.trim()).find(Boolean)?.slice(0, 80) || "未命名 Skill";
  await openSkillEditor("", { sourceDraft: { title, body } });
};

const skillSlotAllowedCapabilities = (groupId = "") => [...skillSlotGroupLineage(groupId)].reverse()
  .find((group) => group.fixed && (group.allowedCapabilities ?? []).length)?.allowedCapabilities ?? [];

const openSkillSlotEditor = async (slotId = "") => {
  await refreshSkillCatalog();
  const form = elements.skillSlotEditorForm;
  const slot = (ui.skillCatalog.customSlots ?? []).find((item) => item.id === slotId);
  const parentGroupId = slot?.parentGroupId ?? ui.skillSlotGroupId ?? "";
  const allowedCapabilities = skillSlotAllowedCapabilities(parentGroupId);
  ui.editingSlotId = slot?.id || null;
  form.reset();
  form.dataset.parentGroupId = parentGroupId;
  form.dataset.allowedCapabilities = allowedCapabilities.join(",");
  form.elements.id.readOnly = Boolean(slot);
  renderCapabilityChecklist("slotCapabilityChecklist", slot?.capabilities ?? [], allowedCapabilities);
  document.querySelector("#skillSlotEditorTitle").textContent = slot ? "编辑自定义插槽" : "新建自定义插槽";
  if (slot) {
    form.elements.id.value = slot.id;
    form.elements.name.value = slot.name;
    form.elements.description.value = slot.description;
    form.elements.workspaceMode.value = slot.workspaceModes?.[0] || "";
    form.elements.slotType.value = slot.slotType === "multi" ? "multi" : "single";
    form.elements.capabilityBoundary.value = slot.capabilityBoundary || "";
    form.elements.triggerKeywords.value = (slot.triggerKeywords ?? []).join("，");
    form.elements.triggerConditions.value = (slot.triggerConditions ?? []).join("\n");
    form.elements.enabled.checked = slot.enabled;
  }
  setSlotEditorSkillSelection(slot?.skillId || "");
  updateSlotTypeControls();
  renderSlotSecondarySkillSelectors(slot?.secondarySkillIds ?? ["", "", ""]);
  elements.skillSlotEditorDialog.showModal();
  requestAnimationFrame(() => form.elements.id.focus());
};

const customSlotPayload = (form) => {
  const data = Object.fromEntries(new FormData(form).entries());
  const capabilities = [...form.querySelectorAll('#slotCapabilityChecklist input[type="checkbox"]:checked')].map((input) => input.value);
  if (capabilities.length !== 1) throw new Error("一个插槽必须且只能对应一项能力");
  return {
    id: data.id,
    name: data.name,
    description: data.description,
    workspaceModes: [data.workspaceMode],
    slotType: data.slotType === "multi" ? "multi" : "single",
    capabilities,
    capabilityBoundary: data.capabilityBoundary,
    skillId: data.skillId,
    secondarySkillIds: data.slotType === "multi"
      ? [...form.querySelectorAll("[data-slot-secondary-skill]")].map((select) => select.value)
      : ["", "", ""],
    triggerKeywords: String(data.triggerKeywords || "").split(/[，,\n]/).map((item) => item.trim()).filter(Boolean),
    triggerConditions: String(data.triggerConditions || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean),
    enabled: form.elements.enabled.checked,
    parentGroupId: form.dataset.parentGroupId || "",
  };
};

const openSkillSlotGroupEditor = async (groupId = "") => {
  await refreshSkillCatalog();
  const form = elements.skillSlotGroupEditorForm;
  const group = (ui.skillCatalog.slotGroups ?? []).find((item) => item.id === groupId && !item.fixed);
  ui.editingSlotGroupId = group?.id || null;
  form.reset();
  form.dataset.parentGroupId = group?.parentGroupId ?? ui.skillSlotGroupId ?? "";
  form.elements.id.value = group?.id || "";
  form.elements.name.value = group?.name || "";
  form.elements.description.value = group?.description || "";
  form.elements.groupType.value = group?.groupType || "parallel";
  const directSlots = (ui.skillCatalog.customSlots ?? []).filter((slot) => slot.parentGroupId === group?.id);
  form.elements.leaderSlotId.innerHTML = `<option value="">暂不设置</option>${directSlots.map((slot) => `<option value="${escapeHtml(slot.id)}">${escapeHtml(slot.name)}</option>`).join("")}`;
  form.elements.leaderSlotId.value = group?.leaderSlotId || "";
  form.elements.leaderSlotId.disabled = form.elements.groupType.value !== "organization";
  document.querySelector("#skillSlotGroupEditorTitle").textContent = group ? "编辑插槽组" : "新建插槽组";
  elements.skillSlotGroupEditorDialog.showModal();
  requestAnimationFrame(() => form.elements.name.focus());
};

document.querySelector(".settings-navigation").addEventListener("click", async (event) => {
  const button = event.target.closest("[data-settings-section]");
  if (!button) return;
  ui.settingsSection = button.dataset.settingsSection;
  const requestedSection = ui.settingsSection;
  // Switch the visible page in the current event; expensive model/Skill and
  // localization work is initialized only after that state has painted.
  syncSettingsSectionVisibility();
  // Paint the Skill page synchronously on the first click. The catalog refresh
  // will replace this cached/loading view when it completes; the user should
  // never need to switch to another tab to force the first render.
  if (requestedSection === "skill") {
    renderSkillSettings();
    void refreshSkillCatalog();
  }
  scheduleUiInitializationAfterPaint(async () => {
    if (ui.settingsSection !== requestedSection || !elements.settingsDialog.open) return;
    renderSettingsSection();
    if (requestedSection === "skill" && !ui.skillCatalog.loading) await refreshSkillCatalog();
    if (requestedSection === "experience") await refreshExperienceManager();
    if (["basic", "sync"].includes(requestedSection)) await refreshStorageStatus();
    if (requestedSection === "sync") await refreshNutstoreSync();
  }, { timeout: 140 });
});

document.querySelector("#reloadExperiences").addEventListener("click", () => void refreshExperienceManager());
document.querySelector("#mergeSelectedExperiences").addEventListener("click", (event) => void mergeSelectedExperiencesFromDesktop(event.currentTarget));
document.querySelector("#filterExperiences").addEventListener("click", () => renderExperienceManager());
document.querySelector("#experienceStatusFilter").addEventListener("change", () => void refreshExperienceManager());
document.querySelector("#experienceViewFilter").addEventListener("change", (event) => {
  ui.automation.experienceView = event.target.value;
  renderExperienceManager();
});
document.querySelector("#experienceSearchFilter").addEventListener("keydown", (event) => {
  if (event.key !== "Enter") return;
  event.preventDefault();
  renderExperienceManager();
});
document.querySelector("#experienceList").addEventListener("click", (event) => {
  const selectInput = event.target.closest("[data-select-experience]");
  if (selectInput) {
    const selected = new Set(ui.automation.experienceSelectedIds ?? []);
    if (selectInput.checked) selected.add(selectInput.dataset.selectExperience);
    else selected.delete(selectInput.dataset.selectExperience);
    ui.automation.experienceSelectedIds = [...selected];
    renderExperienceManager();
    return;
  }
  const revokeButton = event.target.closest("[data-revoke-experience]");
  if (revokeButton) void revokeExperienceFromDesktop(revokeButton.dataset.revokeExperience, revokeButton);
  const restoreButton = event.target.closest("[data-restore-experience]");
  if (restoreButton) void restoreExperienceFromDesktop(restoreButton.dataset.restoreExperience, restoreButton);
  const resumeButton = event.target.closest("[data-resume-experience]");
  if (resumeButton) void resumeExperienceFromDesktop(resumeButton.dataset.resumeExperience, resumeButton);
  const feedbackButton = event.target.closest("[data-experience-feedback]");
  if (feedbackButton) void submitExperienceFeedbackFromDesktop({
    recordId: feedbackButton.dataset.experienceId,
    useId: feedbackButton.dataset.experienceUse,
    taskId: feedbackButton.dataset.experienceTask,
    outcome: feedbackButton.dataset.experienceFeedback,
    button: feedbackButton,
  });
  const promoteButton = event.target.closest("[data-promote-experience]");
  if (promoteButton) void promoteExperienceFromDesktop(promoteButton.dataset.promoteExperience, promoteButton);
  const editButton = event.target.closest("[data-edit-experience]");
  if (editButton) void updateExperienceClassificationFromDesktop(editButton.dataset.editExperience, "facets", editButton);
  const scopeButton = event.target.closest("[data-scope-experience]");
  if (scopeButton) void updateExperienceClassificationFromDesktop(scopeButton.dataset.scopeExperience, "scope", scopeButton);
  const splitButton = event.target.closest("[data-split-experience]");
  if (splitButton) void splitExperienceFromDesktop(splitButton.dataset.splitExperience, splitButton);
  const retryButton = event.target.closest("[data-retry-experience-job]");
  if (retryButton) void retryExperienceCollectionFromDesktop(retryButton.dataset.retryExperienceJob, retryButton);
});

