document.querySelector("#closeSettingsHistory").addEventListener("click", () => elements.settingsHistoryDialog.close());
document.querySelector("#closeSettingsHistoryFooter").addEventListener("click", () => elements.settingsHistoryDialog.close());
elements.settingsHistoryDialog.addEventListener("click", (event) => {
  if (event.target === elements.settingsHistoryDialog) {
    elements.settingsHistoryDialog.close();
    return;
  }
  const deleteButton = event.target.closest("[data-settings-history-delete]");
  if (deleteButton) {
    const scope = ui.settingsHistoryScope;
    if (!window.confirm(uiText(`删除这份${SETTINGS_HISTORY_LABELS[scope]}本地快照？当前设置不会改变，此操作无法撤销。`))) return;
    try {
      const result = deleteSettingsHistoryVersion(globalUiPreferences.settingsHistories, scope, deleteButton.dataset.settingsHistoryDelete, globalUiPreferences);
      globalUiPreferences = normalizedUiPreferences({ ...globalUiPreferences, settingsHistories: result.history });
      state.settings.settingsHistories = globalUiPreferences.settingsHistories;
      persistUiPreferences();
      persist();
      renderSettingsHistory();
      showToast(`${SETTINGS_HISTORY_LABELS[scope]}快照已删除`);
    } catch (error) {
      showToast(error.message || "设置历史版本删除失败");
    }
    return;
  }
  const versionId = event.target.closest("[data-settings-history-restore]")?.dataset.settingsHistoryRestore;
  if (!versionId) return;
  const scope = ui.settingsHistoryScope;
  if (!window.confirm(uiText(`恢复这份${SETTINGS_HISTORY_LABELS[scope]}？当前设置仍会保留，并生成新的当前版本。`))) return;
  try {
    const restored = restoreSettingsHistoryVersion(globalUiPreferences.settingsHistories, scope, versionId, globalUiPreferences);
    applyRestoredSettingsSnapshot(scope, restored.snapshot, restored.history);
    renderSettingsHistory();
    showToast(`${SETTINGS_HISTORY_LABELS[scope]}已恢复为新的当前版本`);
  } catch (error) {
    showToast(error.message || "设置历史版本恢复失败");
  }
});

