elements.customThemeDialog.addEventListener("close", () => {
  if (!ui.customThemeDraft) return;
  ui.customThemeDraft = null;
  ui.customThemeEditingId = "";
  previewSelectedSettingsTheme();
});
elements.customThemeForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const themes = ui.customThemesDraft ?? [];
  const draft = normalizeCustomTheme(ui.customThemeDraft ?? DEFAULT_CUSTOM_THEME);
  const now = Date.now();
  const nowIso = new Date(now).toISOString();
  const current = ui.customThemeEditingId ? themes.find((theme) => theme.id === ui.customThemeEditingId) : null;
  const record = current
    ? {
        ...current,
        ...draft,
        name: draft.name || current.name || "自定义主题",
        version: current.version + 1,
        updatedAtIso: nowIso,
      }
    : {
        id: createCustomThemeRecordId(),
        ...draft,
        name: draft.name || `自定义主题 ${themes.length + 1}`,
        version: 1,
        createdAtIso: nowIso,
        updatedAtIso: nowIso,
      };
  ui.customThemesDraft = current
    ? themes.map((theme) => theme.id === current.id ? record : theme)
    : [...themes, record];
  ui.customThemeHistoriesDraft = {
    ...(ui.customThemeHistoriesDraft ?? {}),
    [record.id]: appendCustomThemeVersion(ui.customThemeHistoriesDraft?.[record.id], record, { reason: current ? "edited" : "created", now }),
  };
  ui.activeCustomThemeIdDraft = record.id;
  ui.customThemeDraft = null;
  ui.customThemeEditingId = "";
  renderCustomThemeChoices("custom");
  persistCustomThemeCatalogDraft();
  previewSelectedSettingsTheme();
  closeCustomThemeDialog();
  showToast(current ? "主题修改已保存为新版本；点击“保存设置”后应用到界面" : "主题方案已保存；点击“保存设置”后应用到界面");
});

