const compositeRelationLabel = (relationType) => ({
  parallel: uiText("并行"),
  "primary-secondary": uiText("主次"),
  organization: uiText("组织"),
}[relationType] || uiText("并行"));

const compositeRelationSourceLabel = (source) => ({
  manifest: uiText("Manifest 明确声明"),
  "legacy-manifest": uiText("旧版 Manifest 仅声明类型"),
  "child-metadata": uiText("子 Skill 角色声明"),
  directory: uiText("目录结构推断"),
  "name-description": uiText("名称与用途推断"),
  body: uiText("正文弱证据"),
  default: uiText("无证据，默认建议"),
  "author-confirmed": uiText("作者确认"),
}[source] || source || uiText("无证据，默认建议"));

const emptySkillPackageImport = () => ({
  sourceKind: "file",
  fileName: "",
  base64: "",
  snapshotId: "",
  selectedType: "",
  analysis: null,
  installing: false,
  error: "",
});

const emptyGithubSkillImport = (url = "") => ({
  url,
  snapshot: null,
  selectedType: "",
  packageHash: "",
  analysis: null,
  loading: false,
  installing: false,
  error: "",
});

const githubSkillTypeLabel = (type = "") => ({
  skill: "单一 Skill",
  module: "模块",
  group: "模组",
}[type] || "Skill");

const renderGithubSkillImport = () => {
  const current = ui.githubSkillImport;
  const snapshot = current.snapshot;
  const input = document.querySelector("#githubSkillUrl");
  const analyze = document.querySelector("#analyzeGithubSkill");
  const status = document.querySelector("#githubSkillStatus");
  const analysisPanel = document.querySelector("#githubSkillAnalysis");
  const confirm = document.querySelector("#confirmGithubSkill");
  if (!input || !analyze || !status || !analysisPanel || !confirm) return;
  input.value = current.url;
  input.disabled = current.loading || current.installing;
  analyze.disabled = current.loading || current.installing || !current.url.trim();
  analyze.textContent = current.loading ? "正在读取…" : "读取链接";
  status.textContent = current.error
    || (current.loading ? "正在下载并安全分析 GitHub Skill…" : snapshot ? `已锁定提交并识别 ${snapshot.skillCount || 0} 个 Skill。` : "粘贴链接后先读取结构，确认类型后才会安装。") ;
  status.classList.toggle("error", Boolean(current.error));
  analysisPanel.hidden = !snapshot;
  confirm.disabled = current.loading || current.installing || !current.analysis || !snapshot;
  confirm.textContent = current.installing
    ? "正在安装…"
    : current.analysis?.composite
      ? "预览关系并安装"
      : "确认并安装";
  if (!snapshot) return;
  document.querySelector("#githubSkillRepository").textContent = `${snapshot.owner}/${snapshot.repository}`;
  document.querySelector("#githubSkillCommit").textContent = String(snapshot.resolvedCommit || "").slice(0, 12);
  document.querySelector("#githubSkillCount").textContent = `${snapshot.skillCount || 0} 项`;
  const typeSelect = document.querySelector("#githubSkillType");
  typeSelect.innerHTML = (snapshot.compatibleTypes || []).map((type) => `<option value="${escapeHtml(type)}" ${type === current.selectedType ? "selected" : ""}>${escapeHtml(githubSkillTypeLabel(type))}${type === snapshot.recommendedType ? "（智能推荐）" : ""}</option>`).join("");
  typeSelect.disabled = current.loading || current.installing;
  document.querySelector("#githubSkillRecommendation").innerHTML = `<strong>智能判断：${escapeHtml(githubSkillTypeLabel(snapshot.recommendedType))}</strong><span>当前可选择：${escapeHtml((snapshot.compatibleTypes || []).map(githubSkillTypeLabel).join("、"))}。模块与模组安装前还需逐层确认内部关系。</span>`;
  const identified = [snapshot.root ? { ...snapshot.root, root: true } : null, ...(snapshot.children || [])].filter(Boolean);
  document.querySelector("#githubSkillChildren").innerHTML = identified.map((skill) => `<article><span class="skill-setting-icon">${icon(skill.root ? "\uE8F1" : "\uE943")}</span><div><strong>${escapeHtml(skill.name || "未命名 Skill")}${skill.root ? " · 总控" : ""}</strong><p>${escapeHtml(skill.description || "未填写说明")}</p><small>${escapeHtml(skill.family || "辅助参考能力")} · ${escapeHtml(skill.sourcePath || "SKILL.md")}</small></div></article>`).join("") || `<p class="settings-empty">未能读取 Skill 名称，请重新选择更具体的子目录。</p>`;
};

const openGithubSkillImport = () => {
  ui.githubSkillImport = emptyGithubSkillImport();
  renderGithubSkillImport();
  const dialog = document.querySelector("#githubSkillDialog");
  dialog.showModal();
  requestAnimationFrame(() => document.querySelector("#githubSkillUrl")?.focus());
};

const analyzeGithubSkillUrl = async () => {
  if (ui.githubSkillImport.loading || ui.githubSkillImport.installing) return;
  const url = document.querySelector("#githubSkillUrl")?.value.trim() || "";
  ui.githubSkillImport = { ...emptyGithubSkillImport(url), loading: true };
  renderGithubSkillImport();
  try {
    const response = await fetch("/api/skills/github/analyze", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ url }),
    });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "GitHub Skill 分析失败");
    ui.githubSkillImport = {
      url,
      snapshot: payload.snapshot,
      selectedType: payload.selectedType,
      packageHash: payload.packageHash,
      analysis: payload.analysis,
      loading: false,
      installing: false,
      error: "",
    };
  } catch (error) {
    ui.githubSkillImport = { ...emptyGithubSkillImport(url), error: error.message || "GitHub Skill 分析失败" };
  }
  renderGithubSkillImport();
};

const prepareGithubSkillType = async (type) => {
  const current = ui.githubSkillImport;
  if (!current.snapshot || current.loading || current.installing || type === current.selectedType) return;
  ui.githubSkillImport = { ...current, selectedType: type, analysis: null, packageHash: "", loading: true, error: "" };
  renderGithubSkillImport();
  try {
    const response = await fetch("/api/skills/github/prepare", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ snapshotId: current.snapshot.snapshotId, type }),
    });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "GitHub Skill 结构准备失败");
    ui.githubSkillImport = { ...ui.githubSkillImport, selectedType: payload.selectedType, packageHash: payload.packageHash, analysis: payload.analysis, loading: false, error: "" };
  } catch (error) {
    ui.githubSkillImport = { ...ui.githubSkillImport, loading: false, error: error.message || "GitHub Skill 结构准备失败" };
  }
  renderGithubSkillImport();
};

const renderSkillPackagePreviewTree = (node, depth = 0) => {
  if (!node) return "";
  const type = node.nodeType === "skill" ? "Skill" : node.nodeType === "group" ? uiText("模组") : uiText("模块");
  return `<li style="--tree-depth:${depth}"><span><i>${escapeHtml(type)}</i><strong>${escapeHtml(node.name || node.id)}</strong>${node.relationType ? `<small>${escapeHtml(compositeRelationLabel(node.relationType))}</small>` : ""}</span>${node.children?.length ? `<ul>${node.children.map((child) => renderSkillPackagePreviewTree(child, depth + 1)).join("")}</ul>` : ""}</li>`;
};

const renderSkillPackagePreview = () => {
  const dialog = document.querySelector("#skillPackagePreviewDialog");
  const body = document.querySelector("#skillPackagePreviewBody");
  const status = document.querySelector("#skillPackagePreviewStatus");
  const confirm = document.querySelector("#confirmSkillPackageImport");
  const analysis = ui.skillPackageImport.analysis;
  if (!analysis) return;
  document.querySelector("#skillPackagePreviewTitle").textContent = analysis.skill?.name || uiText("确认能力结构与关系");
  document.querySelector("#skillPackagePreviewDescription").textContent = `${analysis.skill?.childCount || 0} ${uiText("个子 Skill；确认后才会事务化安装。")}`;
  const conflicts = Array.isArray(analysis.conflicts) ? analysis.conflicts : [];
  const relationCards = (analysis.relations || []).map((decision) => {
    const confidence = Math.round((Number(decision.confidence) || 0) * 100);
    const confidenceBand = confidence >= 90 ? "high" : confidence >= 60 ? "medium" : "low";
    const leaderRole = decision.relationType === "organization" ? uiText("选择上位节点") : uiText("选择主要节点");
    const memberChoices = (decision.members || []).map((member, index) => `<label><input type="radio" name="relation-leader-${escapeHtml(decision.scopeId)}" value="${escapeHtml(member.ref)}" ${index === 0 ? "checked" : ""} /><span>${escapeHtml(member.name || member.ref)}</span></label>`).join("");
    return `<article class="skill-package-relation-card" data-composite-relation-scope="${escapeHtml(decision.scopeId)}">
      <header><div><small>${escapeHtml(decision.scopeKind === "group" ? uiText("模组关系") : uiText("模块关系"))}</small><strong>${escapeHtml(decision.label || decision.scopePath)}</strong></div><span class="relation-confidence ${confidenceBand}">${confidence}%</span></header>
      <label class="relation-type-field"><span>${escapeHtml(uiText("关系类型"))}</span><select data-composite-relation-type><option value="parallel" ${decision.relationType === "parallel" ? "selected" : ""}>${escapeHtml(uiText("并行"))}</option><option value="primary-secondary" ${decision.relationType === "primary-secondary" ? "selected" : ""}>${escapeHtml(uiText("主次"))}</option><option value="organization" ${decision.relationType === "organization" ? "selected" : ""}>${escapeHtml(uiText("组织"))}</option></select></label>
      <fieldset class="relation-leader-field" ${decision.relationType === "parallel" ? "hidden" : ""}><legend>${escapeHtml(leaderRole)}</legend>${memberChoices}</fieldset>
      <details><summary>${escapeHtml(uiText("为什么这样识别"))}</summary><p>${escapeHtml(compositeRelationSourceLabel(decision.source))}</p>${(decision.evidence || []).length ? `<ul>${decision.evidence.map((item) => `<li>${escapeHtml(item.value || item.kind)}</li>`).join("")}</ul>` : ""}${(decision.conflicts || []).length ? `<ul class="relation-conflict-list">${decision.conflicts.map((message) => `<li>${escapeHtml(message)}</li>`).join("")}</ul>` : ""}</details>
    </article>`;
  }).join("");
  body.innerHTML = `<section class="skill-package-analysis-summary"><div><small>${escapeHtml(uiText("包哈希"))}</small><code>${escapeHtml(String(analysis.packageHash || "").slice(0, 16))}…</code></div><div><small>${escapeHtml(uiText("拓扑哈希"))}</small><code>${escapeHtml(String(analysis.topologyHash || "").slice(0, 16))}…</code></div><div><small>${escapeHtml(uiText("关系分析器"))}</small><strong>${escapeHtml(analysis.inferenceVersion || "2.0.0")}</strong></div></section>
    ${conflicts.length ? `<section class="skill-package-conflicts" role="alert"><strong>${escapeHtml(uiText("发现需要确认的关系冲突"))}</strong><ul>${conflicts.map((item) => `<li>${escapeHtml(item.message || String(item))}</li>`).join("")}</ul></section>` : ""}
    <section class="skill-package-tree"><header><strong>${escapeHtml(uiText("包内能力结构"))}</strong><small>${escapeHtml(uiText("节点顺序决定主要、上位和并行关系的运行含义。"))}</small></header><ul>${renderSkillPackagePreviewTree(analysis.tree)}</ul></section>
    <section class="skill-package-relations"><header><strong>${escapeHtml(uiText("逐层确认关系"))}</strong><small>${escapeHtml(uiText("绿色可直接核对；黄色和红色必须检查识别依据。"))}</small></header>${relationCards}</section>`;
  status.textContent = ui.skillPackageImport.error || uiText("尚未写入任何 Skill；确认后一次性提交结构和注册表。") ;
  status.classList.toggle("error", Boolean(ui.skillPackageImport.error));
  confirm.disabled = ui.skillPackageImport.installing || !(analysis.relations || []).length;
  confirm.textContent = ui.skillPackageImport.installing ? uiText("正在事务化导入…") : uiText("确认并导入");
  if (!dialog.open) dialog.showModal();
};

const confirmedCompositeRelationsFromPreview = () => (ui.skillPackageImport.analysis?.relations || []).map((decision) => {
  const card = document.querySelector(`[data-composite-relation-scope="${CSS.escape(decision.scopeId)}"]`);
  const relationType = card?.querySelector("[data-composite-relation-type]")?.value || decision.relationType || "parallel";
  const originalOrder = (decision.orderedMembers || []).filter(Boolean);
  if (relationType === "parallel") return { scopeId: decision.scopeId, relationType, orderedMembers: originalOrder };
  const leader = card?.querySelector('input[type="radio"]:checked')?.value || originalOrder[0];
  return { scopeId: decision.scopeId, relationType, orderedMembers: [leader, ...originalOrder.filter((ref) => ref !== leader)].filter(Boolean) };
});

const completeSkillPackageImport = async (payload, fileName, sourceKind = "file") => {
  await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
  const actionLabel = sourceKind === "github" ? "已从 GitHub 安装" : uiText("已确认关系并事务化导入");
  if (payload.composite && payload.asset?.id) {
    showToast(`${actionLabel}：${payload.skill?.name || fileName}`);
    await openSkillDetail({ kind: "capability-asset", id: payload.asset.id });
  } else {
    showToast(`${sourceKind === "github" ? "已从 GitHub 安装" : uiText("已导入完整 Skill 包")}：${payload.skill?.name || fileName}`);
  }
};

const closeGithubSkillImport = () => {
  if (ui.githubSkillImport.loading || ui.githubSkillImport.installing) return;
  document.querySelector("#githubSkillDialog").close();
  ui.githubSkillImport = emptyGithubSkillImport();
};

document.querySelector("#githubSkillUrl").addEventListener("input", (event) => {
  const url = event.target.value;
  if (url === ui.githubSkillImport.url) return;
  ui.githubSkillImport = emptyGithubSkillImport(url);
  document.querySelector("#githubSkillAnalysis").hidden = true;
  document.querySelector("#githubSkillStatus").textContent = "粘贴链接后先读取结构，确认类型后才会安装。";
  document.querySelector("#githubSkillStatus").classList.remove("error");
  document.querySelector("#analyzeGithubSkill").disabled = !url.trim();
  document.querySelector("#confirmGithubSkill").disabled = true;
});
