document.querySelector("#closeSkillDetail").addEventListener("click", () => elements.skillDetailDialog.close());
document.querySelector("#closeSkillDetailFooter").addEventListener("click", () => elements.skillDetailDialog.close());
document.querySelector("#closeSkillHistory").addEventListener("click", () => elements.skillHistoryDialog.close());
document.querySelector("#closeSkillHistoryFooter").addEventListener("click", () => elements.skillHistoryDialog.close());
elements.skillHistoryDialog.addEventListener("click", async (event) => {
  if (event.target === elements.skillHistoryDialog) {
    elements.skillHistoryDialog.close();
    return;
  }
  const marketplaceInstall = event.target.closest("[data-marketplace-version-install]");
  if (marketplaceInstall && ui.skillHistoryKind === "marketplace" && !marketplaceInstall.disabled) {
    const item = marketplaceCatalogItemById(ui.skillHistoryId);
    if (item?.installed && !window.confirm(uiText("本地已有这个项目。下载所选云端版本会替换本地版本链，只保留所选版本；请先导出需要保留的本地版本。是否继续？"))) return;
    marketplaceInstall.disabled = true;
    const previousLabel = marketplaceInstall.textContent;
    marketplaceInstall.textContent = "下载中";
    try {
      const response = await fetch("/api/skill-marketplace/install", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: marketplaceInstall.dataset.marketplaceVersionInstall, replaceLocalVersions: true }),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw new Error(payload.message || "广场历史版本下载失败");
      await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
      renderSkillHistory();
      showToast("所选云端版本已下载，本地仅保留这一版本");
    } catch (error) {
      marketplaceInstall.disabled = false;
      marketplaceInstall.textContent = previousLabel;
      showToast(error.message || "广场历史版本下载失败");
    }
    return;
  }
  const marketplaceDelete = event.target.closest("[data-marketplace-version-delete]");
  if (marketplaceDelete && ui.skillHistoryKind === "marketplace") {
    if (!window.confirm(uiText("永久删除这个由你发布的云端版本？下载者的本地副本不会被删除，此操作无法撤销。"))) return;
    marketplaceDelete.disabled = true;
    try {
      const response = await fetch("/api/skill-marketplace/publication", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: marketplaceDelete.dataset.marketplaceVersionDelete }),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw new Error(payload.message || "云端版本删除失败");
      await refreshSkillCatalog({ force: true });
      if (!renderSkillHistory()) elements.skillHistoryDialog.close();
      renderSkillSettings();
      showToast("云端发布版本已删除");
    } catch (error) {
      marketplaceDelete.disabled = false;
      showToast(error.message || "云端版本删除失败");
    }
    return;
  }
  const capabilityDelete = event.target.closest("[data-capability-asset-history-delete]");
  if (capabilityDelete && ui.skillHistoryKind === "capability-asset" && !capabilityDelete.disabled) {
    if (!window.confirm(uiText("删除这个本地能力资产版本？当前面板不会改变，此操作无法撤销。"))) return;
    capabilityDelete.disabled = true;
    try {
      const response = await fetch("/api/skills/capability-assets/versions", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: ui.skillHistoryId, version: capabilityDelete.dataset.capabilityAssetHistoryDelete }),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw new Error(payload.message || "能力资产版本删除失败");
      await refreshSkillCatalog({ force: true });
      renderSkillHistory();
      showToast("本地能力资产版本已删除");
    } catch (error) {
      capabilityDelete.disabled = false;
      showToast(error.message || "能力资产版本删除失败");
    }
    return;
  }
  const versionDelete = event.target.closest("[data-skill-history-delete]");
  if (versionDelete && ui.skillHistoryKind === "mine" && !versionDelete.disabled) {
    const active = String((ui.skillCatalog.user ?? []).find((item) => item.id === ui.skillHistoryId)?.version ?? "") === String(versionDelete.dataset.skillHistoryDelete);
    const copy = active
      ? "删除正在使用的本地版本？Skill 会自动切换到最近保留版本，此操作无法撤销。"
      : "删除这个本地 Skill 版本？此操作无法撤销。";
    if (!window.confirm(uiText(copy))) return;
    versionDelete.disabled = true;
    try {
      const response = await fetch("/api/skills/versions", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: ui.skillHistoryId, version: versionDelete.dataset.skillHistoryDelete }),
      });
      const payload = await response.json();
      if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 历史版本删除失败");
      await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
      renderSkillHistory();
      showToast(payload.activeChanged ? "版本已删除，Skill 已切换到最近保留版本" : "本地 Skill 版本已删除");
    } catch (error) {
      versionDelete.disabled = false;
      showToast(error.message || "Skill 历史版本删除失败");
    }
    return;
  }
  const capabilityDetail = event.target.closest("[data-capability-asset-history-detail]");
  if (capabilityDetail && ui.skillHistoryKind === "capability-asset") {
    elements.skillHistoryDialog.close();
    await openSkillDetail({ kind: "capability-asset", id: ui.skillHistoryId, version: capabilityDetail.dataset.capabilityAssetHistoryDetail })
      .catch((error) => showToast(error.message || "能力资产历史版本读取失败"));
    return;
  }
  const detail = event.target.closest("[data-skill-history-detail]");
  if (detail) {
    elements.skillHistoryDialog.close();
    const marketplace = ui.skillHistoryKind === "marketplace";
    const official = ui.skillHistoryKind === "official";
    await openSkillDetail({
      kind: marketplace ? "marketplace" : official ? "official" : "mine",
      id: marketplace ? detail.dataset.skillHistoryDetail : ui.skillHistoryId,
      version: marketplace || official ? "" : detail.dataset.skillHistoryDetail,
    }).catch((error) => showToast(error.message || "Skill 历史版本读取失败"));
    return;
  }
  const restore = event.target.closest("[data-skill-history-restore]");
  if (!restore || restore.disabled || ui.skillHistoryKind === "marketplace") return;
  const version = restore.dataset.skillHistoryRestore;
  if (!window.confirm(uiText(`将 Skill 恢复到 v${version}？当前版本仍会保留在历史记录中。`))) return;
  restore.disabled = true;
  try {
    const response = await fetch("/api/skills/versions/restore", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: ui.skillHistoryId, version }) });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.message || "Skill 历史版本恢复失败");
    await Promise.all([refreshSkillCatalog({ force: true }), refreshSkillLibrary({ force: true })]);
    renderSkillHistory();
    showToast(`已恢复到 v${version}；任务路由已更新`);
  } catch (error) {
    restore.disabled = false;
    showToast(error.message || "Skill 历史版本恢复失败");
  }
});
