elements.skillEditorForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const submit = elements.skillEditorForm.querySelector('[type="submit"]');
  const returnToTemplateManagement = ui.skillSettingsTab === "slots" && Boolean(ui.editingSkillId);
  setSkillEditorValidation(elements.skillEditorForm);
  submit.disabled = true;
  try {
    const republish = ui.marketplaceRepublish?.assetType === "skill" ? { ...ui.marketplaceRepublish } : null;
    const skillDraft = buildSkillMarkdown(elements.skillEditorForm);
    const tested = await installAndTestSkill(skillDraft.content);
    elements.skillEditorDialog.close();
    if (republish) {
      ui.marketplaceRepublish = null;
      try {
        await shareSkillToMarketplaceById(tested.skill.id);
        ui.skillSettingsTab = "marketplace";
        ui.skillMarketplaceView = "published";
        document.querySelectorAll("[data-skill-settings-tab]").forEach((button) => button.classList.toggle("active", button.dataset.skillSettingsTab === "marketplace"));
        renderSkillSettings();
        showToast(`${tested.skill.name} 已保存并发布到本机广场，尚未上传云端；旧版本仍可查看`);
      } catch (publishError) {
        showToast(`Skill 新版本已保存在本机，但发布失败：${publishError.message || "请稍后重试"}`);
      }
      return;
    }
    if (ui.reopenSkillPickerAfterCreate) {
      ui.reopenSkillPickerAfterCreate = false;
      await refreshSkillCatalog({ force: true });
      await openSkillPicker(ui.skillPicker);
    } else {
      ui.skillSettingsTab = returnToTemplateManagement ? "slots" : "custom";
      document.querySelectorAll("[data-skill-settings-tab]").forEach((button) => button.classList.toggle("active", button.dataset.skillSettingsTab === ui.skillSettingsTab));
      renderSkillSettings();
    }
    const compatibilityNote = skillDraft.triggerCompatibilityWarning ? "；已忽略不受支持的自然语言触发条件或过短关键词" : "";
    showToast(tested.test.passed ? `Skill 已保存并通过静态校验${compatibilityNote}` : `Skill 已保存；${tested.test.summary}${compatibilityNote}`);
  } catch (error) {
    const failure = uiText(error.message || "Skill 保存失败");
    const prefix = uiText("Skill 保存失败");
    const message = failure === prefix ? prefix : `${prefix}：${failure}`;
    setSkillEditorValidation(elements.skillEditorForm, { message });
    showToast(message);
  } finally {
    submit.disabled = false;
  }
});

