elements.skillSettingsContent.addEventListener("change", (event) => {
  if (event.target.id === "skillMarketplaceCapabilityFilter") ui.skillMarketplaceCapability = event.target.value;
  else if (event.target.id === "skillMarketplaceModeFilter") ui.skillMarketplaceMode = event.target.value;
  else if (event.target.id === "skillMarketplaceAssetTypeFilter") ui.skillMarketplaceAssetType = event.target.value;
  else return;
  applyMarketplaceFilters();
});

elements.skillSettingsContent.addEventListener("contextmenu", (event) => {
  const fixedSkill = event.target.closest("[data-fixed-skill-detail][data-skill-context-id]");
  if (fixedSkill && ui.skillSettingsTab === "slots") {
    showSkillContextMenu(event, {
      id: fixedSkill.dataset.skillContextId,
      kind: fixedSkill.dataset.skillContextKind || fixedSkill.dataset.fixedSkillDetailKind || "mine",
    });
    return;
  }
  const capabilitySkill = event.target.closest("[data-capability-skill-context-id]");
  if (capabilitySkill && ui.skillSettingsTab === "slots") {
    showSkillContextMenu(event, {
      id: capabilitySkill.dataset.capabilitySkillContextId,
      kind: capabilitySkill.dataset.capabilitySkillContextKind || "mine",
      meta: {
        slotId: capabilitySkill.dataset.capabilitySlotId || "",
        moduleId: capabilitySkill.dataset.templateModuleId || "",
        kernelManaged: capabilitySkill.dataset.capabilityKernelManaged === "true",
      },
    });
    return;
  }
  const capabilityNode = event.target.closest("[data-capability-node-context-type][data-capability-node-context-id]");
  if (capabilityNode && ui.skillSettingsTab === "slots") {
    showCapabilityContextMenu(event, capabilityNode.dataset.capabilityNodeContextType, capabilityNode.dataset.capabilityNodeContextId, {
      placementId: capabilityNode.dataset.capabilityPlacementId || "",
    });
    return;
  }
  const marketplaceCard = event.target.closest("[data-marketplace-skill-id]");
  if (marketplaceCard && ui.skillSettingsTab === "marketplace") {
    const marketplaceSkill = [
      ...(ui.skillCatalog.marketplace?.items ?? []),
      ...(ui.skillCatalog.marketplace?.myPublications ?? []),
    ].find((item) => item.id === marketplaceCard.dataset.marketplaceSkillId);
    showSkillContextMenu(event, {
      id: marketplaceCard.dataset.marketplaceSkillId || "",
      kind: "marketplace",
      meta: {
        assetType: marketplaceCard.dataset.marketplaceAssetType || "skill",
        installedSkillId: marketplaceSkill?.installedSkillId || "",
        installedAssetId: marketplaceSkill?.installedAssetId || "",
        publishedByUser: marketplaceCard.dataset.marketplacePublishedByUser === "true",
        publicationStatus: marketplaceCard.dataset.marketplacePublicationStatus || "published",
      },
    });
    return;
  }
  const capabilityAsset = event.target.closest("[data-capability-asset-id]");
  if (capabilityAsset && ui.skillSettingsTab === "custom") {
    const asset = (ui.skillCatalog.capabilityAssets ?? []).find((item) => item.id === capabilityAsset.dataset.capabilityAssetId);
    showSkillContextMenu(event, { id: asset?.id || "", kind: "capability-asset", meta: asset || null });
    return;
  }
  const row = event.target.closest(".user-skill-row[data-skill-id]");
  if (!row || ui.skillSettingsTab !== "custom") return;
  showSkillContextMenu(event, {
    id: row.dataset.skillDetailId || row.dataset.skillId || "",
    kind: row.dataset.skillDetailKind || "mine",
  });
});

