let settingsOpenPromise = null;

const openSettingsDialog = async () => {
  if (elements.settingsDialog.open) {
    elements.settingsDialog.focus();
    return;
  }
  if (settingsOpenPromise) return settingsOpenPromise;
  elements.settingsDialog.setAttribute("aria-busy", "true");
  elements.settingsDialog.inert = true;
  elements.settingsDialog.showModal();
  settingsOpenPromise = (async () => {
    // Let the native dialog paint before building model, Skill and shortcut
    // controls. On large whiteboards the old synchronous path made the click
    // appear ignored for 200–300 ms even though the handler had already run.
    await new Promise((resolvePaint) => scheduleUiInitializationAfterPaint(resolvePaint, { timeout: 180 }));
    beginSettingsThemePreview();
    beginSettingsUiLanguagePreview();
    ui.generationDraftSettings = normalizeGenerationProfiles(
      clone(state.settings),
      mergeGenerationSecrets(storedGenerationSecrets(), generationSecrets(state.settings)),
    );
    ui.generationBaselineActiveIds = Object.fromEntries(["text", "image", "video", "audio"].map((channel) => [channel, state.settings[generationProfileKeys(channel).active] || ""]));
    ui.skillSlotBindingsDraft = clone(state.settings.skillSlotBindings ?? {});
    ui.capabilityTemplateDirty = false;
    ui.capabilityTemplatePath = [];
    ui.capabilityTemplateDraft = ui.skillCatalog.capabilityTemplate?.current
      ? normalizeCapabilityTemplate(ui.skillCatalog.capabilityTemplate.current)
      : null;
    const form = elements.settingsForm.elements;
    Object.entries(state.settings).forEach(([key, value]) => {
      if (form[key]) form[key].value = value;
    });
    if (form.pauseVideoWhenClickOutside) form.pauseVideoWhenClickOutside.checked = globalUiPreferences.pauseVideoWhenClickOutside !== false;
    renderCustomThemeChoices(state.settings.themePreference);
    refreshGenerationSettingsForm();
    renderShortcutSettings();
    syncTypographyOutputs();
    syncModelCapabilityControls();
    renderTextConnectionTestStatus();
    renderSettingsSection();
    localizeUi(elements.settingsDialog, globalUiPreferences.uiLanguage);
    elements.settingsDialog.removeAttribute("aria-busy");
    elements.settingsDialog.inert = false;
    // Library/storage discovery is not required for the first usable settings
    // frame. Let subsequent navigation clicks win; each destination page also
    // has its own explicit refresh path if the user opens it immediately.
    scheduleUiBackgroundTask(() => {
      if (!elements.settingsDialog.open) return;
      void (async () => {
        await Promise.all([refreshSkillLibrary(), refreshSkillCatalog(), refreshStorageStatus()]);
        if (!elements.settingsDialog.open) return;
        const skillLibraryPath = document.querySelector("#skillLibraryPath");
        if (skillLibraryPath) skillLibraryPath.value = ui.skillLibrary.root || ui.skillLibrary.error || "Skill 库不可用";
        const openedTextProfile = activeGenerationProfile(generationWorkingSettings(), "text");
        if (["opencode", "deepseek_opencode"].includes(openedTextProfile?.agentEngine)) {
          void hydrateGenericOpenCodeCatalog().then(() => {
            if (elements.settingsDialog.open && ui.settingsSection === "model") {
              renderModelOptions(openedTextProfile.provider, { allowBlank: true });
            }
          });
        }
        if (elements.settingsDialog.open && ui.settingsSection === "model"
          && form.adapter.value === "api" && form.apiKey.value
          && !textModelCatalogIsCached(withReusableTextProviderCredential(activeGenerationProfile(generationWorkingSettings(), "text") || {}))) {
          void refreshAvailableModels();
        }
      })().catch((error) => console.warn("Settings background refresh failed:", error.message));
    }, { timeout: 2_400 });
  })().finally(() => {
    elements.settingsDialog.removeAttribute("aria-busy");
    elements.settingsDialog.inert = false;
    settingsOpenPromise = null;
  });
  return settingsOpenPromise;
};

