const discardSettingsChanges = ({ closeDialog = true } = {}) => {
  if (ui.directoryImport.loading) {
    showToast("目录正在导入，完成前不能关闭设置");
    return false;
  }
  // Native dialog close is the immediate acknowledgement. The queued `close`
  // event below performs draft/theme cleanup once, after the surface is gone.
  if (closeDialog && elements.settingsDialog.open) elements.settingsDialog.close();
  return true;
};

