document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    if (ui.noteToolbarExpanded) {
      ui.noteToolbarExpanded = false;
      elements.noteToolbarExpand.setAttribute("aria-expanded", "false");
      elements.noteToolbarMore.hidden = true;
      return;
    }
    if (elements.trashDeleteDialog.open) {
      ui.trashDeleteId = null;
      ui.trashDeleteAll = false;
      return;
    }
    if (elements.trashPreviewDialog.open) {
      closeTrashPreview();
      return;
    }
    if (elements.trashDialog.open) {
      closeTrashDialog();
      return;
    }
    if (elements.historyPreviewDialog.open) {
      closeHistoryPreview();
      return;
    }
    ui.panel = null;
    ui.historyScope = null;
    hideDirectoryMenus();
    hideDocumentMenu();
    clearGlobalSearch({ focus: false });
    hideDocumentMenu();
    elements.projectContextMenu.hidden = true;
    elements.skillContextMenu.hidden = true;
    elements.customThemeContextMenu.hidden = true;
    elements.capabilityNodeContextMenu.hidden = true;
    elements.settingsSectionContextMenu.hidden = true;
    elements.updateContextMenu.hidden = true;
    elements.whiteboardMenu.hidden = true;
    closeWhiteboardNodeCreateMenu();
    elements.mediaAssetMenu.hidden = true;
    closeTextEditContextMenu();
    renderAll();
    return;
  }
  if (!["ArrowDown", "ArrowUp"].includes(event.key)) return;
  const panel = event.target.closest(".utility-panel");
  if (!panel) return;
  const rows = Array.from(panel.querySelectorAll(".utility-row"));
  const index = rows.indexOf(event.target.closest(".utility-row"));
  if (index < 0) return;
  event.preventDefault();
  const next = event.key === "ArrowDown" ? (index + 1) % rows.length : (index - 1 + rows.length) % rows.length;
  rows[next]?.focus();
});

const DAILY_CAPABILITY_CHECK_KEY = "shensi.daily-capability-check.v1";
const DAILY_CAPABILITY_CHECK_INTERVAL_MS = 24 * 60 * 60 * 1000;
let externalWorkspaceRefreshTimer = 0;
let externalWorkspaceRefreshIdleTask = null;
let externalMarkdownActivationQueue = Promise.resolve();

const activateExternalMarkdownPayload = async (payload = {}) => {
  if (payload.ok === false || !payload.state) {
    showToast(`Markdown 打开失败：${payload.message || "文件不可读取"}`);
    return false;
  }
  try {
    const saveDisposition = await flushWorkspaceBeforeSwitch();
    if (saveDisposition?.preservedConflict) ui.workspaceStateCache.delete(workspaceIdentity());
    else rememberCurrentWorkspaceState();
    activateProjectState(payload.state, {
      name: payload.state.projectName || "临时笔记本",
      workspacePath: payload.workspaceRoot || "shensi://temporary-notebook",
      apiKey: state.settings.apiKey,
      workspaceKind: "notebook",
      stateStamp: payload.stateStamp || "",
    });
    ui.workspaceListCacheAt.notebook = 0;
    await refreshNotebooks({ force: true, render: false });
    renderProjectMenu();
    showToast(`已在临时笔记本中预览“${state.documents[payload.documentId]?.title || "Markdown"}”`);
    return true;
  } catch (error) {
    showToast(`Markdown 打开失败：${error.message}`);
    return false;
  }
};

const queueExternalMarkdownActivation = (payload) => {
  externalMarkdownActivationQueue = externalMarkdownActivationQueue
    .then(() => activateExternalMarkdownPayload(payload))
    .catch((error) => showToast(`Markdown 打开失败：${error.message}`));
  return externalMarkdownActivationQueue;
};

const cancelNativeBrowserQuestion = (sessionId) => {
  const id = String(sessionId || "").trim();
  if (!id) return false;
  let cancelled = false;
  for (const conversation of state.conversations || []) {
    const question = conversation.agentQuestion;
    if (question?.kind !== "native_agent" || String(question.metadata?.sessionId || "") !== id) continue;
    cancelled = true;
    void answerNativeConversationQuestion(question, "取消本次网页读取");
  }
  return cancelled;
};

const renderAgentBrowserConfirmation = () => {
  const element = elements.agentBrowserConfirmation;
  if (!element) return;
  const sessions = [...activeAgentBrowserSessions.values()]
    .filter((item) => item.status === "waiting_login")
    .sort((left, right) => Number(left.updatedAt || 0) - Number(right.updatedAt || 0));
  if (!sessions.length) {
    element.hidden = true;
    return;
  }
  const current = sessions.at(-1);
  const title = String(current.title || "网页资料").trim();
  let hostname = "";
  try { hostname = new URL(String(current.url || "")).hostname; } catch {}
  const count = sessions.length > 1 ? `当前有 ${sessions.length} 个网页读取任务等待确认。` : "";
  elements.agentBrowserConfirmationCopy.textContent = `请在临时浏览器窗口完成“${title}”${hostname ? `（${hostname}）` : ""}的必要登录或验证，再回到对话区选择继续；关闭窗口会取消本次读取。${count}`;
  element.hidden = false;
};

const applyAgentBrowserState = (payload = {}) => {
  const sessionId = String(payload.sessionId || "").trim();
  if (!sessionId) return;
  const status = String(payload.status || "");
  if (status === "waiting_login") {
    closedAgentBrowserSessions.delete(sessionId);
    activeAgentBrowserSessions.set(sessionId, { ...payload, status, updatedAt: Date.now() });
  } else if (status === "closed") {
    activeAgentBrowserSessions.delete(sessionId);
    if (payload.reason === "user_closed") {
      closedAgentBrowserSessions.add(sessionId);
      cancelNativeBrowserQuestion(sessionId);
      window.setTimeout(() => closedAgentBrowserSessions.delete(sessionId), 60_000);
    }
  }
  renderAgentBrowserConfirmation();
};

const connectDesktopExternalMarkdown = async () => {
  const bridge = window.shensiDesktop?.externalMarkdown;
  if (!bridge || typeof bridge.ready !== "function") return false;
  bridge.onOpened?.((payload) => { void queueExternalMarkdownActivation(payload); });
  try {
    const ready = await bridge.ready();
    for (const payload of ready?.opened || []) void queueExternalMarkdownActivation(payload);
    return true;
  } catch (error) {
    showToast(`Markdown 打开桥接失败：${error.message}`);
    return false;
  }
};

const connectDesktopAgentBrowser = () => {
  const bridge = window.shensiDesktop?.agentBrowser;
  if (!bridge || typeof bridge.onState !== "function") return false;
  bridge.onState(applyAgentBrowserState);
  void bridge.state?.().then((result) => {
    for (const payload of result?.sessions || []) applyAgentBrowserState(payload);
  }).catch(() => {});
  return true;
};

const scheduleExternalWorkspaceRefresh = () => {
  window.clearTimeout(externalWorkspaceRefreshTimer);
  cancelUiBackgroundTask(externalWorkspaceRefreshIdleTask);
  externalWorkspaceRefreshIdleTask = null;
  externalWorkspaceRefreshTimer = window.setTimeout(() => {
    externalWorkspaceRefreshTimer = 0;
    externalWorkspaceRefreshIdleTask = scheduleUiBackgroundTask(() => {
      externalWorkspaceRefreshIdleTask = null;
      if (document.visibilityState === "visible" && document.documentElement.dataset.bootReady === "true") {
        void refreshExternalWorkspaceDocuments({ silent: true });
      }
    }, { timeout: 2_000 });
  }, 350);
};

window.addEventListener("focus", scheduleExternalWorkspaceRefresh);
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") scheduleExternalWorkspaceRefresh();
});

const runDailyCapabilityConnectionChecks = async () => {
  let previous = {};
  try { previous = JSON.parse(localStorage.getItem(DAILY_CAPABILITY_CHECK_KEY) || "{}"); } catch {}
  const profiles = [
    ...(state.settings.textConnections ?? []).map((settings) => ({ channel: "text", settings })),
    // Audio is optional and hidden until its current-session driver probe
    // succeeds. Check it before potentially slow video-account validation so
    // an installed audio capability appears promptly after startup.
    ...(state.settings.audioConnections ?? []).map((settings) => ({ channel: "audio", settings: { ...settings, audioChannel: true } })),
    ...(state.settings.imageConnections ?? []).map((settings) => ({ channel: "image", settings: { ...settings, imageChannel: true } })),
    ...(state.settings.videoConnections ?? []).map((settings) => ({ channel: "video", settings: { ...settings, videoChannel: true } })),
  ];
  const profileStamp = profiles.map(({ channel, settings }) => channel === "text"
    ? textCapabilityProfileSignature(settings)
    : mediaCapabilityProfileSignature(channel, settings))
    .sort()
    .join("|");
  const sessionHydrated = capabilityProbeSessionIsHydrated(profiles, {
    textProbes: ui.textCapabilityProbes,
    mediaProbes: ui.mediaCapabilityProbes,
  });
  if (sessionHydrated && previous.profileStamp === profileStamp && Date.now() - Number(previous.checkedAt || 0) < DAILY_CAPABILITY_CHECK_INTERVAL_MS) return;
  const report = { checkedAt: Date.now(), profileStamp, verificationLevel: "connection", paidRequests: 0, items: [] };
  for (const entry of profiles) {
    const settings = entry.settings;
    if (settings.adapter === "api" && !settings.apiKey) {
      report.items.push({ channel: entry.channel, connectionId: settings.id, provider: settings.provider, model: settings.model, status: "skipped", reason: "missing_session_credentials" });
      continue;
    }
    if (settings.adapter === "cli" && entry.channel === "text") {
      report.items.push({ channel: entry.channel, connectionId: settings.id, provider: settings.provider, model: settings.model, status: "skipped", reason: "text_cli_requires_explicit_real_inference" });
      continue;
    }
    try {
      const useMediaProbe = usesRegisteredMediaDriver(entry.channel, settings);
      const endpoint = useMediaProbe
        ? "/api/media/capabilities/probe"
        : settings.adapter === "api" ? "/api/models/list" : "/api/adapters/test";
      const body = useMediaProbe
        ? { channel: entry.channel, settings }
        : settings.adapter === "cli"
          ? { ...settings, channel: entry.channel, [`${entry.channel}Channel`]: true, connectionProbeOnly: true }
          : { ...settings, channel: entry.channel, [`${entry.channel}Channel`]: true };
      const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const payload = await response.json();
      let models = probeModelIds(payload.models);
      if (entry.channel === "image" && settings.adapter === "api" && !useMediaProbe) models = models.filter(isImageGenerationModel);
      if (entry.channel === "audio" && settings.adapter === "api" && !useMediaProbe) models = models.filter((model) => model === settings.model || isAudioGenerationModel(model));
      const modelVisible = settings.adapter === "cli"
        ? payload.connected !== false
        : payload.visibilityChecked === false ? true : models.includes(settings.model);
      const driverRegistered = entry.channel !== "video" || payload.driverRegistered === true;
      const connected = response.ok && payload.ok !== false && (!useMediaProbe || payload.connected === true) && modelVisible && driverRegistered;
      report.items.push({ channel: entry.channel, connectionId: settings.id, provider: settings.provider, model: settings.model, status: connected ? "connection_passed" : "connection_failed", reason: connected ? "" : String(payload.message || payload.reason || (modelVisible ? "probe_failed" : "selected_model_not_visible")).slice(0, 240), models });
      if (connected && entry.channel === "text") {
        cacheTextModelsForProfile(settings, (payload.models ?? []).map((item) => typeof item === "string" ? { slug: item, label: item, displayName: item } : item).filter((item) => item?.slug));
        const existing = ui.textCapabilityProbes[settings.id] ?? {};
        const profileSignature = textCapabilityProfileSignature(settings);
        const sameProfile = existing.profileSignature === profileSignature;
        ui.textCapabilityProbes[settings.id] = {
          ...existing,
          connected: true,
          realInference: sameProfile && existing.realInference === true,
          capabilityState: sameProfile && existing.realInference === true ? "available" : "catalog_only",
          modelCatalogChecked: settings.adapter === "api" ? true : existing.modelCatalogChecked === true,
          models,
          profileSignature,
          checkedAt: new Date().toISOString(),
        };
      } else if (entry.channel !== "text") {
        storeMediaCapabilityProbe(entry.channel, settings, {
          ...payload,
          connected,
          available: connected,
          capabilityState: connected ? String(payload.capabilityState || "catalog_only") : String(payload.capabilityState || "unavailable"),
          softwareIntegrated: payload.softwareIntegrated !== false,
          statusDetail: String(payload.message || (connected ? "能力目录已确认，未执行收费生成" : "连接检查未通过")).slice(0, 500),
          driverRegistered: entry.channel === "video" ? payload.driverRegistered === true : payload.driverRegistered,
          models,
          visibilityChecked: useMediaProbe
            ? payload.visibilityChecked !== false
            : settings.adapter === "api" ? payload.visibilityChecked !== false : false,
          checkedAt: new Date().toISOString(),
        });
      }
    } catch (error) {
      report.items.push({ channel: entry.channel, connectionId: settings.id, provider: settings.provider, model: settings.model, status: "connection_failed", reason: String(error.message || error).slice(0, 240) });
      storeCustomCapabilityFailure(entry.channel, settings, error);
    }
  }
  persistCapabilityProbes();
  localStorage.setItem(DAILY_CAPABILITY_CHECK_KEY, JSON.stringify(report));
  renderQuickModelSelector();
  renderWhiteboardGenerateControls();
};

const CREATIVE_START_WELCOME_KEY = "shensi:creative-start-welcome:v1";

const markCreativeStartWelcomeSeen = () => localStorage.setItem(CREATIVE_START_WELCOME_KEY, "seen");

const openWorkspaceCreativeGuidance = async () => {
  if (workspaceHasNoActiveEntry() || state.workspaceKind !== "project") {
    const activated = await activateWorkspaceKind("project");
    if (!activated || workspaceHasNoActiveEntry() || state.workspaceKind !== "project") {
      openWorkspaceCreateDialog("project");
      showToast("请先创建或选择一个作品，随后即可进入创作引导");
      return false;
    }
  }
  ensureWorkspaceCreativeGuidanceSession();
  elements.chatInput.focus({ preventScroll: true });
  return true;
};

elements.dismissCreativeStartWelcome?.addEventListener("click", () => {
  markCreativeStartWelcomeSeen();
  elements.creativeStartWelcomeDialog.close();
});
elements.startCreativeJourney?.addEventListener("click", async () => {
  elements.startCreativeJourney.disabled = true;
  try {
    markCreativeStartWelcomeSeen();
    elements.creativeStartWelcomeDialog.close();
    await openWorkspaceCreativeGuidance();
  } finally {
    elements.startCreativeJourney.disabled = false;
  }
});
elements.creativeStartWelcomeDialog?.addEventListener("cancel", markCreativeStartWelcomeSeen);

const showCreativeStartWelcomeOnce = () => {
  if (localStorage.getItem(CREATIVE_START_WELCOME_KEY) || elements.creativeStartWelcomeDialog?.open) return false;
  elements.creativeStartWelcomeDialog?.showModal();
  return true;
};

const bootstrap = async () => {
  await hydrateRecoveryResumePointer();
  await hydrateDesktopGenerationSecrets();
  await hydrateGenerationRuntimeBindings();
  state.settings = applyGenerationRuntimeBindings(state.settings ?? {}, machineGenerationRuntime, runtimeGenerationSecrets);
  const emptyWorkspaceAtStartup = storedActiveWorkspace()?.empty === true;
  const hydration = await hydrateWorkspace();
  ui.workspaceHydrating = false;
  ui.workspaceMenuKind = state.workspaceKind === "notebook" ? "notebook" : "project";
  const localCodexEnabled = await hydrateLocalCapabilities();
  if (hydration?.status === "failed") {
    ui.workspaceListError = `工作区安全加载失败：${hydration.error?.message || "未知错误"}。磁盘数据未修改，请重试刷新。`;
    renderAll();
    showToast(ui.workspaceListError);
    document.documentElement.dataset.bootReady = "true";
    return;
  }
  ensureStateSchema();
  // Rebind DPAPI-backed API credentials before recovery workers need to
  // resume an older media job. The secrets never enter workspace state.
  try {
    const hasRuntimeCredentials = Object.values(generationSecrets(state.settings ?? {}))
      .some((records) => Object.keys(records || {}).length > 0);
    if (hasRuntimeCredentials) await saveGenerationRuntimeForSettings(state.settings, { confirmed: true });
  } catch (error) {
    console.warn("Generation runtime credential rebind failed:", error.message);
  }
  updateTrashIndexDocument();
  restoreActiveWorkspaceView();
  seedSnapshotPayloads();
  // Render the hydrated workspace and start deterministic task recovery before
  // waiting for the slower project/notebook directory refresh. This keeps a
  // refresh from hiding an already-saved candidate behind unrelated startup IO.
  renderAll();
  // The hydrated workspace is now safe to use. Account discovery, provider
  // reconciliation, workspace enumeration and update checks may legitimately
  // take longer (or wait on an external process), but they must never keep the
  // recovery curtain over an already-rendered document.
  document.documentElement.dataset.bootReady = "true";
  if (generationSecretHydrationError) {
    showToast("模型凭证未能安全读取；文档已正常打开，请到模型设置核验受影响的账号");
  }
  // The first status request is started before workspace hydration, when saved
  // conversation cards do not exist yet. Reconcile again after hydration so a
  // refreshed page can reattach live starts/runs or terminate old orphan cards.
  await refreshCodexAgentStatus({ refreshAccount: currentCodexConnectionSelected() });
  renderMessages();
  for (const conversation of state.conversations ?? []) {
    if (conversationTaskIsRunning(conversationMessagesForTaskState(conversation))) {
      const runningTasks = conversationMessagesForTaskState(conversation)
        .filter((message) => conversationTaskMessageIsRunning(message))
        .map((message) => ({
          conversationId: conversation.id,
          messageId: message.id,
          sourceMessageId: message.execution?.sourceMessageId || "",
          requestId: message.execution?.requestId || "",
          agentTurnId: message.execution?.agentTurnId || "",
          queueItemId: message.execution?.queueItemId || "",
          leaseId: message.execution?.queueLeaseId || "",
        }));
      // A running task owns only the queue item whose task identifiers and,
      // when available, lease both match. Every other stale dispatch is
      // requeued; startup never bulk-acks a conversation's dispatches.
      recoverConversationTaskQueueForStartup(conversation, { runningTasks });
    } else {
      recoverConversationTaskQueue(conversation, { leaseTimeoutMs: 1 });
    }
    if ((conversation.queue ?? []).some((item) => item.state !== "dispatching")) scheduleConversationQueueDrain(conversation.id);
  }
  persist();
  if (allConversationMessages().some(({ message }) => message.pending && message.execution?.strength === "agent")) {
    void pollCodexAgentEvents();
  }
  void reconcileInterruptedTextGenerationAttempts();
  void discoverUnfinishedGenerationAttempts();
  const workspaceListReady = await refreshWorkspaceEntries();
  if (workspaceListReady && (emptyWorkspaceAtStartup || !workspaceKindHasEntry({
    workspaceKind: ui.workspaceMenuKind,
    workspacePath: state.settings.workspacePath,
    projects: ui.projects,
    notebooks: ui.notebooks,
  }))) {
    enterEmptyWorkspaceMode(ui.workspaceMenuKind, { render: false });
    await activateWorkspaceKind(ui.workspaceMenuKind);
  }
  // Workspace enumeration can replace the initial hydrated view with the
  // empty-workspace surface. Open the first-run guide only after that final
  // switch so a late directory refresh cannot silently dismiss it.
  requestAnimationFrame(showCreativeStartWelcomeOnce);
  // Generation drafts are UI state, not provider jobs. Restore the one active
  // draft only after the final startup workspace and its whiteboard DOM exist;
  // job reconciliation below cannot recreate an unsubmitted draft by itself.
  restoreActiveWhiteboardGenerationDialog();
  connectDesktopAgentBrowser();
  await connectDesktopExternalMarkdown();
  mediaRecoveryReconciler.start();
  requestAnimationFrame(() => recoverWhiteboardGenerationJobs());
  scheduleUiBackgroundTask(() => { void runDailyCapabilityConnectionChecks(); }, { delay: 250, timeout: 4_000 });
  if (ui.workspaceRecoveryRestored) {
    try {
      await flushWorkspaceSave({ throwOnError: true });
      showToast("已从断电恢复检查点找回未完成保存的内容");
    } catch (error) {
      showToast(`恢复内容已保留，但重新落盘失败：${error.message}`);
    }
  }
  await checkForUpdates({ silent: true });
  ui.updateTimer ??= window.setInterval(() => checkForUpdates({ silent: true }), UPDATE_CHECK_INTERVAL_MS);
  warmWorkspaceSwitching();
  if (ui.structureMigrationPending) {
    persist();
    ui.structureMigrationPending = false;
  } else if (localCodexEnabled) {
    persistRuntimeCache();
    ui.workspaceDirty = false;
    setAutoSaveState("saved");
  }
  if (localCodexEnabled) {
    showToast(`${ui.localCodex.version} 已检测并载入配置`);
  }
  document.documentElement.dataset.bootReady = "true";
};

bootstrap();
